from PyQt6.QtCore import QObject as _SeedQObject, QRunnable as _SeedQRunnable, pyqtSignal as _seed_pyqtSignal


class _SeedDiagBridge(_SeedQObject):
    """GROOVEBOX_R32_SEED_OFFTHREAD_20261109: carries a finished seed diagnostic from a
    worker thread back to the GUI thread (queued signal), so typing never blocks on parsing."""
    done = _seed_pyqtSignal(int, object)


class _SeedDiagRunnable(_SeedQRunnable):
    def __init__(self, fn, raw, generation, bridge):
        super().__init__()
        self.setAutoDelete(True)
        self._fn, self._raw, self._gen, self._bridge = fn, raw, generation, bridge

    def run(self):
        try:
            d = self._fn(self._raw)
        except Exception as exc:
            d = ("SEED SCRIPT ERROR · diagnostic failure: %s" % exc, 1, 0, 1, "error")
        try:
            self._bridge.done.emit(self._gen, d)
        except RuntimeError:
            pass


class SeedScriptSyntaxHighlighter(QSyntaxHighlighter):
    """Low-overhead syntax shading for the global Seed Script editor.

    This is intentionally visual only: it never evaluates the script and therefore
    cannot perturb deterministic seed/composition state while the user is typing.
    Tokens that look like the supported seed/Python-style language are rendered in
    a neutral light-to-dark grey hierarchy; bracket depth is shaded independently.
    """

    _KEYWORDS = {
        "if", "elif", "else", "while", "for", "in", "def", "return", "lambda",
        "and", "or", "not", "is", "break", "continue", "pass", "True", "False", "None",
        "let", "var", "const", "true", "false", "null",
    }
    _BUILTINS = {
        "abs", "min", "max", "sum", "round", "int", "float", "len", "range",
        "sin", "cos", "tan", "asin", "acos", "atan", "atan2", "sqrt", "log", "log2", "log10",
        "exp", "floor", "ceil", "pow", "mod", "clamp", "sign", "lerp", "mix", "wrap", "frac",
        "smoothstep", "saturate", "heaviside", "ln", "isfinite", "isnan", "isinf", "math", "inf",
        "choose", "hypot", "tanh", "sinh", "cosh", "fabs", "degrees", "radians", "any", "all",
        "map", "filter", "dict", "set", "enumerate", "zip", "sorted", "reversed", "tuple", "list", "bool",
        "polar", "cartesian", "cylindrical", "spherical", "parametric", "isn", "ics", "isx", "isy",
        "arcisn", "arcics", "isn_inv", "ics_inv", "P", "D", "tensor_z", "tensor_rel",
        "ot_add", "ot_sub", "ot_prod", "ot_div", "ot_pow", "ot_band", "ot_equiv_sin", "ot_equiv_cos",
        "math_add", "math_sub", "math_mul", "math_div", "math_pow", "no_sat",
        "MEUM", "M", "PHI", "PI", "E", "SQRT2", "SQRT3", "SILVER", "MEUM_INV", "MEUM_NORM", "tau", "pi", "e",
        "t_norm", "seed", "seed_w", "graph", "graph_x", "graph_y", "graph_z",
        "graph_scalar", "graph_radius", "graph_angle", "graph_energy", "graph_curvature",
        "graph_phase", "graph_u", "graph_v", "graph_w", "graph_index", "graph_count",
        "graph_slot", "sequence_index", "step_index", "domain_value", "domain_weight",
        "graph_id", "domain_id", "graph_vector", "bpm", "sample_rate",
    }
    _TOKEN_RE = re.compile(
        r"(?P<comment>\#.*$)|"
        r"(?P<string>'(?:\\.|[^'\\])*'|\"(?:\\.|[^\"\\])*\")|"
        r"(?P<number>(?<![\w.])(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)|"
        r"(?P<identifier>\b[A-Za-z_]\w*\b)|"
        r"(?P<operator>==|!=|<=|>=|\*\*|//|:=|->|[+\-*/%^=<>?:,.])"
    )

    def __init__(self, document):
        super().__init__(document)
        self._fmt_keyword = self._format("#ededed", bold=True)
        self._fmt_builtin = self._format("#d8d8d8")
        self._fmt_identifier = self._format("#c4c4c4")
        self._fmt_number = self._format("#adadad")
        self._fmt_operator = self._format("#929292")
        self._fmt_string = self._format("#b7b7b7")
        self._fmt_comment = self._format("#777777", italic=True)
        # Repeats gracefully for deeply nested parametric expressions.
        self._bracket_formats = [
            self._format("#f0f0f0", bold=True),
            self._format("#d6d6d6", bold=True),
            self._format("#bcbcbc", bold=True),
            self._format("#a2a2a2", bold=True),
            self._format("#888888", bold=True),
            self._format("#707070", bold=True),
        ]
        self._fmt_unmatched = self._format("#5f5f5f", bold=True, underline=True)

    @staticmethod
    def _format(color, bold=False, italic=False, underline=False):
        fmt = QTextCharFormat()
        fmt.setForeground(QColor(color))
        if bold:
            fmt.setFontWeight(QFont.Weight.Bold)
        if italic:
            fmt.setFontItalic(True)
        if underline:
            fmt.setFontUnderline(True)
        return fmt

    def highlightBlock(self, text):
        # Lexical shading first. This does not call the Seed evaluator/parser.
        for match in self._TOKEN_RE.finditer(text):
            kind = match.lastgroup
            token = match.group(0)
            if kind == "identifier":
                if token in self._KEYWORDS:
                    fmt = self._fmt_keyword
                elif token in self._BUILTINS:
                    fmt = self._fmt_builtin
                else:
                    fmt = self._fmt_identifier
            elif kind == "number":
                fmt = self._fmt_number
            elif kind == "operator":
                fmt = self._fmt_operator
            elif kind == "string":
                fmt = self._fmt_string
            else:
                fmt = self._fmt_comment
            self.setFormat(match.start(), match.end() - match.start(), fmt)
            if kind == "comment":
                break

        # Preserve bracket nesting between lines in the QTextDocument block state.
        previous_depth = self.previousBlockState()
        depth = 0 if previous_depth < 0 else previous_depth
        stack = []
        pairs = {")": "(", "]": "[", "}": "{"}
        opens = "([{"
        closes = ")] }".replace(" ", "")

        # Ignore brackets that occur inside already-recognized comments/strings.
        protected = [False] * len(text)
        for match in self._TOKEN_RE.finditer(text):
            if match.lastgroup in ("comment", "string"):
                for i in range(match.start(), match.end()):
                    if i < len(protected):
                        protected[i] = True
                if match.lastgroup == "comment":
                    break

        for i, ch in enumerate(text):
            if protected[i]:
                continue
            if ch in opens:
                fmt = self._bracket_formats[depth % len(self._bracket_formats)]
                self.setFormat(i, 1, fmt)
                stack.append((ch, i, depth))
                depth += 1
            elif ch in closes:
                closing_depth = max(0, depth - 1)
                fmt = self._bracket_formats[closing_depth % len(self._bracket_formats)]
                if stack and stack[-1][0] == pairs[ch]:
                    stack.pop()
                    depth = closing_depth
                    self.setFormat(i, 1, fmt)
                elif depth > 0:
                    # Cross-line nesting can legitimately close a bracket opened in
                    # an earlier block; shade by inherited depth rather than flagging.
                    depth = closing_depth
                    self.setFormat(i, 1, fmt)
                else:
                    self.setFormat(i, 1, self._fmt_unmatched)

        self.setCurrentBlockState(max(0, depth))


def _ot_role_from_value(value, fallback=OTRole.RESULT):
    """Resolve an explicit OT role property/string without changing engine state."""
    if isinstance(value, OTRole):
        return value
    if value is None:
        return fallback
    key = str(value).strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "variable": OTRole.INDEPENDENT_VARIABLE,
        "independent_variable": OTRole.INDEPENDENT_VARIABLE,
        "input": OTRole.INDEPENDENT_VARIABLE,
        "constant": OTRole.INDEPENDENT_CONSTANT,
        "independent_constant": OTRole.INDEPENDENT_CONSTANT,
        "result": OTRole.RESULT,
        "readout": OTRole.RESULT,
        "output": OTRole.RESULT,
        "dependent_constant": OTRole.DEPENDENT_CONSTANT,
        "derived_constant": OTRole.DEPENDENT_CONSTANT,
        "dependent_variable": OTRole.DEPENDENT_VARIABLE,
        "derived_variable": OTRole.DEPENDENT_VARIABLE,
    }
    return aliases.get(key, fallback)


def _infer_ot_numeric_role(widget, text=""):
    """Infer the author's role color for a UI number.

    Any widget can override this exactly with:
        widget.setProperty("ot_role", "independent_variable")
    """
    try:
        explicit = widget.property("ot_role")
    except Exception:
        explicit = None
    if explicit not in (None, ""):
        return _ot_role_from_value(explicit, OTRole.RESULT)

    try:
        name = str(widget.objectName() or "")
    except Exception:
        name = ""

    sample = (name + " " + str(text or "")).lower()

    # Canonical/reference irrational values are independent constants -> green.
    constant_terms = (
        "meum", "phi", "golden", "pi ", "π", "sqrt", "silver",
        "constant", "reference value", "irrational",
    )
    if any(term in sample for term in constant_terms):
        return OTRole.INDEPENDENT_CONSTANT

    # Explicitly derived/locked constants -> black.
    if any(term in sample for term in (
        "dependent constant", "derived constant", "fixed constant",
        "locked constant", "hard limit",
    )):
        return OTRole.DEPENDENT_CONSTANT

    # Derived/modulated values -> white.
    if any(term in sample for term in (
        "dependent variable", "derived variable", "modulated",
        "automation value", "phase result variable",
    )):
        return OTRole.DEPENDENT_VARIABLE

    # Editable numeric controls are inputs/independent variables -> red.
    if isinstance(widget, (QSpinBox, QDoubleSpinBox, QSlider, QDial, QLineEdit)):
        try:
            if hasattr(widget, "isReadOnly") and widget.isReadOnly():
                return OTRole.RESULT
        except Exception:
            pass
        return OTRole.INDEPENDENT_VARIABLE

    # Named controls that represent editable/live parameters -> red.
    variable_terms = (
        "seed", "offset", "pitch", "tune", "speed", "volume", "gain",
        "tempo", "bpm", "length", "step", "amount", "weight", "resonance",
        "blend", "opacity", "rate", "decay", "frequency", "freq", "pan",
        "velocity", "coverage", "direction", "threshold", "width", "height",
    )
    if any(term in sample for term in variable_terms):
        return OTRole.INDEPENDENT_VARIABLE

    # Readouts/results are blue by default.
    return OTRole.RESULT


def _ot_role_color(role):
    return OT_ROLE_COLORS.get(role, OT_ROLE_COLORS.get(OTRole.RESULT, "#2f80ff"))

def _ot_numeric_tokens_exact(text):
    """Tokenize a displayed number without rounding or dropping trailing zeroes.

    Returns (negative, tokens), where tokens contains one entry for every
    displayed decimal digit and literal decimal dots.  Signs and dots do not
    consume the digit-count index.
    """
    raw = str(text or "").strip()
    negative = raw.startswith("-")
    if raw[:1] in ("-", "+"):
        raw = raw[1:]
    tokens = [ch for ch in raw if ch.isdigit() or ch == "."]
    if not any(ch.isdigit() for ch in tokens):
        tokens = ["0"]
    return negative, tokens


def _ot_glyph_for_display_digit(digit_char, digit_index, negative, role,
                                operation=OTOperation.NONE, continued=False,
                                multiplicity=1, variable_letter=""):
    """Encode exactly one displayed decimal digit at its true count position.

    The alternating direction/orientation therefore follows the full displayed
    number rather than restarting at zero for every glyph.
    """
    signed_probe = -1.0 if negative else 1.0
    direction = ot_direction_for(signed_probe, int(digit_index))
    return ot_encode_nibble(
        int(digit_char),
        direction=direction,
        operation=operation,
        continued=continued,
        multiplicity=multiplicity,
        role=role,
        variable_letter=(variable_letter if int(digit_index) == 0 else ""),
    )




_QUARTER_CELL_PX = 10.5      # 1/4 of preferred 42px symbol cell
_INWARD_STEP_PX = 2.625      # 1/16 of preferred cell; scales with fitted cells
_MAX_INWARD_CYCLES = 4


def _quarter_cycle_state(index, negative=False, cell=42.0):
    """Return (dx, dy, inward, phase) for one visible number position.

    The symbol itself is unchanged. Only its placement advances one quarter-cell
    at a time around the cell. After four positions the next cycle moves inward.

    Positive: clockwise.
    Negative: counter-clockwise.
    """
    i = max(0, int(index))
    phase = i & 3
    cycle = min(i // 4, _MAX_INWARD_CYCLES)

    # quarter-cell positions around the center. Scale with the actual fitted
    # cell so narrow spin boxes do not push the glyph outside their editor.
    q = max(2.0, float(cell) * 0.25)
    inward_step = max(0.5, float(cell) / 16.0)
    cw = (
        (0.0, -q),   # top
        (q, 0.0),    # right
        (0.0, q),    # bottom
        (-q, 0.0),   # left
    )
    ccw = (
        (0.0, -q),   # top
        (-q, 0.0),   # left
        (0.0, q),    # bottom
        (q, 0.0),    # right
    )
    dx, dy = (ccw if negative else cw)[phase]

    # Move subsequent completed cycles inward toward the cell center.
    inward = cycle * inward_step
    if dx > 0:
        dx -= inward
    elif dx < 0:
        dx += inward
    if dy > 0:
        dy -= inward
    elif dy < 0:
        dy += inward

    return dx, dy, inward, phase


def _decimal_boundary_index(text):
    """Return number of digits before decimal; decimal itself consumes no cell."""
    raw = str(text or "")
    if "." not in raw:
        return None
    left = raw.split(".", 1)[0]
    return sum(ch.isdigit() for ch in left)



class OTNumberGlyphWidget(QWidget):
    """Compact painter for the author's 12-line / four-separator number symbols.

    This is a presentation layer only.  OT arithmetic remains controlled by the
    existing Operator Theory toggle; Math Symbols can be turned off to expose the
    ordinary base-10 value without changing the engine state.
    """
    def __init__(self, value=0, role=OTRole.RESULT, parent=None):
        super().__init__(parent)
        self._value = value
        self._role = role
        self._symbols = True
        self._operation = OTOperation.NONE
        self._continued = False
        self._multiplicity = 1
        self._variable_letter = ""
        # READABILITY_20260911: larger minimum cell so the 12-stroke + 4-separator
        # author glyphs remain legible on laptop and HDMI displays.
        self.setMinimumSize(148, 42)
        self.setMaximumHeight(52)
        self.setToolTip(
            "OT symbol readout: 12 directional strokes (4×3), four separator bits, "
            "four-way up/right/down/left orientation. Tiny base-10 cue in each cell "
            "aids learning. Math Symbols OFF shows ordinary base-10."
        )

    def setValue(self, value):
        self._value = value
        self.update()

    def setSymbolsEnabled(self, enabled):
        self._symbols = bool(enabled)
        self.update()

    def setRole(self, role):
        self._role = role
        self.update()

    def setNotation(self, operation=None, continued=None, multiplicity=None, variable_letter=None):
        if operation is not None: self._operation = operation
        if continued is not None: self._continued = bool(continued)
        if multiplicity is not None: self._multiplicity = max(1, int(multiplicity))
        if variable_letter is not None: self._variable_letter = str(variable_letter)[:1]
        self.update()

    def _pen(self, color, width=2.25, dotted=False):
        pen = QPen(QColor(color), width)
        if dotted:
            pen.setStyle(Qt.PenStyle.DotLine)
        return pen

    def _draw_stroke(self, painter, cx, cy, dx, dy, squiggly, color):
        if not squiggly:
            painter.setPen(self._pen(color, 2.55))
            painter.drawLine(QPointF(cx, cy), QPointF(cx+dx, cy+dy))
            return
        path = QPainterPath(QPointF(cx, cy))
        px, py = -dy, dx
        L = max((dx*dx+dy*dy)**0.5, 1.0)
        px, py = px/L*1.7, py/L*1.7
        path.cubicTo(QPointF(cx+dx*.30+px, cy+dy*.30+py),
                     QPointF(cx+dx*.70-px, cy+dy*.70-py),
                     QPointF(cx+dx, cy+dy))
        painter.setPen(self._pen(color, 2.45))
        painter.drawPath(path)

    def _draw_halfspace_squiggle(self, painter, x, y, size, color, phase):
        """Accent only: do not replace or reinterpret the original symbol."""
        # phase 1 is the second quarter (0.5-space point)
        if phase != 1:
            return

        painter.save()
        painter.setPen(QPen(QColor(color), 1.55))
        path = QPainterPath()

        # small wave tucked into the active side of the 32px cell
        cy = y + size * 0.50
        x0 = x + size * 0.30
        x1 = x + size * 0.70
        amp = size * 0.055

        path.moveTo(x0, cy)
        path.cubicTo(
            x0 + (x1-x0) * 0.25, cy - amp,
            x0 + (x1-x0) * 0.50, cy + amp,
            x0 + (x1-x0) * 0.75, cy - amp,
        )
        path.cubicTo(
            x0 + (x1-x0) * 0.86, cy + amp,
            x0 + (x1-x0) * 0.94, cy - amp,
            x1, cy,
        )
        painter.drawPath(path)
        painter.restore()

    def _draw_radix_squiggle(self, painter, x, y, size, color):
        """Compact decimal/radix marker; no decimal-dot width is consumed."""
        painter.save()
        painter.setPen(QPen(QColor(color), 1.35))
        path = QPainterPath()
        x0 = x + size * 0.20
        x1 = x + size * 0.80
        cy = y + size * 0.82
        amp = size * 0.04
        path.moveTo(x0, cy)
        path.cubicTo(
            x0 + (x1-x0) * 0.25, cy - amp,
            x0 + (x1-x0) * 0.50, cy + amp,
            x0 + (x1-x0) * 0.75, cy - amp,
        )
        path.cubicTo(
            x0 + (x1-x0) * 0.85, cy + amp,
            x0 + (x1-x0) * 0.95, cy - amp,
            x1, cy,
        )
        painter.drawPath(path)
        painter.restore()

    def _draw_glyph(self, painter, glyph, x, y, size):
        """Draw one author base-16 cell in the user's four-quadrant format.

        The four quadrants are the nibble bits (UL, UR, LL, LR).  An active
        quadrant carries its three contextual strokes.  The dashed cross and
        center circle are structural landmarks, so every glyph remains easy to
        compare at a glance even when some quadrants are absent.

        READABILITY_20260911:
          - guaranteed cell fill for near-black / near-white roles
          - slightly heavier strokes at small sizes
          - clearer empty-zero (distinct corner marks, no interior clutter)
          - tiny base-10 digit cue in the lower-right of each cell so the
            mapping is learnable without leaving symbol mode
        """
        color = OT_ROLE_COLORS.get(glyph.role, '#5ac8fa')
        role = glyph.role
        # Ensure high-contrast cell backgrounds for roles that would otherwise
        # disappear on typical dark or light host themes.
        if role == OTRole.DEPENDENT_CONSTANT or color in ('#000000', '#1c1c1e'):
            painter.fillRect(QRectF(x, y, size, size), QColor('#d0d0d4'))
        elif role == OTRole.DEPENDENT_VARIABLE or color in ('#ffffff', '#f2f2f7'):
            painter.fillRect(QRectF(x, y, size, size), QColor('#2c2c2e'))
        # Permanent outer author box.  Zero is intentionally sparse but no longer
        # completely invisible: a light outer box + two corner ticks remain.
        stroke_w = 2.85 if size >= 28 else 2.35
        painter.setPen(self._pen(color, stroke_w))
        painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.drawRect(QRectF(x+1.5, y+1.5, size-3.0, size-3.0))
        cx, cy = x + size/2.0, y + size/2.0
        empty_zero = int(getattr(glyph, 'value', 0)) == 0
        if empty_zero:
            # Distinct zero: two short corner ticks so the cell is not mistaken
            # for a missing/blank slot while still reading as "empty count".
            tick = size * 0.12
            painter.setPen(self._pen(color, 1.6))
            painter.drawLine(QPointF(x+3, y+3), QPointF(x+3+tick, y+3))
            painter.drawLine(QPointF(x+3, y+3), QPointF(x+3, y+3+tick))
            painter.drawLine(QPointF(x+size-3, y+size-3), QPointF(x+size-3-tick, y+size-3))
            painter.drawLine(QPointF(x+size-3, y+size-3), QPointF(x+size-3, y+size-3-tick))
        else:
            # Dashed quadrant separators and center ring (literal sketch format).
            painter.setPen(self._pen(color, 1.25, dotted=True))
            painter.drawLine(QPointF(cx, y+3), QPointF(cx, y+size-3))
            painter.drawLine(QPointF(x+3, cy), QPointF(x+size-3, cy))
            painter.setPen(self._pen(color, 1.9))
            r = size * 0.065
            painter.drawEllipse(QRectF(cx-r, cy-r, r*2, r*2))

        # Quadrant stroke groups: UL, UR, LL are vertical; LR is horizontal,
        # matching the supplied handwritten reference.  Each nibble bit turns
        # one whole 3-stroke group on/off; squiggle_mask modifies individual
        # strokes without changing the encoded value.
        groups = [
            [(0.28,0.27,0.28,0.42),(0.37,0.27,0.37,0.42),(0.46,0.27,0.46,0.42)],
            [(0.61,0.27,0.61,0.42),(0.70,0.27,0.70,0.42),(0.79,0.27,0.79,0.42)],
            [(0.28,0.60,0.28,0.79),(0.37,0.60,0.37,0.79),(0.46,0.60,0.46,0.79)],
            [(0.61,0.62,0.79,0.62),(0.61,0.70,0.79,0.70),(0.61,0.78,0.79,0.78)],
        ]
        mask = glyph.separator_mask
        if not empty_zero:
            for q, strokes in enumerate(groups):
                if not (mask & (1 << q)):
                    continue
                for j,(ax,ay,bx,by) in enumerate(strokes):
                    i=q*3+j
                    if not (glyph.presence_mask & (1<<i)):
                        continue
                    x1,y1=x+size*ax,y+size*ay; x2,y2=x+size*bx,y+size*by
                    self._draw_stroke(painter, x1, y1, x2-x1, y2-y1,
                                      bool(glyph.squiggly_mask & (1<<i)), color)

        # Tiny base-10 learning cue (does not alter encoded value or arithmetic).
        # Only shown when the cell is large enough to remain uncluttered.
        if size >= 26:
            dig = int(getattr(glyph, 'value', 0)) % 10
            painter.save()
            cue = QColor(color)
            cue.setAlpha(160)
            painter.setPen(QPen(cue, 1.0))
            painter.setFont(QFont('Sans Serif', max(7, int(size * 0.18)), QFont.Weight.Bold))
            painter.drawText(
                QRectF(x + size * 0.62, y + size * 0.72, size * 0.34, size * 0.24),
                Qt.AlignmentFlag.AlignCenter,
                str(dig),
            )
            painter.restore()

        # Operation metadata stays outside the value-carrying four quadrants.
        if glyph.operation == OTOperation.MUL:
            painter.setPen(self._pen(color, 1.4))
            painter.drawLine(QPointF(x,y), QPointF(x+size*.72,y))
            painter.drawLine(QPointF(x,y), QPointF(x,y+size))
            painter.drawLine(QPointF(x,y+size), QPointF(x+size*.72,y+size))
        elif glyph.operation in (OTOperation.ADD, OTOperation.SUB):
            painter.setPen(self._pen(color, 1.3, dotted=True))
            painter.drawRect(QRectF(x-1,y-1,size+2,size+2))
        elif glyph.operation == OTOperation.DIV:
            painter.setPen(self._pen(color, 1.6))
            painter.drawRect(QRectF(x-1,y-1,size+2,size+2))
        if glyph.continued:
            painter.setPen(self._pen(color, 1.0, dotted=True))
            painter.drawRect(QRectF(x-3,y-3,size+6,size+6))
        if glyph.variable_letter:
            painter.setPen(self._pen(color, 1.1))
            painter.setFont(QFont('Sans Serif', max(6, int(size*.15)), QFont.Weight.Bold))
            painter.drawText(QRectF(x+2,y+2,size*.22,size*.20), Qt.AlignmentFlag.AlignCenter, glyph.variable_letter)
        if glyph.multiplicity > 1:
            painter.setPen(self._pen(color, 1.2))
            painter.drawRect(QRectF(x+size*.82,y+size*.05,size*.12,size*.12))

    def paintEvent(self, event):
        with owned_painter(self) as painter:
            if painter is None:
                return
            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            if not self._symbols:
                painter.setPen(QColor('#e8eef8'))
                painter.setFont(QFont('Monospace', 10, QFont.Weight.Bold))
                painter.drawText(self.rect(), Qt.AlignmentFlag.AlignCenter, str(self._value))
                return
            glyphs = ot_encode_decimal(self._value, role=self._role, operation=self._operation,
                                       continued=self._continued, multiplicity=self._multiplicity,
                                       variable_letter=self._variable_letter)
            count = max(1, len(glyphs))
            # READABILITY_20260911: prefer larger cells (min 26, max 48) so strokes
            # and the tiny base-10 cue stay legible on laptop / HDMI output.
            cell = min(48.0, max(26.0, (self.width()-4.0)/count))
            total = cell*count
            x = max(2.0, (self.width()-total)/2.0)
            y = max(1.0, (self.height()-cell)/2.0)
            for g in glyphs:
                self._draw_glyph(painter, g, x, y, cell)
                x += cell


class _OTNumericOverlay(OTNumberGlyphWidget):
    """Author-symbol display for QSpinBox/QDoubleSpinBox.

    Ordinary decimal text is suppressed at the QLineEdit paint-event level while
    symbol mode is active.  The glyph overlay is parented to the spinbox itself,
    so suppressing the editor's paint can never suppress the glyphs too.
    """
    def __init__(self, owner):
        self.owner = owner
        self._editor = None
        self._syncing = False
        self._last_render_key = None
        self._suppress_editor_paint = False

        # Parent to the spinbox, NOT the line editor.  This is important because
        # the line editor's paint event is intentionally consumed in symbol mode.
        super().__init__(
            0,
            role=_infer_ot_numeric_role(owner, ""),
            parent=owner,
        )

        self.setMinimumSize(0, 0)
        self.setMaximumSize(16777215, 16777215)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground, False)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setAutoFillBackground(False)
        self.setStyleSheet("background: transparent; border: none;")

        self._attach_editor()

        try:
            owner.installEventFilter(self)
            owner.valueChanged.connect(self._value_changed)
        except Exception:
            pass

        self._sync(force=True)

    def _attach_editor(self):
        try:
            le = self.owner.lineEdit()
        except Exception:
            le = None

        if le is self._editor:
            return le

        if self._editor is not None:
            try:
                self._editor.removeEventFilter(self)
            except Exception:
                pass

        self._editor = le
        if le is not None:
            try:
                le.installEventFilter(self)
            except Exception:
                pass
        return le

    def _value_changed(self, *_):
        self._sync(force=False)

    def _line_edit(self):
        return self._attach_editor()

    def _is_editing(self):
        try:
            le = self._line_edit()
            return bool(
                (le is not None and le.hasFocus())
                or self.owner.hasFocus()
            )
        except Exception:
            return False

    def _set_owner_number_text_visible(self, visible):
        # Do not mutate palettes or styles.  Those caused recursion and were also
        # not guaranteed to override parent Qt stylesheets.  Instead, the editor's
        # Paint event is consumed while the symbols are supposed to own the field.
        self._suppress_editor_paint = not bool(visible)
        try:
            le = self._line_edit()
            if le is not None:
                le.update()
        except Exception:
            pass

    def _fit(self):
        """Cover only the numeric editor and keep the overlay above it.

        The spinbox arrow/roll buttons remain completely unobstructed.
        """
        try:
            le = self._line_edit()
            if le is not None:
                # The editor rectangle is the safe paint area. It excludes the
                # QAbstractSpinBox up/down button subcontrols.
                top_left = le.mapTo(self.owner, QPoint(0, 0))
                r = QRect(
                    int(top_left.x()),
                    int(top_left.y()),
                    int(le.width()),
                    int(le.height()),
                )
            else:
                # Fallback: reserve a right-side strip for native roll buttons.
                r = self.owner.rect()
                reserve = max(20, min(34, int(r.width() * 0.22)))
                r.setWidth(max(1, r.width() - reserve))

            if self.parent() is not self.owner:
                self.setParent(self.owner)

            if self.geometry() != r:
                self.setGeometry(r)

            # Keep the author symbols visually on top of the editor.
            self.raise_()
        except RuntimeError:
            pass
        except Exception:
            pass


    def _display_numeric_text(self):
        try:
            if isinstance(self.owner, QDoubleSpinBox):
                decimals = max(0, int(self.owner.decimals()))
                txt = f"{float(self.owner.value()):.{decimals}f}"
                if "." in txt:
                    txt = txt.rstrip("0").rstrip(".")
                return txt
            return str(int(self.owner.value()))
        except Exception:
            try:
                return str(self.owner.value())
            except Exception:
                return "0"

    def _sync(self, force=False):
        if self._syncing:
            return
        self._syncing = True
        try:
            editing = self._is_editing()
            symbols = bool(MATH_SYMBOLS_ENABLED)
            self._symbols = symbols
            self._role = _infer_ot_numeric_role(
                self.owner,
                self._display_numeric_text(),
            )

            # The ordinary number is visible only while the user is actively
            # editing or when symbol mode is disabled.
            self._set_owner_number_text_visible((not symbols) or editing)
            self._fit()

            show_glyphs = bool(symbols and not editing)
            if self.isVisible() != show_glyphs:
                self.setVisible(show_glyphs)

            if show_glyphs:
                self.raise_()
                key = (
                    self._display_numeric_text(),
                    self.width(),
                    self.height(),
                )
                if force or key != self._last_render_key:
                    self._last_render_key = key
                    self.update()
        finally:
            self._syncing = False

    def eventFilter(self, obj, event):
        t = event.type()

        # Absolute masking: consume the editor's paint event.  This is what
        # prevents the base-10 Hindu-Arabic numeral from leaking through even
        # under aggressive application/QStyle stylesheets.
        if obj is self._editor and t == QEvent.Type.Paint:
            if (
                self._suppress_editor_paint
                and bool(MATH_SYMBOLS_ENABLED)
                and not self._is_editing()
            ):
                return True
            return False

        if t in (
            QEvent.Type.Resize,
            QEvent.Type.Show,
            QEvent.Type.LayoutRequest,
            QEvent.Type.FontChange,
        ):
            QTimer.singleShot(0, lambda: self._sync(force=True))

        elif t == QEvent.Type.FocusIn:
            self._set_owner_number_text_visible(True)
            self.hide()
            try:
                if self._editor is not None:
                    self._editor.update()
            except Exception:
                pass

        elif t == QEvent.Type.FocusOut:
            QTimer.singleShot(0, lambda: self._sync(force=True))

        return False

    def mousePressEvent(self, event):
        event.ignore()

    def mouseReleaseEvent(self, event):
        event.ignore()

    def mouseMoveEvent(self, event):
        event.ignore()

    def wheelEvent(self, event):
        event.ignore()

    def paintEvent(self, event):
        if not MATH_SYMBOLS_ENABLED:
            return

        with owned_painter(self) as painter:
            if painter is None:
                return
            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)

            text = self._display_numeric_text()
            negative = text.startswith("-")
            raw = text[1:] if text[:1] in ("-", "+") else text
            digits = [c for c in raw if c.isdigit()]
            if not digits:
                digits = ["0"]

            radix_index = _decimal_boundary_index(text)

            gutter = 2.0
            n = max(1, len(digits))
            # 42px is the authored public target. Fit downward only when the editor
            # cannot hold that many compact digits. Reserve a quarter-cell on both
            # sides for the cycle motion so right/left phases never leave the field.
            preferred = 42.0
            max_by_width = (max(10.0, float(self.width()) - 4.0) - max(0, n-1)*gutter) / (n + 0.5)
            max_by_height = max(12.0, float(self.height()) - 2.0)
            cell = max(12.0, min(preferred, max_by_width, max_by_height))
            motion_margin = cell * 0.25
            total = len(digits) * cell + max(0, len(digits)-1) * gutter
            x = max(1.0 + motion_margin, (self.width() - total) / 2.0)
            y = max(motion_margin, (self.height() - cell) / 2.0)

            role_color = _ot_role_color(self._role)

            for i, ch in enumerate(digits):
                dx, dy, inward, phase = _quarter_cycle_state(i, negative=negative, cell=cell)

                glyph = _ot_glyph_for_display_digit(
                    ch,
                    i,
                    negative,
                    self._role,
                    operation=self._operation,
                    continued=self._continued,
                    multiplicity=self._multiplicity,
                    variable_letter=self._variable_letter,
                )

                # Preserve the original glyph exactly; only move it.
                self._draw_glyph(
                    painter,
                    glyph,
                    x + dx,
                    y + dy,
                    cell,
                )

                # At the 0.5-space point, add the squiggle accent.
                self._draw_halfspace_squiggle(
                    painter,
                    x + dx,
                    y + dy,
                    cell,
                    role_color,
                    phase,
                )

                # Decimal point consumes no cell. Mark the boundary on the first
                # fractional glyph with a compact squiggle accent.
                if radix_index is not None and i == radix_index:
                    self._draw_radix_squiggle(
                        painter,
                        x + dx,
                        y + dy,
                        cell,
                        role_color,
                    )

                x += cell + gutter



# =============================================================================
# CACHED_AUTHOR_NUMERIC_FONT_20260906
# Replace the legacy paint-intercepting numeric overlay with a stable per-field
# glyph-atlas adapter.  The old class remains above only for source-history
# compatibility; this rebinding is the runtime implementation used by all
# subsequently-created numeric symbol fields.
# =============================================================================
_LegacyOTNumericOverlay = _OTNumericOverlay

class _OTNumericOverlay(AuthorNumericFieldAdapter):
    """Cached author-numeric font adapter living inside each spinbox editor.

    It never consumes QLineEdit Paint events and never rewrites the editor's
    numeric value/text.  Each field owns one cached pixmap instance that is
    regenerated only after value, role, size, palette, or notation changes.
    """
    def __init__(self, owner):
        super().__init__(
            owner,
            role_provider=lambda w, t: _infer_ot_numeric_role(w, t),
            enabled_provider=lambda: bool(MATH_SYMBOLS_ENABLED),
            font_library=AUTHOR_NUMERIC_FONT,
        )



class _OTMixedNumericTextOverlay(OTNumberGlyphWidget):
    """Replace numeric substrings in ordinary UI text with 32px author glyphs.

    Nonnumeric text, percent signs and decimal points stay ordinary.  Role color
    follows the existing OT five-role palette.
    """
    NUMBER_RE = re.compile(r"(?<![\w])[-+]?\d+(?:\.\d+)?|[-+]?\d+(?:\.\d+)?")

    def __init__(self, owner):
        self.owner = owner
        self._syncing = False
        self._native_style = str(owner.styleSheet() or "")
        self._last_source = None
        self._source_text = ""
        self._native_hidden = False
        super().__init__(0, role=OTRole.RESULT, parent=owner)

        # Safe deferred refresh.  Because this timer is parented to the overlay,
        # Qt destroys/cancels it with the overlay; no stale lambda can call a
        # deleted C++ QWidget.
        self._sync_timer = QTimer(self)
        self._sync_timer.setSingleShot(True)
        self._sync_timer.setInterval(33 if _low_power_mode() else 16)  # PERF: 16ms normal, 33ms low-power/symbols
        self._sync_timer.timeout.connect(self._deferred_sync)
        self.setMinimumSize(0, 0)
        self.setMaximumSize(16777215, 16777215)
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents, True)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self.setAttribute(Qt.WidgetAttribute.WA_NoSystemBackground, False)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground, True)
        self.setAutoFillBackground(False)
        self.setStyleSheet("background: transparent; border: none;")
        try:
            owner.installEventFilter(self)
        except Exception:
            pass
        try:
            if isinstance(owner, QLineEdit):
                owner.textChanged.connect(lambda *_: self._sync(force=True))
            elif isinstance(owner, QProgressBar):
                owner.valueChanged.connect(lambda *_: self._sync(force=True))
        except Exception:
            pass
        self._sync(force=True)

    def _request_sync(self, force=True):
        try:
            if self._sync_timer is not None and not self._sync_timer.isActive():
                self._sync_timer.start()
        except RuntimeError:
            pass
        except Exception:
            pass

    def _deferred_sync(self):
        try:
            self._sync(force=True)
        except RuntimeError:
            # Owner/overlay may have been destroyed between event delivery and
            # timeout; this is a normal Qt lifetime edge, not an app failure.
            pass
        except Exception:
            pass

    def _raw_text(self):
        try:
            if isinstance(self.owner, QLabel):
                return str(self.owner.text() or "")
            if isinstance(self.owner, (QPushButton, QToolButton, QCheckBox)):
                return str(self.owner.text() or "")
            if isinstance(self.owner, QProgressBar):
                return str(self.owner.text() or "")
            if isinstance(self.owner, QLineEdit):
                return str(self.owner.text() or "")
        except Exception:
            pass
        return ""

    def _is_editing(self):
        try:
            return isinstance(self.owner, QLineEdit) and self.owner.hasFocus()
        except Exception:
            return False

    def _set_native_visible(self, visible):
        # For editable line edits, block paint when symbolized; for text widgets,
        # an owner-local transparent text color leaves frames/icons/backgrounds.
        visible = bool(visible)
        if visible == (not self._native_hidden):
            return
        try:
            if visible:
                if not isinstance(self.owner, QLineEdit):
                    self.owner.setStyleSheet(self._native_style)
                self._native_hidden = False
            else:
                if not isinstance(self.owner, QLineEdit):
                    base = self._native_style
                    hidden = base + "\ncolor: rgba(0,0,0,0);"
                    if isinstance(self.owner, QProgressBar):
                        hidden += "\nQProgressBar { color: rgba(0,0,0,0); }"
                    self.owner.setStyleSheet(hidden)
                self._native_hidden = True
        except RuntimeError:
            pass
        except Exception:
            pass

    def _fit(self):
        try:
            r = self.owner.rect()
            if self.geometry() != r:
                self.setGeometry(r)
            self.raise_()
        except Exception:
            pass

    def _sync(self, force=False):
        if self._syncing:
            return
        self._syncing = True
        try:
            raw = self._raw_text()
            has_number = bool(self.NUMBER_RE.search(raw))
            editing = self._is_editing()
            enabled = bool(MATH_SYMBOLS_ENABLED and has_number and not editing)

            self._source_text = raw
            self._role = _infer_ot_numeric_role(self.owner, raw)

            # Long readouts/constants must not silently lose right-hand decimal
            # glyphs.  Labels and progress/readout widgets may request the exact
            # width needed by the visible number string.  Interactive controls
            # keep their authored geometry.
            if enabled and isinstance(self.owner, (QLabel, QProgressBar)):
                try:
                    fm = QFontMetrics(self.owner.font())
                    required = 8.0
                    pos = 0
                    for m in self.NUMBER_RE.finditer(raw):
                        if m.start() > pos:
                            required += fm.horizontalAdvance(raw[pos:m.start()])
                        required += self._token_width(m.group(0), fm)
                        pos = m.end()
                    if pos < len(raw):
                        required += fm.horizontalAdvance(raw[pos:])
                    self.owner.setMinimumWidth(max(self.owner.minimumWidth(), int(required + 8.0)))
                    self.owner.setMinimumHeight(max(self.owner.minimumHeight(), 36))
                except Exception:
                    pass

            self._set_native_visible(not enabled)
            self._fit()

            try:
                if self.isVisible() != enabled:
                    self.setVisible(enabled)
            except RuntimeError:
                return

            if enabled:
                try:
                    self.raise_()
                    key = (raw, self.width(), self.height(), self._role)
                    if force or key != self._last_source:
                        self._last_source = key
                        self.update()
                except RuntimeError:
                    return
        except RuntimeError:
            return
        finally:
            self._syncing = False

    def eventFilter(self, obj, event):
        t = event.type()

        # General QLineEdit: when symbolized and not focused, suppress its native
        # text paint at the source.  Spinbox line edits are excluded by installer.
        if isinstance(self.owner, QLineEdit) and t == QEvent.Type.Paint:
            if self._native_hidden and MATH_SYMBOLS_ENABLED and not self._is_editing():
                return True
            return False

        if t in (
            QEvent.Type.Show,
            QEvent.Type.Resize,
            QEvent.Type.LayoutRequest,
            QEvent.Type.FontChange,
            QEvent.Type.UpdateRequest,
        ):
            self._request_sync(force=True)
        elif t == QEvent.Type.FocusIn:
            self._set_native_visible(True)
            self.hide()
        elif t == QEvent.Type.FocusOut:
            self._request_sync(force=True)
        elif t == QEvent.Type.Paint:
            # QLabel/QPushButton do not expose textChanged; compare lazily when
            # Qt is already repainting, then update after this event returns.
            current = self._raw_text()
            if current != self._source_text:
                self._request_sync(force=True)
        return False

    def _font_metrics(self, painter):
        try:
            font = QFont(self.owner.font())
        except Exception:
            font = QFont()
        painter.setFont(font)
        return painter.fontMetrics()

    def _alignment(self):
        try:
            if isinstance(self.owner, QLabel):
                return self.owner.alignment()
            if isinstance(self.owner, QLineEdit):
                return self.owner.alignment()
        except Exception:
            pass
        return Qt.AlignmentFlag.AlignCenter

    def _token_width(self, token, fm):
        if self.NUMBER_RE.fullmatch(token):
            raw = token[1:] if token[:1] in ("-", "+") else token
            digits = sum(ch.isdigit() for ch in raw)
            if digits <= 0:
                digits = 1
            return digits * 32.0 + max(0, digits - 1) * 2.0
        return float(fm.horizontalAdvance(token))


    def _draw_number(self, painter, token, x, y, cell=32.0):
        negative = token.startswith("-")
        raw = token[1:] if token[:1] in ("-", "+") else token
        digits = [c for c in raw if c.isdigit()]
        if not digits:
            digits = ["0"]

        radix_index = _decimal_boundary_index(token)
        role_color = _ot_role_color(self._role)

        for i, ch in enumerate(digits):
            dx, dy, inward, phase = _quarter_cycle_state(i, negative=negative, cell=cell)

            glyph = _ot_glyph_for_display_digit(
                ch,
                i,
                negative,
                self._role,
                operation=self._operation,
                continued=self._continued,
                multiplicity=self._multiplicity,
                variable_letter=self._variable_letter,
            )

            self._draw_glyph(
                painter,
                glyph,
                x + dx,
                y + dy,
                cell,
            )

            self._draw_halfspace_squiggle(
                painter,
                x + dx,
                y + dy,
                cell,
                role_color,
                phase,
            )

            if radix_index is not None and i == radix_index:
                self._draw_radix_squiggle(
                    painter,
                    x + dx,
                    y + dy,
                    cell,
                    role_color,
                )

            x += cell + 2.0

        return x


    def mousePressEvent(self, event):
        event.ignore()

    def mouseReleaseEvent(self, event):
        event.ignore()

    def mouseMoveEvent(self, event):
        event.ignore()

    def wheelEvent(self, event):
        event.ignore()

    def paintEvent(self, event):
        if not MATH_SYMBOLS_ENABLED:
            return
        text = self._source_text
        if not text or not self.NUMBER_RE.search(text):
            return

        with owned_painter(self) as painter:
            if painter is None:
                return
            painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            fm = self._font_metrics(painter)

            # Split while preserving numeric runs.
            parts = []
            pos = 0
            for m in self.NUMBER_RE.finditer(text):
                if m.start() > pos:
                    parts.append(("text", text[pos:m.start()]))
                parts.append(("number", m.group(0)))
                pos = m.end()
            if pos < len(text):
                parts.append(("text", text[pos:]))

            total = 0.0
            for kind, token in parts:
                total += self._token_width(token, fm)

            align = self._alignment()
            left_pad = 4.0
            if align & Qt.AlignmentFlag.AlignRight:
                x = max(left_pad, self.width() - total - 4.0)
            elif align & Qt.AlignmentFlag.AlignHCenter:
                x = max(left_pad, (self.width() - total) / 2.0)
            else:
                x = left_pad

            cell = 32.0
            y = max(0.0, (self.height() - cell) / 2.0)

            # Ordinary wording/punctuation uses the widget's normal foreground color.
            try:
                ordinary_color = self.owner.palette().color(QPalette.ColorRole.WindowText)
                if isinstance(self.owner, (QPushButton, QToolButton, QCheckBox)):
                    ordinary_color = self.owner.palette().color(QPalette.ColorRole.ButtonText)
                elif isinstance(self.owner, QLineEdit):
                    ordinary_color = self.owner.palette().color(QPalette.ColorRole.Text)
            except Exception:
                ordinary_color = QColor("#d8d8d8")

            for kind, token in parts:
                if kind == "number":
                    x = self._draw_number(painter, token, x, y, cell)
                else:
                    painter.setPen(QPen(ordinary_color))
                    # baseline centered against the fixed 32px symbol cell.
                    baseline = y + (cell + fm.ascent() - fm.descent()) / 2.0
                    painter.drawText(QPointF(x, baseline), token)
                    x += fm.horizontalAdvance(token)


class _MathSymbolSpinWatcher(QObject):
    """Event-driven installer for *actual numeric controls* only.

    PUBLIC_SYMBOL_PERF_FINAL_20260906: labels/buttons/readouts are deliberately
    not overpainted.  This keeps author notation confined to editable numeric
    fields and avoids an application-wide paint tax.  When Math Symbols is OFF
    this filter returns immediately and creates no overlay widgets.
    """
    TEXT_TYPES = ()

    def __init__(self, host):
        super().__init__(host)
        self._host = host
        self._pending_ids = set()

    def _is_spin_editor(self, obj):
        if not isinstance(obj, QLineEdit):
            return False
        try:
            return isinstance(obj.parentWidget(), (QSpinBox, QDoubleSpinBox))
        except Exception:
            return False

    def _install(self, obj, key):
        try:
            if MATH_SYMBOLS_ENABLED and isinstance(obj, (QSpinBox, QDoubleSpinBox)):
                self._host._ensure_math_symbol_overlay(obj)
        finally:
            self._pending_ids.discard(key)

    def eventFilter(self, obj, event):
        # Absolute fast path: public/default Symbols OFF performs no overlay
        # discovery, scheduling, layout or paint-related work.
        if not MATH_SYMBOLS_ENABLED:
            return False
        try:
            if event.type() == QEvent.Type.Show and isinstance(obj, (QSpinBox, QDoubleSpinBox)):
                oid = id(obj)
                if oid not in self._pending_ids:
                    self._pending_ids.add(oid)
                    QTimer.singleShot(0, lambda w=obj, key=oid: self._install(w, key))
        except RuntimeError:
            pass
        except Exception:
            pass
        return False


# =============================================================================
# PROCESSOR SYNTAX / DESIGN CONTRACT
# =============================================================================
# Every identity-bearing processor follows the same English-readable form:
#   INPUTS -> deterministic mathematical transform -> bounded state -> OUTPUT.
# Oscillator: phase += 2π*f_inst/SR; this is the minimal discrete-time carrier.
# AM: gain = 1 + depth*LFO; it changes energy without changing identity.
# FM: f_inst = f*(1 + depth*LFO); it creates deterministic sideband families.
# PM: phase += depth*sin(modulator); it changes timing while preserving carrier.
# Meum field: sin(M*t + phase) is shared by audio/visual state so both domains
# respond to the same invariant instead of inventing independent randomness.
# Cyclic orbit: p(i)=(a*i+b) mod n, gcd(a,n)=1; this is a finite bijection and
# therefore cannot repeat an index before the orbit closes.
# Hash-noise: H(parameters,index) is used where texture is needed; it is
# deterministic noise, so replaying the same state reproduces the same samples.
# GOAVA: a state bit is included in audio, scenograph and game fingerprints,
# so GOAVA ON/OFF is a genuine audiovisual state transition.
# UI-only randomize buttons may still request fresh user variation; that action
# is deliberately outside the canonical replay kernel.
# =============================================================================


