def ot_tan_via_isn_ics(x):
    c = ot_cos_via_ics(x)
    if c == 0.0:
        s = ot_sin_via_isn(x)
        return math.copysign(math.inf, s if s != 0.0 else 1.0)
    return ot_equiv_div(ot_sin_via_isn(x), c)


