def _seed_script_env(t_scalar=0.0, canonical_context=None):
    """Shared safe eval environment for composition-state and T-axis seed scripts.

    Includes standard math, Meum constants, isn/ics family (and inverses),
    arcisn/arcics, and Equation-of-Reality tensor handles P/E/D.
    Numeric-Python subset: no builtins except safe math helpers.
    """
    def _clamp(v, lo=None, hi=None):
        try:
            out=float(v)
            if lo is not None and out < float(lo):
                out=float(lo)
            if hi is not None and out > float(hi):
                out=float(hi)
            return out
        except Exception:
            return 0.0

    def _lerp(a, b, u):
        return float(a) + (float(b) - float(a)) * float(u)

    def _choose(*args):
        """Pick element i from args where i is the last arg (int index)."""
        if not args:
            return 0.0
        if len(args) == 1:
            return float(args[0])
        idx = int(args[-1]) % max(1, len(args) - 1)
        return float(args[idx])

    def isn(x):
        # Dual-mode: delegates to eqr_isn (OT nested blend when enabled).
        return eqr_isn(x)

    def ics(x):
        # Dual-mode: delegates to eqr_ics (OT nested blend when enabled).
        return eqr_ics(x)

    def _invert_odd(f, y, guess=0.0, lo=-math.pi, hi=math.pi, iters=24):
        y = float(y)
        a, b = float(lo), float(hi)
        fa, fb = f(a) - y, f(b) - y
        if fa * fb > 0:
            for _ in range(8):
                a *= 1.5
                b *= 1.5
                fa, fb = f(a) - y, f(b) - y
                if fa * fb <= 0:
                    break
        x = float(guess)
        for _ in range(iters):
            fx = f(x) - y
            h = 1e-6 + 1e-6 * abs(x)
            df = (f(x + h) - f(x - h)) / (2.0 * h)
            if abs(df) < 1e-12:
                if fa * (f(x) - y) <= 0:
                    b, fb = x, f(x) - y
                else:
                    a, fa = x, f(x) - y
                x = 0.5 * (a + b)
            else:
                x_new = x - fx / df
                x_new = _clamp(x_new, a, b)
                if abs(x_new - x) < 1e-12:
                    return float(x_new)
                x = x_new
        return float(x)

    def isn_inv(y):
        return _invert_odd(isn, y, guess=float(y), lo=-math.pi, hi=math.pi)

    def ics_inv(y):
        y = float(y)
        return abs(_invert_odd(ics, y, guess=0.5, lo=0.0, hi=math.pi))

    def arcisn(y):
        return isn_inv(y)

    def arcics(y):
        return ics_inv(y)

    def isn_pow_neg1(y):
        return isn_inv(y)

    def ics_pow_neg1(y):
        return ics_inv(y)

    def P(s, c=0.0, *rest):
        s = float(s)
        ctx = [float(c)]
        for r in rest:
            ctx.append(float(r))
        return float(eqr_tensor_step(s, ctx, t=float(t_scalar))[0])

    def E(s, c=0.0, *rest):
        s = float(s)
        ctx = [float(c)]
        for r in rest:
            ctx.append(float(r))
        return float(eqr_tensor_step(s, ctx, t=float(t_scalar))[1])

    def D(s, c=0.0, *rest):
        s = float(s)
        ctx = [float(c)]
        for r in rest:
            ctx.append(float(r))
        return float(eqr_tensor_step(s, ctx, t=float(t_scalar))[2])

    def tensor_z(s, c=0.0):
        s = float(s)
        ctx = [float(c)]
        z = eqr_tensor_step(s, ctx, t=float(t_scalar))[3]
        return float(_clamp(z, 0.05, 3.0))

    def tensor_rel(s, c=0.0, z_ref=1.5):
        zr=float(z_ref)
        if zr == 0.0:
            return 0.0
        return tensor_z(s, c) / zr

    def _parametric(*coords):
        vals = []
        for value in coords:
            nums = _coerce_numeric_values(value)
            if not nums:
                return []
            vals.append(float(nums[0]))
        return tuple(vals)

    def cartesian(x, y, z=None):
        return _parametric(x, y) if z is None else _parametric(x, y, z)

    def parametric(*coords):
        return _parametric(*coords)

    def polar(r, theta):
        r, theta = float(r), float(theta)
        return (r * series_book_isx(theta), r * series_book_isy(theta))

    def cylindrical(r, theta, z=0.0):
        r, theta, z = float(r), float(theta), float(z)
        return (r * series_book_isx(theta), r * series_book_isy(theta), z)

    def spherical(r, theta, phi):
        r, theta, phi = float(r), float(theta), float(phi)
        return (r * series_book_isy(phi) * series_book_isx(theta),
                r * series_book_isy(phi) * series_book_isy(theta),
                r * series_book_isx(phi))

    env = {
        "__builtins__": {},
        # Transcendentals route through math_* so Operator Theory ON uses the
        # equivalence kernel (identical numeric result to ordinary math.*).
        "sin": math_sin, "cos": math_cos, "tan": math_tan, "sqrt": math_sqrt,
        "log": math_log, "log2": math_log2, "log10": math_log10, "exp": math_exp,
        "abs": abs, "min": min, "max": max, "floor": math.floor, "ceil": math.ceil,
        "round": round, "pow": pow, "fabs": math.fabs, "hypot": math.hypot,
        "atan2": math_atan2, "asin": math_asin, "acos": math_acos, "atan": math_atan,
        "sinh": math_sinh, "cosh": math_cosh, "tanh": math_tanh,
        "degrees": math.degrees, "radians": math.radians,
        "pi": math.pi, "e": math.e, "tau": math.tau,
        "PHI": PHI, "MEUM": MEUM, "MEUM_NORM": MEUM_NORM, "MEUM_INV": MEUM_INV,
        "MEUM_SQ": MEUM_SQ, "MEUM_LOG2": MEUM_LOG2, "SILVER": SILVER,
        "SQRT2": SQRT2, "SQRT3": SQRT3,
        "clamp": _clamp, "lerp": _lerp, "choose": _choose,
        "cartesian": cartesian, "parametric": parametric, "polar": polar,
        "cylindrical": cylindrical, "spherical": spherical,
        "isn": isn, "ics": ics, "isx": isx, "isy": isy,
        "isn_inv": isn_inv, "ics_inv": ics_inv,
        "arcisn": arcisn, "arcics": arcics,
        "isn_inverse": isn_inv, "ics_inverse": ics_inv,
        "P": P, "E": E, "D": D,
        "tensor_z": tensor_z, "tensor_rel": tensor_rel,
        "ot_add": ot_add, "ot_sub": ot_sub, "ot_prod": ot_prod,
        "ot_div": ot_div, "ot_pow": ot_pow, "ot_i_phase": ot_i_phase,
        "ot_equiv_add": ot_equiv_add, "ot_equiv_sub": ot_equiv_sub,
        "ot_equiv_mul": ot_equiv_mul, "ot_equiv_div": ot_equiv_div,
        "ot_equiv_pow": ot_equiv_pow, "ot_equiv_root": ot_equiv_root,
        "ot_equiv_i_pow": ot_equiv_i_pow,
        "ot_book_isn": ot_book_isn, "ot_book_isn_inv": ot_book_isn_inv,
        "ot_book_ics": ot_book_ics, "ot_book_ics_inv": ot_book_ics_inv,
        "ot_band": ot_band, "ot_master_transform": ot_master_transform,
        "math_add": math_add, "math_sub": math_sub, "math_mul": math_mul,
        "math_div": math_div, "math_pow": math_pow, "math_scale": math_scale,
        "math_sin": math_sin, "math_cos": math_cos, "math_tan": math_tan,
        "math_asin": math_asin, "math_acos": math_acos, "math_atan": math_atan,
        "math_atan2": math_atan2, "math_sinh": math_sinh, "math_cosh": math_cosh,
        "math_tanh": math_tanh, "math_sqrt": math_sqrt, "math_exp": math_exp,
        "math_log": math_log, "math_log2": math_log2, "math_log10": math_log10,
        "ot_equiv_sin": ot_equiv_sin, "ot_equiv_cos": ot_equiv_cos,
        "ot_equiv_tan": ot_equiv_tan, "ot_equiv_asin": ot_equiv_asin,
        "ot_equiv_acos": ot_equiv_acos, "ot_equiv_atan": ot_equiv_atan,
        "ot_equiv_atan2": ot_equiv_atan2, "ot_equiv_sinh": ot_equiv_sinh,
        "ot_equiv_cosh": ot_equiv_cosh, "ot_equiv_tanh": ot_equiv_tanh,
        "ot_equiv_sqrt": ot_equiv_sqrt, "ot_equiv_exp": ot_equiv_exp,
        "ot_equiv_log": ot_equiv_log, "ot_equiv_log2": ot_equiv_log2,
        "ot_equiv_log10": ot_equiv_log10, "ot_equiv_fabs": ot_equiv_fabs,
        "ot_equiv_floor": ot_equiv_floor, "ot_equiv_ceil": ot_equiv_ceil,
        "ot_equiv_hypot": ot_equiv_hypot,
        "no_sat": no_sat,
        # AUTHOR_SYMBOL_CODEC_V4: scripting sees the same semantic spelling/
        # decoder used by Qt, project provenance and native sCode.
        "author_symbol_spell": lambda value: author_symbol_spell_packet(str(value)).to_dict(),
        "author_symbol_decode": lambda integer_cells, half=False, fractional_cells=(), negative=False: float(
            author_symbol_decode_authored(integer_cells, half_squiggle=bool(half), fractional_cells=fractional_cells, negative=bool(negative))
        ),
        "author_symbol_fraction": lambda value, slot, spaced=True: float(
            author_symbol_fractional_cell_value(int(value), int(slot), bool(spaced))
        ),
        "AUTHOR_NUMBER_SCHEME": AUTHOR_NUMBER_SCHEME,
        "op_theory_enabled": operator_theory_enabled,
        "set_op_theory": set_operator_theory,
        "t": float(t_scalar), "x": float(t_scalar), "y": 0.0, "z": 0.0,
        "True": True, "False": False, "None": None,
        "carrier_present": 0,
        "carrier_rms": 0.0,
        "carrier_peak": 0.0,
        "canonical_unison": 0,
        "canonical_count": 0,
        "canonical_mask": 0,
        "canonical_randomizer": 0,
        "canonical_phase_lock": 0,
        "canonical_euclidean": 0,
        "canonical_seeded": 0,
        "canonical_goava": 0,
        "canonical_roster_size": 0,
        # PROJECT SEED SCRIPT CANONICAL HANDLES. These are stable scalar aliases;
        # a supplied canonical_context overrides them below without eval/builtins.
        "vector_x": 0.0, "vector_y": 0.0, "vector_z": 0.0, "vector_drive": 0.5,
        "wavetable_phase": 0.0, "wavetable_curvature": 0.5, "wavetable_twist": 0.5,
        "wavetable_fold": 0.2, "wavetable_canonical_share": 1.0,
        "ball_gravity": 0.25, "ball_gravity_angle": 90.0, "ball_radius": 1.0,
        "ball_vx": 0.7, "ball_vy": -0.4, "ball_polarity": 1,
        "cell_width": 16, "cell_height": 16, "cell_types": 3, "cell_generations": 16,
        "cell_rule": 30,
            "cell_canonical_share": 1.0, "sidechain_depth": 0.5, "sidechain_attack_ms": 10.0,
        "sidechain_release_ms": 120.0, "eq_poles": 128, "eq_low_hz": 10.0,
        "eq_high_hz": 24000.0, "mix_seeded": 1.0, "mix_rand": 1.0,
        "mix_lock": 0.5, "mix_euclidean": 1.0, "mix_goava": 0.19758,
        "goava_canonical_amplitude": 0.19758,
        # list helpers for numeric-Python scripts
        "list": list, "tuple": tuple, "float": float, "int": int, "bool": bool,
        "len": len, "sum": sum, "range": range, "enumerate": enumerate,
        "zip": zip, "sorted": sorted, "reversed": reversed,
    }
    env.update(_SEED_EXTRA_HELPERS)
    # FULL_GRAPH_SCRIPT_CONTEXT_2026: Seed, Instrument, Algorithm, Domain,
    # Canonical, video and game scripts share one graph-variable vocabulary.
    # Preserve the historical Seed Script default x=t when no explicit graph x
    # is supplied, while allowing render/canonical callers to inject true XYZ.
    _cc = canonical_context if isinstance(canonical_context, dict) else {}
    _gx = _cc.get("x", _cc.get("graph_x", t_scalar))
    _gy = _cc.get("y", _cc.get("graph_y", 0.0))
    _gz = _cc.get("z", _cc.get("graph_z", 0.0))
    _gseed = _cc.get("seed", 0.0)
    _gctx = build_graph_context(
        t=t_scalar, t_norm=_cc.get("t_norm", t_scalar),
        x=_gx, y=_gy, z=_gz, seed=_gseed, seed_w=_cc.get("seed_w"),
        graph_index=_cc.get("graph_index", 0), graph_count=_cc.get("graph_count", 1),
        slot=_cc.get("graph_slot", _cc.get("slot", 0)),
        sequence=_cc.get("sequence_index", _cc.get("sequence", 1)),
        step=_cc.get("step_index", _cc.get("step", 0)),
        bpm=_cc.get("bpm", 120.0), sample_rate=_cc.get("sample_rate", 44100.0),
        domain_value=_cc.get("domain_value", 0.0), domain_weight=_cc.get("domain_weight", 1.0),
        graph_id=_cc.get("graph_id", "seed"), domain_id=_cc.get("domain_id", ""),
        canonical_context=_cc,
    )
    env.update(graph_context_env(_gctx))
    if isinstance(canonical_context, dict):
        for _k, _v in canonical_context.items():
            if isinstance(_k, str) and _k.isidentifier() and isinstance(_v, (int, float, bool)):
                env[_k] = _v
        # Flatten common canonical sub-states into documented scalar handles.
        _nested_aliases = {
            "vector": {"x":"vector_x", "y":"vector_y", "z":"vector_z", "drive":"vector_drive"},
            "wavetable": {"phase":"wavetable_phase", "curvature":"wavetable_curvature", "twist":"wavetable_twist", "fold":"wavetable_fold", "canonical_share":"wavetable_canonical_share"},
            "ball": {"gravity":"ball_gravity", "gravity_angle_degrees":"ball_gravity_angle", "radius":"ball_radius", "vx":"ball_vx", "vy":"ball_vy", "initial_polarity":"ball_polarity"},
            "cellular_automata": {"width":"cell_width", "height":"cell_height", "cell_types":"cell_types", "generations":"cell_generations", "rule":"cell_rule"},
            "sidechain": {"depth":"sidechain_depth", "attack_ms":"sidechain_attack_ms", "release_ms":"sidechain_release_ms"},
            "eq": {"poles":"eq_poles", "low_hz":"eq_low_hz", "high_hz":"eq_high_hz"},
            "mix": {"seeded":"mix_seeded", "rand":"mix_rand", "lock":"mix_lock", "euclidean":"mix_euclidean", "goava":"mix_goava"},
        }
        for _group, _mapping in _nested_aliases.items():
            _values = canonical_context.get(_group)
            if isinstance(_values, dict):
                for _source, _target in _mapping.items():
                    _value = _values.get(_source)
                    if isinstance(_value, (int, float, bool)):
                        env[_target] = _value
    # Clamp documented physical/routing handles to safe finite domains.
    for _key, _lo, _hi in (("goava_canonical_amplitude",0.0,1.0),("mix_goava",0.0,1.0),("sidechain_depth",0.0,1.0),("eq_poles",2.0,128.0),("eq_low_hz",10.0,24000.0),("eq_high_hz",10.0,24000.0)):
        try:
            _v=float(env[_key]); env[_key]=max(_lo,min(_hi,_v)) if math.isfinite(_v) else _lo
        except Exception:
            env[_key]=_lo
    return env


def _ot_rewrite_seed_ast(tree):
    """Seed text: names and operators stay as the author wrote them; only the division
    operators (/, //, %) are routed through OT division, which equals Python's for every
    non-zero divisor and defines the zero case while OT is on
    (GROOVEBOX_R23R_OT_SCRIPT_DIVISION_20261103, see ot_script_math)."""
    import ot_script_math
    return ot_script_math.rewrite(tree)



def _normalize_seed_script_text(seed_text):
    """Normalize multiline seed scripts into a single evaluable expression.

    Supports plain numbers, math, return, if/elif shorthand, last non-comment line.
    """
    import re as _re
    text = str(seed_text or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    if not text:
        return ""

    returns = list(_re.finditer(r"(?im)^\s*return\s+(.+?)\s*$", text))
    if returns:
        text = returns[-1].group(1).strip()
    else:
        lines = []
        for ln in text.splitlines():
            s = ln.strip()
            if not s or s.startswith("#"):
                continue
            lines.append(s)
        if lines:
            text = lines[-1]

    text = _re.sub(r"^\s*return\s+", "", text, count=1, flags=_re.I)
    shorthand = _parse_if_elif_shorthand(text)
    if shorthand:
        text = shorthand
    return text.strip()


# GROOVEBOX_R23R_SEED_WORKSPACE_OVERRIDE_20261101: when False the seed panel's
# "Disable workspace override" switch is on: seed scripts see their own defaults
# (x = t, bpm 120, sequence 1, …) instead of the live workspace-bound values.
SEED_WORKSPACE_OVERRIDE = True


def _eval_seed_python(seed_text, t_value=0.0, canonical_context=None, allow_scrape=True):
    """Evaluate seed text as a numeric-Python subset; return list of finite floats.

    Strategy (first success wins):
      1. Normalized single expression (if/elif → ternary, return stripped)
      2. Parenthesis-aware comma/newline list of expressions
      3. Multi-line exec: assignments + final expression / return
      4. Scrape plain numeric tokens from the text (only if allow_scrape)

    Non-numeric results are ignored; only attributable finite numbers remain.

    SCRAPE_IS_LAST_RESORT_ONLY: step 4 is a blunt regex pull of bare digits
    sitting in the raw text — it does not evaluate the script at all. A
    script that is well-formed but hits a domain error at one exact instant
    (e.g. "sqrt(t - 1) * 100" at t=0.0, "100/tan(t)" at t=0.0) throws in
    steps 1-3, and step 4 would then silently return whichever literal
    numbers happen to appear in the source ("1", "100", ...) — values that
    have nothing to do with what the formula actually computes and that
    ignore the real time-varying/conditional behavior entirely. Callers
    that can retry at a nearby, non-degenerate `t` (get_seed_values,
    evaluate_seed_expression_at_time) should do that FIRST with
    allow_scrape=False, so a genuinely evaluable script always wins over a
    blind digit-scrape. The scrape stays available as a true last resort
    for text that truly has no evaluable structure at any t.
    """
    if not SEED_WORKSPACE_OVERRIDE:
        canonical_context = None
    import re as _re

    raw = str(seed_text or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    if not raw:
        return []

    try:
        t_scalar = float(np.asarray(t_value).reshape(-1)[0]) if hasattr(t_value, "__len__") else float(t_value)
    except Exception:
        t_scalar = 0.0
    if not math.isfinite(t_scalar):
        t_scalar = 0.0

    env = _seed_script_env(t_scalar=t_scalar, canonical_context=canonical_context)

    # Coordinate DSL is evaluated before ordinary expression/list parsing so
    # x(t)/y(t), polar and related curves remain structurally meaningful.
    coord = _eval_coordinate_seed_script(raw, env)
    if coord is not None:
        return list(coord[0])

    def _try_expr(expr):
        expr = str(expr or "").strip()
        if not expr or expr.startswith("#"):
            return None
        # strip leading return
        expr = _re.sub(r"^\s*return\s+", "", expr, count=1, flags=_re.I)
        sh = _parse_if_elif_shorthand(expr)
        if sh:
            expr = sh
        try:
            v = float(expr)
            if math.isfinite(v):
                return [v]
        except Exception:
            pass
        try:
            tree = ast.parse(expr, mode="eval")
            tree = _ot_rewrite_seed_ast(tree)
            __import__("ot_script_math").install(env)
            val = eval(compile(tree, "<groovebox-seed>", "eval"), env)
            nums = _coerce_numeric_values(val)
            return nums if nums else None
        except Exception:
            return None

    # 0) GROOVEBOX_R32_SEED_LANGUAGE_20261109: the whole text as ONE program (compiled
    #    once, cached by text; top-level return, outputs, coordinates, last assignment).
    #    This is the authoritative path; the older strategies below only serve text the
    #    language cannot compile (they could value a 60-line program by one stray line).
    try:
        import seed_lang as _sl
        if _sl.HOOKS.get("if_elif_shorthand") is None:
            _sl.HOOKS["if_elif_shorthand"] = _parse_if_elif_shorthand
        _ev = _sl.evaluate(raw, env)
        if _ev.values:
            return list(_ev.values)
        if _ev.source == "none":
            # Compiled and ran, produced no number (e.g. only comments): nothing to scrape.
            return []
    except Exception:
        pass

    # 1) Whole normalized field as one expression
    text = _normalize_seed_script_text(raw)
    if text:
        nums = _try_expr(text)
        if nums:
            return nums

    # 2) Parenthesis-aware list split
    parts = _split_seed_list_parts(raw)
    if len(parts) > 1:
        vals = []
        for part in parts:
            nums = _try_expr(part)
            if nums:
                vals.extend(nums)
        if vals:
            return vals
    elif len(parts) == 1:
        nums = _try_expr(parts[0])
        if nums:
            return nums

    # 3) Multi-line / statement form via exec
    #    Allow: assignments, if/elif/else blocks, final expression or return
    try:
        # Transform bare final expression into _result = <expr>
        lines = []
        for ln in raw.splitlines():
            s = ln.strip()
            if not s or s.startswith("#"):
                continue
            lines.append(ln)
        if lines:
            body = "\n".join(lines)
            # If last line is an expression (not assignment / if / return), capture it
            last = lines[-1].strip()
            if not _re.match(r"^(return|if|elif|else|for|while|def|class|with)\b", last) and "=" not in last.split("#")[0]:
                # expression statement → bind
                body = "\n".join(lines[:-1] + [f"_result = ({last})"])
            elif last.lower().startswith("return "):
                body = "\n".join(lines[:-1] + [f"_result = ({last[7:].strip()})"])
            local = dict(env)
            local["_result"] = None
            # allow limited statement forms
            tree = ast.parse(body, mode="exec")
            tree = _ot_rewrite_seed_ast(tree)
            __import__("ot_script_math").install(local)
            exec(compile(tree, "<groovebox-seed-exec>", "exec"), local, local)
            if local.get("_result") is not None:
                nums = _coerce_numeric_values(local["_result"])
                if nums:
                    return nums
            # also collect any numeric names assigned
            for k, v in local.items():
                if k.startswith("_") or k in env:
                    continue
                nums = _coerce_numeric_values(v)
                if nums:
                    return nums
    except Exception:
        pass

    # 4) Token scrape — last resort for typed numbers in otherwise junk text.
    # Gated behind allow_scrape so callers can retry a real evaluation at a
    # nearby, non-degenerate t before ever falling back to raw digit-scraping.
    if not allow_scrape:
        return []
    vals = []
    for m in _re.finditer(r"[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?", raw):
        try:
            v = float(m.group(0))
            if math.isfinite(v):
                vals.append(v)
        except Exception:
            pass
    return vals


def evaluate_seed_expression_at_time(seed_text, t_value, canonical_context=None):
    """Time-domain (T-axis) evaluation → single float for DSP/render.

    Uses the numeric-Python seed protocol. List scripts are sampled by t phase.
    Never returns a SHA/byte-derived float.
    """
    vals = _eval_seed_python(seed_text, t_value=t_value, canonical_context=canonical_context, allow_scrape=False)
    if vals and _seed_script_is_coordinate(seed_text):
        return _coordinate_seed_projection(vals)
    if not vals:
        # Degenerate-t retry — try a REAL evaluation at nearby t before ever
        # falling back to digit-scraping (see SCRAPE_IS_LAST_RESORT_ONLY).
        try:
            base = float(np.asarray(t_value).reshape(-1)[0]) if hasattr(t_value, "__len__") else float(t_value)
        except Exception:
            base = 0.0
        for probe in (base + 1e-6, base - 1e-6, base + 1e-3, base + 0.5, base + 1.0, 0.25, 1.0):
            vals = _eval_seed_python(seed_text, t_value=probe, canonical_context=canonical_context, allow_scrape=False)
            if vals:
                break
    if not vals:
        # True last resort: no evaluable form at any probed t — scrape.
        vals = _eval_seed_python(seed_text, t_value=t_value, canonical_context=canonical_context, allow_scrape=True)
    if not vals:
        return 0.0
    if len(vals) == 1:
        return float(vals[0])
    try:
        t_scalar = float(np.asarray(t_value).reshape(-1)[0]) if hasattr(t_value, "__len__") else float(t_value)
    except Exception:
        t_scalar = 0.0
    idx = int(math.floor(abs(t_scalar) * max(1.0, len(vals)))) % len(vals)
    return float(vals[idx])


def _app_full_graph_context(app, t_value=0.0, *, t_norm=None, slot=0, row=0, sequence=1, step=0, name=""):
    """Resolve the current composition into the shared script graph payload.

    This is the bridge that prevents Seed/Instrument/Algorithm/Domain/Video/Game
    paths from collapsing a varying graph to one unrelated scalar too early.
    """
    try:
        t = float(t_value)
    except Exception:
        t = 0.0
    if t_norm is None:
        t_norm = float(np.clip(t, 0.0, 1.0))
    try:
        seed = float(app.get_numeric_seed()) if app is not None and hasattr(app, "get_numeric_seed") else 0.0
    except Exception:
        seed = 0.0
    seed_text = ""
    try:
        seed_text = app._seed_text() if app is not None and hasattr(app, "_seed_text") else ""
    except Exception:
        seed_text = ""
    # GRAPH_CONTEXT_CACHE_2026: Instrument + Algorithm commonly evaluate at
    # the exact same control point. Cache the expensive seed/domain projection
    # once so richer graph coverage does not double script-parsing work.
    _cache = getattr(app, "_graph_context_cache", None) if app is not None else None
    if app is not None and not isinstance(_cache, dict):
        _cache = {}
        app._graph_context_cache = _cache
    _cache_key = None
    if isinstance(_cache, dict):
        try:
            _cache_key = (round(float(t), 12), round(float(t_norm), 12), int(slot), int(row),
                          int(sequence), int(step), round(float(seed), 12), seed_text)
            _hit = _cache.get(_cache_key)
            if isinstance(_hit, dict):
                _ctx_hit = dict(_hit)
                _ctx_hit["name"] = str(name or "")
                return _ctx_hit
        except Exception:
            _cache_key = None
    canonical = {}
    try:
        canonical = dict(app._canonical_input_context()) if app is not None and hasattr(app, "_canonical_input_context") else {}
    except Exception:
        canonical = {}
    vals = []
    try:
        if seed_text.strip():
            vals = _eval_seed_python(seed_text, t_value=t, canonical_context=canonical, allow_scrape=False) or []
    except Exception:
        vals = []
    if not vals:
        try:
            vals = list(app.get_seed_values(t_value=t) or []) if app is not None and hasattr(app, "get_seed_values") else []
        except Exception:
            vals = []
    seq = [float(v) for v in vals if isinstance(v, (int, float, np.number)) and math.isfinite(float(v))]
    if not seq:
        seq = [seed]
    if _seed_script_is_coordinate(seed_text) and len(seq) >= 2:
        x, y = float(seq[0]), float(seq[1])
        z = float(seq[2]) if len(seq) >= 3 else 0.0
    else:
        try:
            x, y, z = compositional_xyz(seed, sequential_nums=seq, t=t, slot=int(slot))
        except Exception:
            x, y, z = t, 0.0, 0.0
    domain_value = 0.0
    domain_weight = 1.0
    domain_id = ""
    try:
        engine = getattr(app, "domain_eq_engine", None) if app is not None else None
        if engine is not None:
            _gc = max(1, len(getattr(app, "master_playlist_data", []) or [1])) if app is not None else 1
            domain_value = float(engine.evaluate(
                t, x=x, y=y, z=z, t_norm=float(t_norm), graph_index=int(row),
                graph_count=_gc, slot=int(slot), sequence=int(sequence), step=int(step),
                bpm=float(getattr(app, "_rt_bpm", 120.0) or 120.0) if app is not None else 120.0,
                sample_rate=float(getattr(app, "sample_rate", 44100.0) or 44100.0) if app is not None else 44100.0,
            ))
            domain_id = repr(engine.to_json())
    except Exception:
        domain_value = 0.0
    try:
        bpm = float(app.spin_bpm.value()) if hasattr(app, "spin_bpm") else float(getattr(app, "bpm", 120.0))
    except Exception:
        bpm = 120.0
    sample_rate = float(getattr(app, "sample_rate", 44100.0) or 44100.0) if app is not None else 44100.0
    ctx = build_graph_context(
        t=t, t_norm=float(t_norm), x=x, y=y, z=z, seed=seed,
        graph_index=int(row), graph_count=max(1, len(getattr(app, "master_playlist_data", []) or [1])) if app is not None else 1,
        slot=int(slot), sequence=int(sequence), step=int(step), bpm=bpm, sample_rate=sample_rate,
        domain_value=domain_value, domain_weight=domain_weight, graph_id=seed_text or seed, domain_id=domain_id,
        canonical_context=canonical, values=seq,
    )
    if isinstance(_cache, dict) and _cache_key is not None:
        try:
            if len(_cache) >= 2048:
                _cache.clear()
            _base_store = dict(ctx)
            _base_store.pop("name", None)
            _cache[_cache_key] = _base_store
        except Exception:
            pass
    ctx["name"] = str(name or "")
    return ctx


def _evaluate_app_graph_script(app, script, t_value=0.0, *, t_norm=None, slot=0, row=0, sequence=1, step=0, name="", function_names=("evaluate_wave", "global_script", "evaluate", "main")):
    """Evaluate one script against the same graph context used by all media."""
    ctx = _app_full_graph_context(app, t_value, t_norm=t_norm, slot=slot, row=row, sequence=sequence, step=step, name=name)
    extra = _seed_script_env(t_scalar=float(ctx.get("t", 0.0)), canonical_context=ctx)
    return evaluate_graph_script(script, ctx, function_names=function_names, extra_env=extra)


def goava_get_note(number_assigned, step, numbers):
    """Return the scalar note value produced by GOAVA Composer.getNote()."""
    nums = [float(x) for x in numbers if math.isfinite(float(x))]
    if not nums:
        return 0.0
    num = float(number_assigned)
    total = 0.0
    for value in nums:
        if value != 0.0:
            total += (
                1.0 + series_cos(
                    1.0 + abs((math.pi / 2.0) * num)
                    + (math.pi / 2.0) * ((abs(value) + abs(num)) * step)
                )
            ) / (len(nums) + abs(num - value))
        else:
            total += (
                1.0 + series_cos(
                    1.0 + step
                    + abs((math.pi / 2.0) * num)
                    + (math.pi / 2.0) * ((abs(value) + abs(num)) * step)
                )
            ) / (len(nums) + abs(num - value))
    return abs(float(total))

def goava_irrational_stream(t_values, numbers, base_frequency=432.0, channel=0):
    """GOAVA as an instantaneous RNG: continuous irrational sampling.

    GOAVA Composer.getNote() is already a continuous function of its `step`
    argument (a sum of cosines whose phases are driven by the seed numbers), so
    the step coordinate is naturally real-valued. Sampling that trajectory at
    every audio sample index produces a stream that is:

      (a) anchored to the unique seed — it is a function OF the seed numbers,
          not a detached hash or an unseeded draw;
      (b) unrelated to the phase-lock engine — GOAVA has its own note axis and
          never reads the phase-lock pair coupling;
      (c) irrational-sampled — the time axis is pre-scaled by a MEUM-family
          constant so the sampled trajectory is dense (an irrational rotation)
          and never repeats at integer note periods.

    That is GOAVA "disguised in the longitudinal domain" as another type of
    sound-generation function when it rides on top of the full 5-engine unison:
    it supplies instantaneous, seeded, phase-lock-free motion without ever
    re-splitting the ensemble into per-instrument identity.
    """
    tarr = np.asarray(t_values, dtype=np.float64).reshape(-1)
    nums = [float(x) for x in numbers if math.isfinite(float(x))]
    if not nums:
        return np.zeros(tarr.shape, dtype=np.float32)
    num = float(nums[int(channel) % len(nums)])
    # Continuous step coordinate. base-frequency × MEUM_INV × 0.5 holds the
    # composite pseudo-oscillator inside the audible band; the irrational
    # MEUM constant makes the rotation dense (never periodic).
    step = tarr * float(base_frequency) * MEUM_INV * 0.5
    note = None
    ref = None
    scale = 0.0
    ref_step = step + math.pi
    for value in nums:
        denom = float(len(nums) + abs(num - value))
        scale += 1.0 / denom
        if value == 0.0:
            base_ph = 1.0 + step + abs((math.pi / 2.0) * num)
        else:
            base_ph = 1.0 + abs((math.pi / 2.0) * num)
        if note is None:
            note = (1.0 + ot_cos_vec_equiv(base_ph + (math.pi / 2.0) * ((abs(value) + abs(num)) * step))) / denom
            ref = (1.0 + ot_cos_vec_equiv(base_ph + (math.pi / 2.0) * ((abs(value) + abs(num)) * ref_step))) / denom
        else:
            note = note + (1.0 + ot_cos_vec_equiv(base_ph + (math.pi / 2.0) * ((abs(value) + abs(num)) * step))) / denom
            ref = ref + (1.0 + ot_cos_vec_equiv(base_ph + (math.pi / 2.0) * ((abs(value) + abs(num)) * ref_step))) / denom
    if note is None:
        return np.zeros(tarr.shape, dtype=np.float32)
    # Closed-form, input-independent normalization: the oscillation amplitude is
    # ~ sum(1/denom) whatever the seed magnitude, so dividing by that exact
    # scale (NOT an adaptive peak-ride) makes the stream span [-1, 1] for any
    # seed list.  The final gain is a fixed MEUM-family constant.
    d = (note - ref) / scale if scale != 0.0 else np.zeros_like(note, dtype=np.float64)
    # Dual-mode scale, no soft-clip / no saturation.
    gain = (1.0 + MEUM_NORM) * 0.9
    if operator_theory_enabled():
        out = np.empty_like(d, dtype=np.float64)
        for i, v in enumerate(np.asarray(d, dtype=np.float64).ravel()):
            out.flat[i] = math_scale(v, gain)
        return out.astype(np.float32)
    return (d * gain).astype(np.float32)

# UNION_ENTROPY_2026 — the union's entropy is a fixed-point statistic, not a
# knife-edge.  The per-voice draw D below is a uniform-in-mean hash of the
# (seed, roster-slot) pair with irrational MEUM-family offsets, so its mean over
# the macro is input-invariant and sits exactly on the 0.5 fixed point REGARDLESS
# of seed or patch.  But D itself is not clamped: it still assigns every seed a
# genuinely different point on the entropy axis, so done right some seeds come
# out genuinely entropic and others genuinely ordered — while the distribution
# over seeds never moves off 0.5 while the engines are active.
ENTROPY_FIXED_POINT = 0.5
ENTROPY_FIXED_POINT_TOL = 0.10        # |mean(D) - 0.5| band for the live audit
ENTROPY_REALIZED_SPREAD_MIN = 0.45    # realized min→max range proving per-seed variety
ENTROPY_REALIZED_TOP = 0.55           # at least one voice genuinely entropic (>= this)
ENTROPY_REALIZED_BOTTOM = 0.45        # and at least one genuinely ordered (<= this)

def entropy_draw_0_1(s_abs, s_frac, s_int, vo):
    """The unison entropy draw, single source of truth.

    Mirrors the per-voice entropy coefficient in the canonical render exactly
    (0 = pure harmonic, 1 = full entropy).  Uniform-in-mean on [0,1] with an
    irrational offset lattice (MEUM_NORM / MEUM_INV / MEUM), so for ANY input the
    mean of D over the macro = 0.5 while individual seeds genuinely spread across
    the axis.  The render calls this so the audio and the live fixed-point audit
    can never drift apart.
    """
    return float(np.clip(
        (float(s_frac)
         + 0.37 * series_sin(float(s_abs) * MEUM_NORM + float(vo) * MEUM_INV)
         + 0.29 * series_cos(float(s_int) * MEUM + float(vo))) % 1.0,
        0.0, 1.0
    ))

# ============================================================================
# CANONICAL_VISUAL_2026 — instrument -> total-frame 2.5D scheme, the visual
# dual of the audio instrument pass.
#
# The SAME number of parameters the audio renderer passes to each voice is
# produced here for each instrument slot, from the SAME fixed latices (the
# fractional MEUM_POWERS_36 index, INSTRUMENT_PHASE_LOCK_48, part-cap table)
# and the SAME canonical entropy draw (entropy_draw_0_1).  Rendering all
# instrument slots through this scheme makes one total 2.5D frame — a
# per-instrument constellation like the audio per-voice mix — and with the
# 5-engine union active every slot resolves to the SAME union parameter set,
# so the frame collapses to a single organism (the visual proof of audio
# identity-cancellation).
#
# Each canonical engine drives ONE symmetric structural axis while it is
# active.  Influence is equal by construction: every channel is 0/1-weighted,
# then normalized by the active-engine count, so no engine can dominate or be
# starved and the ensemble is perfectly symmetric under engine toggling.  The
# goava channel only produces a value when GOAVA itself is on.
# ============================================================================
_VISUAL_ENGINE_CHANNELS = ("seeded", "randomizer", "phase_lock", "euclidean", "goava")

# INSTRUMENT_REPARTITION_2026_V32: the composition has one fixed 128-slot
# deterministic identity lattice. Instrument Count selects/repartitions that
# lattice; it never changes the underlying seed-derived material.
CANONICAL_MASTER_SLOTS = 128
MAX_INSTRUMENTS = 128
# GROOVEBOX_DEFAULT_48_20261102: a new project starts with 48 instruments (the count spinner's default). The
# spinner raises it up to MAX_INSTRUMENTS; the roster is no longer silently booted at the full 128.
DEFAULT_ACTIVE_INSTRUMENTS = 48

def canonical_master_slot(index: int, count: int) -> int:
    """Map a live/render index onto the fixed canonical 128-slot lattice."""
    try:
        n = max(1, int(count))
    except Exception:
        n = 1
    try:
        i = int(index)
    except Exception:
        i = 0
    i = max(0, min(n - 1, i))
    if n <= 1:
        return 0
    slot = int((i * (CANONICAL_MASTER_SLOTS - 1) + (n - 1) // 2) // (n - 1))
    return max(0, min(CANONICAL_MASTER_SLOTS - 1, slot))


