def _range_unit(value, lo, hi):
    """Map a finite scalar from [lo, hi] to [0, 1] without signal clipping."""
    v = float(value)
    lo = float(lo); hi = float(hi)
    if not (math.isfinite(v) and math.isfinite(lo) and math.isfinite(hi)):
        return 0.5
    if hi == lo:
        return 0.5
    return (v - lo) / (hi - lo)


def _sequence_units(values):
    """Normalize a numeric sequence across its actual observed range.

    This deliberately does not clip: if the caller supplies a proper range,
    every input retains its exact affine position and the extrema span 0..1.
    """
    vals = []
    for value in values or []:
        try:
            v = float(value)
            if math.isfinite(v):
                vals.append(v)
        except Exception:
            continue
    if not vals:
        return []
    lo, hi = min(vals), max(vals)
    if hi == lo:
        return [0.5] * len(vals)
    return [(float(v) - lo) / (hi - lo) if math.isfinite(float(v)) else 0.5
            for v in values]


def _full_hue(unit, base=0.0):
    """Map a normalized scalar to the complete 360° hue circle."""
    return (float(base) + 360.0 * float(unit)) % 360.0


# Make a default instance for convenience
def _default_shifts(voice_index: int, instrument_count: int) -> int:
    """Compatibility wrapper for the canonical instrument translator."""
    return int(instruments_handler(voice_index, instrument_count)["master_slot"])


def canonical_visual_instrument(slot, ctx, flags):
    """ONE fractal object type per instrument — same schema for every slot.

    Why this is the fractal we want
    -------------------------------
    Every instrument (and every visual layer that mirrors one) is the *same
    object class*: a point on the shared Meum lattice with (base_freq, ratio,
    entropy, phase, depth, hue, …).  The fractal is not "a different effect
    per instrument"; it is the *same object* sampled at every slot, so the
    ensemble is a single self-similar field.  Prevalence of which *regions*
    of that field light up is driven by sequential numeric inputs fed into
    the canonicals (seed list geometry), not by instrument count.

    Geometry hierarchy (most prevalent → most relevant):
      1. Sequential numeric inputs (seed script values over time) — primary
      2. Canonical lattice position of the slot (MEUM_POWERS_36 fold)
      3. Active engines (randomizer / phase_lock / goava / …) — tilt axes
      4. Music pitch/entropy for this slot (same numbers as the voice)
      5. Game spatial residues when the consumer is the videogame path

    ctx: seed, base, ratio, s_int, full_unison, n_inst, meum_depth.
    flags: randomizer, phase_lock, idealize_rhythm, seeded, goava.
    Returns one fractal-object dict (audio keys + 2.5D co-ordinates).
    """
    # Instrument identity is independent of live N; N is handled only by the
    # translation layer as inverse-count contribution compensation.
    n_inst = CANONICAL_MASTER_SLOTS
    i = int(slot) % CANONICAL_MASTER_SLOTS
    inst_map = instruments_handler(i, CANONICAL_MASTER_SLOTS, seed=ctx.get("seed", 0.0),
                                   sequential_nums=ctx.get("sequential_nums", ()))
    fu = bool(ctx.get("full_unison"))
    seedv = float(ctx.get("seed", 0.0))
    s_int = int(ctx.get("s_int", int(_safe_int_seed(seedv)) or 1))
    s_abs = abs(seedv)
    s_frac = s_abs - math.floor(s_abs)
    base = float(ctx.get("base", 432.0))
    ratio = float(ctx.get("ratio", 1.0))
    eng = dict(flags or {})
    levels = dict(eng.get("levels") or {})
    _lev = {
        "seeded": float(np.clip(levels.get("seeded", 1.0), 0.0, 1.0)),
        "randomizer": float(np.clip(levels.get("randomizer", 1.0), 0.0, 1.0)),
        "phase_lock": float(np.clip(levels.get("phase_lock", 1.0), 0.0, 1.0)),
        "euclidean": float(np.clip(levels.get("euclidean", 1.0), 0.0, 1.0)),
        "goava": float(np.clip(levels.get("goava", 1.0), 0.0, 1.0)),
    }
    # Keep the historical engine-count metadata alongside the newer level-
    # weighted influence sum.  MP4/carrier-video rendering reads this value
    # while constructing its first canonical visual layers.
    n5 = sum(1 for _k in _VISUAL_ENGINE_CHANNELS if eng.get(_k))
    n_eng = max(1, n5) if n5 else 6  # idle reference remains the legacy 1/6 scale
    total_level = sum(_lev[k] for k in _VISUAL_ENGINE_CHANNELS if eng.get(k))
    k5 = 1.0 / float(total_level) if total_level != 0.0 else (1.0 / 6.0)
    # Canonical slot lattice (irrational fractional index, never repeats).
    _tpos = (i * MEUM * 3.0) % 36.0
    _tlo = int(_tpos) % 36
    _thi = (_tlo + 1) % 36
    _tfr = _tpos - int(_tpos)
    _pow = (MEUM_POWERS_36[_tlo] * (1.0 - _tfr) + MEUM_POWERS_36[_thi] * _tfr)
    # Union collapses pitch/identity; otherwise the per-slot lattice drives it.
    if fu:
        bf = base
        sr = ratio
        ent = float(entropy_draw_0_1(s_abs, s_frac, s_int, 0))
        phase0 = 0.0
    else:
        bf = base * _pow
        sr = float(_seed_to_pitch_ratio(seedv, i, i))
        ent = float(entropy_draw_0_1(s_abs, s_frac, s_int, i))
        phase0 = float(INSTRUMENT_PHASE_LOCK_48[i % 48])
    # Level-weighted five-canonical visual channels.  RAND also carries the
    # captured entropy token so MP4 identity follows the same instance as audio.
    ch_rnd = (0.5 * _lev["randomizer"] if eng.get("randomizer") else 0.0) * k5
    ch_ph = (0.5 * _lev["phase_lock"] if eng.get("phase_lock") else 0.0) * k5
    ch_euc = (0.5 * _lev["euclidean"] if eng.get("euclidean") else 0.0) * k5
    ch_seed = (0.5 * _lev["seeded"] if eng.get("seeded") else 0.0) * k5
    ch_goa = (0.5 * _lev["goava"] if eng.get("goava") else 0.0) * k5
    if eng.get("randomizer"):
        _rn = int(eng.get("rand_instance_seed", 0) or 0)
        _ru = deterministic_u64("visual-rand-level", _rn, i) / float(2**64)
        ch_rnd *= 0.75 + 0.50 * _ru
    mod = {
        "phase_shift": (0.0 if fu else float(math.tau * ((i * MEUM_NORM * PHI_INV) % 1.0))),
        "mod_rate": 0.78 + 0.48 * ent,
        "fm_depth": float(np.clip(0.22 + 0.38 * (ch_rnd - ch_ph), -0.95, 0.95)),
        "fm_rate": 0.5 + 2.0 * _pow,
        "pm_depth": float(math.pi * float(np.clip(0.18 + 0.55 * (ch_ph - ch_seed), -1.0, 1.0))),
        "pm_rate": 0.5 + 2.0 * ((i * MEUM) % 1.0),
        "am_depth": float(np.clip(MEUM_NORM + 0.5 * ch_euc, 0.0, 1.0)),
        "am_rate": 0.5 + 2.0 * ((i * PHI * MEUM_NORM) % 1.0),
        "meum_depth": float(ctx.get("meum_depth", 1.0)),
    }
    depth = 1.35 + 0.18 * _pow + 2.2 * (ch_seed - 0.25 * k5)
    yaw = float(math.fmod(i * PHI * MEUM_NORM + PHI_INV * (ch_ph - ch_rnd), math.tau))
    pitch = 0.12 * series_sin(i * MEUM + ch_euc * 1.3)
    roll = 0.09 * series_cos(i * MEUM_INV + ch_ph)
    pack = PHI_INV + 0.60 * _pow * (1.0 + MEUM_TWO_MINUS * (ch_seed - 0.5 * k5))
    max_partial = int(INSTRUMENT_PARTIAL_CAP_48[i % 48])
    verts = int(4 + (max_partial % 6) + int(ch_euc * 6.0))
    hue = float(math.fmod(360.0 * inst_map["identity"] + i * 7.0 + ch_goa * 90.0, 360.0))
    # HARMONIC_CANCELLATION_ALIGNMENT_2026: color shading, translucency and
    # 2.5D depth follow the harmonic cancellation envelope of the SOUND.  Under
    # the union every voice shares identity + phase carry (max reinforcement),
    # so the frame is one opaque foreground organism; independent voices recede
    # and grow translucent in proportion to how far their phase locus sits from
    # the shared meum axis — the same relation the mix's phase cancellation has.
    _ax = math.fmod(float(phase0) * MEUM_NORM + i * MEUM_INV, 1.0)
    if fu:
        conson = 1.0
    else:
        conson = 0.5 + 0.5 * series_cos(_ax * math.tau)
    depth = 0.96 + (math.e - 2.0) * (1.0 - conson) + 0.18 * _pow
    # Calculated shading: brightness tracks the same meum phase envelope the
    # audio pass rings against, dimmed proportionally as a voice recedes.
    shade = float(np.clip(0.35 + 0.55 * (0.5 + 0.5 * series_sin(_ax * math.tau)) * (0.5 + 0.5 * conson),
                          0.05, 0.98))
    life = 0.30 + 0.70 * conson * (0.25 + 0.75 * ent)
    rad = (2.0 - depth) * (0.30 + 0.45 * pack)
    return {
        "i": i, "n_inst": n_inst, "master_slot": int(inst_map["master_slot"]), "compensation": float(inst_map["compensation"]),
        "base_freq": bf, "ratio": sr, "s_int": s_int, "entropy": ent,
        "phase0": phase0, "mod": mod, "max_partial": max_partial,
        "spread_axis": ch_rnd, "twist_axis": ch_ph, "structure_axis": ch_euc,
        "scale_axis": ch_seed, "hue_axis": ch_goa, "engines": n_eng,
        "depth": depth, "yaw": yaw, "pitch": pitch, "roll": roll,
        "pack": pack, "verts": verts, "hue": hue, "life": life, "shade": shade,
        "x": float(series_cos(yaw) * rad * series_cos(pitch)),
        "y": float(series_sin(pitch) * rad * (math.e - 2.0)),
        "z": float(depth * (PHI_INV + (2.0 - PHI) * series_sin(roll))),
    }


def goava_frequency(number_assigned, step, numbers, base_frequency=432.0):
    """Map GOAVA's Java sequence scalar to a frequency — no cutoffs or clips.

    Upward-tendency fix: getNote() is non-negative by construction (every
    term is (1+cos)/positive), which forced every GOAVA pitch above the base
    (~+14..+28 semitones mean across seeds, measured).  The scalar is now
    DC-centered against the set mean, so pitches land symmetrically above and
    below the base — same seed still maps to the same centered trajectory
    (deterministic), the projection (per-note delta) is unchanged, only the
    constant offset that created the bias is removed.

    GOAVA policy: no audible_hz / Nyquist / octave clamps on the frequency
    value itself. Callers that need a safe oscillator rate may still apply
    their own limits; GOAVA reports the true mapped frequency.
    """
    raw = goava_get_note(number_assigned, step, numbers)
    # GOAVA musical output is intentionally a single sine at a base-frequency
    # ratio.  Positive/negative raw values select above/below the base; the
    # raw Java-derived scalar remains available as metadata.
    center = 0.0
    try:
        _scale = [goava_get_note(n, i, numbers) for i, n in enumerate(numbers)]
        if _scale:
            center = sum(_scale) / len(_scale) if _scale else 0.0
    except Exception:
        center = 0.0
    raw_c = raw - center
    # Unclipped: centered raw drives the ratio freely (no ±octave or audible_hz).
    ratio = 2.0 ** float(raw_c * 2.25)
    if not math.isfinite(ratio) or ratio <= 0.0:
        ratio = 1.0
    freq = float(base_frequency) * ratio
    if not math.isfinite(freq):
        freq = float(base_frequency)
    return float(freq), float(raw_c)


# ---------------------------------------------------------------------------
# Number-theoretic lattices for the master composer (canonical-friendly)
# ---------------------------------------------------------------------------
def _nt_is_prime(n: int) -> bool:
    n = int(n)
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True


def _nt_primes(limit: int):
    limit = max(2, int(limit))
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i :: i] = [False] * len(sieve[i * i :: i])
    return [i for i, v in enumerate(sieve) if v]


def _nt_quadratic_residues(mod: int):
    mod = max(2, int(mod))
    return sorted({(i * i) % mod for i in range(mod)})


def _nt_euler_totient(n: int) -> int:
    n = int(n)
    if n <= 0:
        return 0
    result, i = n, 2
    while i * i <= n:
        if n % i == 0:
            while n % i == 0:
                n //= i
            result -= result // i
        i += 1
    if n > 1:
        result -= result // n
    return int(result)


def _nt_mobius(n: int) -> int:
    n = int(n)
    if n <= 0:
        return 0
    if n == 1:
        return 1
    primes, x, sign = 0, n, 1
    i = 2
    while i * i <= x:
        if x % i == 0:
            cnt = 0
            while x % i == 0:
                x //= i
                cnt += 1
            if cnt > 1:
                return 0
            primes += 1
            sign = -sign
        i += 1
    if x > 1:
        primes += 1
        sign = -sign
    return sign


def _nt_farey_neighbors(n: int):
    """Farey sequence of order n as fractions a/b in (0,1]."""
    n = max(1, min(64, int(n)))
    seq = [(0, 1), (1, n)]
    # standard adjacent mediants generation
    a, b, c, d = 0, 1, 1, n
    out = [(0, 1)]
    while c <= n:
        k = (n + b) // d
        a, b, c, d = c, d, k * c - a, k * d - b
        out.append((a, b))
    return out


def _nt_stern_brocot_depth(depth: int):
    """Left-to-right Stern–Brocot levels as ratio list (depth small)."""
    depth = max(1, min(8, int(depth)))
    layer = [(0, 1), (1, 1)]
    for _ in range(depth - 1):
        nxt = []
        for i in range(len(layer) - 1):
            a, b = layer[i]
            c, d = layer[i + 1]
            nxt.append((a, b))
            nxt.append((a + c, b + d))
        nxt.append(layer[-1])
        layer = nxt
    return layer


def _nt_step_mask(length: int, mode: str, modulus: int, depth: int = 4):
    """Boolean step mask of `length` from a number-theoretic rule."""
    length = max(1, int(length))
    mod = max(2, int(modulus))
    mode = (mode or "primes").strip().lower()
    mask = [False] * length
    if mode in ("primes", "prime"):
        primes = set(_nt_primes(max(mod * 4, length * 2)))
        for i in range(length):
            mask[i] = ((i % mod) in primes) or _nt_is_prime((i % mod) + 2)
    elif mode in ("quadratic", "qr", "residues"):
        qr = set(_nt_quadratic_residues(mod))
        for i in range(length):
            mask[i] = (i % mod) in qr
    elif mode in ("totient", "phi"):
        # fire when gcd(i, mod) == 1 (units group)
        for i in range(length):
            mask[i] = math.gcd(i % mod, mod) == 1
    elif mode in ("mobius", "mu"):
        for i in range(length):
            mask[i] = _nt_mobius((i % mod) + 1) != 0
    elif mode in ("farey",):
        farey = _nt_farey_neighbors(max(2, depth))
        idxs = {int(round((a / b) * (length - 1))) for a, b in farey if b}
        for i in idxs:
            if 0 <= i < length:
                mask[i] = True
    elif mode in ("stern", "brocot", "stern-brocot"):
        sb = _nt_stern_brocot_depth(depth)
        idxs = {int(round((a / b) * (length - 1))) for a, b in sb if b}
        for i in idxs:
            if 0 <= i < length:
                mask[i] = True
    else:
        for i in range(length):
            mask[i] = (i % mod) == 0
    if not any(mask):
        mask[0] = True
    return mask



# GROOVEBOX_R23R_SEED_SYNTAX_COVERAGE_20261101 ---------------------------------
# Random Seed rotates through every seed-syntax family and every bindable
# workspace variable (shuffled cycles), so repeated presses are guaranteed to
# exercise all of them. Each candidate is validated against a probe context in
# which every workspace-bound name has a live-like value.
_SEED_CONSTANT_NAMES = {"MEUM", "MEUM_INV", "MEUM_LOG2", "MEUM_NORM", "MEUM_SQ", "PHI", "SILVER", "SQRT2", "SQRT3",
                        "pi", "e", "tau", "True", "False", "None", "AUTHOR_NUMBER_SCHEME", "t", "graph", "graph_vector"}
_SEED_COVERAGE = {"features": [], "vars": []}


def seed_workspace_variables(canonical_context=None):
    """Every bindable workspace live variable a seed can read (env-derived, plus live context keys)."""
    try:
        env = _seed_script_env(0.0, canonical_context if isinstance(canonical_context, dict) else None)
    except Exception:
        env = {}
    names = {k for k, v in env.items()
             if not callable(v) and not k.startswith("_") and k not in _SEED_CONSTANT_NAMES
             and isinstance(v, (int, float, bool)) and k.isidentifier()}
    if isinstance(canonical_context, dict):
        names |= {k for k, v in canonical_context.items() if isinstance(k, str) and k.isidentifier()
                  and isinstance(v, (int, float, bool)) and not k.startswith("_")}
    return sorted(names)


def _seed_probe_context(names):
    """Live-like values for every workspace name (validation only)."""
    ctx = {}
    for i, n in enumerate(names):
        ctx[n] = 0.25 + 0.5 * ((i * 0.6180339887) % 1.0)
    for n, v in (("bpm", 120.0), ("sample_rate", 48000.0), ("sequence_index", 2), ("step_index", 5),
                 ("eq_low_hz", 40.0), ("eq_high_hz", 16000.0), ("eq_poles", 8.0), ("cell_rule", 30.0)):
        if n in ctx or n in names:
            ctx[n] = v
    return ctx


def _seed_next(kind, pool, rng, k=1):
    q = _SEED_COVERAGE[kind]
    out = []
    while len(out) < k:
        if not q:
            q.extend(pool); rng.shuffle(q)
        out.append(q.pop())
    return out


def generate_random_seed_script(rng=None, canonical_context=None):
    """Generate a structured, usually long (up to 256 lines) seed program.

    Mixes random structured blocks of assignments, conditionals, loops (bounded),
    function defs, and time-varying expressions. Every candidate is validated
    with the real evaluator; regenerates until it yields finite, time-varying values.
    """
    if rng is None or not hasattr(rng, "choice"):
        rng = random.Random()
    # GROOVEBOX_R32_SEED_GENERATOR_20261109: grammar-driven programs over the whole
    # language, validated by the real evaluator at several instants.  Only limits:
    # 256 lines / 32768 characters.  Never collapses to a one-liner on failure.
    ctx = canonical_context if isinstance(canonical_context, dict) else None
    try:
        import seed_gen
        ws = seed_workspace_variables(ctx)
        probe = dict(_seed_probe_context(ws))
        if ctx:
            probe.update({k: v for k, v in ctx.items() if isinstance(v, (int, float, bool))})

        def _env(tt):
            return _seed_script_env(t_scalar=float(tt), canonical_context=probe)

        return seed_gen.generate(_env, ws, rng=rng)
    except Exception as exc:
        print(f"[Seed] grammar generator unavailable ({exc}); using the coverage generator")
    if rng.random() < 0.75:
        return _generate_long_structured_seed_program(rng, canonical_context)
    return _generate_coverage_seed_script(rng, canonical_context)


def _generate_long_structured_seed_program(rng, canonical_context=None):
    """Build a multi-line program with random length up to 256 lines, usually long."""
    target_lines = rng.randint(48, 256)
    lines = ["# Generated structured seed program — evaluated as real Python"]
    # Always include some time dependence
    lines.append("t_norm = t / (1.0 + abs(t))")
    lines.append("phase = t * MEUM")
    # Random number of blocks
    n_blocks = max(4, target_lines // 12)
    for b in range(n_blocks):
        block = _random_seed_block(rng, b)
        lines.extend(block)
        if len(lines) >= target_lines:
            break
    # Ensure a final return that is time-varying and finite
    lines.append("result = sin(phase) * 0.5 + isn(t_norm * PHI) * 0.3 + 0.2 * tanh(graph_energy)")
    # R32: no isfinite guard in the script — the evaluator drops non-finite values itself.
    lines.append("return result")
    # Trim if over
    if len(lines) > 256:
        lines = lines[:250] + lines[-6:]
    script = "\n".join(lines)
    # Validate; if bad, fall back to a simpler long one
    try:
        vals = _eval_seed_python(script, t_value=0.5, allow_scrape=False)
        if vals:
            v2 = evaluate_seed_expression_at_time(script, 1.7)
            if abs(v2) > 1e-6:
                return script
    except Exception:
        pass
    # Fallback structured but shorter
    return _generate_coverage_seed_script(rng, canonical_context)


def _random_seed_block(rng, idx):
    """Return a list of lines forming one structured block."""
    kind = rng.choice(["assign", "if", "func", "list", "math"])
    lines = []
    if kind == "assign":
        name = f"v{idx}"
        expr = rng.choice([
            f"sin(t * {rng.uniform(0.5, 8):.3f})",
            f"isn(phase + {rng.uniform(-2, 2):.3f})",
            f"tanh(t_norm * PHI)",
            f"abs(cos(t * MEUM))",
        ])
        lines.append(f"{name} = {expr}")
    elif kind == "if":
        lines.append(f"if t > {rng.uniform(0, 4):.2f}:")
        lines.append(f"    tmp = {rng.choice(['sin', 'cos', 'tanh'])}(t * {rng.uniform(1, 5):.2f})")
        lines.append("else:")
        lines.append(f"    tmp = {rng.choice(['isn', 'ics'])}(t * {rng.uniform(0.5, 3):.2f})")
        lines.append(f"v{idx} = tmp")
    elif kind == "func":
        lines.append(f"def f{idx}(x):")
        lines.append(f"    return {rng.choice(['sin', 'tanh', 'isn'])}(x * {rng.uniform(0.5, 3):.2f}) * {rng.uniform(0.2, 1.5):.2f}")
        lines.append(f"v{idx} = f{idx}(t)")
    elif kind == "list":
        lines.append(f"vals{idx} = [{rng.uniform(0.1, 2):.3f} * sin(t), {rng.uniform(0.1, 2):.3f} * cos(phase)]")
        lines.append(f"v{idx} = vals{idx}[int(abs(t)) % 2]")
    else:
        lines.append(f"v{idx} = P(isn(t), ics(t)) * {rng.uniform(0.5, 2):.2f}")
    return lines



def _generate_coverage_seed_script(rng, canonical_context=None):
    """One syntax family (rotating) woven with 3-5 workspace variables (rotating)."""
    ws = seed_workspace_variables(canonical_context)
    probe = dict(_seed_probe_context(ws))
    if isinstance(canonical_context, dict):
        probe.update({k: v for k, v in canonical_context.items() if isinstance(v, (int, float, bool))})
    families = ["number", "list", "if_elif", "ternary", "assign_return", "comment", "parametric_xyz", "polar_rt",
                "polar_fn", "cartesian_fn", "spherical_fn", "cylindrical_fn", "ped", "tensor", "choose", "clamp_lerp",
                "isn_family", "graph_attr", "graph_vector", "logic", "generator_sum", "minmax_math", "ot_math", "walrus"]
    for _attempt in range(60):
        fam = _seed_next("features", families, rng)[0]
        vs = _seed_next("vars", ws or ["graph_x"], rng, k=rng.randint(3, 5))
        a = round(rng.uniform(0.25, 4.0), 3); b = round(rng.uniform(0.5, 6.0), 3)
        n1, n2, n3 = rng.randint(32, 640), rng.randint(48, 900), rng.randint(16, 400)
        k1, k2 = round(rng.uniform(0.05, 0.6), 3), round(rng.uniform(4.0, 60.0), 2)
        W = " + ".join(f"{round(rng.uniform(0.2, 3.0), 3)} * {v}" for v in vs)       # workspace term
        Wf = f"(1 + {k1} * tanh({W}))"
        lines = {
            "number": f"{n1} * {Wf}",
            "list": f"{n1} * {Wf}, {n2} + {k2} * {vs[0]}, {n3} * (1 + {k1} * sin(t * {a})), {n1 // 2} + {vs[1]}",
            "if_elif": f"if({vs[0]} > {round(rng.uniform(0.1, 0.9), 3)}) {n1} * {Wf} elif(isn(t * {a}) > 0) {n2} + {k2} * {vs[1]} elif {n3}",
            "ternary": f"({n1} if {vs[0]} >= {vs[1]} else {n2}) * {Wf}",
            "assign_return": f"base = {n1} * {Wf}\nwob = {k2} * sin(t * {a} + {vs[0]})\nreturn base + wob",
            "comment": f"# workspace-bound: {', '.join(vs)}\n{n1} * {Wf} + {k2} * ics(t * {b})",
            "parametric_xyz": f"x(t) = {n1} * sin(t * {a}) * {Wf}\ny(t) = {n2} * cos(t * {b}) + {k2} * {vs[0]}\nz(t) = {n3} * sin(t_norm * tau + {vs[1]})",
            "polar_rt": f"r(t) = {n1} * {Wf}\ntheta(t) = MEUM * t * {a} + {vs[0]}",
            "polar_fn": f"polar({n1} * {Wf}, MEUM * t * {a})",
            "cartesian_fn": f"cartesian({n1} * sin(t * {a}) + {vs[0]}, {n2} * cos(t * {b}) + {vs[1]}, {n3} * {Wf})",
            "spherical_fn": f"spherical({n1} * {Wf}, MEUM * t, 0.5 * pi + 0.25 * sin(t * {a} + {vs[0]}))",
            "cylindrical_fn": f"cylindrical({n1} * {Wf}, PHI * t * {a}, {n3} * {vs[0]})",
            "ped": f"P(isn(t * {a}), ics(t * {b})) * {n1} * {Wf} + E(sin(t), MEUM) * {n2} + D(t, PHI) * {k2} * {vs[0]}",
            "tensor": f"tensor_z(sin(t * {a}), MEUM) * {n1} * {Wf} + tensor_rel(cos(t), {vs[0]}) * {n2}",
            "choose": f"choose({n1}, {n2}, {n3}, {n1 + n3}, floor(abs(t * {a}) + {vs[0]} * 4)) * {Wf}",
            "clamp_lerp": f"clamp(lerp({n1}, {n2}, 0.5 + 0.5 * isn(t * {a})) * {Wf}, {min(n1, n2) // 2}, {max(n1, n2) * 2})",
            "isn_family": f"({n1} * isx(t * {a}) + {n2} * isy(t * {b}) + {k2} * arcisn(clamp({vs[0]}, -1, 1))) * {Wf}",
            "graph_attr": f"{n1} * (1 + {k1} * tanh(graph.x + graph.energy * graph.phase)) * {Wf}",
            "graph_vector": f"{n1} * (1 + {k1} * tanh(graph_vector[0] - graph_vector[1] + graph_vector[2])) * {Wf}",
            "logic": f"({n1} if (sin(t * {a}) > 0 and {vs[0]} >= 0) or not ({vs[1]} > 1) else {n2}) * {Wf}",
            "generator_sum": f"sum(isn(t * {a} * k) / k for k in range(1, 5)) * {n1} * {Wf} + {n2}",
            "minmax_math": f"max({n3}, min({n2}, {n1} * {Wf} + {k2} * atan2({vs[0]}, 1 + abs({vs[1]})))) + (1 if sin(t) >= 0 else -1) * pow(abs({vs[0]}) + 1, 0.5)",
            "ot_math": f"math_mul({n1}, {Wf}) + ot_equiv_sin(t * {a}) * {n2} + hypot({vs[0]}, {vs[1]}) * {k2}",
            "walrus": f"(g := {n1} * {Wf}) + g * {k1} * sin(t * {a})",
        }
        cand = lines[fam]
        try:
            ok = True
            vals = parse_seed_numeric_list(cand, t_value=0.0, canonical_context=probe, allow_scrape=False)
            if not vals:          # the evaluator already returns finite values only
                ok = False
            for tt in (0.5, 1.25, math.pi):
                if not ok:
                    break
                ok = bool(parse_seed_numeric_list(cand, t_value=tt, canonical_context=probe, allow_scrape=False))
            if ok:
                return cand
        except Exception:
            pass
        # family/variable combination did not validate: give it back for a later press
        _SEED_COVERAGE["features"].insert(0, fam)
        _SEED_COVERAGE["vars"][0:0] = vs
    return f"P(isn(t), ics(t)) * {rng.randint(32, 400)} * (1 + 0.2 * tanh(graph_energy + step_index))"



def instrument_script_is_stock(text):
    """True when a per-instrument script is engine-authored stock scaffolding.

    GROOVEBOX_R23R_SEED_ENGINE_INVARIANCE_20261031: stock workspace/resonance/
    random full-graph scripts are deterministic functions of (seed, voice
    identity), so their roster cardinality must never enter composition
    fingerprints (game/video identity is count-invariant by contract). Only
    user-authored scripts carry authored scripting information. The same
    predicate the stock-rewrite sites use, centralized.
    """
    t = str(text or "").strip()
    return (
        not t
        or t.startswith("# Script workspace for")
        or "Seeded Geometric Resonance Script" in t
        or "Random full-graph Instrument Script" in t
    )


def generate_random_instrument_graph_script(name="Instrument", seed=1.0, slot=0, rng=None):
    """Author a complex but bounded Instrument Script over the full graph context."""
    if rng is None:
        rng = random.Random((_safe_int_seed(seed) ^ (int(slot) * 0x9E3779B1)) & 0xFFFFFFFF)
    a = round(rng.uniform(0.5, 6.0), 4)
    b = round(rng.uniform(0.5, 5.0), 4)
    c = round(rng.uniform(0.05, 0.35), 4)
    mix = round(rng.uniform(0.35, 0.85), 4)
    family = rng.randrange(4)
    if family == 0:
        body = (
            f"    spatial = sin((x + {c}*graph_z) * MEUM * {a}) * cos((y - {c}*graph_x) * PHI * {b})\n"
            f"    temporal = isn(graph_phase + t_norm * tau)\n"
            f"    wave = spatial * ({mix} + {round(1-mix,4)} * temporal)\n"
        )
    elif family == 1:
        body = (
            f"    radial = ics(graph_radius * {a} + t * MEUM)\n"
            f"    angular = sin(graph_angle * {b} + graph_phase)\n"
            f"    wave = {mix} * radial + {round(1-mix,4)} * angular\n"
        )
    elif family == 2:
        body = (
            f"    field = sin((graph_x + graph_y) * {a} + t) * cos((graph_z - graph_x) * {b} - t)\n"
            f"    wave = field * (0.5 + 0.5 * graph_energy) + domain_value * {c}\n"
        )
    else:
        body = (
            f"    uvw = (graph_u - graph_v + graph_w) * {a}\n"
            f"    wave = isn(uvw + graph_phase) * {mix} + ics(t * {b}) * {round(1-mix,4)}\n"
        )
    return (
        f"# Random full-graph Instrument Script · {name}\n"
        f"# Inputs: t,t_norm,x,y,z,seed,seed_w,graph_*,domain_value\n"
        f"def evaluate_wave(x, y, z, t=0.0, t_norm=0.0, graph=None):\n"
        + body
        + f"    return {{'wave': wave, 'amp': 0.55 + 0.45*graph_u, 'pitch': 1.0 + {c}*graph_curvature, 'pan': 2.0*graph_v-1.0, 'opacity': 0.5+0.5*graph_energy, 'scale': 0.75+0.5*graph_w}}"
    )

# GROOVEBOX_R23R_SEMITONE_UNIT_20261103: ONE semitone is the project-wide pitch
# unit, measured against the project base unit frequency (default 432 Hz, the
# Base Frequency control): a step of n semitones multiplies the base by
# 2**(n/12). Every bend / transpose / Mod pitch uses this.
PROJECT_BASE_UNIT_HZ = 432.0
def project_semitone_ratio(n):
    try:
        n = float(n)
    except Exception:
        return 1.0
    if not math.isfinite(n):
        return 1.0
    return float(2.0 ** (n / 12.0))


def project_semitone_hz(base_hz, n):
    """Frequency n project semitones away from base_hz (None → 432 Hz unit)."""
    try:
        b = float(base_hz) if base_hz is not None else PROJECT_BASE_UNIT_HZ
    except Exception:
        b = PROJECT_BASE_UNIT_HZ
    if not math.isfinite(b) or b <= 0.0:
        b = PROJECT_BASE_UNIT_HZ
    return b * project_semitone_ratio(n)


def generate_random_param_graph_script(seed=0.0, pair_signature=0, generation=0):
    """Author the RAND PARAM macro as a full-graph program, not a scalar LFO.

    The generated source is saved with the project so realtime and offline
    playback remain deterministic after the random authoring event.
    """
    rr = random.Random(_safe_int_seed(f"rand-param|{seed}|{pair_signature}|{generation}"))
    a = round(rr.uniform(0.35, 4.75), 5)
    b = round(rr.uniform(0.5, 6.5), 5)
    c = round(rr.uniform(0.08, 0.42), 5)
    m = round(rr.uniform(0.25, 0.78), 5)
    return (
        "# RAND PARAM full-graph performance script\n"
        "# Authored once on engagement; evaluated outside the realtime audio callback.\n"
        "def global_script(t, name, i, graph=None):\n"
        f"    radial = isn(graph_radius * MEUM * {a} + graph_phase)\n"
        f"    spatial = cos((graph_x-graph_y+graph_z) * PHI * {b} + t_norm*tau)\n"
        f"    field = {m}*radial + {round(1.0-m,5)}*spatial + {c}*domain_value\n"
        "    # GROOVEBOX_R23R_BOOST_BEATS_V2_20261103: follow the modern instrument voice —\n"
        "    # vector XYZ/drive, wavetable phase/twist/fold, ball physics, cellular rule, sidechain.\n"
        f"    voice = tanh(vector_x*{round(rr.uniform(0.2,1.2),4)} + vector_y*{round(rr.uniform(0.2,1.2),4)} + vector_z*{round(rr.uniform(0.1,0.8),4)})"
        f" + {round(rr.uniform(0.1,0.5),4)}*sin(wavetable_phase*tau + wavetable_twist) + {round(rr.uniform(0.05,0.3),4)}*wavetable_fold\n"
        f"    motion = tanh(ball_vx*ball_vy + ball_gravity*{round(rr.uniform(0.05,0.4),4)}) + {round(rr.uniform(0.01,0.1),4)}*((cell_rule % 8) / 8.0)\n"
        f"    field = field + {round(rr.uniform(0.1,0.35),4)}*voice + {round(rr.uniform(0.05,0.25),4)}*motion\n"
        f"    return {{'drive': field*(1.0+{round(rr.uniform(0.0,0.3),4)}*vector_drive), 'wave': field, 'amp': (0.70+0.30*graph_u)*(1.0-0.25*sidechain_depth), 'pitch': 1.0+{c}*graph_curvature+{round(rr.uniform(0.0,0.05),4)}*wavetable_curvature, 'pan': 2*graph_v-1, 'rotation': graph_angle, 'opacity': 0.45+0.55*graph_energy, 'speed': 0.8+0.4*graph_w, 'world_z': graph_z}}"
    )

# GROOVEBOX_GLOBAL_ALGO_KINDS_20261102: besides Script / Domain / Wire the Global Play Patcher
# carries Synth, Mod, Geometric and Sequencer algos. Each is a graph script returning a scalar
# (or wave/drive); it can only scale values the project already holds (synth panel values,
# modulation depth, the four geometric instances, sequence values). It never adds notes, steps,
# automation points or audio effects.
GLOBAL_ALGO_EXTRA_KINDS = ("synth", "mod", "geometric", "sequencer")
GLOBAL_ALGO_EXTRA_LABELS = {"synth": "Synth Algo", "mod": "Mod Algo", "geometric": "Geometric Algo", "sequencer": "Sequencer Algo"}


def global_algo_neutral_script(kind):
    return f"# Global {kind} algo\ndef global_script(t, name, i):\n    return 0.0\n"


def global_algo_default_params():
    p = {"mix": 0.35, "enable_script": True, "enable_domain": True, "enable_wire": True,
         "script_amount": 1.0, "domain_amount": 1.0, "wire_amount": 1.0}
    for k in GLOBAL_ALGO_EXTRA_KINDS:
        p["enable_" + k] = True
        p[k + "_amount"] = 1.0
    return p


def global_algo_default_state():
    st = {"script": global_algo_neutral_script("script"), "domain": 'equation = "sin(t * MEUM)"\n',
          "wire": [], "params": global_algo_default_params(), "apply_enabled": False,
          "user_data": True, "canonical_superwrite": False}
    for k in GLOBAL_ALGO_EXTRA_KINDS:
        st[k] = global_algo_neutral_script(k)
    return st


def global_algo_fill_missing(state):
    """Old projects: add the new kinds without touching anything already authored."""
    if not isinstance(state, dict):
        return state
    params = state.get("params")
    if not isinstance(params, dict):
        params = state["params"] = {}
    for k, v in global_algo_default_params().items():
        params.setdefault(k, v)
    for k in GLOBAL_ALGO_EXTRA_KINDS:
        if not isinstance(state.get(k), str):
            state[k] = global_algo_neutral_script(k)
    return state


def generate_random_global_play_algo(rng=None):
    """Deterministic-vocabulary random state for GLOBAL PLAY PATCHER.

    Returns a dict with script, domain, wire list, and params suitable for
    writing into global_algo_state and applying to the project. Uses the same
    Meum / PED / domain families as generate_random_seed_script so seed and
    global-play randomization stay non-redundant but mathematically aligned.
    """
    if rng is None:
        rng = random
    a = round(rng.uniform(0.5, 8.0), 3)
    b = round(rng.uniform(0.25, 4.0), 3)
    mix = round(rng.uniform(MEUM_MINUS_1, 0.85), 3)
    sa = round(rng.uniform(0.40, 1.0), 3)
    da = round(rng.uniform(0.40, 1.0), 3)
    wa = round(rng.uniform(0.25, 1.0), 3)
    script_pool = [
        f"# Global graph script algo\ndef global_script(t, name, i, graph=None):\n    spatial = sin(graph_x * MEUM * {a} + graph_y * PHI)\n    temporal = cos(graph_phase + t * {b})\n    return {{'wave': spatial * {mix} + temporal * {round(1-mix,3)}, 'amp': 0.75 + 0.25 * graph_u, 'pan': 2*graph_v-1}}\n",
        f"# Global graph script algo\ndef global_script(t, name, i, graph=None):\n    v = isn(graph_radius * MEUM + t * {a}) + ics(graph_angle * PHI + t_norm * {b})\n    return {{'scalar': v * {mix}, 'pitch': 1.0 + 0.125 * graph_curvature, 'drive': graph_energy}}\n",
        f"# Global graph script algo\ndef global_script(t, name, i, graph=None):\n    xyz = graph_vector\n    field = MEUM_NORM * sin(xyz[0] * {a} + t) + (1-MEUM_NORM) * cos(xyz[1] * {b} - t)\n    return {{'wave': field, 'x': xyz[0], 'y': xyz[1], 'z': xyz[2], 'opacity': 0.5 + 0.5*graph_energy}}\n",
        f"# Global graph script algo\ndef global_script(t, name, i, graph=None):\n    if graph_energy >= graph_curvature:\n        return {{'scalar': {mix} * cos(graph_phase * {a}), 'scale': 1.0 + 0.2*graph_u}}\n    return {{'scalar': {round(1-mix,3)} * sin((domain_value + t) * {b}), 'rotation': graph_angle}}\n",
        f"# Global graph script algo\ndef global_script(t, name, i, graph=None):\n    v = isn(sin((graph_x+graph_z) * MEUM * {a}) * cos((graph_y+t) * PHI * {b}))\n    return {{'wave': v * {mix}, 'speed': 0.75 + 0.5*graph_w, 'world_z': graph_z}}\n",
    ]
    domain_pool = [
        f"sin(t * MEUM) * {mix} + cos(t * PHI) * {round(1 - mix, 3)}",
        f"MEUM_NORM * sin(t * {a}) + (1 - MEUM_NORM) * cos(t * {b})",
        f"isn(sin(t * MEUM * {a})) * cos(t * PHI)",
        f"log2(abs(sin(t * MEUM)) + 1) * {a} + sqrt(abs(cos(t))) * {b}",
        f"sin(t * MEUM * {a}) * cos(t * {b}) + MEUM_INV * sin(t * PHI)",
        f"sin(t * MEUM) * {a} * cos(t * PHI * {b})",
        f"sin(graph_x * MEUM + t * {a}) * cos(graph_y * PHI - t * {b}) + 0.25 * graph_z",
        f"(graph_energy - graph_curvature) * {mix} + isn(graph_phase + t) * {round(1-mix,3)}",
        f"(graph_u + graph_v + graph_w) / 3.0 + domain_value * MEUM_NORM",
    ]
    detectors = ("phase", "energy", "spectrum", "goava", "euclidean", "seed", "bpm", "pair")
    targets = ("master_mix", "fractallizer", "eqr", "pkp", "ensemble", "scenograph", "domain", "unison")
    n_wires = rng.randint(1, 4)
    wires = []
    used = set()
    for _ in range(n_wires):
        src = rng.choice(detectors)
        dst = rng.choice(targets)
        key = (src, dst)
        if key in used:
            continue
        used.add(key)
        wires.append({
            "source": src,
            "target": dst,
            "amount": round(rng.uniform(0.15, 0.95), 3),
        })
    extra_pool = {
        "synth": [
            f"# Global synth algo\ndef global_script(t, name, i, graph=None):\n    return {{'scalar': sin(graph_phase * MEUM * {a}) * cos(t * PHI * {b})}}\n",
            f"# Global synth algo\ndef global_script(t, name, i, graph=None):\n    return {{'scalar': isn(graph_energy * {a} + t) * MEUM_NORM}}\n",
        ],
        "mod": [
            f"# Global mod algo\ndef global_script(t, name, i, graph=None):\n    return {{'scalar': cos(graph_curvature * {a} + t * MEUM) * {mix}}}\n",
            f"# Global mod algo\ndef global_script(t, name, i, graph=None):\n    return {{'scalar': sin(t * PHI * {b}) * (graph_energy - graph_curvature)}}\n",
        ],
        "geometric": [
            f"# Global geometric algo\ndef global_script(t, name, i, graph=None):\n    return {{'scalar': sin(graph_x * MEUM * {a} + graph_y * PHI) * cos(graph_z + t * {b})}}\n",
            f"# Global geometric algo\ndef global_script(t, name, i, graph=None):\n    return {{'scalar': isn(graph_radius * {a} + graph_angle * {b}) * MEUM_NORM}}\n",
        ],
        "sequencer": [
            f"# Global sequencer algo\ndef global_script(t, name, i, graph=None):\n    return {{'scalar': sin((i + 1) * MEUM * {a} + t) * {mix}}}\n",
            f"# Global sequencer algo\ndef global_script(t, name, i, graph=None):\n    return {{'scalar': cos(graph_phase * PHI * {b} + i) * MEUM_NORM}}\n",
        ],
    }
    params = {
        "mix": mix,
        "enable_script": True,
        "enable_domain": True,
        "enable_wire": bool(wires),
        "script_amount": sa,
        "domain_amount": da,
        "wire_amount": wa,
    }
    out = {
        "script": rng.choice(script_pool),
        "domain": rng.choice(domain_pool),
        "wire": wires,
        "params": params,
        "apply_enabled": True,
        "user_data": True,
    }
    for k in GLOBAL_ALGO_EXTRA_KINDS:
        out[k] = rng.choice(extra_pool[k])
        params["enable_" + k] = True
        params[k + "_amount"] = round(rng.uniform(0.25, 1.0), 3)
    return out


