def generate_random_rhythm_algo(rng=None):
    """Random Meum-grounded gate/offset expression for the RHYTHM algo scope."""
    if rng is None:
        rng = random
    a = round(rng.uniform(0.5, 6.0), 3)
    b = round(rng.uniform(0.1, 3.0), 3)
    thr = round(rng.uniform(0.25, 0.65), 3)
    pool = [
        f"sin(step_i * MEUM * {a} + t * {b}) > {thr}",
        f"(step_i * MEUM_INV % 1.0) > {thr}",
        f"sin(step_i * {a} + t * MEUM) * cos(step_i * PHI * {b}) > {thr - 0.1:.3f}",
        f"isn(step_i * MEUM * {a}) > {thr}",
        f"((step_i + 1) * MEUM % 1.0) < {1.0 - thr:.3f}",
        f"sin(step_i * PHI * {a} + t * MEUM_INV * {b}) > {thr}",
    ]
    offset_pool = [
        f"(step_i * MEUM_INV % 1.0 - 0.5) * {round(rng.uniform(0.1, 0.4), 3)}",
        f"sin(step_i * MEUM * {a}) * {round(rng.uniform(0.05, 0.3), 3)}",
        f"0.0",
    ]
    return {"gate": rng.choice(pool), "offset": rng.choice(offset_pool)}


def generate_random_melody_algo(rng=None):
    """Random Meum-grounded pitch-ratio expression for the MELODY algo scope."""
    if rng is None:
        rng = random
    a = round(rng.uniform(0.5, 4.0), 3)
    b = round(rng.uniform(0.25, 2.0), 3)
    pool = [
        f"MEUM ** (step_i / max(1, n) * {a})",
        f"1.0 + (sin(step_i * MEUM * {a} + t * {b}) * 0.5)",
        f"2.0 ** (round(sin(step_i * MEUM * {a}) * {b}) / 12.0)",
        f"(1.0 + MEUM_MINUS_1 * sin(step_i * PHI * {a})) * {round(rng.uniform(0.8, 1.25), 3)}",
        f"MEUM_INV + (step_i * MEUM % 1.0) * {round(rng.uniform(0.1, 0.5), 3)}",
        f"1.0 + 0.25 * cos(step_i * MEUM * {a} + t * PHI * {b})",
    ]
    return {"pitch": rng.choice(pool)}


def evaluate_seed_component(expr, t_value=0.0, canonical_context=None):
    """Evaluate one seed component expression to a finite float, or None."""
    nums = _eval_seed_python(expr, t_value=t_value, canonical_context=canonical_context)
    if not nums:
        return None
    return float(nums[0])


def _split_seed_list_parts(raw):
    """Split seed text on commas/newlines while respecting parentheses and strings.

    Critical for lerp(a, b, u), clamp(v, lo, hi), choose(...): naive comma split
    would shred function arguments.
    """
    text = str(raw or "").replace("\r\n", "\n").replace("\r", "\n")
    parts = []
    buf = []
    depth = 0
    in_str = None
    i = 0
    while i < len(text):
        ch = text[i]
        if in_str:
            buf.append(ch)
            if ch == in_str and (i == 0 or text[i - 1] != "\\"):
                in_str = None
            i += 1
            continue
        if ch in ("'", '"'):
            in_str = ch
            buf.append(ch)
            i += 1
            continue
        if ch == "(":
            depth += 1
            buf.append(ch)
            i += 1
            continue
        if ch == ")":
            depth = max(0, depth - 1)
            buf.append(ch)
            i += 1
            continue
        if depth == 0 and (ch == "," or ch == "\n"):
            piece = "".join(buf).strip()
            if piece and not piece.startswith("#"):
                parts.append(piece)
            buf = []
            i += 1
            continue
        if depth == 0 and ch == "#":
            while i < len(text) and text[i] != "\n":
                i += 1
            continue
        buf.append(ch)
        i += 1
    piece = "".join(buf).strip()
    if piece and not piece.startswith("#"):
        parts.append(piece)
    return parts


def parse_seed_numeric_list(seed_text, t_value=0.0, canonical_context=None, allow_scrape=True):
    """Split a seed field into evaluated numeric components (finite floats only).

    Failed / non-numeric parts are skipped — never replaced with hash tokens.
    Pass allow_scrape=False to require a real evaluation (see _eval_seed_python).
    """
    return list(_eval_seed_python(seed_text, t_value=t_value, canonical_context=canonical_context,
                                   allow_scrape=allow_scrape))


def seed_script_is_viable(seed_text, n_instruments=8):
    """Return True if seed_text evaluates to finite numbers for composition + time + instruments."""
    try:
        vals = parse_seed_numeric_list(seed_text, t_value=0.0)
        if not vals or not all(math.isfinite(v) for v in vals):
            return False
        for t in (0.0, 0.5, 1.25, 2.0, math.pi):
            v = evaluate_seed_expression_at_time(seed_text, t)
            if not math.isfinite(v):
                return False
        for i in range(max(2, int(n_instruments))):
            v = vals[i % len(vals)]
            if not math.isfinite(v):
                return False
        return True
    except Exception:
        return False


