def _compat_scroll_central(content: QWidget, min_width: int = 420, min_height: int = 280) -> QScrollArea:
    """Global window compatibility wrapper: preserve access to controls instead of clipping them."""
    area = QScrollArea()
    area.setWidgetResizable(True)
    area.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
    area.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
    content.setMinimumSize(max(min_width, content.minimumWidth()), max(min_height, content.minimumHeight()))
    area.setWidget(content)
    return area

def _resample_float32_exact_length(samples, source_rate, target_rate):
    """Polyphase anti-aliased resampling with duration-exact output length.

    The desired length is round(N * target_rate / source_rate), so exported
    duration differs by at most half an output sample.  scipy's polyphase
    result can be ceil-rounded; trim/pad only that final rounding discrepancy.
    Input is treated as read-only and output is contiguous float32.
    """
    x = np.asarray(samples, dtype=np.float32).reshape(-1)
    src = int(source_rate); dst = int(target_rate)
    if src <= 0 or dst <= 0:
        raise ValueError("Sample rates must be positive integers")
    if x.size == 0:
        return np.empty(0, dtype=np.float32)
    target_n = max(1, int(round(x.size * float(dst) / float(src))))
    if src == dst:
        y = np.ascontiguousarray(x, dtype=np.float32)
    else:
        try:
            import math as _math
            _rp = __import__("scipy.signal", fromlist=["resample_poly"]).resample_poly
            g = _math.gcd(src, dst)
            y = np.asarray(_rp(x, dst // g, src // g), dtype=np.float32)
        except Exception:
            n_out = max(1, int(round(x.size * float(dst) / float(src))))
            old = np.linspace(0.0, 1.0, x.size, endpoint=False)
            new = np.linspace(0.0, 1.0, n_out, endpoint=False)
            y = np.interp(new, old, x).astype(np.float32)
    if y.size > target_n:
        y = y[:target_n]
    elif y.size < target_n:
        y = np.pad(y, (0, target_n - y.size), mode="constant")
    return np.ascontiguousarray(y, dtype=np.float32)


def _master_hardclip_snapshot(master, ratio_pct, master_volume):
    """Pure, widget-free form of the canonical export hardclip stage.

    Inputs are frozen scalar values captured on the UI thread. This duplicates
    the exact volume × drive → hard-clip equation without touching a QWidget or
    mutating the live app's monitor state.
    """
    m32 = np.asarray(master, dtype=np.float32).ravel()
    n = int(m32.size)
    if n <= 0:
        return np.ascontiguousarray(m32, dtype=np.float32), {
            "mode": "hardclip", "ratio_pct": float(ratio_pct), "drive": 1.0,
            "vol": float(master_volume), "density_before": 0.0,
            "density_after": 0.0, "peak": 0.0,
        }
    ratio_pct = float(np.clip(float(ratio_pct), 0.0, 100.0))
    r = float(np.clip(ratio_pct / 100.0, 0.0, 1.0))
    drive = float(1.0 + 1.5 * r)
    vol = float(master_volume)
    scaled = m32 * np.float32(vol * drive)
    out = None
    _hc = _GB_ACCEL_FUNCS.get("hardclip") if isinstance(_GB_ACCEL_FUNCS, dict) else None
    if _hc is not None and n >= 256:
        try:
            import ctypes as _ct
            out = np.empty(n, dtype=np.float32)
            metrics = np.zeros(3, dtype=np.float32)
            _hc(
                scaled.ctypes.data_as(_ct.POINTER(_ct.c_float)),
                out.ctypes.data_as(_ct.POINTER(_ct.c_float)),
                _ct.c_size_t(n), _ct.c_float(1.0),
                metrics.ctypes.data_as(_ct.POINTER(_ct.c_float)),
            )
        except Exception:
            out = None
    if out is None:
        out = np.clip(scaled, -1.0, 1.0).astype(np.float32)
    density_before = float(np.mean(np.abs(m32) > 0.99))
    density_after = float(np.mean(np.abs(out) >= 0.999))
    peak = float(np.max(np.abs(out))) if n else 0.0
    report = {
        "mode": "hardclip", "ratio_pct": ratio_pct, "drive": drive,
        "vol": vol, "density_before": density_before,
        "density_after": density_after, "peak": peak,
    }
    return np.ascontiguousarray(out, dtype=np.float32), report


