# =============================================================================
# LAYERED PANEL HOST — nested QGroupBox stack for machines with tight layouts
# Each sub-panel is a titled box inside a scroll area so nothing is obscured
# when the main window is smaller than the design size.
# =============================================================================


# MasterVectorVisualizer: removed (R23r) — it was never instantiated; its controls now live in the per-instrument geometric synth panels.


_NOTE_NAMES = ("C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B")


def frequency_color(hz):
    """Colour for a frequency: hue = pitch class (C red … B violet), lightness = octave."""
    try:
        _hz = float(hz)
        midi = 69.0 + 12.0 * math.log2(_hz / 440.0) if _hz > 0 else 0.0   # 0 Hz has no pitch: lowest colour
    except Exception:
        midi = 69.0
    pc = int(round(midi)) % 12
    octave = int(round(midi)) // 12 - 1
    light = int(np.clip(110 + 14 * octave, 90, 220))
    return QColor.fromHsl(int(pc * 30) % 360, 210, light), f"{_NOTE_NAMES[pc]}{octave}"


class FrequencySlider(QWidget):
    """Log-scale frequency slider, colour-coded by pitch class (GROOVEBOX_R23R_FREQUENCY_SLIDERS_20261031)."""
    valueChanged = pyqtSignal(float)

    def __init__(self, hz=440.0, lo=20.0, hi=20000.0, caption="", parent=None):
        super().__init__(parent)
        self.lo, self.hi = float(lo), float(hi)
        lay = QHBoxLayout(self); lay.setContentsMargins(0, 0, 0, 0); lay.setSpacing(4)
        if caption:
            cap = QLabel(caption); cap.setStyleSheet("color:#cfd8ee; font-weight:800;"); lay.addWidget(cap)
        self.slider = QSlider(Qt.Orientation.Horizontal); self.slider.setRange(0, 1000); self.slider.setMinimumWidth(110)
        self.label = QLabel(""); self.label.setMinimumWidth(92)
        lay.addWidget(self.slider, 1); lay.addWidget(self.label)
        self.slider.valueChanged.connect(self._changed)
        self.setHz(hz)

    def _to_hz(self, v):
        return self.lo * (self.hi / self.lo) ** (float(v) / 1000.0)

    def hz(self):
        return float(self._to_hz(self.slider.value()))

    def setHz(self, hz):
        hz = float(np.clip(float(hz), self.lo, self.hi))
        v = int(round(1000.0 * math.log(hz / self.lo) / math.log(self.hi / self.lo)))
        if self.slider.value() == v:
            self._paint(hz)
        self.slider.setValue(v)

    def _paint(self, hz):
        col, note = frequency_color(hz)
        c = col.name()
        self.label.setText(f"{hz:,.1f} Hz · {note}")
        self.label.setStyleSheet(f"color:{c}; font-weight:900;")
        self.slider.setStyleSheet(
            f"QSlider::groove:horizontal {{ height:6px; border-radius:3px; background: qlineargradient(x1:0,y1:0,x2:1,y2:0,"
            f" stop:0 #ff3b3b, stop:0.17 #ffb03b, stop:0.33 #e6ff3b, stop:0.5 #3bff8a, stop:0.67 #3bc8ff, stop:0.83 #6b3bff, stop:1 #ff3bd2); }}"
            f" QSlider::handle:horizontal {{ background:{c}; border:2px solid #0b0d12; width:14px; margin:-5px 0; border-radius:7px; }}")

    def _changed(self, v):
        hz = self._to_hz(v)
        self._paint(hz)
        self.valueChanged.emit(float(hz))


class DrawnWaveCanvas(QWidget):
    """Draw one waveform cycle with the mouse (GROOVEBOX_R23R_WAVESPACE_20261031).

    Left-drag draws (every column between two mouse positions is filled, so fast
    strokes leave no gaps), right-drag erases back to the canonical cycle,
    double-click clears the drawing (the canonical engines own the cycle again).
    The cycle is stored as DRAWN_WAVE_POINTS samples in [-1, 1], independent of
    the widget size, and emitted on release so a stroke triggers one re-render.
    """
    tableChanged = pyqtSignal(object)

    def __init__(self, caption="DRAW CYCLE", parent=None):
        super().__init__(parent)
        self.caption = str(caption)
        self.setMinimumHeight(96)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
        self.setToolTip("Left-drag: draw this cycle · Right-drag: erase to canonical · Double-click: clear (canonical owns it)")
        self.table = None
        self.canonical = None
        self._last = None
        self._dirty = False

    def set_table(self, table):
        self.table = None if table is None else np.clip(np.asarray(table, dtype=np.float32).ravel(), -1.0, 1.0).copy()
        if self.table is not None and self.table.size != DRAWN_WAVE_POINTS:
            src = np.linspace(0.0, 1.0, self.table.size, endpoint=False)
            dst = np.linspace(0.0, 1.0, DRAWN_WAVE_POINTS, endpoint=False)
            self.table = np.interp(dst, src, self.table, period=1.0).astype(np.float32)
        self.update()

    def set_canonical(self, cycle):
        self.canonical = None if cycle is None else np.asarray(cycle, dtype=np.float32).ravel().copy()
        self.update()

    def _plot_rect(self):
        return self.rect().adjusted(4, 16, -4, -4)

    def _to_index_value(self, pos):
        r = self._plot_rect()
        u = (pos.x() - r.left()) / max(1.0, float(r.width()))
        v = (pos.y() - r.top()) / max(1.0, float(r.height()))
        i = int(round(np.clip(u, 0.0, 1.0) * (DRAWN_WAVE_POINTS - 1)))
        return i, float(np.clip(1.0 - 2.0 * v, -1.0, 1.0))

    def _canonical_points(self):
        if self.canonical is None or self.canonical.size < 2:
            return np.zeros(DRAWN_WAVE_POINTS, dtype=np.float32)
        src = np.linspace(0.0, 1.0, self.canonical.size, endpoint=False)
        dst = np.linspace(0.0, 1.0, DRAWN_WAVE_POINTS, endpoint=False)
        return np.interp(dst, src, self.canonical, period=1.0).astype(np.float32)

    def _stroke(self, pos, erase):
        if self.table is None:
            self.table = self._canonical_points()
        i, v = self._to_index_value(pos)
        j, w = self._last if self._last is not None else (i, v)
        lo, hi = (j, i) if j <= i else (i, j)
        idx = np.arange(lo, hi + 1)
        if erase:
            self.table[idx] = self._canonical_points()[idx]
        else:
            vals = np.interp(idx, [j, i], [w, v]) if i != j else np.full(idx.size, v)
            self.table[idx] = vals.astype(np.float32)
        self._last = (i, v)
        self._dirty = True
        self.update()

    def mousePressEvent(self, e):
        if e.button() in (Qt.MouseButton.LeftButton, Qt.MouseButton.RightButton):
            self._last = None
            self._stroke(e.position(), e.button() == Qt.MouseButton.RightButton)

    def mouseMoveEvent(self, e):
        if e.buttons() & Qt.MouseButton.LeftButton:
            self._stroke(e.position(), False)
        elif e.buttons() & Qt.MouseButton.RightButton:
            self._stroke(e.position(), True)

    def mouseReleaseEvent(self, e):
        self._last = None
        if self._dirty:
            self._dirty = False
            self.tableChanged.emit(None if self.table is None else self.table.copy())

    def mouseDoubleClickEvent(self, e):
        self.table = None
        self._last = None
        self._dirty = False
        self.update()
        self.tableChanged.emit(None)

    def paintEvent(self, event):
        with owned_painter(self) as p:
            if p is None:
                return
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            p.fillRect(self.rect(), QColor("#070b12"))
            r = self._plot_rect()
            p.setPen(QPen(QColor("#1b2a3d"), 1))
            p.drawLine(QPointF(r.left(), r.center().y()), QPointF(r.right(), r.center().y()))
            for q in range(1, 4):
                xx = r.left() + q * r.width() / 4.0
                p.drawLine(QPointF(xx, r.top()), QPointF(xx, r.bottom()))

            def _path(arr, color, width):
                arr = np.asarray(arr, dtype=np.float32).ravel()
                if arr.size < 2:
                    return
                n = min(arr.size, max(2, r.width()))
                idx = np.linspace(0, arr.size - 1, n).astype(int)
                path = QPainterPath()
                for c, ii in enumerate(idx):
                    x = r.left() + c * r.width() / max(1, n - 1)
                    y = r.center().y() - float(arr[ii]) * r.height() * 0.5
                    path.moveTo(x, y) if c == 0 else path.lineTo(x, y)
                p.setPen(QPen(QColor(color), width)); p.setBrush(Qt.BrushStyle.NoBrush); p.drawPath(path)

            if self.canonical is not None:
                _path(self.canonical, "#4f6f8f" if self.table is not None else "#d4af37", 1.2 if self.table is not None else 2.0)
            if self.table is not None:
                _path(self.table, "#00ffcc", 2.0)
            p.setPen(QPen(QColor("#9cc7ff"), 1))
            owner = "USER-DRAWN (exact)" if self.table is not None else "CANONICAL WAVESPACE"
            p.drawText(self.rect().adjusted(5, 1, -5, 0), Qt.AlignmentFlag.AlignTop | Qt.AlignmentFlag.AlignLeft, f"{self.caption} · {owner}")
            p.end()


class VectorPad(QWidget):
    _gb_wheel_edits = True  # page scrolls; Ctrl+wheel edits (GROOVEBOX_R23R_WHEEL_SCROLLS_PAGE_20261101)
    """Mouse X/Y/Z pad: drag = X/Y, wheel or Shift+vertical drag = Z, double-click = centre."""
    vectorChanged = pyqtSignal(float, float, float)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumSize(120, 96)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.setToolTip("Drag: X/Y · Ctrl+wheel or Shift+drag: Z (plain wheel scrolls the page) · Double-click: centre (canonical owns the vector)")
        self.vector = (0.0, 0.0, 0.0)
        self.canonical = (0.0, 0.0, 0.0)
        self.user = (0.0, 0.0, 0.0)
        self._z_drag = None

    def set_vectors(self, effective, canonical=(0.0, 0.0, 0.0), user=None):
        self.vector = tuple(float(np.clip(v, -1.0, 1.0)) for v in effective[:3])
        self.canonical = tuple(float(np.clip(v, -1.0, 1.0)) for v in canonical[:3])
        if user is not None:
            self.user = tuple(float(np.clip(v, -1.0, 1.0)) for v in user[:3])
        self.update()

    def _geom(self):
        r = self.rect().adjusted(4, 4, -4, -4)
        rad = min(r.width(), r.height()) * 0.42
        return r, r.center().x(), r.center().y(), rad

    def _emit(self, x, y, z):
        self.user = (float(np.clip(x, -1.0, 1.0)), float(np.clip(y, -1.0, 1.0)), float(np.clip(z, -1.0, 1.0)))
        self.update()
        self.vectorChanged.emit(*self.user)

    def _xy_from(self, pos):
        r, cx, cy, rad = self._geom()
        return (pos.x() - cx) / max(1.0, rad), -(pos.y() - cy) / max(1.0, rad)

    def mousePressEvent(self, e):
        if e.button() != Qt.MouseButton.LeftButton:
            return
        if e.modifiers() & Qt.KeyboardModifier.ShiftModifier:
            self._z_drag = (e.position().y(), self.user[2])
            return
        x, y = self._xy_from(e.position())
        self._emit(x, y, self.user[2])

    def mouseMoveEvent(self, e):
        if not (e.buttons() & Qt.MouseButton.LeftButton):
            return
        if self._z_drag is not None:
            y0, z0 = self._z_drag
            self._emit(self.user[0], self.user[1], z0 + (y0 - e.position().y()) / 80.0)
            return
        x, y = self._xy_from(e.position())
        self._emit(x, y, self.user[2])

    def mouseReleaseEvent(self, e):
        self._z_drag = None

    def wheelEvent(self, e):
        step = 0.05 if e.angleDelta().y() > 0 else -0.05
        self._emit(self.user[0], self.user[1], self.user[2] + step)

    def mouseDoubleClickEvent(self, e):
        self._emit(0.0, 0.0, 0.0)

    def paintEvent(self, event):
        with owned_painter(self) as p:
            if p is None:
                return
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            r, cx, cy, rad = self._geom()
            p.fillRect(r, QColor("#080c13"))
            p.setPen(QPen(QColor("#26374f"), 1)); p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(QPointF(cx, cy), rad, rad)
            p.drawLine(QPointF(cx - rad, cy), QPointF(cx + rad, cy))
            p.drawLine(QPointF(cx, cy - rad), QPointF(cx, cy + rad))
            # Z bar on the right edge (bottom -1 .. top +1).
            zx = r.right() - 8
            p.drawLine(QPointF(zx, r.top() + 6), QPointF(zx, r.bottom() - 6))
            for z, col in ((self.canonical[2], "#d4af37"), (self.vector[2], "#fff0a6"), (self.user[2], "#00ffcc")):
                zy = cy - z * (r.height() * 0.5 - 8)
                p.setPen(QPen(QColor(col), 2)); p.drawLine(QPointF(zx - 5, zy), QPointF(zx + 5, zy))
            qx, qy, _ = self.canonical
            p.setPen(QPen(QColor("#d4af37"), 2))
            p.drawLine(QPointF(cx, cy), QPointF(cx + qx * rad, cy - qy * rad))
            ex, ey, ez = self.vector
            exx, exy = cx + ex * rad, cy - ey * rad
            p.setPen(QPen(QColor("#fff0a6"), 3)); p.drawLine(QPointF(cx, cy), QPointF(exx, exy))
            rr = 4.0 + 3.0 * (ez + 1.0)
            p.setBrush(QBrush(QColor("#d45b3d"))); p.setPen(QPen(QColor("#ffb08f"), 1))
            p.drawEllipse(QPointF(exx, exy), rr, rr)
            ux, uy, _ = self.user
            p.setBrush(Qt.BrushStyle.NoBrush); p.setPen(QPen(QColor("#00ffcc"), 1, Qt.PenStyle.DashLine))
            p.drawEllipse(QPointF(cx + ux * rad, cy - uy * rad), 6, 6)
            p.setPen(QPen(QColor("#9fd4ff"), 1))
            p.drawText(r.adjusted(4, 2, -4, -2), Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignTop,
                       f"X{ex:+.2f} Y{ey:+.2f} Z{ez:+.2f}")
            p.drawText(r.adjusted(4, 2, -4, -2), Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignBottom, "gold = canonical · cyan = you")
            p.end()


class WavetableProjector(QWidget):
    """Global 1D/2D/3D-inspired wavetable projector feeding the Master Vector guide.

    The UI is deliberately compact: representation mode, shape controls, and a
    live projection. User parameters are retained separately from a canonical
    guide; the effective field is always a 50/50 user/canonical blend.
    """
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMinimumSize(220, 118)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.mode = 1
        self.phase = 0.0
        self.curvature = 0.50
        self.twist = 0.50
        self.fold = 0.20
        self.user_field = (0.50, 0.50, 0.50)
        self.canonical_field = (0.50, 0.50, 0.50)

    def set_fields(self, user, canonical):
        self.user_field = tuple(float(np.clip(v, 0.0, 1.0)) for v in user[:3])
        self.canonical_field = tuple(float(np.clip(v, 0.0, 1.0)) for v in canonical[:3])
        self.update()

    def set_shape(self, phase=None, curvature=None, twist=None, fold=None, mode=None):
        if phase is not None: self.phase = float(phase)
        if curvature is not None: self.curvature = float(curvature)
        if twist is not None: self.twist = float(twist)
        if fold is not None: self.fold = float(fold)
        if mode is not None: self.mode = int(mode)
        self.update()

    def paintEvent(self, event):
        with owned_painter(self) as p:
            if p is None:
                return
            p.setRenderHint(QPainter.RenderHint.Antialiasing, True)
            r = self.rect().adjusted(4, 4, -4, -4)
            p.fillRect(r, QColor('#070b12'))
            w, h = r.width(), r.height()
            cx, cy = r.center().x(), r.center().y()
            # faint projection grid
            p.setPen(QPen(QColor('#1b2a3d'), 1))
            for q in range(1, 5):
                yy = r.top() + q*h/5.0
                p.drawLine(QPointF(r.left(), yy), QPointF(r.right(), yy))
            for q in range(1, 7):
                xx = r.left() + q*w/7.0
                p.drawLine(QPointF(xx, r.top()), QPointF(xx, r.bottom()))
            eu = np.asarray(self.user_field); ec = np.asarray(self.canonical_field)
            ef = 0.5*eu + 0.5*ec
            # 1D/2D/3D display modes all use the same effective field.
            pts=[]
            _cyc = getattr(self, "cycle", None)
            for i in range(96):
                u=i/95.0
                if _cyc is not None and len(_cyc) > 1:
                    wave=float(_cyc[int(u*(len(_cyc)-1))])
                    if self.mode == 2:
                        xx=r.left()+u*w; yy=cy - wave*(h*0.32)*(0.6+0.4*ef[1]) - (u-0.5)*h*0.18*ef[0]
                    elif self.mode == 3:
                        xx=r.left()+u*w; yy=cy - wave*(h*0.30)*(0.5+0.5*ef[2]) - series_sin(u*math.tau*2)*h*0.10*ef[0]
                    else:
                        xx=r.left()+u*w; yy=cy-wave*(h*0.32)*(0.7+0.3*ef[0])
                    pts.append(QPointF(xx, yy))
                    continue
                wave=series_sin(math.tau*(u*(1.0+3.0*self.twist)+self.phase))
                wave += self.fold*series_sin(math.tau*(u*3.0+self.phase*1.7))
                wave *= (0.65 + 0.35*self.curvature)
                if self.mode == 2:
                    xx=r.left()+u*w
                    yy=cy - wave*(h*0.32)*(0.6+0.4*ef[1]) - (u-0.5)*h*0.18*ef[0]
                elif self.mode == 3:
                    xx=r.left()+u*w
                    yy=cy - wave*(h*0.30)*(0.5+0.5*ef[2]) - series_sin(u*math.tau*2)*h*0.10*ef[0]
                else:
                    xx=r.left()+u*w; yy=cy-wave*(h*0.32)*(0.7+0.3*ef[0])
                pts.append(QPointF(xx, yy))
            p.setPen(QPen(QColor('#d4af37'), 2));
            for a,b in zip(pts, pts[1:]): p.drawLine(a,b)
            p.setPen(QPen(QColor('#9cc7ff'), 1));
            p.drawText(r.adjusted(5,4,-5,-4), Qt.AlignmentFlag.AlignTop|Qt.AlignmentFlag.AlignLeft,
                       f"{self.mode}D WAVETABLE · U/C 50/50 · X{ef[0]:.2f} Y{ef[1]:.2f} Z{ef[2]:.2f}")
            p.end()


# True while the startup chooser is modal. The window strip must not show,
# raise, or re-place itself during this window — Labwc centers new
# always-on-top surfaces and that was putting the bar over the chooser.
_GROOVEBOX_STARTUP_ACTIVE = False

# GROOVEBOX_V35_22ZV_EXTERNAL_WINDOW_STRIP_20260924
class _WindowOrganizer(QObject):
    """Owns window launch, order, UI-state maintenance, and thread decisions.

    The bar only paints. This object coordinates streams, pools, and the
    migratory budget so a frozen window cannot stall the strip.
    """
    def __init__(self):
        super().__init__()
        self._queue = []
        self._lock = threading.Lock()
        self._ui_state = {}
        self._stream_on = False

    def enqueue(self, kind, payload):
        with self._lock:
            self._queue.append((kind, payload))

    def drain(self):
        with self._lock:
            items = list(self._queue)
            self._queue.clear()
        return items

    def set_ui_state(self, key, value):
        with self._lock:
            self._ui_state[key] = value

    def ui_state(self, key, default=None):
        with self._lock:
            return self._ui_state.get(key, default)

    def coordinate_stream(self, on, reason=""):
        """Decide the migratory budget. The bar and focus path call this."""
        self._stream_on = bool(on)
        try:
            import thread_budget as _tb
            if hasattr(_tb, "set_streamable"):
                _tb.set_streamable(self._stream_on)
        except Exception:
            pass
        self.set_ui_state("stream", {"on": self._stream_on, "reason": reason})

    def coordinate_pool(self, name, workers):
        """Record a pool size decision. Callers create the pool; this tracks it."""
        self.set_ui_state(f"pool:{name}", int(workers))

    def pool_quota(self):
        """SCODE_QUOTA_20261107: a multidimensional assumption quota.

        Each dimension (audio, video, ui, scode) assumes a share of the 14.
        The focused window's dimension gets a 1/3 advantage. Other dimensions
        shrink when their pooling benefit is low.
        """
        cap = 14
        try:
            import thread_budget as _tb
            cap = _tb.migratory_threads() if hasattr(_tb, "migratory_threads") else 14
        except Exception:
            pass
        dims = ("audio", "video", "ui", "scode")
        benefit = {"audio": 0.8, "video": 0.9, "ui": 0.4, "scode": 0.7}
        focus = self.ui_state("activity", "idle")
        focus_dim = {"play": "audio", "export": "video", "browse": "ui"}.get(focus, "scode")
        weights = dict(benefit)
        weights[focus_dim] = weights.get(focus_dim, 0.5) * (1.0 + 1.0/3.0)
        total = sum(weights.values()) or 1.0
        quota = {d: max(1, int(round(cap * weights.get(d, 0.5) / total))) for d in dims}
        self.set_ui_state("pool_quota", quota)
        return quota

    def predict_and_migrate(self):
        """Use the dimensional quota to predict where threads should go,
        then record the migration so pools can resize.
        """
        quota = self.ui_state("pool_quota") or self.pool_quota()
        focus = self.ui_state("activity", "idle")
        focus_dim = {"play": "audio", "export": "video", "browse": "ui"}.get(focus, "scode")
        # The path is the ordered list of dimensions by quota, focus first.
        path = sorted(quota.keys(), key=lambda d: (d != focus_dim, -quota[d]))
        self.set_ui_state("migration_path", path)
        # Execute: each dimension's pool is set to its quota.
        for dim, n in quota.items():
            self.coordinate_pool(dim, n)
        return path

class _ActivityFollower:
    """Watches what the user is doing and assigns threads to available pools.

    It does not create threads. It decides how many each known pool should
    have, given the activity and the migratory cap.
    """
    def __init__(self, organizer):
        self.org = organizer
        self._activity = "idle"

    def note(self, activity):
        """Record what the user just did: play, export, browse, idle, etc."""
        self._activity = str(activity or "idle")
        self.org.set_ui_state("activity", self._activity)
        self.assign()

    def assign(self):
        """Split the migratory budget. Cap is 14 when idle.

        MIGRATORY_ADV_20261107: the focused window gets a 1/3 advantage.
        Other pathways shrink the migrant count when their pooling benefit
        is low, and grow it when it is high. The focus still takes a third
        more than the pooling rule alone would give.
        """
        try:
            import thread_budget as _tb
            cap = _tb.migratory_threads() if hasattr(_tb, "migratory_threads") else 14
        except Exception:
            cap = 14
        # Pooling benefit: how much each pool gains from more threads.
        benefit = {"audio": 0.8, "video": 0.9, "ui": 0.4, "scode": 0.7}
        # Focus advantage: the selected window's pool gets 1/3 more.
        focus_pool = {"play": "audio", "export": "video", "browse": "ui"}.get(self._activity, "scode")
        weights = dict(benefit)
        weights[focus_pool] = weights.get(focus_pool, 0.5) * (1.0 + 1.0/3.0)
        total = sum(weights.values()) or 1.0
        for name, w in weights.items():
            n = max(1, int(round(cap * w / total)))
            self.org.coordinate_pool(name, n)
        self.org.set_ui_state("assigned", {
            "activity": self._activity, "cap": cap, "focus": focus_pool,
        })
        # MIGRATE_20261107: predict the path and execute it.
        try:
            self.org.predict_and_migrate()
        except Exception:
            pass
        # PATH_PREDICT_20261107: use the dimensional quota to predict and
        # warm the thread paths the focused window will need.
        try:
            quota = self.org.pool_quota()
            paths = []
            if quota.get("audio", 0) >= 3:
                paths.append("audio-render")
            if quota.get("video", 0) >= 3:
                paths.append("video-frame")
            if quota.get("scode", 0) >= 2:
                paths.append("scode-memo")
            self.org.set_ui_state("predicted_paths", paths)
        except Exception:
            pass
        # LIVE_POOL_20261107: a pool change updates the live buffer now.
        try:
            app = QApplication.instance()
            main = getattr(app, "_groovebox_main", None) if app is not None else None
            if main is not None:
                _buffer_linker().link(main)
        except Exception:
            pass

_ACTIVITY_FOLLOWER = None

def _activity_follower():
    global _ACTIVITY_FOLLOWER
    if _ACTIVITY_FOLLOWER is None:
        _ACTIVITY_FOLLOWER = _ActivityFollower(_window_organizer())
    return _ACTIVITY_FOLLOWER

class _BufferLinker:
    """Listens to pools and the live buffer and links them.

    It does not render. It records which pools are feeding the live buffer
    and whether the change point is being honored.
    """
    def __init__(self, organizer):
        self.org = organizer

    def link(self, app):
        """Read pool sizes and buffer state, then record the link."""
        pools = {}
        for name in ("audio", "video", "ui", "video-object"):
            n = self.org.ui_state(f"pool:{name}")
            if n:
                pools[name] = n
        buf = None
        try:
            buf = getattr(app, "play_buffer", None)
            n = int(getattr(buf, "shape", [0])[0]) if buf is not None else 0
        except Exception:
            n = 0
        cp = int(getattr(app, "_buffer_change_point", 0) or 0)
        linked = bool(pools) and n > 0
        # SWAP_AUTO_20261107: write the live buffer into the SSD swap so a
        # later play can map it instead of rebuilding.
        swapped = False
        if linked and buf is not None:
            try:
                import memory_manager as _mm
                store = _mm.manager().swap_store() if hasattr(_mm, "manager") else None
                if store is not None:
                    store.put("live_buffer", np.array(buf, copy=True))
                    swapped = True
            except Exception:
                pass
        self.org.set_ui_state("buffer_link", {
            "pools": pools,
            "samples": n,
            "change_point": cp,
            "linked": linked,
            "swapped": swapped,
        })
        return linked

_BUFFER_LINKER = None

def _buffer_linker():
    global _BUFFER_LINKER
    if _BUFFER_LINKER is None:
        _BUFFER_LINKER = _BufferLinker(_window_organizer())
    return _BUFFER_LINKER

_WINDOW_ORGANIZER = None

def _window_organizer():
    global _WINDOW_ORGANIZER
    if _WINDOW_ORGANIZER is None:
        _WINDOW_ORGANIZER = _WindowOrganizer()
    return _WINDOW_ORGANIZER

class _LongHoldQuitButton(QToolButton):
    """Normal click quits; a six-second hold requests immediate sOS shutdown.

    This is an event-loop gesture, not a hardware failsafe: if Qt is hard-deadlocked,
    no widget event can run. Release after a short GUI stall is still detected by
    elapsed monotonic time.
    """
    holdPowerOff = pyqtSignal()
    def __init__(self,parent=None):
        super().__init__(parent)
        self._press_at=None; self._long_fired=False
        self._hold_timer=QTimer(self); self._hold_timer.setSingleShot(True); self._hold_timer.setInterval(6000)
        self._hold_timer.timeout.connect(self._fire_hold)
        self.holdPowerOff.connect(self._do_poweroff)
    def _fire_hold(self):
        if self._press_at is not None:
            self._long_fired=True; self.holdPowerOff.emit()
    def mousePressEvent(self,event):
        if event.button()==Qt.MouseButton.LeftButton:
            self._press_at=time.monotonic(); self._long_fired=False; self._hold_timer.start()
            self.setToolTip("Keep holding for 6 seconds to power off sOS immediately. Release for normal Quit.")
        super().mousePressEvent(event)
    def mouseReleaseEvent(self,event):
        held=(time.monotonic()-self._press_at) if self._press_at is not None else 0.0
        self._hold_timer.stop(); self._press_at=None
        if held>=6.0 and not self._long_fired:
            self._long_fired=True; self.holdPowerOff.emit()
        super().mouseReleaseEvent(event)
    def _do_poweroff(self):
        try:
            mgr=self.parentWidget()._manager()
            if mgr is not None: mgr.emergency_poweroff()
        except Exception as exc:
            print(f"[Quit] emergency hold action failed: {exc}")


class _GrooveboxWindowStrip(QWidget):
    """Always-visible Wayland window recovery strip outside Groovebox windows.

    This is a parentless top-level surface, not a child of Main/Performance. It
    therefore remains clickable when those windows are hidden or minimized and
    acts as the minimal taskbar that the strict Labwc appliance intentionally
    does not otherwise provide.
    """
    def __init__(self, manager, embedded=False):
        # GROOVEBOX_R23R_WINDOW_BAR_DESKTOP_20261101: on a desktop the bar is a
        # toolbar inside the main window (always at the top, clicks come from a
        # focused Groovebox window so the compositor lets us raise windows). The
        # parentless top strip is kept for the sOS/Labwc appliance only.
        self._embedded = bool(embedded)
        if self._embedded:
            super().__init__(None)
        else:
            flags = (Qt.WindowType.Window |
                     Qt.WindowType.FramelessWindowHint |
                     Qt.WindowType.WindowStaysOnTopHint |
                     Qt.WindowType.WindowDoesNotAcceptFocus)
            super().__init__(None, flags)
        self._manager_ref = weakref.ref(manager)
        self._tab_refs = []
        self.setObjectName("grooveboxExternalWindowStrip")
        self.setProperty("grooveboxExternalWindowStrip", True)
        self.setWindowTitle("Groovebox Windows")
        self.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, False)
        self.setMinimumHeight(38)
        self.setMaximumHeight(42)
        self.setStyleSheet(
            "QWidget#grooveboxExternalWindowStrip { background:#0d1118; border:1px solid #596574; }"
            "QTabBar::tab { background:#171d26; color:#d6dde8; padding:6px 11px; border:1px solid #3d4857; }"
            "QTabBar::tab:selected { background:#263243; color:white; border-color:#7f94ad; }"
            "QToolButton { background:#241818; color:#f0dede; border:1px solid #754848; padding:5px 10px; }"
        )
        row = QHBoxLayout(self)
        row.setContentsMargins(5, 3, 5, 3)
        row.setSpacing(5)
        label = QLabel("Windows:", self)
        label.setStyleSheet("color:#9fb0c4; font-weight:600;")
        row.addWidget(label, 0)
        self.tabs = QTabBar(self)
        self.tabs.setExpanding(False)
        self.tabs.setMovable(True)  # NAV_MOVE_20261107: reorder even if a window is frozen
        # GROOVEBOX_R23R_WINDOW_BAR_ORDER_20261101: closable tabs, scroll buttons +
        # wheel scrolling, elided titles, and a fixed order (0 Main, 1 Performance,
        # 2 Playlist, 3 Sidechain, then other windows in the order they opened).
        self.tabs.setTabsClosable(True)
        self.tabs.setUsesScrollButtons(True)
        self.tabs.setElideMode(Qt.TextElideMode.ElideRight)
        self.tabs.setDrawBase(False)
        self.tabs.tabBarClicked.connect(self._tab_clicked)
        self.tabs.tabCloseRequested.connect(self._tab_close_requested)
        self.tabs.tabMoved.connect(self._tab_moved)
        self.tabs.installEventFilter(self)
        self._first_seen = {}
        row.addWidget(self.tabs, 1)
        self.quit_btn = _LongHoldQuitButton(self)
        self.quit_btn.setText("Quit Groovebox")
        self.quit_btn.setToolTip("Click to quit. Hold for 6 seconds to power off sOS immediately.")
        self.quit_btn.clicked.connect(self._quit_requested)
        self.compat_btn = QToolButton(self)
        self.compat_btn.setText("🧩 Compatibility")
        self.compat_btn.setToolTip("UI scale, rendering, dialogs, audio latency, video export — fit Groovebox to this machine.")
        self.compat_btn.clicked.connect(lambda: (self._manager()._main_ref()._show_compat_dialog() if (self._manager() and self._manager()._main_ref()) else None))
        self.new_btn = QToolButton(self)
        self.new_btn.setText("＋ New window")
        self.new_btn.setToolTip("Open another Performance, Player or Live Player as its own tab — e.g. several players side by side to scan media.")
        self.new_btn.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        _new_menu = QMenu(self.new_btn)
        for _label, _kind in (("🎛 Performance", "performance"), ("▶ Player", "player"), ("🎧 Live Player", "live_player")):
            _new_menu.addAction(_label, lambda k=_kind: self._open_extra(k))
        self.new_btn.setMenu(_new_menu)
        # WINDOW_BAR_R31: export progress dropdown, quick actions, UI-stall report.
        try:
            from window_bar_tools import ExportsButton, ActionsButton, StallLabel, ExportProgressBar
            _mref = lambda: (self._manager()._main_ref() if self._manager() else None)
            _main0 = _mref()
            self.stall_lbl = StallLabel(getattr(_main0, "_ui_watchdog", None), self)
            self.exports_btn = ExportsButton(_mref, self)
            self.export_bar = ExportProgressBar(_mref, self)
            self.actions_btn = ActionsButton(_mref, self)
            row.addWidget(self.stall_lbl, 0)
            row.addWidget(self.exports_btn, 0)
            row.addWidget(self.export_bar, 0)
            row.addWidget(self.actions_btn, 0)
        except Exception as _wb_exc:
            print(f"[UI] window bar tools unavailable: {_wb_exc}")
        # GROOVEBOX_R32_WINDOW_MANAGER_20261109: OS-style arrange menu + right-click on tabs.
        self.arrange_btn = QToolButton(self)
        self.arrange_btn.setText("⊞ Arrange")
        self.arrange_btn.setToolTip("Snap, tile, cascade, minimise all / restore all, cycle windows "
                                    "(Ctrl+Alt+←/→/↑/↓, Ctrl+Alt+T/C/D/R, Ctrl+`). Right-click a tab for its own menu.")
        self.arrange_btn.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        self._arrange_menu = QMenu(self.arrange_btn)
        self._arrange_menu.aboutToShow.connect(self._fill_arrange_menu)
        self.arrange_btn.setMenu(self._arrange_menu)
        self.tabs.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.tabs.customContextMenuRequested.connect(self._tab_context_menu)
        row.addWidget(self.arrange_btn, 0)
        row.addWidget(self.new_btn, 0)
        row.addWidget(self.compat_btn, 0)
        row.addWidget(self.quit_btn, 0)
        self._timer = QTimer(self)
        self._timer.setInterval(8000)   # BAR_SMOOTH_20261107: slower poll, events drive the bar
        self._timer.timeout.connect(self.refresh)
        self._timer.start()
        self._pin_timer = QTimer(self)
        self._pin_timer.setSingleShot(True)
        self._pin_timer.setInterval(400)
        self._pin_timer.timeout.connect(self._place_on_screen)
        self._pin_timer.start()
        QTimer.singleShot(0, self._place_on_screen)

    def _fill_arrange_menu(self):
        try:
            import window_manager as _wm
            m = _wm.manager()
            if m is not None:
                m.build_arrange_menu(self._arrange_menu)
        except Exception as exc:
            print(f"[Windows] arrange menu unavailable: {exc}")

    def _tab_context_menu(self, pos):
        try:
            import window_manager as _wm
            idx = self.tabs.tabAt(pos)
            if idx < 0 or idx >= len(self._tab_refs):
                return
            w = self._tab_refs[idx]()
            m = _wm.manager()
            if w is None or m is None:
                return
            mgr = self._manager()
            main = mgr._main_ref() if mgr is not None else None
            close_fn = None if w is main else (lambda ww, i=idx: self._tab_close_requested(i))
            menu = m.window_context_menu(w, self, close_fn)
            menu.exec(self.tabs.mapToGlobal(pos))
        except Exception as exc:
            print(f"[Windows] tab menu failed: {exc}")

    def _open_extra(self, kind):
        mgr = self._manager()
        main = mgr._main_ref() if mgr is not None else None
        if main is not None and hasattr(main, "open_extra_window"):
            main.open_extra_window(kind)

    def _manager(self):
        return self._manager_ref()

    def _startup_blocked(self):
        return bool(globals().get("_GROOVEBOX_STARTUP_ACTIVE"))

    def _place_on_screen(self):
        if getattr(self, "_embedded", False):
            return
        if self._startup_blocked():
            try:
                self.hide()
            except Exception:
                pass
            return
        try:
            screen = QApplication.primaryScreen()
            if screen is None:
                return
            g = screen.geometry()
            h = 40
            # Top edge of the full display. Do not activate or raise in a way
            # that lets the compositor re-center this frameless surface.
            self.setGeometry(int(g.x()), int(g.y()), max(320, int(g.width())), h)
            self.move(int(g.x()), int(g.y()))
        except Exception:
            pass

    def refresh(self):
        if self._startup_blocked():
            try:
                self.hide()
            except Exception:
                pass
            return
        mgr = self._manager()
        if mgr is None or getattr(mgr, "_shutdown", False):
            return
        try:
            windows = mgr.session_windows()
        except Exception:
            windows = []
        try:
            main_w = mgr._main_ref()
        except Exception:
            main_w = None
        windows = self._ordered(windows, main_w)
        active = QApplication.activeWindow()
        sig=[]
        # BAR_THREAD_20261107: the organizer owns launch/order. The bar only paints.
        try:
            org = _window_organizer()
            for kind, payload in org.drain():
                if kind == "order":
                    self._manual_order = list(payload)
        except Exception:
            pass
        # BAR_SMOOTH_20261107: do not query a window that is mid-restore or
        # known frozen. Use the last cached title/state so the bar stays live.
        frozen = set()
        try:
            pend = getattr(mgr, "_pending_restore", None)
            if pend is not None:
                frozen.add(id(pend))
        except Exception:
            pass
        cache = getattr(self, "_win_cache", {})
        for w in windows:
            try:
                key = id(w)
                if key in frozen:
                    sig.append(cache.get(key, (key, "…", "open", False)))
                    continue
                title=(w.windowTitle() or w.__class__.__name__).strip()
                state="min" if w.isMinimized() else ("open" if w.isVisible() else "hidden")
                entry = (key, title, state, w is active)
                cache[key] = entry
                sig.append(entry)
            except Exception:
                pass
        self._win_cache = cache
        if sig == getattr(self, "_last_sig", None):
            return
        self._last_sig=sig
        try:
            self.tabs.blockSignals(True)
            while self.tabs.count():
                self.tabs.removeTab(0)
            self._tab_refs=[]
            main = main_w
            current = -1
            for n, w in enumerate(windows):
                try:
                    title=(w.windowTitle() or w.__class__.__name__).strip()
                    if w is main:
                        title="Main"
                    if len(title) > 28:
                        title=title[:25] + "…"
                    state="▱" if w.isMinimized() else ("●" if w.isVisible() else "○")
                    i = self.tabs.addTab(f"{n} {state} {title}")
                    self.tabs.setTabToolTip(i, f"#{n} · {w.windowTitle() or title}\nClick: restore / focus · ✕: close this window")
                    if w is main:
                        # Main is ended with Quit Groovebox, not from its tab.
                        for side in (QTabBar.ButtonPosition.RightSide, QTabBar.ButtonPosition.LeftSide):
                            try:
                                self.tabs.setTabButton(i, side, None)
                            except Exception:
                                pass
                    if w is active:
                        current = i
                    self._tab_refs.append(weakref.ref(w))
                except Exception:
                    continue
            # Following the active window scrolls its tab into view.
            self.tabs.setCurrentIndex(current)
        finally:
            try: self.tabs.blockSignals(False)
            except Exception: pass
        try:
            if self._startup_blocked():
                self.hide()
                return
            if not self.isVisible(): self.show()
            self._place_on_screen()
        except Exception:
            pass

    _ROLE_ORDER = (("performance", 1), ("player", 2), ("playlist", 3), ("sidechain", 4), ("side-chain", 4), ("side chain", 4))

    def _ordered(self, windows, main):
        """0 Main, 1 Performance, 2 Playlist, 3 Sidechain, then first-seen order."""
        out = []
        closed = self.__dict__.setdefault("_closed_ids", set())
        for w in windows:
            try:
                key = id(w)
                if key in closed:
                    if w.isVisible():
                        closed.discard(key)      # reopened: list it again
                    else:
                        continue                 # closed from its tab: hide from the bar
                if key not in self._first_seen:
                    self._first_seen[key] = len(self._first_seen)
                if w is main:
                    rank = 0
                else:
                    text = ((w.windowTitle() or "") + " " + w.__class__.__name__).casefold()
                    rank = next((r for k, r in self._ROLE_ORDER if k in text), 10)
                # NAV_MOVE_20261107: a manual drag wins over role order.
                manual = getattr(self, "_manual_order", None) or []
                if key in manual:
                    rank = 100 + manual.index(key)
                out.append((rank, self._first_seen[key], w))
            except Exception:
                continue
        out.sort(key=lambda t: (t[0], t[1]))
        return [w for _r, _o, w in out]

    def _tab_close_requested(self, index):
        if index < 0 or index >= len(self._tab_refs):
            return
        try:
            w = self._tab_refs[index]()
        except Exception:
            w = None
        mgr = self._manager()
        main = mgr._main_ref() if mgr is not None else None
        if w is None or w is main:
            return
        self.__dict__.setdefault("_closed_ids", set()).add(id(w))
        try:
            w.close()
        except Exception:
            try:
                w.hide()
            except Exception:
                pass
        self._last_sig = None
        QTimer.singleShot(0, self.refresh)

    def eventFilter(self, obj, event):
        try:
            if obj is self.tabs and event.type() == QEvent.Type.Wheel:
                self.wheelEvent(event)
                return True
        except Exception:
            pass
        return False

    def wheelEvent(self, event):
        # Wheel over the bar scrolls the tab row (no window is activated by it).
        try:
            dy = event.angleDelta().y() or event.angleDelta().x()
            btns = [b for b in self.tabs.findChildren(QToolButton) if b.isVisible() and b.parent() is self.tabs]
            if len(btns) >= 2:
                (btns[0] if dy > 0 else btns[-1]).click()
            event.accept()
        except Exception:
            pass

    def _tab_moved(self, from_idx, to_idx):
        """Reorder the bar's own list. Never query or wait on the window."""
        refs = getattr(self, "_tab_refs", None)
        if not isinstance(refs, list):
            return
        if 0 <= from_idx < len(refs) and 0 <= to_idx < len(refs):
            refs.insert(to_idx, refs.pop(from_idx))
        order = [id(r()) for r in refs if r() is not None]
        self._manual_order = order
        # BAR_THREAD_20261107: the organizer records the order off the GUI path.
        try:
            _window_organizer().enqueue("order", order)
        except Exception:
            pass

    def _tab_clicked(self, index):
        if index < 0 or index >= len(self._tab_refs):
            return
        try: w=self._tab_refs[index]()
        except Exception: w=None
        mgr=self._manager()
        if mgr is not None and w is not None:
            mgr._pending_restore = w
            # No nested processEvents(): it re-entered every pending event (and any stalled
            # window's work) inside the click. restore_window already re-asserts on the next turn.
            mgr.restore_window(w)
            QTimer.singleShot(0, self.refresh)

    def _quit_requested(self):
        mgr = self._manager()
        if mgr is not None:
            mgr.request_application_exit()
            return
        self._return_to_startup()

    def _return_to_startup(self):
        """Hide the session and show the startup chooser again."""
        mgr = self._manager()
        if mgr is not None and hasattr(mgr, "return_to_startup"):
            mgr.return_to_startup()
            return
        app = QApplication.instance()
        filt = getattr(self, "_main_window_relaunch_filter", None)
        if filt is not None:
            try:
                strip = getattr(filt, "_window_strip", None)
                if strip is not None:
                    strip.hide()
            except Exception:
                pass
            for w in list(getattr(filt, "managed_windows", lambda: [])() or []):
                try:
                    w.hide()
                except Exception:
                    pass
        try:
            self.hide()
        except Exception:
            pass
        try:
            launch_startup_mode_selector(self, app, skip=False, force_chooser=True)
        except Exception as exc:
            print(f"[Quit] startup relaunch failed: {exc}")
            try:
                self.show()
            except Exception:
                pass

    def closeEvent(self, event):
        try:
            self._save_session_layout()
        except Exception:
            pass
        if self._startup_blocked():
            try:
                event.ignore()
                self.hide()
            except Exception:
                pass
            return
        # The recovery strip itself is intentionally persistent. Real shutdown
        # goes through its explicit Quit Groovebox button.
        mgr=self._manager()
        if mgr is not None and not getattr(mgr, "_shutdown", False):
            try: event.ignore(); self.show()
            except Exception: pass
            return
        try: event.accept()
        except Exception: pass

    def showEvent(self, event):
        try: super().showEvent(event)
        except Exception: pass
        QTimer.singleShot(0, self._place_on_screen)

class _MainWindowRelaunchFilter(QObject):
    """Adds one lightweight 'Return to Main Window' control to Groovebox subwindows.

    Installed once on QApplication so dynamically-created dialogs/windows receive
    the same control automatically.  The button only reveals/activates the
    already-running main Groovebox window; it never starts a duplicate process.
    """

    _BUTTON_NAME = "grooveboxRelaunchMainWindowButton"

    def __init__(self, main_window):
        super().__init__(main_window)
        self._main_ref = weakref.ref(main_window)
        # Keep every opened Groovebox tool window alive for the app session.
        # This is the taskbar/session layer that minimal Labwc does not provide.
        self._managed_windows = {}
        self._shutdown = False
        self._window_strip = None

    @staticmethod
    def _eligible_window(obj):
        # Include every Groovebox-owned top-level QWidget, not only dialogs and
        # main windows. Several editors (Blueprint, clip tools, browsers) are
        # plain QWidget windows and otherwise disappear from the session manager.
        if not isinstance(obj, QWidget):
            return False
        # Only inject into true top-level windows — not widgets embedded inside
        # a QTabWidget page (which are dialogs/windows reparented into a tab).
        try:
            if not obj.isWindow():
                return False
        except Exception:
            pass
        # Native utility dialogs are deliberately left untouched; their platform
        # layouts are not owned by Groovebox.  All Groovebox-created dialogs and
        # top-level windows are covered, including dynamically-created ones.
        if isinstance(obj, (QMessageBox, QFileDialog, QInputDialog, QColorDialog, QMenu)):
            return False
        try:
            # R32.9: dropdown lists, menus, tooltips, completers and other popups are top-level windows to Qt —
            # they used to get a "Return to Main Window" button (it showed up under many dropdowns).
            wt = obj.windowType()
            if wt in (Qt.WindowType.Popup, Qt.WindowType.ToolTip, Qt.WindowType.SplashScreen, Qt.WindowType.Drawer,
                      Qt.WindowType.Tool, Qt.WindowType.SubWindow, Qt.WindowType.Desktop):
                return False
            _cn = obj.metaObject().className() if hasattr(obj, "metaObject") else type(obj).__name__
            if _cn in ("QComboBoxPrivateContainer", "QComboBoxListView", "QCompleter", "QTipLabel", "QListView",
                       "QTreeView", "QCalendarPopup", "QColorPickingDialog") or obj.property("grooveboxTouchKeyboard"):
                return False
        except Exception:
            pass
        try:
            if bool(obj.property("grooveboxExternalWindowStrip")):
                return False
            if bool(obj.property("grooveboxStartupSelector")):
                return False
            if bool(obj.property("grooveboxNoReturnButton")):
                return False
            try:
                title = (obj.windowTitle() or "").casefold()
                if any(k in title for k in ("modular patch bay", "patch bay", "patch modular")):
                    return False
            except Exception:
                pass
            # R14: Chromium/QtWebEngine can create transient native helper windows.
            # Never session-manage or relaunch/focus those as Groovebox tool windows.
            cname=(obj.metaObject().className() if hasattr(obj,'metaObject') else obj.__class__.__name__) or ''
            mod=(obj.__class__.__module__ or '')
            if 'WebEngine' in cname or 'QtWebEngine' in mod or 'Chromium' in cname:
                return False
        except Exception:
            pass
        return True

    def _register_window(self, window):
        main = self._main_ref()
        if self._shutdown or window is None or window is main or not self._eligible_window(window):
            return
        key = int(id(window))
        if key in self._managed_windows:
            return
        try:
            window.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, False)
            window.setProperty("grooveboxSessionManaged", True)
        except Exception:
            pass
        # No destroyed() hook: managed_windows() prunes dead wrappers lazily, and a Python slot
        # firing inside ~QWidget after sip released the wrapper segfaults the interpreter.
        self._managed_windows[key] = window

    def ensure_window_strip(self):
        if self._shutdown:
            return None
        if globals().get("_GROOVEBOX_STARTUP_ACTIVE"):
            strip = self._window_strip
            if strip is not None:
                try:
                    strip.hide()
                except Exception:
                    pass
            return None
        strip=self._window_strip
        try:
            if strip is None:
                embedded = os.environ.get("GROOVEBOX_USER_SESSION") != "1"
                main = self._main_ref()
                if embedded and main is not None and hasattr(main, "addToolBar"):
                    strip=_GrooveboxWindowStrip(self, embedded=True)
                    from PyQt6.QtWidgets import QToolBar as _QToolBar
                    tb = _QToolBar("Groovebox Windows", main)
                    tb.setObjectName("grooveboxWindowBar"); tb.setMovable(False); tb.setFloatable(False)
                    tb.setFixedHeight(28)
                    tb.setMinimumHeight(26)
                    tb.setMaximumHeight(30)
                    strip.setFixedHeight(26)
                    tb.addWidget(strip)
                    main.addToolBar(Qt.ToolBarArea.TopToolBarArea, tb)
                    self._window_bar_toolbar = tb
                else:
                    strip=_GrooveboxWindowStrip(self)
                self._window_strip=strip
            strip._place_on_screen()
            strip.show()
            strip._place_on_screen()
            strip.refresh()
            return strip
        except Exception:
            return None

    def _notify_strip(self):
        strip=self._window_strip
        if strip is None or getattr(self, "_strip_refresh_pending", False):
            return
        # Coalesce the burst of Show/Resize/Activate/StateChange into one refresh,
        # and wait a little longer so a flurry of window events cannot stall switchover.
        self._strip_refresh_pending = True

        def _go():
            self._strip_refresh_pending = False
            try:
                strip.refresh()
            except Exception:
                pass
        try:
            QTimer.singleShot(40, _go)  # WINDOW_STRIP_20261107: snappier tab refresh
        except Exception:
            self._strip_refresh_pending = False

    def _listable_window(self, w):
        """GROOVEBOX_R23R_WINDOW_BAR_ANY_WINDOW_20261103: the window bar lists
        EVERY real top-level window the app shows - Groovebox tools, games,
        players, plain QWidget windows, message boxes, file pickers, progress
        and batch-export windows - not only session-managed QDialog/QMainWindow
        ones. Popups, menus, tooltips, splash screens, the bar itself, the
        startup chooser and WebEngine helper surfaces are excluded."""
        try:
            if w is None or not w.isWindow() or w is self._window_strip:
                return False
            if isinstance(w, (QMenu,)) or bool(w.property("grooveboxExternalWindowStrip")) \
                    or bool(w.property("grooveboxStartupSelector")):
                return False
            wt = w.windowType()
            if wt in (Qt.WindowType.Popup, Qt.WindowType.ToolTip, Qt.WindowType.SplashScreen,
                      Qt.WindowType.Desktop, Qt.WindowType.Drawer):
                return False
            cname = (w.metaObject().className() or "") if hasattr(w, "metaObject") else ""
            mod = w.__class__.__module__ or ""
            if "WebEngine" in cname or "QtWebEngine" in mod or "Chromium" in cname or cname.startswith("QComboBox"):
                return False
            if w.width() < 40 or w.height() < 24:
                return False
            return True
        except Exception:
            return False

    def _bounce_others_above_main(self):
        """Keep the main window under every other Groovebox window."""
        if getattr(self, "_bouncing", False):
            return
        self._bouncing = True
        try:
            main = self._main_ref()
            for w in list(self.session_windows()):
                if w is None or w is main:
                    continue
                try:
                    if w.isVisible() and not w.isMinimized():
                        w.raise_()
                except Exception:
                    pass
        finally:
            self._bouncing = False

    def session_windows(self):
        out=[]
        main=self._main_ref()
        if main is not None:
            out.append(main)
        for w in self.managed_windows():
            if w is not None and w is not self._window_strip and w not in out:
                out.append(w)
        # R32.8: windows of external processes Groovebox started (file media player, decks)
        try:
            import ext_windows as _xw
            if not getattr(self, "_xw_hooked", False):
                _xw.on_change(self._notify_strip); self._xw_hooked = True
            for w in _xw.windows():
                if w not in out:
                    out.append(w)
        except Exception:
            pass
        # Any other live top-level window (visible or minimized) is listed too,
        # so nothing - e.g. a batch export or game window - can be lost.
        try:
            for w in QApplication.topLevelWidgets():
                if w in out or not self._listable_window(w):
                    continue
                try:
                    if w.isVisible() or w.isMinimized():
                        out.append(w)
                except RuntimeError:
                    continue
        except Exception:
            pass
        return out

    SOS_POWEROFF_EXIT_CODE = 99

    def emergency_poweroff(self):
        """Non-modal power-off path used by the six-second Quit hold."""
        main=self._main_ref()
        if os.environ.get("GROOVEBOX_USER_SESSION") == "1":
            # Use the documented sOS supervisor exit code; its PID-1 session
            # launcher performs sync + poweroff after the app process exits.
            try:
                if main is not None and hasattr(main,"_autosave_project"):
                    main._autosave_project()
            except Exception as exc:
                print(f"[Quit] hold autosave skipped: {exc}")
            try: self.prepare_for_application_exit()
            except Exception: pass
            QApplication.exit(self.SOS_POWEROFF_EXIT_CODE)
        else:
            # Desktop systems should never be powered off by an application button.
            try: QApplication.quit()
            except Exception: pass

    def request_application_exit(self):
        """Quit Groovebox.

        Desktop: returns to the startup chooser (unchanged).
        sOS appliance (GROOVEBOX_USER_SESSION=1): after confirmation, autosave,
        tear down and exit with code 99; the root session launcher passes it to
        PID-1 /init, which syncs and powers the machine off
        (GROOVEBOX_R23R_QUIT_POWEROFF_20261031).
        """
        main = self._main_ref()
        if os.environ.get("GROOVEBOX_USER_SESSION") == "1":
            # GROOVEBOX_R23R_QUIT_TO_STARTUP_20261103: power off OR go back to
            # the startup chooser (restart the session without rebooting).
            try:
                box = QMessageBox(main)
                box.setWindowTitle("Quit Groovebox")
                box.setText("Power off this computer, or go back to the startup screen?\n\nThe project is autosaved first.")
                b_off = box.addButton("Power off", QMessageBox.ButtonRole.AcceptRole)
                b_start = box.addButton("Back to startup screen", QMessageBox.ButtonRole.ActionRole)
                box.addButton(QMessageBox.StandardButton.Cancel)
                box.setDefaultButton(b_start)
                box.exec()
                clicked = box.clickedButton()
            except Exception:
                clicked = None
                b_off = b_start = object()
            if clicked is b_start:
                self.return_to_startup()
                return
            if clicked is not b_off:
                return
            try:
                if main is not None and hasattr(main, "_autosave_project"):
                    main._autosave_project()
            except Exception as exc:
                print(f"[Quit] autosave before power-off failed: {exc}")
            try:
                self.prepare_for_application_exit()
            except Exception:
                pass
            try:
                if main is not None and hasattr(main, "stop_playback"):
                    main.stop_playback()
            except Exception:
                pass
            QApplication.exit(self.SOS_POWEROFF_EXIT_CODE)
            return
        # Desktop: ask (parented to the main window so the prompt is never hidden).
        try:
            box = QMessageBox(main)
            box.setWindowTitle("Quit Groovebox")
            box.setText("Quit Groovebox?\n\nThe project is autosaved first.")
            b_quit = box.addButton("Quit to desktop", QMessageBox.ButtonRole.AcceptRole)
            b_start = box.addButton("Back to startup chooser", QMessageBox.ButtonRole.ActionRole)
            box.addButton(QMessageBox.StandardButton.Cancel)
            box.setDefaultButton(b_quit)
            box.exec()
            clicked = box.clickedButton()
        except Exception:
            clicked = None
            b_quit = b_start = object()
        if clicked is b_start:
            # (Was main._return_to_startup, which never existed on the main
            # window, so this choice silently did nothing.)
            self.return_to_startup()
            return
        if clicked is not b_quit:
            return
        try:
            if main is not None and hasattr(main, "_autosave_project"):
                main._autosave_project()
        except Exception as exc:
            print(f"[Quit] autosave failed: {exc}")
        try:
            if main is not None and hasattr(main, "stop_playback"):
                main.stop_playback()
        except Exception:
            pass
        try:
            self.prepare_for_application_exit()
        except Exception:
            pass
        try:
            QApplication.quit()
        except Exception:
            pass

    def return_to_startup(self):
        """Autosave, stop audio, hide every session window and show the startup
        chooser again; the chosen mode then reopens the session."""
        main = self._main_ref()
        if main is None:
            return
        try:
            if hasattr(main, "_autosave_project"):
                main._autosave_project()
        except Exception as exc:
            print(f"[Quit] autosave before startup chooser failed: {exc}")
        try:
            if hasattr(main, "stop_playback"):
                main.stop_playback()
        except Exception:
            pass
        strip = self._window_strip
        if strip is not None:
            try:
                strip.hide()
            except Exception:
                pass
        for w in list(self.session_windows()):
            if w is main:
                continue
            try:
                w.hide()
            except Exception:
                pass
        try:
            main.hide()
        except Exception:
            pass

        def _launch():
            try:
                launch_startup_mode_selector(main, QApplication.instance(), skip=False)
            except Exception as exc:
                print(f"[Quit] startup chooser failed: {exc}")
                try:
                    _gb_log_error("quit · back to startup chooser", exc)
                except Exception:
                    pass
                try:
                    main.show(); self.ensure_window_strip()
                except Exception:
                    pass
        QTimer.singleShot(0, _launch)

    def managed_windows(self):
        out=[]
        for key,w in list(self._managed_windows.items()):
            try:
                _=w.windowTitle(); out.append(w)
            except RuntimeError:
                self._managed_windows.pop(key,None)
            except Exception:
                out.append(w)
        return out

    def restore_window(self, window):
        """Bring a window forward without waiting on any other (possibly frozen) window.
        SMOOTH_SWITCH_20261107: the bar never queries the target. A frozen window
        cannot delay the switch.

        WINDOW_SWITCH_FAST_20261106: the switch is fire-and-forget. We never call
        processEvents, never query other windows, and never re-enter restore.
        A frozen tool cannot delay the main window (or any other target).
        """
        if window is None:
            return
        self._pending_restore = window
        try:
            self._register_window(window)
        except Exception:
            pass
        try:
            window.setWindowState(Qt.WindowState.WindowNoState)
        except Exception:
            pass
        try:
            if window.isMinimized():
                window.showNormal()
            else:
                window.show()
        except Exception:
            try:
                window.show()
            except Exception:
                return
        try:
            window.raise_()
            window.activateWindow()
        except Exception:
            pass
        try:
            h = window.windowHandle()
            if h is not None and hasattr(h, "requestActivate"):
                h.requestActivate()
        except Exception:
            pass
        # FOCUS_STREAM_20261107: a focus change adjusts the streamable budget.
        # A performance/player/export window gets the full migratory count;
        # a settings or idle window keeps the small budget.
        try:
            title = (window.windowTitle() or window.__class__.__name__).casefold()
            stream = any(k in title for k in ("performance", "player", "export", "stage", "video"))
            # STREAMABLE_FOCUS_20261107: Streamable only unlocks the 14.
            # Focus notes the activity so the follower gives them to the
            # window you are in. The checkbox is not touched.
            try:
                act = "export" if "export" in title else ("play" if any(k in title for k in ("performance", "player", "stage")) else "browse")
                _activity_follower().note(act)
            except Exception:
                pass
        except Exception:
            pass
        # One deferred re-assert only, and only if this is still the pending target.
        def again():
            try:
                if getattr(self, "_pending_restore", None) is not window:
                    return
                window.raise_()
                window.activateWindow()
            except Exception:
                pass
        try:
            QTimer.singleShot(0, again)
        except Exception:
            pass
        self._notify_strip()

    def close_window(self, window, force=False):
        """WINDOW_TABS_LAG_20261102: close a tool window even if it is stalled.

        hide() never waits for the window's own code. Its timers are stopped so a busy poller cannot keep it
        busy, and ``force`` also drops it from the session list and schedules its deletion. Never raises.
        """
        if window is None:
            return False
        try: window.hide()
        except Exception: pass
        try:
            for t in window.findChildren(QTimer):
                t.stop()
        except Exception:
            pass
        if force:
            try:
                for key, w in list(self._managed_windows.items()):
                    if w is window:
                        self._managed_windows.pop(key, None)
                window.deleteLater()
            except Exception:
                pass
        self._notify_strip()
        return True

    def restore_all_windows(self, exclude=()):
        excluded=set(exclude or ())
        for w in self.managed_windows():
            if w in excluded: continue
            try:
                if (not w.isVisible()) or w.isMinimized(): self.restore_window(w)
            except Exception: pass

    def prepare_for_application_exit(self):
        self._shutdown=True
        strip=self._window_strip
        if strip is not None:
            try: strip._timer.stop(); strip.hide()
            except Exception: pass

    def _button_for(self, window):
        try:
            button = window.findChild(QPushButton, self._BUTTON_NAME)
            if button is not None:
                return button
            button = QPushButton("↩ Return to Main Window", window)
            button.setObjectName(self._BUTTON_NAME)
            button.setToolTip(
                "Show and activate the already-running Mathematician's Groovebox main window. "
                "This does not launch a duplicate process or close this subwindow."
            )
            button.setAutoDefault(False)
            button.setDefault(False)
            button.setMinimumWidth(178)
            button.setMaximumHeight(30)
            button.setStyleSheet(
                "QPushButton#grooveboxRelaunchMainWindowButton {"
                " background: rgba(28,28,28,220); color: #d8d8d8;"
                " border: 1px solid #777; border-radius: 4px; padding: 4px 9px; }"
                "QPushButton#grooveboxRelaunchMainWindowButton:hover {"
                " background: rgba(52,52,52,235); color: #f2f2f2; border-color: #aaa; }"
            )
            # R12_RETURN_MAIN_FIX: bind the button to its owning tool window.
            # Relying on QApplication.activeModalWidget() made the control appear
            # inert on ordinary non-modal pages because the source window stayed
            # raised over Main. Hide/exit the actual source first, then restore Main.
            button.clicked.connect(lambda _checked=False, _window=window: self._relaunch_main(_window))
            button.show()
            button.raise_()
            return button
        except Exception:
            return None

    def _reserve_button_space(self, window, button, margin=10):
        """Reserve a real navigation strip so the return button never covers UI.

        Older builds floated the button over the top-right of every dialog.  That
        made it universal, but compact dialogs (notably Export Parameters) could
        place a spinbox/label underneath it.  Keep the universal overlay approach
        while padding the *owned* content layout below a dedicated top strip.
        Margins are captured once and never accumulate across Show/Resize events.
        """
        try:
            target = window
            layout = window.layout()
            # QMainWindow owns an internal layout; reserve space on its central
            # widget instead of mutating Qt's private main-window layout.
            if isinstance(window, QMainWindow):
                central = window.centralWidget()
                if central is not None and central.layout() is not None:
                    target = central
                    layout = central.layout()
            if layout is None:
                return

            key = "_grooveboxRelaunchOriginalMargins"
            original = getattr(window, key, None)
            if original is None:
                m = layout.contentsMargins()
                original = (int(m.left()), int(m.top()), int(m.right()), int(m.bottom()))
                setattr(window, key, original)

            left, top, right, bottom = original
            button.adjustSize()
            required_top = max(top, int(margin + button.height() + 8))
            current = layout.contentsMargins()
            if (int(current.left()), int(current.top()), int(current.right()), int(current.bottom())) != (left, required_top, right, bottom):
                layout.setContentsMargins(left, required_top, right, bottom)

            # Preserve the dialog's former usable content height where practical.
            # Do this once only; repeated resize/show events must never grow it.
            grow_key = "_grooveboxRelaunchHeightReserved"
            if not bool(getattr(window, grow_key, False)):
                setattr(window, grow_key, True)
                delta = max(0, required_top - top)
                if delta:
                    try:
                        screen = window.screen() or QApplication.primaryScreen()
                        avail_h = int(screen.availableGeometry().height()) if screen else 0
                        desired = int(window.height()) + delta
                        if avail_h > 0:
                            desired = min(desired, max(int(window.height()), avail_h - 24))
                        window.resize(int(window.width()), desired)
                    except Exception:
                        pass
        except Exception:
            pass

    def _position_button(self, window):
        button = self._button_for(window)
        if button is None:
            return
        try:
            button.adjustSize()
            margin = 10
            self._reserve_button_space(window, button, margin)
            x = max(margin, int(window.width()) - int(button.width()) - margin)
            # The button still uses absolute positioning for universal coverage,
            # but the content layout now begins below a reserved navigation strip.
            button.move(x, margin)
            button.raise_()
        except Exception:
            pass

    def _relaunch_main(self, source_window=None):
        main = self._main_ref()
        if main is None:
            return
        # R12: always release the window that owns the button, not merely the
        # currently-active modal widget. This fixes Return-to-Main on the many
        # top-level non-modal tool pages used by Groovebox.
        source = source_window
        try:
            if source is None:
                source = QApplication.activeModalWidget() or QApplication.activeWindow()
            if source is not None and source is not main and self._eligible_window(source):
                try: source.setWindowModality(Qt.WindowModality.NonModal)
                except Exception: pass
                if isinstance(source, QDialog) and bool(source.isModal()):
                    # Keep the historical v35.22zv modal-loop contract literal
                    # while closing the button-owning source dialog correctly.
                    modal = source
                    try: modal.done(0)
                    except Exception: source.hide()
                else:
                    source.hide()
        except Exception:
            pass
        self.restore_window(main)
        try:
            main.showNormal() if main.isMinimized() else main.show()
            main.raise_(); main.activateWindow()
        except Exception:
            pass

    _WINDOW_EVENTS = frozenset((QEvent.Type.Show, QEvent.Type.Hide, QEvent.Type.Close, QEvent.Type.Resize,
                                QEvent.Type.WindowActivate, QEvent.Type.WindowStateChange,
                                QEvent.Type.WindowTitleChange))

    def eventFilter(self, obj, event):
        try:
            et=event.type()
            if et not in self._WINDOW_EVENTS:
                return False   # app-wide filter: paint/mouse/timer events never need the manager
            main = self._main_ref()
            # Closing Main is now session-safe: hide it and leave the external
            # strip alive. Only explicit Quit Groovebox performs teardown.
            if main is not None and obj is main:
                if et == QEvent.Type.Close and not self._shutdown:
                    event.ignore(); main.hide(); self.ensure_window_strip(); self._notify_strip()
                    return True
                if et in (QEvent.Type.Show, QEvent.Type.Hide, QEvent.Type.WindowStateChange, QEvent.Type.WindowActivate):
                    self._notify_strip()
                if et == QEvent.Type.WindowActivate and not getattr(self, "_bouncing", False):
                    QTimer.singleShot(0, self._bounce_others_above_main)
                return False

            if main is not None and self._eligible_window(obj):
                if et in (QEvent.Type.Show,QEvent.Type.Resize,QEvent.Type.WindowActivate,QEvent.Type.Close,QEvent.Type.Hide,QEvent.Type.WindowStateChange):
                    self._register_window(obj)
                if et == QEvent.Type.Close and not self._shutdown:
                    # Uniform session semantics for every Groovebox-owned tool:
                    # X means hide/preserve, never destroy the live session.
                    event.ignore(); obj.hide(); self.ensure_window_strip(); self._notify_strip()
                    return True
                if et in (QEvent.Type.Show,QEvent.Type.Resize,QEvent.Type.WindowActivate):
                    self._position_button(obj)
                if et in (QEvent.Type.Show,QEvent.Type.Hide,QEvent.Type.WindowStateChange,QEvent.Type.WindowActivate):
                    self._notify_strip()
            elif main is not None and et in (QEvent.Type.Show, QEvent.Type.Hide, QEvent.Type.WindowStateChange,
                                             QEvent.Type.WindowTitleChange) \
                    and isinstance(obj, QWidget) and obj.isWindow() and self._listable_window(obj):
                self._notify_strip()
        except Exception:
            pass
        return False


class VoxelSliceCanvas(QWidget):
    """Indexed X/Y editor for one Z plane of the project-owned voxel model."""
    def __init__(self, owner, parent=None):
        super().__init__(parent)
        self.owner = owner
        # Let the voxel scene shrink/grow with its splitter and parent panel.
        self.setMinimumSize(220, 220)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.setMouseTracking(True)

    def _geom(self):
        n = max(1, int(self.owner.grid_size()))
        side = float(min(self.width(), self.height()))
        cell = side / n
        return n, cell

    def paintEvent(self, event):
        with owned_painter(self) as p:
            if p is None:
                return
            alias = int(getattr(self.owner.app, 'voxel_alias_pct', 0) or 0)
            p.setRenderHint(QPainter.RenderHint.Antialiasing, alias > 0)
            p.fillRect(self.rect(), QColor(10, 12, 16))
            n, cell = self._geom()
            z = int(self.owner.z_spin.value())
            records = self.owner.records()
            for (x, y, zz), rgba in records.items():
                if int(zz) != z or not (0 <= x < n and 0 <= y < n):
                    continue
                r, g, b, a = rgba
                pad = (alias / 100.0) * min(2.2, cell * 0.10)
                rect = QRectF(x * cell + pad, y * cell + pad,
                              max(1.0, cell - 2*pad), max(1.0, cell - 2*pad))
                p.fillRect(rect, QColor(int(r), int(g), int(b), int(a)))
            p.setPen(QPen(QColor(70, 78, 88), 1))
            for i in range(n + 1):
                q = i * cell
                p.drawLine(QPointF(q, 0), QPointF(q, n * cell))
                p.drawLine(QPointF(0, q), QPointF(n * cell, q))
            p.setPen(QPen(QColor(245, 217, 125), 1))
            p.drawText(8, 18, f'X/Y INDEX · Z {z} · {len(records)} voxels · Alias {alias}%')

    def _paint_at(self, event, button=None):
        n, cell = self._geom()
        pos = event.position()
        x = int(pos.x() // cell); y = int(pos.y() // cell); z = int(self.owner.z_spin.value())
        if not (0 <= x < n and 0 <= y < n and 0 <= z < n):
            return
        b = button if button is not None else event.button()
        erase = (b == Qt.MouseButton.RightButton)
        self.owner.paint_cell(x, y, z, erase=erase)

    def mousePressEvent(self, event):
        try:
            if not getattr(self.owner.app, '_undo_in_flight', False):
                self.owner.app._push_undo('Voxel color draw/erase')
        except Exception:
            pass
        self._paint_at(event)

    def mouseMoveEvent(self, event):
        buttons = event.buttons()
        if buttons & Qt.MouseButton.LeftButton:
            self._paint_at(event, Qt.MouseButton.LeftButton)
        elif buttons & Qt.MouseButton.RightButton:
            self._paint_at(event, Qt.MouseButton.RightButton)


class VoxelModelPreview(QWidget):
    """Always-visible full-model reference while a particular Z slice is edited."""
    def __init__(self, owner, parent=None):
        super().__init__(parent)
        self.owner = owner
        # Preview is a true resizable scene; its projection is recalculated from
        # the current widget dimensions on every paint.
        self.setMinimumSize(220, 220)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)

    def paintEvent(self, event):
        with owned_painter(self) as p:
            if p is None:
                return
            alias = int(getattr(self.owner.app, 'voxel_alias_pct', 0) or 0)
            p.setRenderHint(QPainter.RenderHint.Antialiasing, alias > 0)
            p.fillRect(self.rect(), QColor(8, 10, 14))
            records = self.owner.records()
            n = max(1, self.owner.grid_size())
            zsel = int(self.owner.z_spin.value())
            p.setPen(QPen(QColor(245, 217, 125), 1))
            p.drawText(10, 20, f'FULL MODEL REFERENCE · selected Z {zsel}')
            if not records:
                p.setPen(QPen(QColor(145, 155, 170), 1))
                p.drawText(10, 44, 'Draw, voxelize video, or import a model to populate the preview.')
                return
            scale = min(self.width(), self.height()) / max(8.0, n * 2.15)
            ox = self.width() * 0.50
            oy = self.height() * 0.64
            # Render back-to-front so the complete object remains readable.
            items = sorted(records.items(), key=lambda kv: (sum(kv[0]), kv[0][2], kv[0][1], kv[0][0]))
            for (x, y, z), rgba in items[:30000]:
                r, g, b, a = rgba
                xx = (x - y) * scale * 0.90 + ox
                yy = (x + y) * scale * 0.45 - z * scale + oy
                size = max(2.0, scale * (0.66 - 0.18 * alias / 100.0))
                alpha = int(max(18, min(255, a if z == zsel else a * 0.58)))
                rect = QRectF(xx - size/2, yy - size/2, size, size)
                p.fillRect(rect, QColor(int(r), int(g), int(b), alpha))
                if z == zsel:
                    p.setPen(QPen(QColor(255, 238, 170, 210), max(1.0, scale * 0.08)))
                    p.drawRect(rect)
            # Project the four corners of the currently indexed Z plane for reference.
            corners = [(0,0,zsel),(n-1,0,zsel),(n-1,n-1,zsel),(0,n-1,zsel),(0,0,zsel)]
            pts=[]
            for x,y,z in corners:
                pts.append(QPointF((x-y)*scale*.90+ox, (x+y)*scale*.45-z*scale+oy))
            p.setPen(QPen(QColor(245, 217, 125, 150), 1))
            for a,b in zip(pts[:-1], pts[1:]): p.drawLine(a,b)


class VoxelDrawKitPanel(QWidget):
    """Embedded Draw/Record voxel editor with color, blend, alias and full-model reference."""
    DEFAULT_RGBA = (80, 220, 200, 220)

    def __init__(self, app, parent=None):
        super().__init__(parent)
        self.app = app
        root = QVBoxLayout(self)
        root.setContentsMargins(8, 8, 8, 8)
        title = QLabel('<b>3D VOXEL DRAW / RECORD</b> — paint in color on indexed X/Y slices; right-click erases. The full model stays visible at right.')
        title.setWordWrap(True); root.addWidget(title)

        ctl = QHBoxLayout()
        ctl.addWidget(QLabel('Grid:'))
        self.grid_spin = QSpinBox(); self.grid_spin.setRange(4, 64)
        self.grid_spin.setValue(int(getattr(app, 'voxel_grid_size', 16) or 16))
        self.grid_spin.valueChanged.connect(self._grid_changed); ctl.addWidget(self.grid_spin)
        ctl.addWidget(QLabel('Z slice:'))
        self.z_spin = QSpinBox(); self.z_spin.setRange(0, max(0, self.grid_spin.value()-1))
        self.z_spin.valueChanged.connect(self._slice_changed); ctl.addWidget(self.z_spin)
        ctl.addSpacing(8)
        ctl.addWidget(QLabel('Voxel Color:'))
        self.color_btn = QPushButton('Choose…'); self.color_btn.clicked.connect(self._choose_color); ctl.addWidget(self.color_btn)
        self._sync_color_button()
        ctl.addStretch(1); root.addLayout(ctl)

        blend_row = QHBoxLayout()
        blend_row.addWidget(QLabel('Voxel Blend:'))
        self.blend_slider = QSlider(Qt.Orientation.Horizontal); self.blend_slider.setRange(0,100)
        self.blend_slider.setValue(int(getattr(app, 'voxel_paint_blend_pct', 86) or 86))
        self.blend_slider.setToolTip('Per-voxel alpha/blend for new paint. Existing voxel colors keep their own stored blend.')
        self.blend_slider.sliderPressed.connect(lambda: (not getattr(self.app, '_undo_in_flight', False)) and self.app._push_undo('Voxel paint blend'))
        self.blend_label = QLabel(f'{self.blend_slider.value()}%')
        self.blend_slider.valueChanged.connect(self._blend_changed)
        blend_row.addWidget(self.blend_slider, 1); blend_row.addWidget(self.blend_label)
        blend_row.addSpacing(18); blend_row.addWidget(QLabel('Overall Alias:'))
        self.alias_slider = QSlider(Qt.Orientation.Horizontal); self.alias_slider.setRange(0,100)
        self.alias_slider.setValue(int(getattr(app, 'voxel_alias_pct', 0) or 0))
        self.alias_slider.setToolTip('Global voxel/model edge smoothing. 0 = crisp blocks; 100 = maximum smoothing. Saved with project and exports.')
        self.alias_label = QLabel(f'{self.alias_slider.value()}%')
        self.alias_slider.sliderPressed.connect(lambda: (not getattr(self.app, '_undo_in_flight', False)) and self.app._push_undo('Voxel Overall Alias'))
        self.alias_slider.valueChanged.connect(self._alias_changed)
        blend_row.addWidget(self.alias_slider, 1); blend_row.addWidget(self.alias_label)
        root.addLayout(blend_row)

        # --- horizontal splitter with scrollable sections ---
        split = QSplitter(Qt.Orientation.Horizontal, self)

        # left section: voxel slice canvas
        self.canvas_scroll = QScrollArea(split)
        self.canvas_scroll.setWidgetResizable(True)
        self.canvas_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.canvas_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.canvas = VoxelSliceCanvas(self, self.canvas_scroll)
        self.canvas_scroll.setWidget(self.canvas)

        # right section: voxel model preview
        self.preview_scroll = QScrollArea(split)
        self.preview_scroll.setWidgetResizable(True)
        self.preview_scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.preview_scroll.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
        self.preview = VoxelModelPreview(self, self.preview_scroll)
        self.preview_scroll.setWidget(self.preview)

        split.addWidget(self.canvas_scroll); split.addWidget(self.preview_scroll)
        split.setChildrenCollapsible(False)
        split.setHandleWidth(8)
        split.setStretchFactor(0, 1); split.setStretchFactor(1, 1)
        split.setSizes([560, 560])
        self.scene_splitter = split
        root.addWidget(split, 1)

        self.model_ref = QLabel('Model reference: ' + (os.path.basename(str(getattr(app,'imported_3d_model_path','') or '')) or 'none'))
        self.model_ref.setWordWrap(True); root.addWidget(self.model_ref)

        row = QHBoxLayout()
        buttons = [
            ('Import 3D Model…', app.import_3d_model_dialog),
            ('Import Video…', app.load_media_dialog),
            ('Voxelize Video Frame', self._voxelize_frame),
            ('Export 3D Model…', app.export_3d_model_dialog),
            ('Export Video…', lambda: app.export_video_dialog(include_audio=True, container='mp4')),
            ('Open Viewer…', lambda: app.open_voxel_viewer() if hasattr(app, 'open_voxel_viewer') else None),
            ('Clear Voxels', self._clear),
        ]
        for text, fn in buttons:
            b=QPushButton(text); b.clicked.connect(fn); row.addWidget(b)
        root.addLayout(row)
        self.status = QLabel('Voxel colors + blend are project data and participate in save/load, Undo/Redo, fingerprints, 3D export, video and game rendering.')
        self.status.setWordWrap(True); root.addWidget(self.status)

    def grid_size(self): return int(self.grid_spin.value())

    def records(self):
        out={}
        for c in (getattr(self.app, 'voxel_cells', []) or []):
            rec=self.app._normalize_voxel_record(c) if hasattr(self.app,'_normalize_voxel_record') else None
            if rec is not None: out[tuple(rec[:3])] = tuple(rec[3:7])
        return out

    def _write_records(self, records):
        self.app.voxel_cells = [list(k) + list(records[k]) for k in sorted(records)]
        try: self.app._refresh_canonical_fingerprint()
        except Exception: pass
        self.refresh_views()

    def current_rgba(self):
        rgb=list(getattr(self.app,'voxel_paint_color',[80,220,200]) or [80,220,200])[:3]
        while len(rgb)<3: rgb.append(200)
        a=int(round(255.0 * max(0,min(100,int(getattr(self.app,'voxel_paint_blend_pct',86) or 86))) / 100.0))
        return tuple(max(0,min(255,int(v))) for v in rgb[:3]) + (a,)

    def paint_cell(self, x, y, z, erase=False):
        records=self.records(); key=(int(x),int(y),int(z))
        if erase: records.pop(key, None)
        else: records[key]=self.current_rgba()
        self._write_records(records)

    def refresh_views(self):
        self.canvas.update(); self.preview.update()
        self.model_ref.setText('Model reference: ' + (os.path.basename(str(getattr(self.app,'imported_3d_model_path','') or '')) or 'none'))

    def _slice_changed(self, _v): self.refresh_views()

    def _grid_changed(self, n):
        try:
            if not getattr(self.app, '_undo_in_flight', False): self.app._push_undo('Voxel grid size')
        except Exception: pass
        n=int(n); self.app.voxel_grid_size=n; self.z_spin.setRange(0,max(0,n-1))
        records={k:v for k,v in self.records().items() if all(0 <= int(q) < n for q in k)}
        self._write_records(records)

    def _choose_color(self):
        rgb=list(getattr(self.app,'voxel_paint_color',[80,220,200]) or [80,220,200])[:3]
        while len(rgb)<3: rgb.append(200)
        col=QColorDialog.getColor(QColor(*[int(v) for v in rgb]), self, 'Choose Voxel Paint Color')
        if not col.isValid(): return
        try:
            if not getattr(self.app, '_undo_in_flight', False): self.app._push_undo('Voxel paint color')
        except Exception: pass
        self.app.voxel_paint_color=[col.red(), col.green(), col.blue()]
        self._sync_color_button()

    def _sync_color_button(self):
        rgb=list(getattr(self.app,'voxel_paint_color',[80,220,200]) or [80,220,200])[:3]
        while len(rgb)<3: rgb.append(200)
        self.color_btn.setStyleSheet(f'background-color: rgb({int(rgb[0])},{int(rgb[1])},{int(rgb[2])}); color: {"black" if sum(rgb)>410 else "white"}; font-weight: 700;')

    def _blend_changed(self, v):
        self.app.voxel_paint_blend_pct=int(v); self.blend_label.setText(f'{int(v)}%')

    def _alias_changed(self, v):
        self.app.voxel_alias_pct=int(v); self.alias_label.setText(f'{int(v)}%'); self.refresh_views()
        try: self.app._on_live_source_changed()
        except Exception: pass

    def _voxelize_frame(self):
        try:
            if not getattr(self.app, '_undo_in_flight', False): self.app._push_undo('Voxelize video frame')
            n=self.app._voxelize_imported_video_frame(grid_size=self.grid_size(), z_slice=int(self.z_spin.value()))
            self.status.setText(f'Voxelized video frame in source colors: {n} occupied cells.'); self.refresh_views()
        except Exception as exc: QMessageBox.warning(self, 'Voxelize Video Frame', str(exc))

    def _clear(self):
        try:
            if not getattr(self.app, '_undo_in_flight', False): self.app._push_undo('Clear voxel drawing')
        except Exception: pass
        self._write_records({})


