    def _install_scroll_value_guards(self):
        """Prevent accidental roller/dropdown edits while the user scrolls.

        Spin boxes accept wheel changes only while deliberately focused. Combo
        boxes accept wheel navigation only while their popup is actually open.
        Otherwise the wheel delta is forwarded to the nearest scroll area.
        Leaving a numeric editor releases its focus so page scrolling resumes.
        """
        try:
            widgets = list(self.findChildren((QSpinBox, QDoubleSpinBox, QComboBox)))
        except Exception:
            widgets = []
        for w in widgets:
            try:
                w.installEventFilter(self)
                w.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
            except Exception:
                pass
        # TELEPORT_OUTSIDE_CLICK_DISMISS_20260924: Step and Automation inspectors
        # are independent top-level Tool windows, so Qt does not give them QMenu's
        # automatic outside-click dismissal. Install this main window once as an
        # application filter so any click elsewhere can close them immediately.
        try:
            app = QApplication.instance()
            if app is not None and not getattr(self, "_teleport_app_filter_installed", False):
                app.installEventFilter(self)
                self._teleport_app_filter_installed = True
        except Exception:
            pass

    def _teleport_popup_hit(self, popup, obj, global_pos):
        """Return True when a click belongs to popup or one of its combo views."""
        if popup is None or not popup.isVisible():
            return False
        try:
            w = obj if isinstance(obj, QWidget) else None
            while w is not None:
                if w is popup:
                    return True
                w = w.parentWidget()
        except Exception:
            pass
        try:
            if global_pos is not None and popup.frameGeometry().contains(global_pos):
                return True
        except Exception:
            pass
        # A QComboBox dropdown is a separate top-level Qt.Popup. Treat its view
        # as part of the teleport menu so choosing an Operator/parameter does not
        # dismiss the Automation inspector underneath it.
        try:
            for combo in popup.findChildren(QComboBox):
                view = combo.view()
                if view is None or not view.isVisible():
                    continue
                w = obj if isinstance(obj, QWidget) else None
                while w is not None:
                    if w is view or w is view.window():
                        return True
                    w = w.parentWidget()
                win = view.window()
                if global_pos is not None and win is not None and win.frameGeometry().contains(global_pos):
                    return True
        except Exception:
            pass
        return False

    def _dismiss_teleport_popups_for_click(self, obj, event):
        """Hide Step/Automation teleport inspectors when the click is outside."""
        try:
            gp = event.globalPosition().toPoint()
        except Exception:
            gp = None
        for name in ("step_editor_popup", "automator_teleport_popup"):
            popup = getattr(self, name, None)
            try:
                if popup is not None and popup.isVisible() and not self._teleport_popup_hit(popup, obj, gp):
                    popup.hide()
            except Exception:
                pass

    def _forward_wheel_to_scroll_area(self, obj, event):
        try:
            p = obj.parentWidget() if hasattr(obj, "parentWidget") else None
            while p is not None:
                if isinstance(p, QScrollArea):
                    delta = int(event.angleDelta().y())
                    bar = p.verticalScrollBar()
                    if bar is not None and bar.maximum() > bar.minimum():
                        step = max(bar.singleStep() * 3, 24)
                        bar.setValue(bar.value() - (step if delta > 0 else -step))
                        return True
                    hbar = p.horizontalScrollBar()
                    if hbar is not None and hbar.maximum() > hbar.minimum():
                        step = max(hbar.singleStep() * 3, 24)
                        hbar.setValue(hbar.value() - (step if delta > 0 else -step))
                        return True
                p = p.parentWidget() if hasattr(p, "parentWidget") else None
        except Exception:
            pass
        return False

    def eventFilter(self, obj, event):
        try:
            if event.type() == QEvent.Type.MouseButtonPress:
                self._dismiss_teleport_popups_for_click(obj, event)
            # HARD SCROLL-SAFETY: wheel events never edit parameter widgets,
            # even when focused or when the widget was created after startup.
            # This app-level filter sees dynamic controls too; direct clicking,
            # dragging, keyboard entry and explicit combo-popup selection remain.
            _wheel_value_widgets = (QSlider, QDial, QSpinBox, QDoubleSpinBox, QComboBox)
            if isinstance(obj, _wheel_value_widgets) and event.type() == QEvent.Type.Wheel:
                self._forward_wheel_to_scroll_area(obj, event)
                event.accept()
                return True
            if isinstance(obj, (QSpinBox, QDoubleSpinBox)) and event.type() == QEvent.Type.Leave:
                obj.clearFocus()
        except Exception:
            pass
        return super().eventFilter(obj, event)

    def _sync_square_visuals(self):
        """Square scenograph centred in its gray frame + rectangular side meters.

        GROOVEBOX_R23R_SCENOGRAPH_SQUARE_CENTER_20261103: sizes are derived
        from the bottom scroll viewport (what the user can actually see), not
        from the container itself.  The old pass read container.width() after
        raising child minimum sizes, so every enlargement became the new floor
        and the square ratcheted past the right border after a few resizes.
        Now the minimums are relaxed first, the bottom pane follows the
        viewport, and the scenograph is a FIXED square that the frame centres.
        """
        if getattr(self, "_square_sync_busy", False):
            return
        self._square_sync_busy = True
        try:
            container = getattr(self, "_visual_container", None)
            viewer = getattr(self, "video_synth_viewer", None)
            if container is None or viewer is None:
                return
            meters = [w for w in (getattr(self, "visual_oscilloscope", None), getattr(self, "spectrum_analyzer", None))
                      if w is not None]
            # 1) relax: nothing may hold the row wider/taller than the viewport.
            viewer.setMinimumSize(120, 120)
            viewer.setMaximumSize(16777215, 16777215)
            for w in meters:
                w.setMinimumSize(110, 120)
                w.setMaximumSize(16777215, 16777215)
            scroll = getattr(self, "bottom_render_scroll", None)
            content = scroll.widget() if scroll is not None else None
            if scroll is not None and content is not None:
                if not getattr(self, "_bottom_viewport_filter", None):
                    self._install_bottom_viewport_filter(scroll)
                vp = scroll.viewport()
                # Preserve the requested wide canvas across resize/splitter
                # events. Shrinking the window scrolls it, never resets its floor.
                content.setMinimumSize(0, 0)
                lay0 = content.layout()
                need = lay0.minimumSize() if lay0 is not None else None
                native_floor = getattr(self, "_bottom_content_floor", (2400, 900))
                floor_w = max(native_floor[0], int(need.width()) if need is not None else 2400)
                floor_h = max(native_floor[1], int(need.height()) if need is not None else 900)
                try:
                    _tw = max(floor_w, vp.width())
                    if lay0 is not None and lay0.hasHeightForWidth():
                        floor_h = max(floor_h, int(lay0.heightForWidth(_tw)))
                except Exception:
                    pass
                content.setMinimumSize(floor_w, floor_h)
                content.resize(max(floor_w, vp.width()), max(floor_h, vp.height()))
                lay = content.layout()
                if lay is not None:
                    lay.activate()
            frame = viewer.parentWidget()
            # 2) measure the real space: the frame's share of the row width and
            #    the row height, minus the frame margins/border and the preview
            #    row that sits under the square.
            avail_w = max(320, int(container.width()))
            avail_h = max(180, int(container.height()))
            frame_w = int((avail_w - 16) * 0.50)
            extra_h = 2 + 12 + 2
            pv = getattr(self, "spin_scene_preview_step", None)
            if pv is not None:
                extra_h += max(pv.sizeHint().height(), 24) + 2
            side = max(120, min(avail_h - extra_h, frame_w - 12 - 2))
            # 3) apply: fixed square (cannot be stretched into a rectangle);
            #    the frame keeps a matching minimum so the row never overlaps.
            viewer.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
            viewer.setFixedSize(side, side)
            if frame is not None and frame.objectName() == "scenographFrame":
                frame.setMinimumWidth(side + 14)
                frame.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
            side_w = max(110, (avail_w - 16 - (side + 14)) // 2)
            for w in meters:
                w.setMinimumSize(110, side)
                w.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
            try:
                fr = getattr(viewer, "_frame", None)
                if fr is not None and (fr.width() != side or fr.height() != side):
                    if getattr(viewer, "engine", None):
                        viewer._request_async_frame(side, side, export=False)
                viewer.update()
            except Exception:
                pass
            self._scenograph_side = side
            self._scenograph_side_w = side_w
        except Exception:
            pass
        finally:
            self._square_sync_busy = False

    # ------------------------------------------------------------ panel 2 tools
    def _perf_panel(self):
        """Open (or reuse) Performance and return it."""
        p = getattr(self, "_performance_panel", None)
        if p is None or not p.isVisible():
            self._open_performance()
            p = getattr(self, "_performance_panel", None)
        return p

    def _open_performance_tab(self, label):
        p = self._perf_panel()
        tabs = getattr(p, "_performance_tabs", None) if p is not None else None
        if tabs is None:
            return None
        for i in range(tabs.count()):
            t = tabs.tabText(i)
            if t == label or label.casefold() in t.casefold():
                tabs.setCurrentIndex(i)
                break
        try:
            p.raise_(); p.activateWindow()
        except Exception:
            pass
        return p

    def _perf_call(self, name, *args):
        p = self._perf_panel()
        fn = getattr(p, name, None) if p is not None else None
        if callable(fn):
            return fn(*args)
        raise RuntimeError(f"Performance has no {name}")

    def _open_exports_folder(self):
        d = self._exports_dir()
        p = self._perf_panel()
        try:
            p._open_file_manager()
            fm = getattr(p, "_file_manager_window", None)
            if fm is not None and hasattr(fm, "set_directory"):
                fm.set_directory(str(d))
        except Exception:
            from PyQt6.QtGui import QDesktopServices
            from PyQt6.QtCore import QUrl
            QDesktopServices.openUrl(QUrl.fromLocalFile(str(d)))

    def _r32_open_clip_editor(self):
        w = getattr(self, "_r32_clip_editor", None)
        try:
            if w is not None:
                w.show(); w.raise_(); return w
        except RuntimeError:
            pass
        from clip_timeline_studio import ClipTimelineStudio
        w = self._r32_clip_editor = ClipTimelineStudio(self)
        w.show(); w.raise_()
        return w

