        def _make_entropy_knob(attr, caption, tip):
            dial = QDial(); dial.setRange(0, 100); dial.setValue(50)
            dial.setNotchesVisible(True); dial.setFixedSize(52, 52); dial.setToolTip(tip)
            lbl = QLabel(caption); lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
            lbl.setStyleSheet("color:#c8e8ff; font-size:8pt; font-weight:700;"); lbl.setToolTip(tip)
            box = QVBoxLayout(); box.addWidget(dial, 0, Qt.AlignmentFlag.AlignCenter); box.addWidget(lbl)
            global_fx_layout.addLayout(box)
            dial.valueChanged.connect(lambda _v: self._on_entropy_knob_changed())
            setattr(self, attr, dial)
            return dial
