        # GROOVEBOX_GLOBAL_ALGO_KINDS_20261102: Synth / Mod / Geometric / Sequencer algos.
        global_algo_fill_missing(self.global_algo_state)
        extra_grid = QGridLayout()
        extra_grid.setContentsMargins(0, 0, 0, 0)
        extra_grid.setHorizontalSpacing(6)
        extra_grid.setVerticalSpacing(2)
        self.gp_extra_fields = {}
        self.gp_extra_sliders = {}
        _extra_tips = {
            "synth": "Scales the Edit Synth panel values the project already holds (pitch, amp, morph, ...). Returns a scalar.",
            "mod": "Widens or narrows the algorithm modulation depth for every instrument. Returns a scalar.",
            "geometric": "Scales the Vector / Wavetable / Ball / Cellular instance values every instrument owns, and drives the geometric visuals. Returns a scalar.",
            "sequencer": "Scales the sequence values already written (never adds steps, notes or automation points). Returns a scalar.",
        }
        for _r, _k in enumerate(GLOBAL_ALGO_EXTRA_KINDS):
            _fld = QLineEdit()
            _fld.setText(str(self.global_algo_state.get(_k) or "").replace("\n", " ⏎ "))
            _fld.setPlaceholderText("graph script returning a scalar · t / graph_* ...")
            _fld.setToolTip(GLOBAL_ALGO_EXTRA_LABELS[_k] + ": " + _extra_tips[_k])
            _fld.setFixedHeight(26)
            _sl = QSlider(Qt.Orientation.Horizontal)
            _sl.setRange(0, 100)
            _sl.setValue(int(float((self.global_algo_state.get("params") or {}).get(_k + "_amount", 1.0)) * 100))
            _sl.setToolTip(GLOBAL_ALGO_EXTRA_LABELS[_k] + " amount (0 = off)")
            extra_grid.addWidget(QLabel(GLOBAL_ALGO_EXTRA_LABELS[_k]), _r, 0)
            extra_grid.addWidget(_fld, _r, 1)
            extra_grid.addWidget(_sl, _r, 2)
            extra_grid.setColumnStretch(1, 3)
            extra_grid.setColumnStretch(2, 1)
            self.gp_extra_fields[_k] = _fld
            self.gp_extra_sliders[_k] = _sl
        gp_outer.addLayout(extra_grid)

        def _sync_inline_algo():
            if getattr(self, "_gp_loading_bay", False):
                return
            if getattr(self, "combo_gp_scope", None) is not None and self.combo_gp_scope.currentText() in ("LOCAL", "GROUP"):
                # GROOVEBOX_R23R_INSTRUMENT_BAYS_20261103: edits go to the selected
                # synth's own Local Algorithm bay (or the named row group's bay).
                bay = self._gp_bay()
                bp = bay.setdefault("params", {})
                bp["mix"] = self.gp_mix_slider.value() / 100.0
                bp["script_amount"] = self.gp_script_slider.value() / 100.0
                bp["domain_amount"] = self.gp_domain_slider.value() / 100.0
                bp["wire_amount"] = self.gp_wire_slider.value() / 100.0
                bay["script"] = self.gp_script_field.toPlainText()
                bay["domain"] = self.gp_domain_field.text()
                bay["proposed_from"] = "user"
                if bay.get("apply_enabled") and self.combo_gp_scope.currentText() == "LOCAL":
                    self._apply_local_bays()
                self.__dict__.pop("_row_bend_cache", None)
                return
            params = self.global_algo_state.setdefault("params", {})
            params["mix"] = self.gp_mix_slider.value() / 100.0
            params["script_amount"] = self.gp_script_slider.value() / 100.0
            params["domain_amount"] = self.gp_domain_slider.value() / 100.0
            params["wire_amount"] = self.gp_wire_slider.value() / 100.0
            self.global_algo_state["script"] = self.gp_script_field.toPlainText()
            self.global_algo_state["domain"] = self.gp_domain_field.text()
            for _k in GLOBAL_ALGO_EXTRA_KINDS:
                params[_k + "_amount"] = self.gp_extra_sliders[_k].value() / 100.0
                self.global_algo_state[_k] = self.gp_extra_fields[_k].text().replace(" ⏎ ", "\n")
            hint_text = self._global_domain_hints(self.gp_domain_field.text())
            self.global_algo_state["domain_hints"] = hint_text
            if hasattr(self, "lbl_gp_domain_hints"):
                self.lbl_gp_domain_hints.setText("hints: " + " · ".join(hint_text[:5]))
            self.global_algo_state["apply_enabled"] = bool(self.btn_apply_algo_master.isChecked())
            self.global_algo_state["user_data"] = True
            self.global_algo_state["canonical_superwrite"] = False
            # RHYTHM_MELODY_ALGO_SYNC: persist rhythm/melody playlist algo expressions
            if hasattr(self, "gp_rhythm_gate_field"):
                self.global_algo_state["rhythm"] = {
                    "gate": self.gp_rhythm_gate_field.text(),
                    "offset": getattr(self, "gp_rhythm_offset_field",
                                      type("_", (), {"text": lambda s: ""})()).text(),
                }
            if hasattr(self, "gp_melody_pitch_field"):
                self.global_algo_state["melody"] = {"pitch": self.gp_melody_pitch_field.text()}

        def _apply_master_algo(checked=True):
            if getattr(self, "_gp_loading_bay", False):
                return
            if getattr(self, "combo_gp_scope", None) is not None and self.combo_gp_scope.currentText() == "GROUP":
                if not getattr(self, "_undo_in_flight", False):
                    self._push_undo("Apply Group Algo " + ("ON" if checked else "OFF"))
                _sync_inline_algo()
                self._gp_bay()["apply_enabled"] = bool(checked)
                self.__dict__.pop("_row_bend_cache", None)
                self.btn_apply_algo_master.setText(("■ Unapply " if checked else "▶ Apply ") + "Group Algo")
                self._refresh_canonical_explain()
                try:
                    self._on_live_source_changed()
                except Exception:
                    pass
                return
            if getattr(self, "combo_gp_scope", None) is not None and self.combo_gp_scope.currentText() == "LOCAL":
                if not getattr(self, "_undo_in_flight", False):
                    self._push_undo("Apply Local Algo " + ("ON" if checked else "OFF"))
                _sync_inline_algo()
                bay = self._gp_bay()
                bay["apply_enabled"] = bool(checked)
                self._apply_local_bays()
                if bool((self.global_algo_state or {}).get("apply_enabled")):
                    self._apply_global_algo_to_ensemble("script")   # global overlay skips local synths
                self.btn_apply_algo_master.setText(("■ Unapply " if checked else "▶ Apply ") + "Local Algo")
                self._refresh_gp_local_label()
                try:
                    self._on_live_source_changed()
                except Exception:
                    pass
                return
            _scope_now = self.combo_gp_scope.currentText() if getattr(self, "combo_gp_scope", None) else "GLOBAL"
            # RHYTHM_MELODY_ALGO_APPLY: playlist-scoped rhythm/melody algo write
            if _scope_now in ("RHYTHM", "MELODY"):
                if not getattr(self, "_undo_in_flight", False):
                    self._push_undo(f"Apply {_scope_now} Algo")
                _sync_inline_algo()
                _rm_family = f"playlist_{_scope_now.lower()}"
                if checked:
                    self._register_heuristic_ownership(_rm_family, source="user", strength=1.0)
                    try:
                        self._apply_global_algo_to_ensemble("script", playlist_scope=_scope_now.lower())
                    except Exception:
                        pass
                    try:
                        self._on_live_source_changed()
                    except Exception:
                        pass
                    self.btn_apply_algo_master.setText(f"■ Unapply {_scope_now} Algo")
                    if hasattr(self, "scope_status_label"):
                        self.scope_status_label.setText(
                            f"🎵 {_scope_now} Algo applied to playlist · ownership registered")
                else:
                    self._clear_heuristic_ownership(_rm_family)
                    self.btn_apply_algo_master.setText(f"▶ Apply {_scope_now} Algo to Playlist")
                    if hasattr(self, "scope_status_label"):
                        self.scope_status_label.setText(f"🎵 {_scope_now} Algo unapplied · canonical authority restored")
                return
            if not getattr(self, "_undo_in_flight", False):
                self._push_undo("Apply Global Algo " + ("ON" if checked else "OFF"))
            _sync_inline_algo()
            self.global_algo_state["apply_enabled"] = bool(checked)
            self.global_algo_state["user_data"] = True
            self.global_algo_state["canonical_superwrite"] = False
            if checked:
                for kind, enabled in (("script", self.gp_script_slider.value()>0), ("domain", self.gp_domain_slider.value()>0), ("wire", self.gp_wire_slider.value()>0),
                                      *[(_k, self.gp_extra_sliders[_k].value()>0) for _k in GLOBAL_ALGO_EXTRA_KINDS]):
                    if enabled:
                        self._apply_global_algo_to_ensemble(kind)
                try:
                    self._on_live_source_changed()
                except Exception:
                    pass
                self.btn_apply_algo_master.setText("■ Unapply Algo from Master Mix")
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText("🌐 Algo applied to Master Mix · userdata · canonical superwrite")
            else:
                self._unapply_global_algo_from_ensemble()
                self.btn_apply_algo_master.setText("▶ Apply Algo to Master Mix")
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText("🌐 Master Mix Algo unapplied · canonical state restored")

        self.btn_apply_algo_master.toggled.connect(_apply_master_algo)
        self.combo_gp_scope.setCurrentText("LOCAL" if str(self.global_algo_state.get("scope", "global")).lower() == "local" else "GLOBAL")
        self.combo_gp_scope.currentIndexChanged.connect(lambda _i: self._on_gp_scope_changed())
        self.btn_gp_local_target.clicked.connect(lambda: self._on_gp_scope_changed(retarget=True))
        self._refresh_gp_local_label()
        for sl in (self.gp_mix_slider, self.gp_script_slider, self.gp_domain_slider, self.gp_wire_slider):
            sl.valueChanged.connect(_sync_inline_algo)
        self.gp_script_field.textChanged.connect(_sync_inline_algo)
        self.gp_domain_field.textChanged.connect(_sync_inline_algo)
        for _k in GLOBAL_ALGO_EXTRA_KINDS:
            self.gp_extra_sliders[_k].valueChanged.connect(_sync_inline_algo)
            self.gp_extra_fields[_k].textChanged.connect(_sync_inline_algo)

        self.chk_gp_row_bend = QCheckBox("Bend playlist rows as groups (offset · pitch · level)")
        self.chk_gp_row_bend.setToolTip("The Algorithm never writes parameters — the Heuristic composes the start values. "
                                        "With this on, the applied algorithms (averaged with the canonical fix) bend each "
                                        "playlist row as one group: the apparent step offset moves by the same seconds for "
                                        "every synth in the row, plus a ±1 semitone pitch bend and ±10 % level bend.")
        self.chk_gp_row_bend.setChecked(bool((self.global_algo_state.get("params") or {}).get("row_bend", True)))
        def _rb_toggle(c):
            self.global_algo_state.setdefault("params", {})["row_bend"] = bool(c)
            self.__dict__.pop("_row_bend_cache", None)
            QTimer.singleShot(0, self._refresh_canonical_explain)
        self.chk_gp_row_bend.toggled.connect(_rb_toggle)
        gp_outer.addWidget(self.chk_gp_row_bend)
        # GROOVEBOX_R23R_FREEZE_BEND_20261103
        self.btn_gp_freeze = QPushButton("❄ Freeze bend → start values · OFF")
