        _ptop = QHBoxLayout(); _ptop.addWidget(QLabel("Panel ◀ ▶ Geometric")); self.lbl_geo_panel_mix = QLabel("50 / 50"); _ptop.addStretch(1); _ptop.addWidget(self.lbl_geo_panel_mix)
