    def _sync_canonical_widgets_from_state(self):
        """Project/undo/provenance restore helper; never mutates composition state."""
        level_map = {
            "seeded": ("slider_level_seeded", "lbl_level_seeded"),
            "randomizer": ("slider_level_rand", "lbl_level_rand"),
            "phase_lock": ("slider_level_lock", "lbl_level_lock"),
            "euclidean": ("slider_level_euclidean", "lbl_level_euclidean"),
            "goava": ("slider_level_goava", "lbl_level_goava"),
            "fractal_seed": ("slider_level_fractal_seed", "lbl_level_fractal_seed"),
        }
        for key, (sattr, lattr) in level_map.items():
            val = int(round(self._canonical_level(key) * 100.0))
            w = getattr(self, sattr, None)
            if w is not None:
                try:
                    w.blockSignals(True); w.setValue(val); w.blockSignals(False)
                except Exception: pass
            lab = getattr(self, lattr, None)
            if lab is not None:
                try: lab.setText(f"{val}%")
                except Exception: pass
        lock_map = {
            "coupling": ("slider_lock_coupling", "lbl_lock_coupling"),
            "timing_pull": ("slider_lock_timing_pull", "lbl_lock_timing_pull"),
            "detune_link": ("slider_lock_detune_link", "lbl_lock_detune_link"),
            "velocity_link": ("slider_lock_velocity_link", "lbl_lock_velocity_link"),
            "phase_spread": ("slider_lock_phase_spread", "lbl_lock_phase_spread"),
        }
        locks = self._lock_characteristics()
        for key, (sattr, lattr) in lock_map.items():
            val = int(round(locks[key] * 100.0))
            w = getattr(self, sattr, None)
            if w is not None:
                try:
                    w.blockSignals(True); w.setValue(val); w.blockSignals(False)
                except Exception: pass
            lab = getattr(self, lattr, None)
            if lab is not None:
                try: lab.setText(f"{val}%")
                except Exception: pass
        if hasattr(self, "lbl_3d_model"):
            try:
                self.lbl_3d_model.setText("3D: " + (os.path.basename(str(getattr(self,"imported_3d_model_path","") or ""))[:20] if getattr(self,"imported_3d_model_path","") else "none"))
            except Exception: pass
        dlg = getattr(self, "_voxel_dialog", None)
        if dlg is not None:
            try:
                dlg.grid_spin.blockSignals(True); dlg.grid_spin.setValue(int(getattr(self,"voxel_grid_size",16) or 16)); dlg.grid_spin.blockSignals(False)
                dlg.z_spin.setRange(0, max(0, dlg.grid_spin.value()-1))
                dlg.alias_slider.blockSignals(True); dlg.alias_slider.setValue(int(getattr(self,"voxel_alias_pct",0) or 0)); dlg.alias_slider.blockSignals(False)
                dlg.alias_label.setText(f"{int(getattr(self,'voxel_alias_pct',0) or 0)}%")
                dlg.canvas.update()
            except Exception: pass

    def _sync_four_canonical_widgets_from_state(self):
        """Compatibility alias for projects/scripts made before Euclidean became canonical."""
        return self._sync_canonical_widgets_from_state()

    def _capture_rand_entropy(self):
        """Capture one RAND token for a new ON cycle, then freeze it (saved with the project).

        R32.9.9 FRACTAL DEFAULT: rand_source "fractal" (default patch) derives the token from the
        project seed — seed_child64(seed, "rand", generation) — so every RAND variation is a
        reproducible child of the seed (the fractal goal). rand_source "pure" keeps true OS
        entropy for the cases where unrepeatable randomness is the point (live jamming, dice
        exploration). Either way the captured token is frozen and replays identically.
        """
        gen = int(getattr(self, "_rand_generation_counter", 0) or 0) + 1
        self._rand_generation_counter = gen
        if str(getattr(self, "rand_source", "fractal") or "fractal") == "pure":
            self._rand_instance_seed = int(secrets.randbits(64))
        else:
            try: base = int(_safe_int_seed(self.get_numeric_seed() or 1))
            except Exception: base = 1
            self._rand_instance_seed = int(seed_child64(base, "rand", gen)) or 1
        return self._rand_instance_seed

    def _set_rand_source(self, mode):
        mode = "pure" if str(mode) == "pure" else "fractal"
        self.rand_source = mode
        try:
            b = getattr(self, "btn_local_randomize", None)
            if b is not None:
                b.setToolTip("RAND · source: " + ("PURE (OS entropy, unrepeatable)" if mode == "pure"
                             else "FRACTAL (seed child — reproducible from the seed; default)")
                             + "\nRight-click to switch source. Each OFF→ON makes a new variation.")
        except Exception:
            pass
        try:
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText("RAND source → " + ("PURE OS entropy" if mode == "pure" else "FRACTAL seed child (default)"))
        except Exception:
            pass

    def _rand_source_menu(self, pos):
        try:
            m = QMenu(self)
            cur = str(getattr(self, "rand_source", "fractal") or "fractal")
            a1 = m.addAction(("● " if cur != "pure" else "○ ") + "Fractal — seed child (reproducible, default)")
            a2 = m.addAction(("● " if cur == "pure" else "○ ") + "Pure — OS entropy (unrepeatable)")
            b = self.btn_local_randomize
            act = m.exec(b.mapToGlobal(pos))
            if act is a1: self._set_rand_source("fractal")
            elif act is a2: self._set_rand_source("pure")
        except Exception as exc:
            print("[RAND] source menu:", exc)

    def _canonical_seed_for_source(self, source):
        """SEEDED/LOCK/GOAVA use project seed; RAND uses captured OS entropy.

        GOAVA can be simultaneously selected with RAND. In that case GOAVA maps
        the still-fresh entropy into a reproducible Randomizer coordinate; it does
        not replace or manufacture the entropy source.
        """
        src = str(source or "").lower().replace("-", "_")
        if src in ("randomizer", "rand", "randomize"):
            raw = getattr(self, "_rand_instance_seed", None)
            if raw is None:
                raw = self._capture_rand_entropy()
            raw = int(raw) & ((1 << 64) - 1)
            if bool(getattr(self, "goava_active", False)):
                try: nums = list(self.get_seed_values(t_value=0.0) or [])
                except Exception: nums = []
                if not nums:
                    try: nums = [float(self.get_numeric_seed() or MEUM)]
                    except Exception: nums = [MEUM]
                step = ((raw >> 11) & 0x1FFFFF) / float(0x1FFFFF)
                assigned = float((raw & 0xFFFFFFFF) + 1)
                g = float(goava_get_note(assigned, step * MEUM, nums))
                blob = f"rand-goava|{raw}|{g:.17g}|{nums}".encode("utf-8", "replace")
                return int.from_bytes(hashlib.blake2b(blob, digest_size=8).digest(), "big")
            return raw
        try: base = int(_safe_int_seed(self.get_numeric_seed() or 1))
        except Exception: base = 1
        if src in ("phase_lock", "lock", "phaselock") and bool(getattr(self, "goava_active", False)):
            # R32.10: LOCK × GOAVA — the lock target is GOAVA's coordinate for the seed (still seed-only)
            try:
                nums = list(self.get_seed_values(t_value=0.0) or []) or [MEUM]
                g = float(goava_get_note(float((base & 0xFFFFFFFF) + 1), MEUM_NORM, nums))
                blob = f"lock-goava|{base}|{g:.17g}".encode("utf-8", "replace")
                return int.from_bytes(hashlib.blake2b(blob, digest_size=8).digest(), "big") or 1
            except Exception:
                return base
        return base

    def _canonical_input_context(self):
        """Stable input + net-canonical context for all six canonical sources."""
        import hashlib
        import numpy as _np
        active = []
        for _name, _attr in (("seeded","btn_seeded_randomize"), ("randomizer","btn_local_randomize"), ("phase_lock","btn_local_phase_lock"), ("euclidean","btn_idealize_rhythm"), ("fractal_seed","btn_fractal_seed_mode")):
            _btn = getattr(self, _attr, None)
            if _btn is not None and _btn.isChecked() and self._canonical_level(_name) > 0.0:
                active.append(_name)
        if bool(getattr(self, "goava_active", False)) and self._canonical_level("goava") > 0.0:
            active.append("goava")
        active = sorted(set(active))
        levels = self._canonical_levels()
        locks = self._lock_characteristics()
        roster = [str(x).strip() for x in (getattr(self, "instrument_names_48", []) or []) if str(x).strip()]
        wf = getattr(self, "imported_waveform", None)
        if wf is None:
            carrier_hash, carrier_rms, carrier_peak = "none", 0.0, 0.0
        else:
            a = _np.asarray(wf, dtype=_np.float32).ravel()
            if a.size:
                idx = _np.linspace(0, a.size - 1, min(2048, a.size)).astype(_np.int64)
                desc = _np.nan_to_num(a[idx], nan=0.0, posinf=0.0, neginf=0.0).astype(_np.float32)
                carrier_hash = hashlib.sha256(desc.tobytes()).hexdigest()[:24]
                carrier_rms = float(_np.sqrt(_np.mean(desc * desc)))
                carrier_peak = float(_np.max(_np.abs(desc)))
            else:
                carrier_hash, carrier_rms, carrier_peak = "empty", 0.0, 0.0
        rand_seed = int(getattr(self, "_rand_instance_seed", 0) or 0)
        vox = getattr(self, "voxel_cells", []) or []
        voxel_digest = hashlib.sha256(repr(sorted(tuple(self._normalize_voxel_record(v) or []) for v in vox if isinstance(v,(list,tuple)) and len(v)>=3)).encode("utf-8","replace")).hexdigest()[:12]
        active_key = "|".join(active) + "|levels=" + json.dumps(levels, sort_keys=True) + "|lock=" + json.dumps(locks, sort_keys=True) + f"|rand={rand_seed}|vox={voxel_digest}:{int(getattr(self,'voxel_alias_pct',0) or 0)}"
        canonical_hash = hashlib.sha256(active_key.encode("utf-8")).hexdigest()[:16] if active else "none"
        return {
            "canonical_unison": 1 if active else 0,
            "canonical_count": len(active),
            "canonical_mask": int(canonical_hash, 16) % 1000000007 if canonical_hash != "none" else 0,
            "canonical_randomizer": int("randomizer" in active),
            "canonical_phase_lock": int("phase_lock" in active),
            "canonical_euclidean": int("euclidean" in active),
            "canonical_seeded": int("seeded" in active),
            "canonical_goava": int("goava" in active),
            "canonical_fractal_seed": int("fractal_seed" in active),
            "canonical_level_fractal_seed": levels["fractal_seed"],
            "canonical_level_seeded": levels["seeded"],
            "canonical_level_randomizer": levels["randomizer"],
            "canonical_level_phase_lock": levels["phase_lock"],
            "canonical_level_euclidean": levels["euclidean"],
            "canonical_level_goava": levels["goava"],
            "phase_lock_characteristics": locks,
            "rand_instance_seed": rand_seed,
            "canonical_roster_size": len(roster),
            "carrier_present": int(wf is not None),
            "carrier_hash": carrier_hash,
            "carrier_rms": carrier_rms,
            "carrier_peak": carrier_peak,
            "voxel_digest": voxel_digest,
            "voxel_alias_pct": int(getattr(self, "voxel_alias_pct", 0) or 0),
        }

    def _schedule_seed_script_validation(self):
        """Debounce visual Seed Script diagnostics; never evaluate/recompose here."""
        try:
            self._seed_validation_timer.start()
        except Exception:
            pass

    @staticmethod
    def _seed_script_static_diagnostic(raw):
        """Return (message, line, col, length) for a confident static seed error.

        This intentionally does *not* execute the script.  It catches Python-style
        syntax errors and unresolved loaded names (including a variable assigned to
        an unknown preset identifier). Groovebox's coordinate DSL and if/elif
        shorthand are normalized/skipped where their custom parser is authoritative.
        """
        text = str(raw or "").replace("\r\n", "\n").replace("\r", "\n")
        if not text.strip():
            return None

        # GROOVEBOX_R32_SEED_LANGUAGE_20261109: analyse the *desugared* program (free
        # syntax, top-level return, coordinate DSL) with the same front end that runs it.
        try:
            import seed_lang as _sl
            if _sl.HOOKS.get("if_elif_shorthand") is None:
                _sl.HOOKS["if_elif_shorthand"] = _parse_if_elif_shorthand
            _allowed = set(_seed_script_env(t_scalar=0.0, canonical_context=None).keys())
            return _sl.analyze(text, _allowed)
        except Exception:
            pass

        # x(t)=..., polar/cylindrical/etc. are owned by the coordinate parser and
        # are not legal Python assignment syntax; do not falsely mark them red.
        try:
            if _seed_script_is_coordinate(text):
                return None
        except Exception:
            pass

        source = text
        # Groovebox shorthand such as `if(t<4) 1 elif 2` has its own parser.
        try:
            sh = _parse_if_elif_shorthand(text.strip())
            if sh:
                source = sh
        except Exception:
            pass

        try:
            tree = ast.parse(source, mode="exec")
        except SyntaxError as exc:
            # A top-level `return expr` is a supported Seed Script convenience;
            # normalize it to the expression before calling it a syntax error.
            try:
                normalized = _normalize_seed_script_text(text)
                if normalized and normalized != text.strip():
                    ast.parse(normalized, mode="eval")
                    return None
            except SyntaxError as exc2:
                exc = exc2
            except Exception:
                pass
            line = max(1, int(getattr(exc, "lineno", 1) or 1))
            col = max(0, int(getattr(exc, "offset", 1) or 1) - 1)
            msg = str(getattr(exc, "msg", None) or "invalid syntax")
            return (f"SEED SCRIPT ERROR · {msg} · line {line}", line, col, 1, "error")
        except Exception:
            return None

        # Names available from the numeric seed environment plus every name the
        # script itself binds.  This catches `voice = MyPreset` as an unresolved
        # preset/name while permitting ordinary local variables and def arguments.
        try:
            allowed = set(_seed_script_env(t_scalar=0.0, canonical_context=None).keys())
        except Exception:
            allowed = set()
        bound = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Name) and isinstance(node.ctx, (ast.Store, ast.Param)):
                bound.add(node.id)
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                bound.add(node.name)
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    for arg in list(node.args.posonlyargs) + list(node.args.args) + list(node.args.kwonlyargs):
                        bound.add(arg.arg)
                    if node.args.vararg:
                        bound.add(node.args.vararg.arg)
                    if node.args.kwarg:
                        bound.add(node.args.kwarg.arg)
            elif isinstance(node, ast.alias):
                bound.add(node.asname or node.name.split(".")[0])

        unresolved = []
        for node in ast.walk(tree):
            if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
                if node.id not in allowed and node.id not in bound:
                    unresolved.append(node)
        if unresolved:
            node = min(unresolved, key=lambda n: (getattr(n, "lineno", 1), getattr(n, "col_offset", 0)))
            name = node.id
            line = max(1, int(getattr(node, "lineno", 1) or 1))
            col = max(0, int(getattr(node, "col_offset", 0) or 0))
            return (
                f"SEED SCRIPT ERROR · unknown variable/preset '{name}' · line {line}",
                line, col, max(1, len(name)), "error",
            )

        # A second assignment to the same local seed variable is legal, but it is
        # important enough to surface because it changes the value used by every
        # later expression.  Track assignment targets in source order and warn on
        # the later write.  Function arguments and loop targets are excluded here;
        # this warning is specifically about user variable reassignment.
        writes = []
        class _SeedWriteVisitor(ast.NodeVisitor):
            def visit_Assign(self, node):
                for target in node.targets:
                    if isinstance(target, ast.Name):
                        writes.append((target.id, target))
                self.generic_visit(node.value)
            def visit_AnnAssign(self, node):
                if isinstance(node.target, ast.Name):
                    writes.append((node.target.id, node.target))
                if node.value is not None:
                    self.visit(node.value)
            def visit_AugAssign(self, node):
                if isinstance(node.target, ast.Name):
                    writes.append((node.target.id, node.target))
                self.visit(node.value)
        _SeedWriteVisitor().visit(tree)
        first_write = {}
        for name, node in sorted(writes, key=lambda item: (getattr(item[1], "lineno", 1), getattr(item[1], "col_offset", 0))):
            if name in first_write:
                prev = first_write[name]
                line = max(1, int(getattr(node, "lineno", 1) or 1))
                col = max(0, int(getattr(node, "col_offset", 0) or 0))
                prev_line = max(1, int(getattr(prev, "lineno", 1) or 1))
                return (
                    f"SEED SCRIPT WARNING · redefining variable '{name}' · line {line} writes over the value first assigned on line {prev_line}; later seed expressions use the new value",
                    line, col, max(1, len(name)), "warning",
                )
            first_write[name] = node
        return None

    def _set_seed_error_highlight(self, line=0, col=0, length=0, severity="error"):
        """Highlight exactly the offending Seed Script token without modifying text."""
        try:
            if not hasattr(self, "input_seed_val"):
                return
            selections = []
            if line > 0 and length > 0:
                doc = self.input_seed_val.document()
                block = doc.findBlockByNumber(int(line) - 1)
                if block.isValid():
                    cursor = QTextCursor(doc)
                    start = block.position() + max(0, int(col))
                    end = min(block.position() + max(0, block.length() - 1), start + max(1, int(length)))
                    cursor.setPosition(start)
                    cursor.setPosition(max(start + 1, end), QTextCursor.MoveMode.KeepAnchor)
                    sel = QTextEdit.ExtraSelection()
                    sel.cursor = cursor
                    fmt = QTextCharFormat()
                    warn = str(severity).lower() == "warning"
                    tone = QColor("#ffbf5a" if warn else "#ff5555")
                    fmt.setForeground(tone)
                    fmt.setFontWeight(QFont.Weight.Bold)
                    fmt.setUnderlineColor(tone)
                    fmt.setUnderlineStyle(QTextCharFormat.UnderlineStyle.SingleUnderline if warn else QTextCharFormat.UnderlineStyle.WaveUnderline)
                    fmt.setBackground(QColor(70, 46, 8, 110) if warn else QColor(80, 12, 18, 115))
                    sel.format = fmt
                    selections.append(sel)
            self.input_seed_val.setExtraSelections(selections)
        except Exception:
            pass

    def _validate_seed_script_ui(self):
        """Refresh the Seed panel diagnostic readout and offending-token highlight.

        GROOVEBOX_R32_SEED_OFFTHREAD_20261109: the parse/analysis runs in the global
        thread pool; only the label/highlight update touches widgets, on the GUI thread.
        A generation counter drops results that a newer keystroke has superseded.
        """
        try:
            raw = self.input_seed_val.toPlainText() if hasattr(self, "input_seed_val") else ""
        except Exception:
            raw = ""
        gen = int(getattr(self, "_seed_diag_generation", 0)) + 1
        self._seed_diag_generation = gen
        bridge = getattr(self, "_seed_diag_bridge", None)
        if bridge is None:
            bridge = self._seed_diag_bridge = _SeedDiagBridge(self)
            bridge.done.connect(self._apply_seed_diagnostic)
        try:
            from PyQt6.QtCore import QThreadPool
            __import__("r32_pool").start(_SeedDiagRunnable(self._seed_script_static_diagnostic, raw, gen, bridge))
        except Exception:
            # No thread pool (minimal Qt): analyse inline.
            try:
                self._apply_seed_diagnostic(gen, self._seed_script_static_diagnostic(raw))
            except Exception:
                pass

    def _apply_seed_diagnostic(self, gen, diag):
        try:
            if int(gen) != int(getattr(self, "_seed_diag_generation", 0)):
                return      # a newer edit is already being analysed
            label = getattr(self, "lbl_seed_script_error", None)
            if diag is None:
                self._set_seed_error_highlight()
                if label is not None:
                    label.clear()
                    label.hide()
                return
            message, line, col, length, severity = diag
            self._set_seed_error_highlight(line, col, length, severity)
            if label is not None:
                if str(severity).lower() == 'warning':
                    label.setStyleSheet(
                        "background-color:#121212; color:#ffbf5a; border:1px solid #6d5725; "
                        "font-family:Consolas, monospace; font-size:9pt; font-weight:bold; padding:3px 6px;"
                    )
                else:
                    label.setStyleSheet(
                        "background-color:#121212; color:#ff5555; border:1px solid #31577a; "
                        "font-family:Consolas, monospace; font-size:9pt; font-weight:bold; padding:3px 6px;"
                    )
                label.setText(message)
                label.show()
        except Exception as exc:
            # Diagnostics must never become a new crash source.
            try:
                label = getattr(self, "lbl_seed_script_error", None)
                if label is not None:
                    label.setText(f"SEED SCRIPT ERROR · diagnostic failure: {exc}")
                    label.show()
            except Exception:
                pass

    def _seed_text(self):
        """Return the complete scrollable seed/script field as plain text."""
        if not hasattr(self, 'input_seed_val'):
            return "0.0"
        try:
            return self.input_seed_val.toPlainText().strip()
        except AttributeError:
            return self.input_seed_val.text().strip()

    def _run_audio_check(self):
        """GROOVEBOX_R23R_AUDIO_CHECK_20261101: tones through every path + report."""
        if getattr(self, "_audio_check_running", False):
            return
        self._audio_check_running = True
        try:
            self.stop_playback()
        except Exception:
            pass
        try:
            self._close_audition_stream()
        except Exception:
            pass
        from PyQt6.QtCore import QObject as _QO, pyqtSignal as _sig

        class _Br(_QO):
            msg = _sig(str)
            done = _sig(str, object)
        br = _Br(self); self._audio_check_bridge = br
        br.msg.connect(lambda t: hasattr(self, "scope_status_label") and self.scope_status_label.setText(t))

        def finished(path, tests):
            self._audio_check_running = False
            try:
                # GROOVEBOX_AUDIO_CHECK_NONMODAL_20261102: the answers window used a modal
                # blocking exec loop; on the appliance window manager it could open behind the main
                # window and leave the whole UI looking frozen. It is now non-modal, always
                # on top, and the report file is already complete before it appears.
                dlg = QDialog(self); dlg.setWindowTitle("Audio check — which tones did you hear?")
                dlg.setWindowModality(Qt.WindowModality.NonModal)
                dlg.setWindowFlag(Qt.WindowType.WindowStaysOnTopHint, True)
                dlg.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
                lay = QVBoxLayout(dlg)
                lay.addWidget(QLabel("The report is already saved in:\n" + path +
                                     "\n\nTick every tone you actually HEARD, then Save (optional)."))
                boxes = []
                for label, result in tests:
                    cb = QCheckBox(f"{label}   ({result})"); lay.addWidget(cb); boxes.append((label, cb))
                b = QPushButton("Save answers")

                def _save():
                    try:
                        with open(path, "a", encoding="utf-8") as f:
                            f.write("\n===== user heard =====\n" + "\n".join(f"{l}: {'HEARD' if cb.isChecked() else 'not heard'}" for l, cb in boxes) + "\n")
                        if hasattr(self, "scope_status_label"):
                            self.scope_status_label.setText(f"🩺 Audio check saved: {path}")
                    except Exception as exc2:
                        print(f"[Audio check] save answers: {exc2}")
                    dlg.close()
                b.clicked.connect(_save); lay.addWidget(b)
                self._audio_check_dialog = dlg
                dlg.show(); dlg.raise_(); dlg.activateWindow()
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText(f"🩺 Audio check report saved: {path}")
            except Exception as exc:
                print(f"[Audio check] {exc}")
        br.done.connect(finished)

        def work():
            try:
                import audio_check as _ac
                report = _ac.system_report(self)
                tests = _ac.playback_tests(self, announce=br.msg.emit)
                path = _ac.logs_dir() / f"audio-check-{time.strftime('%Y%m%d-%H%M%S')}.txt"
                path.write_text(report + "\n\n===== playback tests =====\n" + "\n".join(f"{l}: {r}" for l, r in tests), encoding="utf-8")
                br.done.emit(str(path), tests)
            except Exception as exc:
                br.done.emit(f"(failed: {exc})", [])
        threading.Thread(target=work, daemon=True, name="GrooveboxAudioCheck").start()

    def _on_seed_ws_override_toggled(self, disabled):
        global SEED_WORKSPACE_OVERRIDE
        if not getattr(self, "_undo_in_flight", False) and not getattr(self, "_loading_project_flag", False):
            try:
                self._push_undo("Seed workspace override " + ("off" if disabled else "on"))
            except Exception:
                pass
        SEED_WORKSPACE_OVERRIDE = not bool(disabled)
        self.seed_workspace_override = SEED_WORKSPACE_OVERRIDE
        self._seed_values_memo = {} if getattr(self, "_seed_values_memo", None) is not None else None
        try:
            self._on_live_source_changed()
        except Exception:
            pass
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("🌱 Seed variables: " + ("own defaults only (workspace override disabled)"
                                                                     if disabled else "live workspace values override"))

    def _on_random_seed_clicked(self):
        """Fill the seed field with a random time-conditional / math / list script.

        Uses the expanded generator that also covers scriptable seed parameters
        shared with GLOBAL PLAY PATCHER (domain-path, algo-mix, transmutor, etc.).
        """
        # PROJECT_UNDO_2026: randomizing the seed is a documented, reversible step.
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("Random seed script")
        try:
            try:
                _live_ctx = self._canonical_input_context()
            except Exception:
                _live_ctx = None
            script = generate_random_seed_script(canonical_context=_live_ctx if isinstance(_live_ctx, dict) else None)
        except Exception as exc:
            print(f"[Seed] random script failed: {exc}")
            script = str(random.randint(1, 999999))
        if hasattr(self, "input_seed_val"):
            try:
                self.input_seed_val.blockSignals(True)
                self.input_seed_val.setPlainText(script)
                self.input_seed_val.blockSignals(False)
            except Exception:
                try:
                    self.input_seed_val.setText(script)
                except Exception:
                    pass
        try:
            self._on_live_source_changed()
        except Exception:
            pass
        if hasattr(self, "scope_status_label"):
            preview = script.replace("\n", " ")[:72]
            self.scope_status_label.setText(f"🎲 Random seed script → {preview}")

    def _on_randomize_global_play_algo(self):
        """Write (but DO NOT apply) a random Global Play Algorithm.

        Fills Script Algo, Domain Algo, Wire routing, and amount params from
        generate_random_global_play_algo() and syncs the UI. It NEVER applies
        to the ensemble: written music and shapes are untouched until the user
        explicitly presses "▶ Apply Algo to Master Mix". This is the canonical
        rule — randomizing algorithm output is authoring, not application.
        Does not overwrite the user-controlled seed field.
        """
        # PROJECT_UNDO_2026 / RANDOMIZE_NO_APPLY_2026: reversing the old
        # auto-apply that used to mutate the written music/shapes on randomize.
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("Randomize Global Play algo")
        try:
            state = generate_random_global_play_algo()
        except Exception as exc:
            print(f"[GlobalPlay] randomize failed: {exc}")
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(f"🌐 Randomize Global Play failed: {exc}")
            return
        # Preserve protectable flag from the checkbox if present
        if getattr(self, "chk_algo_protect_userdata", None) is not None:
            state["user_data"] = True
            state["canonical_superwrite"] = True
        # RANDOMIZE_ALL_PATCH_2026: this button is an explicit standalone patch
        # action, so its generated script/domain/wire state is applied immediately.
        # The separate Apply Algo control remains available for manual edits.
        state["apply_enabled"] = True
        _prev_gas = getattr(self, "global_algo_state", {}) or {}
        self.global_algo_state = dict(state)
        # Randomizing the patch keeps the GLOBAL/LOCAL scope and Local target.
        for _k in ("scope", "local_targets"):
            if _k in _prev_gas and _k not in self.global_algo_state:
                self.global_algo_state[_k] = copy.deepcopy(_prev_gas[_k])
        # Sync UI fields
        try:
            if getattr(self, "gp_script_field", None) is not None:
                self.gp_script_field.blockSignals(True)
                self.gp_script_field.setPlainText(str(state.get("script") or ""))
                self.gp_script_field.blockSignals(False)
            if getattr(self, "gp_domain_field", None) is not None:
                self.gp_domain_field.blockSignals(True)
                self.gp_domain_field.setText(str(state.get("domain") or "").replace("\n", " "))
                self.gp_domain_field.blockSignals(False)
            hints = self._global_domain_hints(state.get("domain") or "")
            self.global_algo_state["domain_hints"] = hints
            if getattr(self, "lbl_gp_domain_hints", None) is not None:
                self.lbl_gp_domain_hints.setText("hints: " + " · ".join(hints[:5]))
            wires = state.get("wire") or []
            if getattr(self, "lbl_gp_wire", None) is not None:
                if wires:
                    summary = ", ".join(f"{w.get('source')}→{w.get('target')}" for w in wires[:4])
                    self.lbl_gp_wire.setText(f"routing: {summary}")
                else:
                    self.lbl_gp_wire.setText("routing matrix / modular targets")
            params = state.get("params") or {}
            for sl, key, default in (
                (getattr(self, "gp_mix_slider", None), "mix", 0.35),
                (getattr(self, "gp_script_slider", None), "script_amount", 1.0),
                (getattr(self, "gp_domain_slider", None), "domain_amount", 1.0),
                (getattr(self, "gp_wire_slider", None), "wire_amount", 1.0),
            ):
                if sl is not None:
                    sl.blockSignals(True)
                    sl.setValue(int(float(params.get(key, default)) * 100))
                    sl.blockSignals(False)
            for _k in GLOBAL_ALGO_EXTRA_KINDS:
                _f = (getattr(self, "gp_extra_fields", {}) or {}).get(_k)
                _sx = (getattr(self, "gp_extra_sliders", {}) or {}).get(_k)
                if _f is not None:
                    _f.blockSignals(True); _f.setText(str(state.get(_k) or "").replace("\n", " ⏎ ")); _f.blockSignals(False)
                if _sx is not None:
                    _sx.blockSignals(True); _sx.setValue(int(float(params.get(_k + "_amount", 1.0)) * 100)); _sx.blockSignals(False)
        except Exception as exc:
            print(f"[GlobalPlay] UI sync: {exc}")
        # Standalone patch randomizer applies all generated patch layers immediately.
        try:
            global_algo_fill_missing(self.global_algo_state)
            for kind in ("script", "domain", "wire") + GLOBAL_ALGO_EXTRA_KINDS:
                self._apply_global_algo_to_ensemble(kind)
            if getattr(self, "btn_apply_algo_master", None) is not None:
                self.btn_apply_algo_master.blockSignals(True)
                self.btn_apply_algo_master.setChecked(True)
                self.btn_apply_algo_master.setText("■ Unapply Algo from Master Mix")
                self.btn_apply_algo_master.blockSignals(False)
        except Exception as exc:
            print(f"[GlobalPlay] standalone patch apply failed: {exc}")
        try:
            self._on_live_source_changed()
        except Exception:
            pass
        try:
            self._refresh_canonical_fingerprint()
        except Exception:
            pass
        mode = "userdata · canonical superwrite"
        if hasattr(self, "scope_status_label"):
            n_w = len(self.global_algo_state.get("wire") or [])
            self.scope_status_label.setText(
                f"🎲 RANDOMIZE ALL PATCH · {n_w} wires · applied · {mode}"
            )
        # Preserve the per-cycle toggle palette rather than replacing it with
        # a static green sheet after every generation.
        if getattr(self, "btn_randomize_global_play", None) is not None:
            self._randomizer_toggle_style(
                self.btn_randomize_global_play, True,
                getattr(self, "_randomizer_toggle_cycles", {}).get("global_patch", 0))

    def get_numeric_seed(self):
        """
        Resolve the Seed field exactly once into a deterministic numeric value.

        Accepted: numbers, math, if/elif, return scripts, comma/newline lists.
        Multi-value lists return the first evaluable component (not a hash).
        Use get_seed_values() / get_seed_value_for_index(i) for per-instrument lists.

        This method is the static/global seed snapshot and samples t=0.0.
        Arrangement-aware composition must use get_seed_values(t_value=beat_t)
        (or get_seed_value_for_index(..., t_value=beat_t)); continuous DSP
        modulation resolves t in seconds at the render boundary.

        IMPORTANT: composition-state only — never call from a per-sample loop.
        """
        vals = self.get_seed_values(t_value=0.0)
        if vals:
            return float(vals[0])
        raw = self._seed_text() if hasattr(self, "_seed_text") else ""
        if not str(raw or "").strip():
            return 0.0
        try:
            _ctx = getattr(self, "_canonical_render_input_context", None) or self._canonical_input_context()
        except Exception:
            _ctx = None
        try:
            return float(evaluate_seed_expression_at_time(raw, 0.0, _ctx))
        except Exception:
            return 0.0

    def get_seed_values(self, t_value=0.0):
        """Return every evaluable numeric component of the seed field as floats.

        Scripts, lists, and conditionals are fully evaluated. Failed parts are
        skipped (never replaced with hash/byte tokens). Empty field → [].

        DEGENERATE_T_GUARD: a script can be perfectly valid and still be
        undefined at one exact instant — e.g. "1/t", "log(t)", "sqrt(t-1)",
        "100/tan(t)" all blow up (ZeroDivisionError / domain error / NaN) at
        t=0.0, which is the static snapshot used by get_numeric_seed().
        Arrangement-aware composition supplies its absolute beat explicitly,
        so only truly static/global callers use this degenerate instant. Without this guard, that single
        degenerate instant made the whole script look unevaluable, so
        callers fell through to the text-hash last resort — a static,
        script-unrelated number that also never varies with time. Real user
        data (their number/conditional script) was being silently discarded
        for scripts that were entirely correct. Before giving up, retry at a
        few nearby time offsets so a script that degenerates only at the one
        requested instant still resolves to a real evaluated value.
        """
        raw = self._seed_text() if hasattr(self, "_seed_text") else ""
        if not str(raw or "").strip():
            return []
        try:
            _ctx = getattr(self, "_canonical_render_input_context", None) or self._canonical_input_context()
        except Exception:
            _ctx = None
        # GROOVEBOX_R23R_RENDER_SEED_MEMO_20261031: inside one render the seed text
        # and canonical context are frozen, so each (text, t, context) is evaluated
        # once instead of thousands of times. The memo exists only during a render.
        _memo = getattr(self, "_seed_values_memo", None)
        _render_memo = _memo is not None
        if _memo is None:
            _memo = self.__dict__.setdefault("_control_seed_values_memo", {})
        try:
            # A newly-built context dict has a new id even when every input is
            # identical. Control-lane memo keys must encode its actual contents.
            _context_key = id(_ctx) if _render_memo else json.dumps(_ctx, sort_keys=True, default=str)
            _mkey = (str(raw), float(t_value), _context_key)
        except Exception:
            _mkey = None
        if _mkey is not None and _mkey in _memo:
            return list(_memo[_mkey])
        def _store(v):
            if _mkey is not None:
                if not _render_memo and len(_memo) >= 96:
                    _memo.clear()
                _memo[_mkey] = list(v or [])
            return v
        # Require a REAL evaluation (allow_scrape=False) at the requested t and,
        # failing that, at nearby t before ever falling back to digit-scraping —
        # otherwise a script with embedded numbers (e.g. "sqrt(t - 1) * 100")
        # would get those literals scraped out of the text instead of the
        # correctly retried, mathematically real evaluated value.
        vals = parse_seed_numeric_list(raw, t_value=t_value, canonical_context=_ctx, allow_scrape=False)
        if vals:
            return _store(vals)
        try:
            base_t = float(t_value)
        except Exception:
            base_t = 0.0
        for probe_t in (base_t + 1e-6, base_t - 1e-6, base_t + 1e-3, base_t + 0.5, base_t + 1.0):
            vals = parse_seed_numeric_list(raw, t_value=probe_t, canonical_context=_ctx, allow_scrape=False)
            if vals:
                return _store(vals)
        # True last resort: no evaluable form exists at any probed t — only
        # now fall back to scraping bare numeric tokens out of the raw text.
        vals = parse_seed_numeric_list(raw, t_value=t_value, canonical_context=_ctx, allow_scrape=True)
        return _store(vals)


    def _push_visualizer_seed_hud(self):
        """Feed seed list, ensemble, engines, and live macro/engine params into monitors."""
        try:
            vals = list(self.get_seed_values(t_value=0.0) or [])
        except Exception:
            vals = []
        flags = []
        pairs = (
            ("seeded", "btn_seeded_randomize"),
            ("euclid", "btn_idealize_rhythm"),
            ("phase", "btn_local_phase_lock"),
            ("rand", "btn_local_randomize"),
        )
        for label, attr in pairs:
            btn = getattr(self, attr, None)
            if btn is not None and btn.isChecked():
                flags.append(label)
        if getattr(self, "goava_active", False):
            flags.append("goava")
        ensemble = max(len(vals), 1)
        try:
            rows = getattr(self, "master_playlist_data", None) or []
            ops = set()
            for e in rows:
                if not isinstance(e, dict):
                    continue
                for o in (e.get("operators") or []):
                    n = str(o).strip()
                    if n and n.casefold() != "goava":
                        ops.add(n)
            if ops:
                ensemble = max(ensemble, len(ops))
        except Exception:
            pass
        # Live parameters for HUD (engines + macros + visual + path)
        params = {}
        try:
            if hasattr(self, "slider_eqr"):
                params["EQR"] = float(self.slider_eqr.value()) / 100.0
            if hasattr(self, "slider_fractalizer"):
                params["Frac"] = float(self.slider_fractalizer.value()) / 100.0
            if hasattr(self, "spin_bpm"):
                params["BPM"] = float(self.spin_bpm.value())
            if hasattr(self, "spin_base_frequency"):
                params["BaseHz"] = float(self.spin_base_frequency.value())
            if hasattr(self, "spin_synth_count"):
                params["VisN"] = int(self.spin_synth_count.value())
            if hasattr(self, "spin_engine_strength"):
                # Effective seed weight: FullWeight ON → spin value; OFF → attenuated.
                raw = float(self.spin_engine_strength.value())
                full = bool(getattr(self, "chk_fullweight_seed", None) and self.chk_fullweight_seed.isChecked())
                params["EngStr"] = raw if full else raw * float(MEUM_NORM)
                params["FullWeight"] = 1.0 if full else 0.0
                params["SeedWeight"] = raw
            if hasattr(self, "spin_unison_blend"):
                full_u = bool(getattr(self, "chk_full_unison", None) and self.chk_full_unison.isChecked())
                params["Unison"] = 1.0 if full_u else float(self.spin_unison_blend.value())
                params["FullUnison"] = 1.0 if full_u else 0.0
            if hasattr(self, "slider_master_vol"):
                params["Vol"] = float(self.slider_master_vol.value()) / 100.0
            elif hasattr(self, "master_volume"):
                params["Vol"] = float(self.master_volume)
            params["engines"] = len(flags)
            params["PED"] = params.get("EQR", 0.0)
        except Exception:
            pass
        for attr in ("visual_oscilloscope", "spectrum_analyzer"):
            wid = getattr(self, attr, None)
            if wid is not None and hasattr(wid, "set_seed_hud"):
                try:
                    wid.set_seed_hud(
                        vals,
                        ensemble_voices=ensemble,
                        canonical_flags=flags,
                        engine_params=params,
                    )
                except TypeError:
                    try:
                        wid.set_seed_hud(vals, ensemble_voices=ensemble, canonical_flags=flags)
                    except Exception:
                        pass
                except Exception:
                    pass
        # Scenograph engine also sees activity for module schedule
        try:
            eng = getattr(self, "video_synth_engine", None)
            if eng is not None:
                if hasattr(eng, "_module_target"):
                    # Boost fades for active engine names
                    for name, key in (
                        ("euclidean", "euclidean_spokes"),
                        ("seeded", "seeded_constellation"),
                        ("phase", "phase_ribbons"),
                        ("rand", "rand_static"),
                        ("goava", "goava_glyphs"),
                    ):
                        if name in flags or (name == "goava" and "goava" in flags):
                            if key in eng._module_target:
                                eng._module_target[key] = max(
                                    float(eng._module_target.get(key, 0.0)), 0.55
                                )
        except Exception:
            pass

    def get_seed_value_for_index(self, index, t_value=0.0):
        """Per-instrument / per-row seed: list[i % n], or single evaluated script.

        Every instrument receives a real evaluated number from the script field.
        Hash/byte tokens are never used here.
        """
        vals = self.get_seed_values(t_value=t_value)
        if not vals:
            return 0.0
        try:
            i = int(index)
        except Exception:
            i = 0
        # GROOVEBOX_R32_SEED_DIVERGENCE_20261109: every index gets its own deterministic value.
        try:
            import seed_divergence as _sd
            return float(_sd.apply_to_app(self, vals[i % len(vals)], i, "instrument"))
        except Exception:
            return float(vals[i % len(vals)])

    def _instrument_seed_float(self, index, t_value=0.0, sequence_id=None):
        """Evaluated seed float for instrument/row index (list-aware).

        When the seed field is a list, instrument `index` picks list[i % n].
        Optional sequence_id rotates further through the list so every sequence
        bank slot receives distinct evaluated data (not only the selected one).
        """
        try:
            vals = list(self.get_seed_values(t_value=t_value) or [])
        except Exception:
            vals = []
        if not vals:
            try:
                return float(self.get_numeric_seed() or 0.0)
            except Exception:
                return 0.0
        try:
            i = int(index)
        except Exception:
            i = 0
        if sequence_id is not None:
            try:
                # Offset into the list by sequence number so seq 1,2,3… differ.
                i = i + (int(sequence_id) - 1)
            except Exception:
                pass
        try:
            import seed_divergence as _sd
            return float(_sd.apply_to_app(self, vals[i % len(vals)], i, "sequence" if sequence_id is not None else "instrument"))
        except Exception:
            return float(vals[i % len(vals)])

    def seed_child(self, *labels):
        """SEED_PATH_20261102: sub-seed of the project seed for a label path, e.g. self.seed_child("synth", 3, "wavetable").

        New code derives every part's numbers here. Existing derivations (_instrument_seed_int and the engine
        XOR mixes) are untouched on purpose: changing them would change how saved projects sound."""
        sig = self._seed_program_signature()      # R32: the whole program, not one scalar
        return seed_child(self.get_numeric_seed(), *((("program", sig),) if sig else ()), *labels)

    def _instrument_seed_int(self, index, name="", t_value=0.0, sequence_id=None):
        """NumPy-safe int seed for instrument (+ optional sequence) from scripts.

        Primary entropy is the evaluated seed list/script (never sha256 of the
        instrument name). Sequence_id further selects list components so all
        sequence bank slots are seeded, not only the currently selected one.
        """
        val = self._instrument_seed_float(index, t_value=t_value, sequence_id=sequence_id)
        base = _safe_int_seed(val)
        vals = []
        try:
            vals = list(self.get_seed_values(t_value=t_value) or [])
        except Exception:
            vals = []
        if sequence_id is not None:
            try:
                base = (base ^ (int(sequence_id) * 0x9E3779B1)) & 0x7FFFFFFF
            except Exception:
                pass
        if len(vals) <= 1 and name:
            # Light non-destructive salt — does not replace the evaluated seed.
            salt = (sum(ord(c) for c in str(name)) * 131) & 0xFFFF
            base = (base ^ salt) & 0x7FFFFFFF
        # GROOVEBOX_R32_SEED_SIGNATURE_20261109: fold in what the whole seed program computes over
        # time (not just one value at t=0), so different programs give different instruments.
        # Divergence 0 keeps the legacy integer exactly.
        sig = self._seed_program_signature()
        if sig:
            base = seed_child(base ^ sig, "instrument", int(index)) & 0x7FFFFFFF
        return int(base) & 0x7FFFFFFF

    def _seed_program_signature(self):
        """31-bit fingerprint of the seed program over 20 probe beats (0 when divergence is 0)."""
        try:
            import seed_divergence as _sd
            if _sd.amount_from(self) <= 0.0:
                return 0
            import seed_lang as _sl
            raw = self._seed_text() if hasattr(self, "_seed_text") else ""
            if not str(raw or "").strip():
                return 0
            return int(_sl.signature(raw, lambda tt: _seed_script_env(t_scalar=float(tt), canonical_context=None)))
        except Exception:
            return 0

    def _iter_sequence_mems(self, instrument_name=None):
        """Yield (sequence_id, mem) for every sequence in an instrument bank.

        Ensures seed/engine writes reach the full bank, not only the selected
        sequence mirrored into instrument_sequencer_memory.
        """
        name = instrument_name or self._current_instrument_name()
        banks = getattr(self, "instrument_sequence_banks", {}) or {}
        bank = banks.setdefault(name, {})
        if not bank:
            mem = self.instrument_sequencer_memory.setdefault(name, {
                "steps": [], "gates": [], "amplitudes": [], "pitches": [],
                "probabilities": [], "offsets": [], "pattern_length": DEFAULT_SEQUENCE_LENGTH,
                "sequence_length_user_owned": False,
                "track_offset": 0.0,
                "sequence_playlist_mode": "wrap",
                "sequence_force_wrap": False, "sequence_force_schedule": False,
                "sequence_envelope_attack": 0.5, "sequence_envelope_release": 0.5
            })
            bank[1] = mem
        for sid in sorted(int(k) for k in bank.keys() if str(k).isdigit()):
            mem = bank.get(sid)
            if isinstance(mem, dict):
                yield sid, mem

    def _sync_selected_sequence_mirrors(self):
        """Point instrument_sequencer_memory at each instrument's selected bank slot."""
        banks = getattr(self, "instrument_sequence_banks", {}) or {}
        selected = getattr(self, "instrument_selected_sequence", {}) or {}
        for name, bank in banks.items():
            if not isinstance(bank, dict) or not bank:
                continue
            sid = int(selected.get(name, next(iter(sorted(int(k) for k in bank if str(k).isdigit())), 1)))
            if sid not in bank:
                sid = sorted(int(k) for k in bank if str(k).isdigit())[0]
            self.instrument_sequencer_memory[name] = bank[sid]
            self.instrument_selected_sequence[name] = sid

    def _maintain_stochastic_harmonic_phase_lock(self):
        """Keep the stochastic harmonic phase reference active, including imported carriers."""
        self.sequence_phase_lock_always_on = True
        try:
            # A common phase origin plus per-step deterministic phase offsets gives
            # stochastic harmonic motion without allowing imported audio to reset it.
            self._stochastic_phase_reference = float(getattr(self, "_stochastic_phase_reference", 0.0)) % math.tau
            self._voice_phase_carry = getattr(self, "_voice_phase_carry", {}) or {}
            self._canonical_phase_lock_state = {
                "enabled": True,
                "strength": 1.0,
                "reference": self._stochastic_phase_reference,
                "carrier_independent": True,
                "canonical_composition_weight": 1.0,
                "imported_carrier_phase_lock": 0.5,
                "loaded_sample_scalar_safe": True,
            }
            # The composition is always the authoritative writable state; an
            # imported carrier may phase-steer it, but never replace it.
            self._canonical_composition_weight = 1.0
            self._imported_carrier_phase_lock = 0.5
        except Exception:
            pass

    def _refresh_after_file_input(self, reason="file_input"):
        """Re-bind seed scripts to every instrument after WAV/video/project load.

        File carriers change `carrier_present` / `carrier_rms` / `carrier_peak` in
        the seed expression environment. Without this refresh, scripts that
        branch on those names (and list seeds assigned per instrument) stay
        frozen until the next manual engine toggle.
        """
        # Imported media is a carrier, never a phase-lock disable switch.
        self.sequence_phase_lock_always_on = True
        self._maintain_stochastic_harmonic_phase_lock()
        try:
            self._canonical_render_input_context = dict(self._canonical_input_context())
        except Exception:
            self._canonical_render_input_context = {}
        # Domain engine longitudinal seed weight tracks the evaluated seed field.
        try:
            if hasattr(self, "domain_eq_engine") and self.domain_eq_engine is not None:
                self.domain_eq_engine.set_seed(float(self.get_numeric_seed() or 0.0))
        except Exception:
            pass
        # Force live engines / GOAVA / playlist paint to re-read the seed list
        # for every instrument index.
        try:
            if hasattr(self, "_on_live_source_changed"):
                self._on_live_source_changed()
        except Exception as exc:
            print(f"[FileInput] live source refresh ({reason}): {exc}")
        # R32.11 LOAD WITHOUT FREEZE: a saved project already holds its canonical playlist and sequences
        # (the rebuild is deterministic, so recomputing gives back exactly what was saved). On a project load
        # skip the synchronous rebuild and mark the canonical work as done for these inputs, so the deferred
        # unison pass does not recompute it either. A project saved without canonical output still rebuilds.
        _project_load = reason in ("project_load", "meum_project_load")
        _have_canon = False
        if _project_load:
            try:
                _banks_now = getattr(self, "instrument_sequence_banks", {}) or {}
                _have_canon = any(isinstance(m, dict) and str(m.get("canonical_owner", "")).startswith("canonical:")
                                  for b in _banks_now.values() for m in (b or {}).values())
            except Exception:
                _have_canon = False
        try:
            if hasattr(self, "_rebuild_active_canonical_playlist") and not (_project_load and _have_canon):
                # Only rebuild when at least one canonical engine is active.
                if hasattr(self, "_canonical_active_count") and self._canonical_active_count() > 0:
                    self._rebuild_active_canonical_playlist(reason=reason)
        except Exception as exc:
            print(f"[FileInput] canonical rebuild ({reason}): {exc}")
        if _project_load and _have_canon:
            try:
                _opt = getattr(self, "_scode_optimizer", None)
                if _opt is not None:
                    _opt.claim_host_work(self, "canonical")
            except Exception:
                pass
        # Clear any one-shot render cache so the next Play uses the new carrier
        # and per-instrument seed mapping.
        for attr in ("play_buffer", "_canonical_unison_effect_buffer", "_seed_time_curve"):
            if hasattr(self, attr):
                try:
                    setattr(self, attr, None)
                except Exception:
                    pass
        if hasattr(self, "scope_status_label"):
            try:
                nvals = len(self.get_seed_values(t_value=0.0) or [])
                carrier = "yes" if getattr(self, "imported_waveform", None) is not None else "no"
                self.scope_status_label.setText(
                    f"📂 {reason}: carrier={carrier} · seed components={nvals} · instruments refreshed"
                )
            except Exception:
                pass


    def open_domain_equation_editor(self):
        """Open the partitionable time/space domain equation editor dialog."""
        if not hasattr(self, 'domain_eq_engine') or self.domain_eq_engine is None:
            self.domain_eq_engine = DomainPartitionEquationEngine(seed=0.0)
        # Sync seed from UI into the engine (longitudinal weighting)
        try:
            self.domain_eq_engine.set_seed(float(self.get_numeric_seed() or 0.0))
        except Exception:
            self.domain_eq_engine.set_seed(0.0)
        dlg = DomainEquationEditorDialog(self.domain_eq_engine, parent=self)
        self._domain_eq_dialog_ref = dlg
        QTimer.singleShot(0, self._refresh_per_seq_styling)
        # Non-modal: it should run alongside the main window instead of
        # blocking it, and it gets the same animated math field as other
        # floating panels so it isn't a flat/blank dialog.
        dlg.setModal(False)
        dlg.setWindowModality(Qt.WindowModality.NonModal)
        try:
            attach_math_decor(dlg, app=self, light=False)
            cw = self.centralWidget()
            # PERF_20260909: reuse the canonical background directly.  The old
            # path constructed a throw-away ParametricMathBackground first,
            # briefly creating an extra QWidget/timer every time Domain opened.
            bg = _ensure_single_math_background(self, cw)
            bg.setGeometry(cw.rect())
            bg.lower()
            bg.show()
            self._math_decor = bg
        except Exception as _de:
            print(f"[Decor] domain dialog: {_de}")
        # Keep a reference on self BEFORE showing — a non-modal dialog with
        # no surviving Python reference gets garbage-collected and vanishes.
        self.domain_eq_dialog = dlg
        def _persist_domain_panels(*_args):
            if self._panels_per_sequence_enabled():
                try:
                    name = self._current_instrument_name()
                    panels = self._sequence_panel_slot(name)
                    panels["domain"] = {
                        "domains": copy.deepcopy(getattr(self.domain_eq_engine, "domains", []) or [])
                    }
                    print(f"[Domain] Saved domains to sequence {self._current_sequence_index(name)} panels")
                except Exception as _exc:
                    print(f"[Domain] sequence panel save: {_exc}")
        try:
            dlg.finished.connect(_persist_domain_panels)
        except Exception:
            pass
        dlg.show()
        dlg.raise_()
        dlg.activateWindow()

    def open_help_readme(self):
        """Open the full Help / Readme / scripting documentation dialog."""
        dlg = ReadmeGuideDialog(parent=self)
        dlg.exec()

    def apply_playlist_automation_to_ui(self):
        """
        Push playlist-painted automation onto live synth macros / patch gains.
        Coverage scales depth; direction vector sets sign. Updates UI knobs when present.
        """
        if not getattr(self, 'playlist_automation', None):
            return
        # Aggregate latest per-param influence
        accum = {}  # param -> weighted sum of signed amounts
        weights = {}
        for lane in self.playlist_automation:
            if not lane:
                continue
            param = lane.get("param", "eqr")
            amt = float(lane.get("amount", 0.0)) * float(lane.get("direction", 1.0))
            # Overlap reduces exclusive authority but still contributes
            ov = float(lane.get("overlap", 0.0))
            w = max(0.00, abs(amt) * (1.0 - 0.5 * ov))
            accum[param] = accum.get(param, 0.0) + amt * w
            weights[param] = weights.get(param, 0.0) + w

        def _norm(p, default=0.5):
            if weights.get(p, 0) <= 0.0:
                return default
            return float(np.clip(0.5 + accum[p] / weights[p] * 0.5, 0.0, 1.0))

        # Map onto main macros when present
        if hasattr(self, 'slider_eqr'):
            self.slider_eqr.blockSignals(True)
            self.slider_eqr.setValue(float(_norm("eqr") * 100.0))
            self.slider_eqr.blockSignals(False)
        if hasattr(self, 'slider_fractalizer'):
            self.slider_fractalizer.blockSignals(True)
            self.slider_fractalizer.setValue(float(_norm("fractalizer") * 100.0))
            self.slider_fractalizer.blockSignals(False)
        if hasattr(self, 'slider_pkp_envelope'):
            self.slider_pkp_envelope.blockSignals(True)
            self.slider_pkp_envelope.setValue(int(_norm("pkp_envelope") * 1000))
            self.slider_pkp_envelope.blockSignals(False)

        # Patch bay cable gains: scale by automation "drive" if any
        drive = _norm("drive", 0.2)
        try:
            for c in getattr(self, 'patch_connections', []) or []:
                if c.get("origin") == "additive_optimizer":
                    # Keep optimizer cables; nudge weight gently
                    c["weight"] = float(np.clip(c.get("weight", 0.5) * (0.85 + 0.3 * drive), 0.1, 1.0))
            for c in getattr(GLOBAL_BUS, 'global_cables', []) or []:
                if "gain" in c:
                    base = float(c.get("gain", 1.0))
                    c["gain"] = float(np.clip(base * (0.9 + 0.2 * drive), 0.1, 2.0))
            GLOBAL_BUS.broadcast_update()
        except Exception:
            pass

        # CANONICAL_COMMAND_PLAYLIST_ROUTING_2026:
        # Playlist Auto Target / Automator lanes can steer Master Vector,
        # Wavetable Projector, Global XMOD, Algo XMOD, and Resonance.
        # Coverage/blend/direction from the playlist row already scaled `amt`.
        try:
            st = getattr(self, "master_vector_state", None)
            if isinstance(st, dict):
                for axis, key in (("master_vector_x", "x"), ("master_vector_y", "y"), ("master_vector_z", "z")):
                    if weights.get(axis, 0) > 0.0:
                        # Map normalized 0..1 influence to -1..+1 vector axis
                        st[key] = float(np.clip((_norm(axis, 0.5) - 0.5) * 2.0, -1.0, 1.0))
                        # GROOVEBOX_R23R_GEO_OWNERSHIP_LOAD_20261103: automation steering the vector is
                        # NOT a user edit — marking it "touched" saved it as user data, so after a load the
                        # geometric synths appeared locked as userdata though nobody edited them.
                if weights.get("master_vector_drive", 0) > 0.0:
                    st["drive"] = float(np.clip(_norm("master_vector_drive", 0.5), 0.0, 1.0))
                    if hasattr(self, "slider_master_vector_drive"):
                        self.slider_master_vector_drive.blockSignals(True)
                        self.slider_master_vector_drive.setValue(int(st["drive"] * 100))
                        self.slider_master_vector_drive.blockSignals(False)
                self.master_vector_state = st
                if hasattr(self, "_master_vector_effective"):
                    self._master_vector_effective()

            wt = getattr(self, "wavetable_projector_state", None)
            if isinstance(wt, dict):
                for src, dst in (
                    ("wavetable_frame", "fold"),
                    ("wavetable_phase", "phase"),
                    ("wavetable_curvature", "curvature"),
                    ("wavetable_twist", "twist"),
                    ("wavetable_fold", "fold"),
                ):
                    if weights.get(src, 0) > 0.0:
                        wt[dst] = float(np.clip(_norm(src, float(wt.get(dst, 0.5))), 0.0, 1.0 if dst != "phase" else 1.0))
                self.wavetable_projector_state = wt
                if hasattr(self, "_update_wavetable_projector"):
                    self._update_wavetable_projector()

            gms = getattr(self, "global_mod_state", None)
            if isinstance(gms, dict):
                for src, dst in (
                    ("global_xmod", "xmod"),
                    ("global_input_xmod", "input_xmod"),
                    ("synth_panel_mod", "synth"),
                    ("patch_mod", "patch"),
                    ("script_mod", "script"),
                    ("domain_mod", "domain"),
                ):
                    if weights.get(src, 0) > 0.0:
                        # 0..1 norm -> 0..2 depth (100% center)
                        gms[dst] = float(np.clip(_norm(src, 0.5) * 2.0, 0.0, 2.0))
                self.global_mod_state = gms
                if hasattr(self, "global_xmod_slider") and weights.get("global_xmod", 0) > 0.0:
                    self.global_xmod_slider.blockSignals(True)
                    self.global_xmod_slider.setValue(int(gms.get("xmod", 1.0) * 100))
                    self.global_xmod_slider.blockSignals(False)
                if hasattr(self, "global_input_xmod_slider") and weights.get("global_input_xmod", 0) > 0.0:
                    self.global_input_xmod_slider.blockSignals(True)
                    self.global_input_xmod_slider.setValue(int(gms.get("input_xmod", 1.0) * 100))
                    self.global_input_xmod_slider.blockSignals(False)

            if weights.get("algorithm_xmod_local", 0) > 0.0:
                self.local_algorithm_xmod = float(np.clip(_norm("algorithm_xmod_local", 0.5) * 2.0, 0.0, 2.0))
                if hasattr(self, "local_algorithm_xmod_slider"):
                    self.local_algorithm_xmod_slider.blockSignals(True)
                    self.local_algorithm_xmod_slider.setValue(int(self.local_algorithm_xmod * 100))
                    self.local_algorithm_xmod_slider.blockSignals(False)
            if weights.get("algorithm_xmod_global", 0) > 0.0:
                self.global_algorithm_xmod = float(np.clip(_norm("algorithm_xmod_global", 0.5) * 2.0, 0.0, 2.0))
                if hasattr(self, "global_algorithm_xmod_slider"):
                    self.global_algorithm_xmod_slider.blockSignals(True)
                    self.global_algorithm_xmod_slider.setValue(int(self.global_algorithm_xmod * 100))
                    self.global_algorithm_xmod_slider.blockSignals(False)

            if weights.get("canonical_resonance", 0) > 0.0:
                # Automation follows the currently active protection domain.
                # Protect OFF exposes the complete 0–200% lane; protect ON 50–150%.
                _rlo, _rhi = self._canonical_resonance_range()
                self.canonical_resonance_factor = _rlo + _norm("canonical_resonance", 0.5) * (_rhi - _rlo)
                if hasattr(self, "spin_canonical_resonance"):
                    self.spin_canonical_resonance.blockSignals(True)
                    self.spin_canonical_resonance.setValue(self.canonical_resonance_factor * 100.0)
                    self.spin_canonical_resonance.blockSignals(False)
                if hasattr(self, "lbl_canonical_resonance"):
                    self.lbl_canonical_resonance.setText(
                        f"CANONICAL RESONANCE: {self.canonical_resonance_factor * 100:.0f}%"
                    )
        except Exception:
            pass

    # =====================================================================
    # SEQUENCE_BANK_V6
    # =====================================================================
    def _current_instrument_name(self):
        return (self.instrument_selector_dropdown.currentText()
                if hasattr(self, "instrument_selector_dropdown")
                else (self.instrument_names_48[0] if self.instrument_names_48 else "Operator"))

    def _current_sequence_index(self, instrument_name=None):
        name = instrument_name or self._current_instrument_name()
        return int((getattr(self, "instrument_selected_sequence", {}) or {}).get(name, 1))

    def _current_sequence_mem(self, instrument_name=None):
        name = instrument_name or self._current_instrument_name()
        banks = getattr(self, "instrument_sequence_banks", {}) or {}
        bank = banks.setdefault(name, {})
        if not bank:
            mem = self.instrument_sequencer_memory.setdefault(name, {
                "steps": [], "gates": [], "amplitudes": [], "pitches": [],
                "probabilities": [], "offsets": [], "pattern_length": DEFAULT_SEQUENCE_LENGTH,
                "sequence_length_user_owned": False,
                "track_offset": 0.0,
                "sequence_envelope_attack": 0.5, "sequence_envelope_release": 0.5
            })
            bank[1] = mem
        idx = self._current_sequence_index(name)
        if idx not in bank:
            idx = sorted(bank)[0]
            self.instrument_selected_sequence[name] = idx
        mem = bank[idx]
        # Backward-compatible deterministic chord state, stored with this instrument's sequence.
        mem.setdefault("chord_note_count", 3)
        mem.setdefault("chord_intervals", [0, 4, 7])
        mem.setdefault("chord_slot_features", [])
        mem["chord_slot_features"] = normalize_chord_slot_features(
            mem.get("chord_slot_features", []), int(mem.get("chord_note_count", 3) or 3), 512
        )
        mem.setdefault("chord_user_owned", False)
        self.instrument_sequencer_memory[name] = mem
        return mem

    def _refresh_sequence_selector(self):
        if not hasattr(self, "sequence_selector"):
            return
        name = self._current_instrument_name()
        bank = (getattr(self, "instrument_sequence_banks", {}) or {}).setdefault(name, {})
        if not bank:
            bank[1] = self.instrument_sequencer_memory.get(name, {})
        selected = self._current_sequence_index(name)
        self.sequence_selector.blockSignals(True)
        self.sequence_selector.clear()
        for idx in sorted(bank):
            mem = bank[idx]
            length = int(mem.get("pattern_length", len(mem.get("steps", [])) or 1))
            self.sequence_selector.addItem(f"Sequence {idx}  ·  {length} steps", idx)
        pos = max(0, sorted(bank).index(selected)) if selected in bank else 0
        self.sequence_selector.setCurrentIndex(pos)
        self.sequence_selector.blockSignals(False)
        seq_len = int(bank[selected].get("pattern_length", DEFAULT_SEQUENCE_LENGTH)) if selected in bank else DEFAULT_SEQUENCE_LENGTH
        self.spin_seq_length.blockSignals(True)
        self.spin_seq_length.setValue(seq_len)
        self.spin_seq_length.blockSignals(False)
        self.spin_pattern_length.blockSignals(True)
        self.spin_pattern_length.setValue(seq_len)
        self.spin_pattern_length.blockSignals(False)
        self.btn_remove_sequence.setEnabled(len(bank) > 1)

    def add_sequence(self):
        name = self._current_instrument_name()
        bank = getattr(self, "instrument_sequence_banks", {}).setdefault(name, {})
        src_idx = self._current_sequence_index(name)
        src = copy.deepcopy(bank.get(src_idx, self.instrument_sequencer_memory[name]))
        src["sequence_id"] = max(bank.keys(), default=0) + 1
        src["user_owned"] = True
        src["canonical_owner"] = None
        src["sequence_length_user_owned"] = bool(src.get("sequence_length_user_owned", False))
        new_idx = max(bank.keys(), default=0) + 1
        src["pattern_length"] = int(src.get("pattern_length", len(src.get("steps", [])) or DEFAULT_SEQUENCE_LENGTH))
        bank[new_idx] = src
        self.instrument_selected_sequence[name] = new_idx
        self.instrument_sequencer_memory[name] = src
        self._refresh_sequence_selector()
        self.reload_active_instrument_sequencer_ui()
        try: self._refresh_operator_sample_ui()
        except Exception: pass
        self._on_live_source_changed()

    def remove_sequence(self):
        name = self._current_instrument_name()
        bank = getattr(self, "instrument_sequence_banks", {}).setdefault(name, {})
        if len(bank) <= 1:
            return
        idx = self._current_sequence_index(name)
        bank.pop(idx, None)
        new_idx = sorted(bank)[max(0, sorted(bank).index(idx) - 1)] if bank else 1
        self.instrument_selected_sequence[name] = new_idx
        self.instrument_sequencer_memory[name] = bank[new_idx]
        self._refresh_sequence_selector()
        self.reload_active_instrument_sequencer_ui()
        try: self._refresh_operator_sample_ui()
        except Exception: pass
        self._on_live_source_changed()

    # =====================================================================
    # EDIT_PANELS_PER_SEQUENCE — sequence-local synth/script/patch/domain
    # =====================================================================
    def _canonical_wavetable_guide(self):
        """Deterministic global wavetable guide derived from canonical state.

        Interpolates from a fixed seed-only baseline toward a fixed seed-only
        target, scaled by a saturating function of the active engines and their levels. This guarantees more active engines can only push the guide
        further from baseline (never back toward it via phase wraparound)
        and never past the target."""
        try: seed = _safe_int_seed(self.get_numeric_seed())
        except Exception: seed = 0
        active = self._get_active_engine_set() if hasattr(self, "_get_active_engine_set") else set()
        mask = sum((i + 1) * self._canonical_level(name) for i, name in enumerate(("goava", "randomizer", "phase_lock", "seeded")) if name in active)
        trig = self._trig_engine_transform
        base = (
            float(trig("sin", seed * 0.00011 + PHI_INV)) * 0.5 + 0.5,
            float(trig("cos", seed * 0.00017 + MEUM)) * 0.5 + 0.5,
            float(trig("sin", seed * 0.00023 + PHI * MEUM)) * 0.5 + 0.5,
        )
        target = (
            float(trig("sin", seed * 0.00011 + PHI_INV + PHI)) * 0.5 + 0.5,
            float(trig("cos", seed * 0.00017 + MEUM + PHI)) * 0.5 + 0.5,
            float(trig("sin", seed * 0.00023 + PHI * MEUM + PHI)) * 0.5 + 0.5,
        )
        growth = 1.0 - math.exp(-mask / 3.0)
        return tuple(float(b + (t - b) * growth) for b, t in zip(base, target))

    def _effective_wavetable_field(self):
        st=getattr(self,"wavetable_projector_state",{}) or {}; user=np.asarray([float(st.get(k,0.5)) for k in ("x","y","z")],dtype=float); can=np.asarray(self._canonical_wavetable_guide(),dtype=float)
        # No UI control ever writes wavetable x/y/z (WavetableProjector is
        # display-only) -- these fields are never "adjusted by the user",
        # so canonical share is always 100% per _canonical_field_share.
        shares = np.asarray([self._canonical_field_share(f"wavetable:{k}") for k in ("x", "y", "z")], dtype=np.float64)
        eff=(1.0-shares)*user+shares*can
        st["canonical_share"] = float(shares.mean())
        return eff,can

    def _update_wavetable_projector(self):
        eff,can=self._effective_wavetable_field()
        st=self.wavetable_projector_state
        # The projector and drawing canvas show the instance's actual cycle.
        try:
            from wavespace import apply_wavetable_knobs as _knobs
            _w = self._effective_geometric_states(self._geo_from_buffer(), slot=self._instance_slot(getattr(self, "_geo_editor_instrument", "") or ""))["wavetable"]
            _a, _b = _knobs(*_w["coeffs"], phase=float(_w.get("phase", 0.0)), curvature=float(_w.get("curvature", .5)),
                            twist=float(_w.get("twist", .5)), fold=float(_w.get("fold", .2)))
            _cyc = self._wavespace_cycle((_a, _b), 512)
            if hasattr(self, "wavetable_projector_viz"):
                self.wavetable_projector_viz.cycle = _cyc
            if hasattr(self, "wavetable_draw_canvas"):
                if isinstance(st.get("drawn"), (list, tuple)):
                    self.wavetable_draw_canvas.set_canonical(self._wavespace_cycle(self._canonical_wavespace(self._instance_slot(getattr(self, "_geo_editor_instrument", "") or ""), lane=1), 512))
                else:
                    self.wavetable_draw_canvas.set_canonical(_cyc)
        except Exception as _wexc:
            print(f"[Wavetable] projector cycle skipped: {_wexc}")
        if hasattr(self,"wavetable_projector_viz"):
            self.wavetable_projector_viz.set_fields([st.get("x",.5),st.get("y",.5),st.get("z",.5)],can)
            self.wavetable_projector_viz.set_shape(mode=int(st.get("mode",1)),phase=float(st.get("phase",0.0)),curvature=float(st.get("curvature",.5)),twist=float(st.get("twist",.5)),fold=float(st.get("fold",.2)))
        return eff

    def _canonical_field_share(self, field_key):
        """50% on a value the user has adjusted; 100% on a value they haven't."""
        touched = getattr(self, "_canonical_field_touched", None) or set()
        return 0.5 if field_key in touched else 1.0

    def _canonical_mod_state(self):
        """Deterministic canonical counterpart to the XMOD sliders. Same
        baseline-to-target saturating growth as the wavetable guide, so stronger/more active engines increase disturbance from baseline, never
        wrap back toward it."""
        try: seed = _safe_int_seed(self.get_numeric_seed())
        except Exception: seed = 0
        growth = self._canonical_mod_growth()
        out = {}
        for j, k in enumerate(("xmod", "input_xmod", "synth", "patch", "script", "domain")):
            base_phase = seed * 0.00013 * (j + 1)
            base = 1.0 + series_sin(base_phase) * 0.9
            target = 1.0 + series_sin(base_phase + PHI) * 0.9
            out[k] = float(np.clip(base + (target - base) * growth, 0.0, 2.0))
        return out

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_CANONICAL_OWNERSHIP_20261031
    # One read/write/plan contract for canonical engines alongside user data:
    #   * a value still at its factory default is canonical-owned: the canonical
    #     value is used (100%);
    #   * a value moved off default (or touched) is user-owned/protected: the
    #     stored user value is never overwritten; continuous values blend 50/50
    #     with canonical, discrete choices use the user's value;
    #   * every canonical value derives from the same seed + GOAVA/RAND/LOCK/
    #     SEEDED activity, so all systems move in unison.
    # Applies to Vector, Wavetable, Ball, Cellular, Master Global EQ and
    # Sidechain. Effective values are computed at render time only.
    # ------------------------------------------------------------------
    _CANON_SPECS = {
        "ball": (
            ("gravity", 0.25, "c", 0.08, 0.90), ("gravity_angle_degrees", 90.0, "c", 60.0, 120.0),
            ("radius", 1.0, "c", 0.55, 1.0), ("vx", 0.7, "c", 0.30, 1.60), ("vy", -0.4, "c", -1.40, -0.15),
            ("x", 0.0, "c", -0.50, 0.50), ("y", 0.0, "c", -0.50, 0.50),
        ),
        "cellular": (
            ("rule", 30, "d", (30, 45, 73, 90, 105, 110, 150, 184)), ("generations", 16, "d", (8, 12, 16, 24, 32)),
            ("cell_types", 3, "d", (2, 3, 4)), ("width", 16, "d", (12, 16, 20, 24)), ("height", 16, "d", (12, 16, 20, 24)),
            ("neighborhood", "moore", "d", ("moore", "von_neumann")),
        ),
        "wavetable": (
            ("phase", 0.0, "c", -0.50, 0.50), ("curvature", 0.5, "c", 0.25, 0.75), ("twist", 0.5, "c", 0.25, 0.75),
            ("fold", 0.2, "c", 0.05, 0.45), ("mode", 1, "d", (1, 2, 3)),
        ),
        "sidechain": (
            ("amount", 0.0, "c", 0.0, 0.40), ("attack_ms", 5.0, "c", 2.0, 20.0), ("release_ms", 120.0, "c", 60.0, 260.0),
        ),
    }
    _CANON_LANE_INDEX = {"vector": 0, "wavetable": 1, "ball": 2, "cellular": 3, "eq": 4, "sidechain": 5}

    def _canonical_context_pair(self):
        try:
            seed = _safe_int_seed(self.get_numeric_seed())
        except Exception:
            seed = 0
        try:
            growth = float(self._canonical_mod_growth())
        except Exception:
            growth = 0.0
        return seed, growth

    def _canonical_unit(self, lane, j, ctx=None, slot=0):
        """Deterministic canonical value in [0,1] for parameter j of a lane (unison phase).

        ``slot`` is the instrument instance: each instance reads the same law at its
        own Meum-offset phase (slot 0 is the original single-instance value).
        """
        seed, growth = ctx if ctx is not None else self._canonical_context_pair()
        li = self._CANON_LANE_INDEX.get(lane, 0)
        # Seed term + a fixed golden-angle offset per parameter, so parameters in
        # one lane never collapse onto the same position (even for seed 0).
        phase = seed * 0.00013 * (j + 1 + 7 * li) + li * PHI_INV + (j + 1) * 2.399963229728653  # golden angle
        if slot:
            phase += int(slot) * MEUM * (j + 1 + li)
        base = 0.5 + 0.5 * float(series_sin(phase))
        target = 0.5 + 0.5 * float(series_sin(phase + PHI))
        return float(np.clip(base + (target - base) * growth, 0.0, 1.0))

    @staticmethod
    def _canon_is_user_owned(value, default):
        if value is None:
            return False
        if isinstance(default, str) or isinstance(value, str):
            return str(value) != str(default)
        try:
            return abs(float(value) - float(default)) > 1e-9
        except Exception:
            return False

    def _effective_canonical_block(self, lane, state, ctx=None, force_owned=False, touched=None, slot=0):
        """Return (effective dict, ownership report) for one lane's spec table.

        ``force_owned`` (the panel's Lock / protect checkbox) makes every value
        user-owned, including values still at their default.
        """
        st = dict(state or {})
        out = dict(st)
        report = []
        if touched is None:
            touched = getattr(self, "_canonical_field_touched", None) or set()
        for j, spec in enumerate(self._CANON_SPECS.get(lane, ())):
            key, default, kind = spec[0], spec[1], spec[2]
            u = self._canonical_unit(lane, j, ctx, slot=slot)
            if kind == "c":
                canon = float(spec[3] + (spec[4] - spec[3]) * u)
            else:
                choices = spec[3]
                canon = choices[int(u * len(choices)) % len(choices)]
            user_val = st.get(key, default)
            owned = bool(force_owned) or self._canon_is_user_owned(user_val, default) or f"{lane}:{key}" in touched
            if not owned:
                eff, tag = canon, "C"
            elif kind == "c":
                eff, tag = 0.5 * float(user_val) + 0.5 * canon, "U50"
            else:
                eff, tag = user_val, "U"
            out[key] = eff
            report.append((key, eff, tag))
        return out, report

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_GEOMETRY_PER_INSTRUMENT_20261031
    # The four geometric synths (Vector, Wavetable, Ball, Cellular) are no longer
    # one shared global carrier: every instrument owns one instance of each,
    # stored in instrument_param_state[name]["geo"] (and in the sequence's synth
    # panel when Edit Synth Per Seq is on). The main-window geometric panels are
    # the editor for the *selected* instrument's instance: their state dicts are
    # an editing buffer that is stored on every edit and swapped on instrument
    # switch. GOAVA remains the single-instance source.
    # ------------------------------------------------------------------
    _GEO_PREFIXES = ("master_vector:", "wavetable:", "ball:", "cellular:")

    @staticmethod
    def _geo_factory(instrument_count=None):
        fac = {
            "vector": {"x": 0.0, "y": 0.0, "z": 0.0, "drive": 0.5, "enabled": True, "guard": True},
            "wavetable": {"mode": 1, "phase": 0.0, "curvature": 0.5, "twist": 0.5, "fold": 0.2},
            "ball": {"gravity": 0.25, "gravity_angle_degrees": 90.0, "radius": 1.0, "vx": 0.7, "vy": -0.4,
                     "reverse_polarity_on_hit": True},
            "cellular": {"width": 16, "height": 16, "cell_types": 3, "generations": 16, "rule": 30,
                         "neighborhood": "moore"},
            "touched": [], "ball_locked": False, "ca_locked": False,
        }
        # GROOVEBOX_R23R_CONVOLUTION_DEFAULTS_20261031: with an instrument
        # count, the density parameters follow the convolution scheme the
        # Edit Synth windows use (Default (Convolution) / the instrument-
        # convolution schema): two instruments get the maximal density, every
        # additional instrument removes one step, down to the minimum at 128.
        # Each density parameter passes through its fixed default at the
        # scheme midpoint (n = 0.5, i.e. 66 instruments).
        if instrument_count is not None:
            try:
                d = float(_eq_convolution_default_band_count(int(instrument_count)))
            except Exception:
                d = 64.0
            n = max(0.0, min(1.0, d / 128.0))
            fac["vector"]["drive"] = float(np.clip(0.25 + 0.5 * n, 0.0, 1.0))
            fac["wavetable"]["fold"] = float(np.clip(0.4 * n, 0.05, 0.45))
            fac["ball"]["radius"] = float(np.clip(0.5 + n, 0.05, 1.0))
            _grid = int(round(8.0 + 16.0 * n))
            fac["cellular"]["width"] = _grid
            fac["cellular"]["height"] = _grid
            fac["cellular"]["generations"] = int(round(4.0 + 24.0 * n))
            fac["cellular"]["cell_types"] = int(round(2.0 + 2.0 * n))
        return fac

    def _geometric_convolution_defaults(self):
        """GROOVEBOX_R23R_CONVOLUTION_DEFAULTS_20261031: preset geometric
        defaults follow the convolution scheme for the Edit Synth windows.
        The wet side is the instrument-count convolution density (the same
        schema as Default (Convolution)); the Global Convolve slider convolves
        equally here — the same wet percentage that cross-convolves the
        structural carrier weights these preset defaults. The density rescales
        with the instrument count."""
        names = list(getattr(self, "instrument_names_48", []) or [])
        states = getattr(self, "instrument_param_state", {}) or {}
        count = max(len(names), len(states) if isinstance(states, dict) else 0, 2)
        base = self._geo_factory()
        wet = self._geo_factory(count)
        try:
            c = (float(self.spin_global_convolve.value()) / 100.0) if hasattr(self, "spin_global_convolve") else 0.0
        except Exception:
            c = 0.0
        c = min(1.0, max(0.0, c))
        out = copy.deepcopy(base)
        for lane in ("vector", "wavetable", "ball", "cellular"):
            for k, v in wet[lane].items():
                bv = base[lane].get(k, v)
                if isinstance(v, bool) or isinstance(v, str) or isinstance(bv, bool) or isinstance(bv, str):
                    continue
                if isinstance(v, int) and isinstance(bv, int):
                    out[lane][k] = int(round((1.0 - c) * float(bv) + c * float(v)))
                else:
                    out[lane][k] = float((1.0 - c) * float(bv) + c * float(v))
        return out

    # R32.9.9 CONVOLVE TRACKING: the keys of the r32 project section that change what a render
    # sounds like. The Global Convolve kernel is a function of all of them (plus the canonical
    # engine context, the seed and the frozen RAND token), so convolution follows the workspace.
    _CONVOLVE_TRACK_KEYS = ("fx", "time_fx", "synth_engine", "canonical_mode", "divergence", "divergence_user",
                            "key", "tuning", "playback_style", "song_form", "active_instruments", "mod_osc", "eq",
                            "predictive_fx", "automation", "inst_mix", "perseq")

    def _global_convolve_workspace(self):
        """(digest64, levels, active) — every workspace variable the convolve kernel tracks."""
        try:
            import project_schema as _ps
            snap = _ps.snapshot(self)
            ws = {k: snap.get(k) for k in self._CONVOLVE_TRACK_KEYS}
        except Exception:
            ws = {}
        try: ctx = dict(getattr(self, "_canonical_render_input_context", None) or self._canonical_input_context())
        except Exception: ctx = {}
        try: levels = self._canonical_levels()
        except Exception: levels = {}
        try: active = sorted(self._active_engine_sources())
        except Exception: active = []
        try: seed = int(_safe_int_seed(self.get_numeric_seed() or 1))
        except Exception: seed = 1
        blob = json.dumps({"ws": ws, "ctx": ctx, "levels": levels, "active": active, "seed": seed,
                           "rand": int(getattr(self, "_rand_instance_seed", 0) or 0),
                           "locks": self._lock_characteristics() if hasattr(self, "_lock_characteristics") else {}},
                          sort_keys=True, default=str, separators=(",", ":"))
        dig = int.from_bytes(hashlib.blake2b(blob.encode("utf-8", "replace"), digest_size=8).digest(), "big")
        return dig, levels, active

    def _global_convolve_kernel(self, klen, sample_rate, gf):
        """Global Convolve kernel that tracks the canonical engines and the workspace.

        k[n] = A(n)·Σ_j w_j·sin(2π f_j n / sr + φ_j)
          f = gf·(1, MEUM, PHI, MEUM²)          base, Meum undertow, φ partial, GOAVA partial
          w = (1, ½, ½·L_fractal, ⅓·L_goava)    partial weights follow the engine levels L ∈ [0,1]
          φ_j = 2π·u_j·(1 − L_lock)·(L_seeded ∨ L_rand)   phases are children of the workspace
                digest (u_j = seed_child64(digest, "conv", j)/2⁶⁴); PHASE LOCK pulls them back to 0
          A(n) = exp(−n/klen·3·L_div) · E(n)  divergence shortens the tail; E is a Euclidean
                gate E(n) = 1 if ⌊8n/klen⌋·5 mod 8 < 5 else 1−½·L_euclid (EUCLIDEAN pulse)
        With no engine on and divergence 0 the kernel reduces to the original base + Meum pair, so
        defaults stay neutral; every term is deterministic from the seed and saved state.
        """
        dig, L, active = self._global_convolve_workspace()
        sr = float(max(1, int(sample_rate)))
        n = np.arange(klen, dtype=np.float64)
        on = lambda k: float(L.get(k, 0.0)) if k in active else 0.0
        lf, lg, ll, ls, lr, le = (on("fractal_seed"), on("goava"), on("phase_lock"), on("seeded"),
                                  on("randomizer"), on("euclidean"))
        phase_amt = max(ls, lr) * (1.0 - ll)
        freqs = (gf, gf * MEUM_CONSTANT, gf * 1.6180339887498949, gf * MEUM_CONSTANT * MEUM_CONSTANT)
        weights = (1.0, 0.5, 0.5 * lf, (1.0 / 3.0) * lg)
        k = np.zeros(klen, dtype=np.float64)
        for j, (f, w) in enumerate(zip(freqs, weights)):
            if w <= 0.0:
                continue
            u = seed_child64(dig, "conv", j) / float(1 << 64)
            k += w * ot_sin_vec_equiv(2 * np.pi * (f / sr) * n + 2 * np.pi * u * phase_amt)
        try:
            div = float(getattr(self, "seed_divergence", 0.0) or 0.0) if getattr(self, "_r32_divergence_user", False) else 0.0
        except Exception:
            div = 0.0
        env = np.exp(-(n / max(1, klen)) * 3.0 * float(np.clip(div, 0.0, 1.0)))
        if le > 0.0:
            step = np.floor(n * 8.0 / max(1, klen)).astype(np.int64)
            env = env * np.where((step * 5) % 8 < 5, 1.0, 1.0 - 0.5 * le)
        # R32.10: Hann taper over the first half of the kernel, zero after — no hard edges, so the
        # narrow sine peaks (ringing resonance) become broad, smooth colouring.
        half = max(8, klen // 2)
        taper = np.zeros(klen, dtype=np.float64)
        taper[:half] = 0.5 - 0.5 * np.cos(2.0 * np.pi * np.arange(half) / max(1, half - 1))
        env = env * taper
        self._global_convolve_trace = {"digest": "%016x" % dig, "active": active, "phase_amt": phase_amt,
                                       "weights": list(weights), "divergence": div, "euclid": le}
        return (k * env).astype(np.float32)

    def _rescale_geometric_convolution_defaults(self):
        """R23R convolution defaults rescale: when the instrument count or the
        Global Convolve setting changes, every geometric instance still sitting
        at a default (the fixed factory preset or the previous convolution
        preset) follows the new density. User-touched instances stay
        untouched, exactly like every other user-owned value."""
        new_fac = self._geometric_convolution_defaults()
        fixed = self._geo_factory()
        prev = getattr(self, "_geo_convolution_preset", None)
        changed = 0
        for name, ps in (getattr(self, "instrument_param_state", {}) or {}).items():
            geo = ps.get("geo") if isinstance(ps, dict) else None
            if not isinstance(geo, dict):
                continue
            for lane in ("vector", "wavetable", "ball", "cellular"):
                cur = geo.get(lane)
                if not isinstance(cur, dict):
                    continue
                refs = [fixed[lane]]
                if isinstance(prev, dict) and isinstance(prev.get(lane), dict):
                    refs.append(prev[lane])
                for ref in refs:
                    if all(cur.get(k) == v for k, v in ref.items() if k in cur):
                        for k, v in new_fac[lane].items():
                            cur[k] = copy.deepcopy(v)
                        changed += 1
                        break
        self._geo_convolution_preset = copy.deepcopy(new_fac)
        if changed:
            try:
                self._sync_panel_geometry_preview()
            except Exception:
                pass
        return changed

    def _geo_from_buffer(self):
        """Instance dict built from the editor buffer (the selected instrument)."""
        fac = self._geometric_convolution_defaults()  # R23R convolution preset
        mv = dict(getattr(self, "master_vector_state", {}) or {})
        wt = dict(getattr(self, "wavetable_projector_state", {}) or {})
        bl = dict(getattr(self, "ball_synth_params", {}) or {})
        ca = dict(getattr(self, "cellular_synth_params", {}) or {})
        geo = {
            "vector": {k: mv.get(k, d) for k, d in fac["vector"].items()},
            "wavetable": {k: wt.get(k, d) for k, d in fac["wavetable"].items()},
            "ball": {k: bl.get(k, d) for k, d in fac["ball"].items()},
            "cellular": {k: ca.get(k, d) for k, d in fac["cellular"].items()},
            "touched": sorted(t for t in (getattr(self, "_canonical_field_touched", None) or set())
                              if str(t).startswith(self._GEO_PREFIXES)),
            "ball_locked": bool(getattr(self, "ball_manual_activity_locked", False)),
            "ca_locked": bool(getattr(self, "ca_single_cell_activity_locked", False)),
        }
        if isinstance(wt.get("drawn"), (list, tuple)) and len(wt["drawn"]) >= 4:
            geo["wavetable"]["drawn"] = [round(float(v), 6) for v in wt["drawn"]]
        for k in ("x", "y"):
            if k in bl:
                geo["ball"][k] = float(bl[k])
        if ca.get("manual_cells"):
            geo["cellular"]["manual_cells"] = [list(map(int, q)) for q in ca["manual_cells"]]
        return geo

    def _geo_buffer_store(self, name=None):
        """Store the editor buffer into the instrument's instance (and its sequence panel)."""
        if getattr(self, "_geo_loading", False):
            return
        name = name or getattr(self, "_geo_editor_instrument", None)
        if not name and hasattr(self, "instrument_selector_dropdown"):
            name = self.instrument_selector_dropdown.currentText()
            self._geo_editor_instrument = name or None
        if not name:
            return
        geo = self._geo_from_buffer()
        if not hasattr(self, "instrument_param_state") or self.instrument_param_state is None:
            self.instrument_param_state = {}
        prev = (self.instrument_param_state.get(name) or {}).get("geo")
        if isinstance(prev, dict):
            # User-owned state in the stored instance wins unless the editor itself changed it;
            # a stale buffer used to wipe a lock / drawn cycle set outside the editor.
            edited = getattr(self, "_geo_editor_owned_edits", set())
            for flag, lane, edit in (("ball_locked", "ball", "ball_lock"), ("ca_locked", "cellular", "ca_lock")):
                if prev.get(flag) and edit not in edited:
                    geo[flag] = True
                    geo[lane] = copy.deepcopy(prev.get(lane) or geo[lane])
            for lane, key, edit in (("wavetable", "drawn", "drawn"), ("cellular", "manual_cells", "manual_cells")):
                pv = (prev.get(lane) or {}).get(key)
                if pv and edit not in edited and not (geo.get(lane) or {}).get(key):
                    geo.setdefault(lane, {})[key] = copy.deepcopy(pv)
        self.instrument_param_state.setdefault(name, {})["geo"] = geo
        try:
            if self._panels_per_sequence_enabled():
                panels = self._sequence_panel_slot(name)
                if isinstance(panels, dict) and isinstance(panels.get("synth"), dict) and panels["synth"]:
                    panels["synth"]["geo"] = copy.deepcopy(geo)
        except Exception:
            pass

    def _geo_buffer_load(self, name):
        """Load an instrument's instance into the editor buffer + panels."""
        if not name:
            return
        self._geo_loading = True
        try:
            ps = (getattr(self, "instrument_param_state", {}) or {}).get(name, {}) or {}
            geo = ps.get("geo") if isinstance(ps.get("geo"), dict) else self._geometric_convolution_defaults()  # R23R convolution preset
            fac = self._geometric_convolution_defaults()
            for lane, attr in (("vector", "master_vector_state"), ("wavetable", "wavetable_projector_state"),
                               ("ball", "ball_synth_params"), ("cellular", "cellular_synth_params")):
                buf = getattr(self, attr, None)
                if not isinstance(buf, dict):
                    buf = {}
                    setattr(self, attr, buf)
                for k in ("drawn",) if lane == "wavetable" else (("x", "y") if lane == "ball" else (("manual_cells",) if lane == "cellular" else ())):
                    buf.pop(k, None)
                buf.update(copy.deepcopy(fac[lane]))
                buf.update(copy.deepcopy(dict(geo.get(lane, {}) or {})))
            touched = set(t for t in (getattr(self, "_canonical_field_touched", None) or set())
                          if not str(t).startswith(self._GEO_PREFIXES))
            touched.update(str(t) for t in (geo.get("touched") or []))
            self._canonical_field_touched = touched
            self.ball_manual_activity_locked = bool(geo.get("ball_locked", False))
            self.ca_single_cell_activity_locked = bool(geo.get("ca_locked", False))
            self._geo_editor_owned_edits = set()   # fresh buffer: nothing edited yet
            self._geo_editor_instrument = name
            self._geo_refresh_widgets()
            self._geo_panel_mix_refresh(name)
        finally:
            self._geo_loading = False
        try:
            self._refresh_canonical_ownership_labels()
        except Exception:
            pass

    def _geo_migrate_legacy(self):
        """Old projects: the former shared geometric settings become each instrument's instance."""
        names = list(getattr(self, "instrument_names_48", []) or [])
        ps = getattr(self, "instrument_param_state", None)
        if ps is None:
            ps = self.instrument_param_state = {}
        if any(isinstance((ps.get(n) or {}).get("geo"), dict) for n in names):
            return
        geo = self._geo_from_buffer()
        geo["touched"] = self._geo_real_touched(geo)
        for n in names:
            ps.setdefault(n, {})["geo"] = copy.deepcopy(geo)

    def _geo_real_touched(self, geo):
        """Keep only touched marks whose value really differs from the default instance
        (GROOVEBOX_R23R_GEO_OWNERSHIP_LOAD_20261103)."""
        fac = self._geometric_convolution_defaults()
        lanes = {"master_vector:": "vector", "wavetable:": "wavetable", "ball:": "ball", "cellular:": "cellular"}
        keep = []
        for t in (geo.get("touched") or []):
            t = str(t)
            lane = next((lanes[p] for p in lanes if t.startswith(p)), None)
            if lane is None:
                keep.append(t); continue
            k = t.split(":", 1)[1]
            cur = (geo.get(lane) or {}).get(k, None)
            ref = (fac.get(lane) or {}).get(k, None)
            if lane == "vector" and k in ("x", "y", "z"):
                ref = 0.0
            try:
                same = cur is None or (ref is not None and abs(float(cur) - float(ref)) < 1e-9)
            except (TypeError, ValueError):
                same = cur == ref
            if not same:
                keep.append(t)
        return sorted(set(keep))

    def _geo_refresh_widgets(self):
        """Push the editor buffer into every geometric panel widget (signals blocked)."""
        def _set(w, v):
            if w is None:
                return
            try:
                w.blockSignals(True)
                if hasattr(w, "setChecked") and isinstance(v, bool):
                    w.setChecked(v)
                elif hasattr(w, "setCurrentText") and isinstance(v, str):
                    w.setCurrentText(v)
                elif hasattr(w, "setValue"):
                    w.setValue(v)
            except Exception:
                pass
            finally:
                try: w.blockSignals(False)
                except Exception: pass
        mv = getattr(self, "master_vector_state", {}) or {}
        for k, pair in (getattr(self, "master_vector_sliders", {}) or {}).items():
            _set(pair[0], int(round(float(mv.get(k, 0.0)) * 100)))
            try: pair[1].setText(f"{float(mv.get(k, 0.0)):+.2f}")
            except Exception: pass
        _set(getattr(self, "slider_master_vector_drive", None), int(round(float(mv.get("drive", 0.5)) * 100)))
        _set(getattr(self, "btn_master_vector_convert", None), bool(mv.get("enabled", True)))
        _set(getattr(self, "chk_master_vector_guard", None), bool(mv.get("guard", True)))
        try:
            btn = getattr(self, "btn_master_vector_convert", None)
            if btn is not None:
                btn.setText("VECTOR CONVERT · ON" if bool(mv.get("enabled", True)) else "VECTOR CONVERT · OFF")
        except Exception:
            pass
        wt = getattr(self, "wavetable_projector_state", {}) or {}
        for k in ("phase", "curvature", "twist", "fold"):
            _set(getattr(self, "spin_wt_" + k, None), float(wt.get(k, 0.0)))
        cm = getattr(self, "combo_wavetable_mode", None)
        if cm is not None:
            try:
                cm.blockSignals(True); cm.setCurrentIndex(max(0, min(2, int(wt.get("mode", 1)) - 1)))
            finally:
                cm.blockSignals(False)
        cv = getattr(self, "wavetable_draw_canvas", None)
        if cv is not None:
            cv.set_table(wt.get("drawn") if isinstance(wt.get("drawn"), (list, tuple)) else None)
        bl = getattr(self, "ball_synth_params", {}) or {}
        for k in ("gravity", "gravity_angle_degrees", "radius", "vx", "vy"):
            _set(getattr(self, "spin_ball_" + k, None), float(bl.get(k, 0.0)))
        _set(getattr(self, "chk_ball_reverse_polarity", None), bool(bl.get("reverse_polarity_on_hit", True)))
        _set(getattr(self, "chk_ball_manual_lock", None), bool(getattr(self, "ball_manual_activity_locked", False)))
        bp = getattr(self, "ball_synth_preview", None)
        if bp is not None and hasattr(bp, "set_position"):
            bp.set_position(float(bl.get("x", 0.0)), float(bl.get("y", 0.0)), user=("x" in bl or "y" in bl))
        ca = getattr(self, "cellular_synth_params", {}) or {}
        for k in ("width", "height", "cell_types", "generations", "rule"):
            _set(getattr(self, "spin_ca_" + k, None), int(ca.get(k, 0)))
        _set(getattr(self, "combo_ca_neighborhood", None), str(ca.get("neighborhood", "moore")))
        _set(getattr(self, "chk_ca_single_cell_lock", None), bool(getattr(self, "ca_single_cell_activity_locked", False)))
        cp = getattr(self, "cellular_synth_preview", None)
        if cp is not None:
            try:
                cp.configure(int(ca.get("width", 16)), int(ca.get("height", 16)))
                cp.cells = {tuple(q) for q in (ca.get("manual_cells") or []) if isinstance(q, (list, tuple)) and len(q) == 2}
                cp.update()
            except Exception:
                pass
        name = getattr(self, "_geo_editor_instrument", "") or ""
        try:
            disp = str((getattr(self, "instrument_display_names", {}) or {}).get(name) or name)
        except Exception:
            disp = name
        for attr, title in (("master_vector_group", "LOCAL ▸ VECTOR SYNTH"), ("wavetable_projector_group", "LOCAL ▸ WAVETABLE SYNTH · DRAW"),
                            ("ball_synth_group", "LOCAL ▸ BOUNCING BALL SYNTH"), ("cellular_synth_group", "LOCAL ▸ CELLULAR AUTOMATA SYNTH")):
            g = getattr(self, attr, None)
            if g is not None:
                try:
                    _where = (f"SEQ #{self._current_sequence_index(name)}" if self._panels_per_sequence_enabled() else "MAIN") if name else ""
                    g.setTitle(f"{title} · {disp} · {_where}" if disp else title)
                except Exception: pass
        try:
            self._update_wavetable_projector()
        except Exception:
            pass

    def _effective_geometric_states(self, geo=None, slot=None):
        """Effective Vector / Wavetable / Ball / Cellular for one instrument instance.

        ``geo`` None = the editor buffer (selected instrument; updates the
        ownership readouts). Otherwise an instance dict from instrument params.
        Canonical values are written per slot wherever the instance is at default.
        """
        buffer_mode = geo is None
        if buffer_mode:
            geo = self._geo_from_buffer()
            if slot is None:
                slot = self._instance_slot(getattr(self, "_geo_editor_instrument", "") or "")
        slot = int(slot or 0)
        fac = self._geometric_convolution_defaults()  # R23R convolution preset
        ctx = self._canonical_context_pair()
        touched = set(str(t) for t in (geo.get("touched") or []))
        reports = {}
        # Vector: user XYZ (0 = default) 50/50 with the slot's canonical direction.
        vst = dict(fac["vector"]); vst.update(dict(geo.get("vector", {}) or {}))
        try:
            vcan = self._canonical_master_vector(slot)
        except Exception:
            vcan = (0.0, 0.0, 0.0)
        vrep = []
        for k, c in zip(("x", "y", "z"), vcan):
            uv = float(vst.get(k, 0.0) or 0.0)
            owned = abs(uv) > 1e-9 or f"master_vector:{k}" in touched
            vst[k] = 0.5 * uv + 0.5 * float(c) if owned else float(c)
            vrep.append((k, vst[k], "U50" if owned else "C"))
        reports["vector"] = vrep
        # Wavetable: a drawn cycle makes the instance's wavetable user-owned
        # (cycle + knobs exactly as set); otherwise canonical writes the cycle
        # and the knob values follow the ownership contract.
        wraw = dict(fac["wavetable"]); wraw.update(dict(geo.get("wavetable", {}) or {}))
        _drawn = wraw.get("drawn")
        if isinstance(_drawn, (list, tuple)) and len(_drawn) >= 4:
            wst = {k: wraw.get(k, d) for k, d in fac["wavetable"].items()}
            wrep = [(k, wst[k], "U") for k in ("phase", "curvature", "twist", "fold", "mode")]
            wst["coeffs"] = self._drawn_wavespace(_drawn); wst["cap"] = 256
            wrep.append(("cycle", "drawn", "U"))
        else:
            wst, wrep = self._effective_canonical_block("wavetable", wraw, ctx, touched=touched, slot=slot)
            wst["coeffs"] = self._canonical_wavespace(slot, lane=1); wst["cap"] = WAVESPACE_HARMONICS
            wrep.append(("cycle", "wavespace", "C"))
        wst.pop("drawn", None)
        try:
            guide = self._canonical_wavetable_guide()
            for k, g in zip(("x", "y", "z"), guide):
                wst[k] = float(g)
        except Exception:
            pass
        reports["wavetable"] = wrep
        braw = dict(fac["ball"]); braw.update(dict(geo.get("ball", {}) or {}))
        bst, brep = self._effective_canonical_block("ball", braw, ctx, force_owned=bool(geo.get("ball_locked")),
                                                    touched=touched, slot=slot)
        reports["ball"] = brep
        craw = dict(fac["cellular"]); craw.update(dict(geo.get("cellular", {}) or {}))
        _ca_locked = bool(geo.get("ca_locked"))
        cst, crep = self._effective_canonical_block("cellular", craw, ctx, force_owned=_ca_locked,
                                                    touched=touched, slot=slot)
        _cells = cst.get("manual_cells") or []
        if _cells or _ca_locked:
            crep.append(("cells", len(_cells), "U"))
        else:
            cst["manual_cells"] = self._canonical_cells(int(cst.get("width", 16) or 16), int(cst.get("height", 16) or 16), slot)
            crep.append(("cells", len(cst["manual_cells"]), "C"))
        reports["cellular"] = crep
        if buffer_mode:
            self._canonical_ownership_report = dict(getattr(self, "_canonical_ownership_report", {}) or {}, **reports)
        return {"vector": vst, "wavetable": wst, "ball": bst, "cellular": cst}


    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_WAVESPACE_20261031 — per-instrument wavespace + geometry.
    # Each instrument's Edit Synth panel owns one instance of the geometric
    # synths: a wavespace cycle (drawn by the user, else a seeded canonical
    # point of waveform space), a vector (X/Y/Z), and Vector/Ball/Cellular
    # depths. The Ball trajectory and Cellular density fields are the global
    # geometric synths' (computed once per render), read by each instance at
    # its own golden-ratio slot phase.
    # ------------------------------------------------------------------
    _INSTANCE_GEO_KEYS = (("geo_vec_x", 0.0), ("geo_vec_y", 0.0), ("geo_vec_z", 0.0),
                          ("geo_vector_depth", None), ("geo_ball_depth", None), ("geo_cell_depth", None))

    def _wavespace_seed(self):
        try:
            return int(_safe_int_seed(self.get_numeric_seed()))
        except Exception:
            return 0

    def _canonical_wavespace(self, slot, lane=0):
        seed = self._wavespace_seed()
        cache = self.__dict__.setdefault("_wavespace_coeff_cache", {})
        key = ("c", seed, int(slot), int(lane))
        if key not in cache:
            if len(cache) > 512:
                cache.clear()
            cache[key] = canonical_wavespace_coefficients(seed, slot, lane)
        return cache[key]

    def _drawn_wavespace(self, table):
        arr = np.asarray(table, dtype=np.float32).ravel()
        cache = self.__dict__.setdefault("_wavespace_coeff_cache", {})
        key = ("d", zlib.crc32(arr.tobytes()), arr.size)
        if key not in cache:
            if len(cache) > 512:
                cache.clear()
            cache[key] = drawn_wave_coefficients(arr)
        return cache[key]

    @staticmethod
    def _wavespace_cycle(coeffs, n=512):
        a, b = coeffs
        return fourier_wave(np.linspace(0.0, 2.0 * math.pi, n, endpoint=False), a, b).astype(np.float32)

    def _instance_slot(self, name):
        """Canonical slot of an instrument's instance — the render's _vo.

        Under full canonical unison every instance reads slot 0, so canonical
        output never depends on how many instruments exist.
        """
        try:
            if self._full_canonical_unison_active():
                return 0
        except Exception:
            pass
        names = list(getattr(self, "instrument_names_48", []) or [])
        idx = names.index(name) if name in names else 0
        return canonical_master_slot(idx, max(2, len(names)))

    def _prepare_render_geometry(self):
        """Per-render cache for instance Ball trajectories / Cellular densities."""
        self._render_geometry_cache = {}
        self._render_geometry = {}
        return self._render_geometry

    def _geo_params_with_algo(self, st, op_name, phase):
        """Params whose geometric instance carries the Global Play Geometric Algo drive (st itself when 0)."""
        gd = self._global_algo_kind_drive("geometric", op_name, phase)
        if not gd:
            return st
        out = dict(st if isinstance(st, dict) else {})
        geo = copy.deepcopy(out.get("geo")) if isinstance(out.get("geo"), dict) else self._geometric_convolution_defaults()
        gf = 1.0 + 0.25 * gd
        for lane, keys in (("vector", ("x", "y", "z", "drive")), ("wavetable", ("phase", "curvature", "twist", "fold")),
                           ("ball", ("gravity", "radius", "vx", "vy"))):
            d = geo.get(lane)
            if isinstance(d, dict):
                for k in keys:
                    if isinstance(d.get(k), float):
                        d[k] = d[k] * gf
        out["geo"] = geo
        return out

    def _instance_voice_geometry(self, op_name, op_idx, params=None):
        """Everything one instrument's geometric-synth instance contributes to its voice."""
        from spatial_synth_engines import throw_ball as _tb
        from wavespace import apply_wavetable_knobs as _knobs
        st = params if isinstance(params, dict) else {}
        geo = st.get("geo") if isinstance(st.get("geo"), dict) else None
        if geo is None and params is None:
            # Only when no render params are given: under full unison the render
            # passes params without panels, so the canonical instance is used.
            geo = ((getattr(self, "instrument_param_state", {}) or {}).get(op_name, {}) or {}).get("geo")
        if not isinstance(geo, dict):
            geo = self._geometric_convolution_defaults()  # R23R convolution preset
        eff = self._effective_geometric_states(geo, slot=int(op_idx))
        mix = self._geometric_mixer_snapshot()
        w = eff["wavetable"]
        a, b = _knobs(*w["coeffs"], phase=float(w.get("phase", 0.0)), curvature=float(w.get("curvature", 0.5)),
                      twist=float(w.get("twist", 0.5)), fold=float(w.get("fold", 0.2)))
        v = eff["vector"]
        vdepth = float(mix["vector"]) * min(1.0, 2.0 * float(v.get("drive", 0.5))) if bool(v.get("enabled", True)) else 0.0
        cache = self.__dict__.setdefault("_render_geometry_cache", {})
        bkey = ("ball", json.dumps(eff["ball"], sort_keys=True, default=str))
        if bkey not in cache:
            try:
                cache[bkey] = _ws_ball_curves(eff["ball"], _tb)
            except Exception:
                cache[bkey] = None
        ckey = ("ca", json.dumps(eff["cellular"], sort_keys=True, default=str))
        if ckey not in cache:
            try:
                cache[ckey] = _ws_cellular_density(eff["cellular"])
            except Exception:
                cache[ckey] = None
        return {"coeffs": (a, b), "cap": int(w.get("cap", WAVESPACE_HARMONICS)), "slot": int(op_idx),
                "vector": (float(v["x"]), float(v["y"]), float(v["z"])),
                "ball": cache[bkey], "density": cache[ckey],
                "depths": {"vector": vdepth, "ball": float(mix["ball"]), "cellular": float(mix["cellular"])},
                "wt_gain": float(mix["wavetable"]),
                # Instance x Main synth / Instance x Global mod couplings (mixer).
                "cross": float(np.clip(float(mix.get("cross_mod", 0.0)) / 0.02, 0.0, 1.0)),
                "ensemble": float(np.clip(float(mix.get("ensemble_mod_amt", 0.0)), 0.0, 0.5))}

    def _canonical_cells(self, width, height, slot=0):
        """Canonical seed cells for the Cellular synth while the user has placed none."""
        seed = self._wavespace_seed()
        growth = float(self._canonical_mod_growth()) if hasattr(self, "_canonical_mod_growth") else 0.0
        count = 1 + int(((seed % 9973) * PHI_INV) % 1.0 * 4.0 + 4.0 * growth)
        cells = []
        for j in range(count):
            u = ((seed + 1) * math.sqrt(2.0) + (j + 1) * PHI_INV + int(slot) * MEUM_INV) % 1.0
            v = ((seed + 1) * math.sqrt(3.0) + (j + 1) * MEUM_NORM * 5.0 + int(slot) * PHI_INV) % 1.0
            c = [int(u * width) % max(1, width), int(v * height) % max(1, height)]
            if c not in cells:
                cells.append(c)
        return cells

    def _effective_master_eq_points(self):
        """Master Global EQ: user-owned only (blank/flat by default).

        GLOBAL_EQ_SIDECHAIN_USER_ONLY_20261102: canonical engines already shape EQ per instrument, so a
        canonical global curve would be redundant; the global curve is exactly what the user drew.
        """
        user = getattr(self, "master_global_eq_points", [[0.0, 0.0], [1.0, 0.0]]) or [[0.0, 0.0], [1.0, 0.0]]
        pts = [[float(q[0]), float(q[1])] for q in user]
        self._canonical_ownership_report = dict(getattr(self, "_canonical_ownership_report", {}) or {},
                                                eq=[("curve", max((abs(q[1]) for q in pts), default=0.0), "U")])
        return pts

    def _effective_sidechain_global(self):
        state = getattr(self, "sidechain_state", {}) or {}
        g = dict(state.get("global", {}) if isinstance(state, dict) else {})
        # GLOBAL_EQ_SIDECHAIN_USER_ONLY_20261102: the global sidechain is user-owned (default 0); canonical
        # engines contribute only through the local (per-target / per-step) scope.
        g.setdefault("amount", 0.0)
        rep = [(k, g.get(k), "U") for k in ("amount", "attack_ms", "release_ms") if k in g]
        self._canonical_ownership_report = dict(getattr(self, "_canonical_ownership_report", {}) or {}, sidechain=rep)
        return g

    def _canonical_step_sidechain(self, op_idx, row_idx, s_idx, pattern_len, growth=None):
        """Phase-locked canonical per-step sidechain depth (0 with no canonical activity).

        ONLY_LISTED_FX_20261102: sidechain ducking is not an allowed effect, so canonical engines no longer
        add it on their own; only a depth the user paints on a step (or a Sidechain mod route) applies.
        """
        if os.environ.get("GROOVEBOX_CANONICAL_SIDECHAIN", "") != "1":
            return 0.0
        if growth is None:
            growth = self._canonical_mod_growth()
        if growth <= 0.0:
            return 0.0
        n = max(1, int(pattern_len))
        slot = INSTRUMENT_PHASE_LOCK_48[int(op_idx) % 48]
        w = float(series_sin(2.0 * _SERIES_PI * (int(s_idx) + 0.5) / float(n) + slot + 0.17 * int(row_idx)))
        return float(np.clip(growth * 0.35 * (0.5 + 0.5 * w), 0.0, 0.35))

    def _on_gui_thread(self):
        app = QApplication.instance()
        return app is None or QThread.currentThread() == app.thread()

    def _open_live_jam_dialog(self):
        try:
            from live_jam import LiveJamController
            from live_jam_ui import LiveJamDialog
            if not isinstance(getattr(self, "_live_jam_controls", None), dict):
                self._live_jam_controls = {}
            if not isinstance(getattr(self, "_live_jam_fx", None), dict):
                self._live_jam_fx = {}
            if getattr(self, "_live_jam_controller", None) is None:
                self._live_jam_controller = LiveJamController(self)
            dlg = getattr(self, "_live_jam_dialog", None)
            if dlg is None:
                dlg = self._live_jam_dialog = LiveJamDialog(self, self)
            dlg.show(); dlg.raise_(); dlg.activateWindow()
        except Exception as exc:
            QMessageBox.warning(self, "Live Jam", f"Could not open Live Jam: {exc}")

    def _handle_live_jam_event(self, event):
        """Apply jam-only controls to the live audition voice; never edits project data."""
        if not isinstance(event, dict):
            return False
        kind = str(event.get("kind", ""))
        if kind in ("macro", "envelope", "mouse"):
            target = str(event.get("target", ""))
            if not target:
                return False
            try:
                value = max(0.0, min(1.0, float(event.get("value", 0.5))))
            except Exception:
                return False
            self._live_jam_controls[target] = value
            if target in ("filter", "resonance", "drive", "damping", "attack", "release", "amplitude", "tuning"):
                try:
                    if hasattr(self, "scope_status_label"):
                        self.scope_status_label.setText(f"🎛 LIVE JAM · {target.upper()} {value:.2f}")
                except Exception:
                    pass
            return True
        if kind in ("fx", "fx_toggle"):
            target = str(event.get("target", "jam_fx"))
            enabled = bool(event.get("enabled", not self._live_jam_fx.get(target, False)))
            self._live_jam_fx[target] = enabled
            self._live_jam_controls[f"fx:{target}"] = 1.0 if enabled else 0.0
            return True
        if kind == "jam_note":
            try:
                self._jam_replay_bend = max(-12.0, min(12.0, float(event.get("semitones", 0.0))))
                self._keychart_trigger(int(event.get("degree", 0)), str(event.get("key", "")),
                                       sample_binding=event.get("sample_binding"))
            except Exception:
                return False
            finally:
                try: delattr(self, "_jam_replay_bend")
                except Exception: pass
            return True
        if kind == "sequence":
            item = event.get("item")
            try:
                sid = int(item)
                if hasattr(self, "sequence_selector"):
                    pos = self.sequence_selector.findData(sid)
                    if pos >= 0:
                        self.sequence_selector.setCurrentIndex(pos)
                        return True
            except Exception:
                pass
            self._live_jam_pending_sequence = str(item)
            return True
        return False

    def _open_random_object_dialog(self):
        try:
            from random_object import RandomObjectDialog
            if RandomObjectDialog is None:
                raise RuntimeError("Qt Random Object dialog is unavailable")
            dlg = getattr(self, "_random_object_dialog", None)
            if dlg is None:
                dlg = self._random_object_dialog = RandomObjectDialog(self, self)
            dlg.show(); dlg.raise_(); dlg.activateWindow()
        except Exception as exc:
            QMessageBox.warning(self, "Random Object", f"Could not open Random Object: {exc}")

    def _gui_refresh(self, key, fn):
        """Run fn now on the GUI thread, or once (coalesced by key) from a worker."""
        if self._on_gui_thread():
            fn()
            return
        pending = getattr(self, "_gui_refresh_pending", None)
        bridge = getattr(self, "_gui_call_bridge", None)
        if bridge is None or pending is None or key in pending:
            return
        pending.add(key)
        def _run():
            pending.discard(key)
            fn()
        bridge.call.emit(_run)

    def _schedule_canonical_label_refresh(self):
        if not self._on_gui_thread():
            self._gui_refresh("canonical_label_schedule", self._schedule_canonical_label_refresh)
            return
        t = getattr(self, "_canonical_label_timer", None)
        if t is None:
            t = QTimer(self); t.setSingleShot(True); t.timeout.connect(self._refresh_canonical_ownership_labels)
            self._canonical_label_timer = t
        t.start(180)

    def _refresh_canonical_ownership_labels(self):
        """Show every effective value and who owns it (C canonical, U user, U50 blend)."""
        try:
            self._effective_geometric_states(); self._effective_master_eq_points(); self._effective_sidechain_global()
        except Exception:
            return
        rep = getattr(self, "_canonical_ownership_report", {}) or {}
        try:
            _slot = self._instance_slot(getattr(self, "_geo_editor_instrument", "") or "")
            _eff = self._effective_geometric_states(self._geo_from_buffer(), slot=_slot)
            from spatial_synth_engines import throw_ball as _tb
            from wavespace import ball_curves as _bc
            _bcv = _bc(_eff["ball"], _tb)
            if hasattr(self, "ball_synth_preview") and hasattr(self.ball_synth_preview, "set_canonical"):
                _path = list(zip(_bcv["x"][::4], _bcv["y"][::4])) if _bcv else []
                self.ball_synth_preview.set_canonical(float(_eff["ball"].get("x", 0.0)), float(_eff["ball"].get("y", 0.0)), _path)
            if hasattr(self, "cellular_synth_preview"):
                self.cellular_synth_preview.canonical_cells = {tuple(q) for q in (_eff["cellular"].get("manual_cells") or [])}
                self.cellular_synth_preview.update()
        except Exception as _pexc:
            print(f"[Geometry] preview refresh skipped: {_pexc}")
        def fmt(items):
            parts = []
            for k, v, tag in items:
                vv = f"{v:.2f}" if isinstance(v, float) else str(v)
                parts.append(f"{k} {vv}·{tag}")
            return "  ".join(parts)
        for lane, attr in (("vector", "lbl_vector_canonical"), ("wavetable", "lbl_wavetable_canonical"),
                           ("ball", "lbl_ball_canonical"), ("cellular", "lbl_cellular_canonical"),
                           ("eq", "lbl_master_eq_canonical"), ("sidechain", "lbl_sidechain_canonical")):
            lab = getattr(self, attr, None)
            if lab is not None and lane in rep:
                lab.setText("EFFECTIVE ▸ " + fmt(rep[lane]))
                lab.setToolTip("C = canonical (value at default), U = user-owned (protected), "
                               "U50 = user 50% + canonical 50%. Stored user values are never overwritten.")

    def _canonical_mod_growth(self):
        """0 with no GOAVA/RAND/LOCK/SEEDED activity, saturating toward 1 as they engage."""
        active = self._get_active_engine_set() if hasattr(self, "_get_active_engine_set") else set()
        mask = sum((i + 1) * self._canonical_level(name) for i, name in enumerate(("goava", "randomizer", "phase_lock", "seeded", "euclidean")) if name in active)
        return 1.0 - math.exp(-mask / 3.0)

    def _canonical_mod_depth_curve(self, op_idx, row_idx, n_rows, target=None, growth=None):
        """Canonical Mod Depth for one instrument on one playlist row (1.0 = neutral).

        GROOVEBOX_R23R_CANONICAL_MOD_DEPTH_20261031: the seeded canonical XMOD
        target sets the strength; one series cycle across the playlist sets the
        arrangement shape; each instrument is offset by its INSTRUMENT_PHASE_LOCK_48
        slot so every voice moves together but phase-locked, for any number of
        instruments. With no canonical engines active the curve is exactly 1.0.
        """
        if growth is None:
            growth = self._canonical_mod_growth()
        if growth <= 0.0:
            return 1.0
        if target is None:
            target = float(self._canonical_mod_state().get("xmod", 1.0))
        n = max(1, int(n_rows))
        r = int(row_idx)
        cx = self._mod_couple_ctx(n)
        # LOCK aligns the instruments: their slot offsets shrink by coupling·L_lock
        slot = INSTRUMENT_PHASE_LOCK_48[int(op_idx) % 48] * (1.0 - cx["lock_pull"])
        # RAND × GOAVA: the frozen RAND token indexes GOAVA's curve; that value shifts the phase
        phase = 2.0 * _SERIES_PI * (r + 0.5) / float(n) + slot + cx["goava_phase"]
        wave = float(series_sin(phase))
        if cx["seeded"] > 0.0:          # SEEDED live random: a seed-child value per (instrument, row)
            u = seed_child64(cx["seed"], "modrow", int(op_idx), r) / float(1 << 64)
            wave = (1.0 - cx["seeded"]) * wave + cx["seeded"] * (2.0 * u - 1.0)
        if cx["fractal_pull"] > 0.0 and cx["fractal"] is not None:   # LOCK × FRACTAL: follow the L-system contour
            wave = (1.0 - cx["fractal_pull"]) * wave + cx["fractal_pull"] * float(cx["fractal"][r % len(cx["fractal"])])
        row_target = float(np.clip(target * (1.0 + 0.5 * wave), 0.0, 2.0))
        depth = float(np.clip(1.0 + float(growth) * (row_target - 1.0), 0.0, 2.0))
        if cx["euclid"] > 0.0 and cx["pattern"]:   # EUCLIDEAN gate: off-pulse rows pulled back toward neutral
            if not cx["pattern"][r % len(cx["pattern"])]:
                depth = 1.0 + (1.0 - cx["euclid"]) * (depth - 1.0)
        return depth

    def _mod_couple_ctx(self, n_rows):
        """R32.10 engine coupling for modulation, cached for 0.25 s (called per instrument per row).

        SEEDED, EUCLIDEAN and LOCK compose instead of overwriting one another:
          SEEDED     w ← (1−Lₛ)·w + Lₛ·(2u−1),   u = seed_child64(seed, "modrow", op, row)/2⁶⁴
          LOCK       slot ← slot·(1 − c·L_lock)   (c = lock coupling) — every voice moves together
          EUCLIDEAN  off-pulse rows: d ← 1 + (1 − L_e)·(d − 1), pulses E(k, 16) with k = 3 + σ mod 6
          LOCK×FRACTAL  w ← (1−p)·w + p·F(row), F = the Fractal Seed L-system contour, p = c·L_lock·L_f
          RAND×GOAVA    phase += 2π·G(token, row) where G is GOAVA getNote of the frozen RAND token
        With none of these engines on every term is neutral and the curve is unchanged.
        """
        now = time.monotonic()
        c = getattr(self, "_mod_couple_cache", None)
        try:
            key = (int(n_rows), int(getattr(self, "_rand_instance_seed", 0) or 0), str(self._seed_text() if hasattr(self, "_seed_text") else ""))
        except Exception:
            key = (int(n_rows), 0, "")
        if c and c[0] == key and now - c[1] < 0.25:
            return c[2]
        try: active = set(self._active_engine_sources())
        except Exception: active = set()
        L = lambda k: float(self._canonical_level(k)) if k in active else 0.0
        try: seed = int(_safe_int_seed(self.get_numeric_seed() or 1))
        except Exception: seed = 1
        coupling = float(self._lock_characteristics().get("coupling", 0.62)) if hasattr(self, "_lock_characteristics") else 0.62
        ll, le, ls, lf, lr, lg = L("phase_lock"), L("euclidean"), L("seeded"), L("fractal_seed"), L("randomizer"), L("goava")
        pattern = []
        if le > 0.0:
            k = 3 + seed % 6
            rot = (seed >> 7) % 16
            pattern = [((((i + rot) % 16) * k) % 16) < k for i in range(16)]
        fractal = None
        fp = coupling * ll * lf
        if fp > 0.0:
            try:
                from groovebox_v3.fractal_seed_engine import rasterize_sequence
                plan = self._fractal_seed_event_plan()
                ras = rasterize_sequence(plan, max(1, int(n_rows)))
                fractal = [max(-1.0, min(1.0, (12.0 * math.log2(float(p)) / 12.0) if float(p) > 0 else -1.0)) for p in ras["pitches"]]
            except Exception:
                fractal = None
        gphase = 0.0
        if lr > 0.0 and lg > 0.0:
            try:
                tok = int(getattr(self, "_rand_instance_seed", 0) or 0)
                nums = list(self.get_seed_values(t_value=0.0) or []) or [MEUM]
                gphase = 2.0 * _SERIES_PI * lr * float(goava_get_note(float((tok & 0xFFFFFFFF) + 1), ((tok >> 11) & 0x1FFFFF) / float(0x1FFFFF) * MEUM, nums)) % (2.0 * _SERIES_PI)
            except Exception:
                gphase = 0.0
        ctx = {"seed": seed, "lock_pull": float(np.clip(coupling * ll, 0.0, 1.0)), "seeded": float(np.clip(0.5 * ls, 0.0, 1.0)),
               "euclid": le, "pattern": pattern, "fractal_pull": float(np.clip(fp, 0.0, 1.0)), "fractal": fractal,
               "goava_phase": gphase, "active": sorted(active)}
        self._mod_couple_cache = (key, now, ctx)
        return ctx

    def _effective_mod_state(self):
        user = getattr(self, "global_mod_state", {}) or {}
        canonical = self._canonical_mod_state()
        eff = {}
        for k in ("xmod", "input_xmod", "synth", "patch", "script", "domain"):
            u = float(user.get(k, 1.0))
            c = float(canonical.get(k, 1.0))
            share = self._canonical_field_share(f"mod:{k}")
            eff[k] = float(np.clip((1.0 - share) * u + share * c, 0.0, 2.0))
        return eff

    def _canonical_master_vector(self, slot=0):
        """Deterministic canonical XYZ direction derived from the live composition (per instance slot)."""
        try:
            seed = _safe_int_seed(self.get_numeric_seed())
        except Exception:
            seed = 0
        active = self._get_active_engine_set() if hasattr(self, "_get_active_engine_set") else set()
        mask = sum((i + 1) * self._canonical_level(name) for i, name in enumerate(("goava", "randomizer", "phase_lock", "seeded", "euclidean")) if name in active)
        phase = seed * 0.00017 + mask * PHI_INV + int(slot or 0) * MEUM_NORM * 5.0
        return (
            float(series_sin(phase)),
            float(series_cos(phase * MEUM)),
            float(series_sin(phase * PHI_INV + mask * 0.37)),
        )

    def _master_vector_effective(self):
        st = getattr(self, "master_vector_state", {}) or {}
        user = np.asarray([float(st.get(k, 0.0) or 0.0) for k in ("x", "y", "z")], dtype=np.float64)
        _slot = self._instance_slot(getattr(self, "_geo_editor_instrument", "") or "") if hasattr(self, "_instance_slot") else 0
        canonical = np.asarray(self._canonical_master_vector(_slot), dtype=np.float64)
        shares = np.asarray([0.5 if (abs(float(user[i])) > 1e-9 or f"master_vector:{k}" in (getattr(self, "_canonical_field_touched", None) or set())) else 1.0
                             for i, k in enumerate(("x", "y", "z"))], dtype=np.float64)
        effective = (1.0 - shares) * user + shares * canonical
        self.master_vector_canonical = tuple(float(v) for v in canonical)
        if hasattr(self, "master_vector_viz"):
            _eff, _can, _usr = np.array(effective, copy=True), np.array(canonical, copy=True), np.array(user, copy=True)
            self._gui_refresh("master_vector_viz", lambda: self.master_vector_viz.set_vectors(_eff, _can, _usr))
        return effective

    def _on_geometric_synth_mix_changed(self, key, value, label=None):
        """Set a named geometric synth trim; gains are linear and deterministic."""
        state = getattr(self, "geometric_synth_mixer_state", None)
        if not isinstance(state, dict):
            state = {"vector": .80, "wavetable": .75, "ball": .65, "cellular": .70, "cross_mod": .0024}
        state[str(key)] = float(np.clip(float(value) / 100.0, 0.0, 1.0))
        self.geometric_synth_mixer_state = state
        if label is not None:
            label.setText(f"{state[str(key)]:.2f}")
        self._on_live_source_changed()

    def _on_geometric_cross_mod_changed(self, value):
        """Shared, bounded cross-mod depth; no random source is involved."""
        amount = float(np.clip(float(value) / 10000.0, 0.0, 0.02))
        self.geometric_synth_mixer_state["cross_mod"] = amount
        if hasattr(self, "lbl_geometric_cross_mod"):
            self.lbl_geometric_cross_mod.setText(f"{amount:.4f}")
        self._on_live_source_changed()

    def _on_geometric_inharmonic_changed(self, value):
        """GROOVEBOX_INHARMONIC_GATE_20261102: off-harmonic partial/FM colour amount (0-100%, default 0)."""
        amount = float(np.clip(float(value) / 100.0, 0.0, 1.0))
        state = getattr(self, "geometric_synth_mixer_state", None)
        if not isinstance(state, dict):
            state = {"vector": .80, "wavetable": .75, "ball": .65, "cellular": .70, "cross_mod": .0024}
        state["inharmonic"] = amount
        self.geometric_synth_mixer_state = state
        if hasattr(self, "lbl_geometric_inharmonic"):
            self.lbl_geometric_inharmonic.setText(f"{int(round(amount * 100))}%")
        self._on_live_source_changed()

    def _on_geo_panel_mix_changed(self, value, name=None, announce=True):
        """Store the selected instrument's geometric-vs-panel balance (authored, canonical-visible)."""
        v = geo_panel_weight({"geo_panel_mix": float(value) / 100.0})
        try:
            self.lbl_geo_panel_mix.setText(f"{int(round((1.0 - v) * 100))} / {int(round(v * 100))}")
        except Exception:
            pass
        if getattr(self, "_geo_loading", False):
            return
        name = name or getattr(self, "_geo_editor_instrument", None)
        if not name and hasattr(self, "instrument_selector_dropdown"):
            name = self.instrument_selector_dropdown.currentText()
        if not name:
            return
        ps = getattr(self, "instrument_param_state", None)
        if ps is None:
            ps = self.instrument_param_state = {}
        ps.setdefault(name, {})["geo_panel_mix"] = v
        store = getattr(self, "_canonical_macro_user_store", None)
        if not isinstance(store, dict):
            store = self._canonical_macro_user_store = {}
        us = store.setdefault(name, {})
        if isinstance(us, dict):
            us["geo_panel_mix"] = v
        try:
            if self._panels_per_sequence_enabled():
                panels = self._sequence_panel_slot(name)
                if isinstance(panels, dict) and isinstance(panels.get("synth"), dict) and panels["synth"]:
                    panels["synth"]["geo_panel_mix"] = v
        except Exception:
            pass
        if announce:
            try:
                self._on_live_source_changed()
            except Exception:
                pass

    def _geo_panel_mix_refresh(self, name):
        sl = getattr(self, "slider_geo_panel_mix", None)
        if sl is None or not name:
            return
        v = geo_panel_weight((getattr(self, "instrument_param_state", {}) or {}).get(name))
        sl.blockSignals(True)
        sl.setValue(int(round(v * 100)))
        sl.blockSignals(False)
        try:
            self.lbl_geo_panel_mix.setText(f"{int(round((1.0 - v) * 100))} / {int(round(v * 100))}")
        except Exception:
            pass

    def _on_geometric_ensemble_mod_changed(self, value):
        """Persist the canonical bidirectional geometric↔ensemble modulation amount (0–50%)."""
        amount=float(np.clip(float(value)/100.0,0.0,0.5))
        state=getattr(self,"geometric_synth_mixer_state",None)
        if not isinstance(state,dict): state={"vector":.80,"wavetable":.75,"ball":.65,"cellular":.70,"cross_mod":.0024}
        state["ensemble_mod_amt"]=amount
        self.geometric_synth_mixer_state=state
        if hasattr(self,"lbl_geometric_ensemble_mod"): self.lbl_geometric_ensemble_mod.setText(f"{int(round(amount*100))}%")
        self._on_live_source_changed()

    def _geometric_mixer_snapshot(self):
        """Stable snapshot consumed by geometric synthesis and persisted in project canonicals."""
        defaults = {"vector": .80, "wavetable": .75, "ball": .65, "cellular": .70, "cross_mod": .0024, "ensemble_mod_amt": .12, "inharmonic": 0.0, "multidim": 1.0, "multidim_canon": 1.0}
        state = getattr(self, "geometric_synth_mixer_state", {}) or {}
        out={}
        for key,value in defaults.items():
            if key in ("multidim", "multidim_canon"):      # GROOVEBOX_R23R_MULTIDIM_SYNTH_20261103: 33 … 66 %
                out[key] = float(np.clip(float(state.get(key, value)), 0.0, 1.0))   # R32: 0 … 100 %
                continue
            hi=.02 if key=="cross_mod" else (.5 if key=="ensemble_mod_amt" else 1.0)
            out[key]=float(np.clip(float(state.get(key,value)),0.0,hi))
        return out

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_MULTIDIM_SYNTH_20261103 — the multidimensional synth in every voice
    # ------------------------------------------------------------------
    def _md_engines(self):
        try:
            return sorted(str(e) for e in (self._get_active_engine_set() or ()))
        except Exception:
            return []

    # ------------------------------------------------------------------
    # GROOVEBOX_MD_EXCHANGE_IO_20261104 — master synth ↔ geometric/panel exchange + 3 in / 3 out
    # ------------------------------------------------------------------
    MD_IO_SECTIONS = {
        "Synth": ("morph", "harmonic_freq", "chaos", "fold_depth", "harmonic_lattice", "fractalizer",
                  "eqr", "pkp_envelope", "tuning", "volume", "pitch"),
        "Vector": ("x", "y", "z", "drive"),
        "Wavetable": ("phase", "curvature", "twist", "fold"),
        "Ball": ("gravity", "gravity_angle_degrees", "radius", "vx", "vy"),
        "Cellular": ("width", "height", "cell_types", "generations", "rule"),
        "EQ": ("eq_gain_db", "eq_amount", "eq_tilt", "eq_q", "eq_frequency"),
        "Multidim": ("gravity", "restitution", "rot_hz", "lo", "hi", "up", "down", "phase_shift", "res_q", "res_mix"),
    }
    MD_IO_RANGES = {   # (section, param) → (min, max): inputs normalise by it, outputs move and clamp within it
        ("Synth", "morph"): (0.01, 10.0), ("Synth", "harmonic_freq"): (20.0, 20000.0), ("Synth", "chaos"): (0.0, 1.0),
        ("Synth", "fold_depth"): (1.0, 16.0), ("Synth", "harmonic_lattice"): (0.0, 1.0), ("Synth", "fractalizer"): (0.0, 1.0),
        ("Synth", "eqr"): (0.0, 1.0), ("Synth", "pkp_envelope"): (0.0, 1.0), ("Synth", "tuning"): (0.25, 4.0),
        ("Synth", "volume"): (0.0, 1.0), ("Synth", "pitch"): (0.5, 2.0),
        ("Vector", "x"): (-1.0, 1.0), ("Vector", "y"): (-1.0, 1.0), ("Vector", "z"): (-1.0, 1.0), ("Vector", "drive"): (0.0, 1.0),
        ("Wavetable", "phase"): (-0.5, 0.5), ("Wavetable", "curvature"): (0.0, 1.0), ("Wavetable", "twist"): (0.0, 1.0),
        ("Wavetable", "fold"): (0.0, 0.5),
        ("Ball", "gravity"): (-4.0, 4.0), ("Ball", "gravity_angle_degrees"): (-360.0, 360.0), ("Ball", "radius"): (0.05, 1.0),
        ("Ball", "vx"): (-4.0, 4.0), ("Ball", "vy"): (-4.0, 4.0),
        ("Cellular", "width"): (4.0, 64.0), ("Cellular", "height"): (4.0, 64.0), ("Cellular", "cell_types"): (2.0, 8.0),
        ("Cellular", "generations"): (1.0, 256.0), ("Cellular", "rule"): (0.0, 255.0),
        ("EQ", "eq_gain_db"): (-18.0, 18.0), ("EQ", "eq_amount"): (0.0, 1.0), ("EQ", "eq_tilt"): (-1.0, 1.0),
        ("EQ", "eq_q"): (0.1, 10.0), ("EQ", "eq_frequency"): (20.0, 20000.0),
        ("Multidim", "gravity"): (0.0, 40.0), ("Multidim", "restitution"): (0.0, 0.99), ("Multidim", "rot_hz"): (0.0, 1.0),
        ("Multidim", "lo"): (0.0, 1.0), ("Multidim", "hi"): (0.0, 1.0), ("Multidim", "up"): (0.5, 4.0),
        ("Multidim", "down"): (0.1, 2.0), ("Multidim", "phase_shift"): (0.0, 6.28), ("Multidim", "res_q"): (1.0, 200.0),
        ("Multidim", "res_mix"): (0.0, 1.0),
    }
    MD_EXCHANGE_KEYS = ("talk", "amount", "g2m", "m2g", "bi", "flux")
    _MD_EXCHANGE_NEUTRAL = {"talk": 0.5, "amount": 0.0, "g2m": 0.0, "m2g": 0.0, "bi": 0.0, "flux": 0.0}

    def _md_exchange_store(self):
        st = self.__dict__.get("md_exchange_state")
        if not isinstance(st, dict):
            st = self.md_exchange_state = dict(self._MD_EXCHANGE_NEUTRAL, touched=[])
        return st

    def _md_io_store(self):
        st = self.__dict__.get("md_io_state")
        if not isinstance(st, dict):
            mk = lambda: {"mode": "canonical", "inst": [], "section": "Synth", "param": "morph", "amount": 0.0}
            st = self.md_io_state = {"inputs": [mk() for _ in range(3)], "outputs": [mk() for _ in range(3)]}
        return st

    def _md_canonical_on(self):
        try:
            return bool(self._active_engine_sources())
        except Exception:
            return False

    def _md_exchange_effective(self):
        """Canonical (Meum) while engines are active and a value is untouched; 50/50 once you set it."""
        st = self._md_exchange_store()
        touched = set(st.get("touched") or ())
        on = self._md_canonical_on()
        u = lambda k: (k / MEUM) % 1.0
        canon = {"talk": 0.5, "amount": MEUM - 1.0, "g2m": u(1) - 0.5, "m2g": u(2) - 0.5,
                 "bi": u(3) - 0.5, "flux": MEUM - 1.0} if on else dict(self._MD_EXCHANGE_NEUTRAL)
        out = {}
        for k in self.MD_EXCHANGE_KEYS:
            if k in touched:
                out[k] = 0.5 * float(st.get(k, self._MD_EXCHANGE_NEUTRAL[k])) + 0.5 * canon[k] if on \
                    else float(st.get(k, self._MD_EXCHANGE_NEUTRAL[k]))
            else:
                out[k] = canon[k]
        return out

    def _md_param_value(self, name, section, param):
        st = (getattr(self, "instrument_param_state", {}) or {}).get(name) or {}
        lane = {"Vector": "vector", "Wavetable": "wavetable", "Ball": "ball", "Cellular": "cellular"}.get(section)
        if lane:
            v = ((st.get("geo") or {}).get(lane) or {}).get(param)
        elif section == "Multidim":
            v = (st.get("multidim") or {}).get(param)
        else:
            v = st.get(param)
        try:
            return float(v)
        except Exception:
            return None

    def _md_io_effective(self):
        """The six entries as applied: canonical routes picked on the Meum index, amounts normalised
        (amplified or dampened) so the active entries always sum to master synth volume / 2."""
        st = self._md_io_store()
        names = list(getattr(self, "instrument_names_48", []) or [])
        on = self._md_canonical_on()
        sections = list(self.MD_IO_SECTIONS)
        u = lambda k: (k / MEUM) % 1.0
        sel = ""
        try:
            sel = str(self.instrument_selector_dropdown.currentText())
        except Exception:
            pass
        rows = []
        for kind in ("inputs", "outputs"):
            for j, e in enumerate(st.get(kind) or []):
                mode = str(e.get("mode", "off"))
                if mode == "off" or not names:
                    continue
                if mode == "canonical":
                    if not on:
                        continue
                    k = j + (0 if kind == "inputs" else 3) + 1
                    insts = [names[int(u(k) * len(names)) % len(names)]]
                    s0 = int(u(k + 1) * len(sections)) % len(sections)
                    sec = par = None
                    for d in range(len(sections)):      # Meum-picked section, first one with live parameters
                        cand = sections[(s0 + d) % len(sections)]
                        present = [q for q in self.MD_IO_SECTIONS[cand]
                                   if self._md_param_value(insts[0], cand, q) is not None]
                        if present:
                            sec, par = cand, present[int(u(k + 2) * len(present)) % len(present)]
                            break
                    if sec is None:
                        continue
                    use = ("mix" if j % 2 == 0 else "sustain") if kind == "inputs" else "drive"
                    amt = 1.0
                else:
                    insts = [n for n in (e.get("inst") or []) if n in names] or ([sel] if sel in names else names[:1])
                    sec, par, use = str(e.get("section", "Synth")), str(e.get("param", "")), mode
                    amt = abs(float(e.get("amount", 0.0) or 0.0))
                rows.append({"kind": kind, "insts": insts, "section": sec, "param": par, "mode": use, "amount": amt})
        if not rows:
            return []
        target = 0.5 * float(self._md_mix())
        total = sum(r["amount"] for r in rows)
        for r in rows:
            r["amount"] = (target * r["amount"] / total) if total > 0 else target / len(rows)
        return rows

    def _md_io_inputs_for_lead(self):
        out = []
        for r in self._md_io_effective():
            if r["kind"] != "inputs":
                continue
            vals = [v for v in (self._md_param_value(n, r["section"], r["param"]) for n in r["insts"]) if v is not None]
            if not vals:
                continue
            v = sum(vals) / len(vals)          # a combination behaves exactly like one source: their mean
            lo, hi = self.MD_IO_RANGES.get((r["section"], r["param"]), (None, None))
            s = float(np.clip((v - lo) / (hi - lo), 0.0, 1.0)) if lo is not None and hi > lo \
                else 0.5 + 0.5 * v / (1.0 + abs(v))
            out.append((r["mode"], s, r["amount"]))
        return out

    def _md_io_apply_outputs(self, name, st):
        """Master-synth outputs drive their target parameters (EQ targets boost the band)."""
        try:
            rows = [r for r in self._md_io_effective() if r["kind"] == "outputs" and name in r["insts"]]
        except Exception:
            return st
        if not rows:
            return st
        st = copy.deepcopy(dict(st or {}))
        lanes = {"Vector": "vector", "Wavetable": "wavetable", "Ball": "ball", "Cellular": "cellular"}
        for r in rows:
            sec, par, a = r["section"], r["param"], r["amount"]
            holder = st
            if sec in lanes:
                holder = st.setdefault("geo", {}).setdefault(lanes[sec], {})
            elif sec == "Multidim":
                holder = st.setdefault("multidim", {})
            lo, hi = self.MD_IO_RANGES.get((sec, par), (None, None))
            try:
                v = float(holder[par]) if par in holder else (0.0 if sec == "EQ" else (0.5 * (lo + hi) if lo is not None else 0.0))
            except Exception:
                continue
            f = float(np.clip(1.0 + a, 0.0, 1.0 + MEUM))   # every modulation is a 0 … (1 + M)× factor
            if par == "eq_gain_db":
                nv = v + 20.0 * math.log10(max(f, 1e-3))     # EQ boost: the factor in dB (max ≈ +6.8 dB)
            else:
                nv = v * f
            holder[par] = float(np.clip(nv, lo, hi)) if lo is not None and hi > lo else nv
        return st

    def _md_mix(self):
        """Share of the multidimensional synth in every voice (33 … 66 %). Untouched by the user,
        the canonicals lean on it more the more engines are active (they work through it)."""
        st = getattr(self, "geometric_synth_mixer_state", {}) or {}
        try:
            if bool(st.get("multidim_user", False)):
                return float(np.clip(float(st.get("multidim", 1.0)), 0.0, 1.0))
            # GROOVEBOX_R32_CANONICAL_100_20261109: default 100 % (was 50 % + 3 % per engine, capped at 66 %).
            return float(np.clip(float(st.get("multidim", 1.0)), 0.0, 1.0))
        except Exception:
            return 1.0

    def _md_convolution(self):
        """(density, convolve) — the same convolution scheme the geometric defaults use: density from the
        instrument count (_eq_convolution_default_band_count / 128), amount from Global Convolve."""
        names = list(getattr(self, "instrument_names_48", []) or [])
        states = getattr(self, "instrument_param_state", {}) or {}
        count = max(len(names), len(states) if isinstance(states, dict) else 0, 2)
        try:
            d = float(_eq_convolution_default_band_count(int(count)))
        except Exception:
            d = 64.0
        try:
            c = (float(self.spin_global_convolve.value()) / 100.0) if hasattr(self, "spin_global_convolve") else 0.0
        except Exception:
            c = 0.0
        return max(0.0, min(1.0, d / 128.0)), max(0.0, min(1.0, c))

    def _md_canon_share(self):
        st = getattr(self, "geometric_synth_mixer_state", {}) or {}
        try:
            return float(np.clip(float(st.get("multidim_canon", 1.0)), 0.0, 1.0))
        except Exception:
            return 1.0

    def _md_params(self, name, slot):
        import multidim_synth as _md
        try:
            seed_int = int(_safe_int_seed(self.get_numeric_seed()))
        except Exception:
            seed_int = 0
        engines = self._md_engines()
        canon = _md.canonical_params(seed_int, int(slot), engines, *self._md_convolution())
        user = ((getattr(self, "instrument_param_state", {}) or {}).get(name, {}) or {}).get("multidim")
        params = _md.merge_params(canon, user if isinstance(user, dict) else None,
                                  canonical_active=bool(engines), canon_share=self._md_canon_share())
        # Snapshot the canonical-moderated global XMOD controls into the render
        # packet. DSP workers never read host widgets or mutable main-window state.
        try:
            params["global_mod_state"] = dict(self._effective_mod_state())
        except Exception:
            params["global_mod_state"] = {k: 1.0 for k in
                                           ("xmod", "input_xmod", "synth", "patch", "script", "domain")}
        return params, seed_int

    def _md_triad(self, main, geo, gpw, name, slot, phase, t, sr, step=None):
        """GROOVEBOX_R23R_MULTIDIM_SYNTH_20261103: the voice = (panel × geometrics) against the
        multidimensional synth, with every modulation pathway between them (multidim_synth.triad)."""
        import multidim_synth as _md
        main = np.asarray(main)
        if main.size == 0:
            return main
        w = self._md_mix()
        p, seed_int = self._md_params(name, slot)
        p = dict(p); p["xmod_net_max"] = float(getattr(self, "md_net_mod_max", 0.5))   # MD_NET_MOD_R31
        # MD_STOCH_R31: canonical activation level for the stochastic decisions, and the Morph Bridge mix of
        # the internal default probability (used only when no canonical is active).
        try:
            _eng = list(self._md_engines() or [])
            p["stoch_canon_level"] = max([self._canonical_level_raw(e) for e in _eng] or [0.0])
            p["stoch_canon_active"] = bool(_eng)
        except Exception:
            p["stoch_canon_level"] = 0.0
            p["stoch_canon_active"] = False
        p["stoch_default_mix"] = float(getattr(self, "md_stoch_default_mix", 1.0))
        try:
            ex = self._md_exchange_effective()
            lead_in = self._md_io_inputs_for_lead()
            if lead_in or ex.get("amount"):
                p = dict(p)
                p["exchange"] = ex
                p["lead_inputs"] = lead_in
        except Exception:
            pass
        try:
            base = float(getattr(self, "global_base_frequency_hz", 0.0) or 0.0) or (
                float(self.spin_base_frequency.value()) if hasattr(self, "spin_base_frequency") else 432.0)
        except Exception:
            base = 432.0
        md_out = _md.voice(phase, sr, p, t, base_hz=base, seed_int=seed_int, slot=int(slot), main=main,
                           pool=getattr(self, "_scode_optimizer", None), step=step)   # sCode-pooled scratch
        if md_out.size != main.size:
            return (1.0 - gpw) * main + gpw * geo if geo is not None else main
        return _md.triad(main, geo, gpw, w, md_out, p, sr)

    def _md_blend(self, inner, name, slot, phase, t, sr):
        """Compatibility: inner already mixed (no separate main / geometric parts)."""
        return self._md_triad(inner, None, 0.0, name, slot, phase, t, sr)

    def _on_master_vector_axis(self, key, value):
        st = getattr(self, "master_vector_state", {})
        st[key] = float(np.clip(float(value) / 100.0, -1.0, 1.0))
        self.master_vector_state = st
        if hasattr(self, "_canonical_field_touched"):
            self._canonical_field_touched.add(f"master_vector:{key}")
        if key in getattr(self, "master_vector_sliders", {}):
            self.master_vector_sliders[key][1].setText(f"{st[key]:+.2f}")
        self._master_vector_effective()
        self._on_live_source_changed()

    def _on_master_vector_drive(self, value):
        self.master_vector_state["drive"] = float(np.clip(float(value) / 100.0, 0.0, 1.0))
        if hasattr(self, "lbl_master_vector_mix"):
            self.lbl_master_vector_mix.setText(f"50% U / 50% C · {int(value)}%")
        self._master_vector_effective()
        self._on_live_source_changed()

    def _on_master_vector_toggle(self, checked):
        self.master_vector_state["enabled"] = bool(checked)
        if hasattr(self, "btn_master_vector_convert"):
            self.btn_master_vector_convert.setText("VECTOR CONVERT · ON" if checked else "VECTOR CONVERT · OFF")
        self._on_live_source_changed()

    def _on_master_vector_guard(self, checked):
        self.master_vector_state["guard"] = bool(checked)
        self._on_live_source_changed()

    def _on_vector_pad(self, x, y, z):
        """Vector pad drag/wheel -> the instance's X/Y/Z (centre = hand back to canonical)."""
        if abs(x) < 1e-9 and abs(y) < 1e-9 and abs(z) < 1e-9:
            self._reset_user_vector_direction()
            return
        for key, val in (("x", x), ("y", y), ("z", z)):
            pair = (getattr(self, "master_vector_sliders", {}) or {}).get(key)
            iv = int(round(float(np.clip(val, -1.0, 1.0)) * 100))
            if pair is not None and pair[0].value() != iv:
                pair[0].setValue(iv)  # -> _on_master_vector_axis (ownership + re-render)

    def _on_wavetable_drawn(self, table):
        """A drawn cycle becomes the selected instrument's wavetable (None = canonical)."""
        st = self.wavetable_projector_state
        self.__dict__.setdefault("_geo_editor_owned_edits", set()).add("drawn")
        if table is None:
            st.pop("drawn", None)
        else:
            st["drawn"] = [round(float(v), 6) for v in np.asarray(table, dtype=np.float32).ravel()]
        self._update_wavetable_projector()
        self._on_live_source_changed()

    def _reset_geo_lane(self, lane):
        """Reset one geometric synth of the selected instrument to defaults (canonical-owned)."""
        self.__dict__.setdefault("_geo_editor_owned_edits", set()).update(
            ("ball_lock",) if lane == "ball" else ("ca_lock", "manual_cells"))
        fac = self._geometric_convolution_defaults()  # R23R convolution preset
        if lane == "ball":
            self.ball_synth_params.update(copy.deepcopy(fac["ball"]))
            self.ball_synth_params.pop("x", None); self.ball_synth_params.pop("y", None)
            self.ball_manual_activity_locked = False
            prefix = "ball:"
            if hasattr(self, "lbl_ball_synth_state"): self.lbl_ball_synth_state.setText("BALL RESET · CANONICAL")
        else:
            self.cellular_synth_params.update(copy.deepcopy(fac["cellular"]))
            self.cellular_synth_params.pop("manual_cells", None)
            self.ca_single_cell_activity_locked = False
            prefix = "cellular:"
            if hasattr(self, "lbl_cellular_synth_state"): self.lbl_cellular_synth_state.setText("CELLULAR RESET · CANONICAL")
        self._canonical_field_touched = set(t for t in (getattr(self, "_canonical_field_touched", None) or set())
                                            if not str(t).startswith(prefix))
        self._geo_loading = True
        try:
            self._geo_refresh_widgets()
        finally:
            self._geo_loading = False
        self._on_live_source_changed()

    def _set_recommended_vector_settings(self):
        """Apply the recommended non-destructive Master Vector starting point."""
        self.master_vector_state.update({"drive": 0.50, "enabled": True, "guard": True})
        if hasattr(self, "slider_master_vector_drive"): self.slider_master_vector_drive.setValue(50)
        if hasattr(self, "btn_master_vector_convert"):
            self.btn_master_vector_convert.setChecked(True)
            self.btn_master_vector_convert.setText("VECTOR CONVERT · ON")
        if hasattr(self, "chk_master_vector_guard"): self.chk_master_vector_guard.setChecked(True)
        self._master_vector_effective(); self._on_live_source_changed()

    def _reset_user_vector_direction(self):
        """Neutralize user XYZ direction and hand it back to canonical (100%) --
        an explicit reset is 'un-adjusting' the field, not a 50% adjustment."""
        self.master_vector_state.update({"x": 0.0, "y": 0.0, "z": 0.0})
        for key in ("x", "y", "z"):
            if key in getattr(self, "master_vector_sliders", {}):
                sl, lab = self.master_vector_sliders[key]; sl.setValue(0); lab.setText("0.00")
            if hasattr(self, "_canonical_field_touched"):
                self._canonical_field_touched.discard(f"master_vector:{key}")
        self._master_vector_effective(); self._on_live_source_changed()

    def _update_signal_monitor(self, master):
        """Update post-vector signal health without changing the signal."""
        try:
            arr = np.asarray(master, dtype=np.float64).ravel()
            safe = np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0)
            finite = bool(np.isfinite(arr).all()) if arr.size else True
            rms = float(np.sqrt(np.mean(np.square(safe)))) if safe.size else 0.0
            peak = float(np.max(np.abs(safe))) if safe.size else 0.0
            nonzero = bool(np.any(safe != 0.0)) if safe.size else False
            headroom_db = 120.0 if peak == 0.0 else float(max(-120.0, -20.0 * math.log10(peak)))
            self.signal_monitor_state = {"rms": rms, "peak": peak, "headroom_db": headroom_db, "finite": finite, "nonzero": nonzero}
            def _apply_labels():
                stt = getattr(self, "signal_monitor_state", {}) or {}
                r, pk, hd = stt.get("rms", 0.0), stt.get("peak", 0.0), stt.get("headroom_db", 120.0)
                fin, nz = stt.get("finite", True), stt.get("nonzero", False)
                if hasattr(self, "lbl_signal_rms"): self.lbl_signal_rms.setText(f"RMS {r:.4f}  |  PEAK {pk:.4f}")
                if hasattr(self, "lbl_signal_headroom"): self.lbl_signal_headroom.setText(f"HEADROOM {hd:.1f} dB  |  FINITE {'YES' if fin else 'NO'}")
                if hasattr(self, "lbl_signal_conversion"):
                    if not fin: txt, style = "CONVERSION  CHECK · NON-FINITE INPUT", "color:#ff7070; font-weight:900; font-size:8pt;"
                    elif not nz: txt, style = "CONVERSION  READY · SILENT INPUT", "color:#e6c15a; font-weight:900; font-size:8pt;"
                    else: txt, style = "CONVERSION  READY · SIGNAL PRESENT", "color:#7fd9a0; font-weight:900; font-size:8pt;"
                    self.lbl_signal_conversion.setText(txt); self.lbl_signal_conversion.setStyleSheet(style)
            # Called from the render worker: widgets only change on the GUI thread.
            self._gui_refresh("signal_monitor", _apply_labels)
        except Exception: pass

    def _apply_master_vector_conversion(self, master):
        """Bounded resonant conversion with 50/50 user/canonical direction."""
        arr = np.asarray(master, dtype=np.float32)
        if arr.size == 0:
            return arr
        st = getattr(self, "master_vector_state", {}) or {}
        if not bool(st.get("enabled", True)):
            return arr
        try:
            v = self._master_vector_effective()
            drive = float(np.clip(st.get("drive", 0.5), 0.0, 1.0))
            norm = float(np.linalg.norm(v))
            if norm == 0.0:
                return arr
            vn = v / norm
            # XYZ -> deterministic phase/ring coefficients. The transform is
            # intentionally small and bounded so it improves conversion without
            # replacing the canonical waveform identity.
            idx = np.arange(arr.size, dtype=np.float64)
            phase = idx / max(1.0, float(arr.size)) * math.tau
            wt, _wtc = self._effective_wavetable_field() if hasattr(self, "wavetable_projector_state") else (np.array([0.5,0.5,0.5]), np.array([0.5,0.5,0.5]))
            wt = (wt - 0.5) * 2.0
            resonant = (0.55 * vn[0] * ot_sin_vec_equiv(phase) +
                        0.30 * vn[1] * ot_sin_vec_equiv(phase * MEUM) +
                        0.15 * vn[2] * ot_cos_vec_equiv(phase * PHI_INV))
            resonant += 0.08 * (wt[0] * ot_sin_vec_equiv(phase * MEUM) + wt[1] * ot_cos_vec_equiv(phase * PHI_INV) + wt[2] * ot_sin_vec_equiv(phase * PHI))
            out = arr.astype(np.float64) * (1.0 + 0.18 * drive * resonant)
            out = np.nan_to_num(out, nan=0.0, posinf=0.0, neginf=0.0)
            if bool(st.get("guard", True)):
                # Never erase a genuinely nonzero signal merely because the
                # vector field is active; preserve its sign and finite support.
                nz = arr != 0.0
                out[nz & (out == 0.0)] = arr[nz & (out == 0.0)]
            return out.astype(np.float32)
        except Exception:
            return arr

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_CONNECTOR_OVERLAY_20261031 — signal-flow styling.
    # ------------------------------------------------------------------
    SCOPE_COLORS = {"GLOBAL": ("#e05252", "#ff9a9a"), "LOCAL": ("#3bd18a", "#9ff5c8")}
    _SCOPE_GLOBAL = ("PROJECT NOTES", "GLOBAL · EFFECTS", "GLOBAL · COMPOSITION", "GLOBAL · XMOD", "LIVE DJ",
                     "SIGNAL CONVERSION", "MEUM SPATIAL", "CANONICAL MORPH BRIDGE", "GLOBAL PLAY PATCHER",
                     "MASTER GLOBAL EQ", "GEOMETRIC ENGINE MIXER", "MEDIA · CARRIER")
    PANEL_TINTS = {
        "GLOBAL PLAY PATCHER": ("#1b2430", "#141b24"),
        "MASTER GLOBAL EQ": ("#1d2329", "#15191e"),
        "GEOMETRIC ENGINE MIXER": ("#2a2414", "#1a1710"),
        "VECTOR SYNTH": ("#14262a", "#10191c"),
        "WAVETABLE SYNTH": ("#16242e", "#10181f"),
        "BOUNCING BALL": ("#1a2a1e", "#111b14"),
        "CELLULAR AUTOMATA": ("#22192c", "#17111e"),
    }
    _SCOPE_LOCAL = ("USER CONTEXT", "SYNTH / WINDOW TOOLS", "VECTOR SYNTH", "WAVETABLE SYNTH", "BOUNCING BALL",
                    "CELLULAR AUTOMATA")

    def _apply_scope_outlines(self):
        """GROOVEBOX_R23R_SCOPE_COLORS_20261031: red = GLOBAL (whole project),
        green = LOCAL (the selected instrument), blue = the instrument selector."""
        base = self.__dict__.setdefault("_scope_base_styles", {})
        seqbase = self.__dict__.setdefault("_per_seq_base_styles", {})
        for gb in self.findChildren(QGroupBox):
            try:
                if gb.window() is not self:
                    continue
                title = gb.title()
                bare = title.replace("GLOBAL ▸ ", "").replace("LOCAL ▸ ", "")
                up = bare.upper()
                scope = "LOCAL" if any(k in up for k in self._SCOPE_LOCAL) else ("GLOBAL" if any(k in up for k in self._SCOPE_GLOBAL) else None)
                if scope is None:
                    continue
                if id(gb) not in base:
                    base[id(gb)] = gb.styleSheet()
                edge, text = self.SCOPE_COLORS[scope]
                tint = ""
                for _key, (_c0, _c1) in self.PANEL_TINTS.items():
                    if _key in up:
                        # GROOVEBOX_R23R_PANEL_TINTS_20261101: slightly lifted, hued background.
                        tint = (f" QGroupBox {{ background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 {_c0}, stop:1 {_c1}); }}"
                                f" QGroupBox::title {{ background-color:{_c0}; }}")
                        break
                style = base[id(gb)] + tint + (f" QGroupBox {{ border:2px solid {edge}; }}"
                                               f" QGroupBox::title {{ color:{text}; }}")
                gb.setStyleSheet(style)
                gb.setProperty("grooveboxScope", scope)
                if not up.startswith(scope):
                    label = bare + (" · operator sample = LOCAL" if "MEDIA · CARRIER" in up and "LOCAL" not in up else "")
                    gb.setTitle(f"{scope} ▸ {label}")
                if id(gb) in seqbase:
                    seqbase[id(gb)] = style
                gb.setToolTip(((gb.toolTip() + "\n") if gb.toolTip() else "") +
                              ("GLOBAL (red): applies to the whole project." if scope == "GLOBAL"
                               else "LOCAL (green): applies to the selected instrument (blue selector at the top)."))
            except Exception:
                pass

    def _install_connector_overlay(self):
        if getattr(self, "_connector_overlay", None) is not None:
            return self._connector_overlay
        self._connector_overlay = _ConnectorOverlay(self)
        self._connector_overlay.setGeometry(self.rect())
        self._connector_overlay.show()
        self._refresh_connector_links()
        return self._connector_overlay

    def _geo_groups(self):
        return [getattr(self, a, None) for a in ("master_vector_group", "wavetable_projector_group",
                                                 "ball_synth_group", "cellular_synth_group")]

    def _refresh_connector_links(self):
        """Per Seq: button -> 4 panel editors + 4 geometric synths in the sequence colour;
        always: Geometric Engine Mixer -> the 4 geometric synth instances (dim gold)."""
        ov = getattr(self, "_connector_overlay", None)
        links = []
        geo = [g for g in self._geo_groups() if g is not None]
        mixer = getattr(self, "geometric_engine_mixer_group", None)
        if mixer is not None and geo:
            links.append((mixer, geo, "#d4af37", "", 0.2, {"mid": "blend weights"}))
        trig = getattr(self, "btn_trigger_note", None)
        if trig is not None and geo:
            try:
                _tc = frequency_color(self.trigger_note_freq.hz())[0].name()
            except Exception:
                _tc = "#3bd18a"
            # The four geometric instances feed the Trigger Note sound.
            for _gi, _g in enumerate(geo):
                links.append((_g, [trig], _tc, "", 0.45, {"mid": "feeds Trigger Note"} if _gi == 0 else {}))
        try:
            per_seq = self._panels_per_sequence_enabled()
        except Exception:
            per_seq = False
        if per_seq:
            name = self._current_instrument_name() if hasattr(self, "_current_instrument_name") else ""
            n = self._current_sequence_index(name)
            col = sequence_color(n)
            btns = [getattr(self, a, None) for a in ("btn_edit_synth", "btn_script_inst", "btn_view_patchbay", "btn_domain_eq")]
            links.append((getattr(self, "btn_edit_panels_per_sequence", None), [b for b in btns if b is not None] + geo,
                          col, f"SEQ #{n}", 0.9))
        if self._workflow_arrows_enabled():
            links += self._workflow_links(geo, mixer)
        if ov is not None:
            ov.links = links
            ov.update()
        self._refresh_per_seq_styling()

    # GROOVEBOX_R23R_FLOW_ARROWS_20261101 ----------------------------------
    WORKFLOW_STEPS = (
        ("instrument_selector_dropdown", "① pick instrument", "#5aa9ff"),
        ("btn_edit_synth", "② shape its synth", "#3bd18a"),
        ("master_vector_group", "③ geometric synths", "#3bd18a"),
        ("geometric_engine_mixer_group", "④ blend engines", "#d4af37"),
        ("global_player_group", "⑤ global patch", "#e05252"),
        ("btn_play", "⑥ play", "#f1ce68"),
        ("btn_export", "⑦ export / .MCC", "#c58cff"),
    )

    def _workflow_arrows_enabled(self) -> bool:
        v = getattr(self, "_workflow_arrows_on", None)
        if v is None:
            try:
                from PyQt6.QtCore import QSettings
                v = str(QSettings("MathematiciansGroovebox", "UI").value("workflow_arrows", "1")) not in ("0", "false", "False")
            except Exception:
                v = True
            self._workflow_arrows_on = v
        return bool(v)

    def _set_workflow_arrows(self, on: bool):
        self._workflow_arrows_on = bool(on)
        try:
            from PyQt6.QtCore import QSettings
            QSettings("MathematiciansGroovebox", "UI").setValue("workflow_arrows", "1" if on else "0")
        except Exception:
            pass
        try:
            self._refresh_connector_links()
        except Exception:
            pass

    def _workflow_links(self, geo, mixer):
        """Numbered, labelled workflow order: each visible step points to the next visible one."""
        steps = []
        for attr, text, colour in self.WORKFLOW_STEPS:
            w = getattr(self, attr, None)
            if w is not None:
                steps.append((w, text, colour))
        links = []
        for i, (w, text, colour) in enumerate(steps):
            nxt = [steps[i + 1][0]] if i + 1 < len(steps) else []
            links.append((w, nxt, colour, "", 0.42, {"step": text, "arrow": True, "dot": True, "from": "bottom"}))
        # ③ fans out to all four geometric synths.
        if geo and len(geo) > 1:
            links.append((geo[0], geo[1:], "#3bd18a", "", 0.3, {"dot": True, "horizontal": True, "from": "right", "to": "left"}))
        return links

    def _refresh_per_seq_styling(self):
        """Colour-code everything Edit Synth Per Seq writes with the active sequence's colour.

        Every editor window and geometric panel always states whether it edits
        the MAIN synth setting or SEQ #n's per-sequence setting (and where it is stored).
        """
        try:
            self._geo_loading = True
            self._geo_refresh_widgets()
        except Exception:
            pass
        finally:
            self._geo_loading = False
        try:
            per_seq = self._panels_per_sequence_enabled()
        except Exception:
            per_seq = False
        name = self._current_instrument_name() if hasattr(self, "_current_instrument_name") else ""
        n = self._current_sequence_index(name) if per_seq else 0
        col = sequence_color(n) if per_seq else None
        btn = getattr(self, "btn_edit_panels_per_sequence", None)
        if btn is not None:
            base = self.__dict__.setdefault("_per_seq_btn_base_style", btn.styleSheet())
            if per_seq:
                btn.setText(f"Edit Synth\nPer Seq\nSEQ #{n}")
                btn.setStyleSheet(base + f"QPushButton {{ border:3px solid {col}; color:{col}; background:#151820; font-weight:900; }}")
            else:
                btn.setText("Edit Synth\nPer Seq\nOFF")
                btn.setStyleSheet(base)
        styles = self.__dict__.setdefault("_per_seq_base_styles", {})
        for b in [getattr(self, a, None) for a in ("btn_edit_synth", "btn_script_inst", "btn_view_patchbay", "btn_domain_eq")] + self._geo_groups():
            if b is None:
                continue
            key = id(b)
            if key not in styles:
                styles[key] = b.styleSheet()
            if per_seq:
                sel = "QGroupBox" if isinstance(b, QGroupBox) else "QPushButton"
                b.setStyleSheet(styles[key] + f" {sel} {{ border:2px solid {col}; }}")
            else:
                b.setStyleSheet(styles[key])
        disp = str((getattr(self, "instrument_display_names", {}) or {}).get(name) or name)
        for attr in ("synth_editor_window", "script_editor_window", "patch_bay_dialog", "_domain_eq_dialog_ref"):
            win = getattr(self, attr, None)
            if win is None:
                continue
            try:
                banner = win.findChild(QLabel, "seqBanner")
                if banner is None and win.layout() is not None:
                    banner = QLabel(""); banner.setObjectName("seqBanner")
                    banner.setAlignment(Qt.AlignmentFlag.AlignCenter)
                    win.layout().insertWidget(0, banner)
                if banner is not None:
                    if per_seq:
                        banner.setText(f"PER-SEQ SYNTH SETTING · {disp} · stored in SEQUENCE #{n} · "
                                       f"blends 50/50 with the main synth (Automation Morph moves it)")
                        banner.setStyleSheet(f"background:{col}; color:#0b0d12; font-weight:900; padding:4px; border-radius:4px;")
                    else:
                        banner.setText(f"MAIN SYNTH SETTING · {disp} · stored in the instrument's master panel "
                                       f"(turn on Edit Synth Per Seq to edit a sequence's own setting)")
                        banner.setStyleSheet("background:#2b3446; color:#e8eefc; font-weight:900; padding:4px; border-radius:4px;")
                    banner.show()
                t = win.windowTitle().split(" · SEQ #")[0].split(" · MAIN")[0]
                win.setWindowTitle(f"{t} · SEQ #{n}" if per_seq else f"{t} · MAIN")
            except Exception:
                pass

    def _panels_per_sequence_enabled(self):
        btn = getattr(self, "btn_edit_panels_per_sequence", None)
        return bool(btn is not None and btn.isChecked())

    def _on_edit_panels_per_sequence_toggled(self, checked):
        """Switch live panel editors between master and sequence-local storage."""
        try:
            self.btn_edit_panels_per_sequence.setText("Edit Synth\nPer Seq\nON" if checked else "Edit Synth\nPer Seq\nOFF")
            name = self._current_instrument_name()
            if checked:
                # Leaving master mode: snapshot current live panels into the
                # active sequence so the first ON session is not empty.
                self._save_live_panels_to_sequence(name)
            else:
                # Returning to master: keep sequence overrides stored, but
                # restore master instrument-level state into the live editors.
                self._apply_master_panels_to_live(name)
            self._refresh_sequence_dependent_panels()
            self._refresh_connector_links()
            print(f"[Panels] Edit panels per sequence = {'ON' if checked else 'OFF'}")
        except Exception as exc:
            print(f"[Panels] toggle failed: {exc}")

    def _sequence_panel_slot(self, instrument_name=None, sequence_id=None):
        """Return (and create) the panels dict for one instrument sequence."""
        name = instrument_name or self._current_instrument_name()
        bank = (getattr(self, "instrument_sequence_banks", {}) or {}).setdefault(name, {})
        if sequence_id is None:
            sequence_id = self._current_sequence_index(name)
        mem = bank.setdefault(int(sequence_id), {})
        panels = mem.setdefault("panels", {})
        panels.setdefault("synth", {})
        panels.setdefault("script", "")
        panels.setdefault("domain", {})
        panels.setdefault("patch", [])
        return panels

    def _capture_live_panels(self, instrument_name=None):
        """Snapshot live master panel state for the given instrument."""
        name = instrument_name or self._current_instrument_name()
        synth = copy.deepcopy((getattr(self, "instrument_param_state", {}) or {}).get(name, {}) or {})
        script = str((getattr(self, "instrument_scripts", {}) or {}).get(name, "") or "")
        # Domain: store instrument-relevant domain tags / equations
        domain = {}
        engine = getattr(self, "domain_eq_engine", None)
        if engine is not None:
            relevant = []
            for dom in getattr(engine, "domains", []) or []:
                if not isinstance(dom, dict):
                    continue
                dname = str(dom.get("name", ""))
                if name[:8].lower() in dname.lower() or dname.startswith("Dom::"):
                    relevant.append(copy.deepcopy(dom))
            domain = {"domains": relevant}
        # Patch: incident edges for this operator
        patch = []
        for c in getattr(self, "patch_connections", []) or []:
            if not isinstance(c, dict):
                continue
            if c.get("source") == name or c.get("target") == name:
                patch.append(copy.deepcopy(c))
        return {"synth": synth, "script": script, "domain": domain, "patch": patch}

    def _save_live_panels_to_sequence(self, instrument_name=None, sequence_id=None):
        try:
            _gname = instrument_name or self._current_instrument_name()
            if _gname and _gname == getattr(self, "_geo_editor_instrument", None):
                self._geo_buffer_store(_gname)   # the instance travels with the synth panel
        except Exception:
            pass
        if not self._panels_per_sequence_enabled() and sequence_id is None:
            # Explicit saves from engine paths still allowed when forced via sequence_id
            pass
        name = instrument_name or self._current_instrument_name()
        panels = self._sequence_panel_slot(name, sequence_id)
        live = self._capture_live_panels(name)
        panels["synth"] = live["synth"]
        panels["script"] = live["script"]
        panels["domain"] = live["domain"]
        panels["patch"] = live["patch"]
        return panels

    def _apply_sequence_panels_to_live(self, instrument_name=None, sequence_id=None):
        """Apply panels, then reload the selected instrument's geometric instance from them."""
        result = self._apply_sequence_panels_to_live_inner(instrument_name, sequence_id)
        try:
            _gname = instrument_name or self._current_instrument_name()
            if _gname and _gname == getattr(self, "_geo_editor_instrument", None):
                self._geo_editor_instrument = None
                self._geo_buffer_load(_gname)
        except Exception as _gexc:
            print(f"[Geometry] panel swap reload: {_gexc}")
        return result

    def _apply_sequence_panels_to_live_inner(self, instrument_name=None, sequence_id=None):
        """Push sequence panel overrides into the live instrument stores / UI."""
        name = instrument_name or self._current_instrument_name()
        panels = self._sequence_panel_slot(name, sequence_id)
        # Synth params
        if not hasattr(self, "instrument_param_state") or self.instrument_param_state is None:
            self.instrument_param_state = {}
        if panels.get("synth"):
            self.instrument_param_state[name] = copy.deepcopy(panels["synth"])
        # Script
        if not hasattr(self, "instrument_scripts") or self.instrument_scripts is None:
            self.instrument_scripts = {}
        if panels.get("script") is not None:
            self.instrument_scripts[name] = str(panels.get("script") or "")
        # Domain: merge sequence-local domains under a namespaced marker
        engine = getattr(self, "domain_eq_engine", None)
        seq_domains = (panels.get("domain") or {}).get("domains") or []
        if engine is not None and seq_domains:
            kept = [d for d in (engine.domains or []) if not (
                isinstance(d, dict) and str(d.get("name", "")).startswith(f"seq::{name}::")
            )]
            for d in seq_domains:
                dd = copy.deepcopy(d)
                dd["name"] = f"seq::{name}::{dd.get('name', 'Dom')}"
                dd["sequence_local"] = True
                kept.append(dd)
            engine.domains = kept
        # Patch: replace only this instrument's non-user edges with sequence ones
        if not hasattr(self, "patch_connections") or self.patch_connections is None:
            self.patch_connections = []
        kept_cables = [
            c for c in self.patch_connections
            if not isinstance(c, dict) or (
                c.get("source") != name and c.get("target") != name
            ) or c.get("user_defined", True)
        ]
        for c in panels.get("patch") or []:
            if isinstance(c, dict):
                kept_cables.append(copy.deepcopy(c))
        self.patch_connections = kept_cables
        try:
            self._schedule_ui_after_canonical_write(f"sequence-panels:{name}")
        except Exception:
            pass

    def _apply_master_panels_to_live(self, instrument_name=None):
        """Apply panels, then reload the selected instrument's geometric instance from them."""
        result = self._apply_master_panels_to_live_inner(instrument_name)
        try:
            _gname = instrument_name or self._current_instrument_name()
            if _gname and _gname == getattr(self, "_geo_editor_instrument", None):
                self._geo_editor_instrument = None
                self._geo_buffer_load(_gname)
        except Exception as _gexc:
            print(f"[Geometry] panel swap reload: {_gexc}")
        return result

    def _apply_master_panels_to_live_inner(self, instrument_name=None):
        """No-op for data: master state is already in instrument_param_state etc.
        Sequence overrides remain stored in banks but are not injected."""
        name = instrument_name or self._current_instrument_name()
        # Strip sequence-local domain overlays when returning to master mode
        engine = getattr(self, "domain_eq_engine", None)
        if engine is not None:
            engine.domains = [
                d for d in (engine.domains or [])
                if not (isinstance(d, dict) and d.get("sequence_local"))
            ]

    def _engine_write_sequence_panels(self, source="randomizer", instrument_names=None):
        """Write engine panel addons per sequence; they mix into master at render."""
        names=list(instrument_names or getattr(self,"instrument_names_48",[]) or [])
        written=0
        for name in names:
            bank=(getattr(self,"instrument_sequence_banks",{}) or {}).setdefault(name,{})
            ids=sorted(int(k) for k in bank if str(k).isdigit()) or [1]
            for sid in ids:
                mem=bank.setdefault(sid,{})
                locked = self._sequence_is_user_locked(mem) if hasattr(self, "_sequence_is_user_locked") else bool(mem.get("user_owned"))
                panels=self._sequence_panel_slot(name,sid)
                panels.setdefault("blend", 0.5)
                ec=panels.setdefault("engine_contributions",{})
                if not isinstance(ec,dict): ec=panels["engine_contributions"]={}
                state = getattr(self, "instrument_param_state", {}) or {}
                raw_params = state.get(name, {}) if isinstance(state, dict) else {}

                params = dict(raw_params) if isinstance(raw_params, dict) else {}

                generated = getattr(
                    self, "instrument_param_generated", {}
                ) or {}

                raw_gen = generated.get(name, {}) if isinstance(generated, dict) else {}

                if isinstance(raw_gen, dict):
                    for k, v in raw_gen.items():
                        params.setdefault(k, v)
                gen=dict((getattr(self,"instrument_param_generated",{}) or {}).get(name,{}) or {})
                for k,v in gen.items(): params.setdefault(k,v)
                engine=getattr(self,"domain_eq_engine",None)
                domains=[copy.deepcopy(d) for d in (engine.domains or []) if isinstance(d,dict) and (name[:6].lower() in str(d.get("name","")).lower() or str(d.get("source",""))==source)][:4] if engine is not None else []
                patch=[copy.deepcopy(c) for c in (getattr(self,"patch_connections",[]) or []) if isinstance(c,dict) and (c.get("source")==name or c.get("target")==name)][:6]
                ec[str(source)]={"synth":copy.deepcopy(params),"script":str((getattr(self,"instrument_scripts",{}) or {}).get(name,"") or ""),"domain":{"domains":domains,"source":str(source)},"patch":patch}
                merged_synth={}; merged_script=""; merged_domains=[]; merged_patch=[]; sources=[]
                for src in sorted(ec):
                    cp=ec[src] or {}
                    if cp.get("synth"): merged_synth.update(copy.deepcopy(cp["synth"]))
                    if cp.get("script") and not merged_script: merged_script=str(cp["script"])
                    dom=cp.get("domain") or {}
                    for d in dom.get("domains",[]) if isinstance(dom,dict) else []:
                        if d not in merged_domains: merged_domains.append(copy.deepcopy(d))
                    for edge in cp.get("patch",[]) or []:
                        if edge not in merged_patch: merged_patch.append(copy.deepcopy(edge))
                    sources.append(src)
                # Always blend engine result-mod synth with the live master
                # (non-sequence) panel data so playlist-assigned patterns carry
                # both identities. Locked user sequences keep more of their own
                # prior panel synth (0.35 engine); free sequences take a stronger
                # engine contribution (0.55) still mixed with master defaults.
                master_live = {}
                try:
                    master_live = copy.deepcopy(
                        (getattr(self, "instrument_param_state", {}) or {}).get(name, {}) or {}
                    )
                except Exception:
                    master_live = {}
                if not isinstance(master_live, dict):
                    master_live = {}
                # Seed master with generated defaults so empty panels still have shape
                try:
                    gen = (getattr(self, "instrument_param_generated", {}) or {}).get(name, {}) or {}
                    if isinstance(gen, dict):
                        for _k, _v in gen.items():
                            master_live.setdefault(_k, _v)
                except Exception:
                    pass
                if locked and panels.get("synth"):
                    # User-locked: keep prior sequence panel, light engine + master
                    base = self._blend_param_dicts(panels.get("synth") or {}, master_live, 0.25) if hasattr(self, "_blend_param_dicts") else dict(panels.get("synth") or {})
                    merged_synth = self._blend_param_dicts(base, merged_synth, 0.35) if hasattr(self, "_blend_param_dicts") else {**base, **merged_synth}
                else:
                    # Free / engine-owned: master panel defaults × engine result mod
                    if master_live and hasattr(self, "_blend_param_dicts"):
                        merged_synth = self._blend_param_dicts(master_live, merged_synth, 0.55)
                    elif master_live:
                        merged_synth = {**master_live, **merged_synth}
                # Script / domain / patch: keep master defaults when engine left them empty
                if not merged_script:
                    merged_script = str((getattr(self, "instrument_scripts", {}) or {}).get(name, "") or "")
                if not merged_domains and master_live:
                    # leave domains as engine-provided list (may be empty)
                    pass
                if not merged_patch:
                    try:
                        merged_patch = [
                            copy.deepcopy(c) for c in (getattr(self, "patch_connections", []) or [])
                            if isinstance(c, dict) and (c.get("source") == name or c.get("target") == name)
                        ][:6]
                    except Exception:
                        pass
                panels.update({
                    "synth": merged_synth,
                    "script": merged_script if not (locked and panels.get("script")) else panels.get("script"),
                    "domain": {"domains": merged_domains[:8], "sources": sources},
                    "patch": merged_patch[:12],
                    "engine_source": "+".join(sources),
                    "blend": float(panels.get("blend", 0.5) or 0.5),
                    "master_blended": True,
                })
                written+=1
        return written

    def _on_sequence_envelope_changed(self, _value=0):
        """Store sequence-wide predictive attack/release on the selected sequence."""
        try:
            mem = self._current_sequence_mem()
            mem["sequence_envelope_attack"] = float(self.slider_sequence_attack.value()) / 100.0
            mem["sequence_envelope_release"] = float(self.slider_sequence_release.value()) / 100.0
            if hasattr(self, "lbl_sequence_attack"):
                self.lbl_sequence_attack.setText(f"{self.slider_sequence_attack.value()}%")
            if hasattr(self, "lbl_sequence_release"):
                self.lbl_sequence_release.setText(f"{self.slider_sequence_release.value()}%")
            self._canonical_write_sequence_runtime()
            self._on_live_source_changed()
        except Exception:
            pass

    def _load_sequence_envelope_controls(self, mem=None):
        mem = mem if isinstance(mem, dict) else self._current_sequence_mem()
        a = float(np.clip(float(mem.get("sequence_envelope_attack", 0.5) or 0.0), 0.0, 1.0))
        r = float(np.clip(float(mem.get("sequence_envelope_release", 0.5) or 0.0), 0.0, 1.0))
        if hasattr(self, "slider_sequence_attack"):
            self.slider_sequence_attack.blockSignals(True); self.slider_sequence_attack.setValue(int(round(a * 100))); self.slider_sequence_attack.blockSignals(False)
        if hasattr(self, "slider_sequence_release"):
            self.slider_sequence_release.blockSignals(True); self.slider_sequence_release.setValue(int(round(r * 100))); self.slider_sequence_release.blockSignals(False)
        if hasattr(self, "lbl_sequence_attack"): self.lbl_sequence_attack.setText(f"{int(round(a*100))}%")
        if hasattr(self, "lbl_sequence_release"): self.lbl_sequence_release.setText(f"{int(round(r*100))}%")

    def _sequence_envelope_factor(self, local_t, step_start, step_end, row_duration, mem):
        """Predictive attack before trigger + release through at most one playlist row."""
        row = float(row_duration)
        if row < 0.0:
            row = 0.0
        a_seq = float(np.clip(float(mem.get("sequence_envelope_attack", 0.5) or 0.0), 0.0, 1.0))
        r_seq = float(np.clip(float(mem.get("sequence_envelope_release", 0.5) or 0.0), 0.0, 1.0))
        # Existing instrument/pattern envelope fields contribute equally; missing
        # fields are the requested neutral/default-none envelope.
        p_attack = float(np.clip(float(mem.get("attack", mem.get("envelope_attack", 0.0)) or 0.0), 0.0, 1.0))
        p_release = float(np.clip(float(mem.get("decay", mem.get("envelope_decay", 0.0)) or 0.0), 0.0, 1.0))
        attack = min(row, row * 0.5 * (a_seq + p_attack))
        release = min(row, row * 0.5 * (r_seq + p_release))
        _n = int(local_t.size)
        if _n > 1:
            _key = (_n, float(local_t[0]), float(local_t[_n // 2]), float(local_t[-1]), float(np.sum(local_t)),
                    float(step_start), float(step_end), row, attack, release, bool(mem.get("automation_lane")))
            return _sc_memo("seq_envelope", _key, lambda: _readonly(self._sequence_envelope_raw(
                local_t, step_start, step_end, row, attack, release, mem)), 64)
        return self._sequence_envelope_raw(local_t, step_start, step_end, row, attack, release, mem)

    def _sequence_envelope_raw(self, local_t, step_start, step_end, row, attack, release, mem):
        out = np.ones_like(local_t, dtype=np.float32)
        if attack > 0.0:
            pre = (local_t >= step_start - attack) & (local_t < step_start)
            out[pre] = (local_t[pre] - (step_start - attack)) / attack
        if release > 0.0:
            post = (local_t >= step_end) & (local_t < step_end + release)
            out[post] = 1.0 - (local_t[post] - step_end) / release
        # Longitudinal fallback: with no painted automation, remain linear over one row.
        if not mem.get("automation_lane") and not (row > 0.0):
            # Only a zero-length row can differ from the neutral multiply (u*0.0 == 0, so 1-u*0 == 1 exactly,
            # except where u is NaN); keep the original expression for that case.
            u = np.clip((local_t - step_start) / row, 0.0, 1.0)
            out *= (1.0 - u * 0.0)
        return np.clip(out, 0.0, 1.0).astype(np.float32, copy=False)

    def _on_sequence_selector_changed(self, combo_index):
        if combo_index < 0 or not hasattr(self, "sequence_selector"):
            return
        name = self._current_instrument_name()
        # Persist outgoing sequence panels when per-sequence editing is active.
        prev_idx = self._current_sequence_index(name)
        if self._panels_per_sequence_enabled():
            try:
                self._save_live_panels_to_sequence(name, prev_idx)
            except Exception as _exc:
                print(f"[Panels] save on sequence switch: {_exc}")
        idx = int(self.sequence_selector.itemData(combo_index) or 1)
        bank = getattr(self, "instrument_sequence_banks", {}).setdefault(name, {})
        if idx not in bank:
            return
        self.instrument_selected_sequence[name] = idx
        self.instrument_sequencer_memory[name] = bank[idx]
        seq_len = int(bank[idx].get("pattern_length", DEFAULT_SEQUENCE_LENGTH))
        self.spin_seq_length.blockSignals(True)
        self.spin_seq_length.setValue(seq_len)
        self.spin_seq_length.blockSignals(False)
        self.spin_pattern_length.blockSignals(True)
        self.spin_pattern_length.setValue(seq_len)
        self.spin_pattern_length.blockSignals(False)
        self._load_sequence_envelope_controls(bank[idx])
        self._load_track_offset_control(bank[idx])
        self._load_sequence_playlist_mode_controls(bank[idx])
        if self._panels_per_sequence_enabled():
            try:
                self._apply_sequence_panels_to_live(name, idx)
            except Exception as _exc:
                print(f"[Panels] load on sequence switch: {_exc}")
        self._refresh_sequence_dependent_panels()

    def _on_canonical_control_strategy_changed(self, strategy):
        """Select the canonical authority policy; never lower the 50% floor."""
        strategy = str(strategy or "Full Canonical")
        if strategy not in getattr(self, "canonical_control_options", ()): 
            strategy = "Full Canonical"
        self.canonical_control_strategy = strategy
        self._update_canonical_signal_control()
        try:
            self._canonical_write_sequence_runtime()
        except Exception:
            pass

    def _canonical_coverage_score(self):
        """Measure canonical writable coverage without rewriting user data."""
        active = set(self._active_engine_sources()) if hasattr(self, "_active_engine_sources") else set()
        # The canonical substrate itself always counts as present; missing lanes are
        # opportunities to materialize canonical structures, not reasons to reduce authority.
        score = 0.50
        if active: score += 0.10 * min(len(active), 5)
        try:
            banks = getattr(self, "instrument_sequence_banks", {}) or {}
            seq_ok = any(isinstance(m, dict) and (m.get("steps") or m.get("automation_lane")) for b in banks.values() for m in (b or {}).values())
            auto_ok = bool(getattr(self, "sequencer_automation_points", []))
            mod_ok = any(isinstance((getattr(self, "instrument_param_state", {}) or {}).get(n, {}).get("meum_modulation"), dict) for n in getattr(self, "instrument_names_48", []) or [])
            if seq_ok: score += 0.05
            if auto_ok: score += 0.05
            if mod_ok: score += 0.05
        except Exception:
            pass
        return float(np.clip(score, 0.50, 1.00))

    def _canonical_missing_lanes(self):
        """Return canonical lanes that should be materialized rather than stealing user slots."""
        missing = []
        try:
            banks = getattr(self, "instrument_sequence_banks", {}) or {}
            if not any(isinstance(m, dict) and (m.get("steps") or m.get("automation_lane")) for b in banks.values() for m in (b or {}).values()):
                missing.append("sequence")
            if not getattr(self, "sequencer_automation_points", []): missing.append("automation")
            if not any(isinstance((getattr(self, "instrument_param_state", {}) or {}).get(n, {}).get("meum_modulation"), dict) for n in getattr(self, "instrument_names_48", []) or []):
                missing.extend(["AM", "FM", "PM"])
        except Exception:
            missing.extend(["sequence", "automation", "AM", "FM", "PM"])
        # Effect/global layer is canonical-capable even when its user controls are empty.
        if not isinstance(getattr(self, "global_algo_state", None), dict):
            missing.append("global_effect")
        return missing

    def _materialize_canonical_coverage(self, instrument_name=None, row_idx=0):
        """Create canonical-only structures without consuming or rewriting a user slot.

        Automation is mirrored into sequencer_automation_points + sequence
        automation_lane so the Automator strip and render path actually see data
        (overlays alone were invisible to the UI).
        """
        name = instrument_name or (getattr(self, "instrument_names_48", []) or ["Operator"])[0]
        try:
            name = str(name)
        except Exception:
            name = "Operator"
        overlays = getattr(self, "canonical_runtime_overlays", None)
        if not isinstance(overlays, dict):
            overlays = self.canonical_runtime_overlays = {}
        key = f"{name}:{int(row_idx)}"
        overlay = overlays.setdefault(key, {})
        try:
            auto_len = int(self.spin_auto_point_length.value()) if hasattr(self, "spin_auto_point_length") else 16
        except Exception:
            auto_len = 16
        auto_len = max(1, min(STRUCT_MAX_STEPS, int(auto_len) or 16))
        try:
            sid = int(self._current_sequence_index(name)) if hasattr(self, "_current_sequence_index") else 1
        except Exception:
            sid = 1
        overlay.setdefault("sequence", {
            "pattern_length": auto_len,
            "steps": [((i + int(row_idx)) % 2 == 0) for i in range(auto_len)],
            "amplitudes": [1.0] * auto_len, "pitches": [1.0] * auto_len,
            "offsets": [0.0] * auto_len, "canonical_owner": "canonical:coverage"
        })
        auto_vals = [{"step": i + 1, "value": 0.5 + 0.5 * series_sin((i + 1) * MEUM_NORM + int(row_idx) * 0.17)} for i in range(auto_len)]
        overlay.setdefault("automation", auto_vals)
        # CANONICAL_MODULATION_REMOVED_20261102: the fixed AM/FM/PM overlay defaults were never read by the render;
        # canonical modulation comes from the master Mod Depth (XMOD) path. effect_layer is kept.
        overlay.setdefault("effect_layer", {"source": "canonical_seed_default", "active": True})
        overlay["canonical_owner"] = True
        overlay["row_idx"] = int(row_idx)
        overlay["instrument"] = name

        # Push canonical automation into the live Automator surface when the
        # active instrument/sequence has no user-owned points yet.
        try:
            points = list(getattr(self, "sequencer_automation_points", []) or [])
            def _is_user_point(p):
                if not isinstance(p, dict):
                    return False
                owner = str(p.get("canonical_owner") or "")
                return owner.startswith("user:") or bool(p.get("user_owned"))

            scoped = [
                p for p in points
                if isinstance(p, dict)
                and str(p.get("from_instrument") or p.get("instrument") or "") == name
                and int(p.get("from_sequence", 1) or 1) == int(sid)
            ]
            has_user = any(_is_user_point(p) for p in scoped)
            if not has_user:
                # Drop prior canonical-only points for this scope, then rewrite.
                points = [
                    p for p in points
                    if not (
                        isinstance(p, dict)
                        and str(p.get("from_instrument") or p.get("instrument") or "") == name
                        and int(p.get("from_sequence", 1) or 1) == int(sid)
                        and not _is_user_point(p)
                    )
                ]
                for i, av in enumerate(overlay.get("automation") or auto_vals):
                    step = int(av.get("step", i + 1) if isinstance(av, dict) else (i + 1))
                    val = float(av.get("value", 0.5) if isinstance(av, dict) else 0.5)
                    if not math.isfinite(val):
                        val = 0.5
                    points.append({
                        "step": step,
                        "from_instrument": name,
                        "from_sequence": int(sid),
                        "to_instrument": name,
                        "to_sequence": int(sid),
                        "instrument": name,
                        "morph": float(np.clip(val, 0.0, 1.0)),
                        "step_offset": 0,
                        "playlist_row": int(row_idx) + 1,
                        "composition_blend": 0.5,
                        "canonical_owner": "canonical:coverage",
                        "length": auto_len,
                        "reference_offsets": {},
                        "enabled": True,
                        "synth_param": "morph",
                        "value": val,
                    })
                self.sequencer_automation_points = points
                if hasattr(self, "_canonical_write_sequencer_automation_state"):
                    self._canonical_write_sequencer_automation_state()
                if hasattr(self, "_refresh_sequencer_automation_row"):
                    self._gui_refresh("automation_row", self._refresh_sequencer_automation_row)

            # Per-sequence automation_lane (render path) when empty / non-user.
            mem = None
            try:
                banks = getattr(self, "instrument_sequence_banks", {}) or {}
                bank = banks.get(name, {}) if isinstance(banks, dict) else {}
                mem = bank.get(int(sid)) if isinstance(bank, dict) else None
                if mem is None and hasattr(self, "_current_sequence_mem"):
                    mem = self._current_sequence_mem(name)
            except Exception:
                mem = None
            if isinstance(mem, dict):
                lane = mem.get("automation_lane")
                lane_has_user = False
                if isinstance(lane, list):
                    for p in lane:
                        if isinstance(p, dict) and (
                            str(p.get("canonical_owner") or "").startswith("user:")
                            or bool(p.get("user_owned"))
                        ):
                            lane_has_user = True
                            break
                if not lane_has_user:
                    mem["automation_lane"] = [
                        {
                            "step": int(av.get("step", i + 1) if isinstance(av, dict) else (i + 1)),
                            "value": float(av.get("value", 0.5) if isinstance(av, dict) else 0.5),
                            "enabled": True,
                            "playlist_row": int(row_idx) + 1,
                            "instrument": name,
                            "from_instrument": name,
                            "from_sequence": int(sid),
                            "to_instrument": name,
                            "to_sequence": int(sid),
                            "morph": float(av.get("value", 0.5) if isinstance(av, dict) else 0.5),
                            "canonical_owner": "canonical:coverage",
                        }
                        for i, av in enumerate(overlay.get("automation") or auto_vals)
                    ]
                    mem["automation_lane_length"] = auto_len
        except Exception as _exc:
            print(f"[Canonical] automation materialize surface sync failed: {_exc}")
        return overlay

    def _update_canonical_signal_control(self, instrument_name=None, row_idx=0):
        """Compute authority from an explicit strategy plus available canonical coverage."""
        strategy = str(getattr(self, "canonical_control_strategy", "Full Canonical"))
        if strategy == "Full Canonical":
            strength = 1.00
        elif strategy == "Seeded Baseline":
            strength = 0.50
        elif strategy == "Engine Stack":
            active = len(self._active_engine_sources()) if hasattr(self, "_active_engine_sources") else 0
            strength = 0.50 + 0.10 * min(active, 5)
        else:
            strength = max(0.50, self._canonical_coverage_score())
        # Missing canonical lanes are filled in a canonical-owned structure. They never
        # reduce authority and never rewrite a user-owned program slot.
        if strategy != "Seeded Baseline" and self._canonical_missing_lanes():
            try:
                self._materialize_canonical_coverage(instrument_name, row_idx)
            except Exception:
                pass
            strength = max(0.50, float(strength))
        self.canonical_signal_control = float(strength) if 0.50 <= float(strength) <= 1.00 else 0.50
        def _label():
            self.lbl_canonical_signal_control.setText(f"CANONICAL SIGNAL CONTROL: {self.canonical_signal_control * 100:.0f}%")
        try:
            self._gui_refresh("canonical_signal_label", _label)
        except Exception:
            pass
        return self.canonical_signal_control

    def _user_data_overwrite_on(self):
        """True when Canonical protect is OFF — User Data Overwrite mode."""
        try:
            if hasattr(self, "_canonical_protect_user"):
                return not bool(self._canonical_protect_user())
        except Exception:
            pass
        chk = getattr(self, "chk_canonical_protect", None)
        if chk is not None:
            try:
                return not bool(chk.isChecked())
            except Exception:
                pass
        return False

    def _canonical_resonance_range(self):
        """Return (lo, hi) as fractions of 1.0 for the active resonance band.

        Protect ON (default): 50–150% — safe activity/continuation band that
        respects the user carrier and the 50/50 source coefficients.

        User Data Overwrite ON (protect OFF): 0–200% — full overwrite band so
        canonical activity can go silent (0%) or drive up to 200% when userdata
        locks are wiped and engines may rewrite the composition.
        """
        if self._user_data_overwrite_on():
            return (0.0, 2.0)
        return (0.50, 1.50)

    def _canonical_resonance_tooltip(self):
        if self._user_data_overwrite_on():
            return (
                "Canonical Resonance / Activity — User Data Overwrite ON\n"
                "Range: 0–200%.\n"
                "0% = no autonomous canonical activity; 200% = maximum continuation drive\n"
                "while userdata locks are wiped and engines may rewrite the composition.\n"
                "This is activity/continuation drive, not Master Volume and not the 50/50\n"
                "C/U source coefficients.\n"
                "Turn protect ON (skip overwrite) to return to the 50–150% band."
            )
        return (
            "Canonical Resonance / Activity — User Data Overwrite OFF (protect ON)\n"
            "Range: 50–150%.\n"
            "50% floor with active user data; up to 150% autonomous continuation when\n"
            "user activity is low. Respects protected userdata; does not wipe locks.\n"
            "Activity/continuation drive only — not Master Volume and not the optional Canonical Live Overblend waveform mix.\n"
            "Turn protect OFF (User Data Overwrite) to open the 0–200% band."
        )

    def _validated_canonical_resonance(self, value, *, fallback=None):
        """Return an exact legal resonance value without np.clip/saturation.

        Values inside the active 0–200% or 50–150% domain pass through bit-for-bit
        as Python floats. Out-of-domain/non-finite external data is rejected to the
        supplied fallback rather than silently flattened onto an endpoint.
        """
        lo, hi = self._canonical_resonance_range()
        if fallback is None:
            fallback = CANONICAL_RESONANCE_DEFAULT
        try:
            v = float(value)
        except Exception:
            return float(fallback)
        if not math.isfinite(v) or v < lo or v > hi:
            try:
                f = float(fallback)
            except Exception:
                f = CANONICAL_RESONANCE_DEFAULT
            if not math.isfinite(f) or f < lo or f > hi:
                f = lo + 0.5 * (hi - lo)
            return float(f)
        return v

    def _sync_canonical_resonance_ui_range(self):
        """Expand/contract the resonance spin to match protect / overwrite mode."""
        lo, hi = self._canonical_resonance_range()
        lo_pct, hi_pct = lo * 100.0, hi * 100.0
        spin = getattr(self, "spin_canonical_resonance", None)
        if spin is not None:
            try:
                cur = float(spin.value())
                spin.blockSignals(True)
                spin.setRange(lo_pct, hi_pct)
                # The widget owns the legal UI domain. Preserve every legal interior
                # value exactly; when switching protection domains use unity rather
                # than silently saturating onto an endpoint.
                if cur < lo_pct or cur > hi_pct or not math.isfinite(cur):
                    cur = CANONICAL_RESONANCE_DEFAULT * 100.0
                spin.setValue(cur)
                spin.blockSignals(False)
                spin.setToolTip(self._canonical_resonance_tooltip())
            except Exception:
                try:
                    spin.blockSignals(False)
                except Exception:
                    pass
        try:
            self.canonical_resonance_factor_min = lo
            self.canonical_resonance_factor_max = hi
            factor = self._validated_canonical_resonance(
                getattr(self, "canonical_resonance_factor", CANONICAL_RESONANCE_DEFAULT),
                fallback=CANONICAL_RESONANCE_DEFAULT,
            )
            self.canonical_resonance_factor = factor
            mode = "0–200% OVERWRITE" if self._user_data_overwrite_on() else "50–150% PROTECT"
            if hasattr(self, "lbl_canonical_resonance"):
                self.lbl_canonical_resonance.setText(
                    f"CANONICAL RESONANCE: {factor * 100:.0f}%  ·  {mode}"
                )
        except Exception:
            pass

    def _on_canonical_resonance_changed(self, value):
        """Set the manual canonical resonance/activity ceiling for the active band."""
        lo, hi = self._canonical_resonance_range()
        try:
            self.canonical_resonance_factor = self._validated_canonical_resonance(
                float(value) / 100.0, fallback=getattr(self, "canonical_resonance_factor", CANONICAL_RESONANCE_DEFAULT)
            )
            self.canonical_resonance_handoff = self.canonical_resonance_factor
        except Exception:
            self.canonical_resonance_factor = CANONICAL_RESONANCE_DEFAULT
            self.canonical_resonance_handoff = self.canonical_resonance_factor
        try:
            mode = "0–200% OVERWRITE" if self._user_data_overwrite_on() else "50–150% PROTECT"
            self.lbl_canonical_resonance.setText(
                f"CANONICAL RESONANCE: {self.canonical_resonance_factor * 100:.0f}%  ·  {mode}"
            )
        except Exception:
            pass

    def _canonical_resonance_for_activity(self, user_activity):
        """Return a smoothed canonical activity factor in the active band.

        Protect ON (50–150%): full user activity targets the 50% floor; zero user
        activity targets up to the manual ceiling (≤150%).

        User Data Overwrite ON (0–200%): full user activity can target 0%; zero
        user activity targets up to the manual ceiling (≤200%).

        Applied only to the autonomous canonical continuation branch — never
        changes the independently selected Canonical Live Overblend coefficients.
        """
        lo, hi = self._canonical_resonance_range()
        try:
            ua = float(np.clip(float(user_activity), 0.0, 1.0))
        except Exception:
            ua = 0.0
        # Map user activity into [lo, hi]: high activity → lo, low activity → hi.
        target = lo + (hi - lo) * (1.0 - ua)
        ceiling_raw = getattr(self, "canonical_resonance_factor", hi)
        try:
            ceiling = float(ceiling_raw)
        except (TypeError, ValueError):
            ceiling = hi
        if not math.isfinite(ceiling):
            ceiling = hi
        ceiling = self._validated_canonical_resonance(ceiling, fallback=hi)
        # target is algebraically inside [lo,hi]; ceiling is a user-selected cap.
        # No saturation is applied to legal resonance values.
        if target > ceiling:
            target = ceiling
        current = self._validated_canonical_resonance(
            getattr(self, "canonical_resonance_handoff", CANONICAL_RESONANCE_DEFAULT),
            fallback=CANONICAL_RESONANCE_DEFAULT,
        )
        rate = float(getattr(self, "canonical_resonance_handoff_rate", 0.20) or 0.20)
        if not math.isfinite(rate):
            rate = 0.20
        rate = float(np.clip(rate, 0.01, 1.0))
        current += rate * (target - current)
        # Convex interpolation of legal values remains legal; preserve it exactly.
        self.canonical_resonance_handoff = float(current)
        return current

    def _ensure_canonical_control_integrity(self, instrument_name=None, row_idx=0):
        """Self-heal canonical coverage while preserving user-owned sequence data."""
        try:
            strategy = str(getattr(self, "canonical_control_strategy", "Full Canonical"))
            if strategy not in getattr(self, "canonical_control_options", ()): 
                strategy = "Full Canonical"
                self.canonical_control_strategy = strategy
            strength = self._update_canonical_signal_control(instrument_name, row_idx)
            if strategy == "Full Canonical" and strength < 1.0 - 1e-12:
                self.canonical_signal_control = 1.0
                self._materialize_canonical_coverage(instrument_name, row_idx)
                try:
                    self.lbl_canonical_signal_control.setText("CANONICAL SIGNAL CONTROL: 100%")
                except Exception:
                    pass
            return float(self.canonical_signal_control)
        except Exception:
            self.canonical_signal_control = 1.0 if str(getattr(self, "canonical_control_strategy", "Full Canonical")) == "Full Canonical" else 0.50
            return float(self.canonical_signal_control)

    def _sequence_playlist_mapping(self, mem=None, playlist_entry=None):
        """Resolve sequence traversal mode without changing user step data."""
        mem = mem if isinstance(mem, dict) else {}
        entry = playlist_entry if isinstance(playlist_entry, dict) else {}
        override = str(entry.get("sequence_mapping", "auto") or "auto").strip().lower()
        if override == "force_wrap":
            return "wrap"
        if override == "force_schedule":
            return "schedule"
        if bool(mem.get("sequence_force_schedule", False)):
            return "schedule"
        if bool(mem.get("sequence_force_wrap", False)):
            return "wrap"
        mode = str(mem.get("sequence_playlist_mode", "wrap") or "wrap").strip().lower()
        return "schedule" if mode in ("schedule", "scheduled", "playlist_schedule") else "wrap"

    def _load_sequence_playlist_mode_controls(self, mem):
        mem = mem if isinstance(mem, dict) else {}
        mode = self._sequence_playlist_mapping(mem)
        if hasattr(self, "combo_sequence_playlist_mode"):
            self.combo_sequence_playlist_mode.blockSignals(True)
            self.combo_sequence_playlist_mode.setCurrentIndex(1 if mode == "schedule" else 0)
            self.combo_sequence_playlist_mode.blockSignals(False)
        if hasattr(self, "chk_force_sequence_wrap"):
            self.chk_force_sequence_wrap.blockSignals(True)
            self.chk_force_sequence_wrap.setChecked(bool(mem.get("sequence_force_wrap", False)))
            self.chk_force_sequence_wrap.blockSignals(False)
        if hasattr(self, "chk_force_sequence_schedule"):
            self.chk_force_sequence_schedule.blockSignals(True)
            self.chk_force_sequence_schedule.setChecked(bool(mem.get("sequence_force_schedule", False)))
            self.chk_force_sequence_schedule.blockSignals(False)

    def _on_sequence_playlist_mode_changed(self, index):
        mem = self._current_sequence_mem()
        mem["sequence_playlist_mode"] = "schedule" if int(index) == 1 else "wrap"
        # The explicit mode is editable, while force flags remain independent overrides.
        self._on_live_source_changed()

    def _on_sequence_force_mode_changed(self, checked):
        mem = self._current_sequence_mem()
        sender = self.sender()
        if sender is getattr(self, "chk_force_sequence_schedule", None) and checked:
            if hasattr(self, "chk_force_sequence_wrap"):
                self.chk_force_sequence_wrap.blockSignals(True)
                self.chk_force_sequence_wrap.setChecked(False)
                self.chk_force_sequence_wrap.blockSignals(False)
            mem["sequence_force_schedule"] = True
            mem["sequence_force_wrap"] = False
            if hasattr(self, "combo_sequence_playlist_mode"):
                self.combo_sequence_playlist_mode.blockSignals(True); self.combo_sequence_playlist_mode.setCurrentIndex(1); self.combo_sequence_playlist_mode.blockSignals(False)
        elif sender is getattr(self, "chk_force_sequence_wrap", None) and checked:
            if hasattr(self, "chk_force_sequence_schedule"):
                self.chk_force_sequence_schedule.blockSignals(True)
                self.chk_force_sequence_schedule.setChecked(False)
                self.chk_force_sequence_schedule.blockSignals(False)
            mem["sequence_force_wrap"] = True
            mem["sequence_force_schedule"] = False
            if hasattr(self, "combo_sequence_playlist_mode"):
                self.combo_sequence_playlist_mode.blockSignals(True); self.combo_sequence_playlist_mode.setCurrentIndex(0); self.combo_sequence_playlist_mode.blockSignals(False)
        else:
            if sender is getattr(self, "chk_force_sequence_schedule", None): mem["sequence_force_schedule"] = bool(checked)
            if sender is getattr(self, "chk_force_sequence_wrap", None): mem["sequence_force_wrap"] = bool(checked)
        self._on_live_source_changed()

    def _on_global_track_offset_changed(self, value):
        """Persist the prominent global track timing offset.

        User-owned control (like Canonical Resonance amount): engines respond to
        it, but it is not a handle for canonical modification/overwrite.
        """
        try:
            v = float(value)
            if not math.isfinite(v):
                v = 0.0
            self.global_track_offset = v
            self._on_live_source_changed()
        except Exception as exc:
            print(f"[Global Track Offset] update failed: {exc}")

    def _load_track_offset_control(self, mem):
        """Load the legacy selected-sequence offset if its control still exists."""
        mem = mem if isinstance(mem, dict) else {}
        try:
            value = float(mem.get("track_offset", 0.0) or 0.0)
            if not math.isfinite(value):
                value = 0.0
        except Exception:
            value = 0.0
        if hasattr(self, "spin_track_offset"):
            self.spin_track_offset.blockSignals(True)
            self.spin_track_offset.setValue(value)
            self.spin_track_offset.blockSignals(False)

    def _on_track_offset_changed(self, value):
        """Persist the selected sequence's track offset.

        Per-sequence TrackOffset is user-owned (like resonance amount): the
        runtime schedule is refreshed so audio/video/game respond, but canonical
        engines must not treat this field as a writable modification handle.
        """
        try:
            mem = self._current_sequence_mem()
            v = float(value)
            if not math.isfinite(v):
                v = 0.0
            mem["track_offset"] = v
            # Refresh schedule mirrors only — do not hand ownership to canonical.
            if hasattr(self, "_canonical_write_sequence_runtime"):
                self._canonical_write_sequence_runtime()
            self._on_live_source_changed()
        except Exception as exc:
            print(f"[Track Offset] update failed: {exc}")

    def _on_sequence_length_changed(self, value):
        """V35.20 single-writer STEP length control, parallel to Automation length.

        Human interaction owns this length from this point forward.  Autosave,
        history, canonical refreshes and slower selector refreshes may serialize or
        read it, but may not write an older length back into the live sequence.
        """
        mem = self._current_sequence_mem()
        n = max(1, min(STRUCT_MAX_STEPS, int(value)))
        mem["sequence_length_user_owned"] = True
        self._repartition_sequence_length(mem, n)

        # Repartition canonical companions in the selected bank to the same phase
        # resolution instead of regenerating different musical material.  This is
        # the v35.20 composition-preservation contract: display/control length can
        # change while the canonical form remains phase-equivalent.
        try:
            name = self._current_instrument_name()
            bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(name, {})
            for _sid, _mem in (bank or {}).items():
                if _mem is mem or not isinstance(_mem, dict):
                    continue
                if str(_mem.get("canonical_owner", "")).startswith("canonical:"):
                    self._repartition_sequence_length(_mem, n)
        except Exception:
            pass
        if hasattr(self, "spin_auto_point_length"):
            self.spin_auto_point_length.blockSignals(True)
            self.spin_auto_point_length.setRange(1, STRUCT_MAX_STEPS)
            if str(getattr(self, "automator_timing_mode", "wrap")) == "wrap" and bool(getattr(self, "chk_auto_sync_sequencer", None) is not None and self.chk_auto_sync_sequencer.isChecked()):
                delta = int(self.spin_auto_syncopate.value()) if hasattr(self, "spin_auto_syncopate") else 0
                self.spin_auto_point_length.setValue(max(1, min(STRUCT_MAX_STEPS, n + delta)))
            else:
                self.spin_auto_point_length.setValue(min(max(1, self.spin_auto_point_length.value()), STRUCT_MAX_STEPS))
            self.spin_auto_point_length.blockSignals(False)
        # Keep the hidden compatibility alias synchronized without a second UI concept.
        if hasattr(self, "spin_pattern_length"):
            self.spin_pattern_length.blockSignals(True)
            self.spin_pattern_length.setValue(n)
            self.spin_pattern_length.blockSignals(False)
        if hasattr(self, "slider_pkp_boost_steps"):
            self.slider_pkp_boost_steps.blockSignals(True)
            self.slider_pkp_boost_steps.setRange(0.25, float(max(1, n)))
            self.slider_pkp_boost_steps.setValue(min(self.slider_pkp_boost_steps.value(), float(max(1, n))))
            self.slider_pkp_boost_steps.blockSignals(False)
            self._on_pkp_boost_steps_changed(self.slider_pkp_boost_steps.value())
        self.rebuild_sequencer_steps(n)
        self._refresh_sequence_selector()
        self._refresh_sequence_dependent_panels()
        self._canonical_write_sequence_runtime()
        self._on_live_source_changed()

    def _refresh_sequence_dependent_panels(self):
        """One authoritative refresh path for sequence selection/resize."""
        try:
            QTimer.singleShot(0, self._refresh_connector_links)
        except Exception:
            pass
        try:
            self._refresh_sequence_selector()
        except Exception:
            pass
        try:
            self.reload_active_instrument_sequencer_ui()
        except Exception:
            pass
        try:
            self.update()
        except Exception:
            pass

    def _on_pattern_length_changed(self, value):
        # Compatibility entry point for saved projects/legacy callers.
        self._on_sequence_length_changed(value)

    def _canonical_sequence_reconcile(self, trigger_source=None):
        """Reconcile canonical sequences deterministically, preserving resize identity.

        Normal canonical transactions regenerate canonical material from the active set.
        An ensemble resize is different: surviving instruments must retain the exact
        canonical sequence objects they were already playing, while only newly-created
        instruments receive newly generated canonical sequences.  This prevents the
        post-resize sound from changing until the user retoggles the engines.
        """
        banks = getattr(self, "instrument_sequence_banks", {}) or {}
        names = list(getattr(self, "instrument_names_48", []) or [])
        active = set(self._active_engine_sources()) if hasattr(self, "_active_engine_sources") else set()
        # GOAVA_SINE_HARMONIC_2026: GOAVA no longer occupies a sequence slot in
        # any instrument bank.  Its sine harmonic is synthesized per-row from
        # goava_note_events in the mix path; it reserves no canonical sequence.
        active.discard("goava")
        canonical_order = ["goava", "phase_lock", "euclidean", "randomizer", "seeded", "fractal_seed"]
        active_order = [x for x in canonical_order if x in active]
        if not names:
            return
        prepared = getattr(self, "_canonical_prepared_sequence_plan", None)
        if (not getattr(self, "_canonical_model_only", False)
                and prepared is not None
                and getattr(self, "_unison_composition_guard", False)
                and not getattr(self, "_canonical_resize_preserve_sequences", False)
                and set(prepared["sources"]) == set(active_order)
                and prepared["names"] == names):
            for name in names:
                bank = banks.setdefault(name, {})
                for sid in list(bank):
                    if str((bank[sid] or {}).get("canonical_owner", "")).startswith("canonical:"):
                        del bank[sid]
                for sid, mem in prepared["banks"].get(name, {}).items():
                    if sid in bank:
                        raise RuntimeError("canonical projection would overwrite a user-owned sequence")
                    bank[sid] = copy.deepcopy(mem)
                if not bank:
                    continue
                selected = self.instrument_selected_sequence.get(name, min(bank))
                if selected not in bank:
                    selected = min(bank)
                self.instrument_selected_sequence[name] = selected
                self.instrument_sequencer_memory[name] = bank[selected]
                param = self.instrument_param_state.setdefault(name, {})
                planned = prepared["params"].get(name, {})
                if not param.get("harmonic_freq_user_locked") and "harmonic_freq" in planned:
                    param["harmonic_freq"] = planned["harmonic_freq"]
                    param.setdefault("tuning_ratio", 1.0)
                    getattr(self, "instrument_param_generated", {}).setdefault(name, {})["harmonic_freq"] = planned["harmonic_freq"]
            self._finish_canonical_sequence_projection(active_order)
            return
        seed = _safe_int_seed(self.get_numeric_seed())
        # Evaluate one bounded event plan per seed/tempo transaction, then
        # rasterize it deterministically into each instrument's actual step
        # window. No stochastic RNG is used for Fractal Seed events.
        fractal_plan = self._fractal_seed_event_plan() if "fractal_seed" in active_order else None

        for name in names:
            bank = banks.setdefault(name, {})
            if not bank:
                bank[1] = copy.deepcopy(self.instrument_sequencer_memory.get(name, {}) or
                                        {"pattern_length": DEFAULT_SEQUENCE_LENGTH, "steps": [False]*DEFAULT_SEQUENCE_LENGTH,
                                         "gates": [True]*DEFAULT_SEQUENCE_LENGTH, "amplitudes": [1.0]*DEFAULT_SEQUENCE_LENGTH,
                                         "pitches": [1.0]*DEFAULT_SEQUENCE_LENGTH, "probabilities": [100]*DEFAULT_SEQUENCE_LENGTH,
                                         "offsets": [0.0]*DEFAULT_SEQUENCE_LENGTH, "sequence_envelope_attack": 0.5, "sequence_envelope_release": 0.5})

            # Preserve user-owned/non-canonical IDs exactly.  Canonical IDs occupy a
            # deterministic contiguous range after the highest user sequence ID.
            user_ids = sorted(int(k) for k,v in bank.items()
                              if str(k).isdigit() and isinstance(v, dict)
                              and not str(v.get("canonical_owner", "")).startswith("canonical:"))
            if not user_ids:
                user_ids = [1]
                bank.setdefault(1, {"sequence_id": 1, "pattern_length": DEFAULT_SEQUENCE_LENGTH,
                                     "steps": [False]*DEFAULT_SEQUENCE_LENGTH, "gates": [True]*DEFAULT_SEQUENCE_LENGTH,
                                     "amplitudes": [1.0]*DEFAULT_SEQUENCE_LENGTH, "pitches": [1.0]*DEFAULT_SEQUENCE_LENGTH,
                                     "probabilities": [100]*DEFAULT_SEQUENCE_LENGTH, "offsets": [0.0]*DEFAULT_SEQUENCE_LENGTH,
                                     "user_owned": True})
            # During ensemble resize, preserve canonical sequence objects for every
            # surviving instrument/source pair.  Their exact steps, offsets, amplitudes
            # and pitches are part of the established sound identity.  New instruments
            # are the only ones that need fresh canonical sequence material.
            preserve_resize = bool(getattr(self, "_canonical_resize_preserve_sequences", False))
            existing_canonical = {}
            for idx, mem0 in bank.items():
                if not isinstance(mem0, dict):
                    continue
                owner = str(mem0.get("canonical_owner", ""))
                if owner.startswith("canonical:"):
                    existing_canonical[owner] = (int(idx), mem0)
            if not preserve_resize:
                for idx in list(bank.keys()):
                    mem0 = bank.get(idx)
                    if isinstance(mem0, dict) and str(mem0.get("canonical_owner", "")).startswith("canonical:"):
                        bank.pop(idx, None)
                existing_canonical = {}

            base_max = max(user_ids)
            for rank, source in enumerate(active_order, start=1):
                owner = f"canonical:{source}"
                if preserve_resize and owner in existing_canonical:
                    # Exact object is copied so later candidate evaluation cannot mutate
                    # the preserved resize state through an alias.
                    idx, prior_mem = existing_canonical[owner]
                    bank[idx] = copy.deepcopy(prior_mem)
                    continue
                idx = base_max + rank
                # Avoid collisions if a preserved canonical ID already occupies this slot.
                while idx in bank:
                    idx += 1
                channel = sum(ord(c) for c in source) & 0xFFFF
                # Per-instrument evaluated seed (list scripts → distinct numbers).
                # Do NOT primary-seed from sha256(name) — that overwrote list data.
                try:
                    name_idx = list(names).index(name)
                except Exception:
                    name_idx = 0
                # Fold sequence slot id into seed so each bank sequence differs.
                inst_seed_i = (
                    self._instrument_seed_int(name_idx, name=name, sequence_id=idx)
                    if hasattr(self, "_instrument_seed_int")
                    else (seed ^ channel ^ int(idx)) & 0x7fffffff
                )
                # Evaluated float seed for this instrument (list scripts → unique).
                try:
                    inst_seed_f = float(self._instrument_seed_float(name_idx, sequence_id=idx))
                except Exception:
                    inst_seed_f = float(inst_seed_i)

                # CANONICAL_LENGTH_FROM_SEED: length used to be pinned to the user
                # sequence's pattern_length no matter what the engine was writing,
                # so Euclidean pulse geometry, GOAVA's numeric-event count, and
                # per-instrument seed rotation could only change *which* steps were
                # on, never the length they actually implied. Each source now
                # derives its own length from the same seed/instrument factors it
                # uses to place steps and pitches; phase_lock still tracks the
                # established user grid on purpose (it is meant to lock to it).
                base_len = int(bank.get(user_ids[0], {}).get("pattern_length", DEFAULT_SEQUENCE_LENGTH) or DEFAULT_SEQUENCE_LENGTH)
                if source == "euclidean":
                    stride = max(2, int(2 + (inst_seed_i % 5)))
                    reps = max(1, 2 + (inst_seed_i // 5) % 6)
                    n = stride * reps
                elif source == "goava":
                    try:
                        n_vals = max(1, len(list(self.get_seed_values(t_value=0.0) or [])))
                    except Exception:
                        n_vals = 1
                    # Round up to a whole number of seed-list rotations so every
                    # evaluated value is actually used at least once per pass.
                    n = int(math.ceil(max(base_len, n_vals) / n_vals) * n_vals)
                elif source in ("phase_lock", "fractal_seed"):
                    n = base_len
                else:
                    jitter = int(round(4 * series_sin(inst_seed_i * MEUM_INV)))
                    n = base_len + jitter
                n = max(1, min(STRUCT_MAX_STEPS, n))

                mem = {
                    "sequence_id": idx, "pattern_length": n,
                    "canonical_owner": f"canonical:{source}", "user_owned": False,
                    "steps": [False] * n, "gates": [True] * n,
                    "amplitudes": [1.0] * n, "pitches": [1.0] * n,
                    "probabilities": [100] * n, "offsets": [0.0] * n,
                    "engine_step_sources": {}, "touched": set(),
                }
                rng = np.random.default_rng((inst_seed_i ^ channel) & 0x7fffffff)
                phase_on = "phase_lock" in active
                fractal_raster = None
                if source == "fractal_seed" and isinstance(fractal_plan, dict):
                    try:
                        from groovebox_v3.fractal_seed_engine import rasterize_sequence
                        # GROOVEBOX_RASTER_CACHE_20261102: the projection is a pure function of the plan
                        # and the length and is only read below, so every instrument with the same
                        # length reuses one projection instead of recomputing it (1024 calls per update).
                        _fr_hash = str(fractal_plan.get("event_plan_sha256", "") or "")
                        _fr_key = (_fr_hash, int((fractal_plan.get("interpretation") or {}).get("window_steps", 0) or 0),
                                   str((fractal_plan.get("seed") or {}).get("identity", "")), int(n)) if _fr_hash else None
                        _fr_cache = self.__dict__.setdefault("_fractal_raster_cache", {})
                        fractal_raster = _fr_cache.get(_fr_key) if _fr_key is not None else None
                        if fractal_raster is None:
                            fractal_raster = rasterize_sequence(fractal_plan, n)
                            if _fr_key is not None:
                                if len(_fr_cache) >= 64:
                                    _fr_cache.clear()
                                _fr_cache[_fr_key] = fractal_raster
                    except Exception as _fractal_exc:
                        print(f"[Fractal Seed] sequence projection failed for {name}: {_fractal_exc}")
                for j in range(n):
                    if source == "fractal_seed":
                        if not isinstance(fractal_raster, dict):
                            continue
                        if not fractal_raster["steps"][j]:
                            continue
                        mem["steps"][j] = True
                        mem["pitches"][j] = float(fractal_raster["pitches"][j])
                        mem["amplitudes"][j] = float(fractal_raster["amplitudes"][j])
                        mem["gates"][j] = bool(fractal_raster["gates"][j])
                        mem["probabilities"][j] = 100
                        mem["offsets"][j] = float(fractal_raster["offsets"][j])
                        mem["engine_step_sources"][int(j)] = {"canonical:fractal_seed"}
                        continue
                    if source == "goava":
                        mem["steps"][j] = True
                    elif source == "euclidean":
                        pulses = max(2, n // 4)
                        stride = max(2, int(2 + (inst_seed_i % 5)))
                        mem["steps"][j] = bool(((j * stride + inst_seed_i) % n) < pulses)
                    elif source == "phase_lock":
                        # Dense structural grid — phase-lock owns non-stochastic placement.
                        mem["steps"][j] = bool(((j * 3 + inst_seed_i) % 5) < 3)
                    else:
                        threshold = 0.34 + 0.18 * series_sin((j + 1) * MEUM_INV + inst_seed_i * 1e-4)
                        mem["steps"][j] = bool(rng.random() > threshold)
                    # >>> GROK_EDIT_BEGIN: canonical_pitch_from_seed
                    # ALWAYS write pitches — previously left at 1.0 for most sources
                    # so every instrument hit the same note.
                    lattice = _seed_to_pitch_ratio(inst_seed_f, name_idx, j)
                    if source == "phase_lock":
                        mem["pitches"][j] = float(np.clip(lattice, 1.0/32.0, 32.0))
                    elif phase_on and source in ("seeded", "randomizer", "euclidean"):
                        # Contextual provocation around the phase-lock lattice,
                        # not free random notes that ignore structure.
                        jitter = 0.06 * series_sin((j + 1) * MEUM + inst_seed_i * 0.01)
                        mem["pitches"][j] = float(np.clip(lattice * (1.0 + jitter), 1.0/32.0, 32.0))
                    elif source == "goava":
                        # Full-range GOAVA pitch from seed lattice (no 7-step ramp)
                        mem["pitches"][j] = float(np.clip(lattice, 1.0/32.0, 32.0))
                    else:
                        # Stochastic alone: seed lattice + mild RNG color
                        mem["pitches"][j] = float(np.clip(
                            lattice * (0.85 + 0.30 * float(rng.random())), 1.0/32.0, 32.0
                        ))
                    # <<< GROK_EDIT_END: canonical_pitch_from_seed
                    # Continuous amplitude/offset — full float decimals from seed phase
                    _ph = (j + 1) * MEUM + inst_seed_i * 0.001317
                    _ph2 = (j + 1) * MEUM_INV + inst_seed_i * 1.713e-5
                    mem["amplitudes"][j] = float(0.5 + 0.5 * series_sin(_ph) * series_cos(_ph2 * 0.37))
                    mem["amplitudes"][j] = float(abs(mem["amplitudes"][j]))
                    if mem["amplitudes"][j] < 0.0:
                        mem["amplitudes"][j] = 0.0
                    if mem["amplitudes"][j] > 1.0:
                        mem["amplitudes"][j] = 1.0
                    mem["offsets"][j] = float(0.5 * series_sin(_ph2) * series_cos(_ph * MEUM_NORM))
                    mem["engine_step_sources"][int(j)] = {f"canonical:{source}"}
                # GROOVEBOX_R23R_CANONICAL_CONTOUR_20261103: one seed contour per
                # canonical sequence drives every remaining sculpting lane (phase,
                # phase-mod depth, probability 85–100 %, EQ gain ±3 dB, attack/
                # release with release ≥ attack, automation lane), shaped by the
                # sequencer's Contour control (dull ↔ linear ↔ sharp).
                try:
                    self._write_contour_lanes(mem, self._raw_contour(n, inst_seed_i), f"canonical:{source}", name, idx)
                except Exception as _contour_exc:
                    print(f"[Canonical contour] {name}/{source}: {_contour_exc}")
                if source == "fractal_seed" and isinstance(fractal_raster, dict) and isinstance(fractal_plan, dict):
                    mem["fractal_seed_provenance"] = {
                        "schema_version": fractal_plan.get("schema_version"),
                        "algorithm_version": fractal_plan.get("algorithm_version"),
                        "seed_identity": fractal_raster.get("seed_identity"),
                        "event_plan_sha256": fractal_raster.get("event_plan_sha256"),
                        "depth_requested": (fractal_plan.get("seed") or {}).get("depth_requested"),
                        "depth_completed": (fractal_plan.get("seed") or {}).get("depth_completed"),
                        "symbol_budget": (fractal_plan.get("evaluation") or {}).get("symbol_budget"),
                        "symbols_evaluated": (fractal_plan.get("evaluation") or {}).get("symbols_evaluated"),
                        "complete_for_requested_depth": (fractal_plan.get("evaluation") or {}).get("complete_for_requested_depth"),
                        "sequence_length": n,
                        "window_steps": fractal_raster.get("window_steps"),
                        "step_lineage": copy.deepcopy(fractal_raster.get("step_lineage", {})),
                    }
                bank[idx] = mem
                # Write synth panel fundamental from seed so panels match the note identity.
                try:
                    if not hasattr(self, "instrument_param_state") or self.instrument_param_state is None:
                        self.instrument_param_state = {}
                    pst = self.instrument_param_state.setdefault(name, {})
                    base_hz = float(self.spin_base_frequency.value()) if hasattr(self, "spin_base_frequency") else 432.0
                    # Only overwrite generated (non-user) harmonic when engine is authoring.
                    if not pst.get("harmonic_freq_user_locked"):
                        pst["harmonic_freq"] = float(_seed_to_fundamental_hz(inst_seed_f, base_hz, name_idx, 0))
                        pst.setdefault("tuning_ratio", 1.0)
                        gen = getattr(self, "instrument_param_generated", None)
                        if isinstance(gen, dict):
                            gen.setdefault(name, {})["harmonic_freq"] = pst["harmonic_freq"]
                except Exception:
                    pass
            # Selected sequence is preserved if it points to a user sequence;
            # otherwise it is assigned deterministically to the first canonical slot.
            selected_map = getattr(self, "instrument_selected_sequence", {})
            selected = int(selected_map.get(name, user_ids[0]))
            if selected not in bank or (isinstance(bank.get(selected), dict) and
                                        str(bank[selected].get("canonical_owner", "")).startswith("canonical:")):
                selected = user_ids[0]
            selected_map[name] = selected
            self.instrument_selected_sequence[name] = selected
            self.instrument_sequencer_memory[name] = bank[selected]

        self._finish_canonical_sequence_projection(active_order)

    def _finish_canonical_sequence_projection(self, active_order):
        """GUI-owned panel/UI commits, never run by the numerical worker."""
        try:
            self._engine_resize_untouched_sequences()
        except Exception as _exc:
            print(f"[Unison] untouched sequence resize: {_exc}")
        try:
            for _src in active_order:
                self._engine_write_sequence_panels(source=_src)
        except Exception as _exc:
            print(f"[Unison] sequence addon panels: {_exc}")

        self._refresh_sequence_dependent_panels()

    def _ensure_sequence_banks_after_resize(self):
        banks = getattr(self, "instrument_sequence_banks", {}) or {}
        for name in getattr(self, "instrument_names_48", []):
            if name not in banks:
                banks[name] = {1: self.instrument_sequencer_memory.get(name, {})}
            if name not in self.instrument_selected_sequence:
                self.instrument_selected_sequence[name] = min(banks[name])
            idx = self.instrument_selected_sequence[name]
            self.instrument_sequencer_memory[name] = banks[name].get(idx, next(iter(banks[name].values())))
        # Resize/recomposition is an authoritative boundary: re-expand GOAVA
        # after sequence banks exist so no activation order can leave a tail of
        # playlist rows unfilled.
        if getattr(self, "goava_active", False) and getattr(self, "goava_note_events", None):
            try:
                self._apply_goava_to_canonical_playlist()
            except Exception:
                pass

    def _ensure_seq_mem_length(self, mem, count):
        """Grow sequencer arrays to `count` without shrinking or wiping existing entries."""
        for key, default in (
            ("steps", False),
            ("amplitudes", 1.0),
            ("pitches", 1.0),
            ("gates", True),
            ("probabilities", 100),
            ("offsets", 0.0),
        ):
            if key not in mem:
                mem[key] = [default] * count
            elif len(mem[key]) < count:
                mem[key].extend([default] * (count - len(mem[key])))
        lane = mem.get("automation_lane")
        if not isinstance(lane, list):
            mem["automation_lane"] = []
        controls = mem.get("step_controls")
        if not isinstance(controls, dict):
            controls = {}
            mem["step_controls"] = controls
        for lane_name, default in (("phase_shift", 0.0), ("eq_gain_db", 0.0),
                                   ("eq_frequency", 1000.0), ("eq_q", 0.707),
                                   ("sidechain_depth", 0.0), ("phase_mod_depth", 0.0),
                                   ("trigger_probability", 1.0)):
            values = controls.get(lane_name)
            if not isinstance(values, list):
                values = list(mem.get(lane_name)) if isinstance(mem.get(lane_name), list) else []
            values = values[:len(mem.get("steps", []))]
            if len(values) < len(mem.get("steps", [])):
                values.extend([default] * (len(mem.get("steps", [])) - len(values)))
            controls[lane_name] = values

    def _repartition_sequence_length(self, mem, count):
        """V35.20: phase-map a sequence to a new UI length without changing its form.

        Length is presentation/scheduling resolution once the user owns it.  We do
        not restore an older remembered value and we do not truncate the musical
        shape.  Each new cell samples the old sequence at the same normalized phase.
        """
        if not isinstance(mem, dict):
            return
        n = max(1, min(STRUCT_MAX_STEPS, int(count)))
        old_n = max(1, int(mem.get("pattern_length", len(mem.get("steps", [])) or n) or n))
        defaults = {
            "steps": False, "amplitudes": 1.0, "pitches": 1.0,
            "gates": True, "probabilities": 100, "offsets": 0.0,
        }
        for key, default in defaults.items():
            src = list(mem.get(key) or [])
            if not src:
                src = [default] * old_n
            if len(src) < old_n:
                src.extend([default] * (old_n - len(src)))
            src = src[:old_n]
            if n == old_n:
                mem[key] = src
                continue
            # Cell-centre phase mapping avoids a bias toward step 0 when shrinking.
            out = []
            for i in range(n):
                phase = (i + 0.5) / float(n)
                j = min(old_n - 1, max(0, int(phase * old_n)))
                out.append(copy.deepcopy(src[j]))
            mem[key] = out
        touched = mem.get("touched")
        if touched:
            try:
                mapped = set()
                for i in range(n):
                    phase = (i + 0.5) / float(n)
                    j = min(old_n - 1, max(0, int(phase * old_n)))
                    if j in touched:
                        mapped.add(i)
                mem["touched"] = mapped
            except Exception:
                pass
        mem["pattern_length"] = n

    def _sequence_is_user_locked(self, mem):
        """True when human step edits OR a human-selected sequence length owns the row."""
        if not isinstance(mem, dict):
            return False
        if bool(mem.get("sequence_length_user_owned", False)):
            return True
        touched = mem.get("touched") or set()
        try:
            return len(touched) > 0
        except TypeError:
            return bool(touched)

    def _blend_param_dicts(self, master, addon, amount):
        """Lerp numeric synth keys; non-numeric keys pick addon past 50% blend."""
        amount = float(np.clip(float(amount), 0.0, 1.0))
        out = dict(master or {})
        addon = addon or {}
        if amount <= 0.0 or not addon:
            return out
        for k, v in addon.items():
            if k == "geo" and isinstance(v, dict) and isinstance(out.get(k), dict):
                out[k] = blend_geo_instances([(1.0 - amount, out[k]), (amount, v)])
                continue
            if k == "meum_modulation" and isinstance(v, dict) and isinstance(out.get(k), dict):
                out[k] = self._blend_param_dicts(out.get(k) or {}, v, amount)
                continue
            mv = out.get(k, v)
            try:
                out[k] = (1.0 - amount) * float(mv) + amount * float(v)
            except (TypeError, ValueError):
                out[k] = v if amount >= 0.5 else mv
        return out

    def _coverage_blend_for_operator(self, entry, op_name):
        if not isinstance(entry, dict):
            return 0.5
        if entry.get("blend_percent") not in (None, ""):
            try:
                return float(np.clip(float(entry["blend_percent"]) / 100.0, 0.0, 1.0))
            except (TypeError, ValueError):
                pass
        cov = str(entry.get("coverage") or "")
        name = str(op_name or "")
        if name and name in cov and "%" in cov:
            try:
                part = cov.split(name, 1)[1]
                num = "".join(ch for ch in part.split("%", 1)[0] if ch.isdigit() or ch == ".")
                if num:
                    return float(np.clip(float(num) / 100.0, 0.0, 1.0))
            except Exception:
                pass
        return 0.5

    def _resolved_synth_state(self, op_name, mem, entry=None):
        """Master instrument panel mixed with this sequence's addon synth panel."""
        master = dict((getattr(self, "instrument_param_state", {}) or {}).get(op_name, {}) or {})
        panels = (mem or {}).get("panels") if isinstance(mem, dict) else None
        if not isinstance(panels, dict):
            return master
        addon = panels.get("synth") or {}
        if not addon:
            return master
        amt = panels.get("blend")
        if amt in (None, ""):
            amt = self._coverage_blend_for_operator(entry, op_name)
        else:
            try:
                amt = float(amt)
                if amt > 1.0:
                    amt = amt / 100.0
            except (TypeError, ValueError):
                amt = 0.5
        return self._blend_param_dicts(master, addon, amt)

    def _instrument_has_sounding_steps(self, name):
        banks = (getattr(self, "instrument_sequence_banks", {}) or {}).get(name, {})
        mems = []
        if isinstance(banks, dict):
            mems.extend(v for v in banks.values() if isinstance(v, dict))
        live = (getattr(self, "instrument_sequencer_memory", {}) or {}).get(name)
        if isinstance(live, dict):
            mems.append(live)
        for mem in mems:
            steps = mem.get("steps") or []
            if any(bool(s) for s in steps):
                return True
        return False

    def _engine_resize_untouched_sequences(self):
        """Canonical engines may resize any sequence the user has not touched."""
        banks = getattr(self, "instrument_sequence_banks", {}) or {}
        names = list(getattr(self, "instrument_names_48", []) or [])
        for name in names:
            bank = banks.get(name) or {}
            if not isinstance(bank, dict):
                continue
            canon_ns = [
                max(1, int(m.get("pattern_length", DEFAULT_SEQUENCE_LENGTH) or DEFAULT_SEQUENCE_LENGTH))
                for m in bank.values()
                if isinstance(m, dict) and str(m.get("canonical_owner", "")).startswith("canonical:")
            ]
            if not canon_ns:
                continue
            adopt = int(canon_ns[0])
            for _sid, mem in list(bank.items()):
                if not isinstance(mem, dict) or self._sequence_is_user_locked(mem):
                    continue
                owner = str(mem.get("canonical_owner", ""))
                n = int(mem.get("pattern_length", adopt) or adopt) if owner.startswith("canonical:") else adopt
                n = max(1, min(STRUCT_MAX_STEPS, n))
                mem["pattern_length"] = n
                self._ensure_seq_mem_length(mem, n)
            sel = (getattr(self, "instrument_selected_sequence", {}) or {}).get(name)
            if sel in bank:
                self.instrument_sequencer_memory[name] = bank[sel]
        try:
            mem = self._current_sequence_mem()
            if mem and not self._sequence_is_user_locked(mem) and hasattr(self, "spin_seq_length"):
                n = max(1, int(mem.get("pattern_length", DEFAULT_SEQUENCE_LENGTH) or DEFAULT_SEQUENCE_LENGTH))
                if int(self.spin_seq_length.value()) != n:
                    self.spin_seq_length.blockSignals(True)
                    self.spin_seq_length.setValue(n)
                    self.spin_seq_length.blockSignals(False)
                    if hasattr(self, "spin_pattern_length"):
                        self.spin_pattern_length.blockSignals(True)
                        self.spin_pattern_length.setValue(n)
                        self.spin_pattern_length.blockSignals(False)
                    self.rebuild_sequencer_steps(n)
        except Exception:
            pass

    # =====================================================================
    # STEP_ISOLATION_FIX
    # A click changes exactly one step. Selection and activation are no longer
    # a two-click state machine, which prevents a Step 3 click from visually
    # propagating activation across the sequence.
    # =====================================================================
    # =====================================================================
    # SEQUENCER_AUTOMATION_POINTS_2026
    # Second sequencer row. Points are canonical, playlist-addressable and
    # cross-linkable: a point morphs saved sequence/synth state A→B, then
    # mixes that result 50% with the composition step currently being played.
    # =====================================================================
    def _sequence_state_for_automation(self, instrument_name, sequence_id):
        bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(instrument_name, {})
        try:
            sid = int(sequence_id)
        except Exception:
            sid = 1
        mem = bank.get(sid) if isinstance(bank, dict) else None
        if not isinstance(mem, dict):
            mem = (getattr(self, "instrument_sequencer_memory", {}) or {}).get(instrument_name, {})
        return mem if isinstance(mem, dict) else {}

    def _automation_panel_state(self, instrument_name, sequence_id):
        mem = self._sequence_state_for_automation(instrument_name, sequence_id)
        panels = mem.get("panels", {}) if isinstance(mem, dict) else {}
        if not isinstance(panels, dict):
            panels = {}
        synth = panels.get("synth", {})
        if not isinstance(synth, dict) or not synth:
            synth = copy.deepcopy((getattr(self, "instrument_param_state", {}) or {}).get(instrument_name, {}) or {})
        master = (getattr(self, "instrument_param_state", {}) or {}).get(instrument_name, {}) or {}
        offsets = panels.get("reference_offsets", {})
        if not isinstance(offsets, dict):
            offsets = {}
        for key, value in synth.items():
            if key in master:
                try:
                    if isinstance(value, (int, float, np.number)) and isinstance(master[key], (int, float, np.number)):
                        offsets.setdefault(key, float(value) - float(master[key]))
                except Exception:
                    pass
        return {"synth": copy.deepcopy(synth), "sequence": copy.deepcopy(mem), "reference_offsets": copy.deepcopy(offsets)}

    @staticmethod
    def _automation_lerp_value(a, b, amount):
        try:
            if isinstance(a, bool) or isinstance(b, bool):
                return bool(a if amount < 0.5 else b)
            if isinstance(a, (int, float, np.number)) and isinstance(b, (int, float, np.number)):
                return float(a) + (float(b) - float(a)) * float(amount)
        except Exception:
            pass
        return copy.deepcopy(a if amount < 0.5 else b)

    def _automation_lerp_dict(self, a, b, amount):
        out = copy.deepcopy(a if isinstance(a, dict) else {})
        bb = b if isinstance(b, dict) else {}
        for key in set(out) | set(bb):
            if key not in out:
                out[key] = copy.deepcopy(bb[key])
            elif key == "geo" and isinstance(out[key], dict) and isinstance(bb[key], dict):
                # Automation Morph moves the geometric-synth instance exactly as it
                # moves the other synth params (GROOVEBOX_R23R_GEOMETRY_PER_INSTRUMENT_20261031).
                _amt = float(np.clip(float(amount), 0.0, 1.0))
                out[key] = blend_geo_instances([(1.0 - _amt, out[key]), (_amt, bb[key])])
            elif key in bb:
                out[key] = self._automation_lerp_value(out[key], bb[key], amount)
        return out

    def _automation_span(self):
        """AUTOMATION_SPAN_R31_7: how far an automation morph reaches over the composition step and
        the instrument's own panel patch (0.5 legacy … 1.0 full 0–100% span)."""
        try:
            return float(min(1.0, max(0.5, float(getattr(self, "automation_morph_span", 1.0)))))
        except Exception:
            return 1.0

    def _automation_morph_sequence(self, a, b, amount, composition=None):
        a = a if isinstance(a, dict) else {}
        b = b if isinstance(b, dict) else {}
        composition = composition if isinstance(composition, dict) else a
        n = max(
            int(a.get("pattern_length", len(a.get("steps", [])) or 1) or 1),
            int(b.get("pattern_length", len(b.get("steps", [])) or 1) or 1),
            int(composition.get("pattern_length", len(composition.get("steps", [])) or 1) or 1),
        )
        n = max(1, min(STRUCT_MAX_STEPS, n))
        out = {"pattern_length": n}
        for key, default in (("steps", False), ("gates", True), ("amplitudes", 1.0),
                             ("pitches", 1.0), ("probabilities", 100), ("offsets", 0.0)):
            aa = list(a.get(key, []) or [])
            bb = list(b.get(key, []) or [])
            cc = list(composition.get(key, []) or [])
            vals = []
            for i in range(n):
                av = aa[i] if i < len(aa) else default
                bv = bb[i] if i < len(bb) else default
                cv = cc[i] if i < len(cc) else default
                m = self._automation_lerp_value(av, bv, amount)
                # AUTOMATION_SPAN_R31_7: composition coupling = the Morph Span. 100% (new default):
                # morph 0–100% reaches all the way from A to B. 50% = the legacy fixed coupling
                # (automation shares authority equally with the composition step, reach 0–50%).
                vals.append(self._automation_lerp_value(cv, m, self._automation_span()))
            out[key] = vals
        return out

    def _automation_point_matches(self, point, row_idx, step_idx, instrument_name):
        if not isinstance(point, dict):
            return False
        pstep = int(point.get("step", 0) or 0)
        if pstep != int(step_idx) + 1:
            return False
        prow = int(point.get("playlist_row", 0) or 0)
        if prow not in (0, int(row_idx) + 1):
            return False
        target = str(point.get("instrument", "__all__") or "__all__")
        return target in ("__all__", "", str(instrument_name))

    def _automation_resolved_state(self, point, instrument_name, composition_mem):
        """Resolve one automation control point into synth/sequence state."""
        try:
            amt = float(np.clip(float(point.get("morph", 0.5)), 0.0, 1.0))
        except Exception:
            amt = 0.5
        a_inst = str(point.get("from_instrument", instrument_name))
        b_inst = str(point.get("to_instrument", instrument_name))
        a_seq = int(point.get("from_sequence", 1) or 1)
        b_seq = int(point.get("to_sequence", 1) or 1)
        A = self._automation_panel_state(a_inst, a_seq)
        B = self._automation_panel_state(b_inst, b_seq)
        seq = self._automation_morph_sequence(A["sequence"], B["sequence"], amt, composition_mem)
        synth = self._automation_lerp_dict(A["synth"], B["synth"], amt)
        # Sequence-specific numeric data is an offset from the external/master
        # synth patch. Interpolate that offset separately so script/domain/patch
        # identity stays outside the pattern-wide synth mode.
        ref_offsets = {}
        for key in set(A.get("reference_offsets", {})) | set(B.get("reference_offsets", {})):
            try:
                av = float(A.get("reference_offsets", {}).get(key, 0.0))
                bv = float(B.get("reference_offsets", {}).get(key, 0.0))
                ref_offsets[key] = (1.0 - amt) * av + amt * bv
            except Exception:
                pass

        # Exactly half of the automation synth travel is its stored synth patch;
        # the other half is the sequence-reference offset. Offsets are relative
        # to the already-selected blend, never a second absolute control.
        point_offsets = point.get("reference_offsets", {})
        if isinstance(point_offsets, dict) and point_offsets:
            ref_offsets.update(point_offsets)
        if isinstance(ref_offsets, dict):
            for key, off in ref_offsets.items():
                try:
                    if isinstance(synth.get(key), (int, float, np.number)):
                        synth[key] = float(synth[key]) + 0.5 * float(off)
                except Exception:
                    pass
        patch = copy.deepcopy((getattr(self, "instrument_param_state", {}) or {}).get(instrument_name, {}) or {})
        synth = self._automation_lerp_dict(patch, synth, self._automation_span())
        # STEP_MOD_VECTOR_WAVETABLE_EQ: patch routes and per-step MOD share one
        # deterministic control-rate path. Enabled routes can move their target
        # on their own; a step MOD amount scales/overrides the matching route.
        try:
            motion=getattr(self,"patch_motion_state",{}) or {}
            routes=motion.get("routes",[]) if isinstance(motion,dict) else []
            step=max(1,int(point.get("step",1) or 1))
            step_depth=float(np.clip(float(point.get("mod_amount_pct",0.0) or 0.0)/100.0,-2.0,2.0))
            step_target=str(point.get("mod_target","None") or "None")
            keymap={"Wavetable Phase":"wavetable_phase","Wavetable Fold":"wavetable_fold","Vector X":"master_vector_x","Vector Y":"master_vector_y","Vector Z":"master_vector_z","EQ Low":"eq_low","EQ Mid":"eq_mid","EQ High":"eq_high","Pitch":"pitch","Amplitude":"amp","Filter Cutoff":"filter_cutoff","Resonance":"resonance","Mod Depth":"mod_depth","Sidechain":"sidechain_mod"}
            for route in routes if isinstance(routes,list) else []:
                if not isinstance(route,dict) or not route.get("enabled",True): continue
                target=str(route.get("destination","") or "")
                key=keymap.get(target)
                if not key: continue
                rate=max(0.0,float(route.get("rate_pct",100.0) or 100.0))/100.0
                direction=str(route.get("direction","Forward") or "Forward")
                src=str(route.get("source","Step MOD") or "Step MOD")
                phase=((step-1)*max(rate,0.0001))%1.0
                if src=="Canonical X": phase=(phase+float(getattr(self,"master_vector_state",{}).get("x",0.0))*0.5)%1.0
                elif src=="Canonical Y": phase=(phase+float(getattr(self,"master_vector_state",{}).get("y",0.0))*0.5)%1.0
                elif src=="Canonical Z": phase=(phase+float(getattr(self,"master_vector_state",{}).get("z",0.0))*0.5)%1.0
                elif src=="Wavetable Phase": phase=(phase+float(getattr(self,"wavetable_projector_state",{}).get("phase",0.0))*0.5)%1.0
                elif src=="LFO 2": phase=(phase*1.61803398875)%1.0
                elif src=="EQ Envelope": phase=(phase+float((getattr(self,"global_eq_state",{}) or {}).get("amount",0.0))*0.25)%1.0
                if direction=="Reverse": phase=1.0-phase
                elif direction=="Ping-Pong": phase=1.0-abs(2.0*phase-1.0)
                elif direction=="Random": phase=((step*1103515245+12345)&0x7fffffff)/2147483647.0
                elif direction=="Drift": phase=(phase+step*0.013)%1.0
                wave=2.0*phase-1.0
                route_depth=float(np.clip(float(route.get("depth_pct",50.0) or 0.0)/100.0,-2.0,2.0))
                amount=route_depth*(step_depth if step_target==target and step_depth else 1.0)
                old=synth.get(key,0.0)
                try: base=float(old)
                except Exception: base=0.0
                synth[key]=float(np.clip(base+wave*amount,-4.0,4.0))
            # A per-step MOD target remains usable even if no route is configured.
            if step_depth and step_target!="None" and not any(isinstance(r,dict) and r.get("enabled",True) and str(r.get("destination",""))==step_target for r in (routes if isinstance(routes,list) else [])):
                phase=((step-1)*0.125)%1.0
                direction=str(point.get("mod_direction","Forward") or "Forward")
                if direction=="Reverse": phase=1.0-phase
                elif direction=="Ping-Pong": phase=1.0-abs(2.0*phase-1.0)
                elif direction=="Random": phase=((step*1103515245+12345)&0x7fffffff)/2147483647.0
                key=keymap.get(step_target)
                if key:
                    try: base=float(synth.get(key,0.0))
                    except Exception: base=0.0
                    synth[key]=float(np.clip(base+(2.0*phase-1.0)*step_depth,-4.0,4.0))
        except Exception:
            pass
        return {"sequence": seq, "synth": synth, "point": point}

    def _algorithm_modulate_resolved_automation(self, state, instrument_name, point=None):
        """Runtime-only Algorithm XMOD for existing automation-resolved variables.

        It never creates steps or automation points.  It only modulates numeric
        synth/sequence values already present in the resolved automation state,
        matching the variable reach of the step-side algorithm cross-modulation.
        """
        if not isinstance(state, dict): return state
        gas=getattr(self,"global_algo_state",{}) or {}
        _cont = [c for c in self._algo_contenders_for(str(instrument_name or "")) if c[0] != "canonical"]
        if not _cont:
            return state
        # Averaged user contenders (global + local bay) drive the automation XMOD.
        gas = {"script": _cont[0][1] if len(_cont) == 1 else "", "_contenders": _cont,
               "params": {"mix": sum(c[2] for c in _cont) / len(_cont)}, "apply_enabled": True}
        if not bool(gas.get("apply_enabled",False)) and not any(bool(r.get("global_algorithm_applied")) for r in (getattr(self,"master_playlist_data",[]) or []) if isinstance(r,dict)):
            return state
        # R23r: Algorithm automation depth follows the XMOD master (Canonical Mixer)
        # identically for every instrument; no single-current-instrument factor.
        depth=float(np.clip(float((getattr(self,"global_mod_state",{}) or {}).get("xmod",1.0)),0.0,2.0))
        amount=float(np.clip((gas.get("params") or {}).get("mix",0.35),0.0,1.0))*depth
        phase=0.5
        try: phase=float(point.get("morph",point.get("value",0.5))) if isinstance(point,dict) else 0.5
        except Exception: pass
        factor=1.0 + (phase-0.5)*2.0*MEUM_MINUS_1*amount
        # FULL_GRAPH_SCRIPT_CONTEXT_2026: when Algorithm Script is applied,
        # evaluate it at the same graph coordinate used by audio/video/game.
        # This augments the old morph-only factor without creating notes or
        # automation points. Scalar/wave/drive outputs become bounded XMOD.
        try:
            _cl = gas.get("_contenders") or ([("global", str(gas.get("script") or ""), amount)] if str(gas.get("script") or "").strip() else [])
            _terms = []
            for _src, _algo_script, _cmix in _cl:
                _gres = _evaluate_app_graph_script(
                    self, _algo_script, t_value=phase, t_norm=phase,
                    slot=0, row=int(point.get("row", 0) if isinstance(point, dict) else 0),
                    sequence=int(point.get("ref_sequence", 1) if isinstance(point, dict) else 1),
                    step=int(point.get("step", 0) if isinstance(point, dict) else 0),
                    name=str(instrument_name), function_names=("global_script", "evaluate_wave", "evaluate", "main"),
                )
                _drv = float(_gres.get("scalar", _gres.get("wave", _gres.get("drive", 0.0))) or 0.0)
                _terms.append(math.tanh(_drv))
            if _terms:
                factor *= 1.0 + 0.25 * (sum(_terms) / len(_terms)) * amount
        except Exception:
            pass
        out=copy.deepcopy(state)
        _drv={k:self._global_algo_kind_drive(k,instrument_name,phase,point) for k in GLOBAL_ALGO_EXTRA_KINDS}
        # Mod Algo widens/narrows how far the base factor departs from unity.
        factor = 1.0 + (factor-1.0)*(1.0+0.5*_drv["mod"])
        _bucket_factor={"synth":factor*(1.0+0.25*_drv["synth"]),"sequence":factor*(1.0+0.25*_drv["sequencer"])}
        for bucket in ("synth","sequence"):
            obj=out.get(bucket)
            if not isinstance(obj,dict): continue
            _f=_bucket_factor[bucket]
            for key,val in list(obj.items()):
                if isinstance(val,(int,float,np.number)) and not isinstance(val,bool):
                    obj[key]=float(val)*_f
                elif isinstance(val,list):
                    obj[key]=[float(x)*_f if isinstance(x,(int,float,np.number)) and not isinstance(x,bool) else x for x in val]
        # Geometric Algo scales the continuous values of the four geometric instances.
        _gf=1.0+0.25*_drv["geometric"]
        _geo=(out.get("synth") or {}).get("geo") if isinstance(out.get("synth"),dict) else None
        if isinstance(_geo,dict) and _gf!=1.0:
            for _lane,_keys in (("vector",("x","y","z","drive")),("wavetable",("phase","curvature","twist","fold")),("ball",("gravity","radius","vx","vy"))):
                _d=_geo.get(_lane)
                if isinstance(_d,dict):
                    for _kk in _keys:
                        if isinstance(_d.get(_kk),float): _d[_kk]=_d[_kk]*_gf
        out["algorithm_kind_drives"] = {k:round(v,6) for k,v in _drv.items() if v}
        out["algorithm_xmod_applied"] = amount
        return out

    def _global_algo_kind_drive(self, kind, instrument_name, phase, point=None):
        """GROOVEBOX_GLOBAL_ALGO_KINDS_20261102: bounded -1..1 drive of one extra Global Play algo.

        0.0 whenever the patcher is not applied, the kind is disabled or its amount is 0, so a
        default project is bit-identical to before. Reads user-owned global_algo_state only.
        """
        try:
            gas = getattr(self, "global_algo_state", None) or {}
            if not isinstance(gas, dict) or not bool(gas.get("apply_enabled", False)):
                return 0.0
            params = gas.get("params") if isinstance(gas.get("params"), dict) else {}
            if not bool(params.get("enable_" + kind, True)):
                return 0.0
            body = str(gas.get(kind) or "")
            amount = float(np.clip(params.get(kind + "_amount", 1.0), 0.0, 1.0))
            if amount <= 0.0 or not body.strip():
                return 0.0
            res = _evaluate_app_graph_script(
                self, body, t_value=phase, t_norm=phase, slot=0,
                row=int(point.get("row", 0) if isinstance(point, dict) else 0),
                sequence=int(point.get("ref_sequence", 1) if isinstance(point, dict) else 1),
                step=int(point.get("step", 0) if isinstance(point, dict) else 0),
                name=str(instrument_name), function_names=("global_script", f"global_{kind}", "evaluate_wave", "evaluate", "main"))
            raw = float(res.get("scalar", res.get("wave", res.get("drive", 0.0))) or 0.0)
            if not math.isfinite(raw):
                return 0.0
            mix = float(np.clip(params.get("mix", 0.35), 0.0, 1.0))
            return float(math.tanh(raw)) * amount * (0.5 + 0.5 * mix)
        except Exception:
            return 0.0

    def _automation_lane_points(self, instrument_name, row_idx):
        mem = self._current_sequence_mem(instrument_name)
        lane = mem.get("automation_lane", []) if isinstance(mem, dict) else []
        out = []
        if isinstance(lane, list):
            for p in lane:
                if not isinstance(p, dict):
                    continue
                prow = int(p.get("playlist_row", 0) or 0)
                if prow in (0, int(row_idx) + 1):
                    out.append(p)
        return out

    def _get_sequencer_automation_for_step(self, row_idx, step_idx, instrument_name, composition_mem):
        """Linear longitudinal automation: lane controls are interpolated between steps."""
        if self._row_write_mode(row_idx) in ("step", "identity"):
            return None        # this row writes steps (or identity) only — no automation
        candidates = []
        candidates.extend(self._automation_lane_points(instrument_name, row_idx))
        for point in getattr(self, "sequencer_automation_points", []) or []:
            if isinstance(point, dict) and not bool(point.get("enabled", True)):
                continue
            if isinstance(point, dict) and self._automation_point_matches(point, row_idx, step_idx, instrument_name):
                candidates.append(point)
            elif isinstance(point, dict):
                target = str(point.get("instrument", "__all__") or "__all__")
                prow = int(point.get("playlist_row", 0) or 0)
                src = str(point.get("from_instrument") or point.get("instrument") or "")
                if (target in ("__all__", "", str(instrument_name)) or src in ("", str(instrument_name))) and prow in (0, int(row_idx) + 1):
                    candidates.append(point)
        # Fallback: canonical runtime overlay automation (when points/lane empty)
        if not candidates:
            try:
                ov = (getattr(self, "canonical_runtime_overlays", {}) or {}).get(f"{instrument_name}:{int(row_idx)}")
                auto = ov.get("automation") if isinstance(ov, dict) else None
                if isinstance(auto, list) and auto:
                    for i, av in enumerate(auto):
                        if not isinstance(av, dict):
                            continue
                        candidates.append({
                            "step": int(av.get("step", i + 1) or (i + 1)),
                            "value": float(av.get("value", 0.5) or 0.5),
                            "morph": float(av.get("value", 0.5) or 0.5),
                            "enabled": True,
                            "instrument": str(instrument_name),
                            "from_instrument": str(instrument_name),
                            "to_instrument": str(instrument_name),
                            "from_sequence": 1,
                            "to_sequence": 1,
                            "playlist_row": int(row_idx) + 1,
                            "canonical_owner": "canonical:coverage",
                            "composition_blend": 0.5,
                            "step_offset": 0,
                        })
            except Exception:
                pass
        if not candidates:
            return None

        # Deduplicate by step, preferring sequence-owned painted lane points.
        by_step = {}
        for p in candidates:
            try:
                ps = max(1, int(p.get("step", 1) or 1))
            except Exception:
                ps = 1
            if ps not in by_step or p in self._automation_lane_points(instrument_name, row_idx):
                by_step[ps] = p
        controls = sorted(by_step.items(), key=lambda kv: kv[0])
        if not controls:
            return None

        auto_len = max(1, int(getattr(self, "spin_auto_point_length", None).value() if hasattr(self, "spin_auto_point_length") else max(k for k, _ in controls)))
        # The Automator follows the Sequencer clock. When lengths differ, its own
        # lane cycles modulo its length, giving deliberate syncopation instead of
        # falling off after the last automation point.
        target_step = (int(step_idx) % auto_len) + 1
        if len(controls) == 1:
            return self._algorithm_modulate_resolved_automation(self._automation_resolved_state(controls[0][1], instrument_name, composition_mem), instrument_name, controls[0][1])
        if target_step <= controls[0][0]:
            return self._algorithm_modulate_resolved_automation(self._automation_resolved_state(controls[0][1], instrument_name, composition_mem), instrument_name, controls[0][1])
        if target_step >= controls[-1][0]:
            return self._algorithm_modulate_resolved_automation(self._automation_resolved_state(controls[-1][1], instrument_name, composition_mem), instrument_name, controls[-1][1])

        lo = controls[0]
        hi = controls[-1]
        for idx in range(len(controls) - 1):
            if controls[idx][0] <= target_step <= controls[idx + 1][0]:
                lo, hi = controls[idx], controls[idx + 1]
                break
        span = max(1, hi[0] - lo[0])
        frac = float(np.clip((target_step - lo[0]) / span, 0.0, 1.0))
        # ENV-follow modifies longitudinal automation while keeping the control domain
        # strictly 0..1 row.  The underlying travel remains linear: attack/release
        # create endpoint holds, while the centered slope can change by at most ±50%.
        try:
            a_env = float(np.clip(float(composition_mem.get("sequence_envelope_attack", 0.5) or 0.0), 0.0, 1.0))
            r_env = float(np.clip(float(composition_mem.get("sequence_envelope_release", 0.5) or 0.0), 0.0, 1.0))
            p_att = float(np.clip(float(composition_mem.get("attack", composition_mem.get("envelope_attack", 0.0)) or 0.0), 0.0, 1.0))
            p_rel = float(np.clip(float(composition_mem.get("decay", composition_mem.get("envelope_decay", 0.0)) or 0.0), 0.0, 1.0))
            # Sequence-wide ENV follow is mixed with the selected pattern envelope.
            env_a = 0.5 * (a_env + p_att)
            env_r = 0.5 * (r_env + p_rel)
            # 0.5 is neutral. Each control can therefore move slope/time by ±50%.
            slope_scale = 0.5 + env_a
            hold_start = 0.25 * env_a
            hold_end = 0.25 * env_r
            active_span = 1.0 - hold_start - hold_end
            if active_span == 0.0:
                f = 0.0
            else:
                f = (frac - hold_start) / active_span
            f = float(np.clip(f, 0.0, 1.0))
            # Linear around the midpoint; preserve exact endpoints and never leave 0..1.
            frac = float(np.clip(0.5 + (f - 0.5) * slope_scale, 0.0, 1.0))
        except Exception:
            pass
        A = self._automation_resolved_state(lo[1], instrument_name, composition_mem)
        B = self._automation_resolved_state(hi[1], instrument_name, composition_mem)
        resolved_sequence = self._automation_morph_sequence(A["sequence"], B["sequence"], frac, composition_mem)
        # Direct per-note timing/step offset. This is intentionally additive and
        # does not replace the canonical sequence offset lane.
        try:
            point_offset = float(lo[1].get("step_offset", 0) or 0)
            offsets = list(resolved_sequence.get("offsets", []) or [])
            idx = max(0, int(target_step) - 1)
            if offsets:
                if idx >= len(offsets):
                    offsets.extend([0] * (idx + 1 - len(offsets)))
                offsets[idx] = float(offsets[idx]) + point_offset
                resolved_sequence["offsets"] = offsets
        except Exception:
            pass
        return self._algorithm_modulate_resolved_automation({
            "sequence": resolved_sequence,
            "synth": self._automation_lerp_dict(A["synth"], B["synth"], frac),
            "point": lo[1],
            "linear_fraction": frac,
        }, instrument_name, lo[1])

    def _on_automator_timing_mode_changed(self, index):
        self.automator_timing_mode = "syncopate" if int(index) == 1 else "wrap"
        if hasattr(self, "chk_auto_sync_sequencer"):
            self.chk_auto_sync_sequencer.blockSignals(True)
            self.chk_auto_sync_sequencer.setChecked(self.automator_timing_mode == "wrap")
            self.chk_auto_sync_sequencer.blockSignals(False)
        try: self._on_auto_sync_toggled(self.automator_timing_mode == "wrap")
        except Exception: pass
        try: self._on_live_source_changed()
        except Exception: pass

    def _on_auto_syncopate_changed(self, _value):
        if not hasattr(self, "chk_auto_sync_sequencer") or not self.chk_auto_sync_sequencer.isChecked():
            return
        try:
            seq_n = max(1, int(self._current_sequence_mem().get("pattern_length", self.spin_seq_length.value())))
            n = max(1, min(STRUCT_MAX_STEPS, seq_n + int(self.spin_auto_syncopate.value())))
            self.spin_auto_point_length.blockSignals(True)
            self.spin_auto_point_length.setValue(n)
            self.spin_auto_point_length.blockSignals(False)
            self.spin_auto_point_step.setRange(1, n)
            self.spin_auto_point_step.setValue(min(max(1, self.spin_auto_point_step.value()), n))
            self._refresh_sequencer_automation_row()
        except Exception:
            pass

    def _on_automation_length_changed(self, value):
        n = max(1, min(STRUCT_MAX_STEPS, int(value)))
        if hasattr(self, "spin_auto_point_step"):
            self.spin_auto_point_step.setRange(1, n)
            self.spin_auto_point_step.setValue(min(max(1, self.spin_auto_point_step.value()), n))
        self._refresh_sequencer_automation_row()

    def _on_auto_sync_toggled(self, checked):
        """Optionally lock Automator length to the active Sequencer; OFF permits polymetric/syncopated lengths."""
        if hasattr(self, "spin_auto_point_length"):
            self.spin_auto_point_length.blockSignals(True)
            self.spin_auto_point_length.setRange(1, STRUCT_MAX_STEPS)
            if checked:
                try:
                    seq_n = int(self._current_sequence_mem().get("pattern_length", self.spin_seq_length.value()))
                except Exception:
                    seq_n = int(self.spin_seq_length.value()) if hasattr(self, "spin_seq_length") else DEFAULT_SEQUENCE_LENGTH
                delta = int(self.spin_auto_syncopate.value()) if hasattr(self, "spin_auto_syncopate") else 0
                self.spin_auto_point_length.setValue(max(1, min(STRUCT_MAX_STEPS, seq_n + delta)))
            self.spin_auto_point_length.blockSignals(False)
        self._refresh_sequencer_automation_row()

    def _automation_point_for_step(self, step, instrument_name=None, sequence_id=None):
        """Find an automation reference in the active instrument/sequence scope.

        Automation is allowed to contain the same step number for many source
        tracks, so step alone is never a unique key.
        """
        step = int(step)
        inst = str(instrument_name if instrument_name is not None else getattr(self, "_selected_automation_source_instrument", None) or (self.instrument_selector_dropdown.currentText() if hasattr(self, "instrument_selector_dropdown") else (self.auto_to_instrument.currentText() if hasattr(self, "auto_to_instrument") else "")))
        sid = int(sequence_id if sequence_id is not None else getattr(self, "_selected_automation_source_sequence", None) or (self.sequence_selector.currentData() if hasattr(self, "sequence_selector") and self.sequence_selector.currentData() is not None else (self.spin_auto_to_sequence.value() if hasattr(self, "spin_auto_to_sequence") else 1)))
        fallback = None
        for p in getattr(self, "sequencer_automation_points", []) or []:
            if not isinstance(p, dict) or int(p.get("step", 0) or 0) != step:
                continue
            p_inst = str(p.get("from_instrument") or p.get("instrument") or "")
            p_sid = int(p.get("from_sequence", 1) or 1)
            if p_inst == inst and p_sid == sid:
                return p
        # Never let a destination Operator/Sequence change select a point from
        # another source track. This is the key source-scope invariant for the
        # two-click Automator teleport editor.
        return None

    def _teleport_to_sequencer_automation_point(self, point, reposition=True):
        if not isinstance(point, dict):
            return
        step = int(point.get("step", 1) or 1)
        if hasattr(self, "spin_auto_point_step"):
            self.spin_auto_point_step.blockSignals(True)
            self.spin_auto_point_step.setValue(step)
            self.spin_auto_point_step.blockSignals(False)
        inst = str(point.get("to_instrument") or point.get("from_instrument") or point.get("instrument") or "")
        if inst and hasattr(self, "auto_to_instrument"):
            idx = self.auto_to_instrument.findText(inst)
            if idx >= 0:
                self.auto_to_instrument.blockSignals(True)
                self.auto_to_instrument.setCurrentIndex(idx)
                self.auto_to_instrument.blockSignals(False)
        sid = int(point.get("to_sequence", point.get("from_sequence", 1)) or 1)
        if hasattr(self, "spin_auto_to_sequence"):
            pass
        if hasattr(self, "spin_auto_to_sequence"):
            self.spin_auto_to_sequence.blockSignals(True)
            self.spin_auto_to_sequence.setValue(max(1, min(STRUCT_MAX_VOICES, sid)))
            self.spin_auto_to_sequence.blockSignals(False)
        if hasattr(self, "spin_auto_offset"):
            self.spin_auto_offset.blockSignals(True)
            self.spin_auto_offset.setValue(int(point.get("step_offset", 0) or 0))
            self.spin_auto_offset.blockSignals(False)
        if hasattr(self, "spin_auto_mod_amount"):
            self.spin_auto_mod_amount.blockSignals(True); self.spin_auto_mod_amount.setValue(float(point.get("mod_amount_pct",0.0) or 0.0)); self.spin_auto_mod_amount.blockSignals(False)
        if hasattr(self, "combo_auto_mod_target"):
            self.combo_auto_mod_target.blockSignals(True); self.combo_auto_mod_target.setCurrentText(str(point.get("mod_target","None") or "None")); self.combo_auto_mod_target.blockSignals(False)
        # TELEPORT CONTRACT: an Automator point carries its Operator + Sequence
        # destination into the main Sequencer context as well. Offset remains the
        # Automator's integer step displacement and is not reinterpreted as the
        # main Sequencer's normalized timing-offset control.
        try:
            if inst and hasattr(self, "instrument_selector_dropdown"):
                idx_i = self.instrument_selector_dropdown.findText(inst)
                if idx_i >= 0 and self.instrument_selector_dropdown.currentIndex() != idx_i:
                    self.instrument_selector_dropdown.blockSignals(True)
                    self.instrument_selector_dropdown.setCurrentIndex(idx_i)
                    self.instrument_selector_dropdown.blockSignals(False)
                # Explicitly run the same context-load path even when the destination
                # is already the active instrument; teleport must still refresh its
                # sequence/program state rather than becoming a visual-only selection.
                if inst and hasattr(self, "instrument_selector_dropdown"):
                    self.on_instrument_switched(idx_i)
            if hasattr(self, "sequence_selector"):
                target_bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(inst, {})
                if sid in target_bank:
                    pos = self.sequence_selector.findData(sid)
                    if pos >= 0 and self.sequence_selector.currentIndex() != pos:
                        self.sequence_selector.blockSignals(True)
                        self.sequence_selector.setCurrentIndex(pos)
                        self.sequence_selector.blockSignals(False)
                        self.instrument_selected_sequence[inst] = sid
                        self.instrument_sequencer_memory[inst] = target_bank[sid]
                    self._load_sequence_envelope_controls(target_bank.get(sid, {}))
                    self.rebuild_sequencer_steps(int(target_bank[sid].get("pattern_length", DEFAULT_SEQUENCE_LENGTH)))
        except Exception:
            pass
        if hasattr(self, "lbl_automator_teleport"):
            off = int(point.get("step_offset", 0) or 0)
            self.lbl_automator_teleport.setText(
                f"AUTO {step}  ·  {inst[:14] or 'Operator'}  ·  Seq {sid}  ·  Offset {off:+d}"
            )
        self._refresh_sequencer_automation_row()
        self._load_automator_popup(point)
        # Teleport changes instrument/sequence context; chord count must follow it,
        # not remain bound to the previous step's visible value.
        try:
            self._sync_chord_note_count_controls(self._current_sequence_mem(self._current_instrument_name()))
        except Exception:
            pass
        if reposition:
            self._position_automator_teleport_popup(step)

    def _toggle_sequencer_automation_step(self, step):
        """Sequencer-style interaction: first click selects; second click toggles ON/OFF."""
        step = int(step)
        same_step = getattr(self, "_selected_automation_step", None) == step
        if getattr(self, "_selected_automation_step", None) != step:
            self._selected_automation_source_instrument = str(self.instrument_selector_dropdown.currentText()) if hasattr(self, "instrument_selector_dropdown") else str(self.auto_to_instrument.currentText())
            self._selected_automation_source_sequence = int(self.sequence_selector.currentData() or 1) if hasattr(self, "sequence_selector") and self.sequence_selector.currentData() is not None else int(self.spin_auto_to_sequence.value())
        if getattr(self, "_selected_automation_step", None) != step:
            self._automator_popup_anchor = None
            self._automator_popup_anchor_step = None
        self._selected_automation_step = step
        point = self._automation_point_for_step(step)
        if point is None:
            # SOURCE scope = active sequencer instrument/sequence (matches row filter).
            # DESTINATION = Automator Operator/Sequence selectors.
            _src_inst = str(self.instrument_selector_dropdown.currentText()) if hasattr(self, "instrument_selector_dropdown") else (
                str(self.auto_to_instrument.currentText()) if hasattr(self, "auto_to_instrument") else ""
            )
            _src_sid = int(self.sequence_selector.currentData() or 1) if hasattr(self, "sequence_selector") and self.sequence_selector.currentData() is not None else (
                int(self.spin_auto_to_sequence.value()) if hasattr(self, "spin_auto_to_sequence") else 1
            )
            _dst_inst = (
                _src_inst if self._is_local_context() else
                (str(self.auto_to_instrument.currentText()) if hasattr(self, "auto_to_instrument") else _src_inst)
            )
            _dst_sid = int(self.spin_auto_to_sequence.value()) if hasattr(self, "spin_auto_to_sequence") else _src_sid
            point = {
                "step": step,
                "from_instrument": _src_inst,
                "from_sequence": _src_sid,
                "to_instrument": _dst_inst,
                "to_sequence": _dst_sid,
                "instrument": _src_inst,
                "morph": 1.0,
                "step_offset": 0,
                "playlist_row": 0,
                "composition_blend": 0.5,
                "canonical_owner": "user:sequencer_automation",
                "length": int(self.spin_auto_point_length.value()) if hasattr(self, "spin_auto_point_length") else 16,
                "reference_offsets": {},
                "enabled": False,
                "mod_amount_pct": 0.0,
                "mod_target": "None",
            }
            self.sequencer_automation_points.append(point)
        self._teleport_to_sequencer_automation_point(point)
        if same_step:
            point["enabled"] = not bool(point.get("enabled", True))
            if point["enabled"]:
                # SOURCE = the active sequencer instrument/sequence.
                # DESTINATION = the visible automation Operator/Sequence selectors.
                # Never collapse a randomized reference back onto its source.
                point.setdefault("from_instrument", str(self.instrument_selector_dropdown.currentText()) if hasattr(self, "instrument_selector_dropdown") else str(self.auto_to_instrument.currentText()))
                point.setdefault("from_sequence", int(self.sequence_selector.currentData() or 1) if hasattr(self, "sequence_selector") else int(self.spin_auto_to_sequence.value()))
                point["to_instrument"] = str(self.auto_to_instrument.currentText())
                point["to_sequence"] = int(self.spin_auto_to_sequence.value())
                point["instrument"] = str(self.auto_to_instrument.currentText())
                point["step_offset"] = int(self.spin_auto_offset.value())
            self._canonical_write_sequencer_automation_state()
        self._refresh_sequencer_automation_row()

    def _update_selected_sequencer_automation(self, _value=None):
        step = getattr(self, "_selected_automation_step", None)
        if step is None:
            return
        point = self._automation_point_for_step(step)
        if point is None:
            return
        inst = str(self.auto_to_instrument.currentText())
        sid = int(self.spin_auto_to_sequence.value())
        # The automation editor's Operator/Sequence controls are reference
        # DESTINATION controls. Source identity remains attached to the point,
        # which is essential for per-instrument/per-sequence randomization.
        point.update({
            "to_instrument": inst, "instrument": inst,
            "to_sequence": sid,
            "step_offset": int(self.spin_auto_offset.value()),
            "length": int(self.spin_auto_point_length.value()),
            "mod_amount_pct": float(self.spin_auto_mod_amount.value()) if hasattr(self,"spin_auto_mod_amount") else float(point.get("mod_amount_pct",0.0) or 0.0),
            "mod_target": str(self.combo_auto_mod_target.currentText()) if hasattr(self,"combo_auto_mod_target") else str(point.get("mod_target","None")),
        })
        if not point.get("from_instrument"):
            point["from_instrument"] = str(self.instrument_selector_dropdown.currentText()) if hasattr(self, "instrument_selector_dropdown") else inst
        if not point.get("from_sequence"):
            point["from_sequence"] = int(self.sequence_selector.currentData() or 1) if hasattr(self, "sequence_selector") else 1
        self._canonical_write_sequencer_automation_state()
        self._refresh_sequencer_automation_row()

    def _bake_automation_pattern_to_tiles(self, points, pattern_name="", activate=True, instrument_name=None, sequence_id=None):
        """Write a named automation curve into Automator tiles and refresh the strip.

        points: sequence of 0–100 values (one per step). Each step becomes an
        enabled sequencer_automation_points entry in the active instrument scope
        so tiles light ON and carry morph/value data for playback.
        """
        try:
            pts = [float(x) for x in (points or [])]
        except Exception:
            pts = []
        if not pts:
            return
        try:
            name = str(
                instrument_name
                if instrument_name is not None
                else (
                    self.instrument_selector_dropdown.currentText()
                    if hasattr(self, "instrument_selector_dropdown")
                    else (getattr(self, "instrument_names_48", ["Operator"]) or ["Operator"])[0]
                )
            )
        except Exception:
            name = "Operator"
        try:
            if sequence_id is not None:
                sid = int(sequence_id)
            elif hasattr(self, "sequence_selector") and self.sequence_selector.currentData() is not None:
                sid = int(self.sequence_selector.currentData())
            else:
                sid = int(self._current_sequence_index(name)) if hasattr(self, "_current_sequence_index") else 1
        except Exception:
            sid = 1
        n = max(1, min(STRUCT_MAX_STEPS, len(pts)))
        if hasattr(self, "spin_auto_point_length"):
            try:
                self.spin_auto_point_length.blockSignals(True)
                self.spin_auto_point_length.setValue(n)
                self.spin_auto_point_length.blockSignals(False)
                if hasattr(self, "spin_auto_point_step"):
                    self.spin_auto_point_step.setRange(1, n)
            except Exception:
                pass
        existing = list(getattr(self, "sequencer_automation_points", []) or [])
        kept = []
        for p in existing:
            if not isinstance(p, dict):
                continue
            p_inst = str(p.get("from_instrument") or p.get("instrument") or "")
            p_sid = int(p.get("from_sequence", 1) or 1)
            owner = str(p.get("canonical_owner") or "")
            # Replace prior pattern/canonical tiles for this scope; keep user-owned.
            if p_inst == name and p_sid == sid and not owner.startswith("user:"):
                continue
            kept.append(p)
        for i, val in enumerate(pts):
            step = i + 1
            try:
                v = float(val)
            except Exception:
                v = 50.0
            if not math.isfinite(v):
                v = 50.0
            morph = float(np.clip(v / 100.0, 0.0, 1.0))
            kept.append({
                "step": step,
                "from_instrument": name,
                "from_sequence": int(sid),
                "to_instrument": name,
                "to_sequence": int(sid),
                "instrument": name,
                "morph": morph,
                "value": morph,
                "step_offset": 0,
                "playlist_row": 0,
                "composition_blend": 0.5,
                "canonical_owner": ("pattern:%s" % pattern_name) if pattern_name else "pattern:written",
                "pattern_name": str(pattern_name or ""),
                "length": n,
                "reference_offsets": {},
                "enabled": bool(activate),
                "synth_param": "morph",
            })
        self.sequencer_automation_points = kept
        try:
            banks = getattr(self, "instrument_sequence_banks", {}) or {}
            bank = banks.setdefault(name, {})
            mem = bank.get(int(sid))
            if not isinstance(mem, dict):
                mem = self._current_sequence_mem(name) if hasattr(self, "_current_sequence_mem") else {}
                bank[int(sid)] = mem
            mem["automation_lane"] = [
                {
                    "step": i + 1,
                    "value": float(np.clip(float(pts[i]) / 100.0, 0.0, 1.0)),
                    "morph": float(np.clip(float(pts[i]) / 100.0, 0.0, 1.0)),
                    "enabled": bool(activate),
                    "instrument": name,
                    "from_instrument": name,
                    "from_sequence": int(sid),
                    "to_instrument": name,
                    "to_sequence": int(sid),
                    "canonical_owner": ("pattern:%s" % pattern_name) if pattern_name else "pattern:written",
                    "pattern_name": str(pattern_name or ""),
                }
                for i in range(n)
            ]
            mem["automation_lane_length"] = n
        except Exception as _lane_exc:
            print("[Automation] lane bake failed: %s" % _lane_exc)
        try:
            if hasattr(self, "_canonical_write_sequencer_automation_state"):
                self._canonical_write_sequencer_automation_state()
        except Exception:
            pass
        try:
            if hasattr(self, "_refresh_sequencer_automation_row"):
                self._refresh_sequencer_automation_row()
        except Exception:
            pass
        try:
            if getattr(self, "scope_status_label", None) is not None:
                on_n = sum(1 for p in kept if isinstance(p, dict) and p.get("enabled") and str(p.get("from_instrument") or "") == name)
                self.scope_status_label.setText(
                    "Automation tiles · %s · %d/%d ON · %s / Q%d" % (pattern_name or "pattern", on_n, n, name, sid)
                )
        except Exception:
            pass

    def _canonical_write_sequencer_automation_state(self):
        try:
            self.sequencer_automation_points = sorted(
                [p for p in (getattr(self, "sequencer_automation_points", []) or []) if isinstance(p, dict)],
                key=lambda p: (str(p.get("from_instrument") or p.get("instrument") or ""), int(p.get("from_sequence", 1) or 1), int(p.get("step", 0) or 0))
            )
            # R31 RENDER_SPEED: unchanged automation → nothing to rewrite (this ran ~200× per rendered row,
            # deep-copying the whole automation list twice each time).
            try:
                _fp = _EQ_JSON.dumps(self.sequencer_automation_points, sort_keys=True, default=repr)
            except Exception:
                _fp = None
            if _fp is not None and _fp == getattr(self, "_caw_last_fp", None) \
                    and isinstance(getattr(self, "_canonical_composition_document", None), dict):
                return
            self._caw_last_fp = _fp
            # R31 RENDER_SPEED: readers only use this document's sequence-runtime / automation keys. A full
            # _project_snapshot() here ran several times per render and, on a project loaded from disk
            # (per-sequence panels), cost ~20× the render itself.
            _doc = getattr(self, "_canonical_composition_document", None)
            self._canonical_composition_document = _doc if isinstance(_doc, dict) else {}
            self._canonical_composition_document["sequencer_automation_points"] = copy.deepcopy(self.sequencer_automation_points)
            self._canonical_composition_document["canonical_automation_state"] = {
                "enabled": True,
                "points": copy.deepcopy(self.sequencer_automation_points),
                "canonical_composition_weight": 1.0,
                "imported_carrier_phase_lock": 0.5,
            }
            self._canonical_automation_revision = int(getattr(self, "_canonical_automation_revision", 0)) + 1
            try:
                self._schedule_ui_after_canonical_write("sequencer-automation")
            except Exception:
                pass
        except Exception:
            pass

    def _write_sequencer_automation_point(self):
        # Compatibility entry point for older callers. The visible UI now edits the
        # selected step directly and toggles it with a second click.
        step = int(self.spin_auto_point_step.value())
        self._selected_automation_step = step
        point = self._automation_point_for_step(step)
        if point is None:
            point = {"step": step, "enabled": True, "canonical_owner": "user:sequencer_automation"}
            self.sequencer_automation_points.append(point)
        point.update({
            "from_instrument": str(self.auto_to_instrument.currentText()),
            "to_instrument": str(self.auto_to_instrument.currentText()),
            "instrument": str(self.auto_to_instrument.currentText()),
            "from_sequence": int(self.spin_auto_to_sequence.value()),
            "to_sequence": int(self.spin_auto_to_sequence.value()),
            "step_offset": int(self.spin_auto_offset.value()),
            "length": int(self.spin_auto_point_length.value()),
            "enabled": True,
        })
        self._canonical_write_sequencer_automation_state()
        self._refresh_sequencer_automation_row()

    def _randomize_automation_in_sequence(self, checked=False):
        """Fill the selected sequence for the reversible randomizer toggle action."""
        if getattr(self, "_randomize_automation_guard", False):
            return
        self._randomize_automation_guard = True
        prior_undo = bool(getattr(self, "_undo_in_flight", False))
        try:
            if not prior_undo: self._push_undo("Randomize Automation + Sequence (Local)")
            self._undo_in_flight = True
            name = str(self.auto_to_instrument.currentText())
            sid = int(self.spin_auto_to_sequence.value())
            bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(name, {})
            n = max(1, min(STRUCT_MAX_STEPS, int(getattr(self, "spin_auto_point_length", None).value() if hasattr(self, "spin_auto_point_length") else ((bank.get(sid) or {}).get("pattern_length", DEFAULT_SEQUENCE_LENGTH)))))
            seed = _safe_int_seed(self.get_numeric_seed()) ^ int.from_bytes(hashlib.sha256(f"{name}:{sid}".encode()).digest()[:4], "little")
            rng = np.random.default_rng(seed)
            # Fill the selected sequence itself — not just the automation references.
            mem = bank.get(sid) if isinstance(bank, dict) else None
            if isinstance(mem, dict):
                self._ensure_seq_mem_length(mem, n)
                mem["pattern_length"] = n
                mem["steps"] = [bool(rng.random() > 0.50) for _ in range(n)]
                if not any(mem["steps"]):
                    mem["steps"][int(rng.integers(0, n))] = True
                mem["gates"] = [True] * n
                mem["amplitudes"] = [float(rng.uniform(0.35, 1.0)) for _ in range(n)]
                mem["pitches"] = [float(rng.uniform(0.75, 1.5)) for _ in range(n)]
                mem["probabilities"] = [int(rng.integers(45, 101)) for _ in range(n)]
                mem["offsets"] = [float(rng.uniform(-0.25, 0.25)) for _ in range(n)]
                mem["sequence_envelope_attack"] = float(rng.random())
                mem["sequence_envelope_release"] = float(rng.random())
                mem["attack"] = float(rng.random())
                mem["decay"] = float(rng.random())
                mem["automation_lane_length"] = n
                self.instrument_sequencer_memory[name] = mem
                self.instrument_selected_sequence[name] = sid
            # Local scope: keep the source instrument/sequence fixed, but randomize
            # the reference operator among the active roster and reference sequence
            # among that operator's available sequence bank.
            roster = list(getattr(self, "instrument_names_48", []) or [name])
            old = getattr(self, "sequencer_automation_points", []) or []
            self.sequencer_automation_points = [p for p in old if not (isinstance(p, dict) and str(p.get("from_instrument") or p.get("instrument") or "") == name and int(p.get("from_sequence", 1) or 1) == sid)]
            for step in range(1, n+1):
                if float(rng.random()) < 0.55:
                    ref_op = str(rng.choice(roster))
                    ref_bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(ref_op, {})
                    ref_sids = sorted([int(x) for x in ref_bank.keys()]) or [1]
                    ref_sid = int(rng.choice(ref_sids))
                    self.sequencer_automation_points.append({
                        "step": step, "from_instrument": name, "from_sequence": sid,
                        "to_instrument": ref_op, "to_sequence": ref_sid, "instrument": ref_op,
                        "morph": float(rng.uniform(0.35, 1.0)),
                        "step_offset": int(rng.integers(-8, 9)), "playlist_row": int(rng.integers(0, max(1, int(getattr(self, "spin_playlist_length", None).value() if hasattr(self, "spin_playlist_length") else DEFAULT_PLAYLIST_ROWS)))),
                        "composition_blend": float(rng.uniform(0.35, 0.75)), "canonical_owner": "user:sequencer_automation",
                        "length": n, "reference_offsets": {}, "enabled": True,
                    })
            self._canonical_write_sequencer_automation_state()
            self.reload_active_instrument_sequencer_ui()
            self._refresh_sequencer_automation_row()
            self._canonical_write_sequence_runtime(name, sid)
            # Toggle remains ON until the user retoggles OFF; OFF restores the
            # captured baseline through _randomizer_toggle_restore().
            if hasattr(self, "scope_status_label"): self.scope_status_label.setText(f"🎲 RAND LOCAL SEQ · {name} / Sequence {sid} filled")
        except Exception as exc:
            print(f"[Randomize Automation + Sequence Local] failed: {exc}")
        finally:
            self._undo_in_flight = prior_undo; self._randomize_automation_guard = False

    def _randomize_all_automation_everywhere(self, checked=False):
        """Randomize automation plus reference operator/sequence/offset globally."""
        if getattr(self, "_randomize_automation_guard", False): return
        self._randomize_automation_guard = True
        prior_undo = bool(getattr(self, "_undo_in_flight", False))
        try:
            if not prior_undo: self._push_undo("Randomize Automation + Sequence (Global)")
            self._undo_in_flight = True
            rng = np.random.default_rng(_safe_int_seed(self.get_numeric_seed()) ^ 0xA170A710)
            banks = getattr(self, "instrument_sequence_banks", {}) or {}
            roster = list(getattr(self, "instrument_names_48", []) or banks.keys())
            # This is a true all-sequence action: randomize every sequence payload,
            # not merely the Automator references.
            for name, bank in banks.items():
                for sid, mem in (bank or {}).items():
                    if not isinstance(mem, dict):
                        continue
                    n = max(1, min(STRUCT_MAX_STEPS, int(mem.get("pattern_length", DEFAULT_SEQUENCE_LENGTH) or DEFAULT_SEQUENCE_LENGTH)))
                    self._ensure_seq_mem_length(mem, n)
                    mem["pattern_length"] = n
                    mem["steps"] = [bool(rng.random() > 0.50) for _ in range(n)]
                    if not any(mem["steps"]):
                        mem["steps"][int(rng.integers(0, n))] = True
                    mem["gates"] = [True] * n
                    mem["amplitudes"] = [float(rng.uniform(0.35, 1.0)) for _ in range(n)]
                    mem["pitches"] = [float(rng.uniform(0.75, 1.5)) for _ in range(n)]
                    mem["probabilities"] = [int(rng.integers(45, 101)) for _ in range(n)]
                    mem["offsets"] = [float(rng.uniform(-0.25, 0.25)) for _ in range(n)]
                    mem["sequence_envelope_attack"] = float(rng.random())
                    mem["sequence_envelope_release"] = float(rng.random())
                    mem["attack"] = float(rng.random())
                    mem["decay"] = float(rng.random())
                    mem["automation_lane_length"] = n
            points = []
            for name, bank in banks.items():
                for sid, mem in (bank or {}).items():
                    if not isinstance(mem, dict): continue
                    sid = int(sid); n = max(1, min(STRUCT_MAX_STEPS, int(mem.get("pattern_length", DEFAULT_SEQUENCE_LENGTH) or DEFAULT_SEQUENCE_LENGTH)))
                    for step in range(1, n+1):
                        if float(rng.random()) < 0.55:
                            ref_op = str(rng.choice(roster)) if roster else str(name)
                            ref_bank = banks.get(ref_op, {}) or {}
                            ref_sids = sorted([int(x) for x in ref_bank.keys()]) or [1]
                            ref_sid = int(rng.choice(ref_sids))
                            points.append({
                                "step": step, "from_instrument": str(name), "from_sequence": sid,
                                "to_instrument": ref_op, "to_sequence": ref_sid, "instrument": ref_op,
                                "morph": float(rng.uniform(0.35, 1.0)), "step_offset": int(rng.integers(-8, 9)),
                                "playlist_row": int(rng.integers(0, max(1, int(getattr(self, "spin_playlist_length", None).value() if hasattr(self, "spin_playlist_length") else DEFAULT_PLAYLIST_ROWS)))),
                                "composition_blend": float(rng.uniform(0.35, 0.75)), "canonical_owner": "user:sequencer_automation",
                                "length": n, "reference_offsets": {}, "enabled": True,
                            })
            self.sequencer_automation_points = points
            for _name, _bank in banks.items():
                for _sid in sorted(_bank):
                    self._canonical_write_sequence_runtime(str(_name), int(_sid))
            self._canonical_write_sequencer_automation_state(); self.reload_active_instrument_sequencer_ui(); self._refresh_sequencer_automation_row()
            if hasattr(self, "scope_status_label"): self.scope_status_label.setText(f"🎲 RANDOMIZE ALL SEQ · sequences + {len(points)} automation references randomized")
        except Exception as exc:
            print(f"[Randomize Automation + Sequence Global] failed: {exc}")
        finally:
            self._undo_in_flight = prior_undo; self._randomize_automation_guard = False

    def _clear_sequencer_automation_points(self):
        self.sequencer_automation_points = []
        self._selected_automation_step = None
        self._selected_automation_source_instrument = None
        self._selected_automation_source_sequence = None
        self._automator_popup_anchor = None
        self._automator_popup_anchor_step = None
        self._canonical_write_sequencer_automation_state()
        self._refresh_sequencer_automation_row()

    def _load_automator_popup(self, point):
        if not isinstance(point, dict):
            return
        inst = str(point.get("to_instrument") or point.get("instrument") or point.get("from_instrument") or "")
        sid = int(point.get("to_sequence", point.get("from_sequence", 1)) or 1)
        morph = float(point.get("morph", 1.0) or 0.0)
        off = int(point.get("step_offset", 0) or 0)
        # Target sequence envelope is editable directly from the teleport menu.
        bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(inst, {})
        mem = bank.get(sid, {}) if isinstance(bank, dict) else {}
        att = float(mem.get("sequence_envelope_attack", 0.5) or 0.0) if isinstance(mem, dict) else 0.5
        rel = float(mem.get("sequence_envelope_release", 0.5) or 0.0) if isinstance(mem, dict) else 0.5
        synth = mem.get("panels", {}).get("synth", {}) if isinstance(mem, dict) and isinstance(mem.get("panels", {}), dict) else {}
        if not isinstance(synth, dict) or not synth:
            synth = (getattr(self, "instrument_param_state", {}) or {}).get(inst, {}) or {}
        numeric_params = [str(k) for k,v in synth.items() if isinstance(v, (int,float,np.number)) and not isinstance(v,bool)]
        # Automator sequence can route the full canonical command surface:
        # Master Vector, Wavetable Projector, XMOD windows, Algo XMOD, Resonance.
        for extra in (
            "master_vector_x", "master_vector_y", "master_vector_z", "master_vector_drive",
            "wavetable_frame", "wavetable_phase", "wavetable_curvature", "wavetable_twist", "wavetable_fold",
            "global_xmod", "global_input_xmod", "algorithm_xmod_local", "algorithm_xmod_global",
            "canonical_resonance", "synth_panel_mod", "patch_mod", "script_mod", "domain_mod", "morph",
        ):
            if extra not in numeric_params:
                numeric_params.append(extra)
        if hasattr(self, "popup_auto_param"):
            self.popup_auto_param.blockSignals(True); self.popup_auto_param.clear(); self.popup_auto_param.addItems(numeric_params or ["morph"]); self.popup_auto_param.blockSignals(False)
            chosen = str(point.get("synth_param", numeric_params[0] if numeric_params else "morph"))
            pos = self.popup_auto_param.findText(chosen)
            if pos < 0 and numeric_params:
                pos = 0
            if pos >= 0:
                self.popup_auto_param.setCurrentIndex(pos)
            key = self.popup_auto_param.currentText()
            try: self.popup_auto_param_value.setValue(float(synth.get(key, 0.0)))
            except Exception: self.popup_auto_param_value.setValue(0.0)
        for w in (getattr(self, "popup_auto_operator", None), getattr(self, "popup_auto_sequence", None),
                  getattr(self, "popup_auto_morph", None), getattr(self, "popup_auto_attack", None),
                  getattr(self, "popup_auto_release", None), getattr(self, "popup_auto_offset", None), getattr(self, "popup_auto_param", None), getattr(self, "popup_auto_param_value", None)):
            if w is not None: w.blockSignals(True)
        try:
            if self.popup_auto_operator is not None:
                idx = self.popup_auto_operator.findText(inst)
                if idx >= 0: self.popup_auto_operator.setCurrentIndex(idx)
            self.popup_auto_sequence.setValue(max(1, min(STRUCT_MAX_VOICES, sid)))
            self.popup_auto_morph.setValue(max(0, min(100, int(round(morph*100))))); self.lbl_popup_auto_morph.setText(f"{int(round(morph*100))}%")
            self.popup_auto_attack.setValue(max(0, min(100, int(round(att*100)))))
            self.popup_auto_release.setValue(max(0, min(100, int(round(rel*100)))))
            self.popup_auto_offset.setValue(max(-1024, min(1024, off)))
        finally:
            for w in (getattr(self, "popup_auto_operator", None), getattr(self, "popup_auto_sequence", None),
                      getattr(self, "popup_auto_morph", None), getattr(self, "popup_auto_attack", None),
                      getattr(self, "popup_auto_release", None), getattr(self, "popup_auto_offset", None)):
                if w is not None: w.blockSignals(False)

    def _on_automator_popup_changed(self, _value=None):
        step = getattr(self, "_selected_automation_step", None)
        if step is None: return
        point = self._automation_point_for_step(step)
        if not isinstance(point, dict): return
        inst = str(self.popup_auto_operator.currentText())
        sid = int(self.popup_auto_sequence.value())
        point.update({
            "to_instrument": inst, "instrument": inst, "to_sequence": sid,
            "morph": float(self.popup_auto_morph.value())/100.0,
            "step_offset": int(self.popup_auto_offset.value()),
        })
        bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(inst, {})
        mem = bank.get(sid) if isinstance(bank, dict) else None
        if isinstance(mem, dict):
            mem["sequence_envelope_attack"] = float(self.popup_auto_attack.value())/100.0
            mem["sequence_envelope_release"] = float(self.popup_auto_release.value())/100.0
            # Morph target is the selected operator/sequence; synth-panel values are
            # resolved by _automation_resolved_state using this exact point.
        self._teleport_to_sequencer_automation_point(point, reposition=False)
        self._canonical_write_sequencer_automation_state()
        self._refresh_sequencer_automation_row()

    def _on_automator_popup_param_changed(self, _value=None):
        step = getattr(self, "_selected_automation_step", None)
        if step is None or not hasattr(self, "popup_auto_param"): return
        point = self._automation_point_for_step(step)
        if not isinstance(point, dict): return
        inst = str(self.popup_auto_operator.currentText())
        sid = int(self.popup_auto_sequence.value())
        key = str(self.popup_auto_param.currentText())
        point["synth_param"] = key
        bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(inst, {})
        mem = bank.get(sid) if isinstance(bank, dict) else None
        if isinstance(mem, dict):
            panels = mem.setdefault("panels", {})
            synth = panels.setdefault("synth", {})
            try:
                synth[key] = float(self.popup_auto_param_value.value())
            except Exception:
                pass
        self._canonical_write_sequencer_automation_state()
        self._refresh_sequencer_automation_row()

    def _position_automator_teleport_popup(self, step):
        """Anchor the Automator inspector once; horizontal scrolling never moves it."""
        popup = getattr(self, "automator_teleport_popup", None)
        scroll = getattr(self, "sequencer_automation_scroll", None)
        layout = getattr(self, "sequencer_automation_layout", None)
        if popup is None or scroll is None or layout is None:
            return
        try:
            # A top-level Tool window is deliberately anchored once per selection.
            # If another teleport popup is already visible, this one keeps its own
            # absolute screen coordinate instead of following either scrollbar.
            # Always resolve the current button. Rebuilds replace the button widgets,
            # so cached screen coordinates / anchors can point at a dead first-spawn target.
            idx = max(0, int(step) - 1)
            item = layout.itemAt(idx)
            btn = item.widget() if item is not None else None
            if btn is None:
                return
            popup.adjustSize()
            if popup.height() < 34:
                popup.setFixedHeight(34)
            host = self.top_sequencer
            cell_pos = btn.mapToGlobal(btn.rect().topLeft())
            pw = popup.width()
            ph = popup.height()
            x = cell_pos.x() + (btn.width() - pw) // 2
            screen = host.screen() or QApplication.primaryScreen()
            if screen is not None:
                area = screen.availableGeometry()
                x = max(area.left() + 4, min(x, area.right() - pw - 4))
                # AUTOMATOR_TELEPORT: the popup midpoint sits on the lower
                # cell boundary. It therefore remains visually anchored to the
                # selected cell instead of drifting above the strip.
                y = cell_pos.y() + btn.height() - (ph // 2)
                y = max(area.top() + 4, min(y, area.bottom() - ph - 4))
            else:
                y = max(4, cell_pos.y() + btn.height() - (ph // 2))
            self._automator_popup_anchor = (int(x), int(y))
            self._automator_popup_anchor_step = int(step)
            popup.move(int(x), int(y))
            popup.show()
            popup.raise_()
        except Exception:
            pass

    def _refresh_sequencer_automation_row(self):
        layout = getattr(self, "sequencer_automation_layout", None)
        if layout is None:
            return
        while layout.count():
            item = layout.takeAt(0)
            if item.widget():
                _gb_discard_widget(item.widget())
        self._automator_popup_anchor = None
        self._automator_popup_anchor_step = None
        length = int(self.spin_auto_point_length.value()) if hasattr(self, "spin_auto_point_length") else 16
        points = getattr(self, "sequencer_automation_points", []) or []
        _ui_inst = str(self.instrument_selector_dropdown.currentText()) if hasattr(self, "instrument_selector_dropdown") else (str(self.auto_to_instrument.currentText()) if hasattr(self, "auto_to_instrument") else "")
        _ui_sid = int(self.sequence_selector.currentData() or 1) if hasattr(self, "sequence_selector") and self.sequence_selector.currentData() is not None else (int(self.spin_auto_to_sequence.value()) if hasattr(self, "spin_auto_to_sequence") else 1)
        scoped_points = [p for p in points if isinstance(p, dict) and str(p.get("from_instrument") or p.get("instrument") or "") == _ui_inst and int(p.get("from_sequence", 1) or 1) == _ui_sid]
        # Self-heal: Full Canonical with empty Automator scope materializes coverage
        # into live points so the strip is never a dead blank under canonical authority.
        if not scoped_points and str(getattr(self, "canonical_control_strategy", "Full Canonical")) != "Seeded Baseline":
            if not getattr(self, "_automator_materialize_guard", False):
                try:
                    self._automator_materialize_guard = True
                    if hasattr(self, "_materialize_canonical_coverage") and _ui_inst:
                        self._materialize_canonical_coverage(_ui_inst, 0)
                        points = getattr(self, "sequencer_automation_points", []) or []
                        scoped_points = [p for p in points if isinstance(p, dict) and str(p.get("from_instrument") or p.get("instrument") or "") == _ui_inst and int(p.get("from_sequence", 1) or 1) == _ui_sid]
                except Exception:
                    pass
                finally:
                    self._automator_materialize_guard = False
        by_step = {int(p.get("step", 1) or 1): p for p in scoped_points}
        selected = getattr(self, "_selected_automation_step", None)
        for step in range(1, max(1, length) + 1):
            point = by_step.get(step)
            enabled = bool(point and point.get("enabled", True))
            inst = str((point or {}).get("to_instrument") or (point or {}).get("instrument") or "")
            sid = int((point or {}).get("to_sequence", 1) or 1)
            off = int((point or {}).get("step_offset", 0) or 0)
            if point is None:
                label = f"AUTO {step}"
            else:
                label = f"A{step} · {inst[:7]} / Q{sid} · {off:+d}"
            btn = QPushButton(label)
            btn.setFixedHeight(58)
            btn.setMinimumWidth(72)
            btn.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
            btn.setToolTip(
                f"Automation step {step}: first click selects/teleports; second click toggles {'ON' if enabled else 'OFF'}. "
                "Edit Operator, Sequence, and Offset ± above."
            )
            if enabled:
                bg = "#8f3f2f"
                fg = "#ffe1cf"
                border = "#d76a4e"
            else:
                bg = "#2a1717"
                fg = "#8f625c"
                border = "#4b2926"
            if selected == step:
                border = "#f5d97d"
                border_w = 3
            else:
                border_w = 1
            btn.setStyleSheet(
                f"QPushButton {{ background:{bg}; color:{fg}; border:{border_w}px solid {border}; "
                "border-radius:4px; padding:2px 5px; font-weight:800; } "   # plain string: single brace (was '}}' = parse error)
                "QPushButton:hover { background:#b84f3a; color:#ffe1cf; }"
            )
            btn.clicked.connect(lambda checked=False, s=step: self._toggle_sequencer_automation_step(s))
            layout.addWidget(btn, 1)
        # Keep a minimum content width so a long automation lane scrolls instead of squeezing cells.
        # Arc mode manages its own geometry, so never force a huge minimum there.
        try:
            if not hasattr(self.sequencer_automation_widget, "arc_host"):
                self.sequencer_automation_widget.setMinimumWidth(max(0, int(length) * 96 + 8))
        except Exception:
            pass
        if selected is not None and 1 <= int(selected) <= max(1, length):
            point = self._automation_point_for_step(int(selected))
            if point is not None:
                inst = str(point.get("to_instrument") or point.get("instrument") or "")
                sid = int(point.get("to_sequence", 1) or 1)
                off = int(point.get("step_offset", 0) or 0)
                if hasattr(self, "lbl_automator_teleport"):
                    self.lbl_automator_teleport.setText(
                        f"AUTO {int(selected)}  ·  {inst[:14] or 'Operator'}  ·  Seq {sid}  ·  Offset {off:+d}"
                    )
                # Do not reposition here; the teleport menu is anchored once at selection.

    def _position_step_editor(self, s_idx):
        """Anchor the selected-step editor once in global screen coordinates.

        The editor is a top-level Tool window. It never follows the sequencer
        scrollbar after the explicit step selection.
        """
        popup = getattr(self, 'step_editor_popup', None)
        buttons = getattr(self, 'seq_step_buttons', [])
        scroll = getattr(self, 'steps_scroll', None)
        if popup is None or s_idx >= len(buttons) or scroll is None:
            return
        try:
            # Always resolve the current live step button. The sequencer rebuild
            # replaces these widgets, so a cached first-spawn anchor can become stale.
            btn = buttons[s_idx]
            popup.adjustSize()
            pw, ph = popup.width(), popup.height()
            cell = btn.mapToGlobal(btn.rect().topLeft())
            screen = btn.screen() or QApplication.primaryScreen()
            if screen is not None:
                area = screen.availableGeometry()
                x = cell.x() + (btn.width() - pw) // 2
                x = max(area.left() + 4, min(x, area.right() - pw - 4))
                y_above = cell.y() - ph - 7
                y_below = cell.y() + btn.height() + 7
                # Prefer above; fall below only when the above position would
                # leave the physical display. Clamp horizontally and vertically.
                y = y_above if y_above >= area.top() + 4 else y_below
                y = max(area.top() + 4, min(y, area.bottom() - ph - 4))
            else:
                x = max(4, cell.x() + (btn.width() - pw) // 2)
                y = max(4, cell.y() - ph - 7)
            self._step_popup_anchor = (int(x), int(y))
            self._step_popup_anchor_idx = int(s_idx)
            popup.move(int(x), int(y))
            popup.show()
            popup.raise_()
        except Exception:
            pass

    def _on_step_pad_clicked(self, s_idx):
        curr_i = self.instrument_selector_dropdown.currentText()
        mem = self._current_sequence_mem(curr_i) if hasattr(self, "_current_sequence_mem") else self.instrument_sequencer_memory[curr_i]
        self._ensure_seq_mem_length(mem, max(s_idx + 1, len(mem.get("steps", []))))

        # STEP SELECTION CONTRACT:
        #   first click on a different cell = SELECT ONLY; never touch gates.
        #   second click on that same selected cell = TOGGLE ONLY THAT CELL.
        # Randomizer/Phase-Locker are the only engines permitted to change other cells.
        same_step = (self.selected_step_idx == s_idx)
        if self.selected_step_idx != s_idx:
            self._step_popup_anchor = None
            self._step_popup_anchor_idx = None
        self.selected_step_idx = s_idx
        if same_step:
            self._adopt_canonical_for_edit(mem, curr_i)   # CANONICAL_SEQ_DISPLAY_20261102
            mem["steps"][s_idx] = not bool(mem["steps"][s_idx])
            # USER_TOUCHED_TRACKING: this is an actual manual click — the only
            # place besides the amp/pitch sliders where a human is editing the
            # grid — so mark the step touched. Presets/patches/randomizer output
            # loaded straight into memory never pass through here, so they are
            # correctly left untouched until a person edits them by hand.
            self._mark_step_touched(mem, s_idx)
            try: self._canonical_write_sequence_runtime(curr_i, self._current_sequence_index(curr_i))
            except Exception: pass
            try: self._refresh_canonical_fingerprint()
            except Exception: pass

        if hasattr(self, 'lbl_selected_step'):
            self.lbl_selected_step.setText(f"Step: {s_idx + 1}")
        view = self._sequence_display_mem(curr_i, mem)
        amp = float(view["amplitudes"][s_idx]) if s_idx < len(view.get("amplitudes", [])) else 1.0
        pitch = float(view["pitches"][s_idx]) if s_idx < len(view.get("pitches", [])) else 1.0
        if hasattr(self, 'slider_step_amp'):
            self.slider_step_amp.blockSignals(True)
            self.slider_step_amp.setValue(int(round(amp * 100)))
            self.slider_step_amp.blockSignals(False)
            self.lbl_step_amp.setText(f"{int(round(amp * 100))}%")
        if hasattr(self, 'slider_step_pitch'):
            self.slider_step_pitch.blockSignals(True)
            self.slider_step_pitch.setValue(int(round(pitch * 100)))
            self.slider_step_pitch.blockSignals(False)
            self.lbl_step_pitch.setText(f"{pitch:.2f}×")
        controls = view.get("step_controls", {}) if isinstance(view.get("step_controls", {}), dict) else {}
        phase_values = controls.get("phase_shift", view.get("phase_shift", []))
        phase_radians = float(phase_values[s_idx]) if isinstance(phase_values, list) and s_idx < len(phase_values) else 0.0
        phase_degrees = int(round(math.degrees(phase_radians)))
        if hasattr(self, 'slider_step_phase_shift'):
            self.slider_step_phase_shift.blockSignals(True)
            self.slider_step_phase_shift.setValue(max(-180, min(180, phase_degrees)))
            self.slider_step_phase_shift.blockSignals(False)
            self.lbl_step_phase_shift.setText(f"{phase_degrees}°")
        _eq_lane = controls.get("eq_gain_db", [])
        _eq_db = float(_eq_lane[s_idx]) if isinstance(_eq_lane, list) and s_idx < len(_eq_lane) else 0.0
        _sc_lane = controls.get("sidechain_depth", [])
        _sc_depth = float(_sc_lane[s_idx]) if isinstance(_sc_lane, list) and s_idx < len(_sc_lane) else 0.0
        for _slider_name, _label_name, _value, _scale, _label_text in (
            ("slider_step_eq_gain", "lbl_step_eq_gain", _eq_db, 10.0, f"{_eq_db:.1f}"),
            ("slider_step_sidechain", "lbl_step_sidechain", _sc_depth, 100.0, f"{_sc_depth*100:.0f}%"),
        ):
            _slider = getattr(self, _slider_name, None)
            if _slider is not None:
                _slider.blockSignals(True)
                _slider.setValue(int(round(_value * _scale)))
                _slider.blockSignals(False)
            _label = getattr(self, _label_name, None)
            if _label is not None: _label.setText(_label_text)
        for _wn, _ln, _dv in (("spin_step_eq_freq", "eq_frequency", 1000.0), ("spin_step_eq_q", "eq_q", 0.707)):
            _w = getattr(self, _wn, None)
            if _w is not None:
                _lv = controls.get(_ln, [])
                _w.blockSignals(True)
                _w.setValue(float(_lv[s_idx]) if isinstance(_lv, list) and s_idx < len(_lv) else _dv)
                _w.blockSignals(False)
        if hasattr(self, "slider_step_fx_probability"):
            _fl = controls.get("fx_probability", [])
            _fv = float(_fl[s_idx]) if isinstance(_fl, list) and s_idx < len(_fl) else 1.0
            self.slider_step_fx_probability.blockSignals(True)
            self.slider_step_fx_probability.setValue(int(round(max(0.0, min(1.0, _fv)) * 100)))
            self.slider_step_fx_probability.blockSignals(False)
            self.lbl_step_fx_probability.setText(f"{int(round(max(0.0, min(1.0, _fv)) * 100))}%")
        _prob_lane = controls.get("trigger_probability", [])
        _prob = float(_prob_lane[s_idx]) if isinstance(_prob_lane, list) and s_idx < len(_prob_lane) else (float(view.get("probabilities", [100] * len(view.get("steps", [])))[s_idx]) / 100.0 if s_idx < len(view.get("probabilities", [])) else 1.0)
        if hasattr(self, "slider_step_probability"):
            self.slider_step_probability.blockSignals(True)
            self.slider_step_probability.setValue(int(round(max(0.0,min(1.0,_prob))*100)))
            self.slider_step_probability.blockSignals(False)
            self.lbl_step_probability.setText(f"{int(round(max(0.0,min(1.0,_prob))*100))}%")
        offset = float(mem.get("offsets", [0.0] * len(mem.get("steps", [])))[s_idx]) if s_idx < len(mem.get("offsets", [])) else 0.0
        if hasattr(self, 'spin_step_offset'):
            self.spin_step_offset.blockSignals(True)
            self.spin_step_offset.setValue(float(np.clip(offset, -1.0, 1.0)))
            self.spin_step_offset.blockSignals(False)

        # A normal click never invokes Randomizer/Phase-Locker or changes other pads.
        self.reload_active_instrument_sequencer_ui()
        self._position_step_editor(s_idx)

    # =====================================================================
    # PLAYLIST_VELOCITY_PHASELOCK — playlist velocity participates in the same
    # seeded/random/phase-locked field as sequencer activity. User-edited rows
    # are preserved; only rows marked/recognized as available are fitted.
    # =====================================================================
    def _phase_lock_playlist_velocity(self, rng=None, strength=0.65, randomize=False):
        rows = int(self.spin_playlist_length.value()) if hasattr(self, 'spin_playlist_length') else len(getattr(self, '_render_playlist_snapshot', None) or getattr(self, 'master_playlist_data', []))
        if not getattr(self, 'master_playlist_data', None):
            return
        if rng is None:
            rng = np.random.default_rng(_safe_int_seed(self.get_numeric_seed()))
        for i, entry in enumerate(self.master_playlist_data[:rows]):
            # Per-row evaluated seed (list scripts → distinct phase per row/instrument)
            try:
                row_seed = float(self._instrument_seed_float(i))
            except Exception:
                row_seed = float(self.get_numeric_seed() or 0.0)
            # Seed/phase field: smooth, deterministic, with optional random perturbation.
            phase = (i / max(rows, 1)) * 2.0 * np.pi + (abs(row_seed) % 100000) * 0.000013
            field = 0.5 + 0.5 * ot_sin_vec_equiv(phase * MEUM_CONSTANT + row_seed * 0.0000017)
            field = 0.5 * field + 0.5 * self._contextual_numerology(step=i, row=i) if hasattr(self, "_contextual_numerology") else field
            target = 0.25 + 0.75 * field
            if randomize:
                target = 0.75 * target + 0.25 * float(rng.uniform(0.5, 1.5))
            old = float(entry.get("velocity", 1.0) or 1.0)
            # Treat explicit non-default velocities as user data and preserve them.
            user_locked = bool(entry.get("velocity_user_locked", False))
            if user_locked and self._canonical_protect_user():
                continue
            if randomize:
                entry["velocity"] = float(np.clip((1.0-strength) * old + strength * target, 0.05, 1.5))
            else:
                # Phase-lock must not silently create a timeline amplitude slope.
                # Keep the existing/user value, sanitized to a finite range.
                entry["velocity"] = float(np.clip(old if math.isfinite(old) else 1.0, 0.05, 1.5))

        if hasattr(self, 'active_paint_table') and self.active_paint_table:
            table = self.active_paint_table
            for r, entry in enumerate(self.master_playlist_data[:min(rows, table.rowCount())]):
                item = QTableWidgetItem(f"{float(entry.get('velocity', 1.0))*100:.1f}%")
                table.set_cell_item(r, 3, item)

    def randomize_playlist_velocity(self):
        self._phase_lock_playlist_velocity(np.random.default_rng(_safe_int_seed(self.get_numeric_seed())), strength=1.0, randomize=True)
        self._live_engine_signatures.pop("playlist", None)

    def _on_step_amp_slider(self, val):
        if hasattr(self, 'lbl_step_amp'):
            self.lbl_step_amp.setText(f"{val}%")
        if self.selected_step_idx is None:
            return
        curr_i = self.instrument_selector_dropdown.currentText()
        mem = self._current_sequence_mem(curr_i) if hasattr(self, "_current_sequence_mem") else self.instrument_sequencer_memory[curr_i]
        s = self.selected_step_idx
        self._adopt_canonical_for_edit(mem, curr_i)   # CANONICAL_SEQ_DISPLAY_20261102
        self._ensure_seq_mem_length(mem, s + 1)
        mem["amplitudes"][s] = val / 100.0
        self._mark_step_touched(mem, s)  # USER_TOUCHED_TRACKING: manual slider edit
        try: self._canonical_write_sequence_runtime(curr_i, self._current_sequence_index(curr_i))
        except Exception: pass
        try: self._refresh_canonical_fingerprint()
        except Exception: pass
        # Amp is velocity / step-trigger blend amount into painted together steps
        if mem["steps"][s] and s < len(self.seq_step_buttons):
            pitch = mem["pitches"][s] if s < len(mem.get("pitches", [])) else 1.0
            offset = float(mem.get("offsets", [0.0] * len(mem.get("steps", [])))[s]) if s < len(mem.get("offsets", [])) else 0.0
            self.seq_step_buttons[s].setText(f"Pad {s+1}\nA:{val/100:.2f} P:{pitch:.2f}×\nO:{offset:+.2f} step")

    def _on_step_pitch_slider(self, val):
        ratio = val / 100.0
        if hasattr(self, 'lbl_step_pitch'):
            self.lbl_step_pitch.setText(f"{ratio:.2f}×")
        if self.selected_step_idx is None:
            return
        curr_i = self.instrument_selector_dropdown.currentText()
        mem = self._current_sequence_mem(curr_i) if hasattr(self, "_current_sequence_mem") else self.instrument_sequencer_memory[curr_i]
        s = self.selected_step_idx
        self._adopt_canonical_for_edit(mem, curr_i)   # CANONICAL_SEQ_DISPLAY_20261102
        self._ensure_seq_mem_length(mem, s + 1)
        mem["pitches"][s] = ratio
        try: self._canonical_write_sequence_runtime(curr_i, self._current_sequence_index(curr_i))
        except Exception: pass
        try: self._refresh_canonical_fingerprint()
        except Exception: pass
        if s < len(self.seq_step_buttons):
            amp = mem["amplitudes"][s] if s < len(mem["amplitudes"]) else 1.0
            offset = float(mem.get("offsets", [0.0] * len(mem.get("steps", [])))[s]) if s < len(mem.get("offsets", [])) else 0.0
            self.seq_step_buttons[s].setText(f"Pad {s+1}\nA:{amp:.2f} P:{ratio:.2f}×\nO:{offset:+.2f} step")

    def _on_step_phase_shift_slider(self, val):
        """Edit the canonical per-step phase lane; UI degrees map to stored radians."""
        degrees = int(val)
        if hasattr(self, 'lbl_step_phase_shift'):
            self.lbl_step_phase_shift.setText(f"{degrees}°")
        if self.selected_step_idx is None:
            return
        curr_i = self.instrument_selector_dropdown.currentText()
        mem = self._current_sequence_mem(curr_i) if hasattr(self, '_current_sequence_mem') else self.instrument_sequencer_memory[curr_i]
        s = int(self.selected_step_idx)
        self._adopt_canonical_for_edit(mem, curr_i)   # CANONICAL_SEQ_DISPLAY_20261102
        self._ensure_seq_mem_length(mem, s + 1)
        lanes = mem.setdefault("step_controls", {})
        lane = lanes.setdefault("phase_shift", [0.0] * len(mem.get("steps", [])))
        if len(lane) < len(mem.get("steps", [])):
            lane.extend([0.0] * (len(mem.get("steps", [])) - len(lane)))
        radians = math.radians(float(degrees))
        lane[s] = radians
        # Preserve a pre-existing top-level canonical lane for old consumers,
        # while step_controls remains the schema-v2 authority.
        if isinstance(mem.get("phase_shift"), list):
            if len(mem["phase_shift"]) < len(lane):
                mem["phase_shift"].extend([0.0] * (len(lane) - len(mem["phase_shift"])))
            mem["phase_shift"][s] = radians
        self._mark_step_touched(mem, s)
        try:
            self._canonical_write_sequence_runtime(curr_i, self._current_sequence_index(curr_i))
        except Exception:
            pass
        try:
            self._refresh_canonical_fingerprint()
        except Exception:
            pass

    def _on_step_control_slider(self, lane_name, value):
        """Write a per-step canonical control lane and refresh project identity."""
        if self.selected_step_idx is None:
            return
        curr_i = self.instrument_selector_dropdown.currentText()
        mem = self._current_sequence_mem(curr_i) if hasattr(self, "_current_sequence_mem") else self.instrument_sequencer_memory[curr_i]
        s = int(self.selected_step_idx)
        self._adopt_canonical_for_edit(mem, curr_i)   # CANONICAL_SEQ_DISPLAY_20261102
        self._ensure_seq_mem_length(mem, s + 1)
        controls = mem.setdefault("step_controls", {})
        _lane_default = {"eq_frequency": 1000.0, "eq_q": 0.707, "fx_probability": 1.0, "trigger_probability": 1.0}.get(str(lane_name), 0.0)
        lane = controls.setdefault(str(lane_name), [_lane_default] * len(mem.get("steps", [])))
        if len(lane) < len(mem.get("steps", [])):
            lane.extend([_lane_default] * (len(mem.get("steps", [])) - len(lane)))
        if lane_name == "eq_gain_db":
            lane[s] = float(np.clip(value, -24.0, 24.0))
        elif lane_name == "eq_frequency":
            lane[s] = float(np.clip(value, 20.0, 20000.0))
        elif lane_name == "eq_q":
            lane[s] = float(np.clip(value, 0.1, 18.0))
        elif lane_name == "sidechain_depth":
            lane[s] = float(np.clip(value, -1.0, 1.0))
        else:
            lane[s] = float(np.clip(value, 0.0, 1.0))
        if lane_name == "fx_probability" and hasattr(self, "lbl_step_fx_probability"):
            self.lbl_step_fx_probability.setText(f"{lane[s]*100:.0f}%")
        if lane_name == "trigger_probability":
            probs = mem.setdefault("probabilities", [100] * len(mem.get("steps", [])))
            while len(probs) < len(mem.get("steps", [])): probs.append(100)
            probs[s] = int(round(lane[s] * 100.0))
        if lane_name == "eq_gain_db" and hasattr(self, "lbl_step_eq_gain"):
            self.lbl_step_eq_gain.setText(f"{lane[s]:.1f}")
        elif lane_name == "sidechain_depth" and hasattr(self, "lbl_step_sidechain"):
            self.lbl_step_sidechain.setText(f"{lane[s]*100:.0f}%")
        elif lane_name == "trigger_probability" and hasattr(self, "lbl_step_probability"):
            self.lbl_step_probability.setText(f"{lane[s]*100:.0f}%")
        self._mark_step_touched(mem, s)
        try: self._canonical_write_sequence_runtime(curr_i, self._current_sequence_index(curr_i))
        except Exception: pass
        try: self._refresh_canonical_fingerprint()
        except Exception: pass

    def _on_step_offset_changed(self, val):
        if self.selected_step_idx is None:
            return
        curr_i = self.instrument_selector_dropdown.currentText()
        mem = self._current_sequence_mem(curr_i) if hasattr(self, "_current_sequence_mem") else self.instrument_sequencer_memory[curr_i]
        s = self.selected_step_idx
        self._adopt_canonical_for_edit(mem, curr_i)   # CANONICAL_SEQ_DISPLAY_20261102
        self._ensure_seq_mem_length(mem, s + 1)
        mem["offsets"][s] = float(np.clip(val, -0.5, 0.5))
        if s < len(self.seq_step_buttons):
            amp = mem["amplitudes"][s] if s < len(mem["amplitudes"]) else 1.0
            pitch = mem["pitches"][s] if s < len(mem["pitches"]) else 1.0
            self.seq_step_buttons[s].setText(
                f"Pad {s+1}\nA:{amp:.2f} P:{pitch:.2f}×\nO:{mem['offsets'][s]:+.2f} step"
            )
        self._mark_step_touched(mem, s)
        try: self._canonical_write_sequence_runtime(curr_i, self._current_sequence_index(curr_i))
        except Exception: pass
        try: self._refresh_canonical_fingerprint()
        except Exception: pass

    # deduped: shadowed by later _on_euclidean_live_toggled() definition (perfect-unison system).

    # deduped: shadowed by later _on_seeded_live_toggled() definition (perfect-unison system).

    def _on_user_program_only_toggled(self, checked):
        if checked:
            # Suspend live engines — user carrier only; restore OFF styles via :checked
            for btn, timer, style_attr, off_label in (
                (self.btn_idealize_rhythm, self._live_euclid_timer, "_style_toggle_euclidean", "✨ Euclidean Live Lock"),
                (self.btn_seeded_randomize, self._live_seeded_timer, "_style_toggle_randomizer", "🎲 Seeded Live Randomizer"),
                (self.btn_fractal_seed_mode, None, None, "Fractal Seed Mode"),
            ):
                if timer is not None:
                    timer.stop()
                btn.blockSignals(True)
                btn.setChecked(False)
                btn.blockSignals(False)
                if style_attr and hasattr(self, style_attr):
                    btn.setStyleSheet(getattr(self, style_attr))
                if btn is not self.btn_fractal_seed_mode:
                    btn.setText(off_label)
            self._deactivate_engine_generated_content(source_label="UserProgramOnly")
            print("[User program only] Live engines suspended — carrier only")

    def _canonical_prune_stale_playlist_touches(self):
        """Remove resize-stale UI touches while retaining explicit user ownership.

        Canonical Protect is meant to protect real user edits, not coordinates
        inherited by newly created ensemble rows. Engine/UI writes are performed
        with _paint_expanding, but older touched coordinates can survive a resize.
        Those stale coordinates were the reason turning Protect OFF temporarily
        made the ensemble suddenly become polyphonic again.
        """
        table = getattr(self, "active_paint_table", None)
        if table is None:
            return
        touched = getattr(table, "playlist_user_touched", None)
        if not touched:
            return
        data = getattr(self, "master_playlist_data", None) or []
        valid = set()
        for pair in list(touched):
            try:
                r, c = int(pair[0]), int(pair[1])
            except Exception:
                continue
            if r < 0 or c < 0 or r >= len(data):
                continue
            e = data[r] if isinstance(data[r], dict) else {}
            locks = set()
            try:
                locks = {int(x) for x in (e.get("user_locked_columns") or [])}
            except Exception:
                pass
            # A persistent lock/user instance is proof of ownership. A bare old
            # touch after resize is not.
            if e.get("user_owned") or e.get("user_instances") or c in locks:
                valid.add((r, c))
        table.playlist_user_touched = valid

    def _canonical_protect_user(self):
        """True when user composition locks must be respected (default)."""
        chk = getattr(self, "chk_canonical_protect", None)
        if chk is None:
            return True
        return bool(chk.isChecked())

    def _snapshot_user_composition(self, replace=False):
        """Capture userdata so Canonical Overwrite can be undone anytime.

        Stores playlist rows that carry user locks/ownership, table touch sets,
        and sequencer memories that have human-touched steps.

        Engine wipes call this with replace=False (keep the existing snapshot).
        The user turning Overwrite ON calls replace=True so the snapshot matches
        the composition at that moment. The snapshot is kept after restore so
        Restore userdata works anytime until the next Overwrite cycle.
        """
        if getattr(self, "_user_composition_snapshot", None) and not replace:
            return self._user_composition_snapshot

        playlist_rows = {}
        rows = getattr(self, "master_playlist_data", None) or []
        for i, entry in enumerate(rows):
            if not isinstance(entry, dict):
                continue
            locked = entry.get("user_locked_columns") or []
            if locked or entry.get("velocity_user_locked") or entry.get("user_owned"):
                playlist_rows[i] = copy.deepcopy(entry)

        table_touches = {}
        for table_attr in ("active_paint_table", "paintbrush_table", "playlist_paint_table"):
            table = getattr(self, table_attr, None)
            if table is None:
                continue
            touched = getattr(table, "playlist_user_touched", None)
            if touched:
                table_touches[table_attr] = set(touched)

        seq = {}
        banks = getattr(self, "instrument_sequence_banks", {}) or {}
        for name, bank in banks.items():
            for idx, mem in (bank or {}).items():
                if isinstance(mem, dict) and mem.get("touched"):
                    seq[f"{name}::{int(idx)}"] = copy.deepcopy(mem)
        if not seq:
            mems = getattr(self, "instrument_sequencer_memory", None) or {}
            for name, mem in mems.items():
                if isinstance(mem, dict) and mem.get("touched"):
                    seq[name] = copy.deepcopy(mem)

        # Canonical overwrite is a reversible transaction, not just a lock-mask
        # operation. Preserve the full newer sequence/automation authority so
        # OFF/Restore round-trips Automation, sequence references and timing.
        full_state = {}
        for key in (
            "playlist_automation",
            "instrument_sequence_banks",
            "instrument_selected_sequence",
            "instrument_sequencer_memory",
            "sequencer_automation_points",
            "sequencer_automation_enabled",
            "automator_timing_mode",
            "_selected_automation_step",
            # PROJECT_STATE_INTEGRATION_20260909: state added by recent media,
            # graph, Performance, canonical, modulation and game work. These are
            # lightweight authoritative values/caches, never live device objects.
            "automation_patterns",
            "master_vector_state",
            "geometric_synth_mixer_state",
            "wavetable_projector_state",
            "sample_morph_state",
            "global_mod_state",
            "algorithm_xmod_local",
            "algorithm_xmod_global",
            "media_carrier_slot",
            "carrier_binding_mode",
            "carrier_binding_source",
            "carrier_bound_layers_state",
            "live_dj_random_script",
            "_live_dj_random_generation",
            "canonical_continuation_enabled",
            "canonical_continuation_mode",
            "canonical_resonance_factor",
            "canonical_resonance_handoff",
            "meum_spatial_resolution_enabled",
            "meum_spatial_activity_modulus",
            "_canonical_user_blend_ledger",
            "_canonical_activity_ledger",
            "_last_videogame_identity",
            "_last_videogame_path",
            "canonical_engine_levels", "phase_lock_characteristics", "_rand_instance_seed", "_rand_generation_counter",
            "imported_3d_model_path", "imported_3d_model_meta", "voxel_grid_size", "voxel_alias_pct", "voxel_paint_color", "voxel_paint_blend_pct", "voxel_cells",
        ):
            try:
                full_state[key] = copy.deepcopy(getattr(self, key, None))
            except Exception:
                full_state[key] = None
        snap = {
            "playlist_rows": playlist_rows,
            "table_touches": table_touches,
            "sequencer": seq,
            "full_sequence_automation_state": full_state,
        }
        self._user_composition_snapshot = snap
        print(f"[Canonical] snapshotted {len(playlist_rows)} user playlist rows, "
              f"{len(seq)} sequencer memories")
        return snap

    def _wipe_user_composition_flags(self, take_snapshot=False):
        """Canonical Overwrite: clear userdata locks so unison can rewrite everything.

        Seed remains the initial stochastic modifier; locks/flags are wiped so
        the composition is filled one-to-one in unison rather than branching
        around protected cells. Pass take_snapshot=True on the user toggle so
        restore works anytime; engine paints must not replace that snapshot.
        """
        if take_snapshot:
            self._snapshot_user_composition(replace=True)

        try:
            _writer_protection = (getattr(self, "userdata_protection", {}) or {}).get("playlist_math_writer", {})
            if isinstance(_writer_protection, dict) and not bool(_writer_protection.get("protect_from_canonical_overwrite", True)):
                self.math_writer_userdata = None
        except Exception:
            pass

        rows = getattr(self, "master_playlist_data", None) or []
        wiped = 0
        for entry in rows:
            if not isinstance(entry, dict):
                continue
            if entry.pop("user_locked_columns", None) is not None:
                wiped += 1
            if entry.pop("velocity_user_locked", None) is not None:
                wiped += 1
            entry.pop("user_owned", None)
        for table_attr in ("active_paint_table", "paintbrush_table", "playlist_paint_table"):
            table = getattr(self, table_attr, None)
            if table is None:
                continue
            if hasattr(table, "playlist_user_touched"):
                table.playlist_user_touched = set()
            if hasattr(table, "user_touched"):
                try:
                    table.user_touched = set()
                except Exception:
                    pass
        mems = getattr(self, "instrument_sequencer_memory", None) or {}
        for mem in mems.values():
            if isinstance(mem, dict) and "touched" in mem:
                try:
                    if isinstance(mem["touched"], (list, set)):
                        mem["touched"] = type(mem["touched"])()
                except Exception:
                    pass
        print(f"[Canonical Overwrite] wiped user locks on {wiped} playlist rows — unison may rewrite all")
        return wiped

    def _restore_user_composition(self):
        """Put snapshotted userdata back over the unison fill. Snapshot is kept."""
        snap = getattr(self, "_user_composition_snapshot", None)
        if not snap:
            print("[Canonical] protect ON — no userdata snapshot to restore")
            return 0

        rows = getattr(self, "master_playlist_data", None)
        if rows is None:
            rows = []
            self.master_playlist_data = rows
        restored = 0
        for i, entry in snap.get("playlist_rows", {}).items():
            i = int(i)
            while len(rows) <= i:
                rows.append({})
            rows[i] = copy.deepcopy(entry)
            restored += 1

        for table_attr, touched in (snap.get("table_touches") or {}).items():
            table = getattr(self, table_attr, None)
            if table is None:
                continue
            table.playlist_user_touched = set(touched)

        mems = getattr(self, "instrument_sequencer_memory", None)
        banks = getattr(self, "instrument_sequence_banks", {}) or {}
        if isinstance(mems, dict):
            for key, mem in (snap.get("sequencer") or {}).items():
                if "::" in str(key):
                    name, idx_txt = str(key).rsplit("::", 1)
                    try:
                        idx = int(idx_txt)
                    except Exception:
                        continue
                    banks.setdefault(name, {})[idx] = copy.deepcopy(mem)
                    if int((getattr(self, "instrument_selected_sequence", {}) or {}).get(name, 1)) == idx:
                        mems[name] = banks[name][idx]
                else:
                    mems[key] = copy.deepcopy(mem)
        self.instrument_sequence_banks = banks

        # Restore the complete newer automation/sequence transaction if this
        # snapshot was captured by a current build. Older snapshots remain
        # backwards compatible through the selective restoration above.
        full_state = snap.get("full_sequence_automation_state") or {}
        if full_state:
            for key, value in full_state.items():
                try:
                    setattr(self, key, copy.deepcopy(value))
                except Exception:
                    pass
            try:
                self._ensure_sequence_banks_after_resize()
            except Exception:
                pass

        self._push_restored_playlist_to_table()
        try:
            if hasattr(self, "reload_active_instrument_sequencer_ui"):
                self.reload_active_instrument_sequencer_ui()
        except Exception:
            pass

        # Keep snapshot so Restore userdata works anytime until next Overwrite.
        print(f"[Canonical] restored {restored} user playlist rows from snapshot")
        return restored

    def _on_restore_userdata_clicked(self):
        """Anytime restore: reapply snapshot and turn Canonical protect back ON."""
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("Restore userdata")
        n = self._restore_user_composition()
        chk = getattr(self, "chk_canonical_protect", None)
        if chk is not None and not chk.isChecked():
            chk.blockSignals(True)
            chk.setChecked(True)
            chk.blockSignals(False)
        if hasattr(self, "scope_status_label"):
            if n:
                self.scope_status_label.setText(
                    f"📊 Restored {n} user rows from snapshot — Canonical protect ON"
                )
            else:
                self.scope_status_label.setText("📊 No userdata snapshot yet — paint or overwrite first")

    def _push_restored_playlist_to_table(self):
        """Write the complete authoritative playlist row, including all 18 columns."""
        table = getattr(self, "active_paint_table", None) or getattr(self, "paintbrush_table", None)
        if table is None:
            return
        rows = getattr(self, "master_playlist_data", None) or []
        try:
            if hasattr(table, "setRowCount") and table.rowCount() != len(rows):
                table.setRowCount(len(rows))
            if hasattr(table, "setColumnCount") and table.columnCount() < PLAYLIST_COLUMN_COUNT:
                table.setColumnCount(PLAYLIST_COLUMN_COUNT)
        except Exception:
            pass

        def put(r, c, text):
            if c >= PLAYLIST_COLUMN_COUNT or r >= len(rows):
                return
            try:
                if hasattr(table, "set_cell_item"):
                    table.set_cell_item(r, c, QTableWidgetItem(str(text)))
                else:
                    table.setItem(r, c, QTableWidgetItem(str(text)))
            except Exception:
                pass

        keys = PLAYLIST_COLUMNS
        for r, e in enumerate(rows):
            e = e if isinstance(e, dict) else {}
            for c, key in enumerate(keys):
                val = e.get(key, "")
                if key == "operators_csv" and not val:
                    val = e.get("operator", "")
                if key == "velocity" and val not in (None, ""):
                    try:
                        val = f"{float(val) * 100:.1f}%"
                    except Exception:
                        pass
                put(r, c, "" if val in (None, [], {}) else val)
        try:
            self._r32_tint_playlist(table, rows)
        except Exception:
            pass

    def _record_engine_step_ownership(self, source):
        """Remember which non-user steps an engine currently contributes."""
        store = getattr(self, "_engine_step_ownership", None)
        if store is None:
            store = self._engine_step_ownership = {}
        owned = set()
        for name, mem in (getattr(self, "instrument_sequencer_memory", {}) or {}).items():
            if not isinstance(mem, dict):
                continue
            touched = set(mem.get("touched", ()) or ())
            steps = mem.get("steps", []) or []
            for idx, on in enumerate(steps):
                if on and idx not in touched:
                    owned.add((str(name), int(idx)))
        store[str(source)] = owned

    _R32_ENGINE_BUTTONS = (("seeded", "btn_seeded_randomize"), ("randomizer", "btn_local_randomize"),
                           ("phase_lock", "btn_local_phase_lock"), ("euclidean", "btn_idealize_rhythm"),
                           ("fractal_seed", "btn_fractal_seed_mode"))

    def _r32_engine_buttons_on(self):
        on = {k for k, a in self._R32_ENGINE_BUTTONS if getattr(self, a, None) is not None and getattr(self, a).isChecked()}
        if bool(getattr(self, "goava_active", False)):
            on.add("goava")
        return on

    def _r32_restore_engine_buttons(self, wanted):
        changed = False
        for k, a in self._R32_ENGINE_BUTTONS:
            b = getattr(self, a, None)
            if b is not None and b.isChecked() != (k in wanted):
                b.blockSignals(True); b.setChecked(k in wanted); b.blockSignals(False)
                changed = True
        self.goava_active = "goava" in wanted
        if changed:
            QTimer.singleShot(0, self._on_live_source_changed)

    def _active_engine_sources(self):
        active = set()
        for key, attr in (("seeded","btn_seeded_randomize"), ("randomizer","btn_local_randomize"), ("phase_lock","btn_local_phase_lock"), ("euclidean","btn_idealize_rhythm"), ("fractal_seed","btn_fractal_seed_mode")):
            btn = getattr(self, attr, None)
            if btn is not None and btn.isChecked() and self._canonical_level_raw(key) > 0.0:
                active.add(key)
        if bool(getattr(self, "goava_active", False)) and self._canonical_level_raw("goava") > 0.0:
            active.add("goava")
        return active

    def _deactivate_engine_generated_content(self, source_label="engine", source_key=None):
        """
        Reverse the non-destructive material an additive engine (Randomizer,
        Phase-Locker, Euclidean Live Lock, Seeded Live Randomizer) painted
        in, without touching anything a human actually programmed.

        _paint_operator_pattern_to_playlist's docstring is explicit that
        engine-owned material must be "regenerated from the seed + source
        and ... fully tagged, so Randomizer / Phase-Lock can be removed
        without leaving stale cells or automation" — but nothing previously
        called that removal when an engine was switched OFF, so step cells
        and playlist rows the engine had painted stayed lit/populated
        forever. This is that removal:

          - Step-grid cells: any step that is ON but was never actually
            clicked / slider-edited by a human (not in mem["touched"],
            per USER_TOUCHED_TRACKING) is switched back OFF and its
            amp/pitch/probability reset to defaults. Touched steps are a
            human's own programming and are left exactly as they are.
          - Playlist rows: any row tagged 'generated_by_engine' has its
            engine-authored fields stripped back out, leaving only whatever
            '@u:' user instances were on that row (or a blank row if none).
          - Playlist automation: rows tagged 'generated_by_engine' are
            cleared the same way.
        """
        cleared_steps = 0
        mems = getattr(self, "instrument_sequencer_memory", None) or {}
        ownership = getattr(self, "_engine_step_ownership", {}) or {}
        key_map = {"Randomizer":"randomizer", "PhaseLock":"phase_lock", "EuclideanLiveLock":"euclidean", "SeededLiveRandomizer":"seeded", "FractalSeed":"fractal_seed", "Fractal Seed Mode":"fractal_seed"}
        remove_key = source_key or key_map.get(source_label)
        owned = ownership.get(remove_key, set()) if remove_key else set().union(*ownership.values()) if ownership else set()
        active_sources = self._active_engine_sources()
        for name, idx in list(owned):
            mem = mems.get(name)
            if not isinstance(mem, dict):
                continue
            touched = set(mem.get("touched", ()) or ())
            if idx in touched:
                continue
            owners = mem.get("engine_step_sources", {}).get(int(idx), set())
            if owners and remove_key:
                owners = set(owners)
                owners.discard(remove_key)
                mem.setdefault("engine_step_sources", {})[int(idx)] = owners
                if owners:
                    continue
            elif any((name, idx) in ownership.get(src, set()) for src in active_sources if src != remove_key):
                continue
            steps = mem.get("steps", [])
            if idx >= len(steps):
                continue
            if steps[idx]:
                cleared_steps += 1
            steps[idx] = False
            for key in ("amplitudes", "pitches"):
                arr = mem.get(key, [])
                if idx < len(arr):
                    arr[idx] = 1.0
            probs = mem.get("probabilities", [])
            if idx < len(probs):
                probs[idx] = 100
        if remove_key:
            ownership.pop(remove_key, None)

        # GOAVA has a dedicated contribution field and must disappear cleanly
        # without touching userdata or other canonical contributions.
        if remove_key == "goava":
            for entry in getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or []:
                if isinstance(entry, dict):
                    for key in ("goava_sequence","goava_frequency","goava_pitch","goava_seed",
                                "goava_unison_weight","goava_active","goava_generated_by_engine",
                                "goava_harmonic"):
                        entry.pop(key, None)
                    ops = [x for x in (entry.get("operators") or []) if str(x).strip() != "GOAVA"]
                    entry["operators"] = ops
                    if ops:
                        entry["operators_csv"] = ", ".join(ops)
                    else:
                        _ui_names = [str(u.get("operator") or u.get("name") or "").strip()
                                     for u in (entry.get("user_instances") or []) if isinstance(u, dict)]
                        entry["operators_csv"] = ", ".join([n for n in _ui_names if n])
                    entry["multi_seq"] = ", ".join(
                        x for x in str(entry.get("multi_seq","")).split(",") if x.strip() and x.strip() != "GOAVA"
                    )

        cleared_rows = 0
        rows = getattr(self, "master_playlist_data", None) or []
        for entry in rows:
            if not isinstance(entry, dict):
                continue
            contribs = entry.get("engine_contributions")
            if not isinstance(contribs, dict):
                continue
            if remove_key:
                contribs.pop(remove_key, None)
            else:
                contribs.clear()
            users = list(entry.get("user_instances") or [])
            self._reconcile_engine_playlist_row(entry, users)
            if not contribs:
                entry.pop("engine_contributions", None)
            cleared_rows += 1

        automation = getattr(self, "playlist_automation", None) or []
        for i, auto in enumerate(automation):
            if not (isinstance(auto, dict) and auto.get("generated_by_engine")):
                continue
            mode = str(auto.get("mode", ""))
            if remove_key is None or f"engine:{remove_key}" in mode or mode.endswith(str(remove_key)):
                automation[i] = {}

        self._engine_generated_playlist_rows = set()

        # Redraw whatever playlist grid is currently open, and the step grid.
        try:
            self._push_restored_playlist_to_table()
        except Exception:
            pass
        if hasattr(self, "reload_active_instrument_sequencer_ui"):
            try:
                self.reload_active_instrument_sequencer_ui()
            except Exception:
                pass

        print(f"[{source_label}] deactivated — cleared {cleared_steps} engine step "
              f"cell(s), {cleared_rows} generated playlist row(s)")
        return cleared_steps, cleared_rows

