    def _on_canonical_protect_toggled(self, checked):
        """Canonical-protect is a state boundary, followed by exactly one rebuild.

        Do not invoke individual engines here: doing so creates a partially rebuilt
        playlist which is then used as the next baseline.  Both directions therefore
        enter the same history-free canonical transaction.
        """
        if getattr(self, "_canonical_protect_toggle_guard", False):
            return
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("Canonical protect " + ("ON" if checked else "OFF"))
        self._canonical_protect_toggle_guard = True
        try:
            if checked:
                self._restore_user_composition()
                # Restore is user-state recovery only.  Recompose surviving active
                # canonicals from that recovered baseline so OFF->ON cannot retain
                # the overwritten playlist tail or a single GOAVA identity.
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText("📊 Canonical protect ON — rebuilding from restored user baseline · Resonance 50–150%")
                if hasattr(self, "_canonical_rebuild_guard") and not self._canonical_rebuild_guard:
                    self._rebuild_active_canonical_playlist("canonical_protect_on")
            else:
                self._wipe_user_composition_flags(take_snapshot=True)
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText("📊 Canonical Overwrite (User Data Overwrite ON) — Resonance 0–200%")
                if hasattr(self, "_canonical_rebuild_guard") and not self._canonical_rebuild_guard:
                    self._rebuild_active_canonical_playlist("canonical_overwrite_on")
            # Resonance band follows protect / User Data Overwrite mode.
            if hasattr(self, "_sync_canonical_resonance_ui_range"):
                self._sync_canonical_resonance_ui_range()
        finally:
            self._canonical_protect_toggle_guard = False


    def _live_engine_signature(self, which):
        """Stable snapshot of user-visible inputs; engines write only once per new snapshot."""
        seed = self._seed_text() if hasattr(self, 'input_seed_val') else "0.0"
        inst = self.instrument_selector_dropdown.currentText() if hasattr(self, 'instrument_selector_dropdown') else ""
        seq_len = int(self.spin_seq_length.value()) if hasattr(self, 'spin_seq_length') else DEFAULT_SEQUENCE_LENGTH
        rows = int(self.spin_playlist_length.value()) if hasattr(self, 'spin_playlist_length') else DEFAULT_PLAYLIST_ROWS
        return (which, seed, inst, seq_len, rows, repr(getattr(self, 'instrument_sequencer_memory', {})), repr(getattr(self, '_render_playlist_snapshot', None) or getattr(self, 'master_playlist_data', [])))

    def _apply_live_engine_once(self, which, force=False):
        if getattr(self, "_live_engine_update_guard", False):
            return
        # force=True is used by deferred live-source flushes that already hold
        # the composition guard; only block non-forced re-entrancy.
        if (not force) and getattr(self, "_composition_generation_guard", False):
            return

        sig = self._live_engine_signature(which) if hasattr(self, "_live_engine_signature") else None
        if (
            not force
            and sig is not None
            and getattr(self, "_live_engine_signatures", {}).get(which) == sig
        ):
            return

        snap = self._snapshot_global_effect_sliders()
        self._live_engine_update_guard = True
        self._composition_generation_guard = True
        try:
            self._active_engine_write_source = str(which)
            if which == "euclidean":
                self.apply_euclidean_and_idealized_rhythms()
            else:
                self.apply_seeded_harmonic_randomization()
        except Exception as exc:
            print(f"[LiveEngine:{which}] {type(exc).__name__}: {exc}")
        finally:
            self._active_engine_write_source = None
            self._live_engine_update_guard = False
            self._composition_generation_guard = False
            self._restore_global_effect_sliders(snap)
            if sig is not None:
                if not hasattr(self, "_live_engine_signatures"):
                    self._live_engine_signatures = {}
                self._live_engine_signatures[which] = (
                    self._live_engine_signature(which)
                    if hasattr(self, "_live_engine_signature")
                    else sig
                )
    # NOTE: _flush_live_source_update used to be redefined later in this
    # class, which silently shadowed this copy (Python keeps only the last
    # def). Removed here; the effective version is further down, with
    # phase_lock/randomizer wired in so seed edits actually reach those
    # engines instead of only euclidean/seeded/goava.

    def _live_engine_tick(self, which):
        if getattr(self, 'chk_user_program_only', None) and self.chk_user_program_only.isChecked():
            return
        if which == "euclidean" and self.btn_idealize_rhythm.isChecked():
            self.apply_euclidean_and_idealized_rhythms()
        elif which == "seeded" and self.btn_seeded_randomize.isChecked():
            self.apply_seeded_harmonic_randomization()

    def _serialize_sequence_memory(self, mem):
        out = normalize_sequence_memory(mem)
        # Mixed-type sets (e.g. str + None/int) must never make saving raise.
        _k = lambda x: (x is None, type(x).__name__, str(x))
        if isinstance(out.get("touched"), set):
            out["touched"] = sorted(out["touched"], key=_k)
        srcs = out.get("engine_step_sources")
        if isinstance(srcs, dict):
            out["engine_step_sources"] = {
                str(k): sorted(v, key=_k) if isinstance(v, (set, list, tuple)) else []
                for k, v in srcs.items()
            }
        return out

    def _deserialize_sequence_memory(self, mem):
        out = normalize_sequence_memory(mem)
        if isinstance(out.get("touched"), list):
            out["touched"] = set(out["touched"])
        srcs = out.get("engine_step_sources")
        if isinstance(srcs, dict):
            restored = {}
            for k, v in srcs.items():
                key = int(k) if str(k).lstrip("-").isdigit() else k
                restored[key] = set(v) if isinstance(v, list) else (v if isinstance(v, set) else set())
            out["engine_step_sources"] = restored
        return out

    def _apply_v3_canonical_baseline(self, *, notify=False):
        """Apply the exact V3 fresh-boot canonical baseline to runtime + UI.

        This is deliberately shared by startup values and Clear Memory semantics:
        resonance unity (100%), canonical convolve midpoint (50%), seed transduction
        weight e−2 ≈ 0.718282, FullWeight + Full Unison ON, canonical protection ON, and no user-touched
        canonical-field residue. It does not enable optional stochastic/remix engines.
        """
        self.canonical_resonance_factor = CANONICAL_RESONANCE_DEFAULT
        self.canonical_resonance_handoff = CANONICAL_RESONANCE_DEFAULT
        self._canonical_field_touched = set()
        # Clear Memory: every instrument's geometric instance returns to canonical.
        try:
            for _ps in (getattr(self, "instrument_param_state", {}) or {}).values():
                if isinstance(_ps, dict):
                    _ps.pop("geo", None)
            _fac = self._geometric_convolution_defaults()  # R23R convolution preset
            for _lane, _attr in (("vector", "master_vector_state"), ("wavetable", "wavetable_projector_state"),
                                 ("ball", "ball_synth_params"), ("cellular", "cellular_synth_params")):
                _buf = getattr(self, _attr, None)
                if isinstance(_buf, dict):
                    for _k in {"wavetable": ("drawn",), "ball": ("x", "y"), "cellular": ("manual_cells",)}.get(_lane, ()):
                        _buf.pop(_k, None)
                    _buf.update(copy.deepcopy(_fac[_lane]))
            self.ball_manual_activity_locked = False
            self.ca_single_cell_activity_locked = False
            if getattr(self, "_geo_editor_instrument", None):
                self._geo_loading = True
                try:
                    self._geo_refresh_widgets()
                finally:
                    self._geo_loading = False
        except Exception as _geo_reset_exc:
            print(f"[Baseline] geometric instances reset: {_geo_reset_exc}")
        self._gui_call_bridge = _GuiCallBridge(self)
        self._gui_refresh_pending = set()

        def _set_value(name, value):
            w = getattr(self, name, None)
            if w is None or not hasattr(w, "setValue"):
                return
            try:
                w.blockSignals(True); w.setValue(value); w.blockSignals(False)
            except Exception:
                try: w.blockSignals(False)
                except Exception: pass

        def _set_checked(name, checked):
            w = getattr(self, name, None)
            if w is None or not hasattr(w, "setChecked"):
                return
            try:
                w.blockSignals(True); w.setChecked(bool(checked)); w.blockSignals(False)
            except Exception:
                try: w.blockSignals(False)
                except Exception: pass

        _set_value("spin_canonical_resonance", CANONICAL_RESONANCE_DEFAULT * 100.0)
        _set_value("spin_canonical_convolve", CANONICAL_CONVOLVE_DEFAULT_PCT)
        _set_value("spin_canonical_live_overblend", CANONICAL_LIVE_OVERBLEND_DEFAULT_PCT)
        _set_value("spin_engine_strength", CANONICAL_SEED_WEIGHT_DEFAULT)
        self._unison_blend_user = CANONICAL_ADHERENCE_FALLBACK
