    def _on_master_global_eq_changed(self, points):
        """Commit the drawn curve to the canonical project model."""
        clean=[]
        for pt in points if isinstance(points,(list,tuple)) else []:
            try: clean.append([max(0.0,min(1.0,float(pt[0]))),max(-18.0,min(18.0,float(pt[1])))])
            except Exception: pass
        clean.sort(key=lambda q:q[0])
        if len(clean)<2: clean=[[0.0,0.0],[1.0,0.0]]
        self.master_global_eq_points=clean

    def _apply_master_global_eq(self, signal, sample_rate):
        """Apply the project-global curve with deterministic FFT-bin gain interpolation."""
        try:
            pts=self._effective_master_eq_points()
            if all(abs(float(q[1]))<1e-12 for q in pts): return signal
            x=np.asarray([max(0.0,min(1.0,float(q[0]))) for q in pts],dtype=np.float64)
            db=np.asarray([max(-18.0,min(18.0,float(q[1]))) for q in pts],dtype=np.float64)
            n=len(signal)
            if n<16: return signal
            # User-requested linear frequency scale: normalized x maps linearly 10 Hz–24 kHz.
            f=np.fft.rfftfreq(n,1.0/max(1.0,float(sample_rate)))
            xf=np.clip((f-10.0)/(24000.0-10.0),0.0,1.0)
            gain=np.power(10.0,np.interp(xf,x,db)/20.0)
            spec=np.fft.rfft(np.asarray(signal,dtype=np.float32))
            return np.fft.irfft(spec*gain,n=n).astype(np.float32)
        except Exception:
            return signal

    def _r32_state_section(self):
        try:
            import project_schema
            return project_schema.snapshot(self)
        except Exception as exc:
            print(f"[Project] R32 state not saved: {exc}")
            return {}

    def _apply_project_snapshot(self, data):
        # GROOVEBOX_R32_PROJECT_SCHEMA_20261110: R32 engine state is restored after the rest.
        _r32_unpack_document(data)          # R32.8 COMPACT_MCC
        try:
            return self._apply_project_snapshot_core(data)
        finally:
            try:
                import project_schema
                if isinstance(data, dict) and isinstance(data.get("r32"), dict):
                    project_schema.apply(self, data["r32"])
            except Exception as exc:
                print(f"[Project] R32 state not restored: {exc}")
            try:   # R32.8 UI_AUTOSTATE: every other workspace control, through its own handlers
                import ui_autostate
                if isinstance(data, dict) and isinstance(data.get("ui_auto"), dict):
                    _n, _sk = ui_autostate.restore(self, data["ui_auto"], QApplication.instance())
                    if _sk:
                        print(f"[Project] restored {_n} controls; {_sk} saved controls not in this layout")
            except Exception as exc:
                print(f"[Project] UI controls not restored: {exc}")

    def _apply_project_snapshot_core(self, data):
        """Restore a full project document, then load each instrument's geometric instance.

        GROOVEBOX_R23R_GEOMETRY_PER_INSTRUMENT_20261031: edits fired while the
        document is applied must not store the previous project's editor buffer
        into the newly loaded instruments, so buffer stores are held off until the
        selected instrument's instance is loaded from the document.
        """
        self._playlist_cleared_hold = False
        # PROJECT_LOAD_ISOLATION_20261108: a restored widget state can emit
        # toggled/clicked signals while the document is only partially applied.
        # In particular, never let Boost Beats arm its live scheduler mid-load.
        self._project_loading = True
        self.pkp_boost_active = False
        _boost_timer = getattr(self, "_pkp_boost_timer", None)
        if _boost_timer is not None:
            try:
                _boost_timer.stop()
            except Exception:
                pass
        self._geo_loading = True
        try:
            # Clean editor buffer so a legacy document's shared values never mix
            # with the previous project's instance (drawn cycle, ball spot, cells).
            _fac = self._geometric_convolution_defaults()  # R23R convolution preset
            for _lane, _attr in (("vector", "master_vector_state"), ("wavetable", "wavetable_projector_state"),
                                 ("ball", "ball_synth_params"), ("cellular", "cellular_synth_params")):
                _buf = getattr(self, _attr, None)
                if isinstance(_buf, dict):
                    for _k in {"wavetable": ("drawn",), "ball": ("x", "y"), "cellular": ("manual_cells",)}.get(_lane, ()):
                        _buf.pop(_k, None)
                    _buf.update(copy.deepcopy(_fac[_lane]))
            # Authored geometric-vs-panel balances travel in the document; seed the canonical
            # macro user store from it BEFORE the inner load runs its reconciliation, otherwise
            # the previous project's value would be written back over the loaded one.
            try:
                _mus0 = getattr(self, "_canonical_macro_user_store", None)
                if not isinstance(_mus0, dict):
                    _mus0 = self._canonical_macro_user_store = {}
                _ips = (data or {}).get("instrument_param_state") if isinstance(data, dict) else None
                if isinstance(_ips, dict):
                    for _gn, _gp in _ips.items():
                        if isinstance(_gp, dict) and "geo_panel_mix" in _gp:
                            _mus0.setdefault(_gn, {})["geo_panel_mix"] = _gp["geo_panel_mix"]
                        elif isinstance(_mus0.get(_gn), dict):
                            _mus0[_gn].pop("geo_panel_mix", None)
            except Exception:
                pass
            result = self._apply_project_snapshot_inner(data)
        finally:
            self._geo_loading = False
            self._project_loading = False
        try:
            data = data if isinstance(data, dict) else {}
            if isinstance(data.get("canonical_field_touched"), list):
                self._canonical_field_touched = set(str(t) for t in data["canonical_field_touched"])
            self._geo_migrate_legacy()
            for _gn, _gp in (getattr(self, "instrument_param_state", {}) or {}).items():   # stale marks
                _g = _gp.get("geo") if isinstance(_gp, dict) else None
                if isinstance(_g, dict) and _g.get("touched"):
                    _g["touched"] = self._geo_real_touched(_g)
            # A loaded geometric-vs-panel balance is authored data: the canonical macro user
            # store must carry it, otherwise reconciliation would restore the previous project's value.
            _mus = getattr(self, "_canonical_macro_user_store", None)
            if not isinstance(_mus, dict):
                _mus = self._canonical_macro_user_store = {}
            for _gn, _gp in (getattr(self, "instrument_param_state", {}) or {}).items():
                if isinstance(_gp, dict) and "geo_panel_mix" in _gp:
                    _mus.setdefault(_gn, {})["geo_panel_mix"] = _gp["geo_panel_mix"]
                elif isinstance(_mus.get(_gn), dict):
                    _mus[_gn].pop("geo_panel_mix", None)
            _name = self.instrument_selector_dropdown.currentText() if hasattr(self, "instrument_selector_dropdown") else ""
            self._geo_editor_instrument = None
            self._geo_buffer_load(_name)
            try:
                import userdata_tool as _ut2; _ut2.prune_untouched(self)
            except Exception:
                pass
        except Exception as _geo_load_exc:
            print(f"[Load] geometric instances: {_geo_load_exc}")
        return result

    def _apply_project_snapshot_inner(self, data):
        """Restore a full project document (inverse of _project_snapshot)."""
        data = data if isinstance(data, dict) else {}
        # FRACTAL_SEED_MODE_V3: absent keys migrate ON; explicit OFF is persistent.
        _saved_engines = data.get("engines") if isinstance(data.get("engines"), dict) else {}
        _fractal_enabled = data.get("fractal_seed_mode_enabled", _saved_engines.get("fractal_seed", True))
        _fractal_btn = getattr(self, "btn_fractal_seed_mode", None)
        if _fractal_btn is not None:
            _fractal_btn.blockSignals(True)
            try:
                _fractal_btn.setChecked(bool(_fractal_enabled))
            finally:
                _fractal_btn.blockSignals(False)
        # R28_HF1_MASTER_VOLUME_PROJECT_ROUNDTRIP: saved projects override the
        # 72% fresh-session default. Accept older 0..1 scalar or 0..100 percent
        # representation, and preserve explicit 0 instead of using truthiness.
        try:
            _saved_mv = data.get("master_volume_percent", None)
            if _saved_mv is None and "master_volume" in data:
                _saved_mv = float(data.get("master_volume"))
                if 0.0 <= _saved_mv <= 1.0:
                    _saved_mv *= 100.0
            if _saved_mv is not None and math.isfinite(float(_saved_mv)):
                self._on_master_vol_changed(int(round(max(0.0, min(100.0, float(_saved_mv))))))
        except Exception as _mv_restore_exc:
            print(f"[Project Load] saved master volume skipped: {_mv_restore_exc}")
        if hasattr(self, "master_global_eq_curve"):
            self.master_global_eq_curve.set_points(data.get("master_global_eq", [[0.0,0.0],[1.0,0.0]]))
        if isinstance(data.get("ball_synth_params"), dict) and hasattr(self, "ball_synth_params"):
            self.ball_synth_params.update(data["ball_synth_params"])
            for _k in ("gravity","gravity_angle_degrees","radius","vx","vy"):
                _w=getattr(self,"spin_ball_"+_k,None)
                if _w is not None:
                    _w.blockSignals(True); _w.setValue(float(self.ball_synth_params.get(_k,_w.value()))); _w.blockSignals(False)
            if hasattr(self,"chk_ball_reverse_polarity"): self.chk_ball_reverse_polarity.setChecked(bool(self.ball_synth_params.get("reverse_polarity_on_hit",True)))
        if isinstance(data.get("cellular_synth_params"), dict) and hasattr(self, "cellular_synth_params"):
            self.cellular_synth_params.update(data["cellular_synth_params"])
            for _k in ("width","height","cell_types","generations","rule"):
                _w=getattr(self,"spin_ca_"+_k,None)
                if _w is not None:
                    _w.blockSignals(True); _w.setValue(int(self.cellular_synth_params.get(_k,_w.value()))); _w.blockSignals(False)
