    def _atomic_write_document(self, path, data):
        """Crash-resistant MCC commit with cross-process commit exclusion.

        The new payload is fully fsync'd before replacement. The previous good
        generation is retained as ``.prev`` and the containing directory is
        fsync'd on POSIX so the rename itself survives sudden power loss.
        A short-lived O_EXCL lock prevents two Groovebox processes from
        committing the same document at the same instant.
        """
        path = self._ensure_project_extension(path)
        path_s = str(path)
        part = path_s + ".part"
        prev = path_s + ".prev"
        lock = path_s + ".lock"
        data, _packed = _r32_pack_document(data)
        # big documents: no indentation either (indent alone was ~30 % of the size)
        payload = json.dumps(data, indent=None if _packed else 2, sort_keys=True, default=str,
                             separators=(",", ":") if _packed else None)
        tmp = part + f".{os.getpid()}.tmp"
        lock_fd = None
        try:
            # Cross-process commit exclusion. A stale lock older than 15 min is
            # recoverable after a crashed writer.
            try:
                lock_fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
            except FileExistsError:
                try:
                    if time.time() - os.path.getmtime(lock) > 900:
                        os.unlink(lock)
                        lock_fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
                    else:
                        raise RuntimeError("This MCC is currently being committed by another Groovebox process.")
                except FileNotFoundError:
                    lock_fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
            if lock_fd is not None:
                os.write(lock_fd, f"pid={os.getpid()}\n".encode("ascii", "replace"))
                os.fsync(lock_fd)

            with open(tmp, "w", encoding="utf-8", newline="\n") as f:
                f.write(payload)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, part)

            # Preserve the last committed generation before replacing it.
            if os.path.isfile(path_s):
                prev_tmp = prev + f".{os.getpid()}.tmp"
                with open(path_s, "rb") as src, open(prev_tmp, "wb") as dst:
                    shutil.copyfileobj(src, dst, length=1024 * 1024)
                    dst.flush(); os.fsync(dst.fileno())
                os.replace(prev_tmp, prev)

            os.replace(part, path_s)
            try:
                import project_registry as _preg
                _preg.touch(path_s, "autosave" if os.path.basename(path_s) == "autosave.MCC" else "saved", data)
            except Exception:
                pass
            try:
                from mcc_integrity import sha256_file, write_sidecar
                if os.path.isfile(prev): write_sidecar(prev, sha256_file(prev))
                write_sidecar(path_s, sha256_file(path_s))
            except Exception as _integrity_exc:
                print(f"[MCC] integrity sidecar warning: {_integrity_exc}")
            try:
                if os.name != "nt":
                    dfd = os.open(os.path.dirname(os.path.abspath(path_s)) or ".", os.O_RDONLY)
                    try: os.fsync(dfd)
                    finally: os.close(dfd)
            except Exception:
                pass
            try:   # R32.8 SAVE_HISTORY: last 64 saves / autosaves, chronological (not export job copies)
                if "groovebox_job" not in path_s:
                    import r32_finish as _rf
                    _rf.record_save(path_s, "autosave" if os.path.basename(path_s).lower() == "autosave.mcc" else "save")
            except Exception:
                pass
            return path
        finally:
            for leftover in (tmp,):
                try:
                    if os.path.exists(leftover): os.unlink(leftover)
                except Exception:
                    pass
            if lock_fd is not None:
                try: os.close(lock_fd)
                except Exception: pass
            try:
                if os.path.exists(lock): os.unlink(lock)
            except Exception:
                pass

    def _on_project_memory_worker_done(self, payload):
        if not isinstance(payload, dict):
            return
        ticket = int(payload.get("ticket", 0) or 0)
        callback = self._project_memory_callbacks.pop(ticket, None)
        if callback is not None:
            try:
                callback(payload.get("result"), payload.get("error"))
            except Exception as exc:
                print(f"[ProjectMemory] completion callback warning: {exc}")

    def _submit_project_memory_work(self, kind, data, work, callback=None):
        """Run one ordered live-memory/savefile operation on its own thread."""
        self._project_memory_ticket += 1
        ticket = self._project_memory_ticket
        if callback is not None:
            self._project_memory_callbacks[ticket] = callback

        def _runner():
            result = None
            error = None
            try:
                # Freeze mutable containers on the project-memory lane rather
                # than burdening the GUI thread with deep copying / JSON work.
                frozen = copy.deepcopy(data)
                with self._project_save_lock:
                    self._project_memory_version += 1
                    self._live_project_memory_snapshot = frozen
                    result = work(frozen)
            except Exception as exc:
                error = exc
            try:
                self._project_memory_bridge.done.emit({
                    "ticket": ticket, "kind": str(kind),
                    "result": result, "error": error,
                    "version": self._project_memory_version,
                })
            except RuntimeError:
                pass

        self._project_memory_lane.submit(_runner)
        return ticket

    def _save_project_document(self, path, show_saved=True):
        """Capture Qt-owned state quickly, then save on the dedicated project lane."""
        path = self._ensure_project_extension(path)
        if not getattr(self, "_project_uid", None):
            import uuid as _uuid
            self._project_uid = _uuid.uuid4().hex
        try:
            data = self._project_snapshot()
        except Exception as e:
            QMessageBox.warning(self, "Save failed", f"Could not build project document:\n{e}")
            return None

        def _write_project(frozen):
            return self._atomic_write_document(path, frozen)

        def _save_complete(final, error):
            if error is not None:
                if show_saved:
                    QMessageBox.warning(self, "Save failed", f"{path}\n{error}")
                return
            if show_saved and not self.is_playing:
                QMessageBox.information(self, "Saved", f"Project saved:\n{final}")
            try:
                if _drive_targets is not None:
                    _drive_targets.auto_copy(final if isinstance(final, str) and os.path.isfile(final) else path)
            except Exception:
                pass

        self._submit_project_memory_work("project_save", data, _write_project, _save_complete)
        return path

    def _install_project_autosave(self):
        """AUTOSAVE_2026: every 3 minutes, atomically write the live project to
        the recovery store (a .part file) so a crash can always be finished."""
        if getattr(self, "_autosave_timer", None) is None:
            self._autosave_timer = QTimer(self)
            self._autosave_timer.setInterval(180000)
            self._autosave_timer.timeout.connect(self._autosave_project)
            self._autosave_timer.start()
        self._last_autosave_fp = getattr(self, "lbl_canonical_fp", None)

    def _autosave_project(self):
        """Queue a durable recovery generation on the dedicated project lane.

        GROOVEBOX_AUTOSAVE_BOX_20261102: nothing is written when the Autosave box is unticked. When it is
        ticked and a project file is open, the changes are also saved into that project (the version on
        disk at the start of the session is first kept once as metadata/before-autosave.MCC).
        """
        if getattr(self, "_autosave_disabled", False):   # PIN_RESET_R31: never rewrite data during a reset
            return
        try:
            chk = getattr(self, "chk_autosave", None)
            if chk is not None and not chk.isChecked():
                return
        except Exception:
            pass
        # SPEED_20261102: build the project snapshot once and use it for both the in-place project write
        # and the recovery copy (it used to be built twice per autosave on the GUI thread).
        try:
            data = self._project_snapshot()
        except Exception as exc:
            print(f"[Autosave] snapshot failed: {exc}")
            return
        try:
            self._autosave_into_open_project(data)
        except Exception as exc:
            print(f"[Autosave] project write skipped: {exc}")
        try:
            # R32.4: the recovery copy was skipped whenever the canonical fingerprint label was
            # missing (e.g. autosave timer started before the panel existed), so the newest
            # autosave on disk was often an old one.
            import groovebox_paths
            path = os.path.join(groovebox_paths.metadata_dir(getattr(self, "_current_project_path", None)), "autosave.MCC")

            def _write_autosave(frozen):
                return self._atomic_write_document(path, frozen)

            self._submit_project_memory_work("project_autosave", data, _write_autosave, None)
        except Exception:
            pass

    def _autosave_into_open_project(self, data=None):
        path = getattr(self, "_current_project_path", None)
        if not path or str(path).lower().endswith((".meum", ".mgpr")):
            return
        path = os.path.abspath(str(path))
        if getattr(self, "_recovered_needs_save", False):
            return                      # a recovered snapshot is never silently written over the project
        done = getattr(self, "_autosave_backed_up", None)
        if done is None:
            done = self._autosave_backed_up = set()
        if path not in done:
            done.add(path)
            if os.path.isfile(path):
                try:
                    import groovebox_paths
                    keep = os.path.join(groovebox_paths.metadata_dir(path), "before-autosave.MCC")
                    shutil.copy2(path, keep)
                except Exception as exc:
                    print(f"[Autosave] could not keep the original: {exc}")
        if data is None:
            self._save_project_document(path, show_saved=False)
            return
        path = self._ensure_project_extension(path)
        self._submit_project_memory_work("project_save", data,
                                         lambda frozen, _p=path: self._atomic_write_document(_p, frozen), None)

    def load_autosave_if_available(self):
        """Studio Session helper: restore the newest autosave if one exists.
        Non-fatal; falls back to installing the autosave timer if nothing is found.
        """
        try:
            import groovebox_paths
            candidates = groovebox_paths.autosave_candidates()
            if not candidates:
                self._install_project_autosave()
                return False
            # Prefer the most recent
            c0 = candidates[0]
            # R32.4: rows are dicts; getattr(dict, "path") was None, so str(dict) was "opened".
            path = c0 if isinstance(c0, str) else (c0.get("path") if isinstance(c0, dict) else getattr(c0, 'path', None)) or str(c0)
            if hasattr(self, 'open_project_path'):
                ok = self.open_project_path(path, show_message=False)
                if ok:
                    # Keep working in the real project, not in .../metadata/autosave.MCC.
                    try:
                        src = c0.get("project_path") if isinstance(c0, dict) else ""
                        if src and os.path.isfile(src):
                            self._current_project_path = src
                        elif os.path.basename(path) == "autosave.MCC":
                            root = os.path.dirname(os.path.dirname(path))
                            mccs = [os.path.join(root, f) for f in os.listdir(root) if f.lower().endswith(".mcc")]
                            self._current_project_path = max(mccs, key=os.path.getmtime) if mccs else None
                    except Exception:
                        pass
                    self._install_project_autosave()
                    return True
            # Fallback: just arm the timer
            self._install_project_autosave()
            return False
        except Exception:
            try:
                self._install_project_autosave()
            except Exception:
                pass
            return False

    def _check_project_recovery(self):
        """Offer explicit Recover / Delete / Ignore handling for durable autosaves.

        The prompt identifies the working project with its title and Project Notes.
        Recover restores the snapshot without overwriting the user's last explicit
        project save. Delete removes only the selected autosave/recovery file.
        """
        try:
            import groovebox_paths
            candidates = groovebox_paths.autosave_candidates()
            if not candidates:
                QMessageBox.information(
                    None,
                    "No Autosave Available",
                    "No recoverable autosave or interrupted project save was found.\n\n"
                    "Groovebox will start with a clean project state.",
                )
                return
            # Only the newest recovery artifact per working project is prompted at
            # boot. Older artifacts remain visible in Storage Maintenance.
            unique = []
            seen = set()
            for row in candidates:
                p = Path(row.get("path", ""))
                key = str(p.parent.parent if p.name == "autosave.MCC" and p.parent.name == "metadata" else p.parent)
                if key in seen:
                    continue
                seen.add(key); unique.append(row)

            for row in unique:
                recovery_path = str(row.get("path", ""))
                title = str(row.get("title") or "Untitled Project")
                notes = str(row.get("notes") or "").strip()
                when = "Unknown time"
                try:
                    when = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(float(row.get("mtime", 0))))
                except Exception:
                    pass
                validation_problem = ""
                try:
                    with open(recovery_path, "r", encoding="utf-8") as f:
                        data = json.load(f)
                    if not isinstance(data, dict):
                        validation_problem = "The recovery document root is not an object."
                    elif "master_playlist_data" in data:
                        _playlist = data.get("master_playlist_data")
                        if not isinstance(_playlist, list):
                            validation_problem = "The saved playlist is not a list."
                        elif len(_playlist) > 1024:
                            validation_problem = "The saved playlist exceeds the supported 1024-row limit."
                        elif any(not isinstance(_entry, dict) for _entry in _playlist):
                            validation_problem = "One or more playlist rows are malformed."
                    if validation_problem:
                        data = None
                except Exception as _recovery_read_exc:
                    data = None
                    validation_problem = f"The recovery file could not be read or parsed: {_recovery_read_exc}"

                kind = "Autosave" if row.get("kind") == "autosave" else "Interrupted save"
                box = QMessageBox(None, Qt.WindowType.Dialog | Qt.WindowType.WindowStaysOnTopHint)
                box.setWindowModality(Qt.WindowModality.ApplicationModal)
                box.setIcon(QMessageBox.Icon.Warning)
                box.setWindowTitle("Groovebox Project Recovery")
                box.setText(f"{kind} found for: {title}")
                details = [f"Last recovery write: {when}", f"File: {recovery_path}"]
                if notes:
                    preview = notes if len(notes) <= 1400 else notes[:1400] + "…"
                    details.append("\nProject Notes:\n" + preview)
                else:
                    details.append("\nProject Notes: (none)")
                details.append("\nRecover restores this working state without overwriting your last explicit project save.")
                box.setInformativeText("\n".join(details))
                recover_btn = box.addButton("Recover", QMessageBox.ButtonRole.AcceptRole)
                delete_btn = box.addButton("Delete Autosave" if row.get("kind") == "autosave" else "Delete Recovery File", QMessageBox.ButtonRole.DestructiveRole)
                ignore_btn = box.addButton("Ignore for Now", QMessageBox.ButtonRole.RejectRole)
                if not isinstance(data, dict):
                    recover_btn.setEnabled(False)
                    _why = validation_problem or "The recovery document could not be validated."
                    box.setInformativeText(box.informativeText() + "\n\n" + _why + " Recover is disabled; the file will be preserved unless you explicitly delete it.")
                box.exec()
                clicked = box.clickedButton()
                if clicked is delete_btn:
                    try:
                        groovebox_paths.delete_autosave(recovery_path)
                        print(f"[Recovery] deleted {recovery_path}")
                    except Exception as exc:
                        QMessageBox.warning(None, "Delete autosave failed", str(exc))
                    continue
                if clicked is ignore_btn or clicked is None:
                    return
                if clicked is recover_btn and isinstance(data, dict):
                    self._apply_project_snapshot(data)
                    # Prefer the local project file beside metadata; a stored path
                    # may refer to a different machine or an older mount point.
                    local_project = None
                    rp = Path(recovery_path)
                    if rp.name == "autosave.MCC" and rp.parent.name == "metadata":
                        proot = rp.parent.parent
                        mcc = sorted(proot.glob("*.MCC")) + sorted(proot.glob("*.mcc"))
                        if mcc: local_project = str(mcc[0])
                        else: local_project = str(proot / f"{groovebox_paths._safe_project_name(title)}.MCC")
                    elif recovery_path.lower().endswith(".part"):
                        local_project = recovery_path[:-5]
                    if local_project:
                        self._current_project_path = local_project
                    # GROOVEBOX_R23R_EXPORT_RESUME_COMPAT_20261101: the recovered state
                    # is not written over the user's last explicit save until they choose.
                    self._recovered_needs_save = True
                    try: self.reload_active_instrument_sequencer_ui()
                    except Exception: pass
                    try: self._refresh_after_file_input(reason="recovery")
                    except Exception: pass
                    self._last_autosave_fp = getattr(self, "lbl_canonical_fp", None)
                    print(f"[Recovery] restored project from {recovery_path}")
                    return
        except Exception as exc:
            print(f"[Recovery] scan skipped: {exc}")

    def _current_program_identity(self):
        try:
            from program_identity import identify
            info = identify(os.path.abspath(__file__))
            self._program_identity = info
            return info
        except Exception:
            return {}

    def _composition_id_for_artifact(self):
        try:
            return str(self._canonical_fingerprint() or "")
        except Exception:
            return ""

    def read_program_to_id_dialog(self):
        path, _ = QFileDialog.getOpenFileName(
            self, "Read Program → ID", os.path.dirname(os.path.abspath(__file__)),
            "Programs / packages (*.py *.MCC *.mcc *.zip);;All files (*)")
