    def _render_instrument_voice(self, name, hz, t, dur, sr):
        """Modern per-instrument voice (Boost Beats / keyboard notes): the shared
        _audition_voice (panel synth + four geometrics + algo drives) with the
        instrument sample layered as at render time. No envelope."""
        try:
            self._geo_buffer_store()
        except Exception:
            pass
        voice = self._audition_voice(name, hz, t, sr)
        rec = (getattr(self, "instrument_media_samples", {}) or {}).get(name)
        if isinstance(rec, dict) and rec.get("waveform") is not None:
            raw = self._sample_native_layer(np.asarray(rec["waveform"], dtype=np.float32),
                                            int(rec.get("sample_rate", sr) or sr), t)
            voice = 0.5 * voice + 0.5 * raw
        return np.nan_to_num(np.asarray(voice, dtype=np.float64), nan=0.0, posinf=0.0, neginf=0.0)

    @staticmethod
    def _pkp_boost_envelope(t, dur, shape):
        """PKP Env: 0 = attack-heavy pluck · 0.5 = solid held note · 1 = release-heavy swell.

        Three canonical shapes, morphed linearly (A→S for 0..0.5, S→R for 0.5..1),
        all with 2 ms click-free edges.
        """
        shape = float(min(1.0, max(0.0, shape)))
        dur = max(1e-4, float(dur))
        edge = np.minimum(1.0, np.minimum(t / 0.002, np.maximum(0.0, (dur - t) / 0.002)))
        pluck = np.exp(-t / (0.12 * dur)) * edge                                   # attack-heavy
        solid = np.minimum(1.0, t / 0.005) * np.minimum(1.0, np.maximum(0.0, (dur - t) / 0.012))  # held note
        rise = np.clip(t / (0.55 * dur), 0.0, 1.0)
        swell = (rise * rise) * np.exp(-np.maximum(0.0, t - 0.55 * dur) / (0.6 * dur)) * edge      # release-heavy
        if shape <= 0.5:
            u = shape / 0.5
            return (1.0 - u) * pluck + u * solid
        u = (shape - 0.5) / 0.5
        return (1.0 - u) * solid + u * swell

    def _audition_voice(self, name, hz, t, sr, phase0=0.0):
        """AUDITION_VOICE_20261102: one instrument's voice for a trigger / key / pad hit.

        The same construction as the render voice: Edit Synth panel synth (its waveform with its own
        Meum AM/FM/PM context) mixed with its four geometric synths by the instrument's
        geometric / panel balance, with the Global Play Synth / Geometric Algo drives applied.
        Returns float64 samples over the time grid ``t`` (no envelope; callers shape the hit).
        """
        t = np.asarray(t, dtype=np.float64)
        n = int(t.size)
        if n == 0:
            return np.zeros(0, dtype=np.float64)      # no time, no samples (exact)
        dur = n / float(sr)
        _jam_controller = getattr(self, "_live_jam_controller", None)
        _jam_active = bool(getattr(_jam_controller, "enabled", False))
        _jam = getattr(self, "_live_jam_controls", {}) if _jam_active else {}
        if _jam_active:
            # Jam tuning is a bounded ±2-semitone morph around the unmodified pitch.
            try:
                _tune = max(0.0, min(1.0, float(_jam.get("tuning", 0.5))))
                hz = float(hz) * (2.0 ** (((_tune - 0.5) * 4.0) / 12.0))
            except Exception:
                pass
        st = dict((getattr(self, "instrument_param_state", {}) or {}).get(name, {}) or {})
        st = self._md_io_apply_outputs(name, st)
        ctx = st.get("meum_modulation", st) if isinstance(st.get("meum_modulation", st), dict) else st
        sd = self._global_algo_kind_drive("synth", name, 0.5)
        if sd:
            ctx = dict(ctx)
            for k in ("am_depth", "fm_depth", "pm_depth", "meum_depth"):
                if isinstance(ctx.get(k), (int, float)):
                    ctx[k] = float(ctx[k]) * (1.0 + 0.25 * sd)
        fm, pm, am = meum_modulation_vectors(t, ctx)
        phase = (2.0 * np.pi * np.cumsum(float(hz) * np.asarray(fm, dtype=np.float64)) / sr
                 + np.asarray(pm, dtype=np.float64) + float(phase0))
        wf = str(st.get("waveform", "isn") or "isn").strip().lower()
        try:
            main = np.asarray(meum_waveform_from_phase(phase, wf), dtype=np.float64)
        except Exception:
            main = np.asarray(ot_sin_vec_equiv(phase), dtype=np.float64)
        slot = self._instance_slot(name)
        ig = self._instance_voice_geometry(name, slot, params=self._geo_params_with_algo(st, name, 0.5))
        geo = _ws_geometric_voice(phase, t, dur, ig["slot"], ig["coeffs"], sample_rate=sr, harmonic_cap=ig["cap"],
                                  vector=ig["vector"], ball=ig["ball"], density=ig["density"], depths=ig["depths"])
        g = float(ig["wt_gain"]); geo = g * geo + (1.0 - g) * np.sin(phase)
        gpw = geo_panel_weight(st)
        inner = (1.0 - gpw) * main + gpw * geo
        if _jam_active:
            try:
                _geo = max(0.0, min(1.0, float(_jam.get("geometric_flux", 0.5))))
                _exchange = max(0.0, min(1.0, float(_jam.get("triad_exchange", 0.5))))
                gpw = float(np.clip(gpw + (_geo - 0.5) * 0.45 + (_exchange - 0.5) * 0.30, 0.0, 1.0))
            except Exception:
                pass
        _base_inner = np.asarray(inner, dtype=np.float64)
        try:   # GROOVEBOX_R23R_MULTIDIM_SYNTH_20261103: the same triad as the render voice
            _triad_inner = np.asarray(self._md_triad(main, geo, gpw, name, slot, phase, t, sr), dtype=np.float64)
            if _jam_active:
                # Jam-only Canonical Mix is a signed morph around the normal triad.
                # 0.5 is exactly neutral; lower values deflect toward the pre-triad
                # panel/geometric mix and higher values reinforce the multidim triad.
                _cm = max(0.0, min(1.0, float(_jam.get("canonical_mix", 0.5))))
                inner = _triad_inner + (2.0 * (_cm - 0.5)) * (_triad_inner - _base_inner)
            else:
                inner = _triad_inner
        except Exception:
            pass
        out = inner * np.asarray(am, dtype=np.float64)
        if _jam_active and n:
            try:
                # All controls are centered at 0.5, which is a true no-op.
                _amp = max(0.0, min(1.0, float(_jam.get("amplitude", 0.5))))
                out *= (1.0 + (_amp - 0.5) * 1.5)
                _damp = max(0.0, min(1.0, float(_jam.get("damping", 0.5))))
                if _damp > 0.5:
                    out *= np.exp(-((t - float(t[0])) / max(dur, 1e-6)) * (_damp - 0.5) * 3.0)
                elif _damp < 0.5:
                    out *= 1.0 + (0.5 - _damp) * 0.35
                _attack = max(0.0, min(1.0, float(_jam.get("attack", 0.5))))
                if abs(_attack - 0.5) > 0.01:
                    _attack_s = 0.005 * (2.0 ** ((_attack - 0.5) * 8.0))
                    out *= np.clip((t - float(t[0])) / max(_attack_s, 1e-5), 0.0, 1.0)
                _release = max(0.0, min(1.0, float(_jam.get("release", 0.5))))
                if abs(_release - 0.5) > 0.01:
                    _release_s = 0.005 * (2.0 ** ((_release - 0.5) * 8.0))
                    out *= np.clip((float(t[-1]) - t) / max(_release_s, 1e-5), 0.0, 1.0)
                _res = max(0.0, min(1.0, float(_jam.get("resonance", 0.5))))
                if abs(_res - 0.5) > 0.01:
                    out += (2.0 * (_res - 0.5)) * 0.16 * np.sin(3.0 * phase) * np.asarray(am, dtype=np.float64)
                # GROOVEBOX_R31_MEUM_FX_CORE_20261109: Live Jam uses only the hardcoded FX.
                # filter → Fractallizer tilt, drive → ∞M HyperDrive, Delay → PKP gate,
                # Reverb → EQR, Chorus → Fractallizer, Drive → HyperDrive. No tanh soft
                # clip, no IIR/FFT filter, no reverb/chorus taps. 0.5 / unticked = bypass.
                import hardcoded_fx as _hfx
                _fx = getattr(self, "_live_jam_fx", {}) if _jam_active else {}
                _send = max(0.0, min(1.0, float(_jam.get("fx_send", 0.5))))
                _send_gain = 0.25 + 1.5 * _send
                _filter = max(0.0, min(1.0, float(_jam.get("filter", 0.5))))
                _tilt = (_filter - 0.5) * 2.0
                _frac_amt = abs(_tilt) if abs(_filter - 0.5) > 0.02 else 0.0
                if _fx.get("Chorus", False):
                    _frac_amt = max(_frac_amt, 0.36 * _send_gain)
                if _frac_amt > 0.0 and n > 16:
                    out = _hfx.fractallize(out, sr, min(1.0, _frac_amt), _tilt).astype(np.float64)
                if _fx.get("Delay", False) and n > 64:
                    _g, _ = _hfx.pkp_gate(n, sr, float(getattr(self, "global_bpm", 120.0) or 120.0), 0.5,
                                          min(1.0, 0.5 * _send_gain), 0, 0.5)
                    out = out * _g
                if _fx.get("Reverb", False) and n > 16:
                    out = _hfx.eqr_mix(out, min(1.0, 0.4 * _send_gain), eqr_tensor_audio_z_vec).astype(np.float64)
                _drive = max(0.0, min(1.0, float(_jam.get("drive", 0.5))))
                _hd = (_drive - 0.5) * 2.0 if _drive > 0.5 else 0.0
                if _fx.get("Drive", False):
                    _hd = max(_hd, 0.6)
                if _hd > 0.0:
                    out = _hfx.fi_hyperdrive(out, sr, _hd, float(MEUM_MINUS_1) * 4.0,
                                             start_sample=int(float(t[0]) * sr) if n else 0).astype(np.float64)
            except Exception:
                pass
        return np.nan_to_num(out, nan=0.0, posinf=0.0, neginf=0.0)

    def trigger_selected_note(self):
        """Audition the selected instrument at the Trigger Note frequency.

        50% Edit Synth main synth (its waveform with its own Meum AM/FM/PM context)
        + 50% its four-geometric instance (the exact render function), then its
        sample layered as at render time. One-shot through the shared audition mixer.
        """
        try:
            self._ensure_hardware_use("trigger-note")
            name = self._current_instrument_name() if hasattr(self, "_current_instrument_name") else self.instrument_selector_dropdown.currentText()
            hz = float(self.trigger_note_freq.hz()) if hasattr(self, "trigger_note_freq") else 432.0
            sr = 44100; dur = 0.9; n = int(sr * dur)
            t = np.arange(n, dtype=np.float64) / sr
            try:
                self._geo_buffer_store()
            except Exception:
                pass
            voice = self._audition_voice(name, hz, t, sr)
            rec = (getattr(self, "instrument_media_samples", {}) or {}).get(name)
            if isinstance(rec, dict) and rec.get("waveform") is not None:
                raw = self._sample_native_layer(np.asarray(rec["waveform"], dtype=np.float32),
                                                int(rec.get("sample_rate", sr) or sr), t)
                voice = 0.5 * voice + 0.5 * raw
            # NO_FADE_NO_LIMIT_20261102: the audition note is the raw voice at a fixed gain - no attack/decay fade, no peak limiter.
            mix = (0.28 * voice).astype(np.float32)
            mix = np.nan_to_num(mix, nan=0.0, posinf=0.0, neginf=0.0)
            if isinstance(getattr(self, 'visual_oscilloscope', None), VisualOscilloscope):
                idx = np.linspace(0, len(mix) - 1, 100).astype(int)
                self.visual_oscilloscope.update_waveform(mix[idx])
            if HAS_SOUNDDEVICE:
                self._pkp_poly_submit(mix, sr)
            self._last_trigger_note = mix
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(f"🎯 {name} · {hz:,.1f} Hz · {frequency_color(hz)[1]}")
        except Exception as e:
            print(f"[Trigger Note] error: {e}")

    # ------------------------------------------------------------------
    # GROOVEBOX_PERF_TOOLBAR_20261104 — sequence performance tools
    # Phrases are rendered with the same per-instrument voice as Trigger Note, on a
    # dedicated worker thread, and never write to the sequence banks.
    # ------------------------------------------------------------------
    _PERF_SR = 44100

    @staticmethod
    def _perf_meum_u(k):
        """Meum phyllotaxis index: frac(k / M), the sphere's 300.5° step — evenly spread picks."""
        return math.modf((int(k) + 1) / MEUM)[0]

    def _perf_pick(self, seq, salt=0):
        seq = list(seq)
        if not seq:
            return None
        self._perf_counter = int(getattr(self, "_perf_counter", 0)) + 1
        return seq[int(self._perf_meum_u(self._perf_counter * 7 + salt) * len(seq)) % len(seq)]

    def _perf_canonical_gap(self):
        try:
            bpm = float(self.spin_bpm.value())
        except Exception:
            bpm = 120.0
        return (60.0 / bpm if bpm > 0 else 0.5) * MEUM

    def _perf_gap_seconds(self):
        """Canonical (Meum) at default; once you set a gap it is 50 % yours, 50 % canonical."""
        canon = self._perf_canonical_gap()
        sp = getattr(self, "spin_perf_gap", None)
        if sp is None or sp.value() <= sp.minimum():
            return canon
        return 0.5 * float(sp.value()) + 0.5 * canon

    def _perf_pattern(self, name, idx):
        bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(name) or {}
        if not bank:
            return self._current_sequence_mem(name)
        if int(idx) in bank:
            return bank[int(idx)]
        keys = sorted(bank)
        return bank[keys[min(len(keys) - 1, max(0, int(idx) - 1))]]

    def _perf_render_phrase(self, program, mem):
        """One pass of ``mem``'s steps voiced by ``program`` (worker thread; reads state only)."""
        sr = self._PERF_SR
        try:
            bpm = float(self.spin_bpm.value())
        except Exception:
            bpm = 120.0
        step_s = (60.0 / bpm / 4.0) if bpm > 0 else 0.125
        steps = list(mem.get("steps") or [])
        n = len(steps) or int(mem.get("pattern_length", 16) or 16)
        amps = list(mem.get("amplitudes") or [])
        pits = list(mem.get("pitches") or [])
        offs = list(mem.get("offsets") or [])
        probs = list(mem.get("probabilities") or [])
        hz0 = float(self.trigger_note_freq.hz()) if hasattr(self, "trigger_note_freq") else 432.0
        note_n = max(1, int(step_s * 0.92 * sr))
        total = int((n * step_s + 0.3) * sr)
        out = np.zeros(total, dtype=np.float64)
        t = np.arange(note_n, dtype=np.float64) / sr
        cache = {}
        k0 = int(getattr(self, "_perf_counter", 0))
        for i in range(n):
            if i >= len(steps) or not steps[i]:
                continue
            prob = float(probs[i]) if i < len(probs) else 1.0
            if prob < 1.0 and self._perf_meum_u(k0 + i) >= prob:
                continue
            ratio = float(pits[i]) if i < len(pits) and pits[i] else 1.0
            v = cache.get(round(ratio, 6))
            if v is None:
                v = cache[round(ratio, 6)] = self._audition_voice(program, hz0 * ratio, t, sr)
            amp = float(amps[i]) if i < len(amps) else 1.0
            off = float(offs[i]) if i < len(offs) else 0.0
            s0 = int(max(0.0, (i + off) * step_s) * sr)
            e = min(total, s0 + note_n)
            if e > s0:
                out[s0:e] += amp * v[:e - s0]
        return np.nan_to_num(0.28 * out).astype(np.float32)

    def _perf_hold_buffer(self, programs, hz):
        """A seamless loop (whole cycles of ``hz`` + crossfaded seam) of the summed programs."""
        sr = self._PERF_SR
        cycles = max(1, int(round(2.0 * hz)))
        L = max(256, int(round(cycles * sr / float(hz))))
        xf = min(L // 4, int(0.05 * sr))
        t = np.arange(L + xf, dtype=np.float64) / sr
        acc = np.zeros(L + xf, dtype=np.float64)
        for p in programs:
            acc += self._audition_voice(p, hz, t, sr)
        acc *= 0.28 / math.sqrt(max(1, len(programs)))
        loop = acc[:L].copy()
        ramp = np.linspace(0.0, 1.0, xf, endpoint=False)
        loop[:xf] = loop[:xf] * ramp + acc[L:L + xf] * (1.0 - ramp)
        return np.nan_to_num(loop).astype(np.float32)

    def _perf_executor(self):
        ex = getattr(self, "_perf_exec", None)
        if ex is None:
            try:
                import thread_budget as _tb
                ex = self._perf_exec = _tb.make_lane("performance-phrase", max_workers=1, max_pending=16)
            except Exception:
                import concurrent.futures as _cf
                ex = self._perf_exec = _cf.ThreadPoolExecutor(max_workers=1, thread_name_prefix="perf-phrase")
        return ex

    def _perf_status(self, text):
        lbl = getattr(self, "lbl_perf_state", None)
        if lbl is not None:
            lbl.setText(text)

    def _perf_queue(self, program, mem, label):
        """Render on the perf thread; the GUI clock submits it when ready."""
        self._perf_jobs = [j for j in getattr(self, "_perf_jobs", []) if not j[0].done() or not j[2]]
        fut = self._perf_executor().submit(self._perf_render_phrase, program, mem)
        self._perf_jobs.append([fut, label, False])
        self._perf_status(f"rendering · {label}")
        self._perf_clock_start()

    def _perf_clock_start(self):
        clk = getattr(self, "_perf_clock", None)
        if clk is None:
            clk = self._perf_clock = QTimer(self)
            clk.setInterval(40)
            clk.timeout.connect(self._perf_tick)
        if not clk.isActive():
            clk.start()

    def _perf_tick(self):
        now = time.monotonic()
        for job in getattr(self, "_perf_jobs", []):
            fut, label, sent = job
            if sent or not fut.done():
                continue
            job[2] = True
            try:
                buf = fut.result()
            except Exception as exc:
                self._perf_status(f"render failed · {exc}")
                continue
            if buf.size:
                self._ensure_hardware_use("perf-phrase")
                self._pkp_poly_submit(buf, self._PERF_SR)
                self._perf_next_at = now + buf.size / float(self._PERF_SR) + self._perf_gap_seconds()
                self._perf_status(f"▶ {label}")
        self._perf_jobs = [j for j in getattr(self, "_perf_jobs", []) if not j[2]]
        mode = getattr(self, "_perf_random_mode", None)
        if mode and not self._perf_jobs and now >= float(getattr(self, "_perf_next_at", 0.0)):
            self._perf_random_step(mode)
        if not mode and not self._perf_jobs:
            self._perf_clock.stop()

    def _perf_selected(self):
        try:
            return str(self.instrument_selector_dropdown.currentText())
        except Exception:
            return ""

    def _perf_play_sel_instrument(self):
        name = self._perf_selected()
        use_y = self.btn_perf_pat_xy.isChecked()
        idx = (self.spin_perf_pat_y if use_y else self.spin_perf_pat_x).value()
        self._perf_queue(name, self._perf_pattern(name, idx), f"{name} · pattern {'Y' if use_y else 'X'}={idx}")

    def _perf_play_sel_pattern(self):
        name = self._perf_selected()
        use_y = self.btn_perf_prog_xy.isChecked()
        prog = (self.combo_perf_prog_y if use_y else self.combo_perf_prog_x).currentText()
        mem = self._current_sequence_mem(name)
        self._perf_queue(prog, mem, f"{name} pattern · {'Y' if use_y else 'X'} program {prog}")

    def _perf_random_step(self, mode):
        names = list(getattr(self, "instrument_names_48", []) or [])
        banks = getattr(self, "instrument_sequence_banks", {}) or {}
        if mode == "global":
            live = [n for n in names if any(any(m.get("steps") or []) for m in (banks.get(n) or {}).values())]
            name = self._perf_pick(live or names, 1)
        else:
            name = self._perf_selected()
        if not name:
            return
        idx = self._perf_pick(sorted(banks.get(name) or {1: None}), 2) or 1
        prog = name
        if getattr(self, "chk_perf_random_patch", None) is not None and self.chk_perf_random_patch.isChecked():
            prog = self._perf_pick(names, 3) or name
        self._perf_next_at = float("inf")
        self._perf_queue(prog, self._perf_pattern(name, idx), f"{'🌐' if mode == 'global' else '🎲'} {name} #{idx}" + (f" · patch {prog}" if prog != name else ""))

    def _perf_set_random(self, mode, on):
        other = self.btn_perf_random_global if mode == "local" else self.btn_perf_random
        if on:
            other.blockSignals(True); other.setChecked(False); other.blockSignals(False)
            self._perf_random_mode = mode
            self._perf_next_at = 0.0
            self._perf_clock_start()
        elif getattr(self, "_perf_random_mode", None) == mode:
            self._perf_random_mode = None
            self._perf_status("idle")

    def _perf_set_hold(self, key, on):
        held = self.__dict__.setdefault("_pkp_held", {})
        if not on:
            with self._pkp_poly_lock:
                held.pop(key, None)
            self._perf_status("hold released")
            return
        hz = float(self.trigger_note_freq.hz()) if hasattr(self, "trigger_note_freq") else 432.0
        progs = list(getattr(self, "instrument_names_48", []) or []) if key == "global" else [self._perf_selected()]
        self._perf_status(f"rendering hold · {len(progs)} program(s) · {hz:,.1f} Hz")
        fut = self._perf_executor().submit(self._perf_hold_buffer, progs, hz)

        def _arm():
            if not fut.done():
                QTimer.singleShot(40, _arm)
                return
            btn = self.btn_perf_hold_global if key == "global" else self.btn_perf_hold
            if not btn.isChecked():
                return
            try:
                buf = fut.result()
            except Exception as exc:
                self._perf_status(f"hold failed · {exc}")
                return
            with self._pkp_poly_lock:
                held[key] = [buf, 0, 1.0]
            self._ensure_hardware_use("perf-hold")
            self._pkp_poly_submit(np.zeros(64, dtype=np.float32), self._PERF_SR)   # opens the audition stream
            self._perf_status(f"✋ holding · {'all instruments' if key == 'global' else progs[0]} · {hz:,.1f} Hz")
        _arm()

    def _perf_set_edit_global(self, on):
        self.edit_synth_global = bool(on)
        self._perf_status("Edit Synth GLOBAL · edits apply to every instrument" if on else "Edit Synth · selected instrument only")

    def _perf_stop_all(self):
        for b in ("btn_perf_random", "btn_perf_random_global", "btn_perf_hold", "btn_perf_hold_global"):
            w = getattr(self, b, None)
            if w is not None and w.isChecked():
                w.setChecked(False)
        self._perf_random_mode = None
        self._perf_jobs = []
        with self._pkp_poly_lock:
            self.__dict__.setdefault("_pkp_held", {}).clear()
        self._perf_status("stopped")

