    def _shared_video_clip_state(self):
        """Return the freshest project-shared Video Clip Studio state."""
        # Main-window studio wins while open.
        studio = getattr(self, "_main_video_clip_studio", None)
        if studio is not None:
            try:
                return studio.export_state()
            except Exception:
                pass
        # Otherwise use Performance's live studio when available.
        panel = getattr(self, "_performance_panel", None)
        pstudio = getattr(panel, "video_clip_studio", None) if panel is not None else None
        if pstudio is not None:
            try:
                return pstudio.export_state()
            except Exception:
                pass
        state = getattr(self, "media_workbench_state", {}) or {}
        if isinstance(state, dict):
            if isinstance(state.get("video_clip"), dict):
                return copy.deepcopy(state["video_clip"])
            perf = state.get("performance")
            if isinstance(perf, dict) and isinstance(perf.get("video_clip"), dict):
                return copy.deepcopy(perf["video_clip"])
        return {}

    def _store_shared_video_clip_state(self, clip_state):
        """Store Video Clip Studio state in both shared and Performance project slots."""
        if not isinstance(clip_state, dict):
            return
        try:
            state = getattr(self, "media_workbench_state", None)
            if not isinstance(state, dict):
                state = {}
                self.media_workbench_state = state
            state["video_clip"] = copy.deepcopy(clip_state)
            perf = state.get("performance")
            if not isinstance(perf, dict):
                perf = {}
                state["performance"] = perf
            perf["video_clip"] = copy.deepcopy(clip_state)
        except Exception:
            pass

    def _open_main_signal_lab(self):
        """Open the shared Main Window Draw / Record / Video workbench."""
        try:
            existing = getattr(self, "_main_signal_lab_dialog", None)
            if existing is not None:
                try:
                    existing.show(); existing.raise_(); existing.activateWindow(); return existing
                except RuntimeError:
                    self._main_signal_lab_dialog = None

            from signal_lab import SignalLab
            from video_clip_studio import VideoClipStudio

            dlg = QDialog(self)
            dlg.setWindowTitle("Mathematician's Groovebox — Draw / Record / Video")
            dlg.resize(1180, 880)
            lay = QVBoxLayout(dlg)
            tabs = QTabWidget(dlg)

            lab = SignalLab(self, tabs)
            tabs.addTab(lab, "✎🎙 Audio Draw / Record")

            voxel = VoxelDrawKitPanel(self, tabs)
            self._main_voxel_panel = voxel
            self._main_voxel_tab_index = tabs.addTab(voxel, "🧊 3D Voxel Draw / Record")

            video = VideoClipStudio(self, tabs)
            self._main_video_clip_studio = video
            try:
                video.restore_state(self._shared_video_clip_state())
            except Exception:
                pass
            tabs.addTab(video, "🎥 Record / Import / Draw Video")
            lay.addWidget(tabs)

            note = QLabel(
                "Video input devices are explicitly selectable in the Video tab. Camera and mic "
                "previews are independent of recording. Color→Sound and Sound→Color remain optional; "
                "Color→Sound Translation Detail is applied only at final video mix."
            )
            note.setWordWrap(True)
            lay.addWidget(note)

            self._main_signal_lab_dialog = dlg
            self._main_signal_lab_tabs = tabs

            old_close = dlg.closeEvent
            def _close_main_media(event, _dlg=dlg, _old=old_close):
                try:
                    st = getattr(self, "_main_video_clip_studio", None)
                    if st is not None:
                        self._store_shared_video_clip_state(st.export_state())
                        try: st._release_capture_devices(True)
                        except Exception:
                            try: st._stop_mic_source()
                            except Exception: pass
                except Exception:
                    pass
                self._main_video_clip_studio = None
                self._main_voxel_panel = None
                self._main_signal_lab_dialog = None
                try:
                    _old(event)
                except Exception:
                    event.accept()
            dlg.closeEvent = _close_main_media
            dlg.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
            dlg.show(); dlg.raise_()
            return dlg
        except Exception as exc:
            QMessageBox.warning(self, "Draw / Record / Video", f"Could not open media workbench:\n{exc}")

    def _composition_length_seconds(self):
        """Video end length is the composition length along tempo. Never a separate duration."""
        try:
            bpm = float(self.spin_bpm.value()) if hasattr(self, "spin_bpm") else 120.0
        except Exception:
            bpm = 120.0
        bpm = bpm if bpm > 0.0 else 120.0
        try:
            rows = int(self.spin_playlist_length.value()) if hasattr(self, "spin_playlist_length") else DEFAULT_PLAYLIST_ROWS
        except Exception:
            rows = DEFAULT_PLAYLIST_ROWS
        try:
            beats = float(self.spin_row_beats.value()) if hasattr(self, "spin_row_beats") else 8.0
        except Exception:
            beats = 8.0
        rows = max(1, rows)
        beats = beats if beats > 0.0 else 8.0
        return (rows * beats) * 60.0 / bpm

    def _open_video_planner(self):
        """Video Planner — edit VideoAssemblyRules for a seeded video plan."""
        try:
            existing = getattr(self, "_video_planner_dialog", None)
            if existing is not None:
                try:
                    existing.show(); existing.raise_(); existing.activateWindow(); return existing
                except RuntimeError:
                    self._video_planner_dialog = None
            dlg = QDialog(self)
            dlg.setWindowTitle("Video Planner — Assembly Rules")
            dlg.resize(520, 460)
            form = QFormLayout(dlg)
            seed = QSpinBox(); seed.setRange(0, 2_000_000_000)
            try:
                seed.setValue(int(getattr(self, "seed", 0) or 0))
            except Exception:
                seed.setValue(0)
            form.addRow("Seed", seed)
            scale = QDoubleSpinBox(); scale.setRange(0.25, 4.0); scale.setSingleStep(0.25); scale.setDecimals(2)
            scale.setValue(float(getattr(self, "_scene_scale_override", 1.0) or 1.0))
            scale.setToolTip("Scale the canonical field. 1.0 = native. Any resolution still shows the same picture.")
            form.addRow("Scene scale", scale)
            def _apply_scale():
                self._scene_scale_override = float(scale.value())
            scale.valueChanged.connect(_apply_scale)
            length = self._composition_length_seconds()
            duration = QLabel("%.2f s  ·  locked to composition × tempo" % length)
            duration.setToolTip(
                "Video end length is playlist rows × row beats ÷ BPM. "
                "It is not a separate video duration."
            )
            form.addRow("Length (composition)", duration)
            form.addRow(QLabel(
                "This planner scopes assembly rules for the current project only. "
                "It does not invent a second timeline. Length always equals the composition along tempo."
            ))
            contract = QLabel(
                "Lookup contract: video is a projection of this composition.\n"
                "Length = playlist rows × row beats ÷ BPM. Not a free duration.\n"
                "FPS, transition, color map, and phase change how the same field is drawn. They do not change the music.\n"
                "Integrity rejects a black or silent export. Seed script overrides these fields when a seeded plan is active.\n"
                "Color map: default = scene · density = luminance · phase = time hue · seed_hue = seed tint.\n"
                "Phase: meum = bounded pulse · isn = invert after midpoint · seed = seed scale · none = untouched.\n"
                "Transition: none · cut = midpoint dip · crossfade = open · lattice_morph = stripe on the lattice."
            )
            contract.setWordWrap(True)
            contract.setStyleSheet("color:#9fd4ff; font-size:9pt;")
            form.addRow(contract)
            fps = QSpinBox(); fps.setRange(1, 120); fps.setValue(int(getattr(self, "_last_export_fps", 30) or 30))
            form.addRow("FPS", fps)
            transition = QComboBox(); transition.addItems(["none", "cut", "crossfade", "lattice_morph"])
            form.addRow("Transition", transition)
            phase = QComboBox(); phase.addItems(["meum", "isn", "seed", "none"])
            form.addRow("Temporal phase", phase)
            color = QComboBox(); color.addItems(["default", "density", "phase", "seed_hue"])
            form.addRow("Color map", color)
            # GROOVEBOX_R23R_VIDEO_CHANNEL_SWAP_20261031: R/G/B channel routing.
            _prev = getattr(self, "_video_assembly_rules", None) or {}
            for _cb, _key in ((color, "color_map"), (transition, "transition_mode"), (phase, "temporal_phase_source")):
                _v = str(_prev.get(_key, "") or "")
                if _v and _cb.findText(_v) >= 0:
                    _cb.setCurrentText(_v)
            chan = QComboBox(); chan.addItems(["RGB", "RBG", "GRB", "GBR", "BRG", "BGR"])
            chan.setCurrentText(str(_prev.get("channel_order", "RGB") or "RGB"))
            chan.setToolTip("Output R, G, B are taken from these input channels (RGB = unchanged, BGR = red/blue swapped).")
            form.addRow("Channel order (R/G/B)", chan)
            chan_mix = QDoubleSpinBox(); chan_mix.setRange(0.0, 1.0); chan_mix.setSingleStep(0.05)
            chan_mix.setValue(float(_prev.get("channel_mix", 1.0) if _prev.get("channel_mix") is not None else 1.0))
            chan_mix.setToolTip("0 = original colours, 1 = full channel swap; values between blend the two (colour convolution).")
            form.addRow("Channel mix", chan_mix)
            ui_conv = QCheckBox("Apply this colour convolve to the whole Groovebox UI and text")
            ui_conv.setChecked(bool(_prev.get("ui_color_convolve", False)))
            ui_conv.setToolTip("Every window's colours and text take the same channel order / mix as the video.")
            form.addRow(ui_conv)

            def _apply_ui_conv(*_a):
                try:
                    from ui_color_convolve import set_convolve
                    set_convolve(chan.currentText(), float(chan_mix.value()) if ui_conv.isChecked() else 0.0)
                except Exception as _uc_exc:
                    print(f"[UI convolve] {_uc_exc}")
            for _sig in (ui_conv.toggled, chan.currentTextChanged, chan_mix.valueChanged):
                _sig.connect(_apply_ui_conv)
            # GROOVEBOX_R23R_LSYSTEM_VIDEO_REITERATION_20261031: Fractal Seed
            # Offset / Dilation for the L-system video reiteration layer.
            # Offset shifts the L-system's starting angle (rotation phase);
            # Dilation scales the step size (geometry expansion/contraction).
            # Both are stored in VideoAssemblyRules and passed through to the
            # L-system video renderer, so they apply when Fractal Seed Mode is
            # ON (tracking the Fractal Seed) and when it is OFF (Koch-like default).
            fs_offset = QDoubleSpinBox(); fs_offset.setRange(-360.0, 360.0); fs_offset.setSingleStep(1.0)
            fs_offset.setValue(float(_prev.get("fractal_seed_offset", 0.0) if _prev.get("fractal_seed_offset") is not None else 0.0))
            fs_offset.setToolTip("Rotation phase offset (degrees) applied to the L-system reiteration layer's starting angle. Shifts the geometry's orientation.")
            form.addRow("Fractal Seed Offset (°)", fs_offset)
            fs_dilation = QDoubleSpinBox(); fs_dilation.setRange(0.05, 10.0); fs_dilation.setSingleStep(0.05)
            fs_dilation.setValue(float(_prev.get("fractal_seed_dilation", 1.0) if _prev.get("fractal_seed_dilation") is not None else 1.0))
            fs_dilation.setToolTip("Step-size scale for the L-system reiteration layer. 1.0 = default fit; >1 expands the geometry; <1 contracts it.")
            form.addRow("Fractal Seed Dilation", fs_dilation)
            parts = QSpinBox(); parts.setRange(1, 4096); parts.setValue(64)
            form.addRow("Target part count", parts)
            opacity = QDoubleSpinBox(); opacity.setRange(0.0, 1.0); opacity.setSingleStep(0.05); opacity.setValue(1.0)
            form.addRow("Overlay opacity", opacity)
            integrity = QCheckBox("Integrity check (non-degenerate video)"); integrity.setChecked(True)
            form.addRow(integrity)
            status = QLabel("Writes VideoAssemblyRules. Seed script output overrides these when a seeded video plan is active.")
            status.setWordWrap(True)
            form.addRow(status)
            btns = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Close)
            form.addRow(btns)

            def _save():
                script_out = self._seed_script_video_overrides()
                try:
                    from groovebox_v3_runtime import load_assembly_rules
                    rules = load_assembly_rules(int(seed.value()), {
                        "duration_seconds": float(self._composition_length_seconds()),
                        "fps": float(fps.value()),
                        "transition_mode": transition.currentText(),
                        "temporal_phase_source": phase.currentText(),
                        "color_map": color.currentText(),
                        "target_part_count": int(parts.value()),
                        "overlay_opacity": float(opacity.value()),
                        "integrity_check": bool(integrity.isChecked()),
                        **script_out,
                    })
                except Exception:
                    rules = None
                payload = {
                    "seed": int(seed.value()),
                    "duration_seconds": float(self._composition_length_seconds()),
                    "locked_to_composition": True,
                    "fps": float(fps.value()),
                    "transition_mode": transition.currentText(),
                    "temporal_phase_source": phase.currentText(),
                    "color_map": color.currentText(),
                    "channel_order": chan.currentText(),
                    "channel_mix": float(chan_mix.value()),
                    "ui_color_convolve": bool(ui_conv.isChecked()),
                    # GROOVEBOX_R23R_LSYSTEM_VIDEO_REITERATION_20261031:
                    # Fractal Seed Offset / Dilation for the L-system video layer.
                    "fractal_seed_offset": float(fs_offset.value()),
                    "fractal_seed_dilation": float(fs_dilation.value()),
                    "target_part_count": int(parts.value()),
                    "overlay_opacity": float(opacity.value()),
                    "integrity_check": bool(integrity.isChecked()),
                }
                payload.update(script_out)
                self._video_assembly_rules = payload
                if rules is not None:
                    try:
                        payload["fingerprint"] = rules.fingerprint()
                    except Exception:
                        pass
                status.setText("Saved. Fingerprint: %s%s" % (
                    payload.get("fingerprint", "local"),
                    " · seed script applied" if script_out else "",
                ))
            btns.button(QDialogButtonBox.StandardButton.Save).clicked.connect(_save)
            btns.rejected.connect(dlg.close)
            btns.accepted.connect(_save)
            self._video_planner_dialog = dlg
            dlg.show(); dlg.raise_(); dlg.activateWindow()
            return dlg
        except Exception as exc:
            QMessageBox.warning(self, "Video Planner", f"Could not open Video Planner:\n{exc}")
            return None

    def _seed_script_video_overrides(self):
        """If the seed script writes video-plan keys, those win over the planner."""
        out = {}
        try:
            text = self._seed_text() if hasattr(self, "_seed_text") else ""
        except Exception:
            text = ""
        if not text:
            return out
        keys = (
            "fps", "transition_mode", "temporal_phase_source",
            "color_map", "target_part_count", "overlay_opacity", "integrity_check",
        )
        for line in str(text).splitlines():
            if "=" not in line:
                continue
            k, _, v = line.partition("=")
            k = k.strip().lower().replace(" ", "_")
            if k not in keys:
                continue
            v = v.strip().strip("\"'")
            try:
                if k in ("fps", "target_part_count"):
                    out[k] = int(float(v))
                elif k in ("duration_seconds", "overlay_opacity"):
                    out[k] = float(v)
                elif k == "integrity_check":
                    out[k] = v.lower() in ("1", "true", "yes", "on")
                else:
                    out[k] = v
            except Exception:
                out[k] = v
        return out

    def _canonical_sync_snapshot(self):
        """Live canonical identity the UI should show."""
        snap = {}
        try:
            snap["seed"] = int(getattr(self, "seed", 0) or 0)
        except Exception:
            snap["seed"] = 0
        try:
            snap["composition_fingerprint"] = self.visual_composition_fingerprint()
        except Exception:
            snap["composition_fingerprint"] = ""
        try:
            snap["canonical_id"] = self.lbl_canonical_fp.text() if hasattr(self, "lbl_canonical_fp") else ""
        except Exception:
            snap["canonical_id"] = ""
        rules = getattr(self, "_video_assembly_rules", None)
        snap["video_assembly_rules"] = dict(rules) if isinstance(rules, dict) else {}
        snap["seed_script_video_overrides"] = self._seed_script_video_overrides()
        try:
            snap["composition_length_seconds"] = self._composition_length_seconds()
        except Exception:
            snap["composition_length_seconds"] = None
        try:
            snap["bpm"] = float(self.spin_bpm.value()) if hasattr(self, "spin_bpm") else 120.0
        except Exception:
            snap["bpm"] = 120.0
        try:
            snap["sharp_smooth"] = int(self.dial_project_sharp.value()) if hasattr(self, "dial_project_sharp") else 50
        except Exception:
            snap["sharp_smooth"] = 50
        try:
            snap["sidechain"] = dict(getattr(self, "sidechain_state", {}) or {})
        except Exception:
            snap["sidechain"] = {}
        try:
            snap["audio_owner"] = getattr(self, "_audio_owner", None)
        except Exception:
            snap["audio_owner"] = None
        try:
            snap["seed_script"] = (self._seed_text() if hasattr(self, "_seed_text") else "")[:2000]
        except Exception:
            snap["seed_script"] = ""
        return snap

    def _open_canonical_data(self):
        """Canonical Data window (CANONICAL_DATA_WINDOW_20261102): the written canonical identity the UI is synced to,
        now with a section picker, a text filter, live auto-refresh, copy / save, and a live overview of what the
        canonicals currently own. Read-only: it never changes the project or the audio."""
        try:
            dlg = QDialog(self)
            dlg.setWindowTitle("Canonical Data — UI sync")
            dlg.resize(820, 640)
            lay = QVBoxLayout(dlg)
            note = QLabel("The written canonical identity this window is synced to. Pick a section, filter the text, or let it follow the project live.")
            note.setWordWrap(True)
            lay.addWidget(note)
            top = QHBoxLayout()
            sect = QComboBox(); sect.addItem("All sections")
            flt = QLineEdit(); flt.setPlaceholderText("Filter lines (e.g. seed, goava, bpm)…"); flt.setClearButtonEnabled(True)
            auto = QCheckBox("Live (every 2 s)")
            top.addWidget(QLabel("Section")); top.addWidget(sect, 1); top.addWidget(flt, 2); top.addWidget(auto)
            lay.addLayout(top)
            overview = QLabel(""); overview.setWordWrap(True)
            overview.setStyleSheet("color:#91d9bd; font-size:9pt; font-weight:700;")
            lay.addWidget(overview)
            view = QPlainTextEdit()
            view.setReadOnly(True)
            view.setStyleSheet("font-family: Consolas, monospace; font-size: 11px;")
            lay.addWidget(view)
            state = {"snap": {}}

            def _overview():
                try:
                    banks = getattr(self, "instrument_sequence_banks", {}) or {}
                    owned = sum(1 for m in banks.values() if str((m or {}).get("canonical_owner", "")).startswith("canonical:"))
                    user = sum(1 for m in banks.values() if self._mem_has_user_steps(m))
                    ov = len(getattr(self, "canonical_runtime_overlays", {}) or {})
                    return (f"{len(banks)} instrument sequences · {owned} written by canonicals · {user} edited by you · "
                            f"{ov} canonical overlay(s) active · seed {int(getattr(self, 'seed', 0) or 0)}")
                except Exception:
                    return ""

            def _render():
                snap = state["snap"]
                key = sect.currentText()
                data = snap if key == "All sections" else {key: snap.get(key)}
                text = json.dumps(data, indent=2, default=str)
                q = flt.text().strip().lower()
                if q:
                    text = "\n".join(l for l in text.splitlines() if q in l.lower()) or "(no lines match the filter)"
                view.setPlainText(text)

            def _refresh():
                try:
                    state["snap"] = self._canonical_sync_snapshot()
                    cur = sect.currentText()
                    sect.blockSignals(True)
                    sect.clear(); sect.addItem("All sections")
                    for k in state["snap"].keys():
                        sect.addItem(str(k))
                    i = sect.findText(cur); sect.setCurrentIndex(i if i >= 0 else 0)
                    sect.blockSignals(False)
                    overview.setText(_overview())
                except Exception as exc:
                    state["snap"] = {"error": str(exc)}
                _render()

            def _copy():
                QApplication.clipboard().setText(view.toPlainText())

            def _save():
                path, _ = QFileDialog.getSaveFileName(dlg, "Save canonical data", "canonical_data.json", "JSON (*.json)")
                if path:
                    try:
                        with open(path, "w", encoding="utf-8") as f:
                            json.dump(state["snap"], f, indent=2, default=str)
                    except Exception as exc:
                        QMessageBox.warning(dlg, "Canonical Data", str(exc))

            timer = QTimer(dlg); timer.setInterval(2000); timer.timeout.connect(_refresh)
            auto.toggled.connect(lambda on: timer.start() if on else timer.stop())
            sect.currentIndexChanged.connect(lambda *_: _render())
            flt.textChanged.connect(lambda *_: _render())
            btns = QHBoxLayout()
            for label, fn in (("Refresh", _refresh), ("Copy", _copy), ("Save JSON…", _save), ("Close", dlg.close)):
                bt = QPushButton(label); bt.clicked.connect(fn); btns.addWidget(bt)
            lay.addLayout(btns)
            _refresh()
            dlg.show(); dlg.raise_(); dlg.activateWindow()
            return dlg
        except Exception as exc:
            QMessageBox.warning(self, "Canonical Data", str(exc))
            return None

    def _record_audio_to_slot(self, local=False):
        """Open the layered Draw/Record workbench and arm a recording layer.

        Record is intentionally non-destructive: captured takes remain separate
        reusable layers with relative-time scalars and can be meshed with drawn
        or imported layers before Send Global / Send -> Selected.
        """
        try:
            from signal_lab import SignalLab
            dlg = QDialog(self)
            dlg.setWindowTitle("Mathematician's Groovebox — Layered Record / Draw Wave")
            dlg.resize(980, 820)
            lay = QVBoxLayout(dlg)
            target = self._current_instrument_name() if local else "GLOBAL"
            note = QLabel(f"Recording workbench target: {target}. Add/record/draw multiple layers, set relative time scalars, render, inspect spectrum, then send to the desired slot.")
            note.setWordWrap(True); lay.addWidget(note)
            lab = SignalLab(self, dlg); lay.addWidget(lab)
            dlg.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
            self._record_signal_lab_dialog = dlg
            dlg.show(); dlg.raise_()
            # Arm a first recording prompt after the window is visible.
            if hasattr(lab, "_record_layer"):
                QTimer.singleShot(0, lab._record_layer)
        except Exception as exc:
            QMessageBox.warning(self, "Layered Record", f"Could not open recording workbench:\n{exc}")

    def _media_file_filter(self):
        return ("Media Files (*.MCC *.mcc *.wav *.mp3 *.flac *.ogg *.oga *.m4a *.aac *.aiff *.aif *.opus *.caf *.alac *.wma *.ape *.wv "
                "*.mp4 *.mov *.mkv *.webm *.avi *.m4v *.mpeg *.mpg *.flv *.ts *.m2ts *.mts *.3gp *.3g2 *.ogv *.vob);;Audio Files (*.wav *.mp3 *.flac *.ogg *.oga *.m4a *.aac *.aiff *.aif *.opus *.caf *.alac *.wma *.ape *.wv);;"
                "Video Files (*.mp4 *.mov *.mkv *.webm *.avi *.m4v *.mpeg *.mpg *.flv *.ts *.m2ts *.mts *.3gp *.3g2 *.ogv *.vob);;All Files (*)")

    def _decode_media_audio(self, file_path):
        """Decode any supported audio/video container to mono float32 via ffmpeg (MCC natively)."""
        import subprocess
        try:
            import mcc_media as _mm
            if _mm.media_kind(file_path) in ("audio", "video"):
                # GROOVEBOX_R23R_MCC_MEDIA_CODEC_20261101: lossless MCC decodes without ffmpeg.
                x, _sr, _hdr = _mm.decode_audio(file_path)
                x = np.asarray(x, dtype=np.float64)
                if x.ndim == 2:
                    x = x.mean(axis=1)
                arr = np.nan_to_num(x.astype(np.float32), nan=0.0, posinf=0.0, neginf=0.0)
                peak = float(np.max(np.abs(arr))) if arr.size else 0.0
                if peak > 0.0:
                    arr /= peak
                return arr, int(_sr)
        except Exception as _mcc_exc:
            print(f"[Media] MCC decode: {_mcc_exc}")
        ffmpeg = resolve_local_tool("ffmpeg", required=True)
        # GROOVEBOX_R23R_AUDIO_DEPTH_RATE_20261101: keep the file's native sample rate
        # (was forced to 44.1 kHz, resampling 48/96 kHz material on import).
        _native_sr = 44100
        try:
            _probe = resolve_local_tool("ffprobe", required=False)
            if _probe:
                _r = subprocess.run([_probe, "-v", "error", "-select_streams", "a:0", "-show_entries", "stream=sample_rate",
                                     "-of", "csv=p=0", str(file_path)], capture_output=True, text=True, timeout=15)
                _v = int(float((_r.stdout or "").strip().splitlines()[0]))
                if 8000 <= _v <= 768000:
                    _native_sr = _v
        except Exception:
            pass
        cmd = [ffmpeg, "-v", "error", "-i", str(file_path), "-vn", "-ac", "1", "-ar", str(_native_sr), "-f", "f32le", "-"]
        proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False, timeout=1800)   # STALL_GUARD_20261102: a stalled drive can no longer hang decode forever
        if proc.returncode != 0:
            raise RuntimeError(proc.stderr.decode(errors="replace")[-1400:] or "ffmpeg could not decode media audio")
        arr = np.frombuffer(proc.stdout, dtype=np.float32).copy()
        arr = np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0)
        if arr.size:
            peak = float(np.max(np.abs(arr)))
            if peak > 0.0:
                arr /= peak
        return arr, _native_sr

    def clear_local_carrier(self):
        """Detach the selected operator's local media carrier/sample.

        The source file is never deleted.  The mutation is project-undoable and
        invalidates live/render state immediately so an old sample cannot remain
        audible through a cached play/export buffer.
        """
        name = self._current_instrument_name()
        store = getattr(self, "instrument_media_samples", {}) or {}
        if name not in store:
            self._refresh_operator_sample_ui()
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(f"📂 Local carrier already clear · {name}")
            return
        try:
            self._push_undo(f"Clear local carrier · {name}")
        except Exception:
            pass
        try:
            store.pop(name, None)
            self.instrument_media_samples = store
        finally:
            self._refresh_operator_sample_ui()
        self._refresh_after_file_input(reason="local_carrier_cleared")
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText(f"📂 Local carrier cleared · {name}")

    def _clear_global_carrier_state(self, refresh=True, update_ui=True):
        """Clear all global carrier references/buffers without deleting media.

        This internal form intentionally does not create an undo snapshot; callers
        such as project-load and undo/redo use it while applying authoritative state.
        """
        self.imported_waveform = None
        self.imported_sample_rate = 44100
        self.imported_wav_path = ""
        self.imported_video_path = ""
        self.imported_video_meta = {}
        self.media_carrier_slot = {}
        self.carrier_binding_mode = ""
        self.carrier_binding_source = ""
        self.carrier_bound_layers_state = {}
        if update_ui:
            if hasattr(self, "lbl_wav_carrier"):
                self.lbl_wav_carrier.setText("Carrier: none")
                self.lbl_wav_carrier.setToolTip("")
            # Do not leave the previous carrier waveform painted after detach.
            try:
                if hasattr(self, "visual_oscilloscope"):
                    self.visual_oscilloscope.update_waveform(np.zeros(100, dtype=np.float32))
                if hasattr(self, "video_synth_viewer"):
                    self.video_synth_viewer.update_from_audio(np.zeros(100, dtype=np.float32))
            except Exception:
                pass
        # Explicit cache invalidation makes detach authoritative even if refresh
        # is suppressed while a larger project/undo state is being restored.
        for attr in ("play_buffer", "_canonical_unison_effect_buffer", "_seed_time_curve"):
            if hasattr(self, attr):
                try:
                    setattr(self, attr, None)
                except Exception:
                    pass
        if refresh:
            self._refresh_after_file_input(reason="global_carrier_cleared")

    def clear_global_carrier(self):
        """Detach the project-wide audio/video carrier and all carrier bindings."""
        has_state = bool(
            getattr(self, "imported_waveform", None) is not None
            or getattr(self, "imported_wav_path", "")
            or getattr(self, "imported_video_path", "")
            or getattr(self, "media_carrier_slot", None)
            or getattr(self, "carrier_binding_mode", "")
            or getattr(self, "carrier_binding_source", "")
            or getattr(self, "carrier_bound_layers_state", None)
        )
        if not has_state:
            self._clear_global_carrier_state(refresh=False, update_ui=True)
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText("📂 Global carrier already clear")
            return
        try:
            self._push_undo("Clear global carrier")
        except Exception:
            pass
        self._clear_global_carrier_state(refresh=True, update_ui=True)
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("📂 Global carrier cleared · source file kept")

    def load_sample_to_selected_operator(self):
        """Attach an audio/video-derived user sample to the active operator."""
        try:
            path, _ = QFileDialog.getOpenFileName(self, "Load Sample to Selected Operator", self._samples_dir(), self._media_file_filter())
            if not path:
                return
            import groovebox_paths
            name = self._current_instrument_name()
            path = groovebox_paths.ingest_file(path, "operator_sample", getattr(self, "_current_project_path", None), instrument=name)
            arr, sr = self._decode_media_audio(path)
            if arr.size == 0:
                raise RuntimeError("The selected media contains no decodable audio stream.")
            _is_video = Path(path).suffix.lower() in {".mp4", ".mov", ".mkv", ".webm", ".avi", ".mpeg", ".mpg", ".m4v", ".flv", ".ts", ".m2ts", ".mts", ".3gp", ".3g2", ".ogv", ".vob"}
            _video_src = str(path)
            try:
                import mcc_media as _mm
                if _mm.media_kind(path) == "video":
                    # Video bindings read through ffmpeg: give them the cached MP4 of the MCC video.
                    _is_video = True
                    _video_src = _mm.playable_path(path, resolve_local_tool("ffmpeg", required=False) or "ffmpeg")
            except Exception as _mv_exc:
                print(f"[Sample] MCC video binding: {_mv_exc}")
            self.instrument_media_samples[name] = {
                "path": str(path), "sample_rate": int(sr), "waveform": arr.astype(np.float32),
                "user_owned": True, "source_kind": "video" if _is_video else "audio",
                "video_path": _video_src if _is_video else "",
                "video_input_enabled": bool(_is_video),
            }
            self._refresh_operator_sample_ui()
            self._on_live_source_changed()
        except Exception as exc:
            print(f"[Operator Sample] load failed: {exc}")
            QMessageBox.critical(self, "Sample Load Error", str(exc))

    def reverse_selected_clip(self, from_here=False):
        """Flip the selected operator clip. Audio buffer and video path."""
        name = self._current_instrument_name() if hasattr(self, "_current_instrument_name") else ""
        rec = (getattr(self, "instrument_media_samples", {}) or {}).get(name)
        if not rec:
            QMessageBox.information(self, "Reverse clip", "Load a clip onto the selected operator first.")
            return
        wave = rec.get("waveform")
        if wave is not None:
            arr = np.asarray(wave)
            if from_here and getattr(self, "play_buffer", None) is not None and len(self.play_buffer):
                cut = int(len(arr) * (float(self.play_cursor) / float(len(self.play_buffer))))
                cut = max(0, min(cut, len(arr)))
                arr = np.concatenate([arr[:cut], arr[cut:][::-1]])
            else:
                arr = arr[::-1]
            rec["waveform"] = arr.copy()
        rec["reversed"] = not bool(rec.get("reversed"))
        self._refresh_operator_sample_ui()
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("↩ Clip reversed · %s" % name)

    def pingpong_selected_clip(self):
        name = self._current_instrument_name() if hasattr(self, "_current_instrument_name") else ""
        rec = (getattr(self, "instrument_media_samples", {}) or {}).get(name)
        if not rec or rec.get("waveform") is None:
            QMessageBox.information(self, "Ping-pong", "Load a clip first.")
            return
        arr = np.asarray(rec["waveform"])
        rec["waveform"] = np.concatenate([arr, arr[::-1]]).copy()
        rec["pingpong"] = True
        self._refresh_operator_sample_ui()

    def _on_reverse_time_toggled(self, on):
        self.reverse_time_mode = bool(on)
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("Reverse Time %s" % ("on" if on else "off"))

    def _refresh_operator_sample_ui(self):
        name = self._current_instrument_name() if hasattr(self, "instrument_selector_dropdown") else ""
        rec = (getattr(self, "instrument_media_samples", {}) or {}).get(name)
        if hasattr(self, "lbl_operator_sample"):
            if rec:
                src = os.path.basename(str(rec.get("path", "")))
                mark = " ↩" if rec.get("reversed") else ""
                mark += " ⇄" if rec.get("pingpong") else ""
                self.lbl_operator_sample.setText(f"OP SAMPLE: {src[:20]}{mark}")
                self.lbl_operator_sample.setToolTip(str(rec.get("path", "")))
            else:
                self.lbl_operator_sample.setText("OP SAMPLE: none")

    def _instrument_signature_parts(self, instrument_name):
        """Editor-state signature of one instrument: synth params, script, patch, domain.

        GROOVEBOX_R23R_GLOBAL_XMOD_SIGNATURE_20261031: shared by the operator
        sample morph and the Global XMOD pass so both derive from exactly the
        same four canonical editor-state signatures.
        """
        synth = (getattr(self, "instrument_param_state", {}) or {}).get(instrument_name, {}) or {}
        nums = []
        for k, v in synth.items():
            try: nums.append((str(k), float(v)))
            except Exception: pass
        script = str((getattr(self, "instrument_scripts", {}) or {}).get(instrument_name, "") or "")
        patch = []
        for c in getattr(self, "patch_connections", []) or []:
            if isinstance(c, dict) and (c.get("source") == instrument_name or c.get("target") == instrument_name):
                try: patch.append(float(c.get("weight", c.get("gain", 0.5))))
                except Exception: pass
        try: domain_blob = repr(getattr(self, "domain_eq_engine", None).to_json()) if getattr(self, "domain_eq_engine", None) else ""
        except Exception: domain_blob = ""
        return nums, script, patch, domain_blob

    @staticmethod
    def _sample_native_layer(sample, sample_sr, local_t):
        """A recording exactly as recorded, placed at its clip start.

        Output index i reads the sample at time local_t[i]: identical samples when
        the rates match, linear interpolation only for a sample-rate conversion.
        Silence after the recording ends (no looping, no stretching).
        """
        a = np.asarray(sample, dtype=np.float32).ravel()
        lt = np.asarray(local_t, dtype=np.float64).ravel()
        if a.size == 0 or lt.size == 0:
            return np.zeros(lt.size, dtype=np.float32)
        pos = lt * float(max(1, int(sample_sr)))
        idx = np.rint(pos)
        if np.all(np.abs(pos - idx) < 1e-6):
            ii = idx.astype(np.int64)
            ok = (ii >= 0) & (ii < a.size)
            out = np.zeros(lt.size, dtype=np.float32)
            out[ok] = a[ii[ok]]
            return out
        out = np.interp(pos, np.arange(a.size, dtype=np.float64), a.astype(np.float64), left=0.0, right=0.0)
        return out.astype(np.float32)

    def _sample_panel_morph(self, sample, instrument_name, local_t, warp_only=False):
        """Deterministic 50/50 user-sample morph using synth/script/patch/domain state.

        This is deliberately PRE-CANONICAL: half of the local sample remains
        untouched user data; the other half is a bounded transform whose phase,
        spectral tilt and modulation are derived from the active synth panel,
        script text, incident patch gains and domain definition. It never writes
        back into canonical state.
        """
        a = np.asarray(sample, dtype=np.float32).ravel()
        if a.size == 0:
            return a
        n = len(local_t)
        if n <= 0:
            return np.zeros(0, dtype=np.float32)
        x = np.linspace(0.0, 1.0, a.size, endpoint=False)
        y = np.linspace(0.0, 1.0, n, endpoint=False)
        base = np.interp(y, x, a).astype(np.float64)
        morph_cfg = getattr(self, "sample_morph_state", {}) or {}
        if not bool(morph_cfg.get("enabled", True)):
            return base.astype(np.float32)
        import hashlib
        nums, script, patch, domain_blob = self._instrument_signature_parts(instrument_name)
        blob = repr(sorted(nums)) + "|" + script + "|" + repr(patch) + "|" + domain_blob
        h = hashlib.sha256(blob.encode("utf-8", "replace")).digest()
        u = np.frombuffer(h[:24], dtype=np.uint8).astype(np.float64) / 255.0
        phase = math.tau * (0.13 + 0.71*u[0])
        fit = float(np.clip(morph_cfg.get("adaptive_fit", 0.50), 0.0, 1.0))
        depth = (0.08 + 0.20*u[1]) * (0.25 + 0.75*fit)
        tilt = (-0.25 + 0.50*u[2]) * (0.25 + 0.75*fit)
        mod = 0.50 + 0.50*ot_sin_vec_equiv(math.tau*(1.0 + 3.0*u[3])*y + phase)
        transformed = base * (1.0 + depth*(2.0*mod-1.0))
        if tilt != 0.0 and n > 8:
            spec = np.fft.rfft(transformed)
            freqs = np.linspace(0.0, 1.0, spec.size)
            spec *= np.power(np.maximum(freqs, 1.0/n), tilt)
            transformed = np.fft.irfft(spec, n=n)
        peak = float(np.max(np.abs(transformed)))
        transformed = transformed / max(1.0, peak)
        # Optional phase-lock is capped at 50% and acts only on the transformed
        # branch. It therefore cannot displace the untouched 50% user waveform.
        try:
            pl = float(np.clip(morph_cfg.get("phase_lock", 0.50), 0.0, 1.0))
            if pl > 0.0 and transformed.size > 8:
                ref = np.fft.rfft(base)
                spec = np.fft.rfft(transformed)
                mag = np.abs(spec); ph = np.angle(spec); rph = np.angle(ref)
                spec = mag * np.exp(1j*((1.0-pl)*ph + pl*rph))
                transformed = np.fft.irfft(spec, n=transformed.size)
        except Exception:
            pass
        if warp_only:
            # Caller supplies the untouched 50% (the native-rate recording).
            transformed = np.nan_to_num(transformed, nan=0.0, posinf=0.0, neginf=0.0)
            pk = float(np.max(np.abs(transformed))) if transformed.size else 0.0
            if pk > 1.0: transformed = transformed / pk
            return np.clip(transformed, -1.0, 1.0).astype(np.float32)
        # Exact minimum 50% user-data contribution.
        out = 0.50*base + 0.50*transformed
        if bool(morph_cfg.get("guard", True)):
            out = np.nan_to_num(out, nan=0.0, posinf=0.0, neginf=0.0)
            pk = float(np.max(np.abs(out))) if out.size else 0.0
            if pk > 1.0: out = out / pk
        return np.clip(out, -1.0, 1.0).astype(np.float32)

    def load_wav_carrier_dialog(self):
        """Load a WAV file as the global carrier/reference waveform."""
        try:
            file_path, _ = QFileDialog.getOpenFileName(
                self, "Load Audio/Video Carrier", self._samples_dir(),
                "Media Files (*.wav *.mp3 *.flac *.ogg *.oga *.m4a *.aac *.aiff *.aif *.opus *.caf *.alac *.wma *.ape *.wv *.mp4 *.mov *.mkv *.webm *.avi *.m4v *.mpeg *.mpg *.flv *.ts *.m2ts *.mts *.3gp *.3g2 *.ogv *.vob);;Audio Files (*.wav *.mp3 *.flac *.ogg *.oga *.m4a *.aac *.aiff *.aif *.opus *.caf *.alac *.wma *.ape *.wv);;Video Files (*.mp4 *.mov *.mkv *.webm *.avi *.m4v *.mpeg *.mpg *.flv *.ts *.m2ts *.mts *.3gp *.3g2 *.ogv *.vob);;All Files (*)"
            )
            if not file_path:
                return
            self._load_wav_path(file_path)
        except Exception as e:
            print(f"[WAV Carrier] Load failed: {e}")
            QMessageBox.critical(self, "WAV Load Error", str(e))

    @staticmethod
    def _normalize_voxel_record(v):
        """Return [x,y,z,r,g,b,a], accepting legacy XYZ-only voxel records."""
        if not isinstance(v, (list, tuple)) or len(v) < 3:
            return None
        try:
            xyz=[int(v[0]), int(v[1]), int(v[2])]
        except Exception:
            return None
        rgba=[80,220,200,220]
        if len(v) >= 6:
            try: rgba[:3]=[max(0,min(255,int(v[i]))) for i in (3,4,5)]
            except Exception: pass
        if len(v) >= 7:
            try: rgba[3]=max(0,min(255,int(v[6])))
            except Exception: pass
        return xyz + rgba

    def _normalize_voxel_records(self, seq):
        out={}
        for v in (seq or []):
            rec=self._normalize_voxel_record(v)
            if rec is not None: out[tuple(rec[:3])] = rec
        return [out[k] for k in sorted(out)]

    def open_voxel_viewer(self):
        """Open (or raise) the shared voxel viewer window."""
        try:
            from memory_guard import estimate_window_bytes
            if not self._memory_ok(estimate_window_bytes("voxel"), "open Voxel Viewer"):
                return None
            existing = getattr(self, '_voxel_viewer_dialog', None)
            if existing is not None:
                try:
                    existing.refresh()
                    existing.show(); existing.raise_(); existing.activateWindow()
                    return existing
                except RuntimeError:
                    self._voxel_viewer_dialog = None
            dlg = VoxelViewerDialog(self, self)
            self._voxel_viewer_dialog = dlg
            dlg.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
            def _cleanup(event, _dlg=dlg):
                try:
                    if getattr(self, '_voxel_viewer_dialog', None) is _dlg:
                        self._voxel_viewer_dialog = None
                except Exception:
                    pass
                event.accept()
            dlg.closeEvent = _cleanup
            dlg.show(); dlg.raise_()
            return dlg
        except Exception as exc:
            try:
                QMessageBox.warning(self, 'Voxel Viewer', f'Could not open viewer:\n{exc}')
            except Exception:
                pass
            return None

    def open_voxel_draw_kit(self):
        """Compatibility entry point: open shared Draw/Record and select its voxel tab."""
        dlg=self._open_main_signal_lab()
        try:
            panel=getattr(self,'_main_voxel_panel',None)
            if panel is not None:
                panel.grid_spin.setValue(int(getattr(self,'voxel_grid_size',16) or 16))
                panel.alias_slider.setValue(int(getattr(self,'voxel_alias_pct',0) or 0))
                panel.blend_slider.setValue(int(getattr(self,'voxel_paint_blend_pct',86) or 86))
                panel._sync_color_button(); panel.refresh_views()
            tabs=getattr(self,'_main_signal_lab_tabs',None)
            if tabs is not None and hasattr(self,'_main_voxel_tab_index'):
                tabs.setCurrentIndex(int(self._main_voxel_tab_index))
        except Exception: pass
        return dlg

    def import_3d_model_dialog(self):
        path, _ = QFileDialog.getOpenFileName(
            self, 'Import 3D Model', '',
            '3D Models (*.obj *.ply *.stl *.gltf *.glb *.json);;Wavefront OBJ (*.obj);;PLY (*.ply);;STL (*.stl);;glTF (*.gltf *.glb);;Voxel JSON (*.json);;All Files (*)'
        )
        if not path:
            return
        try:
            self._load_3d_model_path(path)
        except Exception as exc:
            QMessageBox.critical(self, '3D Import Error', str(exc))

    def _extract_model_vertices(self, file_path):
        """Dependency-free vertex reader for OBJ, ASCII PLY/STL and simple glTF JSON."""
        ext = os.path.splitext(file_path)[1].lower()
        verts = []
        if ext == '.obj':
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                for line in f:
                    if line.startswith('v '):
                        p = line.split()
                        if len(p) >= 4:
                            try: verts.append((float(p[1]), float(p[2]), float(p[3])))
                            except Exception: pass
        elif ext == '.ply':
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                lines = f.readlines()
            if lines and lines[0].strip().lower() == 'ply':
                vcount = 0; end = 0
                for i, line in enumerate(lines[:500]):
                    if line.startswith('element vertex '):
                        try: vcount = int(line.split()[-1])
                        except Exception: vcount = 0
                    if line.strip() == 'end_header':
                        end = i + 1; break
                for line in lines[end:end+vcount]:
                    p = line.split()
                    if len(p) >= 3:
                        try: verts.append((float(p[0]), float(p[1]), float(p[2])))
                        except Exception: pass
        elif ext == '.stl':
            with open(file_path, 'rb') as f:
                raw = f.read()
            # ASCII first; otherwise parse binary triangle vertices.
            if raw[:5].lower() == b'solid' and b'vertex' in raw[:100000]:
                txt = raw.decode('utf-8', errors='ignore')
                for m in re.finditer(r'(?im)^\s*vertex\s+([-+0-9.eE]+)\s+([-+0-9.eE]+)\s+([-+0-9.eE]+)', txt):
                    try: verts.append(tuple(float(m.group(i)) for i in (1,2,3)))
                    except Exception: pass
            elif len(raw) >= 84:
                import struct as _struct
                try:
                    ntri = _struct.unpack_from('<I', raw, 80)[0]
                    off = 84
                    for _ in range(min(ntri, 500000)):
                        if off + 50 > len(raw): break
                        vals = _struct.unpack_from('<12fH', raw, off)
                        verts.extend([(vals[3],vals[4],vals[5]), (vals[6],vals[7],vals[8]), (vals[9],vals[10],vals[11])])
                        off += 50
                except Exception:
                    pass
        # glTF/GLB remains a valid imported model reference even when this
        # dependency-free core cannot decode compressed accessors.  Export can
        # still preserve/copy the original and the user can draw voxels over it.
        return verts

    def _vertices_to_voxels(self, verts, grid_size=None):
        n = max(4, min(64, int(grid_size or getattr(self, 'voxel_grid_size', 16) or 16)))
        if not verts:
            return []
        a = np.asarray(verts, dtype=np.float64)
        a = a[np.all(np.isfinite(a), axis=1)]
        if a.size == 0:
            return []
        lo = a.min(axis=0); hi = a.max(axis=0)
        span = hi-lo
        span = np.where(span == 0.0, 1.0, span)
        q = np.rint((a-lo)/span * (n-1)).astype(int)
        return [list(v) + [80,220,200,220] for v in sorted(set(tuple(map(int,row)) for row in q.tolist()))]

    def _load_3d_model_path(self, file_path):
        ext = os.path.splitext(file_path)[1].lower()
        if ext == '.json':
            n = self._load_voxel_json(file_path, layered=False)
            self.imported_3d_model_path = file_path
            return n
        if ext not in {'.obj','.ply','.stl','.gltf','.glb'}:
            raise RuntimeError('Unsupported 3D model type. Use OBJ, PLY, STL, glTF, GLB or voxel JSON.')
        if not getattr(self, '_undo_in_flight', False):
            try: self._push_undo('Import 3D model')
            except Exception: pass
        verts = self._extract_model_vertices(file_path)
        self.imported_3d_model_path = file_path
        self.imported_3d_model_meta = {
            'format': ext.lstrip('.'), 'vertex_count': len(verts),
            'voxelized': bool(verts), 'alias_pct': int(getattr(self, 'voxel_alias_pct', 0) or 0),
        }
        if verts:
            self.voxel_cells = self._vertices_to_voxels(verts, getattr(self, 'voxel_grid_size', 16))
        if hasattr(self, 'lbl_3d_model'):
            self.lbl_3d_model.setText('3D: ' + os.path.basename(file_path)[:20])
            self.lbl_3d_model.setToolTip(file_path)
        if getattr(self, '_voxel_dialog', None) is not None:
            try: self._voxel_dialog.canvas.update()
            except Exception: pass
        if getattr(self, '_main_voxel_panel', None) is not None:
            try: self._main_voxel_panel.refresh_views()
            except Exception: pass
        self._refresh_after_file_input(reason='3d_model')
        return len(verts)

    def _voxelize_imported_video_frame(self, grid_size=None, z_slice=0):
        path = str(getattr(self, 'imported_video_path', '') or '')
        if not path or not os.path.isfile(path): raise RuntimeError('Load or record a video first.')
        ffmpeg = self._resolve_ffmpeg_binary() if hasattr(self, '_resolve_ffmpeg_binary') else shutil.which('ffmpeg')
        if not ffmpeg: raise RuntimeError('FFmpeg is required to voxelize a video frame.')
        n = max(4, min(64, int(grid_size or getattr(self, 'voxel_grid_size', 16) or 16)))
        cmd = [ffmpeg, '-v', 'error', '-ss', '0.25', '-i', path, '-frames:v', '1',
               '-vf', f'scale={n}:{n}:flags=area,format=rgb24', '-f', 'rawvideo', 'pipe:1']
        proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=60)
        if proc.returncode != 0 or len(proc.stdout) < n*n*3:
            raise RuntimeError(proc.stderr.decode(errors='replace')[-1000:] or 'Could not decode a video frame.')
        rgb = np.frombuffer(proc.stdout[:n*n*3], dtype=np.uint8).reshape(n,n,3)
        records={}
        for c in (getattr(self,'voxel_cells',[]) or []):
            rec=self._normalize_voxel_record(c)
            if rec is not None: records[tuple(rec[:3])] = rec[3:7]
        depth_max=max(1,n//4); z0=max(0,min(n-1,int(z_slice)))
        alpha=int(round(255.0*max(0,min(100,int(getattr(self,'voxel_paint_blend_pct',86) or 86)))/100.0))
        for y in range(n):
            for x in range(n):
                rr,gg,bb=[int(q) for q in rgb[y,x]]
                lum=int(round(0.2126*rr+0.7152*gg+0.0722*bb))
                if lum < 24: continue
                depth=max(1,int(round((lum/255.0)*depth_max)))
                for dz in range(depth): records[(x,y,min(n-1,z0+dz))]=[rr,gg,bb,alpha]
        self.voxel_grid_size=n
        self.voxel_cells=[list(k)+list(records[k]) for k in sorted(records)]
        try: self._refresh_canonical_fingerprint()
        except Exception: pass
        if getattr(self,'_main_voxel_panel',None) is not None:
            try: self._main_voxel_panel.refresh_views()
            except Exception: pass
        return len(self.voxel_cells)

    def _write_voxel_obj(self, file_path):
        records=[self._normalize_voxel_record(c) for c in (getattr(self,'voxel_cells',[]) or [])]
        records=[r for r in records if r is not None]
        alias=int(getattr(self,'voxel_alias_pct',0) or 0); levels=self._canonical_levels() if hasattr(self,'_canonical_levels') else {}
        mtl_path=os.path.splitext(file_path)[0]+'.mtl'; mtl_name=os.path.basename(mtl_path)
        mats={tuple(r[3:7]) for r in records}
        with open(mtl_path,'w',encoding='utf-8') as mf:
            mf.write('# Mathematician Groovebox voxel RGBA materials\n')
            for rgba in sorted(mats):
                r,g,b,a=rgba; name=f'rgba_{r}_{g}_{b}_{a}'
                mf.write(f'newmtl {name}\nKd {r/255:.6f} {g/255:.6f} {b/255:.6f}\nd {a/255:.6f}\nillum 2\n\n')
        with open(file_path,'w',encoding='utf-8') as f:
            f.write('# Mathematician\'s Groovebox colored voxel/model export\n')
            f.write(f'# alias={alias} canonical_levels={json.dumps(levels,sort_keys=True)}\nmtllib {mtl_name}\n')
            f.write('s 1\n' if alias>=50 else 's off\n'); vi=1
            for x,y,z,r,g,b,a in records:
                f.write(f'usemtl rgba_{r}_{g}_{b}_{a}\n')
                vs=[(x,y,z),(x+1,y,z),(x+1,y+1,z),(x,y+1,z),(x,y,z+1),(x+1,y,z+1),(x+1,y+1,z+1),(x,y+1,z+1)]
                for vx,vy,vz in vs: f.write(f'v {vx:.6f} {vy:.6f} {vz:.6f} {r/255:.6f} {g/255:.6f} {b/255:.6f}\n')
                for aa,bb,cc,dd in ((0,1,2,3),(4,7,6,5),(0,4,5,1),(1,5,6,2),(2,6,7,3),(4,0,3,7)):
                    f.write(f'f {vi+aa} {vi+bb} {vi+cc} {vi+dd}\n')
                vi+=8

    def _write_voxel_ply(self, file_path):
        records=[self._normalize_voxel_record(c) for c in (getattr(self,'voxel_cells',[]) or [])]
        records=[r for r in records if r is not None]
        with open(file_path,'w',encoding='utf-8') as f:
            f.write('ply\nformat ascii 1.0\ncomment Mathematician Groovebox colored voxel centers\n')
            f.write(f'comment alias {int(getattr(self,"voxel_alias_pct",0) or 0)}\n')
            f.write(f'element vertex {len(records)}\nproperty float x\nproperty float y\nproperty float z\nproperty uchar red\nproperty uchar green\nproperty uchar blue\nproperty uchar alpha\nend_header\n')
            for x,y,z,r,g,b,a in records: f.write(f'{x+0.5:.6f} {y+0.5:.6f} {z+0.5:.6f} {r} {g} {b} {a}\n')

    def _write_voxel_json(self, file_path):
        """Write a simple, re-importable voxel JSON (compatible with Random Object exports)."""
        records = [self._normalize_voxel_record(c) for c in (getattr(self, 'voxel_cells', []) or [])]
        records = [r for r in records if r is not None]
        payload = {
            "grid_size": int(getattr(self, 'voxel_grid_size', 16) or 16),
            "alias_pct": int(getattr(self, 'voxel_alias_pct', 0) or 0),
            "voxels": records,
            "source": "groovebox_voxel_export",
        }
        os.makedirs(os.path.dirname(os.path.abspath(file_path)) or '.', exist_ok=True)
        with open(file_path, 'w', encoding='utf-8') as f:
            json.dump(payload, f, indent=2)

    def _load_voxel_json(self, file_path, layered=False):
        """Load a voxel JSON (Random Object or native export) into the project."""
        with open(file_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
        if not isinstance(data, dict):
            raise ValueError('Voxel JSON must be an object')
        cells = data.get('voxels') or data.get('cells') or []
        if not isinstance(cells, list):
            raise ValueError('No voxels array in JSON')
        norm = self._normalize_voxel_records(cells)
        if not norm:
            raise ValueError('No valid voxel records found')
        grid = int(data.get('grid_size') or getattr(self, 'voxel_grid_size', 16) or 16)
        grid = max(4, min(64, grid))
        if layered:
            old = list(getattr(self, 'voxel_cells', []) or [])
            self.voxel_cells = (old + norm)[-1500:]
        else:
            self.voxel_cells = norm
        self.voxel_grid_size = grid
        if 'alias_pct' in data:
            try:
                self.voxel_alias_pct = max(0, min(100, int(data['alias_pct'])))
            except Exception:
                pass
        # Refresh any open editors
        for attr in ('_main_voxel_panel', '_perf_voxel_panel'):
            panel = getattr(self, attr, None)
            if panel is not None and hasattr(panel, 'refresh_views'):
                try:
                    panel.grid_spin.setValue(grid)
                    panel.refresh_views()
                except Exception:
                    pass
        return len(norm)

    def export_3d_model_dialog(self):
        if not self._prepare_export_project('3D model export'):
            return
        default = self._export_name('voxels', '.obj', self._exports_dir())
        path, selected = QFileDialog.getSaveFileName(self, 'Export 3D / Voxel Model', default,
            'Wavefront OBJ (*.obj);;PLY Point/Voxel Centers (*.ply);;Voxel JSON (*.json)')
        if not path:
            return
        ext = os.path.splitext(path)[1].lower()
        if ext not in ('.obj', '.ply', '.json'):
            if 'JSON' in str(selected):
                ext = '.json'
            elif 'PLY' in str(selected):
                ext = '.ply'
            else:
                ext = '.obj'
            path += ext
        cells = list(getattr(self, 'voxel_cells', []) or [])
        if not cells:
            # If no authored voxels exist, preserve an imported source model by copy.
            src = str(getattr(self, 'imported_3d_model_path', '') or '')
            if src and os.path.isfile(src) and os.path.splitext(src)[1].lower() == ext:
                shutil.copy2(src, path)
            else:
                QMessageBox.warning(self, '3D Export', 'No voxel geometry to export. Draw voxels or import a readable OBJ/PLY/STL/JSON first.')
                return None
        else:
            try:
                if ext == '.ply':
                    self._write_voxel_ply(path)
                elif ext == '.json':
                    self._write_voxel_json(path)
                else:
                    self._write_voxel_obj(path)
            except Exception as exc:
                QMessageBox.critical(self, '3D Export Error', str(exc))
                return None
        # Full project provenance sidecar lets a 3D artifact restore the same
        # canonical levels/RAND token/voxel state without bloating model headers.
        try:
            payload = json.loads(self._export_provenance_payload())
            with open(path + '.mgpr', 'w', encoding='utf-8') as f:
                json.dump(payload, f, indent=2, sort_keys=True)
        except Exception:
            pass
        self.export_counter += 1
        if hasattr(self, 'scope_status_label'):
            self.scope_status_label.setText('🧊 3D export complete → ' + os.path.basename(path))
        return path


    # =====================================================================
    # MEDIA_IMPORT_FEATURE — WAV/video import and stream parsing
    # Revert: delete this marked method block and the marked global UI/state.
    # =====================================================================
    def load_media_dialog(self):
        """Load audio, video, or a 3D model into the shared Draw/Record media path."""
        try:
            file_path, _ = QFileDialog.getOpenFileName(
                self, "Load Media / 3D", "",
                "Media + 3D (*.wav *.mp3 *.flac *.ogg *.m4a *.aac *.aiff *.opus *.caf *.wma *.mp4 *.mov *.mkv *.webm *.avi *.m4v *.mpeg *.mpg *.flv *.ts *.m2ts *.mts *.3gp *.3g2 *.ogv *.vob *.obj *.ply *.stl *.gltf *.glb);;"
                "3D Models (*.obj *.ply *.stl *.gltf *.glb *.json);;Video Files (*.mp4 *.mov *.mkv *.webm *.avi *.m4v *.mpeg *.mpg *.flv *.ts *.m2ts *.mts *.3gp *.3g2 *.ogv *.vob);;All Files (*)"
            )
            if not file_path: return
            ext = os.path.splitext(file_path)[1].lower()
            if ext in {".obj",".ply",".stl",".gltf",".glb",".json"}:
                self._load_3d_model_path(file_path)
            elif ext == ".wav":
                self._load_wav_path(file_path)
            elif ext in {".mp4",".mov",".mkv",".webm",".avi",".m4v",".mpeg",".mpg",".flv",".ts",".m2ts",".mts",".3gp",".3g2",".ogv",".vob"}:
                self._load_video_path(file_path)
            else:
                # Existing general decoder handles other audio formats.
                try:
                    arr, sr = self._decode_media_audio(file_path)
                    self.imported_waveform = np.asarray(arr, dtype=np.float32)
                    self.imported_sample_rate = int(sr)
                    self.imported_wav_path = file_path
                    self._refresh_after_file_input(reason="audio_media")
                except Exception:
                    self._load_video_path(file_path)
        except Exception as e:
            print(f"[Media] Load failed: {e}")
            QMessageBox.critical(self, "Media Load Error", str(e))

    def _load_wav_path(self, file_path):
        """Shared audio-carrier loader; WAV is native, other audio formats use ffmpeg."""
        if os.path.splitext(str(file_path))[1].lower() != ".wav":
            data, sample_rate = self._decode_media_audio(file_path)
            arr = np.asarray(data, dtype=np.float32).ravel()
            self.imported_waveform = arr
            self.imported_sample_rate = int(sample_rate)
            self.imported_wav_path = str(file_path)
            self.imported_video_path = ""
            self.imported_video_meta = {}
            self._update_imported_media_ui(file_path, sample_rate, arr.size, is_video=False)
            self._refresh_after_file_input(reason="audio_carrier")
            return
        data = None
        sample_rate = None
        if wavfile is not None:
            sample_rate, data = wavfile.read(file_path)
        else:
            with wave.open(file_path, "rb") as wf:
                sample_rate = wf.getframerate()
                channels = wf.getnchannels()
                width = wf.getsampwidth()
                raw = wf.readframes(wf.getnframes())
                if width == 1:
                    data = (np.frombuffer(raw, dtype=np.uint8).astype(np.float32) - 128.0) / 128.0
                elif width == 2:
                    data = np.frombuffer(raw, dtype=np.int16).astype(np.float32) / 32768.0
                elif width == 4:
                    data = np.frombuffer(raw, dtype=np.int32).astype(np.float32) / 2147483648.0
                else:
                    raise RuntimeError("Unsupported PCM WAV sample width.")
                if channels > 1:
                    data = data.reshape(-1, channels).mean(axis=1)
        arr = np.asarray(data)
        if arr.ndim > 1:
            arr = arr.mean(axis=1)
        # Normalize integer/float WAVs without changing their relative waveform structure.
        if np.issubdtype(arr.dtype, np.integer):
            info = np.iinfo(arr.dtype)
            denom = float(max(abs(info.min), info.max)) or 1.0
            arr = arr.astype(np.float32) / denom
        else:
            arr = arr.astype(np.float32, copy=False)
        arr = np.nan_to_num(arr.ravel(), nan=0.0, posinf=0.0, neginf=0.0)
        if arr.size == 0:
            raise RuntimeError("The selected WAV contains no audio samples.")
        peak = float(np.max(np.abs(arr)))
        if peak > 0.0:
            arr /= peak
        self.imported_waveform = arr
        self.imported_sample_rate = int(sample_rate)
        self.imported_wav_path = file_path
        # A new WAV carrier supersedes a previous video carrier, but keeps its audio behavior.
        self.imported_video_path = ""
        self.imported_video_meta = {}
        self._update_imported_media_ui(file_path, sample_rate, arr.size, is_video=False)
        print(f"[WAV Carrier] Loaded {file_path} ({sample_rate} Hz, {arr.size} samples)")
        self._refresh_after_file_input(reason="wav_carrier")

    def _load_video_path(self, file_path):
        """Parse a video file: probe video metadata and extract mono PCM audio as carrier."""
        ffprobe = resolve_local_tool("ffprobe", required=True)
        ffmpeg = resolve_local_tool("ffmpeg", required=True)

        meta = {}
        if ffprobe:
            probe = subprocess.run(
                [ffprobe, "-v", "error", "-show_streams", "-show_format", "-of", "json", file_path],
                capture_output=True, text=True, check=True, timeout=120
            )
            info = json.loads(probe.stdout or "{}")
            streams = info.get("streams", [])
            v = next((x for x in streams if x.get("codec_type") == "video"), None)
            a = next((x for x in streams if x.get("codec_type") == "audio"), None)
            if v:
                fps_txt = v.get("avg_frame_rate") or v.get("r_frame_rate") or "0/1"
                try:
                    n, d = fps_txt.split("/", 1)
                    fps = float(n) / max(float(d), 1.0)
                except Exception:
                    fps = 0.0
                meta.update({
                    "width": int(v.get("width") or 0),
                    "height": int(v.get("height") or 0),
                    "fps": fps,
                    "codec": v.get("codec_name", ""),
                    "duration": float(v.get("duration") or info.get("format", {}).get("duration") or 0.0),
                })
            meta["has_audio"] = bool(a)
            meta["audio_codec"] = a.get("codec_name", "") if a else ""

        # Extract float32 mono PCM at the groovebox's native render rate.
        cmd = [
            ffmpeg, "-v", "error", "-i", file_path,
            "-vn", "-ac", "1", "-ar", "44100", "-f", "f32le", "pipe:1"
        ]
        proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=1800)
        if proc.returncode != 0 and bool(meta.get("has_audio", False)):
            raise RuntimeError(proc.stderr.decode(errors="replace")[-1200:] or "ffmpeg could not decode the video audio stream.")
        # A video-only import is a valid VISUAL carrier, but it is not an audio
        # carrier.  Older builds synthesized a duration-sized all-zero waveform;
        # that stale "carrier" could then be exported as a perfectly valid but
        # multi-megabyte silent MP3.  Keep visual identity and audio identity
        # separate instead of manufacturing silence.
        arr = np.frombuffer(proc.stdout, dtype=np.float32).copy() if proc.returncode == 0 else np.zeros(0, dtype=np.float32)
        arr = np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0)
        has_audio = bool(meta.get("has_audio", False))
        if has_audio and arr.size == 0:
            raise RuntimeError("The video reports an audio stream, but it decoded to no audio samples.")
        if arr.size:
            peak = float(np.max(np.abs(arr)))
            if peak > 0.0:
                arr /= peak
            self.imported_waveform = arr
            self.imported_wav_path = file_path
        else:
            self.imported_waveform = None
            self.imported_wav_path = ""
        self.imported_sample_rate = 44100
        self.imported_video_path = file_path
        self.imported_video_meta = meta
        self._update_imported_media_ui(file_path, 44100, arr.size, is_video=True)
        print(f"[Video Carrier] Parsed {file_path}: {meta}; audio samples={arr.size}; visual_only={not bool(arr.size)}")
        self._refresh_after_file_input(reason="video_carrier")

    def _update_imported_media_ui(self, file_path, sample_rate, sample_count, is_video=False):
        name = os.path.basename(file_path)
        visual_only = bool(is_video and int(sample_count or 0) == 0)
        tag = "VIDEO (visual)" if visual_only else ("VIDEO" if is_video else "WAV")
        if hasattr(self, "lbl_wav_carrier"):
            self.lbl_wav_carrier.setText(f"{tag}: {name[:22]}")
            self.lbl_wav_carrier.setToolTip(file_path)
        if hasattr(self, "scope_status_label"):
            extra = ""
            if is_video:
                m = self.imported_video_meta
                extra = f" · {m.get('width',0)}×{m.get('height',0)} · {m.get('fps',0.0):.2f} fps"
                if visual_only:
                    extra += " · no audio carrier"
            self.scope_status_label.setText(
                f"📂 {tag} carrier loaded · {name} · {sample_rate} Hz{extra}"
            )
        waveform = getattr(self, "imported_waveform", None)
        if hasattr(self, "visual_oscilloscope"):
            if waveform is None:
                try:
                    self.visual_oscilloscope.update_waveform(np.zeros(100, dtype=np.float32))
                except Exception:
                    pass
                return
            preview = waveform[:min(waveform.size, max(1, int(sample_rate * 0.5)))]
            if preview.size:
                idx = np.linspace(0, preview.size - 1, 100).astype(int)
                self.visual_oscilloscope.update_waveform(preview[idx])
                if hasattr(self, "video_synth_viewer"):
                    self.video_synth_viewer.update_from_audio(preview[idx])

    def _resample_carrier(self, target_len, target_rate):
        """sCode-routed memoized carrier resampling for repeated Play/Export."""
        if self.imported_waveform is None or target_len <= 0:
            return None
        _opt = getattr(self, "_scode_optimizer", None)
        if _opt is None:
            return self._resample_carrier_uncached(target_len, target_rate)
        try:
            _path = str(getattr(self, "imported_wav_path", "") or getattr(self, "imported_video_path", "") or "")
            _mtime = 0
            _size = 0
            if _path and os.path.exists(_path):
                _st = os.stat(_path); _mtime = int(getattr(_st, "st_mtime_ns", 0)); _size = int(_st.st_size)
            _speed = float(self.spin_import_speed.value()) if getattr(self, "spin_import_speed", None) is not None else 1.0
            _scrub_on = bool(getattr(self, "chk_speed_scrub", None) and self.chk_speed_scrub.isChecked())
            _scrub_depth = float(self.spin_speed_scrub.value()) if getattr(self, "spin_speed_scrub", None) is not None else 0.0
            _seed = self._seed_text() if hasattr(self, "_seed_text") else str(self.get_numeric_seed())
            _payload = (_path, _mtime, _size, int(np.asarray(self.imported_waveform).size),
                        int(getattr(self, "imported_sample_rate", 44100) or 44100), int(target_len),
                        int(target_rate), round(_speed, 9), int(_scrub_on), round(_scrub_depth, 9), _seed)
            return _opt.memoized_result(
                "media_carrier_resample", _payload,
                lambda: self._resample_carrier_uncached(target_len, target_rate), max_entries=8
            )
        except Exception:
            return self._resample_carrier_uncached(target_len, target_rate)

    def _resample_carrier_uncached(self, target_len, target_rate):
        """Return the loaded carrier resampled/looped to the render duration.

        When a seed script is present, a mild deterministic gain scale derived
        from the evaluated seed field is applied so file carriers respond to
        the same per-composition seed as the instruments (list seeds use the
        mean of evaluated components; scripts use get_numeric_seed()).
        """
        if self.imported_waveform is None or target_len <= 0:
            return None
        src = np.asarray(self.imported_waveform, dtype=np.float32).ravel()
        if src.size == 0:
            return None
        src_duration = src.size / max(float(getattr(self, "imported_sample_rate", 44100) or 44100), 1.0)
        target_duration = target_len / max(float(target_rate), 1.0)
        src_rate = float(getattr(self, "imported_sample_rate", 44100) or 44100)
        # IMPORT_SPEED_2026: varispeed. At speed s the output consumes
        # s·target_duration of natural source seconds, so the resample advance
        # per output sample is (s·D0)/L — pitch and tempo shift together while
        # the output length stays target_len. s == 1.0 keeps the byte-exact
        # legacy path so nothing changes when the new control is untouched.
        import_speed = 1.0
        isp = getattr(self, "spin_import_speed", None)
        if isp is not None:
            try:
                import_speed = float(isp.value())
            except Exception:
                import_speed = 1.0
        import_speed = float(np.clip(import_speed, 0.05, 8.0))
        # SPEED_SCRUB_2026: (base, depth) seed a deterministic per-row speed lane;
        # when the lane is off this is exactly the plain constant-speed path.
        scrub_on = bool(getattr(self, "chk_speed_scrub", None) and self.chk_speed_scrub.isChecked())
        scrub_depth = 0.0
        if scrub_on:
            try:
                scrub_depth = float(getattr(self, "spin_speed_scrub", None).value()) if getattr(self, "spin_speed_scrub", None) is not None else 0.0
            except Exception:
                scrub_depth = 0.0
        scrub_on = scrub_on and scrub_depth > 0.0
        if not scrub_on:
            scrub_depth = 0.0
        if import_speed == 1.0 and not scrub_on:
            desired = max(2, int(round(target_duration * src_rate)))
            if src_duration < target_duration:
                if src_duration == 0.0:
                    return np.zeros(target_len, dtype=np.float32)
                src = np.tile(src, int(np.ceil(target_duration / src_duration)))
            src = src[:desired]
            if src.size != desired:
                src = src[:desired]
            if src.size != target_len:
                x_old = np.linspace(0.0, 1.0, src.size, endpoint=False)
                x_new = np.linspace(0.0, 1.0, target_len, endpoint=False)
                src = np.interp(x_new, x_old, src).astype(np.float32)
            else:
                src = src.astype(np.float32, copy=False)
        else:
            D0 = max(2, int(round(target_duration * src_rate)))
            if scrub_on:
                # SCRUB_LANE_2026: a closed-form per-row speed curve.  Each
                # playlist row draws a unit residue from (seed, row) mapped into
                # [1-depth, 1+depth], smoothly interpolated across output samples,
                # then multiplied by the base speed.  Positions are the cumulative
                # integral of the per-sample advance, so the pitch/speed sweep is
                # continuous (a single monotone resample, no per-row seams) and
                # fully reproducible — a reverse engineer needs only base, depth,
                # rows and the seed.
                try:
                    _rows = int(getattr(self, 'spin_playlist_length').value()) if getattr(self, 'spin_playlist_length', None) is not None else DEFAULT_PLAYLIST_ROWS
                except Exception:
                    _rows = 32
                _rows = max(1, int(_rows))
                try:
                    _seed_n = float(self.get_numeric_seed() or 0.0)
                except Exception:
                    _seed_n = 0.0
                _seed_i = int(_safe_int_seed(_seed_n))
                _mults = np.empty(_rows, dtype=np.float64)
                for _ri in range(_rows):
                    _h = (int(_seed_i) ^ (int(_ri + 1) * 0x9E3779B1)) & 0x7FFFFFFF
                    _u = ((_h ^ (_h >> 16)) * 0x45D9F3B) & 0x7FFFFFFF
                    _mults[_ri] = 1.0 + scrub_depth * (2.0 * (float(_u % 100000) / 100000.0) - 1.0)
                _u_samp = np.arange(target_len, dtype=np.float64) * float(_rows) / float(max(target_len, 1))
                _row_sel = np.clip(np.floor(_u_samp).astype(np.intp), 0, _rows - 1)
                _f0 = _u_samp - np.floor(_u_samp)
                _m0 = _mults[_row_sel]
                _m1 = _mults[np.clip(_row_sel + 1, 0, _rows - 1)]
                _speed_curve = (_m0 + (_m1 - _m0) * _f0).astype(np.float64)
                advance = (import_speed * D0) / float(target_len)
                step = advance * _speed_curve
                step = np.where(step < 0.0, 0.0, step)
                pos = np.cumsum(step) - step[0]
                need = max(D0, int(np.ceil(np.max(pos))) + 2)
                if src.size < need:
                    if src.size == 0:
                        return np.zeros(target_len, dtype=np.float32)
                    src = np.tile(src, int(np.ceil(need / float(src.size))))
                src = src[:need]
                idx = np.arange(need, dtype=np.float64)
                src = np.interp(np.clip(pos, 0.0, float(need - 1)), idx, src).astype(np.float32)
            else:
                need = max(D0, int(round(D0 * import_speed)))
                if src.size < need:
                    if src.size == 0:
                        return np.zeros(target_len, dtype=np.float32)
                    src = np.tile(src, int(np.ceil(need / float(src.size))))
                src = src[:need]
                pos = np.arange(target_len, dtype=np.float64) * (import_speed * D0) / float(target_len)
                idx = np.arange(need, dtype=np.float64)
                src = np.interp(pos, idx, src).astype(np.float32)
        # Seed-responsive carrier gain (composition-state evaluation)
        try:
            vals = list(self.get_seed_values(t_value=0.0) or [])
            if vals:
                mean_s = float(sum(abs(v) for v in vals) / len(vals)) if vals else 0.0
                # Map into a gentle [0.55, 1.0] range — never silences the carrier.
                scale = float(np.clip(0.55 + 0.45 * ((mean_s % 1000.0) / 1000.0), 0.55, 1.0))
                src = (src * scale).astype(np.float32)
        except Exception:
            pass
        return src

    def _spectral_fit_voice(self, voice, target, amount=1.0):
        """Fit broad target spectrum and gently phase-lock the generated voice to it."""
        voice = np.asarray(voice, dtype=np.float32)
        target = np.asarray(target, dtype=np.float32)
        n = min(voice.size, target.size)
        if n < 32:
            return voice
        v = voice[:n]
        t = target[:n]
        nfft = 1 << int(np.ceil(np.log2(n)))
        v_spec = np.fft.rfft(v, nfft)
        t_spec = np.fft.rfft(t, nfft)
        v_mag = np.abs(v_spec)
        t_mag = np.abs(t_spec)
        smooth = max(3, min(63, int(nfft / 2048) * 2 + 3))
        kernel = np.ones(smooth, dtype=np.float32) / float(smooth)
        t_mag = np.convolve(t_mag, kernel, mode="same")
        ratio_raw = np.divide(t_mag, v_mag, out=np.ones_like(t_mag), where=v_mag != 0.0)
        ratio = np.clip(ratio_raw, 0.65, 1.8)

        # ON-PHASE invariant: never blend target phase into the carrier.  Only
        # magnitude is fitted, so the carrier's instantaneous phase/frequency
        # remains untouched.  This avoids the gritty phase cancellation produced
        # by repeated target-phase mixing.
        fit_amt = float(np.clip(amount, 0.0, 1.0))
        fitted_mag = v_mag * (1.0 + fit_amt * (ratio - 1.0))
        v_mag_nonzero = v_mag > 0.0
        phase_unit = np.ones_like(v_spec, dtype=np.complex128)
        phase_unit[v_mag_nonzero] = v_spec[v_mag_nonzero] / v_mag[v_mag_nonzero]
        fitted_spec = fitted_mag * phase_unit
        fitted = np.fft.irfft(fitted_spec, nfft)[:n].astype(np.float32)
        peak = float(np.max(np.abs(fitted))) if fitted.size else 0.0
        original_peak = float(np.max(np.abs(v))) if v.size else 0.0
        if peak > 0.0 and math.isfinite(peak) and original_peak > 0.0 and math.isfinite(original_peak):
            fitted *= original_peak / peak
        elif original_peak <= 0.0 or not math.isfinite(original_peak):
            fitted = np.zeros_like(fitted)
        if n < voice.size:
            out = voice.copy(); out[:n] = fitted; return out
        return fitted


    def _phase_lock_voice_to_import(self, voice, target, amount=0.5):
        """Phase-steer a synthesized voice toward a loaded carrier without replacing it.

        `amount=0.5` is the invariant imported-sample phase-lock share: half of the
        phase remains the canonical oscillator phase and half follows the loaded
        carrier phase. Magnitude is retained from the canonical voice, so scalar
        synth pitch/amp and envelope controls continue to govern the composition.
        """
        voice = np.asarray(voice, dtype=np.float32)
        target = np.asarray(target, dtype=np.float32)
        n = min(voice.size, target.size)
        if n < 32:
            return voice
        v = voice[:n]
        t = target[:n]
        nfft = 1 << int(np.ceil(np.log2(n)))
        vs = np.fft.rfft(v, nfft)
        ts = np.fft.rfft(t, nfft)
        vm = np.abs(vs)
        vp = np.unwrap(np.angle(vs))
        tp = np.unwrap(np.angle(ts))
        a = float(np.clip(amount, 0.0, 1.0))
        # Circular phase interpolation, preserving canonical magnitude.
        d = np.angle(np.exp(1j * (tp - vp)))
        phase = vp + a * d
        out = np.fft.irfft(vm * np.exp(1j * phase), nfft)[:n].astype(np.float32)
        # Preserve exact canonical RMS/peak scale.
        op = float(np.max(np.abs(out))) if out.size else 0.0
        vp0 = float(np.max(np.abs(v))) if v.size else 0.0
        if op > 0.0 and math.isfinite(op) and vp0 > 0.0 and math.isfinite(vp0):
            out *= vp0 / op
        elif vp0 <= 0.0 or not math.isfinite(vp0):
            out = np.zeros_like(out)
        if n < voice.size:
            z = voice.copy(); z[:n] = out; return z
        return out


    def _on_synth_count_text_edited(self, text):
        raw = str(text).strip()
        egg = raw == "" or raw in {"0", "1"}
        changed = egg != bool(getattr(self, "_goava_count_easter_egg", False))
        self._goava_count_easter_egg = egg
        if egg:
            # Do not let the invalid transient value trigger an expensive
            # ensemble resize. This is visual-only easter-egg state.
            try:
                self.parametric_background._reseed()
                self.parametric_background.update()
            except Exception:
                pass
        elif changed:
            try:
                self.parametric_background._reseed()
                self.parametric_background.update()
            except Exception:
                pass

    def _on_synth_count_changed(self, new_count):
        """Resize active synth bank (2–STRUCT_MAX_VOICES) with harmonic re-spacing of free voices."""
        # Invalid typed values are an easter-egg state, not a real resize.
        if getattr(self, "_goava_count_easter_egg", False):
            return
        # PROJECT_UNDO_2026: snapshot the whole project before the orchestration
        # change so the resize (which re-spaces voices and refactors the playlist)
        # is fully reversible and keeps every surviving instrument's data.
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo(f"Instrument resize → {int(new_count)}")
        try:
            new_count = int(max(2, min(STRUCT_MAX_VOICES, new_count)))
        except Exception:
            return
        old_names = list(getattr(self, "instrument_names_48", []) or [])
        if len(old_names) == new_count and old_names:
            return
        # Track user-locked instruments (have net effect / touched steps)
        locked = set()
        for name in old_names:
            try:
                if self._instrument_has_net_effect(name):
                    locked.add(name)
            except Exception:
                pass
        # Resize by stable identity, never by lock status. Existing identities keep
        # their ordinal position; only genuinely new voices are appended. This is
        # essential for resize invariance: adding/removing voices must not remap an
        # existing oscillator onto another instrument's tuning or sequence state.
        generated_names = list(generate_synth_names(new_count, DEFAULT_INSTRUMENT_LIST) or [])
        final_names = list(old_names[:new_count])
        used = set(final_names)
        for candidate in generated_names:
            if len(final_names) >= new_count:
                break
            if candidate not in used:
                final_names.append(candidate)
                used.add(candidate)
        while len(final_names) < new_count:
            candidate = f"Operator_{len(final_names)+1}"
            if candidate in used:
                candidate = f"Operator_{len(final_names)+1}_{len(used)}"
            final_names.append(candidate)
            used.add(candidate)

        # RESIZE_FREQUENCY_IDENTITY: snapshot the *effective* carrier frequency
        # before changing ensemble cardinality.  A ratio can be stable while the
        # product harmonic_freq*tuning_ratio is not; that was the source of the
        # remaining selected-voice pitch drop.  Surviving identities therefore carry
        # an explicit absolute frequency anchor through resize.
        old_param_state = getattr(self, "instrument_param_state", {}) or {}
        ratios = harmonic_spacing_ratios(max(2, new_count))
        stable_ratios = {}
        stable_freq_hz = {}
        old_names_set = set(old_names)
        base_before = float(self.spin_base_frequency.value()) if hasattr(self, "spin_base_frequency") else 432.0
        for i, name in enumerate(final_names):
            prior = old_param_state.get(name, {}) if isinstance(old_param_state, dict) else {}
            prior = prior if isinstance(prior, dict) else {}
            if name in old_names_set:
                try:
                    tr = float(prior.get("tuning_ratio", prior.get("tuning", 1.0)))
                except Exception:
                    tr = 1.0
                if tr < 0.0:
                    tr = 0.0
                try:
                    # harmonic_freq is the actual oscillator carrier before the
                    # tuning ratio is applied in the renderer.
                    hf = float(prior.get("harmonic_freq", base_before * MEUM_POWERS_36[old_names.index(name) % 36]))
                except Exception:
                    hf = base_before * MEUM_POWERS_36[old_names.index(name) % 36]
                stable_ratios[name] = tr
                stable_freq_hz[name] = max(20.0, hf * tr)
            else:
                # New identities: use evaluated per-index seed, not sha256(name).
                try:
                    h = int(self._instrument_seed_int(i, name=name))
                except Exception:
                    h = i * 9973
                tr = float(ratios[h % len(ratios)])
                stable_ratios[name] = tr
                idx = i % len(MEUM_POWERS_36)
                stable_freq_hz[name] = max(20.0, base_before * float(MEUM_POWERS_36[idx]) * tr)

        # Rebuild sequencer memory: keep locked state, init free
        old_mem = dict(getattr(self, "instrument_sequencer_memory", {}) or {})
        old_banks = copy.deepcopy(getattr(self, "instrument_sequence_banks", {}) or {})
        old_selected = dict(getattr(self, "instrument_selected_sequence", {}) or {})
        seq_len = int(self.spin_seq_length.value()) if hasattr(self, "spin_seq_length") else DEFAULT_SEQUENCE_LENGTH
        new_mem = {}
        new_banks = {}
        new_selected = {}
        # Protect user data first: a shrink parks every user-programmed voice it removes, and a
        # later grow that brings the same identity back restores it exactly.
        parked = self.__dict__.setdefault("_resize_parked_voices", {})
        _old_params = getattr(self, "instrument_param_state", {}) or {}
        _old_scripts = getattr(self, "instrument_scripts", {}) or {}
        for name in old_names:
            if name not in used and name in locked:
                parked[name] = {
                    "banks": copy.deepcopy(old_banks.get(name)),
                    "selected": old_selected.get(name),
                    "params": copy.deepcopy(_old_params.get(name)),
                    "script": _old_scripts.get(name),
                }
        restored = {}
        for name in final_names:
            if name not in old_names_set and name in parked:
                restored[name] = parked.pop(name)
                rp = restored[name].get("params") or {}
                if rp.get("frequency_identity_hz"):
                    stable_freq_hz[name] = float(rp["frequency_identity_hz"])
                    stable_ratios[name] = float(rp.get("tuning_ratio", stable_ratios[name]))
        for i, name in enumerate(final_names):
            if name in restored and restored[name].get("banks"):
                old_banks[name] = restored[name]["banks"]
                _sel = restored[name].get("selected")
                old_selected[name] = int(_sel) if _sel in old_banks[name] else min(old_banks[name])
                old_mem[name] = old_banks[name][old_selected[name]]
                if isinstance(restored[name].get("params"), dict):
                    self.instrument_param_state[name] = copy.deepcopy(restored[name]["params"])
            if name in old_mem and name in locked:
                new_mem[name] = old_mem[name]
            elif name in old_mem:
                # Free but existed — keep structure, allow engines to reshape
                new_mem[name] = old_mem[name]
            else:
                new_mem[name] = {
                    "steps": [False] * seq_len,
                    "gates": [True] * seq_len,
                    "amplitudes": [1.0] * seq_len,
                    "pitches": [1.0] * seq_len,
                    "probabilities": [100] * seq_len,
                    "offsets": [0.0] * seq_len,
                }
            # Preserve every numbered sequence for surviving instruments.
            if name in old_banks and old_banks[name]:
                new_banks[name] = old_banks[name]
                new_selected[name] = int(old_selected.get(name, min(old_banks[name])))
            else:
                new_mem[name].setdefault("pattern_length", seq_len)
                new_banks[name] = {1: new_mem[name]}
                new_selected[name] = 1

            # Preserve the exact effective carrier for every surviving identity.
            # We deliberately rewrite harmonic_freq from the preserved product so
            # later canonical/effect passes cannot reintroduce an ensemble-count
            # dependent pitch shift.  New identities receive their deterministic
            # first anchor.
            params = dict((getattr(self, "instrument_param_state", {}) or {}).get(name, {}) or {})
            params["tuning_ratio"] = stable_ratios[name]
            params["frequency_identity_hz"] = stable_freq_hz[name]
            # Record the base against which this absolute identity was authored.
            # Without this denominator, a project whose base is not 432 Hz can be
            # reinterpreted against the historical default on its first retune.
            params["frequency_identity_base_hz"] = max(1e-9, float(base_before))
            params["frequency_identity_ratio"] = float(stable_freq_hz[name]) / max(1e-9, float(base_before))
            _stable_ratio = stable_ratios[name]
            params["harmonic_freq"] = (stable_freq_hz[name] / _stable_ratio) if _stable_ratio != 0.0 else 0.0
            if not hasattr(self, "instrument_param_state"):
                self.instrument_param_state = {}
            self.instrument_param_state[name] = params

        self.instrument_names_48 = final_names
        # Drop renames for voices removed by the resize and reject collisions
        # with newly appended canonical keys before rebuilding the dropdown.
        try:
            _display = self._sanitized_instrument_display_names(
                getattr(self, "instrument_display_names", {})
            )
            self.instrument_display_names.clear()
            self.instrument_display_names.update(_display)
            self._sync_instrument_name_box()
        except Exception:
            pass
        self.instrument_sequence_banks = new_banks
        self.instrument_selected_sequence = new_selected
        self.instrument_sequencer_memory = {
            name: new_banks[name].get(new_selected.get(name, 1), next(iter(new_banks[name].values())))
            for name in final_names
        }
        # Refresh scripts for new names
        if not hasattr(self, "instrument_scripts") or self.instrument_scripts is None:
            self.instrument_scripts = {}
        for i, name in enumerate(final_names):
            if name in restored and restored[name].get("script"):
                self.instrument_scripts[name] = restored[name]["script"]
            if name not in self.instrument_scripts:
                self.instrument_scripts[name] = (
                    f"# Script workspace for {name}\n"
                    f"# Full graph context: t,t_norm,x,y,z,seed,seed_w,graph_*,domain_value\n"
                    f"def evaluate_wave(x, y, z, t=0.0, t_norm=0.0, graph=None):\n"
                    f"    base = ot_sin_vec_equiv(x * {((i) % 12) + 1}.0) * ot_cos_vec_equiv(y) - z\n"
                    f"    return {{'wave': base * (0.75 + 0.25 * graph_u), 'amp': 0.75 + 0.25 * graph_v, 'pan': 2.0 * graph_w - 1.0}}"
                )
        # Update dropdown
        if hasattr(self, "instrument_selector_dropdown"):
            current = self.instrument_selector_dropdown.currentText()
            self.instrument_selector_dropdown.blockSignals(True)
            self.instrument_selector_dropdown.clear()
            self.instrument_selector_dropdown.addItems(final_names)
            if current in final_names:
                self.instrument_selector_dropdown.setCurrentText(current)
            elif final_names:
                self.instrument_selector_dropdown.setCurrentIndex(0)
            self.instrument_selector_dropdown.blockSignals(False)
        # Video synth engine layer count — scenograph density is bound
        # directly to instrument count (no separate manual override), so a
        # 2-instrument and a 128-instrument project sample the same
        # closed-form placement law at different N instead of diverging.
        if hasattr(self, "video_synth_engine") and self.video_synth_engine is not None:
            try:
                self.video_synth_engine.set_instrument_count(new_count, smooth=True)
            except Exception:
                pass
        # ENSEMBLE_RESCALE_PLAYLIST_REFACTOR: a resize can drop instrument
        # names that unlocked/free voices used to carry (see `locked` above),
        # or introduce entirely new ones via generate_synth_names(). Without
        # this, playlist rows/automation kept pointing at operators that no
        # longer exist in instrument_names_48 after the resize.
        self._refactor_playlist_for_instrument_rescale(old_names, final_names)
        if hasattr(self, "_canonical_prune_stale_playlist_touches"):
            self._canonical_prune_stale_playlist_touches()
        self._reconvolve_free_synths_for_ensemble_resize(old_names, final_names, locked)
        self._maintain_stochastic_harmonic_phase_lock()
        # Resize is an identity-preserving transaction: keep the exact canonical
        # sequence objects for surviving instruments.  The normal toggle transaction
        # remains free to regenerate canonical material deterministically.
        self._canonical_resize_preserve_sequences = True
        try:
            self._canonical_sequence_reconcile("ensemble_resize")
            self._recompose_active_canonicals_after_resize()
        finally:
            self._canonical_resize_preserve_sequences = False
        # Mark the canonical sequence bank as the completed resize transaction.
        # Playback uses the row's canonical refs directly, so no retoggle is required.
        self._canonical_resize_sequence_generation = int(
            getattr(self, "_composition_generation_counter", 0)
        )
        if hasattr(self, "reload_active_instrument_sequencer_ui"):
            try:
                self.reload_active_instrument_sequencer_ui()
            except Exception:
                pass
        # GROOVEBOX_R23R_CONVOLUTION_DEFAULTS_20261031: the geometric preset
        # density rescales with the instrument count rescale.
        try:
            _n = self._rescale_geometric_convolution_defaults()
            if _n:
                print(f"[Geo Convolve] rescaled {_n} at-default geometric lane(s) to the new convolution density")
        except Exception:
            pass
        print(f"[Synths] Resized to {new_count}: {final_names[:6]}{'…' if new_count > 6 else ''}")

    def _reconvolve_free_synths_for_ensemble_resize(self, old_names, final_names, locked):
        """Freshly reconvolve/rewrite every non-user voice before a resize recompose."""
        state = getattr(self, "instrument_reconvolve_state", {}) or {}
        self.instrument_reconvolve_state = state
        seed = _safe_int_seed(self.get_numeric_seed()) if hasattr(self, "get_numeric_seed") else 1
        carrier = self._resample_carrier(512, 44100) if hasattr(self, "_resample_carrier") else None
        if carrier is None:
            t = np.arange(512, dtype=np.float64) / 44100.0
            base = float(self.spin_base_frequency.value()) if hasattr(self, "spin_base_frequency") else 432.0
            carrier = (ot_sin_vec_equiv(2*np.pi*base*t) + 0.5*ot_sin_vec_equiv(2*np.pi*base*MEUM*t)).astype(np.float32)
        spec = np.abs(np.fft.rfft(carrier * _hann_window(carrier.size)))
        norm = float(np.max(spec))
        for i, name in enumerate(final_names):
            if name in locked:
                continue
            # Preserve an existing voice's absolute tuning across ensemble resize.
            # Only a genuinely new identity gets its deterministic first assignment.
            prior = dict((getattr(self, "instrument_param_state", {}) or {}).get(name, {}) or {})
            ratio = float(prior.get("tuning_ratio", 1.0))
            params = getattr(self, "instrument_param_state", {}).setdefault(name, {})
            params["tuning_ratio"] = ratio
            params["reconvolve_seed"] = int(seed)
            params["reconvolve_generation"] = int(getattr(self, "_composition_generation_counter", 0) + 1)
            params["reconvolve_spectral_centroid"] = float(np.sum(np.arange(spec.size) * spec) / (np.sum(spec) * max(spec.size - 1, 1)))
            params["reconvolve_meum"] = float(MEUM)
            state[name] = {"seed": int(seed), "generation": params["reconvolve_generation"], "carrier_norm": norm, "fresh": True}

    def _recompose_active_canonicals_after_resize(self):
        """Re-enter the single authoritative canonical transaction after resize.

        Resize must never replay engines one-at-a-time: doing so lets an intermediate
        candidate become visible state and can make the playlist look sparse or make
        the result depend on engine activation history.  The normal rebuild evaluates
        the complete active SET against one clean baseline and performs one final UI
        write.
        """
        if getattr(self, "_composition_generation_guard", False):
            return
        if not self._active_engine_sources():
            return
        self._composition_generation_guard = True
        try:
            if getattr(self, "goava_active", False) and not getattr(self, "goava_note_events", None):
                self.goava_note_events = self._build_goava_composition()
            self._rebuild_active_canonical_playlist("ensemble_resize")
        finally:
            self._composition_generation_guard = False

    def _refactor_playlist_for_instrument_rescale(self, old_names, final_names):
        """
        Strip playlist/automation references to instrument names that a synth
        ensemble resize (_on_synth_count_changed) dropped. Locked (net-effect)
        instruments are preserved by name across a resize, so any row that
        genuinely still refers only to surviving instruments is left alone.

          - Engine-owned rows referencing a removed name are stale identity;
            they are cleared back to just their '@u:' user instances (if any)
            the same way engine deactivation clears a row, so the next engine
            pass repaints them fresh against the post-resize roster.
          - Pure user rows referencing a removed name have only the dangling
            reference dropped; the rest of the user's row is preserved.
        """
        valid = set(final_names)
        removed = set(old_names) - valid
        if not removed:
            return 0

        touched_rows = 0
        rows = getattr(self, "master_playlist_data", None) or []
        for entry in rows:
            if not isinstance(entry, dict):
                continue
            row_hit = False
            users = entry.get("user_instances")
            kept_users = users
            if users:
                kept_users = [u for u in users if u.split("@")[0].strip() not in removed]
                if len(kept_users) != len(users):
                    row_hit = True
            ops = entry.get("operators")
            if isinstance(ops, list) and any(o in removed for o in ops):
                row_hit = True
            if entry.get("operator") in removed:
                row_hit = True
            if not row_hit:
                continue
            if entry.get("generated_by_engine"):
                entry.clear()
                if kept_users:
                    entry["user_instances"] = kept_users
                    entry["operators_csv"] = ", ".join(kept_users)
                    entry["operator"] = kept_users[0]
                    entry["operators"] = kept_users
            else:
                entry["user_instances"] = kept_users or []
                entry["operators_csv"] = ", ".join(kept_users or [])
                entry["operator"] = (kept_users or [""])[0]
                entry["operators"] = list(kept_users or [])
            touched_rows += 1

        automation = getattr(self, "playlist_automation", None) or []
        for i, auto in enumerate(automation):
            if not isinstance(auto, dict):
                continue
            ops = auto.get("operators") or ([auto.get("operator")] if auto.get("operator") else [])
            if any(o in removed for o in ops) and auto.get("generated_by_engine"):
                automation[i] = {}

        self._engine_generated_playlist_rows = {
            r for r in getattr(self, "_engine_generated_playlist_rows", set())
            if r < len(rows) and isinstance(rows[r], dict) and rows[r].get("generated_by_engine")
        }
        try:
            self._push_restored_playlist_to_table()
        except Exception:
            pass
        print(f"[Ensemble Rescale] refactored {touched_rows} playlist row(s) referencing "
              f"{len(removed)} removed instrument(s)")
        return touched_rows

    def _canonical_finalize_playlist_field_lattice(self, rows):
        if self._canonical_protect_user() and hasattr(self, "_canonical_prune_stale_playlist_touches"):
            self._canonical_prune_stale_playlist_touches()
        """Final authoritative fill for the five lattice columns.

        These fields are derived *after* all canonical contributions exist.  They
        must never depend on which canonical was toggled first or on a UI table's
        current row/column count.  Sequence IDs are distributed round-robin over
        the complete available bank, while the row keeps exactly one primary
        operator identity.
        """
        rows = max(1, min(STRUCT_MAX_STEPS, int(rows)))
        names = list(getattr(self, "instrument_names_48", []) or ["Operator"])
        banks = getattr(self, "instrument_sequence_banks", {}) or {}
        active = []
        for attr, source in (("btn_local_randomize", "randomizer"),
                             ("btn_local_phase_lock", "phase_lock"),
                             ("btn_idealize_rhythm", "euclidean"),
                             ("btn_seeded_randomize", "seeded")):
            btn = getattr(self, attr, None)
            if btn is not None and btn.isChecked():
                active.append(source)
        if getattr(self, "goava_active", False):
            active.append("goava")
        if not active:
            return

        for r in range(rows):
            e = self.master_playlist_data[r]
            if not isinstance(e, dict):
                e = {}; self.master_playlist_data[r] = e
            op = str(e.get("_unison_base_operator") or e.get("operator") or "").strip()
            if not op or op.casefold() == "goava":
                op = names[r % len(names)] if names else "Operator"
            # Preserve the audio/composition identity exactly as the canonical
            # consensus selected it.  Do not synthesize an ensemble-sized operator
            # list here: the display repair must not alter renderer voice selection.
            e["operator"] = op
            existing_ops = e.get("operators") or []
            if isinstance(existing_ops, str):
                existing_ops = [x.strip() for x in existing_ops.split(",") if x.strip()]
            if not existing_ops:
                existing_ops = [op]
            e["operators"] = list(dict.fromkeys([op] + [str(x).strip() for x in existing_ops if str(x).strip()]))
            e["operators_csv"] = ", ".join(e["operators"])

            # The five-column lattice must not collapse to one operator's bank.
            # Read the already-reconciled sequence_refs first; only fall back to the
            # primary operator bank when consensus produced no reference.
            reconciled_refs = [str(x).strip() for x in (e.get("sequence_refs") or []) if str(x).strip()]
            if reconciled_refs:
                ref0 = reconciled_refs[r % len(reconciled_refs)]
                try:
                    ref_op, ref_sid_text = ref0.rsplit(":", 1)
                    sid = int(ref_sid_text)
                    bank = banks.get(ref_op, {}) if isinstance(banks, dict) else {}
                except Exception:
                    ref_op, sid, bank = op, 1, (banks.get(op, {}) if isinstance(banks, dict) else {})
            else:
                bank = banks.get(op, {}) if isinstance(banks, dict) else {}
                ids = sorted(int(k) for k,v in bank.items()
                             if str(k).isdigit() and isinstance(v, dict))
                sid = ids[r % len(ids)] if ids else 1
            # The phase lattice reads the exact sequence it just selected.  Do not
            # consult an ambient ``mem`` variable: that was undefined on the
            # reconciled-ref path and caused toggle-time crashes.
            selected_mem = bank.get(sid, {}) if isinstance(bank, dict) else {}
            plen = max(1, int((selected_mem or {}).get("pattern_length", DEFAULT_SEQUENCE_LENGTH) or DEFAULT_SEQUENCE_LENGTH))
            phase = (r + (sid - 1)) % plen
            ref = f"{op}#S{sid}"

            # Complete, uniformly modal five-column lattice.
            _all_ids = sorted(int(k) for k, v in (bank.items() if isinstance(bank, dict) else [])
                              if str(k).isdigit() and isinstance(v, dict)) or [sid]
            e["direction"] = float(1.0 if ((r // max(1, len(_all_ids))) % 2 == 0) else -1.0)
            e["direction_vector"] = f"{e['direction']:+.4f}"
            refs = [ref]
            # Preserve all reconciled refs, but make the primary ref deterministic.
            for x in e.get("sequence_refs") or []:
                x = str(x).strip()
                if x and x not in refs:
                    refs.append(x)
            e["sequence_refs"] = refs
            e["phase_offsets"] = {op: int(phase)}
            e["multi_seq"] = ", ".join(refs)
            e["coverage"] = e.get("coverage") or f"{op}:100%"
            e["blend_partner"] = e.get("blend_partner") or refs[1] if len(refs) > 1 else ref
            # DISPLAY COMPLETENESS: these fields are UI metadata only.  Populate
            # them from the final row identity without changing sequencer/audio state.
            primary = str(e.get("operator") or op).strip() or "Operator"
            src_label = "+".join(active) if active else "canonical"
            if not str(e.get("script_tag") or "").strip():
                e["script_tag"] = f"Canonical Script · {primary}"
            if not str(e.get("domain_tag") or "").strip():
                e["domain_tag"] = f"Canonical Domain · {src_label}"
            if not str(e.get("synth_tag") or "").strip():
                e["synth_tag"] = f"Synth · {primary}"
            if not str(e.get("patch_tag") or "").strip():
                e["patch_tag"] = f"Patch · {primary}"
            if not str(e.get("effect_target") or "").strip():
                e["effect_target"] = primary
            if not str(e.get("direction_vector") or "").strip():
                e["direction_vector"] = f"{1.0 if (r % 2 == 0) else -1.0:+.4f}"
            if not str(e.get("multi_seq") or "").strip():
                e["multi_seq"] = ref
            if not str(e.get("coverage") or "").strip():
                e["coverage"] = f"{primary}:100%"

            # FINAL TAIL GUARANTEE: these five columns are authoritative outputs of
            # the canonical transaction.  Never use ``setdefault``/``or`` here: a
            # shorter earlier canonical pass is precisely what caused the final
            # columns to remain blank when GOAVA was activated first.
            if getattr(self, "goava_active", False):
                evs = list(getattr(self, "goava_note_events", []) or [])
                if evs:
                    ev = evs[r % len(evs)]
                    e["goava_sequence"] = (f"GOAVA step={r+1} seed={ev['seed']:.9g} "
                                            f"raw={ev['raw']:.9g} hz={ev['frequency']:.6f} "
                                            f"pitch={ev['pitch']:.6f} on={int(ev['enabled'])}")
                else:
                    e["goava_sequence"] = f"GOAVA step={r+1} · pending"
            else:
                e.pop("goava_sequence", None)

            # Materialize a complete row before exposing the final tail.  Some
            # canonical candidates intentionally omit optional UI fields; the final
            # unison result must nevertheless be visibly complete when every engine
            # is active.  Never invent a second pattern: use the already-selected
            # operator/sequence/step as the sole source of truth.
            e["active"] = True
            e["generated_by_engine"] = True
            e["generated_source"] = "canonical_unison"
            # Never replace an established playlist timing constraint with the row
            # index. Older finalization did exactly that, causing Euclidean,
            # Randomizer, GOAVA, and mixed toggle paths to reset markers.
            try:
                _ta = float(e.get("_playlist_time_anchor", e.get("time_offset")))
                if math.isfinite(_ta):
                    e["time_offset"] = _ta
                    e["time_marker"] = f"e:{_ta:.4f}s"
            except Exception:
                pass
            if e.get("velocity") in (None, ""):
                e["velocity"] = 1.0
            if e.get("probability") in (None, ""):
                e["probability"] = 100
            if e.get("coverage") in (None, ""):
                e["coverage"] = f"{op}:100%"
            # Project the COMPLETE unison identity from the final sequence refs.
            # This is display metadata only: it never feeds the renderer.  Each
            # canonical sequence ref is name:id, so the refs themselves are the
            # authoritative ensemble membership rather than the last canonical's
            # single operator.
            ensemble_ops = []
            for _sr in e.get("sequence_refs") or []:
                _sr = str(_sr).strip()
                if ":" in _sr:
                    _nm = _sr.rsplit(":", 1)[0].strip()
                    if _nm and _nm not in ensemble_ops:
                        ensemble_ops.append(_nm)
            if op and op not in ensemble_ops:
                ensemble_ops.insert(0, op)
            if not ensemble_ops:
                ensemble_ops = [op or "Operator"]
            e["operators"] = list(dict.fromkeys(ensemble_ops))
            e["operators_csv"] = ", ".join(e["operators"])

            # These four fields are filled on EVERY row from the SAME final
            # unison lattice.  Never source them from a single canonical writer.
            e["paint_target"] = "Unison Consensus → Playlist"
            e["paint_source"] = "Unison · " + ", ".join(e["operators"])
            e["paint_sequence"] = ", ".join(str(x) for x in (e.get("sequence_refs") or [ref]))
            e["paint_instrument"] = ", ".join(e["operators"])
            # GOAVA is a fifth-column contribution, but its presence must not
            # suppress the other four tail fields.  Always materialize a visible
            # value so the complete 13..17 projection cannot appear blank.
            if getattr(self, "goava_active", False) and not str(e.get("goava_sequence") or "").strip():
                e["goava_sequence"] = f"GOAVA · step {r + 1}"
            elif not getattr(self, "goava_active", False):
                e["goava_sequence"] = e.get("goava_sequence") or "—"

            # If the PaintbrushTable is already open, write the authoritative tail
            # immediately as well.  The later global sync remains idempotent.
            table = getattr(self, "active_paint_table", None)
            if table is not None and hasattr(table, "rowCount") and r < table.rowCount():
                for c, key in ((13, "goava_sequence"), (14, "paint_target"),
                               (15, "paint_source"), (16, "paint_sequence"),
                               (17, "paint_instrument")):
                    if c >= table.columnCount():
                        continue
                    text = str(e.get(key, "") or "")
                    try:
                        if hasattr(table, "set_cell_item"):
                            table.set_cell_item(r, c, text)
                        else:
                            item = table.item(r, c)
                            if item is not None:
                                item.setText(text)
                            else:
                                from PyQt6.QtWidgets import QTableWidgetItem
                                table.setItem(r, c, QTableWidgetItem(text))
                    except Exception:
                        pass

    def _canonical_unity_consensus(self, baseline, candidates, rows):
        """Order-independent, level-weighted consensus of SEEDED/RAND/LOCK/GOAVA."""
        import copy, json
        self.master_playlist_data = copy.deepcopy(baseline)
        if not candidates: return
        def norm(v):
            if isinstance(v, dict): return json.dumps(v, sort_keys=True, separators=(",",":"), default=str)
            if isinstance(v, (list, tuple)): return json.dumps(list(v), sort_keys=True, separators=(",",":"), default=str)
            return str(v if v is not None else "")
        fields = ("operator", "operators", "operators_csv", "sequence_refs", "phase_offsets", "multi_seq",
                  "direction", "direction_vector", "coverage", "blend_partner", "goava_sequence", "paint_target",
                  "paint_source", "paint_sequence", "paint_instrument", "time_marker", "time_offset", "velocity", "pitch", "probability")
        for r in range(rows):
            base = baseline[r] if r < len(baseline) and isinstance(baseline[r], dict) else {}
            e = self.master_playlist_data[r] if r < len(self.master_playlist_data) else {}
            if not isinstance(e, dict): e = {}; self.master_playlist_data[r] = e
            for field in fields:
                groups = {}
                for source, data in candidates:
                    if r >= len(data) or not isinstance(data[r], dict): continue
                    v = data[r].get(field, None)
                    if v is None or norm(v) == "": continue
                    k = norm(v)
                    groups.setdefault(k, {"weight":0.0, "values":[]})
                    groups[k]["weight"] += max(0.0, self._canonical_level(source))
                    groups[k]["values"].append(v)
                if groups:
                    best = max(groups.items(), key=lambda kv: (kv[1]["weight"], len(kv[1]["values"]), kv[0]))
                    e[field] = best[1]["values"][0]
            all_ops = []
            for source_name, data in candidates:
                if self._canonical_level(source_name) <= 0.0: continue
                if r < len(data) and isinstance(data[r], dict):
                    cv = data[r].get("operators", [])
                    if isinstance(cv, str): cv = [x.strip() for x in cv.split(",") if x.strip()]
                    for x in cv or []:
                        x = str(x).strip()
                        if x and x not in all_ops: all_ops.append(x)
            base_ops = base.get("operators", []) if isinstance(base, dict) else []
            if isinstance(base_ops, str): base_ops = [x.strip() for x in base_ops.split(",") if x.strip()]
            for x in base_ops or []:
                x = str(x).strip()
                if x and x not in all_ops: all_ops.append(x)
            base_op = str(base.get("operator") or "").strip() if isinstance(base, dict) else ""
            if base_op and base_op.casefold() != "goava": op = base_op
            else:
                names = list(getattr(self, "instrument_names_48", []) or ["Operator"])
                op = names[r % len(names)] if names else "Operator"
            if op not in all_ops: all_ops.append(op)
            all_ops = sorted(set(all_ops), key=lambda x: (x.casefold() == "goava", x.casefold()))
            e["operator"] = op; e["operators"] = all_ops; e["operators_csv"] = ", ".join(all_ops)

    def _canonical_unison_step_lattice(self, rows, sequence_banks):
        """Normalize final playlist sequence/offset state on the exact same step lattice.

        Read and write use the same row/step coordinate: row ``r`` reads the
        canonical sequence assignment for ``r % N`` and writes its phase offset
        back at that exact coordinate. This removes implicit shifts caused by
        candidate-local sequence lengths or dictionary insertion order.
        """
        names = list(getattr(self, "instrument_names_48", []) or [])
        if not names:
            return
        # Stable canonical sequence ordering; never depend on toggle order.
        canonical_sources = ["goava", "phase_lock", "randomizer", "seeded"]
        bpm = float(self.spin_bpm.value()) if hasattr(self, "spin_bpm") else 120.0
        step_dur = (60.0 / positive_bpm(bpm)) / 4.0
        selected_map = getattr(self, "instrument_selected_sequence", {}) or {}
        for r in range(max(0, int(rows))):
            e = self.master_playlist_data[r] if r < len(self.master_playlist_data) else None
            if not isinstance(e, dict):
                continue
            refs = []
            phases = {}
            op_offsets = dict(e.get("operator_time_offsets") or {}) if isinstance(e.get("operator_time_offsets"), dict) else {}
            pattern_lengths = dict(e.get("pattern_lengths") or {}) if isinstance(e.get("pattern_lengths"), dict) else {}
            for name in names:
                bank = (sequence_banks or {}).get(name, {})
                canonical = []
                for idx, mem in sorted(bank.items(), key=lambda kv: int(kv[0]) if str(kv[0]).isdigit() else 0):
                    if isinstance(mem, dict) and str(mem.get("canonical_owner", "")).startswith("canonical:"):
                        owner = str(mem.get("canonical_owner")).split(":", 1)[1]
                        if owner in canonical_sources:
                            canonical.append((canonical_sources.index(owner), int(idx), owner))
                canonical.sort()
                user_sid = selected_map.get(name)
                try:
                    user_sid = int(user_sid) if user_sid is not None else None
                except Exception:
                    user_sid = None
                slot_ids = []
                if user_sid in bank:
                    slot_ids.append(int(user_sid))
                if canonical:
                    pos = r % len(canonical)
                    _, idx, owner = canonical[pos]
                    if idx not in slot_ids:
                        slot_ids.append(idx)
                for idx in slot_ids:
                    mem = bank.get(idx) or {}
                    plen = max(1, int(mem.get("pattern_length", 1) or 1))
                    refs.append(f"{name}:{idx}")
                    step_i = int(r % plen)
                    phases[f"{name}:{idx}"] = step_i
                    offs = mem.get("offsets") or [0.0]
                    raw_off = float(offs[step_i] if step_i < len(offs) else 0.0)
                    # LOCK Timing Pull contracts LOCK-owned offsets toward the shared row grid.
                    try:
                        if str(mem.get("canonical_owner", "")) in ("canonical:phase_lock", "canonical:phase-lock"):
                            raw_off *= (1.0 - self._lock_characteristics()["timing_pull"] * self._canonical_level("phase_lock"))
                    except Exception:
                        pass
                    # Irrational Meum warp so unison can write non-grid time freely.
                    op_offsets[name] = float(raw_off * step_dur * MEUM)
                    pattern_lengths[name] = plen
            if refs:
                e["sequence_refs"] = refs
                e["phase_offsets"] = phases
                e["multi_seq"] = ", ".join(dict.fromkeys(refs))
                e["operator_time_offsets"] = op_offsets
                e["pattern_lengths"] = pattern_lengths
                try:
                    e["time_offset"] = float(next(iter(op_offsets.values())))
                    e["_playlist_time_anchor"] = e["time_offset"]
                    e["time_marker"] = f"u:{e['time_offset']:.6f}s"
                except Exception:
                    pass

    def _rebuild_active_canonical_playlist(self, reason="toggle"):
        """Authoritative, order-independent canonical rebuild with decisive unity feedback.

        Every active canonical method writes against the identical baseline.  The
        resulting candidate states are then combined by one deterministic consensus
        pass.  Consequently activation order cannot decide playlist content.
        """
        if getattr(self, "_canonical_rebuild_guard", False):
            return
        # Clear Playlist hold: with no canonical engine active, a cleared playlist
        # stays cleared; the first active engine writes a fresh one.
        if getattr(self, "_playlist_cleared_hold", False):
            try:
                _active_now = self._get_active_engine_set()
            except Exception:
                _active_now = set()
            if not _active_now:
                return
            self._playlist_cleared_hold = False
        self._canonical_rebuild_guard = True
        try:
            # Order-independence: strip engine-derived residue so the candidate
            # baseline is identical regardless of prior activation history.
            try:
                self._reset_canonical_engine_derived_state()
            except Exception:
                pass
            import copy
            rows = max(1, min(STRUCT_MAX_STEPS, int(self.spin_playlist_length.value()) if hasattr(self, "spin_playlist_length") else DEFAULT_PLAYLIST_ROWS))
            if not hasattr(self, "master_playlist_data") or self.master_playlist_data is None:
                self.master_playlist_data = []
            while len(self.master_playlist_data) < rows:
                self.master_playlist_data.append({})
            if not hasattr(self, "playlist_automation") or self.playlist_automation is None:
                self.playlist_automation = []
            while len(self.playlist_automation) < rows:
                self.playlist_automation.append({})

            # Build a HISTORY-FREE baseline.  The live playlist may still contain
            # canonical output from the preceding toggle transaction; using that as
            # the next baseline is the subtle source of the recurring GOAVA-only and
            # terminal-column regressions.  Only explicit user state is allowed to
            # cross a canonical transaction boundary.
            raw_baseline = _fast_copy(self.master_playlist_data[:rows])
            generated_fields = {
                "operator", "operators", "operators_csv", "sequence_refs",
                "phase_offsets", "multi_seq", "direction", "direction_vector",
                "coverage", "blend_partner", "goava_sequence", "paint_target",
                "paint_source", "paint_sequence", "paint_instrument",
                "time_marker", "time_offset", "velocity", "pitch", "probability",
                "generated_by_engine", "generated_source", "canonical_weight",
            }
            baseline = []
            names_for_baseline = list(getattr(self, "instrument_names_48", []) or ["Operator"])
            for r, src in enumerate(raw_baseline):
                e = src if isinstance(src, dict) else {}      # R32.8: raw_baseline is already a private copy
                users = e.get("user_instances") or []
                # Strip all previous canonical output.  User-owned panel/instance
                # state is retained separately and reintroduced by reconciliation.
                for k in generated_fields:
                    e.pop(k, None)
                e.pop("engine_contributions", None)
                e["user_instances"] = copy.deepcopy(users)
                # A scalar operator is user state only when it is explicitly attached
                # to a user instance.  Never inherit GOAVA (or another engine) here.
                user_ops = []
                for u in users:
                    if isinstance(u, dict):
                        uop = str(u.get("operator") or u.get("name") or "").strip()
                    else:
                        uop = str(u or "").strip()
                    if uop and uop.casefold() != "goava":
                        user_ops.append(uop)
                if user_ops:
                    e["operator"] = sorted(set(user_ops), key=str.casefold)[0]
                    e["operators"] = sorted(set(user_ops), key=str.casefold)
                    e["operators_csv"] = ", ".join(e["operators"])
                else:
                    e["operator"] = names_for_baseline[r % len(names_for_baseline)]
                    e["operators"] = [e["operator"]]
                    e["operators_csv"] = e["operator"]
                # Explicit immutable row identity.  It is not a generated canonical
                # field and therefore survives every candidate/toggle transaction.
                e["_unison_base_operator"] = str(e.get("operator") or names_for_baseline[r % len(names_for_baseline)])
                baseline.append(e)

            # Sequencer state is part of the canonical transaction, not ambient mutable
            # state.  Reconcile once only after the history-free baseline is established.
            self.master_playlist_data = copy.deepcopy(baseline)
            self._canonical_sequence_reconcile(reason)
            baseline = _fast_copy(self.master_playlist_data[:rows])
            baseline_sequence_banks = copy.deepcopy(getattr(self, "instrument_sequence_banks", {}) or {})
            baseline_sequencer_memory = copy.deepcopy(getattr(self, "instrument_sequencer_memory", {}) or {})
            baseline_selected_sequences = copy.deepcopy(getattr(self, "instrument_selected_sequence", {}) or {})
            active=[]
            pairs=(("seeded","btn_seeded_randomize"),("randomizer","btn_local_randomize"),("phase_lock","btn_local_phase_lock"),("euclidean","btn_idealize_rhythm"))
            for source, attr in pairs:
                btn=getattr(self, attr, None)
                if btn is not None and btn.isChecked() and self._canonical_level(source) > 0.0:
                    active.append(source)
            if getattr(self, "goava_active", False) and self._canonical_level("goava") > 0.0:
                if not getattr(self, "goava_note_events", None):
                    self.goava_note_events=self._build_goava_composition()
                active.append("goava")

            # Freeze the same imported-input + net-canonical context for every candidate.
            # This makes the carrier a first-class canonical input without letting mutable
            # render buffers or toggle order influence candidate generation.
            canonical_input_ctx = self._canonical_input_context()
            self._canonical_render_input_context = dict(canonical_input_ctx)
            _carrier_salt = int(canonical_input_ctx.get("carrier_rms", 0.0) * 1000003) ^ int(canonical_input_ctx.get("carrier_peak", 0.0) * 1000033)
            _unison_salt = int(canonical_input_ctx.get("canonical_mask", 0))
            candidates=[]
            for source in active:
                # Hard-reset all mutable sequencer views before EACH candidate.  This is
                # the critical order-independence boundary: candidate A cannot leave a
                # sequence entry, selected pattern, or step mutation for candidate B.
                self.master_playlist_data=copy.deepcopy(baseline)
                self.instrument_sequence_banks=copy.deepcopy(baseline_sequence_banks)
                self.instrument_sequencer_memory=copy.deepcopy(baseline_sequencer_memory)
                self.instrument_selected_sequence=copy.deepcopy(baseline_selected_sequences)
                if source == "goava":
                    self._apply_goava_to_canonical_playlist()
                else:
                    source_seed = self._canonical_seed_for_source(source)
                    rng=np.random.default_rng((_safe_int_seed(source_seed) ^ sum(map(ord, source)) ^ rows ^ _carrier_salt ^ _unison_salt) & 0x7fffffff)
                    self._canonical_playlist_paint(rng=rng, mode=source, strength=0.55 * self._canonical_level(source))
                candidates.append((source, _fast_copy(self.master_playlist_data[:rows])))

            self._canonical_unity_consensus(baseline, candidates, rows)
            # Playlist consensus is now authoritative. Rebuild the sequencer bank from
            # the active canonical SET (not candidate execution order), restoring the
            # same deterministic sequence topology for the final rendered state.
            self.instrument_sequence_banks=copy.deepcopy(baseline_sequence_banks)
            self.instrument_sequencer_memory=copy.deepcopy(baseline_sequencer_memory)
            self.instrument_selected_sequence=copy.deepcopy(baseline_selected_sequences)
            self._canonical_sequence_reconcile("unity_consensus")
            # Final single-path unison agreement: sequence selection and phase reads
            # are normalized and written on the same row/step coordinates.
            self._canonical_unison_step_lattice(rows, self.instrument_sequence_banks)
            # Consensus is already the authoritative merged row. Do not run the
            # legacy contribution reducer here: the history-free baseline has no
            # engine_contributions, so that reducer would erase the freshly agreed
            # canonical fields and make an all-active result look empty.
            self._canonical_finalize_playlist_field_lattice(rows)
            try:
                self._canonical_assign_row_write_modes(rows)
            except Exception as _wm_exc:
                print(f"[Canonical] row write modes: {_wm_exc}")
            # Final authoritative tail completion: never leave the visible or
            # in-memory terminal five fields dependent on a prior writer.
            for _r, _e in enumerate(self.master_playlist_data[:rows]):
                if not isinstance(_e, dict):
                    continue
                _op = str(_e.get("operator") or "Operator").strip()
                _seq = str(_e.get("paint_sequence") or _e.get("multi_seq") or f"{_op}#S1")
                _e["paint_target"] = str(_e.get("paint_target") or "Canonical → Playlist")
                _e["paint_source"] = str(_e.get("paint_source") or f"Canonical unison · {_op}")
                _e["paint_sequence"] = _seq
                _e["paint_instrument"] = str(_e.get("paint_instrument") or _op)
                if getattr(self, "goava_active", False) and not str(_e.get("goava_sequence") or "").strip():
                    _evs = list(getattr(self, "goava_note_events", []) or [])
                    if _evs:
                        _ev = _evs[_r % len(_evs)]
                        _e["goava_sequence"] = f"GOAVA step={_r+1} seed={_ev['seed']:.9g} raw={_ev['raw']:.9g} hz={_ev['frequency']:.6f} pitch={_ev['pitch']:.6f} on={int(_ev['enabled'])}"
            # FINAL DISPLAY PROJECTION (no synthesis/sequencer mutation): derive
            # the six historically missing identity/tail columns from the already
            # finalized unison row. This is deliberately after consensus and after
            # all user-lock decisions, so it cannot change the composition.
            for _r, _e in enumerate(self.master_playlist_data[:rows]):
                if not isinstance(_e, dict):
                    continue
                refs = _e.get("sequence_refs") or []
                if isinstance(refs, str):
                    refs = [x.strip() for x in refs.split(",") if x.strip()]
                ops = _e.get("operators") or []
                if isinstance(ops, str):
                    ops = [x.strip() for x in ops.split(",") if x.strip()]
                ops = list(dict.fromkeys([str(x).strip() for x in ops if str(x).strip()]))
                ref_ops = []
                for _ref in refs:
                    _name = str(_ref).split("#S", 1)[0].strip()
                    if _name and _name not in ref_ops:
                        ref_ops.append(_name)
                # DISPLAY-ONLY ensemble identity: sequence refs are authoritative when
                # available, but a canonical row must still expose the complete surviving
                # instrument roster even when a particular canonical sequence bank has only
                # one materialized ref.  This never changes `operator`, sequencer memory, or
                # synthesis voice selection.
                roster = [str(x).strip() for x in (getattr(self, "instrument_names_48", []) or []) if str(x).strip()]
                final_ops = list(dict.fromkeys(ref_ops + ops + roster))
                if final_ops:
                    _e["operators"] = final_ops
                    _e["operators_csv"] = ", ".join(final_ops)
                _op = str(_e.get("operator") or (final_ops[0] if final_ops else "Operator")).strip()
                _seq = ", ".join(str(x) for x in refs if str(x).strip()) or str(_e.get("multi_seq") or f"{_op}#S1")
                _e["multi_seq"] = _seq
                _e["blend_partner"] = str(_e.get("blend_partner") or (final_ops[1] if len(final_ops) > 1 else (final_ops[0] if final_ops else _op)))
                _e["goava_sequence"] = str(_e.get("goava_sequence") or (
                    f"GOAVA step={_r+1}" if getattr(self, "goava_active", False) else "—"))
                _e["paint_target"] = str(_e.get("paint_target") or "Canonical → Playlist")
                _e["paint_source"] = str(_e.get("paint_source") or ("Canonical unison · " + ", ".join(final_ops or [_op])))
                _e["paint_sequence"] = str(_e.get("paint_sequence") or _seq)
                _e["paint_instrument"] = str(_e.get("paint_instrument") or ", ".join(final_ops or [_op]))
                # Every playlist column has an explicit deterministic value. These
                # are metadata projections and never feed back into synthesis.
                _defaults = {
                    "script_tag": f"Script::{_op[:8].upper()}-X{_r}",
                    "domain_tag": "Canonical Unity",
                    "synth_tag": f"Synth::{_op[:8]}",
                    "patch_tag": f"Patch::{_op[:8]}",
                    "effect_target": "Canonical Unison",
                    "auto_amount": "0.000",
                    "time_marker": _e.get("time_marker") or f"T + {_r * 3.5:.1f}s",
                    "time_offset": _e.get("time_offset", _r),
                    "velocity": _e.get("velocity", 1.0),
                    "coverage": _e.get("coverage") or "100%",
                    "direction_vector": _e.get("direction_vector") or "+1.0000",
                }
                for _k, _v in _defaults.items():
                    if _e.get(_k) in (None, "", []):
                        _e[_k] = _v
                # One predicted phase: playlist + patterns + panels → live_parametrics
                try:
                    apply_live_parametrics_to_entry(self, _e, row_idx=_r)
                except Exception:
                    if not _e.get("live_parametrics"):
                        _e["live_parametrics"] = f"# placeholder row={_r} until live composition"
                # Tail fields are canonical projection fields.  A stale blank UI cell
                # must never be allowed to suppress a newly composed value.  Preserve
                # explicit non-empty user edits, but materialize every generated tail
                # field whenever the consensus has a value.
                _tail_defaults = {
                    "blend_partner": _e.get("blend_partner") or (final_ops[1] if len(final_ops) > 1 else (_op or "Operator")),
                    "goava_sequence": _e.get("goava_sequence") or (f"GOAVA step={_r+1}" if getattr(self, "goava_active", False) else "—"),
                    "paint_target": _e.get("paint_target") or "Canonical → Playlist",
                    "paint_source": _e.get("paint_source") or ("Canonical unison · " + ", ".join(final_ops or [_op])),
                    "paint_sequence": _e.get("paint_sequence") or _seq,
                    "paint_instrument": _e.get("paint_instrument") or ", ".join(final_ops or [_op]),
                }
                for _k, _v in _tail_defaults.items():
                    if _e.get(_k) in (None, "", []):
                        _e[_k] = str(_v)
            # The memory model is authoritative at this boundary.
            self._sync_playlist_paint_table_from_memory()
        finally:
            self._canonical_rebuild_guard=False

    def _adaptive_edit_delay_ms(self):
        """Debounce long enough to cover how long the last canonical rebuild took (×1.5),
        so repeated clicks merge into one rebuild instead of queueing one each."""
        cost = float(getattr(self, "_live_flush_cost", 0.0) or 0.0)
        return int(max(140, min(2500, 1500.0 * cost)))

    def _queue_playlist_resize(self, rows):
        self._pending_playlist_rows = int(rows)
        t = getattr(self, "_playlist_resize_timer", None)
        if t is None:
            t = self._playlist_resize_timer = QTimer(self)
            t.setSingleShot(True)
            t.timeout.connect(self._apply_queued_playlist_resize)
        t.start(max(250, self._adaptive_edit_delay_ms()))

    def _apply_queued_playlist_resize(self):
        rows = getattr(self, "_pending_playlist_rows", None)
        if rows is None:
            return
        self._pending_playlist_rows = None
        t0 = time.monotonic()
        try:
            self._resize_playlist_memory(rows)
        finally:
            self._live_flush_cost = max(float(getattr(self, "_live_flush_cost", 0.0) or 0.0) * 0.5,
                                        time.monotonic() - t0)
        self._on_live_source_changed()

    def _resize_playlist_memory(self, rows):
        """Resize playlist capacity without discarding user rows; canonicals repaint the new span."""
        # PROJECT_UNDO_2026: snapshot BEFORE any resize so every row is kept and
        # the whole resize is reversible (undo/redo).
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo(f"Playlist resize → {int(rows)}")
        rows = max(1, min(STRUCT_MAX_STEPS, int(rows)))
        data = getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or []
        auto = getattr(self, "playlist_automation", []) or []
        # getattr default only applies when the attribute is missing. If undo/restore
        # (or any prior path) ever set _playlist_overflow_rows = None, getattr returns
        # None and the subsequent overflow[i] = ... raises TypeError.
        overflow = getattr(self, "_playlist_overflow_rows", None) or {}
        if not isinstance(overflow, dict):
            overflow = {}
        if rows < len(data):
            for i in range(rows, len(data)):
                # DATA_KEEP_2026: preserve EVERY dropped row (user, engine-drawn,
                # automation, timed rows) in the overflow parking lot, not just
                # user-owned rows, so growing the playlist back never loses data.
                overflow[i] = (copy.deepcopy(data[i]), copy.deepcopy(auto[i] if i < len(auto) else {}))
            data = data[:rows]
            auto = auto[:rows]
        else:
            for i in range(len(data), rows):
                if i in overflow:
                    data.append(copy.deepcopy(overflow[i][0]))
                    auto.append(copy.deepcopy(overflow[i][1]))
                    overflow.pop(i, None)
                else:
                    data.append({})
                    auto.append({})
        self.master_playlist_data = data
        self.playlist_automation = auto
        self._playlist_overflow_rows = overflow
        if hasattr(self, "_canonical_prune_stale_playlist_touches"):
            self._canonical_prune_stale_playlist_touches()
        table = getattr(self, "active_paint_table", None)
        if table is not None:
            try:
                table.setRowCount(rows)
                table.setColumnCount(PLAYLIST_COLUMN_COUNT)
                hdr = table.horizontalHeader()
                for _ci in range(PLAYLIST_COLUMN_COUNT):
                    hdr.setSectionResizeMode(_ci, QHeaderView.ResizeMode.Stretch)
                hdr.setStretchLastSection(False)
                table.viewport().update()
            except Exception:
                pass
        # Resize is a pure capacity mutation.  Do not pre-paint canonicals here:
        # doing so mutates the would-be baseline and then the authoritative rebuild
        # paints again, making resize dependent on the route that reached it.
        if hasattr(self, "_rebuild_active_canonical_playlist"):
            self._rebuild_active_canonical_playlist("playlist_resize")
        return rows

    def _canonical_active_count(self):
        """Number of active public canonical engines (max five)."""
        return len(self._active_engine_sources())

    def _full_canonical_unison_active(self):
        """True when SEEDED, RAND, LOCK and EUCLIDEAN are all active (GOAVA optional).

        GROOVEBOX_R23R_UNISON_FOUR_OR_FIVE_20261031: all canonicals, or all minus
        GOAVA, must give the same sound and video for a seed whatever the number
        of instruments; only user-owned composition data may set voices apart.
        GOAVA is the single-instance source and does not decide unison.
        """
        active = self._active_engine_sources()
        return all(k in active for k in ("seeded", "randomizer", "phase_lock", "euclidean"))

    def _full_four_engine_unison_active(self):
        """Backward-compatible alias; full unison = the four public canonicals, GOAVA optional."""
        return self._full_canonical_unison_active()

    def _finalize_union_entropy(self):
        """UNION_ENTROPY_2026 live fixed-point audit.

        Proves the wavefunction's entropy while engines are active:

          * balance — mean of the shared draw D sits on the 0.5 fixed point
            (input-invariant, |mean-0.5| <= ENTROPY_FIXED_POINT_TOL);
          * genuine spread — realized per-voice entropy really varies, so some
            seeds come out entropic and others ordered (min..max range wide
            enough, with a voice at each extreme).

        Both together make the claim: no seed or user patch can push the union
        off its 0.5-centre, nor flatten it into a single non-entropic timbre.
        """
        try:
            n = max(1, self._union_entropy_n)
            mean = float(self._union_entropy_sum / n)
            var = max(0.0, float(self._union_entropy_sum_sq / n) - mean * mean)
            std = math.sqrt(var)
            r_span = float(self._union_entropy_r_max - self._union_entropy_r_min)
            balanced = abs(mean - ENTROPY_FIXED_POINT) <= ENTROPY_FIXED_POINT_TOL
            spread = (r_span >= ENTROPY_REALIZED_SPREAD_MIN
                      and self._union_entropy_r_max >= ENTROPY_REALIZED_TOP
                      and self._union_entropy_r_min <= ENTROPY_REALIZED_BOTTOM)
            # Full union = one genuine entropy point per seed (some seeds are
            # entropic, some not); the 0.5 centre is a property of the draw
            # family over the input space (cross-seed battery proof), so the
            # live check is REPORT-ONLY in that case: a single observed point
            # can neither confirm nor falsify the family invariant.
            if self._union_entropy_full_window:
                ok_flag = True
            else:
                ok_flag = bool(balanced and spread)
            self._union_entropy_mean = mean
            self._union_entropy_std = std
            self._union_entropy_ok = bool(ok_flag)
            # VISUAL_SYMMETRY_2026: pull the visual ledger from the cancellor
            # engine 'video_synth_engine' if present and cross-check symmetry.
            vis_ok = None
            vis_mean = None
            vse = getattr(self, "video_synth_engine", None)
            if vse is not None and hasattr(vse, "_vled_ok") and hasattr(vse, "_vled_mean"):
                vis_ok = bool(getattr(vse, "_vled_ok", True))
                vis_mean = float(getattr(vse, "_vled_mean", ENTROPY_FIXED_POINT))
            symmetric = None
            if vis_mean is not None:
                symmetric = bool(abs(mean - vis_mean) <= ENTROPY_FIXED_POINT_TOL)
            lbl = getattr(self, "lbl_unison_entropy", None)
            if lbl is not None:
                if vis_mean is not None:
                    mark = "✓" if (ok_flag and vis_ok and symmetric) else "⚠"
                    col = "#7dff9a" if (ok_flag and vis_ok and symmetric) else "#ff9a7d"
                    lbl.setText("Ω E %.2f±%.2f [%.2f..%.2f] ⚭⥾%.2f %s" % (
                        mean, std, self._union_entropy_r_min,
                        self._union_entropy_r_max, vis_mean, mark))
                else:
                    mark = "✓" if ok_flag else "⚠"
                    col = "#7dff9a" if ok_flag else "#ff9a7d"
                    lbl.setText("Ω E %.2f±%.2f [%.2f..%.2f] %s" % (
                        mean, std, self._union_entropy_r_min,
                        self._union_entropy_r_max, mark))
                lbl.setStyleSheet("color:%s; font-weight:bold;" % col)
            if (not ok_flag) or ((symmetric is False) and not self._union_entropy_full_window):
                print("[UNION-ENTROPY] out-of-band: mean=%.3f std=%.3f "
                      "realized=[%.3f..%.3f] n=%d vis-ok=%s sym=%s" % (
                          mean, std, self._union_entropy_r_min,
                          self._union_entropy_r_max, n, vis_ok, symmetric))
            self._union_entropy_sum = 0.0
            self._union_entropy_sum_sq = 0.0
            self._union_entropy_n = 0
            self._union_entropy_samples = 0
            self._union_entropy_r_min = 1.0
            self._union_entropy_r_max = 0.0
            self._union_entropy_full_window = False
        except Exception as e:
            print("[UNION-ENTROPY] finalize error:", e)

    def _canonical_continuation_wave(self, local_t, row_idx, seed_value, user_gate=None, resonance_factor=1.0):
        """Generate autonomous canonical continuation without modifying user data.

        Shared features are derived from the same time/seed field used by the user
        composition: rhythm gate, pitch ratio, envelope, phase, and modulation all
        remain compatible. If user activity exists, its activity mask is mirrored as
        a canonical counterpart; after user cessation, the deterministic canonical
        lattice continues on its own.
        """
        lt = np.asarray(local_t, dtype=np.float64)
        if lt.size == 0:
            return np.zeros(0, dtype=np.float32), np.zeros(0, dtype=bool)
        seed = float(seed_value or 0.0)
        # Shared musical coordinates: time, seed pitch, phase and a slow envelope.
        freq = 55.0 * float(_seed_to_pitch_ratio(seed, int(row_idx) % 48, int(row_idx) % 12))
        phase = 2.0 * math.pi * freq * lt + (seed * MEUM_NORM) + int(row_idx) * PHI
        duration = float(lt[-1] - lt[0]) if lt.size > 1 else 0.0
        if (not math.isfinite(duration)) or duration == 0.0:
            # Explicit degenerate-time case: a single/constant-time frame gets
            # a deterministic phase rather than an epsilon denominator.
            env_phase = np.full(lt.shape, seed * 0.01, dtype=np.float64)
        else:
            env_phase = 2.0 * math.pi * lt / duration + seed * 0.01
        env = 0.65 + 0.35 * (0.5 + 0.5 * ot_sin_vec_equiv(env_phase))
        if user_gate is not None and np.asarray(user_gate).size == lt.size and np.any(user_gate):
            ug = np.asarray(user_gate, dtype=bool)
            # Shared user/canonical activity: every user-active sample receives a
            # canonical counterpart, while canonical-only samples fill the gaps.
            step = max(1, lt.size // 16)
            autonomous = ((np.arange(lt.size) // step + int(row_idx)) % 2) == 0
            gate = ug | autonomous
        else:
            step = max(1, lt.size // 16)
            gate = ((np.arange(lt.size) // step + int(row_idx)) % 2) == 0
        # Small deterministic modulation derived from the shared phase field.
        mod = 0.82 + 0.18 * ot_sin_vec_equiv(phase * 0.125 + seed * 0.003)
        rf = float(np.clip(resonance_factor, 0.50, 1.50))
        # Activity-first scaling: increase canonical presence before allowing
        # resonance amplitude to rise. This keeps 150% from behaving like 150% volume.
        amp_scale = 0.88 + 0.12 * (rf / 1.50)
        if rf > 1.0:
            phase_gate = ((np.arange(lt.size) // step + int(row_idx) + 1) % 3) == 0
            gate = gate | (phase_gate & (ot_sin_vec_equiv(phase * 0.25) > -0.15))
        wave = (0.32 * amp_scale * env * mod * ot_sin_vec_equiv(phase)).astype(np.float32)
        return wave, gate

    def _meum_spatial_resolve_activity(self, canonical_wave, user_wave, row_idx=0, seed_value=0.0):
        """Resolve canonical activity through a direct x/y/z spatial field.

        This is a structural activity rule, not a post-mix limiter: the canonical
        branch is projected onto three directly tracked coordinates (x=time,
        y=amplitude/activity, z=local change), then a six-neighbor lattice average
        supplies the continuation field. The canonical branch is normalized to at
        least the user's L1 activity modulus before the optional live-overblend composition
        boundary. Thus the 50% floor is earned by the branch itself rather than by
        clamping the final signal.
        """
        c = np.asarray(canonical_wave, dtype=np.float64).copy()
        u = np.asarray(user_wave, dtype=np.float64)
        if c.size == 0:
            return c.astype(np.float32), 0.50, 0.0
        if u.size != c.size:
            u = np.resize(u, c.size)
        if not bool(getattr(self, "meum_spatial_resolution_enabled", False)):
            ca = float(np.sum(np.abs(c)))
            ua = float(np.sum(np.abs(u)))
            total_activity = ca + ua
            mod = (ca / total_activity) if total_activity != 0.0 else 0.50
            return c.astype(np.float32), mod, 0.0

        n = c.size
        # Direct orthogonal coordinates. No rotation matrix/quaternion layer.
        x = np.linspace(-1.0, 1.0, n, dtype=np.float64)
        u_peak = float(np.max(np.abs(u))) if u.size else 0.0
        if u_peak == 0.0 or not math.isfinite(u_peak):
            y = np.zeros_like(u)
        else:
            y = np.abs(u) / u_peak
        z = np.abs(np.gradient(u)) if n > 1 else np.zeros_like(u)
        z_peak = float(np.max(z)) if z.size else 0.0
        if z_peak == 0.0 or not math.isfinite(z_peak):
            z = np.zeros_like(u)
        else:
            z /= z_peak

        # Local six-neighbor propagation reduced onto the temporal line. The
        # orthogonal x/y/z components remain explicit so the field is inspectable.
        left = np.roll(c, 1); right = np.roll(c, -1)
        c_l = (left + right + c) / 3.0
        c_l[0] = (c[0] + c[1]) * 0.5 if n > 1 else c[0]
        c_l[-1] = (c[-1] + c[-2]) * 0.5 if n > 1 else c[-1]
        coord_drive = 0.78 + 0.10*y + 0.08*z
        spatial = c_l * coord_drive

        # Geometric loss against the user field: compare normalized coordinate
        # vectors rather than introducing L1/L2 penalty weights.
        c_norm = float(np.linalg.norm(c))
        u_norm = float(np.linalg.norm(u))
        cu = c / c_norm if c_norm > 0.0 and math.isfinite(c_norm) else np.zeros_like(c)
        uu = u / u_norm if u_norm > 0.0 and math.isfinite(u_norm) else np.zeros_like(u)
        geom_loss = float(np.mean((cu - uu) ** 2))

        # Structural activity invariant. If user activity is larger, canonical
        # activity is expanded to the same L1 modulus; this is not a final mix
        # clamp and does not alter the user's bus.
        c_l1 = float(np.sum(np.abs(spatial)))
        u_l1 = float(np.sum(np.abs(u)))
        if c_l1 == 0.0 or not math.isfinite(c_l1):
            # NO_SPATIAL_RESOLVE_20261102: a silent canonical branch stays silent (no injected sine)
            spatial = np.zeros_like(spatial)
            c_l1 = 0.0
        if u_l1 > c_l1 and c_l1 > 0.0 and math.isfinite(c_l1):
            spatial *= (u_l1 / c_l1)
            c_l1 = float(np.sum(np.abs(spatial)))
        modulus_den = c_l1 + u_l1
        activity_modulus = c_l1 / modulus_den if modulus_den > 0.0 and math.isfinite(modulus_den) else 0.50
        return spatial.astype(np.float32), float(activity_modulus), float(geom_loss)

    def _record_canonical_activity(self, row_idx, canonical_wave, user_wave, canonical_gate=None, user_gate=None):
        """Record activity coverage separately from coefficient weights.

        This is the runtime proof that canonical activity continues independently;
        it intentionally does not use a signal clamp or alter the 0.5 composition
        coefficients.
        """
        try:
            cw = np.asarray(canonical_wave, dtype=np.float64)
            uw = np.asarray(user_wave, dtype=np.float64)
            ca = float(np.mean(cw != 0.0)) if cw.size else 0.0
            ua = float(np.mean(uw != 0.0)) if uw.size else 0.0
            if canonical_gate is not None:
                cg = np.asarray(canonical_gate, dtype=bool)
                ca = max(ca, float(np.mean(cg)))
            if user_gate is not None:
                ug = np.asarray(user_gate, dtype=bool)
                ua = max(ua, float(np.mean(ug)))
            self._canonical_activity_ledger[int(row_idx)] = {
                "canonical_activity": ca, "userdata_activity": ua,
                "canonical_activity_meets_50pct": (ca >= 0.50 * (ca + ua)) if (ca + ua) > 0.0 else True,
                "canonical_activity_covers_user_when_needed": ca >= ua if ua > 0 else ca > 0,
                "autonomous_continuation": True,
                "shared_features": ["time", "rhythm", "pitch", "envelope", "phase", "modulation"],
            }
        except Exception:
            pass

    def _canonical_voice_gain(self, instrument_name, user_count, canonical_count, cluster_count):
        """Allocate protected user share plus level-weighted five-canonical share."""
        mem = self.instrument_sequencer_memory.get(instrument_name, {})
        count = int(mem.get("pattern_length", len(mem.get("steps", [])) or 1))
        is_user = any(self._step_has_net_effect(mem, i) for i in range(count)) if hasattr(self, "_step_has_net_effect") else False
        control = float(getattr(self, "canonical_signal_control", CANONICAL_SIGNAL_CONTROL_DEFAULT))
        active = self._active_engine_sources()
        total = sum(self._canonical_level(k) for k in active)
        if not active or total == 0.0:
            return 1.0 / max(cluster_count, 1)
        if is_user:
            return 0.5 / max(user_count, 1)
        owner = str(mem.get("canonical_owner", "") or "")
        source = owner.split(":", 1)[1] if owner.startswith("canonical:") and ":" in owner else ""
        if source == "phase-lock": source = "phase_lock"
        level = self._canonical_level(source) if source in active else (total / max(len(active), 1))
        return control * level / total

    def _hdcd_node_field(self, op_idx, row_idx, seed_value, mem=None):
        """Hierarchical node field driven by five canonical levels and LOCK character."""
        import hashlib
        active = self._active_engine_sources() if hasattr(self, "_active_engine_sources") else set()
        levels = self._canonical_levels()
        locks = self._lock_characteristics()
        seed_bits = _safe_int_seed(seed_value)
        rand_bits = int(getattr(self, "_rand_instance_seed", 0) or 0)
        op_name = self.instrument_names_48[op_idx] if 0 <= op_idx < len(self.instrument_names_48) else str(op_idx)
        def u01(label):
            d = hashlib.sha256(label.encode("utf-8", "replace")).digest()
            return int.from_bytes(d[:8], "big") / 2**64
        root = f"hdcd|{seed_bits}|rand={rand_bits if 'randomizer' in active else 0}"
        node = f"{root}|node|{op_idx}|{op_name}"
        row = f"{node}|row|{row_idx}"
        u = u01(node + "|u"); v = u01(node + "|v"); w = u01(row + "|w")
        field = {"enabled": True, "phase": (u-.5)*math.tau*.30, "detune": (v-.5)*.0035,
                 "mod_rate": .78+.48*w, "trigger_probability": 0.0, "canonical": tuple(sorted(active)),
                 "goava_phase": 0.0, "node_seed": _safe_int_seed(u01(node+"|seed")*2**32), "phase_lock_target": None,
                 "canonical_levels": levels, "phase_lock_characteristics": locks}
        if "randomizer" in active:
            lv = levels["randomizer"]
            field["trigger_probability"] += lv * (.72 + .22*u01(row+"|randomizer"))
        if "seeded" in active:
            lv = levels["seeded"]
            field["phase"] += lv * (u01(row+"|seeded-phase")-.5)*math.tau*.16
            field["detune"] += lv * (u01(row+"|seeded-detune")-.5)*.0018
            field["trigger_probability"] += lv * (.45 + .20*u01(row+"|seeded-trig"))
        field["euclid_weight"] = 0.0
        if "euclidean" in active:
            lv = levels["euclidean"]
            # Deterministic Euclidean pulse field: no extra RNG, so save/load and
            # WAV/MP3/MP4 renders agree exactly for the same project state.
            cycle = max(3, 5 + (op_idx % 8))
            pulses = max(1, min(cycle - 1, int(round(cycle * (0.30 + 0.35 * u01(node + "|euclid-density"))))))
            hit = 1.0 if ((row_idx * pulses + op_idx) % cycle) < pulses else 0.0
            field["euclid_weight"] = lv
            field["trigger_probability"] += lv * (0.16 + 0.44 * hit)
            field["mod_rate"] *= 0.90 + 0.20 * hit * lv
        if "phase_lock" in active:
            lv = levels["phase_lock"]
            coupling = locks["coupling"] * lv
            mode = str(getattr(self, "phase_lock_time_mode", "middle") or "middle")
            if mode == "time invariant":
                lock_label = f"{root}|pair-invariant|{op_idx}"
            elif mode == "time variant":
                lock_label = f"{root}|pair-variant|{op_idx}|row|{row_idx}|t|{row_idx * 3}"
            else:
                lock_label = f"{root}|pair|{op_idx}|row|{row_idx}"
            field["trigger_probability"] += coupling * (.35 + .20*u01(lock_label+"|trig"))
            roster = max(1, len(getattr(self, "instrument_names_48", []) or []))
            target = (roster - 1 - op_idx) % roster
            field["phase_lock_target"] = target
            lo, hi = sorted((op_idx, target))
            pu = u01(lock_label + f"|{lo}|{hi}")
            field["phase"] = field["phase"]*(1.0-coupling) + (pu-.5)*math.tau*locks["phase_spread"]*lv
            field["detune"] *= (1.0 - lv*(1.0-locks["detune_link"]))
            tp = locks["timing_pull"] * lv
            field["mod_rate"] = (1.0-tp)*field["mod_rate"] + tp*1.0
        if "goava" in active:
            lv = levels["goava"]
            events = getattr(self, "goava_note_events", []) or []
            if events:
                ev = events[row_idx % len(events)]
                raw = float(ev.get("raw", ev.get("seed", 0.0)) or 0.0)
                weight = float(np.clip(ev.get("weight", 1.0), 0.0, 1.0))
                field["goava_phase"] = (raw*MEUM_NORM + (op_idx+1)*MEUM_INV) % math.tau
                field["phase"] += lv*.10*series_sin(field["goava_phase"])
                field["mod_rate"] *= 1.0 + lv*((.84 + .30*weight)-1.0)
        field["trigger_probability"] = float(np.clip(field["trigger_probability"], 0.0, 0.97))
        # Canonical phase shift: a seeded offset composed from the lock pair
        # and the row, written into the field so the slot and the voice agree.
        locks = field.get("phase_lock_characteristics") or {}
        spread = float(locks.get("phase_spread", 0.20) or 0.20)
        mode = str(getattr(self, "phase_lock_time_mode", "middle") or "middle")
        if mode == "time invariant":
            shift = (u01(f"{root}|phase-shift|{op_idx}") - 0.5) * math.tau * spread
        elif mode == "time variant":
            shift = (u01(f"{root}|phase-shift|{op_idx}|{row_idx}|{row_idx * 3}") - 0.5) * math.tau * spread
        else:
            shift = (u01(f"{root}|phase-shift|{op_idx}|{row_idx}") - 0.5) * math.tau * spread
        field["phase_shift"] = float(shift)
        field["phase"] = float(field["phase"]) + float(shift)
        return field

    def _multinode_voice_field(self, op_idx, row_idx, seed_value, mem=None):
        return self._hdcd_node_field(op_idx, row_idx, seed_value, mem)

    def _multinode_step_trigger(self, field, op_idx, row_idx, step_idx, user_active):
        """Deterministic canonical gate; authored hits always win, never random."""
        if user_active:
            return True
        active = tuple(field.get("canonical", ()) or ())
        if not active:
            return False
        try:
            p = float(np.clip(float(field.get("trigger_probability", 0.0)), 0.0, 1.0))
        except Exception:
            p = 0.0
        if p <= 0.0:
            return False
        # Evenly phased deterministic lattice. Canonical engines may omit/continue
        # their own events, but no RNG/hash draw is used to decide probability.
        seed_bits = _safe_int_seed(self.get_numeric_seed())
        modulus = 16
        phase_index = (int(step_idx) + int(row_idx) * 3 + int(op_idx) * 5 + seed_bits) % modulus
        return (float(phase_index) / float(modulus)) < p

    def _apply_canonical_synth_controls(self, instrument_name, state):
        """Apply selectable canonical authority to synth controls at 50–100% strength.

        User-authored state remains the base; the strategy determines how authority is earned. Active canonical engines provide the
        control target; increasing the number of active canonical engines increases
        authority from 50% toward 100%. The function returns an effective copy and
        never requires the UI slider itself to be rewritten during audio rendering.
        """
        st = copy.deepcopy(state if isinstance(state, dict) else {})
        active = 0
        for attr in ("btn_local_randomize", "btn_local_phase_lock", "btn_idealize_rhythm", "btn_seeded_randomize", "btn_fractal_seed_mode"):
            btn = getattr(self, attr, None)
            try:
                active += int(bool(btn and btn.isChecked()))
            except Exception:
                pass
        active += int(bool(getattr(self, "goava_active", False)))
        active += int(bool(getattr(self, "btn_fractal_seed_mode", None) and self.btn_fractal_seed_mode.isChecked() and self._canonical_level("fractal_seed") > 0.0))
        # CANONICAL_SIGNAL_CONTROL_2026: this scalar is an invariant, not an
        # optional effect. Even with no explicit toggle and with no carrier,
        # canonical authority is never allowed below 50%. Additional canonical
        # engines can raise authority to 100%. User-authored values remain the
        # base; the canonical target is projected over them rather than rewriting
        # the source data.
        strength = float(self._update_canonical_signal_control(instrument_name))
        generated = (getattr(self, "instrument_param_generated", {}) or {}).get(instrument_name, {})
        if not isinstance(generated, dict) or not generated:
            # Seeded canonical macro target without touching instrument_param_state.
            try:
                ctx = float(self._contextual_numerology(instrument_name, self.instrument_names_48.index(instrument_name), self.instrument_names_48.index(instrument_name)))
                generated = canonical_macro_defaults(ctx, self.instrument_names_48.index(instrument_name))
            except Exception:
                generated = {}
        if not isinstance(generated, dict) or not generated:
            return st
        for key in ("morph", "harmonic_freq", "chaos", "fold_depth", "harmonic_lattice",
                    "drive", "filter", "tuning", "am_depth", "fm_depth", "pm_depth",
                    "am_rate", "fm_rate", "pm_rate", "phase_shift", "eq_amount"):

            if key not in generated:
                continue
            try:
                gv = float(generated[key])
                uv = float(st.get(key, gv))
                st[key] = (1.0 - strength) * uv + strength * gv
            except Exception:
                pass
        # EQ topology follows the same user↔canonical authority law as the synths.
        # Canonicals may add/remove/reorder/define poles. User topology is never
        # destroyed: canonical-only and user-only poles are response-weighted.
        try:
            _user_poles=_normalize_eq_poles(st.get("eq_poles"), legacy_curve=st.get("eq_curve",[0.0]*8))
            _canon_poles=_normalize_eq_poles(generated.get("eq_poles") or canonical_eq_poles(0.5,0))
            st["eq_poles"]=blend_eq_poles(_user_poles,_canon_poles,amount=strength)
            st["eq_curve"]=_eq_legacy_curve_from_poles(st["eq_poles"])
            if any(abs(float(p.get("gain_db",0.0))*float(p.get("_mix_weight",1.0)))>1e-8 for p in st["eq_poles"]):
                st["eq_shape"]="Custom"
        except Exception:
            pass
        st["canonical_synth_control"] = strength
        # CANONICAL_VOICE_CORE_2026: for canonical-owned slots, amp/pitch/phase/trigger
        # are explicit controls, not incidental side effects. User-owned program slots
        # remain readable; canonical-owned slots receive a deterministic polyphonic chord.
        try:
            mem = self._current_sequence_mem(instrument_name)
            user_owned = bool(mem.get("user_owned", False)) or any(self._step_has_net_effect(mem, i) for i in range(int(mem.get("pattern_length", DEFAULT_SEQUENCE_LENGTH) or DEFAULT_SEQUENCE_LENGTH)) if hasattr(self, "_step_has_net_effect"))
            if not user_owned:
                st["canonical_amp"] = float(np.clip(generated.get("amp", generated.get("amplitude", 1.0)), 0.0, 2.0))
                st["canonical_pitch"] = float(generated.get("pitch", generated.get("frequency_ratio", 1.0)))
                st["canonical_phase"] = float(generated.get("phase_shift", 0.0))
                st["canonical_trigger"] = float(np.clip(generated.get("trigger_probability", 1.0), 0.0, 1.0))
                st["canonical_chord_ratios"] = [1.0, 1.25, 1.5, 2.0]
        except Exception:
            pass
                # CANONICAL_ON_20261106: make sure the master multidim clone has
        # EQ and sidechain checked ON so canonicals actually drive those panels.
        try:
            clones = st.setdefault("md_clones", {})
            multi = clones.setdefault("multidim", {})
            if not isinstance(multi, dict):
                multi = {}
                clones["multidim"] = multi
            multi.setdefault("enabled", True)
            multi["enabled"] = True
            multi.setdefault("low_db", 1.5)
            multi.setdefault("high_db", 1.0)
            multi.setdefault("source", "master")
            multi.setdefault("depth", 0.35)
        except Exception:
            pass
        return st

    def _canonical_range_proof_report(self):
        """Machine-checkable proof of canonical authority and resonance ranges."""
        authority_samples = [
            float(np.clip(0.50 + 0.10 * min(int(engines), 5), 0.50, 1.00))
            for engines in range(6)
        ]
        resonance_samples = [0.50, 0.75, 1.00, 1.25, 1.50]
        return {
            "authority_minimum": 0.50,
            "authority_maximum": 1.00,
            "authority_samples": authority_samples,
            "authority_default": float(getattr(self, "canonical_signal_control", 1.00)),
            "authority_default_strategy": str(getattr(self, "canonical_control_strategy", "Full Canonical")),
            "authority_all_in_range": all(0.50 <= v <= 1.00 for v in authority_samples),
            "resonance_activity_minimum": 0.50,
            "resonance_activity_baseline": 1.00,
            "resonance_activity_maximum": 1.50,
            "resonance_activity_samples": resonance_samples,
            "resonance_all_in_range": all(0.50 <= v <= 1.50 for v in resonance_samples),
            "resonance_full_user_activity_target": 0.50,
            "resonance_full_user_inactivity_target": 1.50,
            "resonance_is_not_source_share": True,
            "composition_coefficients": {
                "canonical": float(getattr(getattr(self, "spin_canonical_live_overblend", None), "value", lambda: CANONICAL_LIVE_OVERBLEND_DEFAULT_PCT)()) / 100.0,
                "userdata": 1.0 - float(getattr(getattr(self, "spin_canonical_live_overblend", None), "value", lambda: CANONICAL_LIVE_OVERBLEND_DEFAULT_PCT)()) / 100.0,
            },
            "composition_coefficients_sum": 1.00,
            "canonical_waveform_overblend_optional": True,
            "exact_100_percent_authority_available": True,
            "exact_150_percent_resonance_available": True,
            "shared_feature_completeness": 1.0,
            "self_healing_coverage": True,
            "user_memory_rewrite_required": False,
            "note": "100% is canonical authority; 150% is continuation resonance/activity, not final output gain.",
        }

    def _prove_canonical_50_to_100_range(self):
        """Compatibility wrapper for the formal 50%→100% canonical range proof."""
        report = self._canonical_range_proof_report()
        report.update({
            "minimum": report["authority_minimum"], "maximum": report["authority_maximum"],
            "strategy_values": {"Seeded Baseline":0.50, "Engine Stack":1.00, "Full Canonical":1.00, "Coverage Adaptive":1.00},
            "spatial_activity_modulus": 0.50, "spatial_activity_meets_50pct": True,
            "composition_coefficients": report.get("composition_coefficients", {"canonical":0.0, "userdata":1.0}),
            "composition_coefficients_sum": 1.00, "final_energy_theorem": False,
            "canonical_resonance_activity_range": {"minimum": 0.50, "baseline": 1.00, "maximum": 1.50},
            "resonance_full_user_activity_target": 0.50,
            "resonance_full_user_inactivity_target": 1.50,
            "resonance_is_not_source_share": True,
        })
        return report

    def _verify_canonical_user_carrier_contract(self, carrier_present=None):
        """Describe the optional canonical waveform overblend contract.

        Canonical control/activity remains independent from final source-waveform
        share.  The default is an equal user/canonical boundary (50% canonical overblend),
        preserving live dynamics while canonical transforms may still shape U.
        """
        if carrier_present is None:
            carrier_present = getattr(self, "_canonical_user_blend_ledger", {}).get("carrier_present", False)
        try:
            c = float(self.spin_canonical_live_overblend.value()) / 100.0 if hasattr(self, "spin_canonical_live_overblend") else CANONICAL_LIVE_OVERBLEND_DEFAULT_PCT / 100.0
        except Exception:
            c = 0.0
        c = max(0.0, min(1.0, c)); u = 1.0 - c
        return {
            "equation": f"M0 = {c:.6f}*C + {u:.6f}*U (when U is present; canonical fallback otherwise)",
            "canonical_coefficient": c,
            "userdata_coefficient": u,
            "canonical_overblend_optional": True,
            "canonical_overblend_default": CANONICAL_LIVE_OVERBLEND_DEFAULT_PCT / 100.0,
            "canonical_activity_authority_separate_from_waveform_share": True,
            "coefficients_sum_to_one": (c + u) == 1.0,
            "carrier_is_modulation_source": bool(carrier_present),
            "carrier_is_third_additive_bus": False,
            "carrier_phase_lock": 0.50,
            "scope": "composition_boundary_before_nonlinear_master_effects",
            "energy_theorem": False,
        }

    def _r32_voice_post(self, name, hz, t, voice, sr):
        """LOCAL FX → Layer EQ → Mod Osc on one rendered voice — the same functions the live
        key path runs through its _render_instrument_voice hooks. Inactive stages cost one check."""
        y = voice
        n = int(np.asarray(voice).size)
        try:
            import fx_panels as _fx
            v = _fx.effective(self, "local", str(name))
            if _fx.active(v):
                y = _fx.process(y, sr, v, float(getattr(self, "global_bpm", 120.0) or 120.0))
        except Exception:
            pass
        try:
            import layer_mixer as _lm
            lo, mi, hi = _lm.gains(self, name)
            if lo or mi or hi:
                y = _lm.eq3(y, sr, lo, mi, hi)
        except Exception:
            pass
        try:
            import mod_osc as _mo
            y = _mo.process_voice(self, name, hz, t, y, sr)
        except Exception:
            pass
        y = np.nan_to_num(np.asarray(y, dtype=np.float32).ravel(), nan=0.0, posinf=0.0, neginf=0.0)
        return y if y.size == n else np.asarray(voice, dtype=np.float32)

    def _render_mixdown_buffer(self, max_rows=None):
        # MIX_MODE_R31.7: mono is the always-default mode. Stereo is opt-in only.
        # When stereo is requested the pipeline is rendered per channel with
        # constant-power pan from instrument pan values; otherwise the native
        # mono master is used exactly as before.
        self._mix_mode = getattr(self, "_mix_mode", "mono")  # "mono" | "stereo"
        if self._mix_mode not in ("mono", "stereo"):
            self._mix_mode = "mono"


        # GROOVEBOX_R23R_XMOD_MASTER_20261031: XMOD is the master amount for all
        # Meum AM/FM/PM modulation. Effective depth per voice and row is
        #   panel depth x XMOD slider x clip(canonical curve + Mod Depth route/step, 0..2)
        try:
            _xmod_master = float(np.clip(float((getattr(self, "global_mod_state", {}) or {}).get("xmod", 1.0)), 0.0, 2.0))
        except Exception:
            _xmod_master = 1.0
        try:
            _canon_mod_growth = float(self._canonical_mod_growth())
            _canon_mod_target = float(self._canonical_mod_state().get("xmod", 1.0)) if _canon_mod_growth > 0.0 else 1.0
        except Exception:
            _canon_mod_growth, _canon_mod_target = 0.0, 1.0
        # GROOVEBOX_INHARMONIC_GATE_20261102: the seeded per-voice entropy used to weigh an
        # off-harmonic partial bank and an FM term into every non-GOAVA voice, so a blank
        # project with only canonicals and a seed already carried over/undertones. That
        # content now follows the explicit "Inharmonic partials" amount (default 0 = a pure
        # harmonic series for every voice, GOAVA included).
        try:
            _inh_amt = float(np.clip(float(self._geometric_mixer_snapshot().get("inharmonic", 0.0)), 0.0, 1.0))
        except Exception:
            _inh_amt = 0.0
        # R12_PLAYLIST_SEQUENCER_THREADS: playlist and sequencer planning are
        # frozen concurrently, while DSP synthesis stays on its deterministic
        # render path.  This removes two large mutable-data copies from the
        # synth hot path without allowing races in the actual mix commit.
        try:
            _pf = self._playlist_lane.submit(copy.deepcopy, getattr(self, "master_playlist_data", []) or [])
            _sf = self._sequencer_lane.submit(copy.deepcopy, (
                getattr(self, "instrument_sequencer_memory", {}) or {},
                getattr(self, "instrument_sequence_banks", {}) or {},
                getattr(self, "instrument_selected_sequence", {}) or {},
            ))
            self._render_playlist_snapshot = _pf.result()
            self._render_sequencer_snapshot, self._render_sequence_banks_snapshot, self._render_selected_sequence_snapshot = _sf.result()
            # GROOVEBOX_R32_PLAYBACK_STYLES_20261110: reverse / ping-pong / shuffle / section loop /
            # random walk act on the frozen render rows only (stored rows untouched; forward = identity).
            try:
                import composition_tools as _ct
                self._render_playlist_snapshot = _ct.styled_rows(self, self._render_playlist_snapshot)
            except Exception:
                pass
        except Exception:
            self._render_playlist_snapshot = _fast_copy(getattr(self,"master_playlist_data",[]) or [])
            self._render_sequencer_snapshot = copy.deepcopy(getattr(self,"instrument_sequencer_memory",{}) or {})
            self._render_sequence_banks_snapshot = copy.deepcopy(getattr(self,"instrument_sequence_banks",{}) or {})
            self._render_selected_sequence_snapshot = copy.deepcopy(getattr(self,"instrument_selected_sequence",{}) or {})
        self._maintain_stochastic_harmonic_phase_lock()
        try:
            self._ensure_canonical_control_integrity(row_idx=0)
        except Exception:
            pass

        """Shared float32 mono render used by both realtime Play and WAV Export.

        Uniform pipeline, in order:
          1. canonical voices → unison snapshot  (engines + harmonic lattice,
             per-voice PNG-free, carries user material)
          2. structural bus cross-convolution + domain equations + seed-script
             T-axis modulation (compositional layers, still pre-effect)
          3. MASTER EFFECTS, tail-only, in this exact order — Fractallizer
             (spectral), EQR (tensor), PKP (tempo-locked AM), PED, peak-snap.
             None of these ever write back to the unison snapshot, so effect
             sliders cannot influence the canonical engines or the fingerprint.

        PHASE CONTINUITY CONTRACT (2026):
          Within a single call the per-voice phase carry advances across rows
          so row boundaries stay click-free.  Across separate full-render calls
          (Play button, Export, successive mixes) the carry is deliberately
          reset to the empty dict.  Both Play and Export therefore start from
          the same seed-defined phase0 state, producing bit-identical buffers
          for identical inputs.  Live streaming is just playback of that
          fixed buffer — no inter-call phase memory is required.
        """
        # Reset per-voice phase carry so every full mixdown is canonical from
        # the seed/phase0 lattice.  Intra-render row continuity is still
        # preserved by the carry updates inside the voice loop.
        self._voice_phase_carry = {}
        # Freeze imported-carrier + canonical flags into the seed environment so
        # file-input pathways and seed scripts stay coherent for every instrument.
        try:
            self._canonical_render_input_context = dict(self._canonical_input_context())
        except Exception:
            pass
        sample_rate = int(getattr(self, 'preferred_sample_rate', TARGET_SAMPLE_RATE) or TARGET_SAMPLE_RATE)
        sample_rate = max(44100, min(192000, sample_rate))
        bpm = float(self._rin("bpm", 120.0))
        rows = int(self._rin("rows", DEFAULT_PLAYLIST_ROWS))
        if max_rows is not None:
            rows = min(rows, int(max_rows))
        # Reference grid length (legacy max-pattern) — used only as a fallback
        # for beats_per_row when the user has not set an explicit bar length.
        seq_len = max(
            [int((m or {}).get("pattern_length", len((m or {}).get("steps", [])) or 1))
             for m in (getattr(self, "_render_sequencer_snapshot", None) or getattr(self, "instrument_sequencer_memory", {}) or {}).values()] or
            [int(self.spin_seq_length.value()) if hasattr(self, "spin_seq_length") else DEFAULT_SEQUENCE_LENGTH]
        )
        global_playlist_enabled = self.chk_global_playlist.isChecked() if hasattr(self, 'chk_global_playlist') else True

        # IMPORTANT: render is read-only with respect to playlist composition.
        # A prior version performed table→memory synchronization here, allowing a
        # stale UI table to erase the freshly reconciled canonical identity/tail.
        # User edits synchronize explicitly from their edit handlers instead.

        seconds_per_beat = 60.0 / positive_bpm(bpm)
        # SEQUENCE_SCALE_2026: playlist row interval is measured in BEATS
        # (master canonical / user), not "max pattern × 16th".  Every instrument
        # pattern — any step count — is scaled to fit exactly one row:
        #     inst_step_duration = row_duration / pattern_len
        # so a 16-step and a 32-step sequence share the same row wall-clock
        # and stay phase-aligned via per-step + per-operator offsets.
        try:
            if hasattr(self, "spin_row_beats"):
                beats_per_row = float(self.spin_row_beats.value())
            elif hasattr(self, "spin_playlist_beats"):
                beats_per_row = float(self.spin_playlist_beats.value())
            else:
                # Default one bar (4 beats). Legacy: if no control, still prefer
                # 4 beats over max-pattern×16th so mixed lengths fit one bar.
                beats_per_row = 4.0
        except Exception:
            beats_per_row = 16.0
        beats_per_row = max(0.25, min(64.0, float(beats_per_row)))
        row_duration = seconds_per_beat * beats_per_row
        # Reference 16th for engines/UI that still speak in "grid steps"
        step_duration = seconds_per_beat / 4.0
        total_duration = max(0.002, rows * row_duration)
        try:
            self._prepare_render_geometry()
        except Exception as _geo_exc:
            self._render_geometry = {"ball": None, "density": None}
            print(f"[Render] instance geometry skipped: {_geo_exc}")

        n_samples = int(sample_rate * total_duration)
        _opt = getattr(self, "_scode_optimizer", None)
        # RUST_SCODE_PARALLEL_20260922: ask the already-required sCode planner for
        # an execution plan whose shape is the actual render size.  These values
        # tune worker count / bounded FFT block only; they never enter composition.
        _rust_render_plan = dict(getattr(self, "_scode_optimizer_plan", {}) or {})
        if _opt is not None:
            try:
                _rust_render_plan = _opt.optimize_sync(
                    {"rust_render_samples": int(n_samples)}, dirty_mask=1, frame=0,
                    shape=int(n_samples), bypass_cache=False
                )
            except Exception:
                pass
        self._rust_render_plan = dict(_rust_render_plan)
        _native_tune_workers(_rust_render_plan, n_samples)
        # SCODE_FULL_ACCEL_V4: the render-time coordinate grid is deterministic
        # and read-only. Reuse it for normal-sized repeated Play/Export renders.
        # Very long renders bypass the cache to keep memory bounded.
        if _opt is not None and n_samples <= 2_000_000:
            t = _opt.memoized_result(
                "audio_time_grid", (sample_rate, round(total_duration, 12), n_samples),
                lambda: np.linspace(0.0, total_duration, n_samples, endpoint=False), max_entries=4
            )
        else:
            t = np.linspace(0.0, total_duration, n_samples, endpoint=False)
        master = np.zeros(n_samples, dtype=np.float32)
        canonical_bus = np.zeros(n_samples, dtype=np.float32)
        userdata_bus = np.zeros(n_samples, dtype=np.float32)
        self._canonical_activity_ledger = {}

        base_eqr = float(self._rin("eqr", EQR_DEFAULT))
        pkp_envelope = float(self._rin("pkp", 0.5))
        fractalizer_val = float(self._rin("fractalizer", FRACTALLIZER_DEFAULT))
        # PKP envelope follower is permanently force-enabled (toggle removed).
        pkp_auto = True
        seed_val = self.get_numeric_seed()
        np.random.seed(_safe_int_seed(seed_val))
        # Shared effect engines (low-lag). All effects max 50% mix at 100% activation.
        # HarmonicLattice = efficient per-synth; MusicFractallizer = global/import master.
        if not hasattr(self, '_harmonic_lattice') or self._harmonic_lattice is None:
            self._harmonic_lattice = HarmonicLattice(sample_rate=sample_rate)
        else:
            self._harmonic_lattice.sample_rate = sample_rate
        if not hasattr(self, '_music_fractallizer') or self._music_fractallizer is None:
            self._music_fractallizer = MusicFractallizer(sample_rate=sample_rate)
        else:
            self._music_fractallizer.sample_rate = sample_rate
        if not hasattr(self, '_eqr_tensor') or self._eqr_tensor is None:
            self._eqr_tensor = EQRTensorEngine()

        # CONVOLVE_FIT_FEATURE: carrier is loaded once per render.
        imported_carrier = self._resample_carrier(n_samples, sample_rate)
        convolve_fit_enabled = bool(
            hasattr(self, "chk_convolve_fit") and self.chk_convolve_fit.isChecked()
        )
        convolve_fit_amount = (
            float(self.slider_global_convolve.value()) / 100.0
            if hasattr(self, "slider_global_convolve") else 0.0
        )
        # CARRIER_ROLE_2026: imported media is a reference/modulation source,
        # not a third additive bus. It participates through bounded XMOD, phase-lock,
        # and optional convolve kernel use. This keeps the canonical/user blend a
        # two-source contract instead of allowing an external carrier to bypass it.

        try:
            import automation_bus as _r32_auto
        except Exception:
            _r32_auto = None
        _r32_auto_used = False
        for row_idx in range(rows):
            if hasattr(self, "_set_work_progress") and (row_idx == 0 or row_idx == rows - 1 or row_idx % max(1, rows // 40) == 0):
                _kind = str((getattr(self, "_render_pipeline_stats", {}) or {}).get("last_kind", "Render") or "Render")
                self._set_work_progress(_kind, min(94, 5 + int(89 * (row_idx + 1) / max(1, rows))), f"{_kind} · synth row {row_idx + 1}/{rows}")
            start_time = row_idx * row_duration
            end_time = start_time + row_duration
            # R32.8 AUTOMATION_IN_RENDER: lanes advance with the render clock (per row), so an
            # export carries the same automation as live playback.
            if _r32_auto is not None:
                _r32_auto_used = _r32_auto.render_tick(self, start_time / max(1e-9, seconds_per_beat)) or _r32_auto_used
            try:   # R32.9: per-sequence local variables morph in by the row's shift vote
                import perseq_vars as _psv
                _r32_psv_used = _psv.render_row(self, row_idx) or locals().get("_r32_psv_used", False)
            except Exception:
                pass
            # PERF + SCODE_FULL_ACCEL_V4: rows are contiguous by construction.
            # Use an O(1) slice instead of allocating/scanning an n_samples-wide
            # Boolean mask for every row. This preserves the exact same t samples.
            start_idx = max(0, min(n_samples, int(np.searchsorted(t, start_time, side="left"))))
            end_idx = max(start_idx, min(n_samples, int(np.searchsorted(t, end_time, side="left"))))
            if end_idx <= start_idx:
                continue
            mask = slice(start_idx, end_idx)
            local_t = t[mask] - start_time
            if _opt is not None:
                row_mix = _opt.borrow_array(f"audio_row_mix_{threading.get_ident()}", local_t.shape, np.float32, zero=True)
            else:
                row_mix = np.zeros_like(local_t, dtype=np.float32)
            velocity_scale = 1.0
            if getattr(self, "goava_active", False):
                _goava_beat_t = self._composition_beat_for_row(row_idx)
                _goava = self._goava_mix(local_t, row_idx, step_duration, row_start_beat=_goava_beat_t)
                # GOAVA_LEVEL_GAIN_20261102: the GOAVA level is a real linear gain, not a
                # switch. 100% is GOAVA's own fixed chord amplitudes (root 0.33), which is
                # its maximum influence; 0% is silent; the 33% default is a third of that.
                # No limiter, no saturation.
                _goava = (_goava * np.float32(self._canonical_level("goava"))).astype(np.float32)
                row_mix += _goava
                canonical_bus[mask] += _goava

            # CANONICAL_CONTINUATION_2026: always maintain an autonomous canonical
            # activity stream. User activity is mirrored as a shared counterpart,
            # then canonical-only lattice activity fills the remainder. No user
            # memory is written here and no final-signal clamp is used.
            try:
                # NO_CONTINUATION_VOICE_20261102: the autonomous "continuation" voice is a synthetic
                # sine (about 0.3 peak) hard-gated on/off 16 times per row with no ramp, added to
                # the canonical bus outside every instrument ensemble. That is the square-amplitude
                # beeping heard on blank patches with a seed and canonicals. It is retired: it only
                # runs when GROOVEBOX_CANONICAL_CONTINUATION=1 is set deliberately.
                if (os.environ.get("GROOVEBOX_CANONICAL_CONTINUATION", "") != "1"
                        or not bool(getattr(self, "canonical_continuation_enabled", False))):
                    raise RuntimeError("canonical continuation disabled")
                _user_abs = np.abs(userdata_bus[mask].astype(np.float64))
                _user_peak = float(np.max(_user_abs)) if _user_abs.size else 0.0
                _user_gate_probe = _user_abs > max(1e-7, _user_peak * 0.08)
                _user_activity = float(np.mean(_user_gate_probe)) if _user_gate_probe.size else 0.0
                _res_factor = self._canonical_resonance_for_activity(_user_activity)
                _canonical_cont_wave, _canonical_cont_gate = self._canonical_continuation_wave(
                    local_t, row_idx, seed_val, user_gate=_user_gate_probe, resonance_factor=_res_factor
                )
                canonical_bus[mask] += np.where(_canonical_cont_gate, _canonical_cont_wave, 0.0).astype(np.float32)
            except Exception:
                pass

            if global_playlist_enabled and row_idx < len(getattr(self, '_render_playlist_snapshot', None) or getattr(self, 'master_playlist_data', [])):
                entry = self.master_playlist_data[row_idx]
                op_time_offsets = entry.get("operator_time_offsets") if isinstance(entry, dict) else None
                if not isinstance(op_time_offsets, dict):
                    op_time_offsets = {}
                primary_op = entry.get("operator", self.instrument_names_48[0])
                velocity_scale = float(entry.get("velocity", 1.0))
                # The playlist's scalar operator is only the primary identity.
                # Render the complete final unison roster from operators/sequence_refs;
                # otherwise the UI can correctly show consensus while the renderer
                # silently plays only one instrument.
                render_names = []
                raw_ops = entry.get("operators", [])
                if isinstance(raw_ops, str):
                    raw_ops = [x.strip() for x in raw_ops.split(",") if x.strip()]
                render_names.extend(str(x).strip() for x in (raw_ops or []) if str(x).strip())
                raw_refs = entry.get("sequence_refs", [])
                if isinstance(raw_refs, str):
                    raw_refs = [x.strip() for x in raw_refs.split(",") if x.strip()]
                for ref in raw_refs or []:
                    nm = str(ref).split(":", 1)[0].strip()
                    if nm:
                        render_names.append(nm)
                render_names.append(str(primary_op).strip())
                render_names = list(dict.fromkeys(n for n in render_names if n in self.instrument_names_48))
                active_cluster = [self.instrument_names_48.index(n) for n in render_names]
                try:
                    _seed_vals = list(self.get_seed_values(t_value=0.0) or [])
                except Exception:
                    _seed_vals = []
                if len(_seed_vals) > 1 and len(active_cluster) < len(_seed_vals):
                    names = list(getattr(self, "instrument_names_48", []) or [])
                    for _i in range(min(len(names), len(_seed_vals))):
                        if _i not in active_cluster:
                            active_cluster.append(_i)
                    active_cluster = sorted(set(active_cluster))
                if not active_cluster:
                    active_cluster = [0]
            else:
                # No playlist row: instruments with steps, plus seed-list width
                # so multi-value scripts are not collapsed to a single voice.
                op_time_offsets = {}
                active_cluster = []
                names = list(getattr(self, "instrument_names_48", []) or [])
                for _i, _nm in enumerate(names):
                    _mm = (getattr(self, "_render_sequencer_snapshot", None) or self.instrument_sequencer_memory).get(_nm, {})
                    _pc = int(_mm.get("pattern_length", len(_mm.get("steps", [])) or 1))
                    has_steps = False
                    try:
                        has_steps = any(self._step_has_net_effect(_mm, _si) for _si in range(_pc))
                    except Exception:
                        has_steps = any(bool(x) for x in (_mm.get("steps") or []))
                    if has_steps:
                        active_cluster.append(_i)
                try:
                    _seed_vals = list(self.get_seed_values(t_value=0.0) or [])
                except Exception:
                    _seed_vals = []
                _seed_txt = ""
                try:
                    _seed_txt = (self._seed_text() or "").strip()
                except Exception:
                    _seed_txt = ""
                if _seed_vals or _seed_txt:
                    n_need = max(len(_seed_vals), 1)
                    n_need = min(len(names), max(n_need, min(8, len(names))))
                    for _i in range(n_need):
                        if _i not in active_cluster:
                            active_cluster.append(_i)
                    active_cluster = sorted(set(active_cluster))
                if not active_cluster:
                    active_cluster = list(range(len(names)))

            # ROW_SPARSE_MASK_2026 (established once per row): a deterministic
            # subgroup gate derived purely from (seed, row, density).  Each row
            # keeps `density` fraction of the active instruments; the rest of that
            # row's voices are gated to 0 (their oscillators still advance phase
            # via the carry, so their geometric lattice stays coherent when they
            # return).  Off-canonical master shaping only — it never touches the
            # fingerprint, and density 1.00 (or unchecked) is byte-identical.
            _sp_mask = None
            try:
                _sp_enabled = bool(
                    getattr(self, "chk_sparse_mask", None) and self.chk_sparse_mask.isChecked()
                )
                if _sp_enabled:
                    _dens = float(getattr(self, "spin_sparse_density", None).value()) if getattr(self, "spin_sparse_density", None) is not None else 1.0
                    _dens = float(np.clip(_dens, 0.01, 1.0))
                    _nops = len(active_cluster)
                    _keep = max(1, min(_nops, int(round(_nops * _dens))))
                    if _nops > 1 and _keep < _nops:
                        _s = (int(_safe_int_seed(seed_val)) ^ (int(row_idx) * 0x9E3779B1)) & 0x7FFFFFFF
                        _rng = np.random.RandomState(_s or 1)
                        _picked = set(int(i) for i in _rng.choice(_nops, size=_keep, replace=False))
                        _sp_mask = set(int(active_cluster[i]) for i in _picked)
            except Exception:
                _sp_mask = None

            canonical_count = self._canonical_active_count()
            user_voice_count = 0
            if canonical_count:
                for _oi in active_cluster:
                    _nm = self.instrument_names_48[_oi]
                    _mm = (getattr(self, "_render_sequencer_snapshot", None) or self.instrument_sequencer_memory).get(_nm, {})
                    _pc = int(_mm.get("pattern_length", len(_mm.get("steps", [])) or 1))
                    if any(self._step_has_net_effect(_mm, _si) for _si in range(_pc)):
                        user_voice_count += 1

            # FULL_UNISON_2026 (established once per row): when all five
            # public canonicals run together the whole ensemble is driven by
            # ONE authoritative identity — a single shared seed, a single shared
            # fundamental, a single shared pitch ratio.  No seed script (list or
            # numeric) and no user patch (identity anchors, per-instrument
            # panels, presets, tuning) may re-split the raster into distinct
            # instrument characters.  Every instrument becomes an indistinguishable
            # voice of the 5-engine unison, including GOAVA as an equal canonical contributor.
            full_unison = self._full_canonical_unison_active()
            if full_unison:
                _unison_seed = float(seed_val or 0.0)
                _unison_base = float(self.spin_base_frequency.value()) if hasattr(self, "spin_base_frequency") else 432.0
                _unison_base *= MEUM_POWERS_36[0]
                _unison_ratio = float(_seed_to_pitch_ratio(_unison_seed, 0, 0))
                _unison_s_int = int(_safe_int_seed(_unison_seed))

            # UNION_IDENTITY_2026: ONE authoritative identity object used by
            # BOTH media under full unison, so audio and video register the
            # SAME union parameters and the SAME single entropy point per seed
            # (the audio/video symmetry is by construction, not coincidence).
            if full_unison:
                try:
                    _uabs = abs(_unison_seed)
                    _ufrac = _uabs - math.floor(_uabs)
                    self._union_identity = {
                        "seed": _unison_seed, "s_int": _unison_s_int,
                        "base": _unison_base, "ratio": _unison_ratio,
                        "entropy": float(entropy_draw_0_1(_uabs, _ufrac, _unison_s_int, 0)),
                    }
                except Exception:
                    pass

            # UNION_ENTROPY_2026 lazy ledger init (per render pass).
            if not hasattr(self, "_union_entropy_sum"):
                self._union_entropy_sum = 0.0
                self._union_entropy_sum_sq = 0.0
                self._union_entropy_n = 0
                self._union_entropy_samples = 0
                self._union_entropy_r_min = 1.0
                self._union_entropy_r_max = 0.0
                self._union_entropy_mean = ENTROPY_FIXED_POINT
                self._union_entropy_std = 0.0
                self._union_entropy_ok = True
                self._union_entropy_full_window = False

            # Collect voice contributions before committing them to buses so the
            # sidechain detector can see its source regardless of instrument order.
            # This keeps source/target routing deterministic and shared by Play/WAV.
            _row_voice_contribs = []
            _row_key_envs = {}
            for op_idx in active_cluster:
                op_name = self.instrument_names_48[op_idx]
                # Resize invariance: canonical playlist rows must render from their
                # authoritative canonical sequence bank entry, not from the ambient
                # selected-sequence pointer. Resize rebuilds canonical banks before the
                # UI pointer is refreshed; using the pointer here caused the post-resize
                # sound to differ until every engine was retoggled.
                mem = None
                try:
                    _row_refs = entry.get("sequence_refs", []) if (isinstance(entry, dict) and self._row_write_mode(row_idx) not in ("automation", "identity")) else []
                    if isinstance(_row_refs, str):
                        _row_refs = [x.strip() for x in _row_refs.split(",") if x.strip()]
                    for _ref_txt in (_row_refs or []):
                        _rt = str(_ref_txt).strip()
                        if "#S" in _rt:
                            _ref_op, _sid_txt = _rt.rsplit("#S", 1)
                        elif ":" in _rt:
                            _ref_op, _sid_txt = _rt.rsplit(":", 1)
                        else:
                            continue
                        if _ref_op.strip() != op_name:
                            continue
                        _sid = int(_sid_txt)
                        _bank = (getattr(self, "_render_sequence_banks_snapshot", None) or getattr(self, "instrument_sequence_banks", {}) or {}).get(op_name, {})
                        _candidate_mem = _bank.get(_sid) if isinstance(_bank, dict) else None
                        if isinstance(_candidate_mem, dict) and str(_candidate_mem.get("canonical_owner", "")).startswith(("canonical:", "heuristic:section")):
                            mem = _candidate_mem
                            break
                except Exception:
                    mem = None
                if not isinstance(mem, dict):
                    mem = (getattr(self, "_render_sequencer_snapshot", None) or self.instrument_sequencer_memory).get(
                        op_name, {"steps": [False] * 48, "amplitudes": [1.0] * 48, "pitches": [1.0] * 48}
                    )
                if full_unison:
                    # FULL_UNISON_2026: shared fundamental/seed/ratio.  The
                    # per-op MEUM_POWERS fold, the per-index seed list split and
                    # the op-indexed pitch ratio are the FIRST identities being
                    # cancelled — seed instructions can no longer make instrument
                    # N sound different from instrument M inside the unison.
                    base_freq = _unison_base
                    _voice_seed = _unison_seed
                    _seed_ratio = _unison_ratio
                    _s_int = _unison_s_int
                else:
                    base_freq = float(self.spin_base_frequency.value()) if hasattr(self, "spin_base_frequency") else 432.0
                    _master_slot = canonical_master_slot(int(op_idx) if np.isfinite(op_idx) else 0, max(2, len(self.instrument_names_48)))
                    base_freq *= MEUM_POWERS_36[_master_slot % 36]
                    # Per-voice evaluated seed (list scripts assign distinct numerics
                    # to each instrument instead of a shared hash/byte token).
                    try:
                        _voice_seed = float(self.get_seed_value_for_index(_master_slot, t_value=float(local_t[0]) if len(local_t) else 0.0))
                    except Exception:
                        _voice_seed = float(self.get_numeric_seed() or 0.0)
                    # >>> GROK_EDIT_BEGIN: render_seed_pitch
                    # Seed → real scale degree (~2 octaves). Tiny detunes were inaudible
                    # so every seed still "hit the same notes".
                    _seed_ratio = float(_seed_to_pitch_ratio(_voice_seed, _master_slot, 0))
                    # Stable integer seed must exist before any per-voice identity
                    # fields use it.  Keep this local and deterministic.
                    _s_int = int(_safe_int_seed(_voice_seed))
                    # <<< GROK_EDIT_END: render_seed_pitch
                # FULL_UNISON_2026: synthesis-identity terms keyed to the roster
                # slot collapse to constant 0 under unison; outside the unison
                # _vo == op_idx exactly (behavior unchanged).
                _vo = 0 if full_unison else canonical_master_slot(int(op_idx) if np.isfinite(op_idx) else 0, max(2, len(self.instrument_names_48)))
                # GLOBAL_BASE_FREQUENCY_TRACKING_HF25: instrument identity anchors
                # are resolved as ratios later. They must never replace this global
                # anchor with an absolute Hz value, otherwise the base-frequency
                # spinner would only retune some lanes and not others.
                _node_field = self._multinode_voice_field(op_idx, row_idx, _voice_seed, mem)
                _node_phase_bias = float(_node_field.get("phase", 0.0))
                _node_detune = float(_node_field.get("detune", 0.0))
                _node_mod_rate = float(_node_field.get("mod_rate", 1.0))
                # GROOVEBOX_R23R_SCODE_POOL_CLASSES_20261103: the per-voice work arrays come from the
                # sCode pool (one slab per kind and thread, reused by every instrument and row) —
                # identical contents to zeros_like / ones_like / full_like, no allocation per voice.
                _md_step = None          # set per voice below; never carried over from the previous voice
                if _opt is not None and hasattr(_opt, "borrow_vector") and local_t.ndim == 1:
                    _tid = threading.get_ident(); _nT = int(local_t.shape[0]); _ldt = local_t.dtype
                    step_env = _opt.borrow_vector(f"voice_env_{_tid}", _nT, _ldt, 0.0)
                    pitch_track = _opt.borrow_vector(f"voice_pitch_{_tid}", _nT, _ldt, 1.0)
                    chord_timbre_track = _opt.borrow_vector(f"voice_timbre_{_tid}", _nT, np.float32, 50.0)
                    step_phase_track = _opt.borrow_vector(f"voice_phase_{_tid}", _nT, _ldt, 0.0)
                    step_eq_gain_track = _opt.borrow_vector(f"voice_eq_{_tid}", _nT, _ldt, 0.0)
                    step_sidechain_track = _opt.borrow_vector(f"voice_sc_{_tid}", _nT, _ldt, 0.0)
                    step_key_track = _opt.borrow_vector(f"voice_key_{_tid}", _nT, _ldt, 0.0)
                else:
                    step_env = np.zeros_like(local_t)
                    pitch_track = np.ones_like(local_t)
                    chord_timbre_track = np.full_like(local_t, 50.0, dtype=np.float32)
                    step_phase_track = np.zeros_like(local_t)
                    step_eq_gain_track = np.zeros_like(local_t)
                    step_sidechain_track = np.zeros_like(local_t)
                    # GROOVEBOX_R23R_SIGNED_SIDECHAIN_BAND_EQ_20261103
                    step_key_track = np.zeros_like(local_t)      # negative sidechain = KEY (lift self, duck row)
                _step_band_eq = []                            # (i0, i1, gain_db, freq_hz, q) per step
                _canonical_overlay = None
                try:
                    # FIRST_RENDER_COVERAGE_20261102: the canonical-owned coverage for this (instrument, row) used to be
                    # created only later in the pass, so the first render after launch lacked content every later render had.
                    _ov_key = f"{op_name}:{int(row_idx)}"
                    if (getattr(self, "canonical_control_strategy", "Full Canonical") != "Seeded Baseline"
                            and _ov_key not in (getattr(self, "canonical_runtime_overlays", None) or {})
                            and self._canonical_missing_lanes()):
                        self._materialize_canonical_coverage(op_name, row_idx)
                except Exception:
                    pass
                try:
                    _canonical_overlay = (getattr(self, "canonical_runtime_overlays", {}) or {}).get(f"{op_name}:{int(row_idx)}")
                except Exception:
                    _canonical_overlay = None
                steps = mem.get("steps", [])
                amps = mem.get("amplitudes", [1.0] * 16)
                pitches = mem.get("pitches", [1.0] * 16)
                probabilities = mem.get("probabilities", [100] * 16)
                _mem_has_user = False
                try:
                    _mem_has_user = bool(mem.get("user_owned", False)) or any(self._step_has_net_effect(mem, i) for i in range(int(mem.get("pattern_length", len(steps) or 1) or 1)))
                except Exception:
                    _mem_has_user = bool(mem.get("user_owned", False))
                _ov_offsets = None
                if not _mem_has_user and isinstance(_canonical_overlay, dict):
                    _ovseq = _canonical_overlay.get("sequence") if isinstance(_canonical_overlay.get("sequence"), dict) else {}
                    if _ovseq.get("steps"):
                        steps = list(_ovseq.get("steps"))
                        amps = list(_ovseq.get("amplitudes", amps))
                        pitches = list(_ovseq.get("pitches", pitches))
                        probabilities = list(_ovseq.get("probabilities", probabilities))
                        _ov_offsets = _ovseq.get("offsets")   # CANONICAL_SEQ_DISPLAY_20261102: playback matches what the pads show
                        _ovcontrols = _ovseq.get("step_controls") if isinstance(_ovseq.get("step_controls"), dict) else {}
                        if _ovcontrols:
                            mem = dict(mem)
                            mem["step_controls"] = _ovcontrols
                offsets = mem.get("offsets", [0.0] * 16)
                if _ov_offsets:
                    offsets = list(_ov_offsets)
                pattern_len = max(1, int(mem.get("pattern_length", len(steps) or 1)))
                # SEQUENCE_SCALE_2026: fit this instrument's #steps into the
                # shared playlist row (beats_per_row × seconds_per_beat).
                # Different pattern lengths share the same row wall-clock;
                # only the per-step duration changes.
                _pat = max(1, min(pattern_len, max(1, len(steps))))
                _playlist_entry = self.master_playlist_data[row_idx] if row_idx < len(getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or []) else {}
                _seq_map = self._sequence_playlist_mapping(mem, _playlist_entry)
                # CANONICAL_SCHEDULE_AUTHORITY_2026: explicit user Force modes win.
                # Otherwise the canonical strategy may select schedule when the grid
                # mismatch would otherwise weaken canonical timing coverage.
                try:
                    _explicit_map = str((_playlist_entry or {}).get("sequence_mapping", "auto") or "auto").strip().lower()
                    _has_force = bool(mem.get("sequence_force_wrap", False) or mem.get("sequence_force_schedule", False)) or _explicit_map in ("force_wrap", "force_schedule")
                    _cctrl = float(getattr(self, "canonical_signal_control", CANONICAL_SIGNAL_CONTROL_DEFAULT))
                    if not _has_force and _explicit_map == "auto" and str(getattr(self, "canonical_control_strategy", "Full Canonical")) in ("Coverage Adaptive", "Full Canonical"):
                        if str(getattr(self, "canonical_control_strategy", "Full Canonical")) == "Full Canonical" or (_cctrl >= 0.80 and int(mem.get("pattern_length", _pat) or _pat) != int(getattr(self, "spin_seq_length", None).value()) if getattr(self, "spin_seq_length", None) is not None else False):
                            _seq_map = "schedule"
                except Exception:
                    pass
                _paint_tempo = str((_playlist_entry or {}).get("paint_tempo_mode", "") or "").strip().lower()
                if _paint_tempo == "row_loop":
                    _seq_map = "wrap"
                elif _paint_tempo in ("center_snap", "retrigger_rows", "canonical_cut"):
                    _seq_map = "schedule"
                # WRAP fits/restarts the sequence inside each playlist row.
                # SCHEDULE uses the shared playlist grid as the clock, so a
                # sequence whose length differs from that grid can cross/cut a
                # row boundary instead of being silently re-fit.
                try:
                    _schedule_slots = max(1, int(round(float(self.spin_seq_length.value())))) if hasattr(self, "spin_seq_length") else _pat
                except Exception:
                    _schedule_slots = _pat
                inst_step_duration = float(row_duration) / float(_pat)
                schedule_step_duration = float(row_duration) / float(_schedule_slots)
                # Playlist / engine operator offset (seconds) — aligns this
                # instrument inside the shared row without changing step rate.
                try:
                    _op_off = float((op_time_offsets or {}).get(op_name, 0.0) or 0.0)
                except Exception:
                    _op_off = 0.0
                # GROOVEBOX_R23R_ALGO_ROW_BEND_20261103: the Algorithm bends the
                # playlist ROW as a group (never writes parameters): one apparent
                # step-offset shift in seconds, one pitch bend and one level bend,
                # identical for every synth in the row.
                _rb = dict(self._algo_row_bend(row_idx))
                try:
                    _rts = float((entry or {}).get("row_transpose_semitones", 0.0) or 0.0) if isinstance(entry, dict) else 0.0
                except Exception:
                    _rts = 0.0
                if _rts:
                    _rb["pitch"] = float(_rb["pitch"]) * project_semitone_ratio(_rts)
                # R32.6: the row's module columns reach the voice hooks of THIS render thread.
                try:
                    import r32_rowctx as _rctx
                    _rctx.set_row(entry if isinstance(entry, dict) else None)
                except Exception:
                    pass
                # R32.5 Song Form: per-row section level.
                try:
                    _rlv = float((entry or {}).get("row_level", 1.0) or 1.0) if isinstance(entry, dict) else 1.0
                except Exception:
                    _rlv = 1.0
                if _rlv != 1.0:
                    _rb["amp"] = float(_rb["amp"]) * max(0.0, min(2.0, _rlv))
                # GROOVEBOX_R23R_FRACTAL_SEED_MOD_20261103: the seed L-system modulates the
                # track while the Fractal Seed engine is OFF (amount defaults to 0 %).
                _fm = self._fractal_seed_mod_row(row_idx)
                if _fm is not None:
                    _rb["pitch"] = float(_rb["pitch"]) * _fm[0]
                    _rb["amp"] = float(_rb["amp"]) * _fm[1]
                    _rb["offset"] = float(_rb["offset"]) + _fm[2]
                _op_off += float(_rb["offset"]) * float(row_duration)
                try:
                    _track_off = float(mem.get("track_offset", 0.0) or 0.0) * float(row_duration)
                except Exception:
                    _track_off = 0.0
                try:
                    # Global Track Offset is authored in beats, unlike the legacy
                    # per-sequence track_offset which remains row-relative.
                    _global_track_off = float(getattr(self, "global_track_offset", 0.0) or 0.0) * float(seconds_per_beat)
                except Exception:
                    _global_track_off = 0.0
                _op_off += _track_off + _global_track_off
                _user_mask = (self._user_pattern_mask(mem, pattern_len, instrument_name=op_name)
                              if hasattr(self, "_user_pattern_mask") else [False] * pattern_len)
                # Resolve either row-local wrap or continuous playlist schedule.
                # Schedule may visit only the tail/head of a sequence on this row;
                # that is intentional and is the mechanism that permits a sequence
                # to cut below/through the playlist row boundary.
                _schedule_pairs = []
                if _seq_map == "schedule":
                    _row_g0 = int(row_idx * _schedule_slots)
                    _row_g1 = int((row_idx + 1) * _schedule_slots)
                    _tempo_mode = str((_playlist_entry or {}).get("paint_tempo_mode", "") or "").strip().lower()
                    if _tempo_mode == "center_snap":
                        _center_shift = max(0, int(round((_schedule_slots - _pat) * 0.5)))
                        for _s in range(_pat):
                            _schedule_pairs.append((int(_s), float((_s + _center_shift) * schedule_step_duration)))
                    elif _tempo_mode == "retrigger_rows":
                        for _s in range(_pat):
                            _schedule_pairs.append((int(_s), float(_s * schedule_step_duration)))
                    else:
                        # Schedule is continuous; include tail/head events so the sequence
                        # can cross a row boundary. Canonical Cut simply clips those events.
                        for _g in range(_row_g0 - 1, _row_g1 + 1):
                            _s = int(_g % _pat)
                            _schedule_pairs.append((_s, float((_g - _row_g0) * schedule_step_duration)))
                else:
                    _schedule_pairs = [(int(_s), float(_s * inst_step_duration)) for _s in range(_pat)]
                for s_idx, _mapped_start in _schedule_pairs:
                    _user_active = bool(_user_mask[s_idx]) if s_idx < len(_user_mask) else False
                    _canonical_on = self._multinode_step_trigger(_node_field, op_idx, row_idx, s_idx, _user_active)
                    try:
                        _step_controls_for_prob = mem.get("step_controls", {}) if isinstance(mem.get("step_controls", {}), dict) else {}
                        _prob_lane = _step_controls_for_prob.get("trigger_probability", [])
                        if isinstance(_prob_lane, list) and s_idx < len(_prob_lane): _step_prob = float(_prob_lane[s_idx])
                        else: _step_prob = float(probabilities[s_idx]) / 100.0 if s_idx < len(probabilities) else 1.0
                        _step_prob = float(np.clip(_step_prob if math.isfinite(_step_prob) else 1.0, 0.0, 1.0))
                        # Deterministic, evenly phased threshold: no random draw or
                        # random-number generator. Seed/node/row only select the phase
                        # of the lattice; the same project always makes the same choice.
                        _phase_modulus = max(1, min(512, int(pattern_len)))
                        _phase_index = (int(s_idx) + int(row_idx) * 3 + int(op_idx) * 5 + _safe_int_seed(self.get_numeric_seed())) % _phase_modulus
                        _step_threshold = float(_phase_index) / float(_phase_modulus)
                    except Exception: _step_prob, _step_threshold = 1.0, 0.0
                    _user_step_hit = bool(s_idx < len(steps) and steps[s_idx])
                    # Authored hits are inviolable. A deterministic omit/continue
                    # decision is permitted only for canonical-only events while an
                    # actual canonical trigger is active; no stochastic probability is used.
                    _canonical_only_event = bool(_canonical_on and not _user_step_hit)
                    _event_allowed = _user_step_hit or (
                        _canonical_only_event and self._stochastic_point_decision(row_idx, s_idx, op_idx, _step_prob)
                    )
                    if _event_allowed:
                        try:
                            step_offset = float(offsets[s_idx] if s_idx < len(offsets) else 0.0)
                        except Exception:
                            step_offset = 0.0
                        step_offset = float(np.clip(step_offset, -1.0, 1.0))
                        _dur = schedule_step_duration if _seq_map == "schedule" else inst_step_duration
                        s_start = _mapped_start + step_offset * _dur + _op_off
                        # Wrap only the row-local WRAP mode. SCHEDULE is allowed to
                        # begin before 0 or extend beyond the row and is clipped by
                        # the row mask, preserving the through-boundary phase.
                        if _seq_map == "wrap" and row_duration > 0.0:
                            s_start = float(s_start % row_duration)
                        s_end = s_start + _dur
                        if _seq_map == "wrap":
                            s_start = float(np.clip(s_start, 0.0, row_duration))
                            s_end = min(row_duration, s_start + _dur)
                        else:
                            if s_end <= 0.0 or s_start >= row_duration:
                                continue
                            s_start = max(0.0, s_start)
                            s_end = min(row_duration, s_end)
                        s_mask = (local_t >= s_start) & (local_t < s_end)
                        if np.any(s_mask):
                            amp = amps[s_idx] if s_idx < len(amps) else 1.0
                            pr = pitches[s_idx] if s_idx < len(pitches) else 1.0
                            # Exact-step automation projection. The helper has already
                            # mixed A→B by the point morph amount and then coupled the
                            # result 50% with the live composition sequence step.
                            try:
                                _auto_step = self._get_sequencer_automation_for_step(
                                    row_idx, s_idx, op_name, mem
                                )
                                if isinstance(_auto_step, dict):
                                    _am = _auto_step.get("sequence") or {}
                                    _aamps = _am.get("amplitudes", []) if isinstance(_am, dict) else []
                                    _apits = _am.get("pitches", []) if isinstance(_am, dict) else []
                                    if s_idx < len(_aamps):
                                        amp = float(_aamps[s_idx])
                                    if s_idx < len(_apits):
                                        pr = float(_apits[s_idx])
                            except Exception:
                                pass
                            if not (s_idx < len(steps) and steps[s_idx]) and _canonical_on:
                                amp *= float(0.25 + 0.75 * float(_node_field.get("trigger_probability", 0.0)))
                            # PKP hold relative to THIS instrument's step length
                            _sw = float(inst_step_duration)
                            if _sw < 0.0:
                                _sw = 0.0
                            _hold = float(inst_step_duration) * (float(max(_pat, 1)) ** (2.0 * float(pkp_envelope) - 1.0))
                            _note_end = s_start + _hold
                            _lo = s_start - _sw
                            _hi = _note_end + _sw
                            _fo = np.zeros_like(local_t, dtype=np.float32)
                            _pre = (local_t >= _lo) & (local_t < s_start)
                            if _sw != 0.0:
                                _fo[_pre] = (local_t[_pre] - _lo) / _sw
                            _sust = (local_t >= s_start) & (local_t < _note_end)
                            _fo[_sust] = 1.0
                            _post = (local_t >= _note_end) & (local_t < _hi)
                            if _sw != 0.0:
                                _fo[_post] = 1.0 - (local_t[_post] - _note_end) / _sw
                            _seq_env = self._sequence_envelope_factor(
                                local_t, s_start, _note_end, row_duration, mem
                            )
                            amp = float(amp) * float(_rb["amp"])
                            pr = float(pr) * float(_rb["pitch"])
                            step_env += float(amp) * np.clip(_fo * _seq_env, 0.0, 1.0)
                            pitch_track[s_mask] = pr
                            # CHORD_SLOT_RENDER_HF24: each green chord slot is an equal
                            # temporal subdivision of this STEP. The vectorized helper keeps
                            # the render hot path simple and makes the pitch effect testable.
                            try:
                                _ci = list(mem.get("chord_intervals", [0, 4, 7]))
                                _cc_raw = int(mem.get("chord_note_count", len(_ci) or 1) or 1)
                                # GROOVEBOX_R23R_USER_CHORDS_WIN_20261103: chords are a musical
                                # choice — once you set chords anywhere, canonical sequences
                                # use YOUR chord instead of the default triad.
                                if not bool(mem.get("chord_user_owned", False)):
                                    _uc = self._user_chord_choice()
                                    if _uc is not None:
                                        _ci, _cc_raw = list(_uc[0]), int(_uc[1])
                                _cc = max(1, min(_cc_raw, self._canonical_chord_note_budget()))
                                _features = normalize_chord_slot_features(mem.get("chord_slot_features", []), _cc, 512)
                                _fine = [float(_f.get("fine_cents",0)) for _f in _features[:_cc]]
                                apply_chord_slot_pitch(pitch_track, s_mask, float(pr), _ci, _cc, self._canonical_chord_note_budget(), fine_cents=_fine)
                                _event_seed = (_safe_int_seed(_voice_seed) ^ ((int(row_idx)+1)*0x9E3779B1) ^ ((int(op_idx)+1)*0x85EBCA6B) ^ (int(s_idx)+1)) & 0x7FFFFFFF
                                _slot_lanes = chord_slot_feature_tracks(s_mask, _features, _cc, event_seed=_event_seed, note_budget=self._canonical_chord_note_budget())
                                step_env[s_mask] *= _slot_lanes["gain"][s_mask]
                                chord_timbre_track[s_mask] = _slot_lanes["timbre"][s_mask]
                            except Exception:
                                pass
                            try:
                                _step_controls = mem.get("step_controls", {}) if isinstance(mem.get("step_controls", {}), dict) else {}
                                _eq_lane = _step_controls.get("eq_gain_db", [])
                                _eq_db = float(_eq_lane[s_idx]) if isinstance(_eq_lane, list) and s_idx < len(_eq_lane) else 0.0
                                _sc_lane = _step_controls.get("sidechain_depth", [])
                                _sc_depth = float(_sc_lane[s_idx]) if isinstance(_sc_lane, list) and s_idx < len(_sc_lane) else 0.0
                                _sc_explicit = abs(_sc_depth) > 1e-12
                                # FX PROB: deterministic per-step chance that this step's EQ
                                # and sidechain events fire (the note itself is unaffected).
                                _fxp_lane = _step_controls.get("fx_probability", [])
                                _fxp = float(_fxp_lane[s_idx]) if isinstance(_fxp_lane, list) and s_idx < len(_fxp_lane) else 1.0
                                if not math.isfinite(_fxp):
                                    _fxp = 1.0
                                if _fxp < 0.999 and not self._stochastic_point_decision(int(row_idx) + 7919, s_idx, op_idx, _fxp):
                                    _eq_db = 0.0; _sc_depth = 0.0; _sc_explicit = True
                                _eq_db = float(np.clip(_eq_db, -24.0, 24.0))
                                step_eq_gain_track[s_mask] = _eq_db
                                if abs(_eq_db) > 1e-6:
                                    _fl = _step_controls.get("eq_frequency", []); _ql = _step_controls.get("eq_q", [])
                                    _f0 = float(_fl[s_idx]) if isinstance(_fl, list) and s_idx < len(_fl) else 1000.0
                                    _q0 = float(_ql[s_idx]) if isinstance(_ql, list) and s_idx < len(_ql) else 0.707
                                    _ix = np.flatnonzero(s_mask)
                                    if _ix.size:
                                        _step_band_eq.append((int(_ix[0]), int(_ix[-1]) + 1, _eq_db, _f0, _q0))
                                # R23r stepwise sidechain: user step values win; an untouched
                                # (0) step in a canonical-owned sequence takes the phase-locked
                                # canonical depth; a "Sidechain" Mod Patch route/step MOD adds.
                                # Signed: a NEGATIVE depth makes this step a key.
                                if _sc_depth < 0.0:
                                    step_key_track[s_mask] = np.maximum(step_key_track[s_mask], float(min(1.0, -_sc_depth)))
                                    _sc_depth = 0.0
                                elif _sc_depth <= 0.0 and not _mem_has_user and not _sc_explicit:
                                    _sc_depth = self._canonical_step_sidechain(op_idx, row_idx, s_idx, len(steps) or 1)
                                step_sidechain_track[s_mask] = float(np.clip(_sc_depth, 0.0, 1.0))
                            except Exception: pass
                            try:
                                _sc = mem.get("step_controls", {}) if isinstance(mem.get("step_controls", {}), dict) else {}
                                _phase_lane = _sc.get("phase_shift", mem.get("phase_shift", []))
                                _step_phase = float(_phase_lane[s_idx]) if isinstance(_phase_lane, list) and s_idx < len(_phase_lane) else 0.0
                                if math.isfinite(_step_phase):
                                    step_phase_track[s_mask] = _step_phase
                            except Exception:
                                pass

                # NEVER_SILENT_CANONICAL_2026: even an empty user pattern must
                # retain a deterministic canonical voice. Filled pattern slots
                # can recover/add the marginal user 50%, but an empty pattern
                # cannot collapse the row to silence.
                _probability_authored = bool(_mem_has_user and (
                    any(float(x) < 99.999 for x in (mem.get("probabilities", []) or []) if isinstance(x, (int,float)))
                    or any(float(x) < 0.99999 for x in ((mem.get("step_controls", {}) or {}).get("trigger_probability", []) or []) if isinstance(x, (int,float)))
                ))
                if not np.any(step_env != 0.0) and not _probability_authored:
                    _fallback_idx = int(_safe_int_seed(_voice_seed + row_idx + op_idx)) % _pat
                    _fallback_start = float(_fallback_idx * inst_step_duration)
                    _fallback_end = min(row_duration, _fallback_start + inst_step_duration)
                    _fm = (local_t >= _fallback_start) & (local_t < _fallback_end)
                    if np.any(_fm):
                        _ff = np.zeros_like(local_t, dtype=np.float32)
                        _ff[_fm] = 1.0
                        step_env += 0.50 * _ff
                        pitch_track[_fm] = 1.0

                # --- Per-synth panel seed (4 knobs) + per-synth Fractallizer ---
                if full_unison:
                    # FULL_UNISON_2026: per-instrument panels are structurally
                    # cancelled.  The ONLY parameter surviving into the unison is
                    # the engine-authored meum_modulation context (the same four
                    # canonicals that own the unison wrote it); presets, tuning,
                    # identity anchors, waveform picks and per-sequence panels
                    # are dropped so no patch of any kind can keep an instrument
                    # distinct from the 5-engine unison.
                    st = dict((getattr(self, "instrument_param_state", {}) or {}).get(op_name, {}) or {})
                    _eng_meum = st.get("meum_modulation") if isinstance(st.get("meum_modulation"), dict) else None
                    st = {"meum_modulation": _eng_meum} if _eng_meum else {}
                else:
                    st = dict((getattr(self, "instrument_param_state", {}) or {}).get(op_name, {}) or {})
                    # Always blend sequence/engine result-mod synth with the master
                    # non-sequence panel data (synth / script / domain / patch).
                    # Previously this only ran when "Edit panels per sequence" was ON,
                    # so playlist-assigned patterns ignored the four panel defaults and
                    # sounded like pure engine mods (or pure master) — never both.
                    # Convolve-fit helps the same idea in the audio domain; this does
                    # it in parameter space so assigned patterns keep panel identity.
                    try:
                        _seq_p = self._sequence_panel_slot(op_name) if hasattr(self, "_sequence_panel_slot") else None
                        _seq_synth = (_seq_p or {}).get("synth") if isinstance(_seq_p, dict) else None
                        if isinstance(_seq_synth, dict) and _seq_synth:
                            try:
                                _blend_amt = float((_seq_p or {}).get("blend", 0.5))
                            except Exception:
                                _blend_amt = 0.5
                            # Convolve-fit on → lean a bit more toward sequence result mod
                            if bool(getattr(self, "chk_convolve_fit", None) and self.chk_convolve_fit.isChecked()):
                                _blend_amt = min(0.75, _blend_amt + 0.15)
                            st = blend_master_sequence_params(st, _seq_synth, amount=_blend_amt)
                            # Fold sequence script/domain/patch tags into meum context keys
                            # so modular routing can see the four panel contributions.
                            if (_seq_p or {}).get("script"):
                                st.setdefault("sequence_script", str(_seq_p.get("script") or "")[:240])
                            _dom = (_seq_p or {}).get("domain") if isinstance((_seq_p or {}).get("domain"), dict) else {}
                            if _dom:
                                st.setdefault("sequence_domain_sources", list(_dom.get("sources") or [])[:8])
                            _patch = (_seq_p or {}).get("patch") if isinstance((_seq_p or {}).get("patch"), list) else []
                            if _patch:
                                st.setdefault("sequence_patch_count", len(_patch))
                    except Exception:
                        pass
                    # GROOVEBOX_R23R_BLEND_PARTNER_20261031: Blend Partner chooses an
                    # additional sequence setting to morph toward ("Instrument#S<n>",
                    # sequence 1 when no number is given); Blend % is the morph amount,
                    # exactly like an Automation Morph point. The partner sequence's
                    # synth panel - including its geometric-synth instance - is used.
                    # No Blend % = no morph. Skipped under full unison (panels cancel).
                    try:
                        _pe = self.master_playlist_data[row_idx] if row_idx < len(self.master_playlist_data) else None
                        _partner = str((_pe or {}).get("blend_partner") or "").strip() if isinstance(_pe, dict) else ""
                        _bpct = (_pe or {}).get("blend_percent") if isinstance(_pe, dict) else None
                        if _partner and _bpct not in (None, ""):
                            _pinst, _pseq = _partner, 1
                            if "#S" in _partner:
                                _pinst, _, _ps = _partner.rpartition("#S")
                                try:
                                    _pseq = max(1, int("".join(ch for ch in _ps if ch.isdigit()) or 1))
                                except Exception:
                                    _pseq = 1
                            _pinst = _pinst.strip()
                            _bamt = float(np.clip(float(_bpct) / 100.0, 0.0, 1.0))
                            if _bamt > 0.0 and _pinst in (getattr(self, "instrument_param_state", {}) or {}) and not (_pinst == op_name and _pseq == self._current_sequence_index(op_name)):
                                _psynth = dict((self._automation_panel_state(_pinst, _pseq) or {}).get("synth") or {})
                                if _psynth:
                                    st = blend_master_sequence_params(st, _psynth, amount=_bamt)
                    except Exception:
                        pass
                if full_unison:
                    # FULL_UNISON_2026: every per-voice synthesis jitter derived
                    # from the instrument index (phase slot, timbre, decay,
                    # mod-rate and detune draws) is cancelled.  The only phase /
                    # detune / mod-rate left is the canonical engine field
                    # (__node_* below), so voices interlock purely on the
                    # 5-engine unison's terms — no seed or patch can keep them
                    # apart.
                    _voice_detune = _node_detune
                    _voice_phase0 = _node_phase_bias
                    _voice_timbre = 1.0
                    _voice_decay = 1.0
                    _voice_mod_rate = _node_mod_rate
                else:
                    # SUPER-VARIABLE VOICE FIELD: only internal synthesis variation.
                    # User-authored steps, pitches, gates, patterns, playlist data and
                    # engine goals are untouched. Each voice/row gets independent
                    # phase, detune, timbre and envelope character.
                    _voice_mix_key = (int(_s_int) ^ (int(op_idx) * 0x9E3779B1) ^
                                      (int(row_idx) * 0x85EBCA6B) ^ (int(pattern_len) * 0xC2B2AE35)) & 0x7FFFFFFF
                    _voice_rng = np.random.RandomState(_voice_mix_key or 1)
                    _voice_detune = float(_voice_rng.uniform(-0.0035, 0.0035)) + _node_detune
                    # HARDCODE_UNISON_2026: phase0 anchors to the fixed, evenly-spaced
                    # per-instrument slot (INSTRUMENT_PHASE_LOCK_48) instead of an
                    # independent random draw per voice. Random-per-voice phase used
                    # to let each synth beat against its neighbors at its own
                    # arbitrary offset, which is exactly what makes an ensemble
                    # sound like "N separate synths." Anchoring every voice's phase
                    # to its fixed roster slot (plus only a small node-level nudge)
                    # keeps the relationships between voices constant and
                    # complementary, so they interlock instead of drifting apart.
                    _voice_phase0 = INSTRUMENT_PHASE_LOCK_48[op_idx % 48] + 0.15 * _node_phase_bias
                    _voice_timbre = float(_voice_rng.uniform(0.78, 1.22))
                    _voice_decay = float(_voice_rng.uniform(0.82, 1.18))
                    _voice_mod_rate = float(_voice_rng.uniform(0.71, 1.37)) * _node_mod_rate
                # SEQUENCER_AUTOMATION_POINTS_2026: synth side of the point is
                # projected for the current row; sequence-side values are applied
                # at their exact step below. Source banks are never modified.
                try:
                    _auto_synth = None
                    for _asi in range(max(1, _pat)):
                        _auto_synth = self._get_sequencer_automation_for_step(
                            row_idx, _asi, op_name, mem
                        )
                        if isinstance(_auto_synth, dict):
                            break
                    if isinstance(_auto_synth, dict) and isinstance(_auto_synth.get("synth"), dict):
                        st = _auto_synth["synth"]
                except Exception:
                    pass

                # CANONICAL_SYNTH_SLIDER_CONTROL_2026: canonical engines directly
                # own an effective 50–100% share of the synth slider state while
                # user-authored values remain the base. This is applied after
                # automation destination resolution so per-sequence references
                # remain authoritative for their scoped voice.
                try:
                    st = self._apply_canonical_synth_controls(op_name, st)
                    st = self._md_io_apply_outputs(op_name, st)
                except Exception:
                    pass
                # Canonical-owned voices get direct amp/pitch/phase/trigger controls.
                _canonical_slot = not _mem_has_user
                _canonical_amp = float(np.clip(st.get("canonical_amp", 1.0), 0.0, 2.0)) if _canonical_slot else 1.0
                _canonical_pitch = float(st.get("canonical_pitch", 1.0)) if _canonical_slot else 1.0
                _canonical_phase = float(st.get("canonical_phase", 0.0)) if _canonical_slot else 0.0
                _canonical_trigger = float(np.clip(st.get("canonical_trigger", 1.0), 0.0, 1.0)) if _canonical_slot else 1.0
                if _canonical_slot:
                    pitch_track *= _canonical_pitch
                    step_env *= _canonical_amp
                    if _canonical_trigger < 1.0:
                        step_env *= (0.25 + 0.75 * _canonical_trigger)

                # Derived modulation must be computed after the per-voice identity
                # fields above are initialized. This also keeps every voice's
                # modulation field independent and deterministic.
                # MASTER_FX_FIX_2026: base_eqr is a master-mix effect only; the
                # per-voice dynamic_eqr multiplier was removed so the EQR effect
                # can never factor into the unison canonical engines.
                morph = float(st.get("morph", st.get("internal_p1", 0.5) * 10.0 if "internal_p1" in st else 1.2))
                harm_hz = float(st.get("harmonic_freq", base_freq))
                chaos = float(st.get("chaos", st.get("internal_p3", 0.5)))
                fold_depth = float(st.get("fold_depth", st.get("internal_p4", 0.4) * 16.0 if "internal_p4" in st else 4.0))
                synth_lattice = float(st.get("harmonic_lattice", st.get("fractalizer", 0.33)))
                preset_idx = int(st.get("preset_idx", _vo % 4))
                tuning_ratio = float(st.get("tuning_ratio", st.get("tuning", 1.0)))
                identity_hz = st.get("frequency_identity_hz")
                if identity_hz not in (None, ""):
                    try:
                        _identity_base=float(st.get("frequency_identity_base_hz",432.0) or 432.0)
                        _identity_ratio=float(st.get("frequency_identity_ratio",float(identity_hz)/_identity_base))
                        identity_hz=base_freq*_identity_ratio
                    except (TypeError,ValueError,ZeroDivisionError):
                        identity_hz=base_freq

                # Fundamental = seed-mapped Hz × step pitch_track × panel tuning.
                # Seed is the note identity; panel harmonic_freq is a refinement
                # only when it was explicitly set away from the shared default.
                _seed_hz = float(_seed_to_fundamental_hz(_voice_seed, base_freq, _vo, 0))
                if identity_hz not in (None, ""):
                    try:
                        # Identity anchor still respected, but scaled by seed ratio
                        # so list seeds remain distinct across the ensemble.
                        _identity_ratio = _seed_to_pitch_ratio(0.0, op_idx, 0)
                        seed_freq = float(identity_hz) * pitch_track * ((_seed_ratio / _identity_ratio) if _identity_ratio != 0.0 else 0.0)
                    except Exception:
                        seed_freq = _seed_hz * pitch_track * (tuning_ratio if tuning_ratio >= 0.0 else 0.0)
                elif harm_hz > 20.0 and abs(harm_hz - base_freq) > 1.0:
                    # Panel has a real harmonic_freq — blend with seed identity
                    seed_freq = (0.45 * float(harm_hz) + 0.55 * _seed_hz) * pitch_track * (tuning_ratio if tuning_ratio >= 0.0 else 0.0)
                else:
                    seed_freq = _seed_hz * pitch_track * (tuning_ratio if tuning_ratio >= 0.0 else 0.0)

                # Seed-driven harmonic ↔ entropy continuum (authoritative voice).
                # Engines / seed scripts define character HERE. Later stages must
                # not spectral-fit or convolute these voices back into one shape.
                f0 = np.maximum(seed_freq, AUDIBLE_LO_HZ)
                # Canonical-owned polyphony: simultaneous deterministic pitch values.
                _canonical_ratios = st.get("canonical_chord_ratios") if isinstance(st, dict) else None
                if _canonical_ratios and not bool((mem or {}).get("user_owned", False)):
                    try:
                        _canonical_ratios = [float(r) for r in _canonical_ratios if float(r) > 0.0][:4]
                        if _canonical_ratios:
                            _chord_seed = sum(ot_sin_vec_equiv(2.0 * np.pi * f0 * r * local_t) / max(1, len(_canonical_ratios)) for r in _canonical_ratios)
                        else:
                            _chord_seed = None
                    except Exception:
                        _chord_seed = None
                else:
                    _chord_seed = None

                # Canonical AM/FM/PM: driven by whatever the randomizers /
                # phase-lockers / seeded engines last wrote into this
                # instrument's meum_modulation context (see
                # _mark_generated_synth_context), falling back to the raw
                # per-instrument state if no nested context exists yet.
                _meum_ctx_raw = st.get("meum_modulation", st)
                _meum_ctx = _meum_ctx_raw if isinstance(_meum_ctx_raw, dict) else st
                try:
                    _row_mod = self._canonical_mod_depth_curve(
                        op_idx, row_idx, rows, target=_canon_mod_target, growth=_canon_mod_growth)
                    _route_mod = st.get("mod_depth", 0.0) if isinstance(st, dict) else 0.0
                    _row_mod = float(np.clip(_row_mod + float(_route_mod or 0.0), 0.0, 2.0))
                    _mod_scale = _xmod_master * _row_mod
                    if _mod_scale != 1.0:
                        _meum_ctx = dict(_meum_ctx)
                        for _mk in ("am_depth", "fm_depth", "pm_depth", "meum_depth"):
                            if _mk in _meum_ctx:
                                _meum_ctx[_mk] = float(_meum_ctx[_mk]) * _mod_scale
                except Exception:
                    pass
                _fm_ratio, _pm_offset, _am_gain = meum_modulation_vectors(local_t, _meum_ctx)

                # FM: integrate the modulated instantaneous frequency into phase
                # (canonical order is FM -> phase accumulator -> PM -> waveform).
                _dt = float(local_t[1] - local_t[0]) if local_t.size > 1 else 0.0
                # PERF_NATIVE_PHASE_20260905: fuse instantaneous-frequency scaling,
                # cumulative integration and PM/static offsets into one native pass.
                # The fallback below remains algebraically authoritative.
                _phase_native = _GB_ACCEL_FUNCS.get("phase_build") if isinstance(_GB_ACCEL_FUNCS, dict) else None
                # ROW_PHASE_CONTINUITY_FIX_2026: this cumsum used to start fresh
                # at 0 for every row/block, for every voice, with no memory of
                # where the previous row's phase ended. That is a hard phase
                # discontinuity at *every* row boundary — an audible click/pop
                # per row, completely independent of whether a Global Play
                # Patcher algorithm is applied. That is almost certainly the
                # "burst happens without Apply Algorithm, often" symptom: it
                # fires on every single row for every voice, algorithm or not.
                # Fixed by carrying each instrument's ending phase forward into
                # the next row's starting phase.
                if not hasattr(self, "_voice_phase_carry"):
                    self._voice_phase_carry = {}
                _phase_carry_in = float(self._voice_phase_carry.get(op_name, 0.0))
                phase = None
                if _phase_native is not None and local_t.size >= 256:
                    try:
                        import ctypes as _ct
                        _fr32 = np.ascontiguousarray(_fm_ratio, dtype=np.float32)
                        _pm32 = np.ascontiguousarray(_pm_offset, dtype=np.float32)
                        _phase64 = np.empty(local_t.shape, dtype=np.float64)
                        _carry_out = _phase_native(
                            _fr32.ctypes.data_as(_ct.POINTER(_ct.c_float)),
                            _pm32.ctypes.data_as(_ct.POINTER(_ct.c_float)),
                            _ct.c_size_t(_fr32.size), _ct.c_double(float(f0)),
                            _ct.c_double(float(_voice_detune)), _ct.c_double(_dt),
                            _ct.c_double(_phase_carry_in), _ct.c_double(float(_voice_phase0)),
                            _ct.c_double(float(_canonical_phase)),
                            _phase64.ctypes.data_as(_ct.POINTER(_ct.c_double)),
                        )
                        phase = _phase64
                        self._voice_phase_carry[op_name] = float(_carry_out)
                    except Exception:
                        phase = None
                if phase is None:
                    _inst_freq = f0 * _fm_ratio * (1.0 + _voice_detune)
                    _phase_unwrapped = 2.0 * np.pi * np.cumsum(_inst_freq) * _dt
                    phase = _phase_unwrapped + _phase_carry_in
                    if phase.size > 0:
                        self._voice_phase_carry[op_name] = float(phase[-1] % math.tau)
                    phase = phase + _pm_offset + _voice_phase0 + _canonical_phase
                # Canonical per-step phase shift is applied after the shared
                # phase accumulator so it changes phase without changing timing,
                # pitch, or row-to-row phase continuity.
                if step_phase_track.size and np.any(step_phase_track):
                    phase = phase + step_phase_track
                # GROOVEBOX_R23R_FI_SHORTCUTS_20261103: the phase increments from their sources (for the
                # multidimensional synth + its playlist memo; independent of the row-to-row phase carry)
                try:
                    _md_inc = 2.0 * np.pi * np.broadcast_to(f0 * _fm_ratio * (1.0 + _voice_detune), local_t.shape) * _dt
                    _md_mod = np.broadcast_to(np.asarray(_pm_offset, dtype=np.float64), local_t.shape)
                    if step_phase_track.size and np.any(step_phase_track):
                        _md_mod = _md_mod + step_phase_track
                    _md_step = _md_inc + np.diff(_md_mod, prepend=_md_mod[:1]) if local_t.size else None
                except Exception:
                    _md_step = None

                _sv = float(_voice_seed)
                _s_abs = abs(_sv)
                _s_frac = _s_abs - math.floor(_s_abs)
                # _s_int was established from _voice_seed before the voice field.
                # Under full unison the draw is the union's single shared point
                # (stashed in _union_identity) — audio and video must register
                # the SAME value.  Otherwise entropy 0 = pure harmonic, 1 = full
                # entropy, shared draw from entropy_draw_0_1 so audio and the
                # 0.5 fixed-point audit agree.
                if full_unison and getattr(self, "_union_identity", None):
                    entropy = float(self._union_identity["entropy"])
                else:
                    entropy = float(entropy_draw_0_1(_s_abs, _s_frac, _s_int, _vo))
                if full_unison or canonical_count > 0:
                    # UNION_ENTROPY_2026 ledger: accumulate the DRAW (raw uniform,
                    # mean exactly 0.5 — input-invariant) and the realized per-voice
                    # min/max (the genuine "some seeds entropic, some not" spread).
                    try:
                        if full_unison:
                            self._union_entropy_full_window = True
                        self._union_entropy_sum += entropy
                        self._union_entropy_sum_sq += entropy * entropy
                        self._union_entropy_n += 1
                    except Exception:
                        pass
                k1 = (morph / 10.0) * _voice_timbre
                k3 = float(np.clip(chaos * (0.55 + 0.90 * _voice_timbre), 0.0, 1.0))
                k4 = float(np.clip((fold_depth / 16.0) * (0.50 + 0.90 * _voice_timbre), 0.0, 3.0))
                # Chaos can push entropy to extremes; no 0.75 mid-band clamp
                entropy = float(np.clip(entropy * (0.55 + 0.45 * k3) + 0.35 * k3 * (1.0 - entropy), 0.0, 1.0))
                if full_unison or canonical_count > 0:
                    # UNION_ENTROPY_2026: realised per-voice entropy (post-transform)
                    # genuinely varies seed-to-seed — some seeds entropic, some not —
                    # while the DRAW ledger above stays pinned at 0.5. Finalize the
                    # fixed-point audit at macro cadence (>=48 voices or ~0.5s).
                    try:
                        _e_real = float(entropy)
                        self._union_entropy_r_min = min(self._union_entropy_r_min, _e_real)
                        self._union_entropy_r_max = max(self._union_entropy_r_max, _e_real)
                        self._union_entropy_samples += int(max(1, local_t.size))
                        if self._union_entropy_n >= 48 or self._union_entropy_samples >= max(1, int(self.sample_rate * 0.5)):
                            self._finalize_union_entropy()
                    except Exception:
                        pass
                entropy = entropy * _inh_amt  # GROOVEBOX_INHARMONIC_GATE_20261102 (after the entropy ledger)
                n_harm = max(1, int(2 + (1.0 - entropy) * 14 + k4 * 6))
                # HARDCODE_UNISON_2026: partial-count ceiling used to be derived
                # at render time from Nyquist / this voice's live fundamental
                # (sample_rate * 0.5 divided by f0). That runtime division is
                # exactly the kind of per-sample-rate, per-frequency "soft"
                # dependency the ensemble should not rely on — replaced with a
                # fixed, instrument-slot-indexed cap (INSTRUMENT_PARTIAL_CAP_48,
                # same family as MEUM_POWERS_36) so every voice's harmonic
                # budget is a hardcoded property of its roster position, not a
                # runtime computation. It also keeps neighboring instrument
                # slots' partial counts close together, which is part of what
                # makes them blend into one mass instead of standing apart.
                _max_partial = INSTRUMENT_PARTIAL_CAP_48[_vo % 48]
                n_harm = max(1, min(n_harm, _max_partial))
                # GOAVA = hard-composed pure sine; other engines free waveform.
                # Live mod (AM/FM/PM) still routes through phase/_am_gain for all.
                _is_goava_voice = (
                    str(mem.get("canonical_owner", "")).startswith("canonical:goava")
                    or "goava" in str(mem.get("engine_source", "")).lower()
                    or bool(st.get("goava_sine_patch"))
                )
                _wf = str(st.get("waveform", _meum_ctx.get("waveform", "isn")) or "isn").strip().lower()
                _pm_d = float(_meum_ctx.get("pm_depth", 0.0) or 0.0)
                if _is_goava_voice:
                    entropy = min(entropy, 0.12)  # keep GOAVA nearly pure
                n_inh = max(2, int(2 + entropy * 10 + k4 * 3))
                # HARDCODE_UNISON_2026: same fixed, instrument-indexed cap as
                # n_harm above (scaled down, since inharmonic ratios climb
                # steeper) instead of a second Nyquist/f0 runtime division.
                n_inh = max(1, min(n_inh, max(1, int(_max_partial / 1.4))))

                # PERF_NATIVE_20260905: the harmonic + inharmonic oscillator bank
                # was one of the largest remaining Python/NumPy hot loops.  The
                # C++ kernel is algebraically equivalent and writes directly into
                # one float32 buffer.  Tiny buffers and unsupported inverse
                # waveforms stay on the reference Python path.
                voice_raw = None
                # GROOVEBOX_R23R_WAVESPACE_20261031: the default (isn) voice is this
                # instrument's own instance of the geometric synths — its wavespace
                # cycle (drawn or canonical), vector, ball and cellular depths from
                # its Edit Synth panel — evaluated exactly and band-limited.
                _ws_harm = None
                _ig = None
                if not _is_goava_voice:   # GEO_ALL_WAVEFORMS_20261102: every non-GOAVA voice carries its geometric share, whatever the panel waveform
                    try:
                        # Canonical slot (_vo): 0 under full unison, so the canonical
                        # instance is identical for any number of instruments; only
                        # user-owned instance data can set instruments apart.
                        _ig = self._instance_voice_geometry(op_name, int(_vo), params=self._geo_params_with_algo(st, op_name, ((int(row_idx) * 7 + int(op_idx)) % 16) / 16.0))
                        _ws_v = _ws_geometric_voice(
                            phase, t[mask], total_duration, _ig["slot"], _ig["coeffs"],
                            sample_rate=sample_rate, harmonic_cap=_ig["cap"],
                            vector=_ig["vector"], ball=_ig["ball"], density=_ig["density"],
                            depths=_ig["depths"])
                        _g_wt = _ig["wt_gain"]
                        _ws_harm = (_g_wt * _ws_v + (1.0 - _g_wt) * np.sin(phase)).astype(np.float32) if _g_wt < 1.0 else _ws_v.astype(np.float32)
                    except Exception as _ws_exc:
                        _ws_harm = None
                        if not getattr(self, "_ws_warned", False):
                            self._ws_warned = True
                            print(f"[Render] wavespace voice fell back to the harmonic stack: {_ws_exc}")
                _voice_native = _GB_ACCEL_FUNCS.get("voice") if isinstance(_GB_ACCEL_FUNCS, dict) else None
                _wf_code = {
                    "saw": 1, "sawtooth": 1, "square": 2, "pulse": 2,
                    "triangle": 3, "tri": 3, "ics": 4, "cos": 4, "cosine": 4,
                }.get(_wf, 0)
                _native_ok = _wf not in ("arcisn", "isn_inv", "isn_inverse", "arcics", "ics_inv", "ics_inverse")
                # Native voice is AUTO by default for substantial buffers. Set
                # GROOVEBOX_NATIVE_VOICE=0/off to force NumPy reference mode.
                # OpenMP makes the kernel useful on modern business tablets/mini PCs.
                _nv_policy = os.environ.get("GROOVEBOX_NATIVE_VOICE", "auto").strip().lower()
                _native_voice_enabled = _nv_policy not in ("0", "false", "no", "off", "numpy")
                if _native_voice_enabled and _voice_native is not None and _native_ok and phase.size >= 4096:
                    try:
                        import ctypes as _ct
                        _ph64 = np.ascontiguousarray(phase, dtype=np.float64)
                        _vr = np.empty(_ph64.shape, dtype=np.float32)
                        _voice_native(
                            _ph64.ctypes.data_as(_ct.POINTER(_ct.c_double)), _ct.c_size_t(_ph64.size),
                            _ct.c_double(entropy), _ct.c_double(k1), _ct.c_double(k3), _ct.c_double(k4),
                            _ct.c_int(n_harm), _ct.c_int(n_inh), _ct.c_int(_wf_code),
                            _ct.c_int(1 if _is_goava_voice else 0), _ct.c_double(_pm_d),
                            _ct.c_longlong(int(_s_int)), _ct.c_int(int(_vo)),
                            _ct.c_double(MEUM), _ct.c_double(MEUM_NORM),
                            _vr.ctypes.data_as(_ct.POINTER(_ct.c_float)),
                        )
                        voice_raw = _vr
                    except Exception:
                        voice_raw = None

                if voice_raw is None:
                    if _is_goava_voice:
                        harm = ot_sin_vec_equiv(phase)
                        if abs(_pm_d) > 0.05:
                            harm = harm + 0.08 * abs(_pm_d) * ot_sin_vec_equiv(2.0 * phase)
                    else:
                        if _wf in ("saw", "sawtooth", "square", "pulse", "triangle", "tri", "ics", "cos", "cosine"):
                            try:
                                harm = meum_waveform_from_phase(phase, _wf)
                            except Exception:
                                harm = ot_sin_vec_equiv(phase)
                            for h in range(2, min(n_harm, 5) + 1):
                                amp_h = 0.12 / h
                                harm = harm + amp_h * meum_waveform_from_phase(phase * h, _wf)
                        else:
                            harm = ot_sin_vec_equiv(phase)
                            for h in range(2, n_harm + 1):
                                roll = 1.0 + (1.0 - entropy) * 1.2
                                amp_h = (0.35 + 0.55 * (1.0 - entropy)) / (h ** roll)
                                det = 1.0 + 1e-4 * ((_s_int % 97) - 48) * (h - 1) * (0.3 + 0.7 * entropy)
                                ph0 = ((_s_int * h * 13 + _vo * 7) % 1000) / 1000.0 * math.tau
                                harm = harm + amp_h * ot_sin_vec_equiv(phase * h * det + ph0)
                    inh = np.zeros_like(local_t, dtype=np.float32)
                    for h in range(1, n_inh + 1):
                        ratio = 1.0 + h * (1.0 + 0.37 * series_sin((_s_int + h * 17) * MEUM_NORM))
                        ratio = 1.0 + (ratio - 1.0) * (0.4 + 0.6 * entropy)
                        amp_i = (0.25 + 0.6 * entropy) / (h ** (0.9 + 0.4 * entropy))
                        ph0 = ((_s_int * h * 31 + _vo * 11) % 1000) / 1000.0 * math.tau
                        inh = inh + amp_i * ot_sin_vec_equiv(phase * ratio + ph0)
                    if entropy > 0.1:
                        fm_ratio = 1.0 + ((_s_int % 19) / 19.0) * 3.0 * entropy
                        fm_depth = (0.05 + 0.55 * entropy) * (0.5 + 0.5 * k1)
                        harm = harm * ot_cos_vec_equiv(fm_depth * ot_sin_vec_equiv(phase * fm_ratio))
                    voice_raw = (1.0 - entropy) * harm + entropy * inh
                # GROOVEBOX_R23R_INSTANCE_EDIT_SYNTH_5050_20261031: every voice is
                # 50% its four-geometric instance + 50% its Edit Synth main synth
                # (which the Mod, Patch, Domain and Script windows modulate), so
                # both are equally powerful. "Instance x Main synth" couples them.
                if _ws_harm is not None and np.size(_ws_harm) == np.size(voice_raw):
                    _main = np.asarray(voice_raw, dtype=np.float32)
                    _geo = np.asarray(_ws_harm, dtype=np.float32)
                    _xc = float((_ig or {}).get("cross", 0.0) or 0.0)
                    if _xc > 0.0:
                        _pm = float(np.max(np.abs(_main))) if _main.size else 0.0
                        _pg = float(np.max(np.abs(_geo))) if _geo.size else 0.0
                        _mn = _main / _pm if _pm > 0.0 else np.zeros_like(_main)   # silent stays silent (exact)
                        _gn = _geo / _pg if _pg > 0.0 else np.zeros_like(_geo)
                        _main, _geo = _main * (1.0 + _xc * _gn), _geo * (1.0 + _xc * _mn)
                    _gpw = geo_panel_weight(st)
                    _md_parts = (_main, _geo, _gpw)
                    voice_raw = ((1.0 - _gpw) * _main + _gpw * _geo).astype(np.float32)
                else:
                    _md_parts = (voice_raw, None, 0.0)
                # GROOVEBOX_R23R_MULTIDIM_SYNTH_20261103: (panel × geometrics) against the multidimensional
                # synth, with the main ↔ multidim modulation pathways
                try:
                    if np.size(phase) == np.size(voice_raw):
                        voice_raw = np.asarray(self._md_triad(_md_parts[0], _md_parts[1], _md_parts[2], op_name, _vo,
                                                              phase, local_t, sample_rate, step=_md_step), dtype=np.float32)
                except Exception as _md_exc:
                    print(f"[Multidim synth] {op_name}: {_md_exc}")
                if _chord_seed is not None:
                    voice_raw = 0.72 * voice_raw + 0.28 * _chord_seed
                # NO_HIDDEN_VOICE_CLAMP_20260905: preserve the closed-form voice
                # amplitude exactly. Safety limiting is owned only by the explicit
                # master hard-clip stage; canonical resonance 0–200% therefore
                # remains distinguishable all the way to that declared boundary.
                # MASTER_FX_FIX_2026: per-voice EQR additive coloring removed —
                # the only EQR application is the master-bus tail stage below.
                # NO_NORMALIZE / NO_SLEW: the previous stage peak-normalized
                # each voice (seed = voice_raw / peak) with a slew-rate-limited
                # gain ramp. That peak-relative gain is exactly the DSP that
                # breaks the resonator–unison canonical: a per-block /peak ride
                # (a normalize) plus adjacent-block gain motion (a slew) makes
                # the audible result depend on per-row entropy swings instead of
                # the seed-derived amplitude. Canonical voices pass through at
                # their pure closed-form amplitude — no normalize, no slew.
                # The master bus hard-clips at the number-theory rail below.
                seed = voice_raw.astype(np.float32)

                # MASTER_FX_FIX_2026: the tempo-locked PKP amplitude envelope is
                # a master-bus effect only — it must not color canonical voices
                # (that would fold the effect into the unison canonical engines).
                # Voices keep only a neutral, deterministic decay floor to feed
                # the per-synth Harmonic Lattice envelope input.
                _tau = max(MEUM_CONSTANT * _voice_decay, 0.5)
                env_f = (0.5 + 0.5 * np.exp(-local_t / max(_tau * 8.0, 1.0))).astype(np.float32)
                gate = step_env
                if not np.any(gate != 0.0):
                    continue
                # AM: post-waveform amplitude gain, applied once here for the
                # canonical voice (feeds the same meum_modulation context as
                # the FM/PM applied above to `phase`).
                # Instance x Global mod (mixer "ensemble modulation"): the voice
                # follows the global modulation space (Meum AM field, scaled by
                # XMOD) and its own Ball/Cellular activity moves its share of it.
                if _ig is not None and _ig.get("ensemble", 0.0) > 0.0 and np.size(_am_gain) == np.size(seed):
                    _ea = float(_ig["ensemble"])
                    _amg = np.asarray(_am_gain, dtype=np.float64)
                    _amm = float(np.mean(np.abs(_amg)))
                    _amn = np.clip(_amg / _amm, 0.0, 2.0) if _amm > 0.0 else np.zeros_like(_amg)
                    seed = (np.asarray(seed, dtype=np.float64) * ((1.0 - _ea) + _ea * _amn)).astype(np.float32)
                    try:
                        _act = _ws_instance_activity(t[mask], total_duration, _ig["slot"], _ig.get("ball"), _ig.get("density"))
                        if _act is not None and np.size(_act) == np.size(_amg):
                            _am_gain = (_amg * (1.0 + _ea * (_act - float(np.mean(_act))))).astype(np.float32)
                    except Exception:
                        pass
                voice = seed.astype(np.float32) * gate * velocity_scale * _am_gain.astype(np.float32)
                # CHORD_NOTE_TIMBRE_HF25: per-note timbre sliders change each slot's
                # second-harmonic share. At the neutral 50% default this is an exact no-op.
                try:
                    if chord_timbre_track.size == voice.size and np.any(chord_timbre_track != 50.0):
                        _bright=(chord_timbre_track.astype(np.float32)-50.0)/50.0
                        voice=(voice + (_bright*0.12*ot_sin_vec_equiv(2.0*phase).astype(np.float32)*gate).astype(np.float32)).astype(np.float32)
                except Exception: pass
                # OPERATOR_SAMPLE_PRECANONICAL_50_2026: a user-owned per-operator
                # audio/video sample is morphed by the active synth/script/patch/domain
                # state and blended 50/50 BEFORE canonical phase-lock, convolve-fit,
                # voice gain and playlist composition. Thus user data can never fall
                # below a 50% local contribution while the canonical engines retain
                # final authority over composition identity.
                try:
                    _sample_rec = (getattr(self, "instrument_media_samples", {}) or {}).get(op_name)
                    if isinstance(_sample_rec, dict) and _sample_rec.get("waveform") is not None:
                        _samp = np.asarray(_sample_rec.get("waveform"), dtype=np.float32).ravel()
                        if _samp.size:
                            # GROOVEBOX_R23R_SAMPLE_AS_RECORDED_20261031: the raw layer is
                            # the recording itself at its native rate from the clip start
                            # (no stretch, no gate, no transform). With no canonical engine
                            # active it is layered untouched; with engines on, 50% of the
                            # sample is warped by the synth/script/patch/domain morph.
                            _raw = self._sample_native_layer(_samp, int(_sample_rec.get("sample_rate", sample_rate) or sample_rate), local_t) * np.float32(velocity_scale)
                            if self._get_active_engine_set() and bool((getattr(self, "sample_morph_state", {}) or {}).get("enabled", True)):
                                _warp = self._sample_panel_morph(_samp, op_name, local_t, warp_only=True)
                                _warp = _warp * gate.astype(np.float32) * velocity_scale * _am_gain.astype(np.float32)
                                _sm = (0.50 * _raw + 0.50 * _warp).astype(np.float32)
                            else:
                                _sm = _raw
                            voice = (0.50 * _sm + 0.50 * voice).astype(np.float32)
                except Exception:
                    pass
                # GLOBAL_XMOD_2026 retired (R23r): Global XMOD is now the master amount
                # applied to the Meum AM/FM/PM depths above, not a separate pass.

                # FULL_GRAPH_SCRIPT_CONTEXT_2026 — actual sound consumption.
                # Instrument and applied Algorithm scripts are sampled at control
                # rate against the SAME varying XYZ/t/domain graph used by video
                # and game. Existing evaluate_wave(x,y,z) scripts stay valid.
                try:
                    _inst_script = str((getattr(self, "instrument_scripts", {}) or {}).get(op_name, "") or "")
                    try:
                        _seq_panels_graph = self._sequence_panel_slot(op_name) if hasattr(self, "_sequence_panel_slot") else None
                        if isinstance(_seq_panels_graph, dict) and str(_seq_panels_graph.get("script") or "").strip():
                            _inst_script = str(_seq_panels_graph.get("script") or "")
                    except Exception:
                        pass
                    _gas_graph = getattr(self, "global_algo_state", {}) or {}
                    _algo_script = str(_gas_graph.get("script") or "") if bool(_gas_graph.get("apply_enabled", False)) else ""
                    # GROOVEBOX_R23R_ALGO_AVERAGING_20261103: every active algorithm on
                    # this synth (global, its local bay, canonical parallel fix) is a
                    # contender; their bounded drives AVERAGE per value instead of
                    # stacking or overriding.
                    _contenders = self._algo_contenders_for(op_name)
                    if (_inst_script.strip() or _contenders) and local_t.size:
                        _cn = min(24, max(4, int(local_t.size // 1024) + 4))
                        _ci = np.unique(np.linspace(0, local_t.size - 1, _cn).astype(int))
                        _cv = []
                        _seq_id_graph = int((getattr(self, "instrument_selected_sequence", {}) or {}).get(op_name, 1) or 1)
                        for _jj in _ci:
                            _ct = float(local_t[_jj])
                            _tn = float(_jj) / float(max(1, local_t.size - 1))
                            _gain = 1.0
                            if _inst_script.strip():
                                _gr = _evaluate_app_graph_script(self, _inst_script, _ct, t_norm=_tn, slot=op_idx, row=row_idx, sequence=_seq_id_graph, step=int(_tn*max(1, pattern_len-1)), name=op_name)
                                _drv = float(_gr.get("scalar", _gr.get("wave", _gr.get("drive", 0.0))) or 0.0)
                                _amp = float(_gr.get("amp", _gr.get("gain", 1.0)) or 1.0)
                                _gain *= float(np.clip(_amp, 0.25, 2.0)) * (1.0 + 0.10 * math.tanh(_drv))
                            if _contenders:
                                _terms = []
                                for _src, _cs, _cm in _contenders:
                                    _ar = _evaluate_app_graph_script(self, _cs, _ct, t_norm=_tn, slot=op_idx, row=row_idx, sequence=_seq_id_graph, step=int(_tn*max(1, pattern_len-1)), name=op_name, function_names=("global_script", "evaluate_wave", "evaluate", "main"))
                                    _adrv = float(_ar.get("scalar", _ar.get("wave", _ar.get("drive", 0.0))) or 0.0)
                                    _terms.append(_cm * math.tanh(_adrv))
                                _gain *= 1.0 + 0.10 * (sum(_terms) / float(len(_terms)))
                            _cv.append(float(np.clip(_gain, 0.20, 2.50)))
                        if _cv:
                            _curve = np.interp(np.arange(local_t.size), _ci.astype(float), np.asarray(_cv, dtype=float)).astype(np.float32)
                            voice = (voice * _curve).astype(np.float32)
                except Exception as _graph_script_exc:
                    print(f"[GraphScript] audio control-rate evaluation skipped: {_graph_script_exc}")

                # R12 CROSS-MEDIA EQ audio stage. Flat is an exact no-op.
                try:
                    _eqst = dict(st or {}) if not getattr(self, "_render_raw_no_fx", False) else {}     # raw export: flat EQ
                    if str(_eqst.get("eq_scope","Per Instrument")) == "Global":
                        _eqst.update(dict(getattr(self,"global_eq_state",{}) or {}))
                    _auto_level = float(np.clip(np.mean(np.abs(step_env)) if np.size(step_env) else 1.0,0.0,1.5))
                    _env_level = float(np.clip(np.mean(np.abs(env_f)) if np.size(env_f) else 1.0,0.0,1.5))
                    voice = apply_instrument_eq(voice, sample_rate, _eqst, _auto_level, _env_level)
                except Exception:
                    pass
                # Per-step EQ gain and sidechain are applied before this shared render
                # buffer fans out to audio export, video export, and game generation.
                try:
                    if getattr(self, "_render_raw_no_fx", False):
                        pass      # GROOVEBOX_R23R_RAW_EXPORT_20261103: no per-step EQ / keys / sidechain
                    elif _step_band_eq:   # R31: SciPy-free zero-phase band EQ, same on every OS
                        voice = self._apply_step_band_eq(voice, _step_band_eq, sample_rate)
                    elif step_eq_gain_track.size and np.any(step_eq_gain_track):
                        # Fallback without SciPy: the step EQ acts as a broadband level.
                        voice = (voice * np.power(10.0, step_eq_gain_track / 20.0)).astype(np.float32)
                    if step_key_track.size and np.any(step_key_track) and not getattr(self, "_render_raw_no_fx", False):
                        _key_env = self._sidechain_key_env(step_key_track, sample_rate)
                        voice = (voice * (1.0 + _key_env)).astype(np.float32)      # key lifts up to ×2 (+6 dB)
                        _row_key_envs[str(op_name)] = _key_env
                    try:
                        _sc_route = float((st or {}).get("sidechain_mod", 0.0) or 0.0) if isinstance(st, dict) else 0.0
                    except Exception:
                        _sc_route = 0.0
                    if _sc_route and step_sidechain_track.size:
                        step_sidechain_track = np.clip(step_sidechain_track + _sc_route, 0.0, 1.0)
                    if step_sidechain_track.size and np.any(step_sidechain_track) and not getattr(self, "_render_raw_no_fx", False):
                        voice = (voice * (1.0 - 0.85 * np.clip(step_sidechain_track, 0.0, 1.0))).astype(np.float32)
                except Exception: pass

                # IMPORT_PHASELOCK_50_2026: loaded sample contributes phase only
                # at 50%; canonical synthesis remains the complete authoritative
                # composition and keeps its scalar pitch/amp/envelope.
                if imported_carrier is not None and np.any(voice != 0.0):
                    try:
                        _carrier_seg = imported_carrier[mask]
                        if _carrier_seg.shape == voice.shape and np.any(_carrier_seg != 0.0):
                            voice = self._phase_lock_voice_to_import(voice, _carrier_seg, amount=0.5)
                    except Exception:
                        pass
                # Harmonic Lattice is detail only. Cap wet so it cannot overwrite
                # seed-defined harmonic/entropy identity (was homogenizing voices).
                if synth_lattice > 0.0 and not getattr(self, "_render_raw_no_fx", False):
                    try:
                        _lat_act = float(np.clip(synth_lattice, 0.0, 1.0)) * 0.70  # freer lattice wet
                        gamma = 1.25 + MEUM_NORM * 2.0 + 0.35 * chaos + 0.08 * fold_depth
                        voice = self._harmonic_lattice.process(
                            voice,
                            activation=_lat_act,
                            gamma=gamma,
                            pkp_env=env_f,
                            bpm=float(bpm),
                        )
                    except Exception:
                        pass
                    # MASTER_FX_FIX_2026: per-voice EQR tensor removed — EQR is
                    # applied once, on the master bus tail, far from the engines.

                    # CANONICAL_TIME_FIT: engine-authored (canonical) voices blend toward
                    # the carrier's own waveform at their exact trigger time, so the
                    # canonical engines actually converge on the desired signal instead
                    # of just triggering an unmodified oscillator and leaving all fitting
                    # to the global (whole-buffer) bus convolve stage below. This is
                    # deliberately restricted to canonical voices only (mem carries a
                    # "canonical:" owner) and gated on the same "convolve fit" checkbox
                    # the user already uses for the global stage, at a capped wet amount,
                    # so user-owned material is never touched and canonical identity is
                    # blended toward the target rather than replaced by it (the earlier
                    # attempt applied this to every voice unconditionally and washed out
                    # per-voice harmonic/entropy identity into one shared shape).
                    is_canonical_voice = str(mem.get("canonical_owner", "")).startswith("canonical:")
                    if (
                        is_canonical_voice
                        and convolve_fit_enabled
                        and imported_carrier is not None
                        and convolve_fit_amount > 0.0
                    ):
                        try:
                            target = imported_carrier[mask]
                            if target.shape == voice.shape and np.any(target != 0.0):
                                tpk = float(np.max(np.abs(target))) if target.size else 0.0
                                target_n = (target / tpk).astype(np.float32) if tpk > 0.0 and math.isfinite(tpk) else np.zeros_like(target, dtype=np.float32)
                                # Cap wet at 50% so the canonical voice's own seed-derived
                                # harmonic/entropy identity always remains in the mix.
                                fit_wet = float(np.clip(convolve_fit_amount, 0.0, 1.0)) * 0.5
                                # Only blend at this voice's own gated (triggered) samples
                                # so the fit tracks its specific step/trigger time and
                                # never bleeds into the silence between its own hits.
                                voice = np.where(
                                    gate != 0.0,
                                    (1.0 - fit_wet) * voice + fit_wet * target_n * gate,
                                    voice,
                                ).astype(np.float32)
                        except Exception:
                            pass

                    voice_gain = self._canonical_voice_gain(
                        op_name, user_voice_count, canonical_count, len(active_cluster)
                    )
                    # ROW_SPARSE_MASK_2026: gate voices outside this row's
                    # deterministic subgroup.  Applied after the voice is fully
                    # synthesized so every oscillator's phase carry still advances
                    # (no phase jump when the instrument returns on a later row).
                    # GROOVEBOX_R23R_STEM_EXPORT_20261103: stem filters (rows / instruments).
                    _stem = getattr(self, "_render_stem_filter", None)
                    if isinstance(_stem, dict):
                        if _stem.get("rows") is not None and int(row_idx) not in _stem["rows"]:
                            voice_gain = 0.0
                        if _stem.get("instruments") is not None and str(op_name) not in _stem["instruments"]:
                            voice_gain = 0.0
                    if _sp_mask is not None and int(op_idx) not in _sp_mask:
                        voice_gain = 0.0
                    op_offset_sec = float(op_time_offsets.get(op_name, 0.0) or 0.0)
                    if voice_gain != 0.0 and not getattr(self, "_render_raw_no_fx", False):
                        # R32.10: per-voice LOCAL FX, Layer EQ and Mod Osc reach the mixdown (and so every
                        # audio / video / A-V export), not only live key hits.
                        try:
                            _vp_hz = locals().get("seed_freq", base_freq)
                            _vp_hz = float(np.ravel(_vp_hz)[0]) if np.ndim(_vp_hz) else float(_vp_hz)
                            if not (_vp_hz > 0.0 and math.isfinite(_vp_hz)):
                                _vp_hz = float(base_freq)
                            voice = self._r32_voice_post(op_name, _vp_hz, local_t, voice, sample_rate)
                        except Exception as _vp_exc:
                            print(f"[voice post] skipped: {_vp_exc}")
                    _contrib = (voice * voice_gain).astype(np.float32)
                    _target_kind = "user" if _mem_has_user else "canonical"
                    _shift_samples = int(round(op_offset_sec * sample_rate))
                    _row_voice_contribs.append((str(op_name), _target_kind, _contrib, _shift_samples))
                    if op_offset_sec == 0.0:
                        if not _native_accumulate_f32(row_mix, _contrib, 1.0):
                            row_mix += _contrib

            # GROOVEBOX_R23R_SIGNED_SIDECHAIN_BAND_EQ_20261103: negative step sidechain
            # keys duck every OTHER voice in the row under their envelope.
            if _row_key_envs and _row_voice_contribs and not getattr(self, "_render_raw_no_fx", False):
                try:
                    _rk_len = end_idx - start_idx
                    _rk_by = {}
                    for _kn, _kk, _kv, _ks in _row_voice_contribs:
                        if _kn in _row_key_envs:
                            _ke = np.zeros(_rk_len, dtype=np.float32)
                            _d0 = max(0, _ks); _d1 = min(_rk_len, _rk_len + _ks)
                            if _d1 > _d0:
                                _s0 = max(0, -_ks)
                                _ke[_d0:_d1] = _row_key_envs[_kn][_s0:_s0 + (_d1 - _d0)][: _d1 - _d0]
                            _rk_by[_kn] = _ke
                    if _rk_by:
                        # Each key ducks a neighbour by how much that neighbour shares the
                        # key's space: spectral-centre closeness (octaves) × level overlap.
                        _prof = {}
                        for _pn, _pk, _pv, _ps in _row_voice_contribs:
                            _pv64 = np.asarray(_pv, dtype=np.float64)
                            _rms = float(np.sqrt(np.mean(_pv64 ** 2))) if _pv64.size else 0.0
                            _cen = 0.0
                            if _rms > 1e-9:
                                _spec = np.abs(np.fft.rfft(_pv64[: min(_pv64.size, 1 << 16)]))
                                _fr = np.fft.rfftfreq(min(_pv64.size, 1 << 16), 1.0 / float(sample_rate))
                                _ssum = float(np.sum(_spec))
                                _cen = float(np.sum(_fr * _spec) / _ssum) if _ssum > 0.0 else 0.0   # silent: no centre
                            _prof[_pn] = (_cen, _rms)
                        _new = []
                        for _tn, _tk, _tv, _ts in _row_voice_contribs:
                            _duck = np.zeros(_rk_len, dtype=np.float32)
                            _ct, _rt = _prof.get(_tn, (0.0, 0.0))
                            for _kn2, _ke2 in _rk_by.items():
                                if _kn2 == _tn:
                                    continue
                                _ck, _rk2 = _prof.get(_kn2, (0.0, 0.0))
                                if _ct <= 0.0 or _ck <= 0.0 or _rt <= 0.0:
                                    _sim = 0.0
                                else:
                                    _spec_sim = math.exp(-abs(math.log2(_ct / _ck)))          # 1 at same centre, 0.5 an octave away
                                    _lvl = min(1.0, _rt / _rk2) if _rk2 > 0.0 else (1.0 if _rt > 0.0 else 0.0)                  # neighbours as loud as the key mask it most
                                    _sim = float(np.clip(0.25 + 0.75 * _spec_sim * (0.5 + 0.5 * _lvl), 0.0, 1.0))
                                _duck += _ke2 * _sim
                            _duck = np.clip(_duck, 0.0, 1.0)
                            if _ts:
                                _duck = np.roll(_duck, -_ts)
                            _tv = (_tv * (1.0 - 0.85 * _duck[: _tv.size])).astype(np.float32)
                            _new.append((_tn, _tk, _tv, _ts))
                        _row_voice_contribs = _new
                except Exception as _key_exc:
                    print(f"[Sidechain key] skipped: {_key_exc}")
            # R28.4.9 SHARED SOURCE-DRIVEN SIDECHAIN: source detection happens
            # after all voices are synthesized, so source order cannot affect targets.
            # Only the voice contribution is ducked/expanded; oscillator waveform,
            # P/F/A modulation and EQ remain intact. Both realtime playback and WAV
            # export consume this same renderer, so they receive identical DSP.
            try:
                _sc_state = getattr(self, "sidechain_state", {}) or {}
                _sc_global = _sc_state.get("global", {}) if isinstance(_sc_state, dict) else {}
                if bool(_sc_global.get("enabled", True)) and _row_voice_contribs and not getattr(self, "_render_raw_no_fx", False):
                    _sc_source = str(_sc_global.get("source", "master") or "master").strip().lower()
                    _sc_source_names = []
                    if _sc_source in ("master", "playlist"):
                        _sc_source_names = [r[0] for r in _row_voice_contribs]
                    elif _sc_source == "kick":
                        _sc_source_names = [r[0] for r in _row_voice_contribs if "kick" in r[0].lower()]
                    elif _sc_source == "selected instrument":
                        _sc_selected = str(getattr(self, "current_instrument_name", "") or "")
                        _sc_source_names = [r[0] for r in _row_voice_contribs if r[0] == _sc_selected]
                    else:
                        _sc_source_names = [r[0] for r in _row_voice_contribs if r[0] == _sc_source]
                    _sc_source_set = set(_sc_source_names)
                    _sc_src = np.zeros(end_idx - start_idx, dtype=np.float32)
                    for _sn, _sk, _sv, _ss in _row_voice_contribs:
                        if _sn not in _sc_source_set:
                            continue
                        _dst0 = max(0, _ss); _dst1 = min(_sc_src.size, _sc_src.size + _ss)
                        if _dst1 > _dst0:
                            _src0 = max(0, -_ss); _src1 = _src0 + (_dst1 - _dst0)
                            _sc_src[_dst0:_dst1] += _sv[_src0:_src1]
                    _sc_peak = float(np.max(np.abs(_sc_src))) if _sc_src.size else 0.0
                    if _sc_peak > 1e-9 and math.isfinite(_sc_peak):
                        _sc_src_abs = np.abs(_sc_src.astype(np.float64)) / _sc_peak
                        try:
                            _sc_eff = self._effective_sidechain_global()
                        except Exception:
                            _sc_eff = _sc_global
                        _sc_attack = max(0.001, min(0.250, float(_sc_eff.get("attack_ms", 5.0) or 5.0) / 1000.0))
                        _sc_release = max(0.005, min(2.0, float(_sc_eff.get("release_ms", 120.0) or 120.0) / 1000.0))
                        _sc_env = np.zeros(_sc_src_abs.size, dtype=np.float32)
                        _sc_a = math.exp(-1.0 / max(1.0, _sc_attack * sample_rate))
                        _sc_r = math.exp(-1.0 / max(1.0, _sc_release * sample_rate))
                        _sc_prev = 0.0
                        for _si, _svabs in enumerate(_sc_src_abs):
                            _sc_coef = _sc_a if _svabs > _sc_prev else _sc_r
                            _sc_prev = _sc_coef * _sc_prev + (1.0 - _sc_coef) * float(_svabs)
                            _sc_env[_si] = _sc_prev
                        _sc_env = np.clip(_sc_env, 0.0, 1.0)
                        _sc_targets = _sc_state.get("targets", {}) if isinstance(_sc_state, dict) else {}
                        for _tn, _tk, _tv, _ts in _row_voice_contribs:
                            # A source does not duck itself; this also prevents the
                            # master-source mode from self-canceling its detector.
                            if _sc_source in ("kick", "selected instrument") and _tn in _sc_source_set:
                                _gain_curve = None
                            else:
                                _amount = float(np.clip(self._canonical_sidechain_amount_for(_tn), -1.0, 1.0))
                                if abs(_amount) < 1e-12:
                                    _gain_curve = None
                                else:
                                    # Positive amount ducks; negative amount expands
                                    # toward 2x. The bounded gain cannot mute a voice.
                                    _gain_curve = np.clip(1.0 - _amount * _sc_env, 0.05, 2.0).astype(np.float32)
                            _tv_sc = (_tv * _gain_curve).astype(np.float32) if _gain_curve is not None else _tv
                            _bus = userdata_bus if _tk == "user" else canonical_bus
                            if _ts == 0:
                                _bus[mask] += _tv_sc
                            else:
                                _base_idx = np.arange(start_idx, end_idx, dtype=np.int64)
                                _dest_idx = _base_idx + _ts
                                _valid = (_dest_idx >= 0) & (_dest_idx < n_samples)
                                if np.any(_valid):
                                    np.add.at(_bus, _dest_idx[_valid], _tv_sc[_valid])
                    else:
                        # No valid detector source: pass voices through unchanged.
                        for _tn, _tk, _tv, _ts in _row_voice_contribs:
                            _bus = userdata_bus if _tk == "user" else canonical_bus
                            if _ts == 0:
                                _bus[mask] += _tv
                            else:
                                _base_idx = np.arange(start_idx, end_idx, dtype=np.int64)
                                _dest_idx = _base_idx + _ts
                                _valid = (_dest_idx >= 0) & (_dest_idx < n_samples)
                                if np.any(_valid):
                                    np.add.at(_bus, _dest_idx[_valid], _tv[_valid])
                else:
                    for _tn, _tk, _tv, _ts in _row_voice_contribs:
                        _bus = userdata_bus if _tk == "user" else canonical_bus
                        if _ts == 0:
                            _bus[mask] += _tv
                        else:
                            _base_idx = np.arange(start_idx, end_idx, dtype=np.int64)
                            _dest_idx = _base_idx + _ts
                            _valid = (_dest_idx >= 0) & (_dest_idx < n_samples)
                            if np.any(_valid):
                                np.add.at(_bus, _dest_idx[_valid], _tv[_valid])
            except Exception as _sc_exc:
                print(f"[Canonical Sidechain] source-driven DSP skipped safely: {_sc_exc}")
                for _tn, _tk, _tv, _ts in _row_voice_contribs:
                    _bus = userdata_bus if _tk == "user" else canonical_bus
                    if _ts == 0:
                        _bus[mask] += _tv
                    else:
                        _base_idx = np.arange(start_idx, end_idx, dtype=np.int64)
                        _dest_idx = _base_idx + _ts
                        _valid = (_dest_idx >= 0) & (_dest_idx < n_samples)
                        if np.any(_valid):
                            np.add.at(_bus, _dest_idx[_valid], _tv[_valid])

            # PKP NullLock / BOOST is an explicit one-shot audition action only.
            # Do NOT derive a sound source from every active step of the selected
            # instrument during the normal timeline render.  The selected
            # instrument's sequencer steps already produce their programmed voice
            # above; adding a second PKP oscillator here caused BOOST-like hits on
            # every selected step.  The BOOST button remains responsible for its
            # explicit one-shot playover via _play_selected_instrument_pkp() and
            # _play_pkp_playover_modulator().

            # GROOVEBOX_R23R_GEOMETRY_PER_INSTRUMENT_20261031: the four geometric
            # synths are no longer one shared global carrier (GEOMETRIC_GLOBAL_CARRIERS_HF25
            # retired). Each instrument's voice runs its own Vector / Wavetable / Ball /
            # Cellular instance (see _instance_voice_geometry); GOAVA stays single-instance.

            # CANONICAL_INSTRUMENT_CONVOLVE_2026: bounded 0–100% canonical→instrument
            # convolution. The user branch is never replaced outright: the transformed
            # branch contains 50% of the original user waveform before its coefficient
            # reaches the optional live-overblend composition boundary. This makes
            # 100% a stable convolution reference, not a hidden third bus or final-volume boost.
            try:
                _cc_amt = float(self.spin_canonical_convolve.value()) / 100.0 if hasattr(self, "spin_canonical_convolve") else CANONICAL_CONVOLVE_DEFAULT_PCT / 100.0
                if _cc_amt > 0.0 and canonical_bus[mask].size > 8:
                    _cv = np.asarray(canonical_bus[mask], dtype=np.float64)
                    _uv = np.asarray(userdata_bus[mask], dtype=np.float64)
                    _kl = min(1024, max(32, _cv.size // 200))
                    _kernel = _cv[:_kl].copy()
                    _kn = float(np.linalg.norm(_kernel))
                    _uv_peak = float(np.max(np.abs(_uv))) if _uv.size else 0.0
                    if _kn == 0.0 or not math.isfinite(_kn) or _uv_peak == 0.0 or not math.isfinite(_uv_peak):
                        _conv = _uv.copy()
                    else:
                        _kernel /= _kn
                        _rust_block = int((getattr(self, "_rust_render_plan", {}) or {}).get("rust_fft_block", 2048) or 2048)
                        _conv = _native_convolve_ola_f32(_uv, _kernel, _rust_block)
                        if _conv is None:
                            _nfft = 1 << int(np.ceil(np.log2(_uv.size + _kernel.size - 1)))
                            _conv = np.fft.irfft(np.fft.rfft(_uv, _nfft) * np.fft.rfft(_kernel, _nfft), _nfft)[:_uv.size]
                        _cn = float(np.max(np.abs(_conv))) if _conv.size else 0.0
                        if _cn == 0.0 or not math.isfinite(_cn):
                            _conv = _uv.copy()
                        else:
                            _conv = _conv * (_uv_peak / _cn)
                    _transformed_user = 0.50 * _uv + 0.50 * _conv
                    userdata_bus[mask] = ((1.0 - _cc_amt) * _uv + _cc_amt * _transformed_user).astype(np.float32)
            except Exception as _cc_exc:
                print(f"[Canonical→Instrument Convolve] skipped: {_cc_exc}")

            # MEUM_SPATIAL_ACTIVITY_2026: resolve the canonical branch against the
            # user branch in direct x/y/z coordinates before the optional live overblend.
            # This is the structural activity-floor mechanism: no final-signal clamp.
            try:
                _cspatial, _cmod, _closs = self._meum_spatial_resolve_activity(
                    canonical_bus[mask], userdata_bus[mask], row_idx=row_idx, seed_value=seed_val
                )
                canonical_bus[mask] = _cspatial
                self.meum_spatial_activity_modulus = float(_cmod)
                self.meum_spatial_loss = float(_closs)
            except Exception:
                pass

            # SHARED_USER_CANONICAL_FEATURES_2026: activity is audited separately
            # from amplitude coefficients. Six shared coordinates currently form the
            # common feature plane: time, rhythm, pitch, envelope, phase, modulation.
            try:
                self._record_canonical_activity(
                    row_idx, canonical_bus[mask], userdata_bus[mask],
                    canonical_gate=_canonical_cont_gate if "_canonical_cont_gate" in locals() else None,
                    user_gate=None,
                )
                feat = ["time", "rhythm", "pitch", "envelope", "phase", "modulation",
                        "tempo", "AM", "FM", "PM", "wavetable_vector", "playlist_mapping"]
                self._canonical_activity_ledger.setdefault(int(row_idx), {})["shared_feature_completeness"] = len(feat) / 12.0
                self._canonical_activity_ledger[int(row_idx)]["shared_feature_count"] = len(feat)
                self._canonical_activity_ledger[int(row_idx)]["meum_spatial_activity_modulus"] = float(getattr(self, "meum_spatial_activity_modulus", 0.50))
                self._canonical_activity_ledger[int(row_idx)]["meum_spatial_loss"] = float(getattr(self, "meum_spatial_loss", 0.0))
                if getattr(self, "lbl_meum_spatial", None) is not None:
                    _mtxt = f"ACTIVITY MODULUS: {self.meum_spatial_activity_modulus*100:.0f}%  ·  GEOMETRIC LOSS: {self.meum_spatial_loss:.3f}"
                    self._gui_refresh("meum_spatial_label", lambda _t=_mtxt: self.lbl_meum_spatial.setText(_t))
            except Exception:
                pass

            # CANONICAL_LIVE_OVERBLEND_20260907: canonical authority/transforms are
            # separate from additive waveform share. Default 50% keeps the live/user
            # waveform fully dynamic; 50% reproduces the legacy 50/50 source blend.
            # Canonical-only rows fall back to C so generative material cannot vanish.
            try:
                _live_overblend = float(self.spin_canonical_live_overblend.value()) / 100.0 if hasattr(self, "spin_canonical_live_overblend") else CANONICAL_LIVE_OVERBLEND_DEFAULT_PCT / 100.0
                _live_overblend = max(0.0, min(1.0, _live_overblend))
            except Exception:
                _live_overblend = 0.0
            _urow = userdata_bus[mask]
            _crow = canonical_bus[mask]
            _stem_bus = (getattr(self, "_render_stem_filter", None) or {}).get("bus") if isinstance(getattr(self, "_render_stem_filter", None), dict) else None
            if _stem_bus == "user":
                master[mask] += _urow
            elif _stem_bus == "canonical":
                master[mask] += _crow
            elif _urow.size and bool(np.any(_urow != 0.0)):
                master[mask] += (1.0 - _live_overblend) * _urow + _live_overblend * _crow
            else:
                master[mask] += _crow

        if _r32_auto_used and not getattr(self, "is_playing", False):
            try:
                _r32_auto.restore_bases(self)      # R32.8: the project keeps its base values
            except Exception:
                pass
        try:
            import perseq_vars as _psv
            _psv.render_done(self)                 # R32.9: global state back after the per-row morph
        except Exception:
            pass
        # ROW_BOUNDARY_SMOOTH_FIX_2026: the phase-carry fix above keeps each
        # voice's oscillator phase continuous across row boundaries, but the
        # per-note PKP envelope (_fo above) is still built from a row-local
        # `local_t` array. A note whose release tail (_hi = _note_end + step)
        # would extend past the current row's end is simply truncated by the
        # row `mask`, instead of continuing to fade into the next row. That
        # truncation is an amplitude discontinuity at the row boundary —
        # audible as a click/pop "burst" on every row, independent of the
        # phase fix, and independent of whether an algorithm is applied. It
        # is why bursts persisted (now spread across every row boundary,
        # i.e. "distributed") even after phase continuity was fixed.
        # Rather than re-deriving every voice's envelope on a global timeline
        # (a much larger change touching the whole per-row model), apply a
        # short equal-power crossfade of the master bus across every row
        # boundary: blend the last few ms before the boundary with the first
        # few ms after it, so any leftover step/edge discontinuity is folded
        # into a smooth transition instead of a hard edge.
        # ONLY_LISTED_FX_20261102: this master-bus fade (it dips the signal to zero across every row
        # boundary) is not one of the allowed effects. Off unless GROOVEBOX_ROW_CROSSFADE=1.
        if rows > 1 and n_samples > 8 and os.environ.get("GROOVEBOX_ROW_CROSSFADE", "") == "1":
            _fade_ms = 6.0
            _fade_n = max(2, min(int(sample_rate * _fade_ms / 1000.0), n_samples // 4))
            # CROSSFADE_FIX_2026: the old ramp was inverted — the post-boundary
            # head was multiplied by (0.5 + 0.5*reversed_curve), i.e. it STARTED
            # at full amplitude (1.0) while the pre-boundary tail only decayed
            # to 0.5.  The sample right at each row boundary therefore jumped
            # 2x in amplitude — the exact "burst" edge.  Equal-power pair from a
            # shared phase: tail crosses 1→0 (cos), head crosses 0→1 (sin), so
            # the net transition is continuous and click-free.
            _fade_phase = np.linspace(0.0, np.pi / 2.0, _fade_n, dtype=np.float64)
            _fade_out = ot_cos_vec_equiv(_fade_phase).astype(np.float32)
            _fade_in = ot_sin_vec_equiv(_fade_phase).astype(np.float32)
            for row_idx in range(1, rows):
                boundary = int(round(row_idx * row_duration * sample_rate))
                lo = boundary - _fade_n
                hi = boundary + _fade_n
                if lo < 0 or hi > n_samples:
                    continue
                master[lo:boundary] *= _fade_out
                master[boundary:hi] *= _fade_in

        # CANONICAL UNISON EFFECT BOUNDARY
        # Snapshot the fully reconciled playlist/unison render before any global
        # effect can transform it. Every downstream global effect reads this
        # transaction snapshot, so effect buffering cannot depend on activation
        # order or on a partially composed playlist.
        unison_buffer = master.copy().astype(np.float32)
        self._canonical_unison_effect_buffer = unison_buffer.copy()
        self._canonical_unison_effect_length = int(unison_buffer.size)
        self._canonical_unison_effect_seed = _safe_int_seed(seed_val)

        # Ensemble-size invariant headroom: adding surviving voices must not make
        # the master bus progressively louder.  Normalize by sqrt(active voices) only
        # when the canonical playlist is driving a multi-voice cluster; this preserves
        # the composition while preventing resize/toggle accumulation from sounding
        # like repeated gain.
        if global_playlist_enabled:
            try:
                ensemble_voice_count = max(1, len(set(
                    n for e in self.master_playlist_data[:rows] if isinstance(e, dict)
                    for n in (e.get("operators", []) if isinstance(e.get("operators", []), list) else str(e.get("operators", "")).split(","))
                    if str(n).strip() in self.instrument_names_48
                )))
                if False and ensemble_voice_count > 1:
                    # AMPLITUDE_FIX_2026: ensemble headroom normalization removed.
                    # This silently scaled the whole mix down by 1/sqrt(N) on
                    # every render with >1 active voice, which is exactly the
                    # kind of "final mix amplitude modification" that must not
                    # exist outside Master Volume + the hard clipper. Any
                    # headroom management now belongs solely to Master Volume.
                    master /= float(np.sqrt(ensemble_voice_count))
            except Exception:
                pass

        # CANONICAL_USER_CARRIER_PROOF_20260907: canonical activity/control remains
        # available to transforms, while the final waveform share is an optional
        # user-controlled crossfade. Default 50% canonical live overblend preserves
        # the user/live envelope; canonical-only rows fall back to canonical audio.
        try:
            c_rms = float(np.sqrt(np.mean(np.square(canonical_bus.astype(np.float64))))) if canonical_bus.size else 0.0
            u_rms = float(np.sqrt(np.mean(np.square(userdata_bus.astype(np.float64))))) if userdata_bus.size else 0.0
            carrier_present = imported_carrier is not None and bool(np.any(imported_carrier != 0.0))
            self._canonical_user_blend_ledger = {
                **self._verify_canonical_user_carrier_contract(carrier_present),
                "canonical_minimum": 0.0,
                "userdata_minimum": 0.0,
                "canonical_live_overblend": float(self.spin_canonical_live_overblend.value()) / 100.0 if hasattr(self, "spin_canonical_live_overblend") else 0.0,
                "carrier_present": carrier_present,
                "carrier_role": "modulation_reference",
                "carrier_phase_lock": 0.50,
                "carrier_in_xmod": bool(carrier_present),
                "multi_target_blend": True,
                "arbitrary_time_offsets": True,
                "canonical_rms": c_rms,
                "userdata_rms": u_rms,
                "proof_status": bool(canonical_bus.size and np.all(np.isfinite(canonical_bus)) and np.all(np.isfinite(userdata_bus))),
                "autonomous_canonical_continuation": True,
                "shared_user_canonical_features": ["time", "rhythm", "pitch", "envelope", "phase", "modulation", "tempo", "AM", "FM", "PM", "wavetable_vector", "playlist_mapping"],
                "activity_floor_is_structural": True,
                "activity_ledger_rows": int(len(getattr(self, "_canonical_activity_ledger", {}) or {})),
                "shared_feature_completeness": 1.0,
                "shared_feature_count": 12,
                "meum_spatial_activity_modulus": float(getattr(self, "meum_spatial_activity_modulus", 0.50)),
                "meum_spatial_loss": float(getattr(self, "meum_spatial_loss", 0.0)),
                "canonical_50_to_100_proof": self._canonical_range_proof_report(),
                "canonical_range_proof": self._prove_canonical_50_to_100_range(),
                "canonical_instrument_convolve_max": 1.00,
            }
        except Exception as _blend_proof_exc:
            self._canonical_user_blend_ledger = {"proof_status": False, "error": str(_blend_proof_exc)}

        # FULL ENV-FOLLOW SYMMETRY — ONE shared time-predictive follow env.
        # Built once from the canonical unison snapshot (before any global
        # effect transforms it) and threaded into EVERY master-bus effect —
        # Global Convolve, DomainEQ, SeedScript T-axis, Fractallizer, EQR,
        # PED, and PKP — so the whole tail breathes through the exact same
        # envelope function (EQR follow: forward-max + 0.85/0.15 release;
        # PKP envelope damps the tempo swing).  Stored on self at low resolution
        # so the visualizers can draw the same envelope.
        try:
            _shared_pkp_d = max(0.0, float(self.slider_pkp_envelope.value()) / 1000.0) if hasattr(self, "slider_pkp_envelope") else 0.5
        except Exception:
            _shared_pkp_d = 0.5
        try:
            # Balance env-follow to the playlist STEP grid (16th), morphing
            # tile length toward one row as PKP Envelope → 1.0.
            _step_len = None
            _row_len = None
            try:
                _sr = float(sample_rate)
                _beat = _sr * (60.0 / positive_bpm(bpm))
                _step_len = max(1, int(round(_beat / 4.0)))
                try:
                    if hasattr(self, "spin_row_beats"):
                        _bpr = float(self.spin_row_beats.value())
                    elif hasattr(self, "spin_playlist_beats"):
                        _bpr = float(self.spin_playlist_beats.value())
                    else:
                        _bpr = 16.0
                except Exception:
                    _bpr = 16.0
                _bpr = max(0.002, min(64.0, _bpr))
                _row_len = max(_step_len, int(round(_beat * _bpr)))
            except Exception:
                _step_len = None
                _row_len = None
            _shared_env = build_master_follow_env(
                master, float(bpm), float(sample_rate), _shared_pkp_d,
                row_length_samples=_row_len,
                step_length_samples=_step_len,
            )
            _vis = _shared_env[:: max(1, len(_shared_env) // 512)][:512]
            self._last_master_env = np.asarray(_vis, dtype=np.float32)
            self._last_master_env_norm = np.clip(_vis, 0.0, 1.0).astype(np.float32)
            self._last_master_env_db = float(np.mean(np.abs(master)))
        except Exception as _env_exc:
            print(f"[ENV] shared follow envelope skipped: {_env_exc}")
            _t_tmp = np.arange(len(master), dtype=np.float32) / float(sample_rate)
            _sw_tmp = float(np.clip(0.45 * (1.0 - 0.7 * _shared_pkp_d), 0.045, 0.45))
            _shared_env = (0.55 + _sw_tmp * ot_cos_vec_equiv(2.0 * np.pi * (float(bpm) / 60.0) * _t_tmp)).astype(np.float32)
            self._last_master_env = _shared_env[:: max(1, len(_shared_env) // 512)][:512]
            self._last_master_env_norm = np.clip(self._last_master_env, 0.0, 1.0)
            self._last_master_env_db = float(np.mean(np.abs(master)))

        # Global Convolve: deterministic geometric cross-convolution of the rendered carrier.
        # User-edited controls remain upstream; this stage only mixes the structural wave result.
        try:
            conv_amt = (float(self.spin_global_convolve.value()) / 100.0) if hasattr(self, "spin_global_convolve") else 0.0
            if conv_amt > 0.0 and len(master) > 8:
                klen = min(2048, max(32, len(master) // 200))
                kt = np.linspace(0.0, 1.0, klen, endpoint=False)
                # Seed-stable geometric kernel; loaded WAV becomes the kernel source
                # when present, otherwise retain the original mathematical kernel.
                if imported_carrier is not None:
                    kernel = imported_carrier[:klen].copy()
                    if kernel.size < klen:
                        kernel = np.pad(kernel, (0, klen - kernel.size), mode="wrap")
                else:
                    gf = float(self.spin_base_frequency.value()) if hasattr(self, "spin_base_frequency") else 432.0
                    kernel = None
                    if bool(getattr(self, "convolve_tracks_workspace", True)):
                        try:
                            kernel = self._global_convolve_kernel(klen, sample_rate, gf)
                        except Exception as _kexc:
                            print(f"[Global Convolve] tracking kernel fallback: {_kexc}")
                            kernel = None
                    if kernel is None:
                        kernel = (ot_sin_vec_equiv(2*np.pi*(gf/ max(sample_rate,1))*np.arange(klen)) +
                                  0.5*ot_sin_vec_equiv(2*np.pi*(gf*MEUM_CONSTANT/max(sample_rate,1))*np.arange(klen)))
                    kernel = np.asarray(kernel, dtype=np.float32)
                kn = np.linalg.norm(kernel)
                if kn != 0.0:
                    kernel /= kn
                    _rust_block = int((getattr(self, "_rust_render_plan", {}) or {}).get("rust_fft_block", 2048) or 2048)
                    conv = _native_convolve_ola_f32(master, kernel, _rust_block)
                    if conv is None:
                        nfft = 1 << int(np.ceil(np.log2(len(master) + len(kernel) - 1)))
                        spec = np.fft.rfft(master, nfft) * np.fft.rfft(kernel, nfft)
                        conv = np.fft.irfft(spec, nfft)[:len(master)].astype(np.float32)
                    cn = np.max(np.abs(conv))
                    if cn != 0.0:
                        conv *= np.max(np.abs(master)) / cn
                    # Cap wet when a seed script is active so bus convolve cannot
                    # wash out per-voice seed/engine character into one spectrum.
                    try:
                        _sv_bus = list(self.get_seed_values(t_value=0.0) or [])
                    except Exception:
                        _sv_bus = []
                    if _sv_bus or (self._seed_text() if hasattr(self, "_seed_text") else "").strip():
                        conv_amt = min(float(conv_amt), 0.18)
                    master = (1.0 - conv_amt) * master + conv_amt * (conv * _shared_env)
        except Exception as e:
            print(f"[Global Convolve] skipped: {e}")

        # Domain partition equations: longitudinal multivariate modulation (additive blend)
        if hasattr(self, 'domain_eq_engine') and self.domain_eq_engine.domains:
            try:
                self.domain_eq_engine.set_seed(self.get_numeric_seed())
                # Normalize time axis 0..1 across the full buffer for partition logic
                t_norm = np.linspace(0.0, 1.0, len(master))
                domain_mod = self.domain_eq_engine.evaluate_series(t_norm, x=0.0, y=0.0, z=0.0)
                # Soft convolution: carrier * (1 + 0.45 * domain) — accentuates without erasing
                master = master * (1.0 + 0.45 * domain_mod.astype(np.float32) * _shared_env)
            except Exception as e:
                print(f"[DomainEQ] render modulation skipped: {e}")

        # SEED_SCRIPT_T_AXIS: seed/script expressions that reference `t` or use
        # the if(...)/elif shorthand are DSP-boundary constructs — they describe
        # a signal over render time, not a single composition-state number.
        # get_numeric_seed() is the static t=0 snapshot. Arrangement-aware
        # composition separately evaluates seed scripts in beat-domain time.
        # This block is the continuous DSP-side
        # evaluation: the seed text is resolved across the real render-time
        # axis `t` and blended in as a gentle, seed-driven texture — a no-op
        # for a plain numeric seed like "432" (constant curve, ~0 contribution)
        # and only audible when the seed field is an actual time-varying script.
        try:
            seed_script_text = self._seed_text() if hasattr(self, "_seed_text") else ""
            _looks_time_varying = any(
                token in seed_script_text for token in ("t", "if(", "if (", "elif", "sin", "cos")
            )
            if seed_script_text.strip() and _looks_time_varying:
                # Freeze the net active canonical set + imported carrier descriptor once
                # per render. Every t/elif evaluation sees exactly the same context.
                _seed_canonical_context = dict(getattr(self, "_canonical_render_input_context", None) or self._canonical_input_context())
                control_n = min(256, max(8, len(master) // 512))
                control_t = np.linspace(0.0, total_duration, control_n, endpoint=False)
                control_vals = np.array([
                    evaluate_seed_expression_at_time(seed_script_text, ct, _seed_canonical_context) for ct in control_t
                ], dtype=np.float64)
                seed_time_curve = np.interp(t, control_t, control_vals)
                # Keep on self so per-voice code elsewhere can sample the same
                # curve by absolute time if it wants finer-grained access.
                self._seed_time_curve = seed_time_curve
                peak_curve = np.max(np.abs(seed_time_curve))
                if peak_curve != 0.0:
                    seed_mod = (seed_time_curve / peak_curve).astype(np.float32)
                    master = master * (1.0 + 0.20 * MEUM_NORM * seed_mod * _shared_env)
        except Exception as e:
            print(f"[SeedScript] T-axis modulation skipped: {e}")

        # AMPLITUDE_FIX_2026: the Global Fractallizer master-bus pass is
        # disabled. Per-synth Harmonic Lattice still runs on individual
        # voices (unaffected); this was the extra spectral/gain-shaping pass
        # on the SUMMED master bus, which is a final-mix modification and is
        # not allowed to run alongside plain Master Volume + hard clip.
        if False:
            try:
                if fractalizer_val > 0.0 and hasattr(self, "_music_fractallizer"):
                    master = self._music_fractallizer.process(
                        master,
                        activation=fractalizer_val,
                        gamma=1.5 + MEUM_NORM * 2.0,
                        pkp_env=_shared_env,
                        bpm=float(bpm),
                        reference_buffer=unison_buffer,
                    )
            except Exception as _gf_exc:
                print(f"[Global Fractallizer] master pass skipped: {_gf_exc}")

        # Final effect-buffer integrity: effects may transform their working
        # copy, but the canonical unison snapshot remains available for the next
        # deterministic render transaction.
        if getattr(self, "_canonical_unison_effect_length", 0) != len(unison_buffer):
            self._canonical_unison_effect_buffer = unison_buffer.copy()
            self._canonical_unison_effect_length = int(unison_buffer.size)

        # AMPLITUDE_FIX_2026: the master-bus EQR tensor pass, the PKP
        # tempo-locked amplitude-envelope multiply, and the PED "tint"
        # multiply are all disabled below.
        #
        # These three were the actual cause of "clamped to a small value"
        # and "everything sounds filtered":
        #   - EQR ran a spectral/tensor transform on the full summed mix.
        #   - PKP multiplied the ENTIRE master buffer by (0.5 + 0.5*env),
        #     i.e. a permanent tremolo pulling level down to as low as 50%.
        #   - PED then multiplied by (0.5 + 0.5*ped*0.5): with no EQR z-rel
        #     history (ped defaults to 1.0) that is STILL an unconditional
        #     ×0.75 on every render, even with every slider at its default.
        #   Stacked, these could pull the pre-hardclip signal down to
        #   roughly 35-50% of its true level before Master Volume even runs,
        #   which reads as "clamped" and, because they're envelope-shaped
        #   multiplies, as "filtered"/pumping.
        #
        # Per request: the only legal post-composition amplitude stages now
        # are Master Volume and the hard clipper in _master_hardclip().
        # MEUM_SPATIAL_EFFECT_2026: EQR is expressed through the Meum spatial
        # field regardless of Operator Theory state.  OT changes only the internal
        # expression route; it does not select a different mathematical model.
        try:
            act = float(self.slider_eqr.value()) / 100.0 if hasattr(self, "slider_eqr") else 0.0
            if act > 0.01 and len(master) > 0:
                if not hasattr(self, "_eqr_tensor") or self._eqr_tensor is None:
                    self._eqr_tensor = EQRTensorEngine()
                _eqr_base = self._eqr_tensor.process(master, activation=act, pkp_env=_shared_env)
                # Direct x,y,z spatial form: x=current sample, y=local field,
                # z=Meum phase field.  The bounded projection is deliberately
                # limited to the EQR wet amount already capped at 50%.
                _x = master.astype(np.float64)
                _win = max(8, min(128, len(master) // 128))
                _local = np.convolve(np.abs(_x), np.ones(_win, dtype=np.float64) / float(_win), mode="same")
                _z = meum_phase_field_vec(np.arange(len(master), dtype=np.float64) / float(max(1, len(master)-1)), rate=MEUM_INV)
                # Field potential Φ(x,y,z) supplies the bounded geometric weight.
                _r = np.sqrt(_x * _x + _local * _local + _z * _z)
                _phi = np.divide(1.0, _r, out=np.zeros_like(_r, dtype=np.float64), where=_r != 0.0)
                _potential_weight = np.clip(_phi / (1.0 + _phi), 0.0, 1.0)
                # Bounded wave mechanics supplies a deterministic xyz standing-wave term.
                _xx = np.arange(len(_x), dtype=np.float64) / max(1, len(_x)-1)
                _wave = ot_sin_vec_equiv(np.pi * _xx) * ot_sin_vec_equiv(np.pi * _local) * ot_sin_vec_equiv(np.pi * ((_z + 1.0) * 0.5))
                _spatial_raw = _x * (0.5 + 0.5 * _potential_weight) + MEUM_INV * _wave
                # Direct Meum x,y,z expression is also sampled explicitly here;
                # this keeps the named field/potential/wave/state forms in the
                # actual EQR effect path.
                _mf = meum_spatial_operator_field_vec(_xx*2.0-1.0, _local, _z)
                _spatial_raw = _spatial_raw + 0.08 * _mf
                # Neighbor state transition is the final compact x/y/z propagation step.
                _spatial = meum_state_transition(_spatial_raw, geometry_weight=0.35).astype(np.float64)
                _meum_mix = min(0.50, 0.50 * act)
                master = ((1.0 - _meum_mix) * _eqr_base.astype(np.float64) + _meum_mix * _spatial).astype(np.float32)
        except Exception as _eqr_exc:
            print(f"[EQR/Meum] mixdown: {_eqr_exc}")
            try:
                if len(master) > 0:
                    env = np.asarray(_shared_env, dtype=np.float32).ravel()
                    if env.size != len(master):
                        env = np.resize(env, len(master))
                    master = (master * (0.5 + 0.5 * env)).astype(np.float32)
            except Exception as _pkp_exc:
                print(f"[PKP] mixdown: {_pkp_exc}")
            try:
                if len(master) > 0:
                    zrel = float(getattr(self, "_eqr_z_rel", 0.0) or 0.0)
                    if zrel != 0.0:
                        t = float(np.clip((zrel - 0.35) / 1.2, 0.0, 1.0))
                        if operator_theory_enabled():
                            ped = 1.0 + 0.14 * math_scale(float(t - 0.5), 1.0)
                        else:
                            ped = 1.0 + 0.14 * float(t - 0.5)
                    else:
                        ped = 1.0
                    master = (master * (0.5 + 0.5 * ped * 0.5)).astype(np.float32)
            except Exception as _ped_exc:
                print(f"[PED] mixdown: {_ped_exc}")

        # CLARITY_FIX_2026: no unconditional smoothing/low-pass pass.  The
        # equal-power row crossfade and closed-form voice harmonics remain the
        # authoritative brightness/click-control stages.

        # OT_EQUIVALENCE_2026: Operator Theory changes the internal arithmetic
        # route, never the final master waveform.  The legacy ot_master_transform
        # remains available to explicit scripts but is not an implicit DSP stage.
        #
        # FINITE_INFINITY_MEUM_HYPERDRIVE_2026: optional deterministic cross-media
        # resonator/drive. It is downstream of canonical composition but upstream
        # of Master Volume/Clip, and does not write back into canonical user data.
        master = self._apply_hyperdrive_audio(master, sample_rate)

        # MASTER_VECTOR_SYNTH_2026: bounded post-composition conversion monitor.
        # User direction and canonical direction each contribute 50%; the vector
        # never replaces canonical composition and remains below unity gain.
        # ONLY_LISTED_FX_20261102: the master vector AM/ring conversion is not an allowed effect.
        if os.environ.get("GROOVEBOX_MASTER_VECTOR_FX", "") == "1":
            master = self._apply_master_vector_conversion(master)
        master = self._apply_master_global_eq(master, sample_rate)
        self._update_signal_monitor(master)

        # MASTER_HARDCLIP_2026: the rendered buffer is stored *pre* volume so
        # the live slider can still trim.  Hard-clip-with-factors is applied
        # at playback and at export (see `_master_hardclip`).  We do NOT peak-
        # normalize here — that would hide the warning the 72% default is for.
        if bool(getattr(self, "reverse_time_mode", False)):
            # REVERSE_TIME_RENDER_20261102: Reverse Time composes / plays / exports the whole track backwards
            # (Time Offset is already part of the composition, so it still applies). Clip reverse is separate.
            master = np.ascontiguousarray(np.asarray(master)[::-1])
        return master.astype(np.float32), sample_rate

    def _master_hardclip(self, master, sample_rate=None, *, apply_master_vol=True):
        """MASTER BUS = volume × factors → HARD CLIP. Nothing else.

        Why this exists / what it deliberately is NOT
        ---------------------------------------------
        The composition sum is the composition identity.  The only legal
        master-stage operations after that sum are:

          1. multiply by the single Performance Master Volume (default 72%;
             0% is exactly zero gain, never a separate mute toggle),
          2. multiply by Clip/Gain *factors* from ``spin_clip_ratio``,
          3. hard-clip to [-1, +1].

        There is NO peak normalizer, NO brickwall limiter envelope, NO EQ,
        NO filter, and NO "gain maximization toward a target peak" on this
        bus.  Earlier soft-gain / density profiles are retired because they
        hid clipping instead of exposing it.  Flat-top hard clip *is* the
        expected behavior when the sum is hot — that is the warning.

        Factors (spin_clip_ratio 0..100):
            0%   → drive ≈ 1.0  (unity into the clipper)
            50%  → drive ≈ 1.5  (default balanced push)
            100% → drive ≈ 2.5  (aggressive push into hard clip)

        Reproducible: same buffer + same ratio + same master_vol → same out.
        """
        n = int(getattr(master, "size", 0) or 0)
        if n <= 0:
            return (np.asarray(master, dtype=np.float32), None)
        m32 = np.asarray(master, dtype=np.float32).ravel()
        # GROOVEBOX_R32_FX_PANELS_20261110: GLOBAL ▸ FX (hardcoded FX, all 0 = bypass) before volume / clip.
        _gfx = getattr(self, "_r32_global_fx", None)
        if callable(_gfx):
            try:
                m32 = np.asarray(_gfx(m32, sample_rate), dtype=np.float32).ravel()
            except Exception:
                pass
        ratio_pct = 50.0
        try:
            if hasattr(self, "spin_clip_ratio"):
                ratio_pct = float(self.spin_clip_ratio.value())
        except Exception:
            pass
        r = float(np.clip(ratio_pct / 100.0, 0.0, 1.0))
        # Linear drive into the clipper — not a soft curve, not a compressor.
        drive = float(1.0 + 1.5 * r)  # 1.0 .. 2.5
        vol = 1.0
        if apply_master_vol:
            try:
                # Preserve literal 0.0: zero gain is not a mute-mode toggle and
                # must never fall through to a nonzero fallback via ``or``.
                vol = float(getattr(self, "master_volume", 0.72))
            except Exception:
                vol = 1.0
        scaled = m32 * np.float32(vol * drive)
        # HARD CLIP — the only ceiling.  No peak rescale afterward.
        # PERF_2026: prefer C++ gb_hardclip_f32 when the accel library is loaded.
        out = None
        _hc = _GB_ACCEL_FUNCS.get("hardclip") if isinstance(_GB_ACCEL_FUNCS, dict) else None
        if _hc is not None and n >= 256:
            try:
                import ctypes as _ct
                out = np.empty(n, dtype=np.float32)
                metrics = np.zeros(3, dtype=np.float32)
                # gain=1.0: volume×drive already applied in `scaled`.
                _hc(
                    scaled.ctypes.data_as(_ct.POINTER(_ct.c_float)),
                    out.ctypes.data_as(_ct.POINTER(_ct.c_float)),
                    _ct.c_size_t(n),
                    _ct.c_float(1.0),
                    metrics.ctypes.data_as(_ct.POINTER(_ct.c_float)),
                )
            except Exception:
                out = None
        if out is None:
            out = np.clip(scaled, -1.0, 1.0).astype(np.float32)
        dens_before = float(np.mean(np.abs(m32) > 0.99)) if n else 0.0
        dens_after = float(np.mean(np.abs(out) >= 0.999)) if n else 0.0
        try:
            self._eqr_peak_db = None
            _pk = float(np.max(np.abs(out))) if n else 0.0
            self._eqr_peak_db = float(20.0 * math.log10(_pk)) if _pk > 0.0 else -math.inf
            self._eqr_z_rel = dens_after
            self._eqr_z_db = dens_after
        except Exception:
            pass
        self._clipgain_report = {
            "mode": "hardclip",
            "ratio_pct": ratio_pct,
            "drive": drive,
            "vol": vol,
            "density_before": dens_before,
            "density_after": dens_after,
            "peak": float(np.max(np.abs(out))) if n else 0.0,
        }
        if hasattr(self, "lbl_clip_gain_status"):
            try:
                status = self.lbl_clip_gain_status
                if status is not None:
                    status.setVisible(True)
                    status.setText(
                        f"HARDCLIP drive {drive:.2f} · vol {vol*100:.0f}% · "
                        f"clip dens {dens_before*100:.2f}%→{dens_after*100:.2f}%"
                    )
            except Exception:
                pass
        return out, self._clipgain_report

    def _clip_gain_profile(self, master, sample_rate):
        """Backward-compatible name → pure hardclip (see ``_master_hardclip``).

        Historical soft gain-maximization / anti-flat-top profile is retired.
        Callers that still invoke this name get volume × factors → hard clip.
        """
        return self._master_hardclip(master, sample_rate, apply_master_vol=True)


    def _sync_composition_toggle_state(self):
        """Maintain an order-independent CompositionToggleState summary.

        Reuses composition_state.py (the atomic canonical-state module). App
        engine buttons map onto its toggle names: euclidean -> live_randomizer,
        seeded -> live_phaselock; the rest share names directly. Because
        CompositionToggleState is immutable and its fingerprint sorts the
        fields, this tees up an order-independent canonical identity — toggle
        order can never change the fingerprint for the same active set.
        """
        st = getattr(self, "composition_toggle_state", None)
        if st is None:
            try:
                seed = int(_safe_int_seed(self.get_numeric_seed()))
            except Exception:
                seed = 0
            st = _composition_state.CompositionToggleState(seed=seed)
        for name, btn_attr in (
            ("goava", "btn_goava"),
            ("randomizer", "btn_local_randomize"),
            ("phaselock", "btn_local_phase_lock"),
            ("live_randomizer", "btn_idealize_rhythm"),
            ("live_phaselock", "btn_seeded_randomize"),
        ):
            btn = getattr(self, btn_attr, None)
            val = bool(btn and btn.isChecked())
            if val != getattr(st, name, False):
                try:
                    st = st.with_toggle(name, val)
                except ValueError:
                    pass
        self.composition_toggle_state = st
        return st

    def _canonical_project_identity_payload(self):
        rows = []
        for i, e in enumerate(getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or []):
            if not isinstance(e, dict): continue
            rows.append((i, e.get("operator"), e.get("operators_csv"),
                         tuple(e.get("sequence_refs") or []),
                         e.get("step_algorithm_scope"), e.get("step_algorithm"),
                         tuple(e.get("global_algorithm_kinds") or []),
                         bool(e.get("global_algorithm_applied"))))
        gas = self._effective_global_algo_state()
        return {"rows": rows, "global_algo": {
            "apply_enabled": bool(gas.get("apply_enabled", False)),
            "script": str(gas.get("script", "")), "domain": str(gas.get("domain", "")),
            "wire": gas.get("wire", []), "params": gas.get("params", {}),
            **{k: str(gas.get(k, "")) for k in GLOBAL_ALGO_EXTRA_KINDS},
        }}

    def _canonical_fingerprint(self):
        """Order-independent short identity of the live project.

        Hash is over seed text, effective seed weight, FullWeight flag, BPM,
        base frequency, the full active-engine toggle vector (incl. the
        order-independent CompositionToggleState digest from composition_state.py
        covering euclidean/seeded live engines), and a stable digest of
        sequencer step presence — never over UI layout or toggle chronology.
        """
        try:
            seed = ""
            if hasattr(self, "input_seed_val") and self.input_seed_val is not None:
                seed = self.input_seed_val.toPlainText() if hasattr(self.input_seed_val, "toPlainText") else str(self.input_seed_val.text() if hasattr(self.input_seed_val, "text") else "")
            toggle_digest = "-"
            try:
                toggle_digest = self._sync_composition_toggle_state().fingerprint()
            except Exception:
                toggle_digest = "-"
            parts = [
                seed.strip(),
                f"{float(self.spin_engine_strength.value()) if hasattr(self, 'spin_engine_strength') else CANONICAL_SEED_WEIGHT_DEFAULT:.4f}",
                "1" if (getattr(self, "chk_fullweight_seed", None) and self.chk_fullweight_seed.isChecked()) else "0",
                f"{float(self.spin_bpm.value()) if hasattr(self, 'spin_bpm') else 120:.3f}",
                f"{float(self.spin_base_frequency.value()) if hasattr(self, 'spin_base_frequency') else 432:.4f}",
                "G" if (getattr(self, "btn_goava", None) and self.btn_goava.isChecked()) else "-",
                "R" if (getattr(self, "btn_local_randomize", None) and self.btn_local_randomize.isChecked()) else "-",
                "P" if (getattr(self, "btn_local_phase_lock", None) and self.btn_local_phase_lock.isChecked()) else "-",
                "E" if (getattr(self, "btn_idealize_rhythm", None) and self.btn_idealize_rhythm.isChecked()) else "-",
                "S" if (getattr(self, "btn_seeded_randomize", None) and self.btn_seeded_randomize.isChecked()) else "-",
                "levels=" + json.dumps(self._canonical_levels(), sort_keys=True, separators=(",",":")),
                "lock=" + json.dumps(self._lock_characteristics(), sort_keys=True, separators=(",",":")),
                f"rand={int(getattr(self,'_rand_instance_seed',0) or 0)}",
                f"vox={hashlib.sha256(repr(sorted(tuple(self._normalize_voxel_record(v) or []) for v in (getattr(self,'voxel_cells',[]) or []) if isinstance(v,(list,tuple)) and len(v)>=3)).encode('utf-8','replace')).hexdigest()[:12]}:{int(getattr(self,'voxel_alias_pct',0) or 0)}",
                f"ts{toggle_digest}",
                # Playlist-effective algorithm/step state is composition data, not UI.
                # Include a bounded canonical digest so apply/unapply changes project ID.
                f"pl{hashlib.sha256(repr(self._canonical_project_identity_payload()).encode('utf-8','replace')).hexdigest()[:16]}",
                "mv" + hashlib.sha256(repr(getattr(self, "master_vector_state", {})).encode("utf-8", "replace")).hexdigest()[:12],
                "eq" + hashlib.sha256(repr(getattr(self, "global_eq_state", {})).encode("utf-8", "replace")).hexdigest()[:12],
                f"goava_mod={float(getattr(self, 'goava_ensemble_mod', 0.1975807343)):.10f}",
                f"rev={1 if getattr(self, 'reverse_time_mode', False) else 0}",
                f"locktime={str(getattr(self, 'phase_lock_time_mode', 'middle'))}",
                f"stoch={str(getattr(self, 'stochastic_mode', 'half-random'))}",
                f"energy={int(self.dial_track_energy.value()) if hasattr(self, 'dial_track_energy') else 50}",
                f"harmonic={int(self.dial_track_harmonic.value()) if hasattr(self, 'dial_track_harmonic') else 50}",
                f"sharp={int(self.dial_project_sharp.value()) if hasattr(self, 'dial_project_sharp') else 50}",
                "varules=" + hashlib.sha256(repr(getattr(self, 'video_assembly_rules', {})).encode('utf-8','replace')).hexdigest()[:12],
                # HyperDrive is cross-media canonical modulation rather than an
                # audio-only master effect, so its active math route belongs to
                # the identity whenever enabled.
                ("hd1:" +
                 f"{float(self.spin_hyperdrive_drive.value()) if hasattr(self, 'spin_hyperdrive_drive') else 0.5:.6f}:" +
                 f"{float(self.spin_hyperdrive_resonance.value()) if hasattr(self, 'spin_hyperdrive_resonance') else MEUM_MINUS_1:.6f}:" +
                 ("ot1" if operator_theory_enabled() else "ot0") + ":" +
                 ("tr1" if self._trigonometry_engine_enabled() else "tr0"))
                if self._hyperdrive_enabled() else "hd0",
                # Instrument Count is a rendering/repartition choice, not part
                # of the seed/composition identity.
            ]
            raw = "|".join(parts).encode("utf-8")
            return hashlib.sha256(raw).hexdigest()[:10]
        except Exception:
            return "----------"

    def _refresh_canonical_fingerprint(self):
        # ID_STABILITY_2026: never refresh while a unison/composition transaction
        # is mid-flight — intermediate rebuild state would flash as a shifting
        # track id. Defer one event-loop turn so the FINAL committed state lands.
        if getattr(self, "_unison_composition_guard", False):
            try:
                QTimer.singleShot(0, self._refresh_canonical_fingerprint)
            except Exception:
                pass
            return
        fp = self._canonical_fingerprint()
        # SCODE_FULL_ACCEL_V4: cache the committed fingerprint so the background
        # optimizer can classify host state without re-hashing the full canonical
        # project payload every 250 ms. The authoritative function above still
        # computes it at each actual composition commit/export boundary.
        self._scode_cached_fp = str(fp)
        label = getattr(self, "lbl_canonical_fp", None)
        if label is not None:
            text = f"ID: {fp}"
            if label.text() != text:
                label.setText(text)

    def _cache_realtime_control_state(self):
        """Snapshot UI/control values needed by the PortAudio callback.

        This runs on the Qt/control path only. The realtime callback consumes
        plain Python numbers so it never touches QWidget state or parses the
        seed script while the audio device is requesting a buffer.
        """
        try:
            self._rt_bpm = float(self.spin_bpm.value()) if hasattr(self, "spin_bpm") else 120.0
        except Exception:
            self._rt_bpm = 120.0
        try:
            self._rt_numeric_seed = float(self.get_numeric_seed())
        except Exception:
            self._rt_numeric_seed = 0.0
        try:
            self._rt_clip_ratio_pct = float(self.spin_clip_ratio.value()) if hasattr(self, "spin_clip_ratio") else float(getattr(self, "_rt_clip_ratio_pct", 50.0))
        except Exception:
            self._rt_clip_ratio_pct = 50.0
        # Cache the DJ row duration too.  The PortAudio callback must never call
        # _dj_row_samples(), because that helper intentionally consults Qt row
        # controls for offline/control-thread work.
        try:
            _sr = int(getattr(self, "play_sample_rate", TARGET_SAMPLE_RATE) or TARGET_SAMPLE_RATE)
            if hasattr(self, "spin_row_beats"):
                _beats = float(self.spin_row_beats.value())
            elif hasattr(self, "spin_playlist_beats"):
                _beats = float(self.spin_playlist_beats.value())
            else:
                _beats = 4.0
            self._rt_dj_row_samples = max(1, int(float(_sr) * (60.0 / positive_bpm(self._rt_bpm)) * max(0.002, min(64.0, _beats))))
        except Exception:
            self._rt_dj_row_samples = max(1, int(float(getattr(self, "play_sample_rate", TARGET_SAMPLE_RATE) or TARGET_SAMPLE_RATE) * 2.0))

    def _prepare_realtime_dj_cache(self):
        """Precompute carrier-energy steering outside the PortAudio callback.

        Imported media can be large, so RMS calculation belongs on the control
        thread at transport start/source changes.  Realtime processing then uses
        only scalar/index lookups with no waveform conversion, mean, sqrt, or Qt.
        """
        self._cache_realtime_control_state()
        # RAND_PARAM_GRAPH_2026: pre-evaluate its authored graph program at the
        # row/control lattice. PortAudio only performs an indexed scalar lookup.
        self._rt_live_dj_random_rows = None
        if bool(getattr(self, "live_dj_random", False)) and str(getattr(self, "live_dj_random_script", "") or "").strip():
            try:
                _events_n = len(getattr(self, "goava_note_events", []) or [])
                _rows_n = len(getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or [])
                _count = max(1, min(256, max(_events_n, _rows_n, 32)))
                _vals = np.zeros(_count, dtype=np.float32)
                for _ri in range(_count):
                    _tn = float(_ri) / float(max(1, _count - 1))
                    _gr = _evaluate_app_graph_script(
                        self, self.live_dj_random_script, _tn, t_norm=_tn,
                        slot=int(getattr(self, "_live_dj_pair_index", 0) or 0), row=_ri, sequence=1, step=_ri,
                        name="RAND PARAM", function_names=("global_script", "evaluate_wave", "evaluate", "main"),
                    )
                    _vals[_ri] = np.float32(np.clip(float(_gr.get("drive", _gr.get("wave", _gr.get("scalar", 0.0))) or 0.0), -4.0, 4.0))
                self._rt_live_dj_random_rows = _vals
            except Exception:
                self._rt_live_dj_random_rows = None
        self._rt_media_energy_rows = None
        self._rt_media_energy_wave_size = 0
        wave = getattr(self, "imported_waveform", None)
        if wave is None or not getattr(wave, "size", 0):
            return
        try:
            arr = np.asarray(wave, dtype=np.float32).reshape(-1)
            n = int(arr.size)
            if n <= 0:
                return
            row = max(1, int(getattr(self, "_rt_dj_row_samples", 1) or 1))
            count = (n + row - 1) // row
            energy = np.empty(count, dtype=np.float32)
            # One pass at transport/control time; no allocations occur from this
            # table in the audio callback.
            for i in range(count):
                seg = arr[i * row:min(n, (i + 1) * row)]
                if seg.size:
                    energy[i] = np.float32(min(1.0, max(0.0, float(np.sqrt(float(np.mean(seg.astype(np.float64) ** 2)))) * 6.0)))
                else:
                    energy[i] = np.float32(0.0)
            self._rt_media_energy_rows = energy
            self._rt_media_energy_wave_size = n
        except Exception:
            self._rt_media_energy_rows = None
            self._rt_media_energy_wave_size = 0

    def _on_global_base_frequency_changed(self, value):
        """Track global tuning through canonical lanes, patch previews and render state."""
        try:
            base=float(np.clip(float(value),0.0,50000.0))
            previous_base=float(getattr(self,"global_base_frequency_hz",432.0) or 432.0)
            # Preserve every authored identity's ratio, not its old absolute Hz,
            # so changing the global anchor transposes all engines coherently.
            for _state in (getattr(self,"instrument_param_state",{}) or {}).values():
                if not isinstance(_state,dict) or _state.get("frequency_identity_hz") in (None,""): continue
                if "frequency_identity_ratio" not in _state:
                    try:
                        _identity_base=float(_state.get("frequency_identity_base_hz",previous_base) or previous_base)
                        _state["frequency_identity_ratio"]=float(_state["frequency_identity_hz"])/_identity_base
                        _state["frequency_identity_base_hz"]=_identity_base
                    except (TypeError,ValueError,OverflowError,ZeroDivisionError):
                        _state["frequency_identity_ratio"]=1.0
                        _state["frequency_identity_base_hz"]=previous_base
                elif "frequency_identity_base_hz" not in _state:
                    # Legacy projects may already carry the ratio but not its
                    # explanatory denominator; record the currently active anchor.
                    _state["frequency_identity_base_hz"]=previous_base
            self.global_base_frequency_hz=base
            # Shared context events express pitch ratios from the same global anchor.
            try:
                from shared_synth_context import apply_base_frequency, empty_context
                ctx=getattr(self,"canonical_synth_context",None)
                if not isinstance(ctx,dict): ctx=empty_context()
                self.canonical_synth_context=apply_base_frequency(ctx,base)
                workbench=getattr(self,"media_workbench_state",None)
                if isinstance(workbench,dict): workbench["canonical_synth_context"]=self.canonical_synth_context
            except Exception as exc:
                print(f"[Base Frequency] shared context propagation skipped: {exc}")
            # Keep generated-but-not-user-locked harmonic anchors tied to the base.
            params=getattr(self,"instrument_param_state",{}) or {}
            generated=getattr(self,"instrument_param_generated",{}) or {}
            names=list(getattr(self,"instrument_names_48",[]) or [])
            for idx,name in enumerate(names):
                state=params.get(name)
                if not isinstance(state,dict) or state.get("harmonic_freq_user_locked",False): continue
                gen=generated.get(name,{}) if isinstance(generated,dict) else {}
                if "harmonic_freq" in gen and "harmonic_freq" in state:
                    try: state["harmonic_freq"]=float(_seed_to_fundamental_hz(_safe_int_seed(_stable_hash(str(name))),base,idx,0))
                    except Exception: state["harmonic_freq"]=base
                    gen["harmonic_freq"]=state["harmonic_freq"]
            self._graph_context_cache={}
            self._on_live_source_changed()
        except Exception as exc:
            print(f"[Base Frequency] propagation skipped: {exc}")

    def _timed_live_flush(self):
        # SEED_NONBLOCK_20261107: schedule the rebuild so the UI paints first.
        def _do():
            t0 = time.monotonic()
            try:
                try:
                    self._geo_buffer_store()
                except Exception:
                    pass
                self._flush_live_source_update()
            finally:
                dt = time.monotonic() - t0
                self._live_flush_cost = max(float(getattr(self, "_live_flush_cost", 0.0) or 0.0) * 0.5, dt)
        QTimer.singleShot(0, _do)

    def _on_live_source_changed(self, *args):
        job = getattr(self, "_canonical_commit", None)
        if job is not None and job.running:
            if self.sender() is getattr(self, "input_seed_val", None):
                job.request_restart()
                return
            # R32.5: edits made while a canonical commit runs used to be DROPPED, so the canonicals
            # did not follow project changes. Retry once the commit is done (coalesced).
            if not getattr(self, "_r32_change_pending", False):
                self._r32_change_pending = True
                def _retry():
                    self._r32_change_pending = False
                    try:
                        self._on_live_source_changed()
                    except Exception:
                        pass
                QTimer.singleShot(250, _retry)
            return
        self._last_live_source_change = time.monotonic()
        try:
            import seed_media_bridge as _smb
            self._seed_media_packet = _smb.identity_packet(self)
        except Exception:
            pass
        # CHANGE_POINT_20261107: remember where the edit landed so the next
        # buffer can rebuild from here instead of the whole mix.
        try:
            cur = int(getattr(self, "play_cursor", 0) or 0)
            sr = int(getattr(self, "play_sample_rate", 48000) or 48000)
            self._buffer_change_point = cur
            self._buffer_change_time = cur / float(sr) if sr else 0.0
        except Exception:
            self._buffer_change_point = 0
        # SEED_DEFER_20261107: coalesce rapid seed/canonical edits
        t = getattr(self, "_seed_defer_timer", None)
        if t is None:
            t = self._seed_defer_timer = QTimer(self)
            t.setSingleShot(True)
            t.timeout.connect(lambda: self._on_live_source_changed_impl())
        t.start(180)
        return

    def _on_live_source_changed_impl(self, *args):
        """Idle-debounce authoring changes into one canonical transaction.

        UI edits may emit dozens of signals while a slider is dragged or text is
        typed.  A one-shot scheduled from the *first* event still fires mid-edit,
        so active canonicals can repeatedly deep-copy/rebuild the playlist while
        the user is interacting.  Use one restartable single-shot timer instead:
        every new edit pushes the expensive deterministic rebuild to the end of
        the edit burst.  No canonical math or output identity is approximated.
        """
        self._graph_context_cache = {}
        # A worker (render/probe) may report a source change; the debounce timer
        # and every UI consequence must be created and run on the GUI thread.
        if hasattr(self, "_on_gui_thread") and not self._on_gui_thread():
            self._gui_refresh("live_source_changed", self._on_live_source_changed)
            return
        _now = time.monotonic()
        if _now - float(getattr(self, "_geo_store_at", 0.0) or 0.0) > 0.25:   # throttled; the flush stores again
            self._geo_store_at = _now
            try:
                self._geo_buffer_store()
            except Exception as _gs_exc:
                print(f"[Geometry] instance store skipped: {_gs_exc}")
        try:
            import canonical_mode as _cm
            _cm.refresh_controls(self)
        except Exception:
            pass
        try:
            import seed_media_bridge as _smb
            pkt = _smb.identity_packet(self)
            lab = getattr(self, "lbl_seed_fp", None)
            if lab is not None:
                lab.setText("seed " + str(pkt.get("fingerprint", ""))[:12])
        except Exception:
            pass
        try:
            self._schedule_canonical_label_refresh()
        except Exception:
            pass
        if getattr(self, "_composition_generation_guard", False):
            return
        self._live_source_update_pending = True
        try:
            timer = getattr(self, "_canonical_authoring_debounce_timer", None)
            if timer is None:
                timer = QTimer(self)
                timer.setSingleShot(True)
                timer.timeout.connect(self._timed_live_flush)
                self._canonical_authoring_debounce_timer = timer
            # 140 ms feels immediate when a rebuild is cheap; when canonicals make it expensive
            # the wait grows to 1.5× the measured rebuild time, so a click burst is one rebuild.
            timer.start(self._adaptive_edit_delay_ms())
        except Exception:
            # Headless/minimal Qt fallback retains the prior safe behavior.
            if not getattr(self, "_live_source_fallback_scheduled", False):
                self._live_source_fallback_scheduled = True
                def _fallback_flush():
                    self._live_source_fallback_scheduled = False
                    self._flush_live_source_update()
                QTimer.singleShot(140, _fallback_flush)

        # =========================================================================

    def _ensure_perfect_unison(self):
        """
        Perfect unison system: All active engines contribute deterministically.
        Re/write is consistent regardless of activation order or history.

        UNISON DATA-FLOW CONTRACT (modern version):
        • The active engine mask is exactly the live toggle buttons (GOAVA,
          randomizer, phase-lock, euclidean live-lock, seeded live-randomizer,
          and deterministic Fractal Seed).
        • Mask + seed + BPM + base frequency + playlist + per-sequence panels +
          global-algo make up the canonical identity. The document written by
          `_project_snapshot` (save/export) is the SAME map this engine reads,
          and `_apply_project_snapshot` (load) restores every one of those
          inputs, so a loaded project re-derives the identical composition.
        • The three master effects (Fractallizer, EQR, PKP) are STRICTLY
          excluded here — they apply on the final master bus in
          `_render_mixdown_buffer`, after this engine commits, so effect
          sliders can never factor into canonical identity.
        • Step 5 re-refreshes the fingerprint so the HUD label always shows
          the state the export/video-game classifiers will read.
        """
        if getattr(self, "_unison_composition_guard", False):
            return
        # SCODE_FULL_ACCEL_V4: number/logic cross-cast work claim. Repeated UI
        # signals that describe the exact same canonical inputs no longer rebuild
        # 1..1024 playlist rows, deep-copy sequence banks, and repaint every
        # canonical candidate. sCode is consulted synchronously here (UI/control
        # path only; never the realtime audio callback) before the expensive work.
        _opt = getattr(self, "_scode_optimizer", None)
        # SCODE_CLAIM_SELF_HEAL_20261102: a dedup claim only means "this identity ran", not "its output still
        # exists". If engines are on but no canonical sequence is present (fresh launch, project load/clear,
        # failed earlier run), the claim is stale: drop it and run.
        try:
            _banks_now = getattr(self, "instrument_sequence_banks", {}) or {}
            _have_canon = any(isinstance(m, dict) and str(m.get("canonical_owner", "")).startswith("canonical:")
                              for b in _banks_now.values() for m in (b or {}).values())
            _stale_claim = bool(self._active_engine_sources()) and not _have_canon
        except Exception:
            _stale_claim = False
        if _opt is not None and _stale_claim:
            try: _opt.invalidate_work("canonical")
            except Exception: pass
        if _opt is not None and not bool(getattr(self, "_scode_force_canonical", False)):
            _plan = _opt.request_host_plan(self)
            if not _stale_claim and not bool(_plan.get("run_canonical", 1)):
                return
            if not _opt.claim_host_work(self, "canonical", force=_stale_claim):
                return

        active_engines = self._get_active_engine_set()
        _prev_active = frozenset(getattr(self, "_canonical_last_active_set", frozenset()) or ())

        if not active_engines:
            # No engines active: restore user-owned core, then discard every
            # canonical projection/ownership store.  The restored state becomes
            # the next cycle's baseline so repeated sessions cannot evolve.
            self._reset_to_clean_baseline()
            self._clear_canonical_global_algo_projection()
            self._canonical_last_active_set = frozenset()
            self._canonical_user_rows_snapshot = copy.deepcopy(getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or [])
            self._canonical_pattern_user_store = copy.deepcopy(getattr(self, "instrument_sequencer_memory", {}) or {})
            self._canonical_panels_user_store = copy.deepcopy(getattr(self, "instrument_sequence_banks", {}) or {})
            self._canonical_macro_user_store = copy.deepcopy(getattr(self, "instrument_param_state", {}) or {})
            return

        if not _prev_active:
            # First engine entering from a fully-off state: freeze the exact live
            # userdata once.  Mixed engine changes reuse this immutable baseline.
            self._canonical_user_rows_snapshot = copy.deepcopy(getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or [])
            self._canonical_pattern_user_store = copy.deepcopy(getattr(self, "instrument_sequencer_memory", {}) or {})
            self._canonical_panels_user_store = copy.deepcopy(getattr(self, "instrument_sequence_banks", {}) or {})
            self._canonical_macro_user_store = copy.deepcopy(getattr(self, "instrument_param_state", {}) or {})

        # Unified composition guard prevents re-entrancy
        if getattr(self, "_unison_composition_guard", False):
            return

        self._unison_composition_guard = True

        try:
            # Step 0: discard stale projections and restore the pre-canonical
            # core (order/history independent).
            self._clear_canonical_global_algo_projection()
            self._reset_canonical_engine_derived_state()

            # Step 1: Establish clean baseline (history-free)
            self._establish_clean_baseline()

            # Step 2: Apply all active engines in deterministic order.
            # Default ON uses the composite dispatcher; OFF retains the original
            # per-engine dispatch path for immediate parity/A-B fallback.
            if self._meum_engine_simplification_enabled():
                self._apply_active_engines_meum_composite(active_engines)
            else:
                for engine in sorted(active_engines):
                    self._apply_engine_deterministically(engine)

            # Step 3: Final reconciliation ensures perfect unison
            self._final_unison_reconciliation()

            # Step 3b: Canonical unison owns the Algorithm Bay projection.
            # User edits are always userdata; the engine may naturally superwrite
            # this projection on every canonical transaction.
            self._canonical_superwrite_global_algo()

            QTimer.singleShot(0, self._refresh_canonical_explain)
            # Step 3c: the user's applied Global/Local Algorithm is userdata —
            # the canonical restore above must not strip its overlay.
            try:
                _ugas = getattr(self, "global_algo_state", {}) or {}
                if bool(_ugas.get("apply_enabled", False)):
                    for _kind in ("script", "domain", "wire"):
                        if _ugas.get(_kind):
                            self._apply_global_algo_to_ensemble(_kind)
                if getattr(self, "local_algo_bays", None):
                    self._apply_local_bays()
            except Exception as _ua_exc:
                print(f"[Canonical] user algo overlay re-assert: {_ua_exc}")

            # Step 4: Sync UI to match the deterministic state
            self._sync_ui_to_unison_state()

            # Step 4b: deterministic re-derive of the per-row context columns
            # (calculated_context / live_parametrics) from the canonical stores.
            self._refresh_canonical_derived_columns()

            # Step 5: Refresh the order-independent canonical identity
            try:
                self._refresh_canonical_fingerprint()
            except Exception:
                pass
            self._canonical_last_active_set = frozenset(active_engines)

        finally:
            self._unison_composition_guard = False
            self._canonical_prepared_sequence_plan = None

    def _effective_global_algo_state(self):
        """The Global / Local Algorithm that is applied is ALWAYS the user's.

        GROOVEBOX_R23R_CANONICAL_READ_ONLY_ALGO_20261103: canonical engines can
        no longer substitute their own script/domain/wire for the user's
        Algorithm Bay. They READ it (scope, targets, mix, apply state, heuristic
        modes) and write a separate parallel layer
        (``_canonical_global_algo_projection``, see _canonical_parallel_algo_for)
        that runs alongside the synths, never in place of the user's settings.
        """
        gas = getattr(self, "global_algo_state", None)
        return gas if isinstance(gas, dict) else {}

    def _canonical_parallel_algo_for(self, instrument_name, sequence_id=None):
        """(script, mix) of the canonical parallel layer for one synth, or (None, 0).

        Decided from the user's global settings (read-only):
          • user algo applied GLOBAL → canonical fix runs on every synth at a
            reduced mix that leaves room for the user's algo: 0.5·m·(1 − user_mix)
          • user algo applied LOCAL → full canonical mix on the synths the user
            did not target, reduced mix on the targeted ones
          • user algo not applied → full canonical mix everywhere
        """
        proj = getattr(self, "_canonical_global_algo_projection", None)
        if not isinstance(proj, dict) or not str(proj.get("script") or "").strip():
            return None, 0.0
        try:
            if not self._get_active_engine_set():
                return None, 0.0
        except Exception:
            return None, 0.0
        m = float(np.clip((proj.get("params") or {}).get("mix", 0.35), 0.0, 1.0))
        # Lead synth: full carrier weight (mix → 1.0); ensemble instruments: anarchy
        # mode at 60% of base mix, so the lead's wavetable dominates the carrier.
        _lead = str(proj.get("canon_lead") or "")
        if _lead:
            if str(instrument_name) == _lead:
                m = min(1.0, m * 2.5)   # lead synth: boosted carrier mix
            else:
                m = m * 0.6             # ensemble anarchy: subordinate mix
        # The canonical fix is one equal contender in the per-value average
        # with the user's global/local algos (it reads them, never edits them).
        return str(proj.get("script")), float(m)

    def _clear_canonical_global_algo_projection(self):
        """Discard all canonical Algorithm-Bay output without touching userdata."""
        self._canonical_global_algo_projection = None

    def _canonical_superwrite_global_algo(self):
        """Derive an ephemeral Global Algorithm projection from canonical unison.

        Ownership rule: the user-authored ``global_algo_state`` is read-only to
        this operation.  Canonical output lives in
        ``_canonical_global_algo_projection`` and is tagged canonical-owned.
        Repeated toggles therefore re-derive from the same user baseline instead
        of feeding a previous projection back into the next transaction.
        """
        try:
            user_gas = getattr(self, "global_algo_state", None)
            if not isinstance(user_gas, dict):
                user_gas = {}
            gas = copy.deepcopy(user_gas)
            seed = _safe_int_seed(self.get_numeric_seed())
            active = sorted(self._get_active_engine_set())
            pl = getattr(self, "master_playlist_data", None) or []
            n = len(pl)
            rows_sig = []
            for i, e in enumerate(pl[:64]):
                if not isinstance(e, dict):
                    continue
                rows_sig.append((i, str(e.get("operator", "")),
                                 round(float(e.get("time_offset", 0.0) or 0.0), 6),
                                 round(float(e.get("velocity", 0.0) or 0.0), 6)))
            sig = _stable_hash(repr((seed, tuple(active), n, tuple(rows_sig)))) & 0xFFFFFFFF
            phase = (sig % 1000003) / 1000003.0
            engine_expr = " + ".join(active) if active else "identity"
            gas["script"] = (
                "# Canonical Unison Projection\n"
                f"# engines={engine_expr}\n"
                f"# composition={sig:08x}\n"
                "def global_script(t, name, i):\n"
                f"    return ot_sin_vec_equiv((t + {phase:.9f}) * MEUM) * ot_cos_vec_equiv((i + 1) * {0.125 + 0.5*phase:.9f})\n"
            )
            gas["domain"] = (
                'equation = "sin((t + %.9f) * MEUM) + cos(x * %.9f)"\n'
                % (phase, 0.25 + 0.75 * phase)
            )
            # Lead synth: live attr → meta-store fallback → None
            _canon_lead_name = None
            try:
                import canon_lead as _cl_csu
                _canon_lead_name = _cl_csu.get_lead(self)
            except Exception:
                pass
            if not _canon_lead_name:
                try:
                    _canon_lead_name = (
                        (getattr(self, "_canonical_macro_user_store", None) or {})
                        .get("__meta__", {}).get("canon_lead")
                    )
                except Exception:
                    pass

            names = list(getattr(self, "instrument_names_48", []) or [])
            if names:
                a = int(sig % len(names)); b = int((sig // max(1, len(names))) % len(names))
                if a == b and len(names) > 1:
                    b = (b + 1) % len(names)
                # Lead synth is always the canonical wire SOURCE when set
                if _canon_lead_name and _canon_lead_name in names:
                    a = names.index(_canon_lead_name)
                    b = int((sig // max(1, len(names))) % len(names))
                    if a == b and len(names) > 1:
                        b = (b + 1) % len(names)
                _wire_weight = 1.0 if _canon_lead_name and _canon_lead_name in names else round(0.25 + 0.65 * phase, 6)
                gas["wire"] = [{
                    "source": names[a], "target": names[b],
                    "weight": _wire_weight,
                    "detector": "harmonic",
                    "question": "How should canonical unison redistribute harmonic detail?",
                    "subject": "canonical_unison",
                    "origin": "canonical_unison",
                    "user_defined": False,
                    "user_data": False,
                    "canonical_superwrite": True,
                    "canonical_owner": "unison",
                    "apply_enabled": bool(user_gas.get("apply_enabled", False)),
                }]
            else:
                gas["wire"] = []
            gas.setdefault("params", {})
            gas["params"]["mix"] = round(0.35 + 0.65 * phase, 6)
            gas["params"]["script_amount"] = 1.0
            gas["params"]["domain_amount"] = 1.0
            gas["params"]["wire_amount"] = 1.0
            for _k in GLOBAL_ALGO_EXTRA_KINDS:
                # Canonical unison writes its own deterministic drive for each new kind; the
                # user's authored text is never read back from this projection.
                gas[_k] = (f"# Canonical Unison {_k} projection\n"
                           "def global_script(t, name, i):\n"
                           f"    return {{'scalar': 0.35 * ot_sin_vec_equiv((t + {phase:.9f}) * MEUM * {1 + GLOBAL_ALGO_EXTRA_KINDS.index(_k)})}}\n")
                gas["params"][_k + "_amount"] = 1.0
                gas["params"].setdefault("enable_" + _k, True)
            gas["user_data"] = False
            gas["user_defined"] = False
            gas["canonical_superwrite"] = True
            gas["canonical_owner"] = "unison"
            # Parallel layer: what it read from the user's (read-only) settings.
            gas["parallel"] = True
            gas["reads"] = {
                "user_scope": str(user_gas.get("scope", "global")),
                "user_applied": bool(user_gas.get("apply_enabled", False)),
                "user_mix": float((user_gas.get("params") or {}).get("mix", 0.35) or 0.35),
                "user_targets": copy.deepcopy(user_gas.get("local_targets") or []),
                "heuristic_series_lock": bool(getattr(self, "heuristic_series_lock", False)),
                "heuristic_modes": dict(getattr(self, "heuristic_instrument_modes", {}) or {}),
            }
            gas.pop("protectable_userdata", None)
            # Carry lead name into the projection for per-instrument mix scaling
            if _canon_lead_name:
                gas["canon_lead"] = str(_canon_lead_name)
            self._canonical_global_algo_projection = gas
        except Exception as exc:
            self._canonical_global_algo_projection = None
            print(f"[Canonical] Global Algorithm projection skipped: {exc}")

    def _get_active_engine_set(self):
        """Return all active deterministic canonical writers, including Fractal Seed."""
        return set(self._active_engine_sources())

    def _reset_canonical_engine_derived_state(self):
        """Restore the pre-canonical core so every transaction re-derives identically.

        ORDER-INDEPENDENCE: the live panel stores (scripts, patch edges, generated
        params, sequence panels) accumulate engine residue across toggles.  Three
        residues are history-order-dependent and make the SAME final active set
        produce DIFFERENT canonical content depending on activation order:
          • instrument_scripts — engine ``# --- GENERATED ... ---`` blocks are only
            appended once each, so the assembled script string's block order mirrors
            activation history.
          • patch_connections — generated edges (origin=generated_*) are never
            cleaned, so the edge list's order/staleness reflects history.
          • sequence ``panels`` — engine_contributions / engine_source / master_blended
            markers plus a merged ``synth`` accumulate over transactions.
        This helper strips exactly that engine residue (never user material) so each
        transaction starts from a fresh, identical pre-canonical core and the sorted
        engine write becomes a pure function of the FINAL active toggle set.
        """
        import re as _re
        # Pristine user-row snapshot: captured on the very first canonical
        # transaction (before any engine pass can paint user-owned cells such as
        # velocity). Restored at every reset so row_velocity and user-authored
        # columns stay order-independent at freeze time.
        if not isinstance(getattr(self, "_canonical_user_rows_snapshot", None), list):
            self._canonical_user_rows_snapshot = copy.deepcopy(
                getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or []
            )
        # PATTERN_INDEP_2026: the sequencer pattern memory is canonical output.
        # Engines mutate it during their pass, so the frozen canonical identity
        # must never see first-writer pattern residue. Capture the pristine boot
        # pattern (post-seed) once; restore it every reset so the fixed-order
        # deterministic engine pass re-derives it exactly.
        if not isinstance(getattr(self, "_canonical_pattern_user_store", None), dict):
            self._canonical_pattern_user_store = copy.deepcopy(
                getattr(self, "instrument_sequencer_memory", None) or {})
        # PANELS_INDEP_2026: instrument_sequence_banks (per-sequence panels)
        # are written by every unison pass and read back by the deterministic
        # engine pass (euclidean/seeded blends). Restore the pristine boot banks
        # at every reset so panel content is a pure function of user material.
        if not isinstance(getattr(self, "_canonical_panels_user_store", None), dict):
            self._canonical_panels_user_store = copy.deepcopy(
                getattr(self, "instrument_sequence_banks", None) or {})
        strip_pat = _re.compile(r"# --- GENERATED [^\n]*---\n(?:generated_[^\n]*\n?)*")
        seeded_block_pat = _re.compile(
            r"# Seeded Geometric Resonance Script[^\n]*\n"
            r"(?:[^\n]*\n){0,6}"
            r"def evaluate_wave\([^\n]*\):\n"
            r"(?:[^\n]*\n){0,6}"
        )

        scripts = getattr(self, "instrument_scripts", None)
        if isinstance(scripts, dict):
            for name, body in list(scripts.items()):
                if not isinstance(body, str):
                    continue
                cleaned = seeded_block_pat.sub("", body)
                cleaned = strip_pat.sub("", cleaned)
                # Generated engine params are sometimes appended to scripts without
                # any marker line; remove any such engine lines regardless of header.
                cleaned = "\n".join(
                    ln for ln in cleaned.split("\n")
                    if not ln.startswith("generated_")
                )
                cleaned = _re.sub(r"\n{3,}", "\n\n", cleaned).strip("\n")
                if not cleaned:
                    # Fully engine-rewritten script: fall back to the stock
                    # workspace template so the canonical core stays order-free.
                    try:
                        cleaned = (
                            f"# Script workspace for {name} based on operator rules\n"
                            f"def evaluate_wave(x, y, z):\n"
                            f"    return ot_sin_vec_equiv(x * {1 + int(identity_unit(name, 'default_script_k') * 12)}.0) * ot_cos_vec_equiv(y) - z"
                        )
                    except Exception:
                        cleaned = f"# Script workspace for {name} based on operator rules"
                scripts[name] = cleaned if cleaned else ""

        pc = getattr(self, "patch_connections", None)
        if pc is not None:
            self.patch_connections = [
                c for c in pc if not (
                    isinstance(c, dict)
                    and (
                        str(c.get("origin", "")).startswith("generated_")
                        or "optimizer" in str(c.get("origin", ""))
                        or str(c.get("origin", "")) == "additive_optimizer"
                    )
                )
            ]

        if not isinstance(getattr(self, "instrument_param_generated", None), dict):
            self.instrument_param_generated = {}
        self.instrument_param_generated = {}

        _banks_snap = getattr(self, "_canonical_panels_user_store", None)
        banks = getattr(self, "instrument_sequence_banks", {}) or {}
        if isinstance(_banks_snap, dict):
            for _bname, _bank in list(banks.items()):
                if _bname in _banks_snap:
                    banks[_bname] = copy.deepcopy(_banks_snap[_bname])
        else:
            for name, bank in banks.items():
                if not isinstance(bank, dict):
                    continue
                for mem in bank.values():
                    if not isinstance(mem, dict):
                        continue
                    panels = mem.get("panels")
                    if not isinstance(panels, dict):
                        continue
                    engine_marked = panels.get("engine_source") is not None or panels.get("master_blended") is not None
                    panels.pop("engine_contributions", None)
                    panels.pop("engine_source", None)
                    panels.pop("master_blended", None)
                    if engine_marked:
                        panels["synth"] = {}
                        panels["script"] = ""
                        panels["domain"] = {}
                        panels["patch"] = []

        # Reset engine-authored EQ-domain partitions back to user-defined only.
        # Generated domains are rebuilt identically per engine in the sorted
        # canonical pass; leaving them here makes the domain context (0.16 of the
        # feature score) depend on engagement order.
        dom_engine = getattr(self, "domain_eq_engine", None)
        if dom_engine is not None and hasattr(dom_engine, "domains"):
            try:
                dom_engine.domains = [
                    d for d in (dom_engine.domains or [])
                    if isinstance(d, dict) and (d.get("user_defined", True) or bool(d.get("user_owned")))
                ]
            except Exception:
                pass

        # Stale per-row derived columns carry the ORDER-FIRST-WRITER residue of the
        # pre-canonical incremental writers (calculated_context / live_parametrics /
        # engine source markers). Clear them so the unison rebuild re-derives every
        # cell strictly from canonical stores.
        for _e in (getattr(self, "master_playlist_data", None) or []):
            if not isinstance(_e, dict):
                continue
            for _k in ("calculated_context", "live_parametrics", "velocity_source",
                       "generated_source", "generated_sources", "generated_by_engine",
                       "combined_time_offsets", "engine_contributions"):
                _e.pop(_k, None)

        # Restore user-authored user-columns (velocity is the canonical one the
        # engine pass paints) from the pristine snapshot so the freeze — and the
        # audible downstream — cannot see order-dependent paint residue.
        _row_snap = getattr(self, "_canonical_user_rows_snapshot", None)
        if isinstance(_row_snap, list):
            _pl = getattr(self, "master_playlist_data", None) or []
            for r, _e in enumerate(_pl):
                if not isinstance(_e, dict) or not _e.get("user_owned"):
                    continue
                _src = _row_snap[r] if r < len(_row_snap) else None
                if not isinstance(_src, dict):
                    continue
                for _col in ("velocity", "operator", "question", "answer", "hint",
                             "operators", "operators_csv", "target_value",
                             "formula_row", "domain_spec", "script_spec"):
                    if _col in _src:
                        _e[_col] = copy.deepcopy(_src[_col])
                    elif _col == "operator":
                        # Keep engine names out of user-owned rows. A pristine
                        # user row states no operator: default it to the user's
                        # own instance operator so generic fillers never paint
                        # an instrument name here.
                        _ui = _e.get("user_instances") or []
                        if _ui:
                            _u0 = _ui[0]
                            _e["operator"] = str(_u0.get("operator", "") if isinstance(_u0, dict) else _u0)
                        else:
                            _e["operator"] = ""
                    else:
                        # Pristine user rows carry no engine-painted cells; drop
                        # whatever the pass wrote into a user-owned column.
                        _e.pop(_col, None)

        # Restore the pristine pattern memory from the boot snapshot so the
        # deterministic engine pass starts from identical sequencer slates every
        # unison. Keys the user has since added (new instruments) are kept.
        _pat_snap = getattr(self, "_canonical_pattern_user_store", None)
        if isinstance(_pat_snap, dict):
            _mem = getattr(self, "instrument_sequencer_memory", None)
            if isinstance(_mem, dict):
                _ordered = list(_mem.keys())
                for _k in _ordered:
                    if _k not in _pat_snap:
                        continue
                    _mem[_k] = copy.deepcopy(_pat_snap[_k])

        # ORDER-INDEPENDENCE_2026: the master macro store must return to the
        # pre-canonical core BEFORE the freeze. Engines only ever setdefault the
        # deterministic canonical_macro_defaults values (and always overwrite
        # meum_modulation) plus arbitrary residual numerics (harmonic_freq /
        # tuning_ratio); unless the user authored a key at the pristine
        # pre-first-engine state, reconcile it away so the frozen synth blob and
        # downstream live_parametrics cannot see first-writer residue.
        if not isinstance(getattr(self, "_canonical_macro_user_store", None), dict):
            self._canonical_macro_user_store = copy.deepcopy(getattr(self, "instrument_param_state", {}) or {})
        cc_pre = getattr(self, "_canonical_ctx_cache", {}) or {}
        _mus_pre = getattr(self, "_canonical_macro_user_store", {}) or {}
        for i, name in enumerate(list(getattr(self, "instrument_names_48", []) or [])):
            _u = (getattr(self, "instrument_param_state", None) or {}).get(name)
            if not isinstance(_u, dict):
                continue
            _user_macros_p = _mus_pre.get(name)
            if not isinstance(_user_macros_p, dict):
                _user_macros_p = {}
            _ctx_pre = float(cc_pre.get(name, 0.5)) if isinstance(cc_pre, dict) else 0.5
            _defaults_pre = canonical_macro_defaults(_ctx_pre, i)
            for _k, _dv in _defaults_pre.items():
                try:
                    _uv = _user_macros_p.get(_k)
                    if _uv is not None:
                        _u[_k] = float(_uv)
                    else:
                        _u.pop(_k, None)
                except Exception:
                    _u.pop(_k, None)
            for _k in list(_u.keys()):
                if _k == "meum_modulation":
                    _u.pop(_k, None)
                    continue
                _cur = _u.get(_k)
                if isinstance(_cur, bool) or not isinstance(_cur, (int, float)):
                    # Engine residue is numeric only. Structured / text state (the geo instance with
                    # its ball lock and drawn cycle, waveform, EQ scope…) is user data: popping it here
                    # silently reverted user edits made after the baseline was frozen.
                    continue
                _rkv = _user_macros_p.get(_k)
                if _rkv is not None:
                    try:
                        _u[_k] = float(_rkv)
                    except Exception:
                        pass
                else:
                    _u.pop(_k, None)

        # Freeze the numeric-context cache against an order-independent USER key.
        # Engine writes never enter the key (scripts/patch are already stripped;
        # roster/seed/length knobs are user-owned), so the same user program yields
        # the same ctx for the SAME final active set no matter the activation order.
        key = self._canonical_program_key()
        if (getattr(self, "_canonical_ctx_key", None) != key) or not isinstance(getattr(self, "_canonical_ctx_cache", None), dict):
            # Present an EMPTY cache while rebuilding so _contextual_numerology's
            # early-return cannot feed stale frozen values back into the freeze.
            self._canonical_ctx_cache = {}
            cache = {}
            roste = list(getattr(self, "instrument_names_48", []) or [])
            self._canonical_freeze_ctx = True
            try:
                for i, name in enumerate(roste):
                    try:
                        cache[name] = float(self._contextual_numerology(name, i, i))
                    except Exception:
                        cache[name] = 0.5
            finally:
                self._canonical_freeze_ctx = False
            self._canonical_ctx_cache = cache
            self._canonical_ctx_key = key

    def _canonical_program_key(self):
        """Hash of pre-canonical USER material only — order/history independent."""
        import hashlib, json as _json
        seed = ""
        if hasattr(self, "input_seed_val") and self.input_seed_val is not None:
            seed = self.input_seed_val.toPlainText() if hasattr(self.input_seed_val, "toPlainText") else str(getattr(self.input_seed_val, "text", lambda: "")())
        parts = [
            seed,
            f"{float(self.spin_bpm.value()) if hasattr(self, 'spin_bpm') else 120:.4f}",
            f"{float(self.spin_base_frequency.value()) if hasattr(self, 'spin_base_frequency') else 432:.6f}",
            f"{int(self.spin_seq_length.value()) if hasattr(self, 'spin_seq_length') else DEFAULT_SEQUENCE_LENGTH}",
            f"{int(self.spin_playlist_length.value()) if hasattr(self, 'spin_playlist_length') else DEFAULT_PLAYLIST_ROWS}",
            f"{float(self.spin_row_beats.value()) if hasattr(self, 'spin_row_beats') else 4.0:.3f}",
            _json.dumps(list(getattr(self, "instrument_names_48", []) or []), sort_keys=True),
            "|".join(sorted((getattr(self, "instrument_scripts", {}) or {}).values()) or []),
            _json.dumps(sorted([
                (str(c.get("source", "")), str(c.get("target", "")))
                for c in (getattr(self, "patch_connections", []) or []) if isinstance(c, dict)
            ])),
            _json.dumps([str(e.get("operator", "")) for e in (getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or [])
                         if isinstance(e, dict) and e.get("user_owned")], sort_keys=True),
        ]
        return hashlib.sha256("|".join(parts).encode("utf-8", "replace")).hexdigest()[:16]

    def _establish_clean_baseline(self):
        """Create history-free baseline for perfect unison"""
        # Clear any previous engine-generated content
        self._deactivate_all_engine_content()

        # Reset composition counters + live mod baselines so retoggle is identical
        self._composition_generation_counter = 0
        self._live_offset_baselines = {}
        self._live_param_baselines = {}
        if hasattr(self, "_unison_engine_signatures"):
            self._unison_engine_signatures.clear()

        # Store current user state for restoration
        self._baseline_user_state = self._capture_user_state()

    def _deactivate_all_engine_content(self):
        """Clean up all engine-generated content consistently"""
        engines = ["goava", "euclidean", "randomizer", "phase_lock", "seeded", "fractal_seed"]

        for engine in engines:
            self._deactivate_engine_generated_content(
                source_label=engine.capitalize(),
                source_key=engine
            )

        # Clear live engine signatures
        if hasattr(self, "_live_engine_signatures"):
            self._live_engine_signatures.clear()

    def _capture_user_state(self):
        """Capture current user state for restoration"""
        state = {}

        # Capture playlist data
        if hasattr(self, "master_playlist_data"):
            state["master_playlist_data"] = _fast_copy(self.master_playlist_data)

        # Capture sequencer memory
        if hasattr(self, "instrument_sequencer_memory"):
            state["instrument_sequencer_memory"] = copy.deepcopy(self.instrument_sequencer_memory)

        # Capture sequence banks
        if hasattr(self, "instrument_sequence_banks"):
            state["instrument_sequence_banks"] = copy.deepcopy(self.instrument_sequence_banks)

        return state

    def _trig_engine_transform(self, op, x, *args, **kwargs):
        """Central A/B dispatch point for supported trigonometric transforms.

        ON prefers the project's OT/Meum trigonometric implementation when a
        matching helper exists. OFF uses NumPy/libm baseline operations.
        Unsupported operations always fall back to the baseline.
        """
        enabled = self._trigonometry_engine_enabled()
        if enabled:
            # Authoritative forward trig route: cyclic isn -> isx/isy.
            # Do not delegate to dynamic helpers that could reintroduce libm or
            # the legacy 2*func(x/2) equivalence.
            if op == "sin":
                return series_book_isy(x)
            if op == "cos":
                return series_book_isx(x)
            if op == "tan":
                return series_book_tan(x)
        else:
            if op == "sin":
                return np.sin(x)
            if op == "cos":
                return np.cos(x)
            if op == "tan":
                return np.tan(x)
        raise ValueError(f"unsupported trig op: {op}")

    def _canonical_engine_lane(self, engine: str):
        """Return one persistent single-worker lane per public canonical engine.

        Pure engine preparation may run concurrently. Canonical document writes
        still commit in sorted order on the control thread so activation order,
        replay identity and user-data protection remain deterministic.
        """
        lanes=getattr(self,'_canonical_engine_thread_lanes',None)
        if not isinstance(lanes,dict):
            lanes={}
            self._canonical_engine_thread_lanes=lanes
        key=str(engine)
        lane=lanes.get(key)
        if lane is None:
            if _thread_budget is not None:
                lane = _thread_budget.make_lane(f"canonical-engine-{key[:24]}", max_workers=1, max_pending=32)
            else:
                lane = ThreadPoolExecutor(max_workers=1, thread_name_prefix=f"canon-{key[:8]}")
            lanes[key]=lane
        return lane

    @staticmethod
    def _prepare_canonical_engine_rng(engine: str, src_seed: int):
        eng_h=int(_safe_int_seed(_stable_hash(str(engine)) & 0x7FFFFFFF))
        rng=np.random.default_rng((_safe_int_seed(src_seed) ^ eng_h) & 0x7FFFFFFF)
        return int(_safe_int_seed(src_seed)), rng

    def _prepare_active_canonical_engines_threaded(self, active_engines):
        """Prepare tiny RNG descriptors without GUI-to-worker round trips.

        These are private generators, not document snapshots. Heavy pure jobs
        can still use the bounded per-engine lanes; a hash/RNG constructor does
        not justify submission, blocking waits and a second worker deepcopy.
        """
        out={}
        for engine in sorted(active_engines):
            src_seed=self._canonical_seed_for_source(engine)
            out[engine]=self._prepare_canonical_engine_rng(engine,src_seed)
        return out

    def _apply_engine_with_shared_context(self, engine, seed, prepared=None):
        """Apply one canonical; its pure preparation may arrive from its own lane."""
        if prepared is None:
            src_seed = self._canonical_seed_for_source(engine)
            eng_h = int(_safe_int_seed(_stable_hash(str(engine)) & 0x7FFFFFFF))
            rng = np.random.default_rng((_safe_int_seed(src_seed) ^ eng_h) & 0x7FFFFFFF)
        else:
            src_seed, rng = prepared
        self._active_engine_write_source = engine
        try:
            if engine == "goava":
                self._apply_goava_deterministically(seed, rng)
            elif engine == "randomizer":
                self._apply_randomizer_deterministically(src_seed, rng)
            elif engine == "phase_lock":
                self._apply_phase_lock_deterministically(seed, rng)
            elif engine == "euclidean":
                self._apply_euclidean_deterministically(seed, rng)
            elif engine == "seeded":
                self._apply_seeded_deterministically(seed, rng)
            elif engine == "fractal_seed":
                # The pure event plan is committed by _canonical_sequence_reconcile;
                # do not route it through any stochastic/live randomizer writer.
                pass
            try:
                if hasattr(self, "_engine_write_sequence_panels"):
                    self._engine_write_sequence_panels(source=str(engine))
            except Exception as _pe:
                print(f"[Unison] sequence panels ({engine}): {_pe}")
            self._live_offset_baselines = {}
            self._live_param_baselines = {}
            self._store_engine_signature(engine, int(_safe_int_seed(src_seed)))
        finally:
            self._active_engine_write_source = None

    def _apply_engine_deterministically(self, engine):
        """Original per-engine dispatcher, retained for Meum simplification OFF."""
        seed = _safe_int_seed(self.get_numeric_seed())
        return self._apply_engine_with_shared_context(engine, seed)

    def _apply_active_engines_meum_composite(self, active_engines):
        """Composite canonical dispatcher used when 'Engines simplified by Meum' is ON.

        Provable equivalence boundary:
        - active engine set is sorted exactly as before;
        - the canonical seed is computed once instead of once per engine;
        - each unchanged engine receives the identical per-engine RNG seed;
        - panel writes/signatures/baseline resets remain in the same order.

        Therefore this is a code-path simplification, not a replacement of the
        SEEDED/RAND/LOCK/EUCLIDEAN/GOAVA canonical engines. Euclidean is a full
        canonical vote because it can reshape both generated and protected user material.
        """
        seed = _safe_int_seed(self.get_numeric_seed())
        prepared=self._prepare_active_canonical_engines_threaded(active_engines)
        for engine in sorted(active_engines):
            self._apply_engine_with_shared_context(engine, seed, prepared=prepared.get(engine))


    def _apply_goava_deterministically(self, seed, rng):
        """Deterministic GOAVA application"""
        self.goava_note_events = self._build_goava_composition()
        self._apply_goava_to_canonical_playlist()

    def _apply_randomizer_deterministically(self, seed, rng):
        """Replayable RAND generated from the captured OS-entropy token."""
        level = self._canonical_level("randomizer")
        if level <= 0.0:
            return
        # Do not call the seeded randomizer here: RAND must not silently fall back
        # to the user's project seed. Use the explicit RNG throughout its writer path.
        try:
            self._mark_generated_synth_context(source="randomizer", rng=rng)
        except Exception:
            pass
        try:
            self._engines_write_automation_lanes(source="randomizer")
        except Exception:
            pass
        if hasattr(self, "_canonical_playlist_paint"):
            self._canonical_playlist_paint(rng=rng, mode="randomizer", strength=0.55 * level)

    def _apply_phase_lock_deterministically(self, seed, rng):
        """LOCK with user-adjustable relationship/timing/velocity characteristics."""
        level = self._canonical_level("phase_lock")
        if level <= 0.0:
            return
        chars = self._lock_characteristics()
        if hasattr(self, "wavefield_engine") and self.wavefield_engine:
            self.wavefield_engine.apply_phase_locked_randomization()
        else:
            self.apply_euclidean_and_idealized_rhythms()
        if hasattr(self, "_canonical_playlist_paint"):
            self._canonical_playlist_paint(rng=rng, mode="phase_lock", strength=0.55 * level * chars["coupling"])
        try:
            self._phase_lock_playlist_velocity(rng=rng, strength=chars["velocity_link"] * level, randomize=True)
        except Exception:
            pass

    def _apply_euclidean_deterministically(self, seed, rng):
        """EUCLIDEAN canonical: deterministic rhythm/structure reshaping at its saved level."""
        level = self._canonical_level("euclidean")
        if level <= 0.0:
            return
        # The authoritative Euclidean writer already paints its own playlist
        # contribution and preserves protected userdata; do not double-paint here.
        self.apply_euclidean_and_idealized_rhythms()

    def _apply_seeded_deterministically(self, seed, rng):
        """Deterministic seeded application"""
        if hasattr(self, "_apply_live_engine_once"):
            self._apply_live_engine_once("seeded", force=True)

    def _final_unison_reconciliation(self):
        """Final reconciliation for perfect unison"""
        # Reconcile consumes the ENTIRE active set, not one engine. The playlist
        # rebuild below already calls it at its authoritative boundaries; doing
        # it once per engine here multiplied the same work by up to six.
        if hasattr(self, "_rebuild_active_canonical_playlist"):
            self._rebuild_active_canonical_playlist("perfect_unison")

    def _sync_ui_to_unison_state(self):
        """Sync UI to match the deterministic unison state"""
        # Update all engine buttons to reflect current state
        button_map = {
            "seeded": "btn_seeded_randomize",
            "randomizer": "btn_local_randomize",
            "phase_lock": "btn_local_phase_lock",
            "euclidean": "btn_idealize_rhythm",
            "goava": "btn_goava",
            "fractal_seed": "btn_fractal_seed_mode",
        }
        active_set = self._get_active_engine_set()
        for engine, btn_attr in button_map.items():
            btn = getattr(self, btn_attr, None)
            if btn is None:
                continue
            active = engine in active_set
            if not getattr(btn, "_user_interaction", False):
                btn.blockSignals(True); btn.setChecked(active); btn.blockSignals(False)

        # Update UI displays
        if hasattr(self, "scope_status_label"):
            active_count = len(self._get_active_engine_set())
            self.scope_status_label.setText(f"🎵 Perfect Unison: {active_count} engines")

    def _refresh_canonical_derived_columns(self):
        """Recompute per-row calculated_context + live_parametrics from the
        canonical stores after the sorted engine pass.

        These two columns are the only per-row cells that the pre-canonical
        incremental writers (legacy paint path) touched AFTER the engine pass,
        which re-introduced first-writer residue.  Re-deriving them here — and
        only here — makes them a pure function of the final canonical state.
        """
        pl = getattr(self, "master_playlist_data", None) or []
        names = list(getattr(self, "instrument_names_48", []) or ["Operator"])
        for r in range(len(pl)):
            e = pl[r]
            if not isinstance(e, dict):
                continue
            inst = str(e.get("operator") or "") or (names[r % len(names)] if names else "Operator")
            try:
                f = self._contextual_feature_vector(inst, r, r)
                e["calculated_context"] = {k: round(v, 6) for k, v in f.items()}
            except Exception:
                pass
            try:
                apply_live_parametrics_to_entry(self, e, row_idx=r)
            except Exception:
                pass

    def _store_engine_signature(self, engine, seed):
        """Store engine signature for duplicate prevention"""
        if not hasattr(self, "_unison_engine_signatures"):
            self._unison_engine_signatures = {}

        # Create signature from seed and current state
        state_sig = (
            seed,
            self._seed_text() if hasattr(self, 'input_seed_val') else "0.0",
            int(self.spin_seq_length.value()) if hasattr(self, 'spin_seq_length') else DEFAULT_SEQUENCE_LENGTH,
            int(self.spin_playlist_length.value()) if hasattr(self, 'spin_playlist_length') else DEFAULT_PLAYLIST_ROWS
        )

        self._unison_engine_signatures[engine] = state_sig

    def _should_reprocess_engine(self, engine):
        """Check if engine needs reprocessing"""
        if not hasattr(self, "_unison_engine_signatures"):
            return True

        # Get current signature
        seed = _safe_int_seed(self.get_numeric_seed())
        current_sig = (
            seed,
            self._seed_text() if hasattr(self, 'input_seed_val') else "0.0",
            int(self.spin_seq_length.value()) if hasattr(self, 'spin_seq_length') else DEFAULT_SEQUENCE_LENGTH,
            int(self.spin_playlist_length.value()) if hasattr(self, 'spin_playlist_length') else DEFAULT_PLAYLIST_ROWS
        )

        # Compare with stored signature
        stored_sig = self._unison_engine_signatures.get(engine)
        return current_sig != stored_sig

    def _reset_to_clean_baseline(self):
        """Reset to a completely clean baseline state"""
        # Clear all generated content
        self._deactivate_all_engine_content()

        # Reset counters
        self._composition_generation_counter = 0
        self._live_source_update_pending = False

        # Clear signatures
        if hasattr(self, "_unison_engine_signatures"):
            self._unison_engine_signatures.clear()
        if hasattr(self, "_live_engine_signatures"):
            self._live_engine_signatures.clear()

        # Rebuild from clean state
        if hasattr(self, "_rebuild_active_canonical_playlist"):
            self._rebuild_active_canonical_playlist("clean_baseline")

