    def _apply_math_symbol_display_transform(self, enabled):
        """Reversible compact-display transform used by Math Symbols mode.

        It compresses dead layout space rather than shrinking the authored glyphs:
        margins/spacing tighten across the whole window while numeric controls gain
        just enough face height for the larger heavy-stroke symbol cells.  The
        original geometry is cached once and restored exactly when symbols are off.
        """
        enabled = bool(enabled)
        density = 0.76
        widgets = [self] + list(self.findChildren(QWidget))
        seen_layouts = set()
        for widget in widgets:
            try:
                lay = widget.layout()
            except Exception:
                lay = None
            if lay is None or id(lay) in seen_layouts:
                continue
            seen_layouts.add(id(lay))
            try:
                if not hasattr(lay, '_math_symbol_original_metrics'):
                    m = lay.contentsMargins()
                    lay._math_symbol_original_metrics = (m.left(), m.top(), m.right(), m.bottom(), lay.spacing())
                l,t,r,b,sp = lay._math_symbol_original_metrics
                if enabled:
                    # Never erase a deliberate separator completely; use 1px as
                    # the compact visual rhythm when an original margin existed.
                    cv = lambda v: 0 if v <= 0 else max(1, int(round(v*density)))
                    lay.setContentsMargins(cv(l), cv(t), cv(r), cv(b))
                    if sp >= 0: lay.setSpacing(0 if sp == 0 else max(1, int(round(sp*density))))
                else:
                    lay.setContentsMargins(l,t,r,b)
                    if sp >= 0: lay.setSpacing(sp)
            except Exception:
                pass

        for w in list(self.findChildren(QSpinBox)) + list(self.findChildren(QDoubleSpinBox)):
            try:
                if not hasattr(w, '_math_symbol_original_min_height'):
                    w._math_symbol_original_min_height = w.minimumHeight()
                if enabled:
                    w.setMinimumHeight(max(int(w._math_symbol_original_min_height), 46))
                else:
                    w.setMinimumHeight(int(w._math_symbol_original_min_height))
            except Exception:
                pass
        try:
            self.updateGeometry(); self.update()
        except Exception:
            pass

    def _ensure_math_text_overlay(self, w):
        """Create at most one mixed-text number overlay for supported widgets."""
        if w is None:
            return None
        if isinstance(w, QLineEdit):
            try:
                if isinstance(w.parentWidget(), (QSpinBox, QDoubleSpinBox)):
                    return None
            except Exception:
                pass
        if not isinstance(w, (QLabel, QPushButton, QToolButton, QCheckBox, QProgressBar, QLineEdit)):
            return None
        try:
            existing = getattr(w, "_math_text_overlay", None)
            if existing is not None:
                existing._sync(force=False)
                return existing
        except RuntimeError:
            return None
        try:
            ov = _OTMixedNumericTextOverlay(w)
            w._math_text_overlay = ov
            overlays = getattr(self, "_math_symbol_text_overlays", None)
            if overlays is None:
                overlays = self._math_symbol_text_overlays = []
            overlays.append(ov)
            ov._sync(force=True)
            return ov
        except Exception:
            return None

    def _ensure_math_symbol_overlay(self, w):
        """Create at most one overlay for a numeric control."""
        if w is None or not isinstance(w, (QSpinBox, QDoubleSpinBox)):
            return None
        try:
            existing = getattr(w, "_math_symbol_overlay", None)
            if existing is not None:
                existing._sync(force=False)
                return existing
        except RuntimeError:
            return None
        try:
            ov = _OTNumericOverlay(w)
            w._math_symbol_overlay = ov
            overlays = getattr(self, "_math_symbol_numeric_overlays", None)
            if overlays is None:
                overlays = self._math_symbol_numeric_overlays = []
            overlays.append(ov)
            ov._sync(force=True)
            return ov
        except Exception:
            return None

    def _install_math_symbol_numeric_overlays(self):
        """Install overlays only when explicitly enabled.

        PUBLIC_SYMBOL_PERF_2026: numeric author notation defaults OFF and creates
        zero overlay widgets in that state.  When enabled, only actual numeric
        fields are masked; arbitrary labels/buttons keep ordinary text. This
        removes the largest UI repaint cost while preserving author notation
        where it is semantically useful and editable.
        """
        if getattr(self, "_math_symbol_numeric_overlays", None) is None:
            self._math_symbol_numeric_overlays = []
        if getattr(self, "_math_symbol_text_overlays", None) is None:
            self._math_symbol_text_overlays = []
        if not MATH_SYMBOLS_ENABLED:
            self._apply_math_symbol_display_transform(False)
            return
        # R32.9 SMOOTH SYMBOLS: every VISIBLE numeric field of every Groovebox window, installed in small
        # batches across event-loop turns (no multi-hundred-widget stall on the click). Hidden fields get
        # theirs from the Show watcher below when they appear.
        try:
            widgets = [w for w in QApplication.allWidgets()
                       if isinstance(w, (QSpinBox, QDoubleSpinBox)) and w.isVisible()
                       and getattr(w, "_math_symbol_overlay", None) is None]
        except Exception:
            widgets = []
        self._math_symbol_batch = widgets
        self._math_symbol_batch_gen = getattr(self, "_math_symbol_batch_gen", 0) + 1
        _gen = self._math_symbol_batch_gen

        def _step():
            if not MATH_SYMBOLS_ENABLED or _gen != self._math_symbol_batch_gen:
                return
            batch, self._math_symbol_batch = self._math_symbol_batch[:24], self._math_symbol_batch[24:]
            for _w in batch:
                try:
                    self._ensure_math_symbol_overlay(_w)
                except RuntimeError:
                    pass
            if self._math_symbol_batch:
                QTimer.singleShot(0, _step)
        QTimer.singleShot(0, _step)
        self._apply_math_symbol_display_transform(True)
        try:
            if getattr(self, "_math_symbol_spin_watcher", None) is None:
                self._math_symbol_spin_watcher = _MathSymbolSpinWatcher(self)
                app = QApplication.instance()
                if app is not None:
                    app.installEventFilter(self._math_symbol_spin_watcher)
        except Exception:
            self._math_symbol_spin_watcher = None

    def _refresh_math_symbol_numeric_overlays(self):
        """Refresh only changed field glyphs; OFF is an absolute zero-work path."""
        if not MATH_SYMBOLS_ENABLED:
            return
        _opt = getattr(self, "_scode_optimizer", None)
        if _opt is not None:
            if _opt.editing_active(self):
                return
            if not _opt.should_run("symbols"):
                return
            if not _opt.cadence_due("symbols"):
                return
        alive = []
        for ov in list(getattr(self, "_math_symbol_numeric_overlays", []) or []):
            try:
                if ov is None or getattr(ov, "owner", None) is None:
                    continue
                ov._sync(force=False)
                alive.append(ov)
            except RuntimeError:
                pass
            except Exception:
                alive.append(ov)
        self._math_symbol_numeric_overlays = alive

        text_alive = []
        for ov in list(getattr(self, "_math_symbol_text_overlays", []) or []):
            try:
                if ov is None or getattr(ov, "owner", None) is None:
                    continue
                ov._sync(force=False)
                text_alive.append(ov)
            except RuntimeError:
                pass
            except Exception:
                text_alive.append(ov)
        self._math_symbol_text_overlays = text_alive

    def _on_math_symbols_toggled(self, checked):
        """Toggle author symbols; OFF destroys overlay machinery completely."""
        global MATH_SYMBOLS_ENABLED
        MATH_SYMBOLS_ENABLED = bool(checked)
        btn = getattr(self, "btn_math_symbols", None)
        if btn is not None:
            btn.setText("Math Symbols · ON" if MATH_SYMBOLS_ENABLED else "Math Symbols · OFF · base 10")
        preview = getattr(self, "ot_symbol_preview", None)
        if preview is not None:
            preview.setSymbolsEnabled(MATH_SYMBOLS_ENABLED)
            preview.update()

        if MATH_SYMBOLS_ENABLED:
            self._install_math_symbol_numeric_overlays()
            self._apply_math_symbol_display_transform(True)
            self._refresh_math_symbol_numeric_overlays()
            return

        # PUBLIC_SYMBOL_ZERO_WORK_20260906: restore native editors first, then
        # destroy every overlay and remove the application-wide watcher.  Thus
        # OFF means no overlay paint/layout/event-filter work remains resident.
        for ov in list(getattr(self, "_math_symbol_numeric_overlays", []) or []):
            try:
                ov._set_owner_number_text_visible(True)
                if getattr(ov, "owner", None) is not None:
                    ov.owner.removeEventFilter(ov)
                    try:
                        ov.owner._math_symbol_overlay = None
                    except Exception:
                        pass
                le = getattr(ov, "_editor", None)
                if le is not None:
                    le.removeEventFilter(ov)
                ov.hide(); ov.deleteLater()
            except Exception:
                pass
        self._math_symbol_numeric_overlays = []
        for ov in list(getattr(self, "_math_symbol_text_overlays", []) or []):
            try:
                ov._set_native_visible(True)
                if getattr(ov, "owner", None) is not None:
                    ov.owner.removeEventFilter(ov)
                ov.hide(); ov.deleteLater()
            except Exception:
                pass
        self._math_symbol_text_overlays = []
        watcher = getattr(self, "_math_symbol_spin_watcher", None)
        if watcher is not None:
            try:
                app = QApplication.instance()
                if app is not None:
                    app.removeEventFilter(watcher)
                watcher.deleteLater()
            except Exception:
                pass
            self._math_symbol_spin_watcher = None
        self._apply_math_symbol_display_transform(False)

    def _on_goava_ensemble_mod_changed(self, value):
        self.goava_ensemble_mod = float(max(0.0, min(1.0, float(value))))
        try:
            self._on_live_source_changed()
        except Exception:
            pass

    def _on_goava_toggled(self, checked):
        """Modified to use perfect unison system"""
        try:
            self.slider_goava_ensemble.setEnabled(bool(checked))
        except Exception:
            pass
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("GOAVA " + ("ON" if checked else "OFF"))
        if checked:
            self.goava_active = True
        else:
            self.goava_active = False
        self._on_live_source_changed()

    def _schedule_ui_after_canonical_write(self, reason="canonical-write"):
        """Coalesce UI refresh after any canonical document mutation.

        Canonical writers update the document on worker/control paths; the live
        sequencer, automation row, chord/envelope controls, and related panels
        must reflect that state without requiring the user to re-select the
        instrument or open Performance.
        """
        # Canonical writes also happen inside the render worker; a QTimer must be
        # created on the GUI thread (a worker has no running Qt event loop).
        if hasattr(self, "_on_gui_thread") and not self._on_gui_thread():
            self._gui_refresh(f"ui_after_canonical_write:{reason}",
                              lambda r=reason: self._schedule_ui_after_canonical_write(r))
            return
        try:
            from PyQt6.QtCore import QTimer
        except Exception:
            return
        # Merge rapid multi-instrument writes into one GUI tick.
        pending = getattr(self, "_canonical_ui_refresh_pending", None)
        if not isinstance(pending, set):
            pending = set()
            self._canonical_ui_refresh_pending = pending
        pending.add(str(reason or "canonical-write"))
        if getattr(self, "_canonical_ui_refresh_armed", False):
            return
        self._canonical_ui_refresh_armed = True

        def _run():
            self._canonical_ui_refresh_armed = False
            reasons = set(getattr(self, "_canonical_ui_refresh_pending", set()) or set())
            self._canonical_ui_refresh_pending = set()
            try:
                # Sequence pads / chord / envelope for the active instrument.
                if hasattr(self, "reload_active_instrument_sequencer_ui"):
                    self.reload_active_instrument_sequencer_ui()
                if hasattr(self, "_refresh_sequence_selector"):
                    self._refresh_sequence_selector()
                if hasattr(self, "_refresh_sequencer_automation_row"):
                    self._refresh_sequencer_automation_row()
                if hasattr(self, "_load_sequence_envelope_controls") and hasattr(self, "_current_sequence_mem"):
                    try:
                        self._load_sequence_envelope_controls(self._current_sequence_mem())
                    except Exception:
                        pass
                if hasattr(self, "_refresh_sequence_dependent_panels"):
                    try:
                        self._refresh_sequence_dependent_panels()
                    except Exception:
                        pass
                # Synth / parameter surfaces that mirror canonical param state.
                for _name in (
                    "_sync_synth_panel_from_state",
                    "_reload_active_synth_ui",
                    "_refresh_instrument_param_ui",
                    "_sync_active_instrument_controls",
                    "_refresh_canonical_fingerprint",
                ):
                    fn = getattr(self, _name, None)
                    if callable(fn):
                        try:
                            fn()
                        except Exception:
                            pass
                # Keep paint/playlist tables honest if they cache sequence choices.
                try:
                    apt = getattr(self, "active_paint_table", None)
                    if apt is not None and hasattr(apt, "_refresh_paint_sequence_choices"):
                        apt._refresh_paint_sequence_choices()
                except Exception:
                    pass
            except Exception as exc:
                print(f"[Canonical UI] refresh after {reasons} failed: {exc}")

        try:
            QTimer.singleShot(40, _run)
        except Exception:
            _run()

    def _canonical_write_sequence_runtime(self, instrument_name=None, sequence_id=None):
        """Write the live synth + sequence + automation/envelope state to the canonical document.

        The canonical document explicitly carries pitch/amp and pattern attack/release so
        automation, playback, export and video/game consumers observe the same state.
        """
        try:
            name = instrument_name or self._current_instrument_name()
            sid = int(sequence_id or self._current_sequence_index(name))
            mem = copy.deepcopy(self._current_sequence_mem(name))
            synth = copy.deepcopy((getattr(self, "instrument_param_state", {}) or {}).get(name, {}) or {})
            # GROOVEBOX_R23R_CANONICAL_GEOMETRY_20261031: the four geometric
            # synth components (Vector, Wavetable, Ball, Cellular) are fully
            # integrated into the canonical project data write as first-class
            # lanes. The write plan carries each component's live instance
            # state (falling back to the convolution preset when the instance
            # is missing), the shared mixer depths and the Instance × Main
            # synth / Instance × Global mod couplings, and the instance
            # ownership flags — so every consumer (mixdown render, video
            # export, game interpreter) reads the same authoritative
            # geometric instance instead of an opaque sub-dict inside synth.
            _geo_live = synth.get("geo") if isinstance(synth.get("geo"), dict) else None
            if _geo_live is None:
                _geo_live = self._geometric_convolution_defaults()
            _geo_preset = self._geometric_convolution_defaults()
            _geo_mix = self._geometric_mixer_snapshot()
            _geo_components = {
                "vector": copy.deepcopy(_geo_live.get("vector") or _geo_preset["vector"]),
                "wavetable": copy.deepcopy(_geo_live.get("wavetable") or _geo_preset["wavetable"]),
                "ball": copy.deepcopy(_geo_live.get("ball") or _geo_preset["ball"]),
                "cellular": copy.deepcopy(_geo_live.get("cellular") or _geo_preset["cellular"]),
                "mixer": {
                    "vector": _geo_mix.get("vector", 0.0),
                    "wavetable": _geo_mix.get("wavetable", 0.0),
                    "ball": _geo_mix.get("ball", 0.0),
                    "cellular": _geo_mix.get("cellular", 0.0),
                    "cross_mod": _geo_mix.get("cross_mod", 0.0),
                    "ensemble_mod_amt": _geo_mix.get("ensemble_mod_amt", 0.0),
                },
                "ownership": {
                    "ball_locked": bool(_geo_live.get("ball_locked", False)),
                    "ca_locked": bool(_geo_live.get("ca_locked", False)),
                    "has_drawn_cycle": isinstance(_geo_live.get("wavetable", {}).get("drawn"), list),
                    "has_manual_cells": isinstance(_geo_live.get("cellular", {}).get("manual_cells"), list),
                },
            }
            # track_offset is mirrored for consumers only — user-owned, not a
            # canonical modification handle (same ownership model as resonance amount).
            try:
                _user_track_off = float(mem.get("track_offset", 0.0) or 0.0)
                if not math.isfinite(_user_track_off):
                    _user_track_off = 0.0
            except Exception:
                _user_track_off = 0.0
            try:
                _user_global_track_off = float(getattr(self, "global_track_offset", 0.0) or 0.0)
                if not math.isfinite(_user_global_track_off):
                    _user_global_track_off = 0.0
            except Exception:
                _user_global_track_off = 0.0
            seq_payload = {
                "instrument": name,
                "sequence_id": sid,
                "pattern_length": int(mem.get("pattern_length", len(mem.get("steps", [])) or 1) or 1),
                "steps": copy.deepcopy(mem.get("steps", [])),
                "amplitudes": copy.deepcopy(mem.get("amplitudes", [])),
                "pitches": copy.deepcopy(mem.get("pitches", [])),
                "chord_note_count": int(mem.get("chord_note_count", 3) or 3),
                "chord_intervals": copy.deepcopy(mem.get("chord_intervals", [0, 4, 7])),
                "chord_slot_features": copy.deepcopy(normalize_chord_slot_features(
                    mem.get("chord_slot_features", []), int(mem.get("chord_note_count", 3) or 3), 512)),
                "chord_user_owned": bool(mem.get("chord_user_owned", False)),
                "probabilities": copy.deepcopy(mem.get("probabilities", [])),
                "offsets": copy.deepcopy(mem.get("offsets", [])),
                "step_controls": copy.deepcopy(mem.get("step_controls", {})),
                "phase_shift": copy.deepcopy((mem.get("step_controls", {}) or {}).get("phase_shift", mem.get("phase_shift", []))),
                "attack": float(mem.get("attack", mem.get("envelope_attack", 0.0)) or 0.0),
                "release": float(mem.get("decay", mem.get("envelope_decay", 0.0)) or 0.0),
                "sequence_envelope_attack": float(mem.get("sequence_envelope_attack", 0.5) or 0.0),
                "sequence_envelope_release": float(mem.get("sequence_envelope_release", 0.5) or 0.0),
                "automation_lane": copy.deepcopy(mem.get("automation_lane", [])),
                "automation_lane_length": int(mem.get("automation_lane_length", mem.get("pattern_length", 1)) or 1),
                "synth": synth,
                # R23R canonical geometry: the four geometric synth components
                # as first-class lanes in the write plan.
                "geometric_components": _geo_components,
                "synth_pitch": synth.get("pitch", synth.get("frequency_ratio", 1.0)),
                "synth_amp": synth.get("amp", synth.get("amplitude", synth.get("volume", synth.get("gain", 1.0)))),
                "canonical_control_strategy": str(getattr(self, "canonical_control_strategy", "Full Canonical")),
                "canonical_signal_control": float(getattr(self, "canonical_signal_control", CANONICAL_SIGNAL_CONTROL_DEFAULT)),
                "canonical_lanes": ["sequence", "automation", "pitch", "amp", "phase_shift", "eq_gain_db", "sidechain_depth", "trigger_probability", "phase", "trigger", "AM", "FM", "PM", "effect_layer", "vector", "wavetable", "ball", "cellular"],
                "instrument_script": str((getattr(self, "instrument_scripts", {}) or {}).get(name, "") or ""),
                "graph_context_contract": "full_graph_v1",
                "graph_script_variables": list(GRAPH_SCRIPT_VARIABLES),
                "track_offset": _user_track_off,
                "global_track_offset": _user_global_track_off,
                "track_offset_user_owned": True,
            }
            # SCODE_FULL_ACCEL_V4: many Qt controls emit the same committed value
            # more than once (editingFinished + valueChanged + canonical sync). Reject
            # an identical sequence-runtime write before rebuilding the document and
            # fingerprint. The payload itself remains the complete correctness key.
            _opt = getattr(self, "_scode_optimizer", None)
            if _opt is not None and not _opt.claim_work("canonical_sequence_runtime", (name, sid, seq_payload)):
                return
            doc = getattr(self, "_canonical_composition_document", None)
            if not isinstance(doc, dict):
                doc = {}                       # R31 RENDER_SPEED: only runtime / automation keys are read
            doc.setdefault("canonical_sequence_runtime_all", {})
            doc["canonical_sequence_runtime_all"][f"{name}:{sid}"] = seq_payload
            doc["canonical_sequence_runtime"] = seq_payload
            doc["sequencer_automation_points"] = copy.deepcopy(getattr(self, "sequencer_automation_points", []))
            doc["canonical_automation_state"] = {
                "enabled": bool(getattr(self, "sequencer_automation_enabled", True)),
                "points": copy.deepcopy(getattr(self, "sequencer_automation_points", [])),
                "canonical_composition_weight": 1.0,
                "imported_carrier_phase_lock": 0.5,
            }
            self._canonical_composition_document = doc
            self._canonical_automation_revision = int(getattr(self, "_canonical_automation_revision", 0)) + 1
            self._refresh_canonical_fingerprint()
            # HF28: any sequence/automation canonical write must paint the live UI.
            try:
                self._schedule_ui_after_canonical_write(f"sequence-runtime:{name}:{sid}")
            except Exception:
                pass
        except Exception as exc:
            print(f"[Canonical] sequence runtime write failed: {exc}")

    def _randomizer_toggle_style(self, button, checked, cycle=0, role="random"):
        """Apply a parser-safe, high-contrast state color for randomizer toggles.

        The palette intentionally changes on each ON cycle so a retoggle is
        visually obvious as a fresh generation rather than a stale latch.
        """
        if button is None:
            return
        palettes = (
            ("#1b5e3a", "#79ffb0", "#b7ffd5"),
            ("#6a4b12", "#ffd166", "#fff0b3"),
            ("#63205f", "#ff78e7", "#ffd1f5"),
            ("#6a2b1a", "#ff9f72", "#ffd6c7"),
            ("#3f5f1c", "#c6f36b", "#edffc2"),
        )
        bg, fg, border = palettes[int(cycle) % len(palettes)]
        if not checked:
            bg, fg, border = "#17233d", "#7ce7ff", "#3d7ea6"
        button.setStyleSheet(
            "QPushButton { background-color:%s; color:%s; border:2px solid %s; "
            "border-radius:6px; padding:5px 9px; font-weight:900; } "
            "QPushButton:hover { background-color:%s; } "
            "QPushButton:pressed { background-color:#ff9f1c; color:#16110a; }"
            % (bg, fg, border, bg)
        )

    def _randomizer_toggle_restore(self, key, button=None, label="Randomizer"):
        """Restore the exact pre-randomization state captured for this toggle."""
        snap = (getattr(self, "_randomizer_toggle_snapshots", {}) or {}).get(key)
        if not isinstance(snap, dict):
            return False
        self._randomizer_toggle_guard = True
        try:
            self._undo_in_flight = True
            self._project_history_restore(snap)
        finally:
            self._undo_in_flight = False
            self._randomizer_toggle_guard = False
        self._randomizer_toggle_snapshots.pop(key, None)
        if button is not None:
            try:   # R32.10: the ON snapshot holds this button checked — restoring must not re-check it
                button.blockSignals(True); button.setChecked(False); button.blockSignals(False)
            except Exception:
                pass
            self._randomizer_toggle_style(button, False, getattr(self, "_randomizer_toggle_cycles", {}).get(key, 0))
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("↩ %s OFF · restored pre-randomize state" % label)
        return True

    def _randomizer_toggle_prepare(self, key, button=None, label="Randomizer"):
        """Capture a clean baseline for a new ON cycle and advance its color."""
        if getattr(self, "_randomizer_toggle_guard", False):
            return False
        snaps = getattr(self, "_randomizer_toggle_snapshots", None)
        cycles = getattr(self, "_randomizer_toggle_cycles", None)
        if snaps is None:
            self._randomizer_toggle_snapshots = {}; snaps = self._randomizer_toggle_snapshots
        if cycles is None:
            self._randomizer_toggle_cycles = {}; cycles = self._randomizer_toggle_cycles
        snaps[key] = self._project_history_snapshot()
        cycles[key] = int(cycles.get(key, -1)) + 1
        if button is not None:
            self._randomizer_toggle_style(button, True, cycles[key])
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo(label + " ON")
        return True

    def _toggle_one_shot_randomizer(self, checked, key, action, button=None, label="Randomizer"):
        """Common reversible toggle contract for one-shot randomizer controls."""
        if getattr(self, "_randomizer_toggle_guard", False):
            return
        if not checked:
            self._randomizer_toggle_restore(key, button=button, label=label)
            return
        if not self._randomizer_toggle_prepare(key, button=button, label=label):
            return
        try:
            prior_undo = bool(getattr(self, "_undo_in_flight", False))
            self._undo_in_flight = True
            action()
            self._undo_in_flight = prior_undo
        except Exception as exc:
            self._undo_in_flight = prior_undo if "prior_undo" in locals() else False
            print("[%s] toggle failed: %s" % (label, exc))
            try:
                _log = _gb_log_error(f"randomizer · {label}", exc)
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText(f"⚠ {label} failed: {exc}" + (f" · details: {_log}" if _log else ""))
            except Exception:
                pass
            self._randomizer_toggle_restore(key, button=button, label=label)
            return
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("🎲 %s ON · fresh randomized variation" % label)

    def _randomize_everything_scoped(self, checked=True):
        """Single full-state randomizer; one undo boundary, no duplicate randomizer button.

        It refreshes the newer sequence/automation/envelope/canonical state in addition to
        the established playlist, synth, patch and global algorithm systems.
        """
        if getattr(self, "_randomize_all_guard", False):
            return
        self._randomize_all_guard = True
        # GROOVEBOX_R23R_RANDOMIZE_ALL_20261031: Harmonic Frequency is the
        # tuning anchor — snapshot it before any canonical machinery runs so the
        # transaction can restore and lock it. Randomize All skips it.
        _r23r_hf_anchor = {}
        for _rn, _rp in (getattr(self, "instrument_param_state", {}) or {}).items():
            if isinstance(_rp, dict):
                try:
                    _hf = float(_rp.get("harmonic_freq"))
                except (TypeError, ValueError):
                    _hf = None
                if _hf is not None:
                    _r23r_hf_anchor[_rn] = _hf
        prior_undo = bool(getattr(self, "_undo_in_flight", False))
        try:
            if not prior_undo:
                self._push_undo("Randomize All")
            # Suppress nested undo boundaries: Randomize All is exactly one transaction.
            self._undo_in_flight = True
            # Seed is intentionally randomized first so every deterministic subsystem
            # receives a new common source.
            self._on_random_seed_clicked()
            # RANDOMIZE_ALL_COMPOSER_20261102: the Heuristic Composer (family / bias / span) and the number-theory
            # algorithm (lattice, modulus, depth) are randomized with the rest; scope and nothing is written until Apply.
            try:
                _fam, _bias = self.combo_heuristic_family, self.combo_heuristic_bias
                _fam.setCurrentIndex(random.randrange(_fam.count()))
                _bias.setCurrentIndex(random.randrange(_bias.count()))
                self.spin_heuristic_span.setValue(random.choice((8, 12, 16, 24, 32, 48, 64)))
                self.combo_nt_mode.setCurrentIndex(random.randrange(self.combo_nt_mode.count()))
                self.spin_nt_modulus.setValue(random.choice((5, 7, 8, 9, 10, 11, 12, 13, 16, 17, 19, 24, 31, 36)))
                self.spin_nt_depth.setValue(random.randint(2, 9))
            except Exception:
                pass

            # Established local composition randomizer / canonical unison.
            # IMPORTANT: Randomize All is its own transaction.  Do NOT enter the
            # local toggle's snapshot machinery here: if Local Randomizer is also
            # ON, its independent pre-toggle snapshot must remain intact.  Otherwise
            # turning ALL OFF first can restore the Local snapshot and resurrect the
            # sequence randomization that ALL had already undone.
            try:
                if hasattr(self, "btn_local_randomize"):
                    self.btn_local_randomize._user_interaction = True
                self._ensure_perfect_unison()
            finally:
                if hasattr(self, "btn_local_randomize"):
                    self.btn_local_randomize._user_interaction = False

            # Global algorithm authoring is included; it remains non-applied by design.
            self._on_randomize_global_play_algo()

            # RHYTHM_MELODY_RANDOMIZE_ALL_20261104: generate fresh rhythm and melody
            # algos, store them in global_algo_state, and register canonical activation
            # so the ownership registry reflects the new Randomize All state.
            try:
                _rm_rng = random  # uses seeded state from _on_random_seed_clicked above
                _rhythm_algo = generate_random_rhythm_algo(_rm_rng)
                _melody_algo = generate_random_melody_algo(_rm_rng)
                gas = getattr(self, "global_algo_state", None)
                if isinstance(gas, dict):
                    gas["rhythm"] = _rhythm_algo
                    gas["melody"] = _melody_algo
                # Update the UI fields if they exist
                if hasattr(self, "gp_rhythm_gate_field"):
                    self.gp_rhythm_gate_field.blockSignals(True)
                    self.gp_rhythm_gate_field.setText(str(_rhythm_algo.get("gate", "")))
                    self.gp_rhythm_gate_field.blockSignals(False)
                if hasattr(self, "gp_rhythm_offset_field"):
                    self.gp_rhythm_offset_field.blockSignals(True)
                    self.gp_rhythm_offset_field.setText(str(_rhythm_algo.get("offset", "")))
                    self.gp_rhythm_offset_field.blockSignals(False)
                if hasattr(self, "gp_melody_pitch_field"):
                    self.gp_melody_pitch_field.blockSignals(True)
                    self.gp_melody_pitch_field.setText(str(_melody_algo.get("pitch", "")))
                    self.gp_melody_pitch_field.blockSignals(False)
                # Canonical activation: Randomize All is treated as a canonical
                # write — both families get owned at canonical strength so the next
                # canonical paint knows they were just authored here.
                self._register_heuristic_ownership("playlist_rhythm", source="canonical", strength=0.55)
                self._register_heuristic_ownership("playlist_melody", source="canonical", strength=0.55)
                # Engine families are fully re-written below by the loop, so clear
                # any prior user ownership to avoid stale blending.
                self._clear_heuristic_ownership("engine_rhythm")
                self._clear_heuristic_ownership("engine_melody")
            except Exception as _rm_exc:
                print(f"[Randomize All] rhythm/melody algo generation: {_rm_exc}")

            # Randomize sequence content while preserving the current number of sequence slots.
            rng = np.random.default_rng(_safe_int_seed(self.get_numeric_seed()))
            for name, bank in (getattr(self, "instrument_sequence_banks", {}) or {}).items():
                for sid, mem in (bank or {}).items():
                    if not isinstance(mem, dict):
                        continue
                    n = max(1, min(STRUCT_MAX_STEPS, int(mem.get("pattern_length", DEFAULT_SEQUENCE_LENGTH) or DEFAULT_SEQUENCE_LENGTH)))
                    mem["steps"] = [bool(rng.random() > 0.55) for _ in range(n)]
                    mem["gates"] = [True] * n
                    mem["amplitudes"] = [float(rng.uniform(0.35, 1.0)) for _ in range(n)]
                    mem["pitches"] = [float(rng.uniform(0.75, 1.5)) for _ in range(n)]
                    mem["probabilities"] = [int(rng.integers(45, 101)) for _ in range(n)]
                    mem["offsets"] = [float(rng.uniform(-0.25, 0.25)) for _ in range(n)]
                    # New envelope controls remain bounded to 0–1 row.
                    mem["sequence_envelope_attack"] = float(rng.random())
                    mem["sequence_envelope_release"] = float(rng.random())
                    mem["attack"] = float(rng.random())
                    mem["decay"] = float(rng.random())
                    mem["automation_lane_length"] = n

            # GROOVEBOX_R23R_LEAD_RANDOMIZE_PRIORITY_20261103: ensure the Canon Lead
            # synth is always present in param_state so the loop below touches it.
            try:
                import canon_lead as _cl_rand
                _lead_name = _cl_rand.get_lead(self)
                if _lead_name and _lead_name not in (getattr(self, "instrument_param_state", {}) or {}):
                    getattr(self, "instrument_param_state", {}).setdefault(_lead_name, {})
            except Exception:
                pass
            # Randomize synth pitch/amp explicitly, then write every selected sequence to canonical.
            for name, params in (getattr(self, "instrument_param_state", {}) or {}).items():
                if not isinstance(params, dict):
                    continue
                params["pitch"] = float(rng.uniform(0.5, 2.0))
                params["volume"] = float(rng.uniform(0.45, 1.0))
                params["amplitude"] = float(params["volume"])
                # RAND_PARAMS_GRAPH_2026: stock/engine-authored scripts graduate
                # to the same full graph contract. User-authored scripts stay untouched.
                _existing_script = str((getattr(self, "instrument_scripts", {}) or {}).get(name, "") or "")
                _stock_script = instrument_script_is_stock(_existing_script)
                if _stock_script and hasattr(self, "instrument_scripts"):
                    _slot = list((getattr(self, "instrument_param_state", {}) or {}).keys()).index(name) if name in (getattr(self, "instrument_param_state", {}) or {}) else 0
                    self.instrument_scripts[name] = generate_random_instrument_graph_script(name, self.get_numeric_seed(), _slot)
                bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(name, {})
                for sid in sorted(bank):
                    self._canonical_write_sequence_runtime(name, sid)

            # GROOVEBOX_R23R_RANDOMIZE_ALL_20261031: Harmonic Frequency stays
            # fixed as the tuning anchor, so Randomize All skips it while
            # randomizing everything else in Edit Synth and the four geometric
            # instances, including mixer depths and couplings. The randomized
            # values are written on the user's behalf into the canonical macro
            # user store: reconciliation treats that store as the authored
            # program, so without this the next unison reconciliation would
            # revert the Edit Synth values.
            _r23r_user_store = getattr(self, "_canonical_macro_user_store", None)
            if not isinstance(_r23r_user_store, dict):
                _r23r_user_store = {}
                self._canonical_macro_user_store = _r23r_user_store
            for name, params in (getattr(self, "instrument_param_state", {}) or {}).items():
                if not isinstance(params, dict):
                    continue
                # Edit Synth panel params — harmonic_freq is never touched.
                _r23r_anchor = _r23r_hf_anchor.get(name)
                if _r23r_anchor is not None:
                    params["harmonic_freq"] = _r23r_anchor
                    # The anchor is user-owned from here on: the canonical
                    # sequence reconciler must not re-derive it.
                    params["harmonic_freq_user_locked"] = True
                params["morph"] = float(rng.uniform(0.01, 10.0))
                params["chaos"] = float(rng.uniform(0.0, 1.0))
                params["fold_depth"] = float(rng.uniform(1.0, 16.0))
                params["harmonic_lattice"] = float(rng.uniform(0.0, 1.0))
                geo = params.get("geo")
                if not isinstance(geo, dict):
                    geo = self._geometric_convolution_defaults()  # R23R convolution preset
                    params["geo"] = geo
                vec = geo.get("vector")
                if not isinstance(vec, dict):
                    vec = dict(self._geometric_convolution_defaults()["vector"])
                    geo["vector"] = vec
                for axis in ("x", "y", "z"):
                    vec[axis] = float(rng.uniform(-1.0, 1.0))
                vec["drive"] = float(rng.uniform(0.0, 1.0))
                wt = geo.get("wavetable")
                if not isinstance(wt, dict):
                    wt = dict(self._geometric_convolution_defaults()["wavetable"])
                    geo["wavetable"] = wt
                wt["mode"] = int(rng.choice((1, 2, 3)))
                wt["phase"] = float(rng.uniform(-0.5, 0.5))
                wt["curvature"] = float(rng.uniform(0.25, 0.75))
                wt["twist"] = float(rng.uniform(0.25, 0.75))
                wt["fold"] = float(rng.uniform(0.05, 0.45))
                # A hand-drawn cycle stays user-owned, exactly like an
                # authored script: Randomize All never rewrites it.
                if not geo.get("ball_locked"):
                    ball = geo.get("ball")
                    if not isinstance(ball, dict):
                        ball = dict(self._geometric_convolution_defaults()["ball"])
                        geo["ball"] = ball
                    ball["gravity"] = float(rng.uniform(-4.0, 4.0))
                    ball["gravity_angle_degrees"] = float(rng.uniform(-360.0, 360.0))
                    ball["radius"] = float(rng.uniform(0.05, 1.0))
                    ball["vx"] = float(rng.uniform(-4.0, 4.0))
                    ball["vy"] = float(rng.uniform(-4.0, 4.0))
                if not geo.get("ca_locked"):
                    ca = geo.get("cellular")
                    if not isinstance(ca, dict):
                        ca = dict(self._geometric_convolution_defaults()["cellular"])
                        geo["cellular"] = ca
                    ca["width"] = int(rng.integers(4, 65))
                    ca["height"] = int(rng.integers(4, 65))
                    ca["cell_types"] = int(rng.integers(2, 9))
                    ca["generations"] = int(rng.integers(1, 257))
                    ca["rule"] = int(rng.integers(0, 256))
                    ca["neighborhood"] = str(rng.choice(("moore", "von_neumann")))
                    # Hand-placed cells stay user-owned, like a drawn cycle.
                # Authorize the randomized program: the canonical macro user
                # store is the authored-program key, so the randomized values
                # survive the next unison reconciliation instead of being
                # reverted to the pre-transaction user program.
                _r23r_us = _r23r_user_store.setdefault(name, {})
                if isinstance(_r23r_us, dict):
                    _r23r_us.update(copy.deepcopy(params))
            # Mixer depths + the Instance × Main synth / Instance × Global mod
            # couplings are one shared project-wide contract: randomize once.
            mix = getattr(self, "geometric_synth_mixer_state", None)
            if isinstance(mix, dict):
                for lane in ("vector", "wavetable", "ball", "cellular"):
                    mix[lane] = float(rng.uniform(0.0, 1.0))
                mix["cross_mod"] = float(rng.uniform(0.0, 0.008))
                mix["inharmonic"] = float(rng.uniform(0.0, 1.0))  # GROOVEBOX_INHARMONIC_GATE_20261102
                mix["ensemble_mod_amt"] = float(rng.uniform(0.0, 0.5))
                if hasattr(self, "geometric_engine_mix_sliders"):
                    for _k, (_sl, _lab) in self.geometric_engine_mix_sliders.items():
                        _sl.setValue(int(round(mix[_k] * 100)))
                        _lab.setText(f"{mix[_k]:.2f}")
                if hasattr(self, "slider_geometric_inharmonic"):
                    self.slider_geometric_inharmonic.setValue(int(round(mix["inharmonic"] * 100)))
                if hasattr(self, "slider_geometric_cross_mod"):
                    self.slider_geometric_cross_mod.setValue(int(round(mix["cross_mod"] * 10000)))
                    if hasattr(self, "lbl_geometric_cross_mod"):
                        self.lbl_geometric_cross_mod.setText(f"{mix['cross_mod']:.4f}")
                if hasattr(self, "slider_geometric_ensemble_mod"):
                    self.slider_geometric_ensemble_mod.setValue(int(round(mix["ensemble_mod_amt"] * 100)))
                    if hasattr(self, "lbl_geometric_ensemble_mod"):
                        self.lbl_geometric_ensemble_mod.setText(f"{int(round(mix['ensemble_mod_amt'] * 100))}%")

            # Refresh UI without opening any obsolete panel/tab windows.
            try:
                self._refresh_sequence_selector()
                self.reload_active_instrument_sequencer_ui()
                self._refresh_sequencer_automation_row()
                self._load_sequence_envelope_controls(self._current_sequence_mem())
            except Exception:
                pass
            self._on_live_source_changed()
            self._maintain_stochastic_harmonic_phase_lock()
            self._refresh_canonical_fingerprint()
            # GROOVEBOX_R23R_PKP_BOOST_DJ_20261103: Randomize All is the ONLY
            # randomizer that may activate PKP Boost DJ (25 % probability).
            # Other randomizers (local context, partial) must never trigger it.
            try:
                if random.random() < 0.25:
                    _pkp_boost_target = float(rng.uniform(1.2, 3.0))
                    if hasattr(self, "slider_pkp_boost"):
                        self.slider_pkp_boost.setValue(round(_pkp_boost_target, 3))
                    self.pkp_boost_active = True
                    self.pkp_boost_amount = _pkp_boost_target
                    _dj_note = f"PKP Boost DJ activated: ×{_pkp_boost_target:.2f}"
                    if hasattr(self, "scope_status_label"):
                        # note will be overwritten by the setText below; store it
                        pass
                else:
                    _dj_note = ""
            except Exception:
                _dj_note = ""
            if hasattr(self, "scope_status_label"):
                _base = "🎲 RANDOMIZE ALL · Edit Synth (Harmonic Frequency anchor fixed) + geo instances + mixer/couplings + synth/pitch/amp + sequences + automation + envelopes + canonical written"
                self.scope_status_label.setText(_base + (f"  ·  🎧 {_dj_note}" if _dj_note else ""))
        except Exception as exc:
            print(f"[Randomize All] failed: {exc}")
            _log = _gb_log_error("Randomize All", exc)
            # GROOVEBOX_R23R_ERROR_LOG_20261101: one automatic retry (e.g. a startup
            # race with background initialisation); the traceback is kept on disk.
            _retry = not getattr(self, "_rand_all_retrying", False)
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(
                    f"🎲 Randomize All failed: {exc}" + (" · retrying…" if _retry else "")
                    + (f" · details: {_log}" if _log else ""))
            if _retry:
                def _again():
                    self._rand_all_retrying = True
                    try:
                        self._randomize_everything_scoped(checked)
                    finally:
                        self._rand_all_retrying = False
                QTimer.singleShot(1500, _again)
        finally:
            self._undo_in_flight = prior_undo
            self._randomize_all_guard = False

    def _randomize_local_context(self, checked=True):
        """RAND: fresh OS entropy on each OFF→ON activation, replayable thereafter."""
        if getattr(self, "_randomizer_toggle_guard", False):
            return
        key = "local_randomizer"
        if not checked:
            self._randomizer_toggle_restore(key, self.btn_local_randomize, "RAND")
            return
        if not self._randomizer_toggle_prepare(key, self.btn_local_randomize, "RAND"):
            return
        self._capture_rand_entropy()
        try:
            self.btn_local_randomize._user_interaction = True
            self._on_live_source_changed()
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(("RAND ON · OS entropy " if str(getattr(self, "rand_source", "fractal")) == "pure" else "RAND ON · fractal seed child #%d " % int(getattr(self, "_rand_generation_counter", 0) or 0)) + f"{int(self._rand_instance_seed):016x}")
        finally:
            self.btn_local_randomize._user_interaction = False

    def _phase_lock_local_context(self, checked=True):
        """Modified to use perfect unison system"""
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("Phase-lock engine")
        # Store user interaction flag to prevent UI feedback loop
        if hasattr(self, "btn_local_phase_lock"):
            self.btn_local_phase_lock._user_interaction = True

        self._on_live_source_changed()

        # Clear user interaction flag after processing
        if hasattr(self, "btn_local_phase_lock"):
            self.btn_local_phase_lock._user_interaction = False

    def _on_euclidean_live_toggled(self, checked):
        """Modified to use perfect unison system"""
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("EUCLIDEAN canonical " + ("ON" if checked else "OFF"))
        # Store user interaction flag to prevent UI feedback loop
        if hasattr(self, "btn_idealize_rhythm"):
            self.btn_idealize_rhythm._user_interaction = True

        self._on_live_source_changed()

        # Handle timer separately
        if checked:
            if hasattr(self, "_live_euclid_timer"):
                self._live_euclid_timer.start()
        else:
            if hasattr(self, "_live_euclid_timer"):
                self._live_euclid_timer.stop()

        # Clear user interaction flag after processing
        if hasattr(self, "btn_idealize_rhythm"):
            self.btn_idealize_rhythm._user_interaction = False

    def _on_seeded_live_toggled(self, checked):
        """Reversible seeded-live randomizer with explicit OFF restoration."""
        if getattr(self, 'chk_user_program_only', None) and self.chk_user_program_only.isChecked():
            if hasattr(self, "btn_seeded_randomize"):
                self.btn_seeded_randomize.blockSignals(True)
                self.btn_seeded_randomize.setChecked(False)
                self.btn_seeded_randomize.blockSignals(False)
            return
        key = "seeded_live_randomizer"
        if getattr(self, "_randomizer_toggle_guard", False):
            return
        if not checked:
            if hasattr(self, "_live_seeded_timer"):
                self._live_seeded_timer.stop()
            self._randomizer_toggle_restore(key, self.btn_seeded_randomize, "SEEDED LIVE RANDOMIZER")
            return
        self._randomizer_toggle_prepare(key, self.btn_seeded_randomize, "SEEDED LIVE RANDOMIZER")
        try:
            self.btn_seeded_randomize._user_interaction = True
            self._on_live_source_changed()
            if hasattr(self, "_live_seeded_timer"):
                self._live_seeded_timer.start()
        finally:
            self.btn_seeded_randomize._user_interaction = False

    def _flush_live_source_update(self):
        """Modified to use perfect unison system"""
        job = getattr(self, "_canonical_commit", None)
        if job is not None and job.running:
            job.request_restart()
            return
        if self._get_active_engine_set() and getattr(self, "_scode_optimizer", None) is not None:
            from canonical_pool import CanonicalPool
            pool = getattr(self, "_canonical_sequence_pool", None)
            if pool is None:
                pool = self._canonical_sequence_pool = CanonicalPool(self)
            try:
                if not pool.prepare():
                    return
            except Exception as exc:
                self._canonical_prepared_sequence_plan = None
                print(f"[Canonical pool] snapshot unavailable: {exc}; using synchronous ownership-safe path")
        if self._get_active_engine_set() and os.environ.get("GROOVEBOX_COOPERATIVE_CANONICAL", "0") != "0":
            from canonical_cooperative import CanonicalCommit
            if job is None:
                job = self._canonical_commit = CanonicalCommit(self)
            self._cache_realtime_control_state()
            self._live_source_update_pending = False
            self._live_source_update_dirty = False
            job.start()
            return
        self._live_source_update_pending = False
        self._cache_realtime_control_state()

        # Use perfect unison instead of individual processing
        self._ensure_perfect_unison()

        try:
            self._refresh_canonical_fingerprint()
        except Exception:
            pass

        # Also handle the live engine timers if needed
        if (hasattr(self, "btn_idealize_rhythm") and
            self.btn_idealize_rhythm.isChecked()):
            if hasattr(self, "_live_euclid_timer"):
                self._live_euclid_timer.start()

        if (hasattr(self, "btn_seeded_randomize") and
            self.btn_seeded_randomize.isChecked()):
            if hasattr(self, "_live_seeded_timer"):
                self._live_seeded_timer.start()

    def _refresh_live_dj_pair(self):
        """Choose one canonical unordered sound pair and expose its stable ID."""
        names = list(getattr(self, "instrument_names_48", []) or [])
        active = []
        for name in names:
            mem = (getattr(self, "instrument_sequencer_memory", {}) or {}).get(name, {})
            steps = mem.get("steps", []) if isinstance(mem, dict) else []
            if any(bool(x) for x in steps):
                active.append(names.index(name))
            if len(active) >= 2:
                break
        if len(active) < 2:
            active = [0, 1]
        self._live_dj_pair_space = CommutativePairSpace(len(names) if len(names) >= 2 else 2)
        desc = self._live_dj_pair_space.descriptor(active[0], active[1])
        self._live_dj_pair_ids = (desc.a, desc.b)
        self._live_dj_pair_index = int(desc.index)
        self._live_dj_pair_signature = int(desc.signature)
        if not hasattr(self, "_live_dj_engine") or self._live_dj_engine is None:
            self._live_dj_engine = LiveDJEffects(sample_rate=int(getattr(self, "play_sample_rate", TARGET_SAMPLE_RATE) or TARGET_SAMPLE_RATE))
        self._live_dj_engine.pair_space = self._live_dj_pair_space
        self._cache_realtime_control_state()
        self._live_dj_engine.set_context(seed=float(getattr(self, "_rt_numeric_seed", 0.0)), pair=self._live_dj_pair_ids, sample_rate=int(getattr(self, "play_sample_rate", TARGET_SAMPLE_RATE) or TARGET_SAMPLE_RATE))

    def _live_dj_status(self):
        labels = []
        if getattr(self, "live_dj_goava", False):
            labels.append("GOAVA DJ")
        if getattr(self, "live_dj_random", False):
            labels.append("PARAM DJ")
        for key in EXTRA_DJ_EFFECTS:
            if getattr(self, f"live_dj_{key}", False):
                labels.append(key.replace("_", " ").upper())
        return " + ".join(labels) if labels else "OFF"

    def _on_live_dj_extra_toggled(self, key, checked):
        if key not in EXTRA_DJ_EFFECTS:
            return
        setattr(self, f"live_dj_{key}", bool(checked))
        slider = self.live_dj_extra_controls[key][1]
        setattr(self, f"live_dj_{key}_amount", slider.value() / 100.0 if checked else 0.0)
        self._refresh_live_dj_pair()
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText(f"LIVE DJ: {self._live_dj_status()}")

    def _on_live_dj_extra_amount_changed(self, key, value, label=None):
        amount = max(0, min(100, int(value))) / 100.0
        setattr(self, f"live_dj_{key}_amount", amount if getattr(self, f"live_dj_{key}", False) else 0.0)
        if label is not None:
            label.setText(f"{int(value)}%")

    def _live_dj_effects_snapshot(self):
        controls = getattr(self, "live_dj_extra_controls", {})
        return {key: {"enabled": bool(getattr(self, f"live_dj_{key}", False)),
                      "amount": controls[key][1].value() / 100.0 if key in controls
                      else float(getattr(self, f"live_dj_{key}_amount", 0.0))}
                for key in EXTRA_DJ_EFFECTS}

    def _restore_live_dj_effects(self, state):
        state = state if isinstance(state, dict) else {}
        controls = getattr(self, "live_dj_extra_controls", {})
        for key in EXTRA_DJ_EFFECTS:
            item = state.get(key, {})
            item = item if isinstance(item, dict) else {}
            enabled = bool(item.get("enabled", False))
            try:
                amount = float(item.get("amount", 0.55))
                amount = max(0.0, min(1.0, amount)) if math.isfinite(amount) else 0.55
            except (TypeError, ValueError):
                amount = 0.55
            setattr(self, f"live_dj_{key}", enabled)
            setattr(self, f"live_dj_{key}_amount", amount if enabled else 0.0)
            if key in controls:
                button, slider, label = controls[key]
                button.blockSignals(True); slider.blockSignals(True)
                button.setChecked(enabled); slider.setValue(int(round(amount * 100)))
                button.blockSignals(False); slider.blockSignals(False)
                label.setText(f"{slider.value()}%")

