    def _ab_store(self, slot):
        self.__dict__.setdefault("_ab_slots", {})[slot] = copy.deepcopy(self._project_snapshot())
        self._ab_active = slot
        self._ab_refresh_buttons()
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText(f"A/B · stored the current project in {slot}")

    def _ab_toggle(self):
        slots = getattr(self, "_ab_slots", {}) or {}
        cur = getattr(self, "_ab_active", "A")
        nxt = "B" if cur == "A" else "A"
        if nxt not in slots:
            QMessageBox.information(self, "A/B compare", f"Store {nxt} first (the current state goes into {cur} automatically).")
            if cur not in slots:
                self._ab_store(cur)
            return
        slots[cur] = copy.deepcopy(self._project_snapshot())   # keep edits made while on the current slot
        playing = bool(getattr(self, "is_playing", False))
        self._apply_project_snapshot(copy.deepcopy(slots[nxt]))
        try:
            self._refresh_after_file_input(reason="ab_compare")
        except Exception:
            pass
        self._ab_active = nxt
        self._ab_refresh_buttons()
        try:
            self._on_live_source_changed()
        except Exception:
            pass
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText(f"A/B · now hearing {nxt}" + (" (playback continues)" if playing else ""))

    def _ab_refresh_buttons(self):
        b = getattr(self, "_panel2_buttons", {}) or {}
        cur = getattr(self, "_ab_active", "A")
        slots = getattr(self, "_ab_slots", {}) or {}
        t = b.get("A⇄B")
        if t is not None:
            t.setText(f"A⇄B · {cur}" + ("" if slots else " (empty)"))

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_VIDEO_EXPORT_OFF_GUI_20261103
    # ------------------------------------------------------------------
    def _off_ui(self, fn, done=None):
        """Run fn() on a worker. done(result, error) is called on the UI thread.

        OFF_UI_20261106: buffer saves, file copies and sync must not stall
        the main window. The worker is a single shared executor.
        """
        ex = getattr(self, "_off_ui_pool", None)
        if ex is None:
            try:
                import thread_budget as _tb
                ex = self._off_ui_pool = _tb.make_lane("main-off-ui", max_workers=2, max_pending=96)
            except Exception:
                import concurrent.futures
                ex = self._off_ui_pool = concurrent.futures.ThreadPoolExecutor(
                    max_workers=1, thread_name_prefix="off-ui")
        def _finish(fut):
            try:
                res = fut.result()
                err = None
            except Exception as exc:
                res, err = None, exc
            if done is not None:
                try:
                    from ui_runtime import post_to_ui
                    post_to_ui(done, res, err, key=("off-ui-result", id(self), id(fut)))
                except Exception:
                    pass
        try:
            fut = ex.submit(fn)
            fut.add_done_callback(_finish)
            return fut
        except Exception as exc:
            if done is not None:
                done(None, exc)
            return None

    def _run_off_gui(self, fn):
        """Run fn() on the video-export worker while the GUI keeps processing
        events (the window stays responsive during long frame renders)."""
        if os.environ.get("GROOVEBOX_VIDEO_EXPORT_GUI_THREAD", "") == "1":
            return fn()
        ex = getattr(self, "_video_export_worker", None)
        if ex is None:
            try:
                import thread_budget as _tb
                ex = self._video_export_worker = _tb.make_lane("video-export", max_workers=1, max_pending=16)
            except Exception:
                from concurrent.futures import ThreadPoolExecutor
                ex = self._video_export_worker = ThreadPoolExecutor(max_workers=1, thread_name_prefix="groovebox-video-frame")
        fut = ex.submit(fn)
        # BUFFER_FREEZE_20261107: do not processEvents while waiting. A nested
        # event loop re-enters the UI and freezes it. Just wait for the result.
        return fut.result()

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_OWNERSHIP_VIEW_20261103
    # ------------------------------------------------------------------
    def _row_ownership(self, e):
        """Short tag + colour + description of who writes / bends this row."""
        if not isinstance(e, dict) or not e:
            return "·", "#3a3f45", "empty row"
        parts, desc = [], []
        if str(e.get("write_mode_owner")) == "user" or str(e.get("paint_source") or "").lower().startswith("user") or e.get("paint_instrument"):
            parts.append("U"); desc.append("you painted / set it")
        if e.get("heuristic_section"):
            parts.append("H"); desc.append("heuristic section")
        if str(e.get("paint_target") or "").startswith(("Canonical", "Unison")) or str(e.get("write_mode_owner")) == "canonical":
            parts.append("C"); desc.append("canonical")
        wm = str(e.get("write_mode") or "both")
        parts.append({"both": "SA", "step": "S", "automation": "A", "identity": "I"}.get(wm, "SA"))
        desc.append("writes " + {"both": "steps + automation", "step": "steps only", "automation": "automation only",
                                 "identity": "synth identity only"}.get(wm, wm))
        if e.get("algo_group"):
            parts.append("G:" + str(e["algo_group"])[:6]); desc.append(f"bent by group '{e['algo_group']}'")
        if e.get("row_transpose_semitones"):
            parts.append(f"{float(e['row_transpose_semitones']):+g}st"); desc.append("transposed")
        if e.get("active") is False:
            parts.append("off"); desc.append("thinned (inactive)")
        col = "#2c5a3a" if "U" in parts else ("#5a4a1c" if "H" in parts else ("#1f4250" if "C" in parts else "#3a3f45"))
        return " ".join(parts), col, " · ".join(desc)

    def _playlist_ownership_refresh(self, table=None):
        from PyQt6.QtWidgets import QTableWidgetItem as _TI
        tw = getattr(table or getattr(self, "active_paint_table", None), "table_widget", None)
        if tw is None:
            return
        data = getattr(self, "master_playlist_data", []) or []
        for r in range(min(tw.rowCount(), len(data))):
            tag, col, desc = self._row_ownership(data[r])
            it = _TI(f"{r + 1} {tag}")
            it.setToolTip(f"Row {r + 1}: {desc}")
            it.setBackground(QColor(col))
            tw.setVerticalHeaderItem(r, it)

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_SECTION_AB_20261103
    # ------------------------------------------------------------------
    def _section_ab(self, op, table=None):
        data = getattr(self, "master_playlist_data", None)
        if not isinstance(data, list) or not data:
            return
        st = self.__dict__.setdefault("_section_ab_slots", {})
        sel = self._playlist_selected_rows(table)
        if op in ("storeA", "storeB"):
            st[op[-1]] = {"rows": list(sel), "data": [copy.deepcopy(data[r]) for r in sel]}
            msg = f"section {op[-1]} stored ({len(sel)} rows)"
        else:
            cur = st.get("_active", "A"); nxt = "B" if cur == "A" else "A"
            if nxt not in st:
                QMessageBox.information(self, "Section A/B", f"Store section {nxt} first.")
                return
            if not getattr(self, "_undo_in_flight", False):
                self._push_undo("Section A/B swap")
            if cur in st:
                st[cur]["data"] = [copy.deepcopy(data[r]) if r < len(data) else {} for r in st[cur]["rows"]]
            for r, e in zip(st[nxt]["rows"], st[nxt]["data"]):
                while len(data) <= r:
                    data.append({})
                data[r] = copy.deepcopy(e)
            st["_active"] = nxt
            msg = f"now hearing section {nxt}"
            self.__dict__.pop("_row_bend_cache", None)
            try:
                self._sync_playlist_paint_table_from_memory(); self._on_live_source_changed()
            except Exception:
                pass
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("🧩 " + msg)

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_KEY_MAP_20261103
    # ------------------------------------------------------------------
    def _open_key_map(self):
        data = getattr(self, "master_playlist_data", []) or []
        banks = getattr(self, "instrument_sequence_banks", {}) or {}
        lines = []
        for r, e in enumerate(data):
            if not isinstance(e, dict):
                continue
            refs = [str(x) for x in (e.get("sequence_refs") or [])]
            ops = {x.rsplit("#S", 1)[0]: int(x.rsplit("#S", 1)[1]) for x in refs if "#S" in x and x.rsplit("#S", 1)[1].isdigit()}
            for op in str(e.get("operators_csv") or e.get("operator") or "").split(","):
                op = op.strip()
                if op and op not in ops:
                    ops[op] = int((getattr(self, "instrument_selected_sequence", {}) or {}).get(op, 1) or 1)
            for op, sid in ops.items():
                mem = (banks.get(op) or {}).get(sid)
                if not isinstance(mem, dict):
                    continue
                sc = mem.get("step_controls") or {}
                sd = sc.get("sidechain_depth") or []
                fx = sc.get("fx_probability") or []
                keys = [(k, float(v), float(fx[k]) if k < len(fx) else 1.0) for k, v in enumerate(sd) if isinstance(v, (int, float)) and v < 0]
                if keys:
                    avgp = sum(p for _k, _v, p in keys) / len(keys)
                    lines.append(f"row {r + 1:>4}  {op[:26]:<26} seq {sid:<3} keys on steps "
                                 + ", ".join(str(k + 1) for k, _v, _p in keys[:12]) + ("…" if len(keys) > 12 else "")
                                 + f"   depth {min(v for _k, v, _p in keys):+.2f}   fires ≈{avgp * 100:.0f}% of passes")
        dlg = QDialog(self); dlg.setWindowTitle("Key map — where negative-sidechain keys land")
        lay = QVBoxLayout(dlg)
        t = QTextEdit(); t.setReadOnly(True)
        t.setPlainText("\n".join(lines) if lines else "No negative-sidechain keys in the playlist yet.\n"
                       "Set a step's Sidechain below 0 (or let the canonical contour place rare keys).")
        t.setStyleSheet("font-family: monospace;")
        lay.addWidget(t); dlg.resize(820, 420); dlg.show(); self._key_map_dialog = dlg

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_STEP_INSPECTOR_20261103
    # ------------------------------------------------------------------
    def _open_step_inspector(self):
        try:
            name = self._current_instrument_name()
            sid = int(self._current_sequence_index(name))
            mem = self._current_sequence_mem(name)
        except Exception as exc:
            QMessageBox.warning(self, "Why?", str(exc)); return
        s = int(getattr(self, "selected_step_idx", 0) or 0)
        g = lambda key, d=None: (mem.get(key) or [])[s] if s < len(mem.get(key) or []) else d
        sc = mem.get("step_controls") or {}
        gl = lambda key, d=None: (sc.get(key) or [])[s] if s < len(sc.get(key) or []) else d
        owner = str(mem.get("canonical_owner") or ("user" if mem.get("user_owned") else "default"))
        L = [f"{name} · sequence {sid} · step {s + 1}", ""]
        L.append(f"Written by: {owner}" + (" (heuristic averaged with the prior values)" if mem.get("heuristic_averaged_with_prior") else ""))
        L.append(f"  step on: {bool(g('steps', False))}   level {g('amplitudes', 1.0)}   pitch ×{g('pitches', 1.0)}   "
                 f"offset {g('offsets', 0.0)}   prob {g('probabilities', 100)}%")
        L.append(f"  phase {gl('phase_shift', 0.0)} rad   band EQ {gl('eq_gain_db', 0.0)} dB @ {gl('eq_frequency', 1000.0)} Hz Q {gl('eq_q', 0.707)}")
        sd = gl("sidechain_depth", 0.0) or 0.0
        L.append(f"  sidechain {sd:+.2f} " + ("(KEY: lifts itself, ducks neighbours sharing its space)" if sd < 0 else "(ducks itself)" if sd > 0 else "")
                 + f"   FX prob {float(gl('fx_probability', 1.0) or 1.0) * 100:.0f}%")
        cc = mem.get("canonical_contour")
        if isinstance(cc, dict):
            L.append(f"Contour: shape {cc.get('shape', 0):+.2f} by {cc.get('owner')} over lanes {', '.join(cc.get('lanes') or [])}")
        cont = self._algo_contenders_for(name, sid)
        L.append("")
        L.append("Algorithms on this synth (averaged): " + (", ".join(f"{src} mix {m:.2f}" for src, _sc, m in cont) if cont else "none"))
        rows = [r for r, e in enumerate(getattr(self, "master_playlist_data", []) or [])
                if isinstance(e, dict) and (name in str(e.get("operators_csv") or e.get("operator") or "")
                                            or any(str(x).startswith(name + "#S") for x in (e.get("sequence_refs") or [])))]
        if rows:
            r0 = rows[0]
            b = self._algo_row_bend(r0)
            L.append(f"Row bend at row {r0 + 1} (first row it plays): offset {b['offset'] * 100:+.2f}% of row, "
                     f"pitch ×{b['pitch']:.4f}, level ×{b['amp']:.3f}; write mode {self._row_write_mode(r0)}")
            keys = []
            e0 = (getattr(self, "master_playlist_data", []) or [])[r0]
            for ref in (e0.get("sequence_refs") or []):
                op, _, sid_t = str(ref).partition("#S")
                if op == name or not sid_t.isdigit():
                    continue
                m2 = ((getattr(self, "instrument_sequence_banks", {}) or {}).get(op) or {}).get(int(sid_t)) or {}
                if any(isinstance(v, (int, float)) and v < 0 for v in ((m2.get("step_controls") or {}).get("sidechain_depth") or [])):
                    keys.append(op)
            L.append("Keys in that row that can duck this synth: " + (", ".join(keys) if keys else "none"))
        try:
            auto = self._get_sequencer_automation_for_step(rows[0] if rows else 0, s, name, mem)
            if isinstance(auto, dict):
                L.append(f"Automation at this step: morph {((auto.get('point') or {}).get('morph', '—'))}")
        except Exception:
            pass
        dlg = QDialog(self); dlg.setWindowTitle("Why does this step sound like this?")
        lay = QVBoxLayout(dlg); t = QTextEdit(); t.setReadOnly(True); t.setPlainText("\n".join(L))
        lay.addWidget(t); dlg.resize(760, 380); dlg.show(); self._step_inspector_dialog = dlg

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_FREEZE_BEND_20261103
    # ------------------------------------------------------------------
    def _on_freeze_bend_toggled(self, checked):
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("Freeze algorithm bend " + ("ON" if checked else "OFF"))
        snap = getattr(self, "_freeze_bend_snapshot", None)
        if not checked:
            if isinstance(snap, dict):
                for n, bank in snap["banks"].items():
                    self.instrument_sequence_banks[n] = copy.deepcopy(bank)
                self.global_algo_state["apply_enabled"] = snap["global_apply"]
                for n, on in snap["local"].items():
                    if n in (getattr(self, "local_algo_bays", {}) or {}):
                        self.local_algo_bays[n]["apply_enabled"] = on
                for n, on in snap["groups"].items():
                    if n in (getattr(self, "algo_group_bays", {}) or {}):
                        self.algo_group_bays[n]["apply_enabled"] = on
                self._freeze_bend_snapshot = None
            self.btn_gp_freeze.setText("❄ Freeze bend → start values · OFF")
        else:
            data = getattr(self, "master_playlist_data", []) or []
            bends = [self._algo_row_bend(r) for r in range(len(data))] or [self._ROW_BEND_IDENTITY]
            o = sum(b["offset"] for b in bends) / len(bends)
            _bp = [float(b["pitch"]) for b in bends]
            pr = float(np.exp(np.mean([math.log(p) for p in _bp]))) if all(p > 0 for p in _bp) else 0.0   # a 0 ratio zeroes the geometric mean
            a = sum(b["amp"] for b in bends) / len(bends)
            names = list(getattr(self, "instrument_names_48", []) or [])
            self._freeze_bend_snapshot = {
                "banks": {n: copy.deepcopy(self.instrument_sequence_banks.get(n, {})) for n in names},
                "global_apply": bool(self.global_algo_state.get("apply_enabled", False)),
                "local": {n: bool(b.get("apply_enabled")) for n, b in (getattr(self, "local_algo_bays", {}) or {}).items()},
                "groups": {n: bool(b.get("apply_enabled")) for n, b in (getattr(self, "algo_group_bays", {}) or {}).items()},
            }
            for n in names:
                sid = int((getattr(self, "instrument_selected_sequence", {}) or {}).get(n, 1) or 1)
                mem = (self.instrument_sequence_banks.get(n) or {}).get(sid)
                if not isinstance(mem, dict) or not mem.get("steps"):
                    continue
                L = len(mem["steps"])
                mem["pitches"] = [float(np.clip(float(x) * pr, 1.0 / 32.0, 32.0)) for x in (mem.get("pitches") or [1.0] * L)]
                mem["amplitudes"] = [float(np.clip(float(x) * a, 0.0, 2.0)) for x in (mem.get("amplitudes") or [1.0] * L)]
                mem["offsets"] = [float(np.clip(float(x) + o * L, -1.0, 1.0)) for x in (mem.get("offsets") or [0.0] * L)]
                mem["frozen_bend"] = {"offset_row": o, "pitch": pr, "amp": a}
            self.global_algo_state["apply_enabled"] = False
            for b in (getattr(self, "local_algo_bays", {}) or {}).values():
                b["apply_enabled"] = False
            for b in (getattr(self, "algo_group_bays", {}) or {}).values():
                b["apply_enabled"] = False
            self.btn_gp_freeze.setText(f"❄ Frozen: pitch ×{pr:.4f} · level ×{a:.3f} · offset {o * 100:+.2f}% · ON")
        self.__dict__.pop("_row_bend_cache", None)
        try:
            self._unapply_global_algo_from_ensemble()
            if self.global_algo_state.get("apply_enabled"):
                for k in ("script", "domain", "wire"):
                    if self.global_algo_state.get(k):
                        self._apply_global_algo_to_ensemble(k)
            self._apply_local_bays()
            self._gp_load_bay_to_ui()
            self.reload_active_instrument_sequencer_ui()
            self._on_live_source_changed()
        except Exception:
            pass

