    # GROOVEBOX_R23R_STEM_EXPORT_20261103 / RAW_EXPORT
    # ------------------------------------------------------------------
    def _open_stem_export_dialog(self, rows_from_selection=False, table=None):
        dlg = QDialog(self); dlg.setWindowTitle("Export stems / raw")
        lay = QVBoxLayout(dlg)
        from PyQt6.QtWidgets import QListWidget as _QLW, QAbstractItemView as _QAIV
        cmb = QComboBox(); cmb.addItems(["Full mix", "User stem only", "Canonical stem only", "User + Canonical (2 files)"])
        lay.addWidget(QLabel("What to render:")); lay.addWidget(cmb)
        rows_sel = self._playlist_selected_rows(table) if rows_from_selection else None
        chk_rows = QCheckBox(f"Only playlist rows {rows_sel[0] + 1}–{rows_sel[-1] + 1} ({len(rows_sel)} selected)" if rows_sel else "Only the selected playlist rows")
        chk_rows.setChecked(bool(rows_sel)); chk_rows.setEnabled(bool(rows_sel))
        lay.addWidget(chk_rows)
        lay.addWidget(QLabel("Instruments (multi-select; none = all):"))
        lst = _QLW(); lst.setSelectionMode(_QAIV.SelectionMode.ExtendedSelection)
        for n in (getattr(self, "instrument_names_48", []) or []):
            lst.addItem(n)
        lst.setMinimumHeight(160); lay.addWidget(lst)
        chk_raw = QCheckBox("RAW — no FX processing (lattice, EQ, band EQ, sidechain, keys, DJ bake skipped; ~2× faster). "
                            "Loudness match and the master hard clip still apply.")
        chk_raw.setChecked(False); lay.addWidget(chk_raw)
        btn = QPushButton("Render + save…"); lay.addWidget(btn)

        def go():
            insts = [i.text() for i in lst.selectedItems()]
            mode = cmb.currentText()
            jobs = {"Full mix": [None], "User stem only": ["user"], "Canonical stem only": ["canonical"],
                    "User + Canonical (2 files)": ["user", "canonical"]}[mode]
            base = self._export_name("stem", ".wav", self._exports_dir()) if hasattr(self, "_export_name") else os.path.join(str(self._exports_dir()), "stem.wav")
            path, _f = QFileDialog.getSaveFileName(dlg, "Save stem(s)", str(base), "WAV (*.wav)")
            if not path:
                return
            dlg.accept()
            self._render_stems(path, jobs, rows=(set(rows_sel) if (rows_sel and chk_rows.isChecked()) else None),
                               instruments=(set(insts) if insts else None), raw=chk_raw.isChecked())
        btn.clicked.connect(go)
        dlg.show(); self._stem_dialog = dlg

    def _render_stems(self, path, jobs, rows=None, instruments=None, raw=False):
        """EXPORT_SCHEDULER_R31: each stem is its own worker-process job on the project frozen now.
        (Was: render + write on the UI thread via blocking _run_off_gui waits.)"""
        root, ext = os.path.splitext(str(path))
        queued = []
        for bus in jobs:
            out = path if len(jobs) == 1 else f"{root}_{bus or 'mix'}{ext or '.wav'}"
            opts = {"bus": bus, "rows": sorted(int(r) for r in rows) if rows else None,
                    "instruments": sorted(str(i) for i in instruments) if instruments else None, "raw": bool(raw)}
            job = self._export_scheduler().submit_job(
                "stem_file", out, opts, label="STEM %s%s · %s" % ("raw " if raw else "", bus or "full", os.path.basename(out)))
            queued.append(job)
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText(f"🎚 {len(queued)} stem job(s) queued · rendering in worker processes")
        self.show_export_jobs()
        return [j.out_file for j in queued]

