    def trigger_note_at_hz(self, hz, dur=0.9):
        """Trigger Note at an explicit frequency — raw voice, fixed gain (NO_FADE_NO_LIMIT_20261102)."""
        try:
            self._ensure_hardware_use("trigger-note")
            name = self._current_instrument_name()
            sr = 44100
            t = np.arange(int(sr * dur), dtype=np.float64) / sr
            mix = np.nan_to_num((0.28 * self._render_instrument_voice(name, float(hz), t, dur, sr)).astype(np.float32),
                                nan=0.0, posinf=0.0, neginf=0.0)
            if HAS_SOUNDDEVICE:
                self._pkp_poly_submit(mix, sr)
        except Exception as exc:
            _gb_log_error("trigger note at hz", exc)

    def _toggle_keyboard_notes(self):
        on = not bool(getattr(self, "_keychart_enabled", True))
        self._keychart_enabled = on
        if on and getattr(self, "_keychart_filter", None) is None:
            self._install_keychart()
        b = (getattr(self, "_panel2_buttons", {}) or {}).get("⌨ Keys play notes")
        if b is not None:
            b.setText("⌨ Keys play notes · " + ("ON" if on else "off"))
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("⌨ Key chart keys " + ("play the selected instrument" if on else "are off"))

    def _open_key_chart(self):
        return self._show_key_chart_dialog()

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_VIDEO_CHUNK_PIPELINE_20261103
    # ------------------------------------------------------------------
    def _pipelined_frames(self, produce, f0, f1, chunk=None):
        """Yield (fi, frame) in order. A single worker renders chunks of
        `chunk` frames ahead (bounded queue of 2 chunks) — frame order and
        engine state stay exactly sequential — while the caller writes frames
        and the GUI keeps processing events."""
        import queue, threading
        _dchunk = 24
        try:   # R32.8 DYNAMIC_RAM: smaller frame chunks on small rigs / under memory pressure
            import resource_governor as _rg
            _dchunk = int(_rg.recommend()["video_chunk"])
        except Exception:
            pass
        chunk = int(chunk or os.environ.get("GROOVEBOX_VIDEO_CHUNK", "") or _dchunk)  # EXPORT_SPEED_20261107
        if os.environ.get("GROOVEBOX_VIDEO_EXPORT_GUI_THREAD", "") == "1":
            for fi in range(f0, f1):
                yield fi, produce(fi)
            return
        q = queue.Queue(maxsize=2)
        stop = threading.Event()

        def worker():
            try:
                for c0 in range(f0, f1, chunk):
                    if stop.is_set():
                        return
                    q.put([(fi, produce(fi)) for fi in range(c0, min(f1, c0 + chunk))])
                q.put(None)
            except BaseException as exc:
                q.put(exc)
        th = threading.Thread(target=worker, name="groovebox-video-chunks", daemon=True)
        th.start()
        try:
            while True:
                try:
                    item = q.get(timeout=0.05)
                except queue.Empty:
                    # EXPORT_SPEED_20261106: yield without nested processEvents so a
                    # stalled window cannot re-enter the export and stall the UI.
                    continue
                if item is None:
                    return
                if isinstance(item, BaseException):
                    raise item
                for fi, fr in item:
                    yield fi, fr
        finally:
            stop.set()
            try:
                while True:
                    q.get_nowait()
            except Exception:
                pass

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_FRACTAL_SEED_MOD_20261103 — mod the track by the seed L-system
    # ------------------------------------------------------------------
    def _fractal_mod_state(self):
        st = getattr(self, "fractal_seed_mod", None)
        if not isinstance(st, dict):
            st = self.fractal_seed_mod = {"amount": 0.0, "pitch": True, "level": True, "timing": False}
        return st

    def _fractal_seed_mod_row(self, row_idx):
        """(pitch ratio, level factor, offset as row fraction) for this playlist row, or None."""
        st = self._fractal_mod_state()
        amt = float(st.get("amount", 0.0) or 0.0)
        if amt <= 0.0:
            return None
        try:
            if "fractal_seed" in self._get_active_engine_set():
                return None          # the engine itself is writing the sequences
        except Exception:
            pass
        rows = getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or []
        n = max(1, len(rows))
        try:
            plan = self._fractal_seed_event_plan()
            key = (id(plan), n)
            cache = getattr(self, "_fractal_mod_cache", None)
            if not cache or cache[0] != key:
                from groovebox_v3.fractal_seed_engine import rasterize_sequence
                cache = self._fractal_mod_cache = (key, rasterize_sequence(plan, n))
            ras = cache[1]
            i = int(row_idx) % n
            _rp = float(ras["pitches"][i])
            semis = 12.0 * math.log2(_rp) if _rp > 0 else -12.0   # 0 ratio = the bottom of the ±12 range
            semis = max(-12.0, min(12.0, semis))
            vel = float(ras["amplitudes"][i]) if ras["steps"][i] else 0.5
        except Exception:
            return None
        pr = project_semitone_ratio(amt * semis) if st.get("pitch", True) else 1.0
        lv = (1.0 + amt * (vel - 1.0 + 0.5)) if st.get("level", True) else 1.0
        off = (amt * (semis / 12.0) / 32.0) if st.get("timing", False) else 0.0
        return float(pr), float(max(0.0, lv)), float(off)

    def _build_fractal_seed_mod_menu(self):
        from PyQt6.QtWidgets import QWidgetAction
        btn = QToolButton(); btn.setText("🌿 Seed L-system mod ▾")
        btn.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup)
        btn.setToolTip("Modulate the whole track by the seed's L-system while Fractal Seed is OFF "
                       "(pitch / level / timing per playlist row). Default 0 % = no influence.")
        menu = QMenu(btn)
        box = QWidget(); lay = QVBoxLayout(box); lay.setContentsMargins(10, 8, 10, 8)
        st = self._fractal_mod_state()
        lbl = QLabel(""); lay.addWidget(lbl)
        sld = QSlider(Qt.Orientation.Horizontal); sld.setRange(0, 100); sld.setValue(int(round(float(st["amount"]) * 100)))
        sld.setMinimumWidth(220); lay.addWidget(sld)
        chks = {}
        for k, t in (("pitch", "Pitch (L-system intervals)"), ("level", "Level (L-system velocity)"), ("timing", "Timing (small row offset)")):
            c = QCheckBox(t); c.setChecked(bool(st.get(k))); lay.addWidget(c); chks[k] = c
        note = QLabel("Only acts while the Fractal Seed engine is off."); note.setStyleSheet("color:#8da5b8;"); lay.addWidget(note)

        def upd(*_a):
            st["amount"] = sld.value() / 100.0
            for k, c in chks.items():
                st[k] = c.isChecked()
            lbl.setText(f"Amount: {sld.value()} %")
            btn.setText("🌿 Seed L-system mod " + (f"{sld.value()} % ▾" if sld.value() else "▾"))
            self.__dict__.pop("_fractal_mod_cache", None)
        sld.valueChanged.connect(upd)
        for c in chks.values():
            c.toggled.connect(upd)
        upd()
        wa = QWidgetAction(menu); wa.setDefaultWidget(box); menu.addAction(wa)
        btn.setMenu(menu)
        self._fractal_mod_widgets = (sld, chks, btn)
        return btn

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_INSTRUMENT_BAYS_20261103 — per-instrument Local bays
    # ------------------------------------------------------------------
    def _local_algo_bay(self, name, create=False):
        bays = self.__dict__.setdefault("local_algo_bays", {})
        bay = bays.get(str(name))
        if bay is None and create:
            g = getattr(self, "global_algo_state", {}) or {}
            # A new local bay starts as a PROPOSAL copied from the global algo.
            bay = {"script": str(g.get("script") or ""), "domain": str(g.get("domain") or ""),
                   "params": copy.deepcopy(g.get("params") or {"mix": 0.35}), "apply_enabled": False,
                   "sequence": "all", "proposed_from": "global"}
            bays[str(name)] = bay
        return bay

    def _local_algo_for(self, name, sequence_id=None):
        bay = (getattr(self, "local_algo_bays", {}) or {}).get(str(name))
        if not isinstance(bay, dict) or not bay.get("apply_enabled") or not str(bay.get("script") or "").strip():
            return None, 0.0
        sq = bay.get("sequence", "all")
        if sq not in (None, "all", 0) and sequence_id is not None and int(sq) != int(sequence_id):
            return None, 0.0
        return str(bay["script"]), float(np.clip((bay.get("params") or {}).get("mix", 0.35), 0.0, 1.0))

    def _gp_bay(self):
        """The bay the Global Play Patcher is editing right now."""
        if getattr(self, "combo_gp_scope", None) is not None and self.combo_gp_scope.currentText() == "GROUP":
            name = (self.combo_gp_group.currentText().strip() if getattr(self, "combo_gp_group", None) is not None else "") or "group 1"
            bays = self.__dict__.setdefault("algo_group_bays", {})
            if name not in bays:
                g = getattr(self, "global_algo_state", {}) or {}
                bays[name] = {"script": str(g.get("script") or ""), "domain": "", "params": copy.deepcopy(g.get("params") or {"mix": 0.35}),
                              "apply_enabled": False, "proposed_from": "global"}
            return bays[name]
        if getattr(self, "combo_gp_scope", None) is not None and self.combo_gp_scope.currentText() == "LOCAL":
            try:
                name = self._current_instrument_name()
            except Exception:
                name = (list(getattr(self, "instrument_names_48", []) or ["Operator"]) or ["Operator"])[0]
            return self._local_algo_bay(name, create=True)
        if not isinstance(getattr(self, "global_algo_state", None), dict):
            self.global_algo_state = {}
        return self.global_algo_state

    def _gp_load_bay_to_ui(self):
        bay = self._gp_bay()
        w = [getattr(self, n, None) for n in ("gp_script_field", "gp_domain_field", "gp_mix_slider", "gp_script_slider",
                                                "gp_domain_slider", "gp_wire_slider", "btn_apply_algo_master")]
        if any(x is None for x in w):
            return
        self._gp_loading_bay = True
        try:
            for x in w:
                x.blockSignals(True)
            p = bay.get("params") if isinstance(bay.get("params"), dict) else {}
            self.gp_script_field.setPlainText(str(bay.get("script") or ""))
            self.gp_domain_field.setText(str(bay.get("domain") or "").replace("\n", " "))
            self.gp_mix_slider.setValue(int(float(p.get("mix", 0.35)) * 100))
            self.gp_script_slider.setValue(int(float(p.get("script_amount", 1.0)) * 100))
            self.gp_domain_slider.setValue(int(float(p.get("domain_amount", 1.0)) * 100))
            self.gp_wire_slider.setValue(int(float(p.get("wire_amount", 1.0)) * 100))
            on = bool(bay.get("apply_enabled", False))
            self.btn_apply_algo_master.setChecked(on)
            _sc_txt = self.combo_gp_scope.currentText()
            self.btn_apply_algo_master.setText(("■ Unapply " if on else "▶ Apply ") + (
                "Local Algo" if _sc_txt == "LOCAL" else "Group Algo" if _sc_txt == "GROUP" else "Algo to Master Mix"))
        finally:
            for x in w:
                x.blockSignals(False)
            self._gp_loading_bay = False
        self._refresh_gp_local_label()
        self._refresh_canonical_explain()

    def _apply_local_bays(self):
        """Write/refresh the overlay of every applied local bay (and clear the rest)."""
        names = list(getattr(self, "instrument_names_48", []) or [])
        engine = getattr(self, "domain_eq_engine", None)
        doms = [d for d in (getattr(engine, "domains", []) or []) if not (isinstance(d, dict) and d.get("source") == "local_player")] if engine is not None else []
        applied = {}
        for name in names:
            st = (getattr(self, "instrument_param_state", {}) or {}).setdefault(name, {})
            bay = (getattr(self, "local_algo_bays", {}) or {}).get(name)
            if isinstance(bay, dict) and bay.get("apply_enabled") and str(bay.get("script") or bay.get("domain") or "").strip():
                st["local_script_algo"] = str(bay.get("script") or "")
                st["local_algo_mix"] = float((bay.get("params") or {}).get("mix", 0.35))
                applied[name] = bay.get("sequence", "all")
                body = str(bay.get("domain") or "").strip()
                if body and engine is not None:
                    doms.append({"name": f"local_player::{name}", "axis": "time", "t0": 0.0, "t1": 1.0,
                                 "x0": -1.0, "x1": 1.0, "y0": -1.0, "y1": 1.0, "logic": "True",
                                 "equation": body.split("equation =", 1)[-1].strip().strip('"').strip("'") if "equation =" in body else body,
                                 "limit_lo": -1.0, "limit_hi": 1.0,
                                 "weight": float((bay.get("params") or {}).get("mix", 0.35)) * float((bay.get("params") or {}).get("domain_amount", 1.0)),
                                 "user_defined": False, "source": "local_player", "user_data": True, "instrument": name})
            else:
                st.pop("local_script_algo", None); st.pop("local_algo_mix", None)
        if engine is not None:
            engine.domains = doms
        for row in (getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or []):
            if isinstance(row, dict):
                if applied:
                    row["local_algorithm_bays"] = dict(applied)
                    row["global_algorithm_scope"] = "global+local" if (getattr(self, "global_algo_state", {}) or {}).get("apply_enabled") else "local"
                else:
                    row.pop("local_algorithm_bays", None)
                    if row.get("global_algorithm_scope") in ("local", "global+local"):
                        if (getattr(self, "global_algo_state", {}) or {}).get("apply_enabled"):
                            row["global_algorithm_scope"] = "global"
                        else:
                            row.pop("global_algorithm_scope", None)
        return applied

    def _heuristic_bay_store(self):
        if getattr(self, "_heur_loading_bay", False) or not hasattr(self, "combo_heuristic_family"):
            return
        bays = self.__dict__.setdefault("heuristic_bays", {"global": {}, "local": {}})
        rec = {"family": self.combo_heuristic_family.currentText(), "bias": self.combo_heuristic_bias.currentText(),
               "span": int(self.spin_heuristic_span.value())}
        if self.combo_heuristic_scope.currentText() == "GLOBAL":
            bays["global"] = rec
        else:
            try:
                name = self._current_instrument_name()
            except Exception:
                return
            bays.setdefault("local", {})[str(name)] = rec

    def _heuristic_bay_load(self):
        if not hasattr(self, "combo_heuristic_family"):
            return
        bays = getattr(self, "heuristic_bays", None) or {}
        if self.combo_heuristic_scope.currentText() == "GLOBAL":
            rec = bays.get("global") or {}
        else:
            try:
                rec = (bays.get("local") or {}).get(str(self._current_instrument_name())) or bays.get("global") or {}
            except Exception:
                rec = {}
        if not rec:
            return
        self._heur_loading_bay = True
        try:
            for w, key in ((self.combo_heuristic_family, "family"), (self.combo_heuristic_bias, "bias")):
                w.blockSignals(True)
                if rec.get(key):
                    w.setCurrentText(str(rec[key]))
                w.blockSignals(False)
            self.spin_heuristic_span.blockSignals(True)
            self.spin_heuristic_span.setValue(int(rec.get("span", self.spin_heuristic_span.value())))
            self.spin_heuristic_span.blockSignals(False)
        finally:
            self._heur_loading_bay = False

    def _on_bays_instrument_switched(self):
        try:
            if getattr(self, "combo_gp_scope", None) is not None and self.combo_gp_scope.currentText() == "LOCAL":
                self._gp_load_bay_to_ui()
            if getattr(self, "combo_heuristic_scope", None) is not None and self.combo_heuristic_scope.currentText() == "LOCAL":
                self._heuristic_bay_load()
            self._refresh_canonical_explain()
        except Exception as exc:
            print(f"[Bays] instrument switch: {exc}")

    def _refresh_canonical_explain(self):
        """Highlighted, line-by-line summary of active heuristic writers / the
        Global-Local Algorithm and what the canonicals append alongside them."""
        try:
            on = lambda b: bool(b is not None and b.isChecked())
            dot = lambda x: "<b style='color:#7dffa0'>● ON</b>" if x else "<span style='color:#7a8690'>○ off</span>"
            scope = str(self.combo_heuristic_scope.currentText()) if hasattr(self, "combo_heuristic_scope") else "LOCAL"
            names = list(getattr(self, "instrument_names_48", []) or [])
            n_ser = sum(1 for n in names if self._heuristic_instrument_mode(n) == "series")
            try:
                cur = self._current_instrument_name()
            except Exception:
                cur = ""
            hl = (f"<b>Heuristic</b> · scope <b>{scope}</b> · "
                  + (f"<b style='color:#ffd166'>{'Series lock' if getattr(self, 'heuristic_series_lock', False) else 'Ensemble'}</b> "
                     f"({n_ser} series / {len(names) - n_ser} ensemble)" if scope == "GLOBAL" else f"local bay: <b>{cur}</b>")
                  + f"<br>STEP {dot(on(getattr(self, 'btn_heuristic_write_step', None)))} · "
                  f"AUTOMATION {dot(on(getattr(self, 'btn_heuristic_write_automation', None)))} · "
                  f"SEQ SYNTH {dot(on(getattr(self, 'btn_heuristic_seq_synth', None)))} · "
                  f"GEOMETRIC {dot(on(getattr(self, 'btn_heuristic_write_geo', None)))}"
                  "<br><span style='background:#2b3a12; color:#e9ffb0'>&nbsp;Canonicals never write heuristic effects: "
                  "heuristic-written steps, automation, sequence synths and geometrics stay exactly as written.&nbsp;</span>"
                  "<br><span style='background:#2b3a12; color:#e9ffb0'>&nbsp;Canonicals append beside them only: contour lanes on "
                  "their own canonical sequences (phase, probability, EQ, sidechain, envelope, automation).&nbsp;</span>")
            if getattr(self, "lbl_heuristic_explain", None) is not None:
                self.lbl_heuristic_explain.setText(hl)
            gas = getattr(self, "global_algo_state", {}) or {}
            g_applied = bool(gas.get("apply_enabled", False))
            bays = getattr(self, "local_algo_bays", {}) or {}
            local_on = [n for n in names if isinstance(bays.get(n), dict) and bays[n].get("apply_enabled")]
            umix = float((gas.get("params") or {}).get("mix", 0.35) or 0.35)
            proj = getattr(self, "_canonical_global_algo_projection", None)
            cmix = float(((proj or {}).get("params") or {}).get("mix", 0.0) or 0.0) if isinstance(proj, dict) else 0.0
            engines = bool(self._get_active_engine_set()) if hasattr(self, "_get_active_engine_set") else False
            editing = "LOCAL bay · " + cur if (getattr(self, "combo_gp_scope", None) is not None and self.combo_gp_scope.currentText() == "LOCAL") else "GLOBAL bay"
            lines = [f"Editing <b>{editing}</b> · GLOBAL algo " + ("<b style='color:#7dffa0'>applied</b>" if g_applied else "<span style='color:#7a8690'>not applied</span>")
                     + f" · local algos applied on <b>{len(local_on)}</b> synth(s)"]
            if local_on:
                lines.append("<span style='background:#3a2f0a; color:#ffe9a8'>&nbsp;Local Algorithm write: "
                             + ", ".join(local_on[:6]) + ("…" if len(local_on) > 6 else "")
                             + " run their own bay; where the GLOBAL algo is also applied the two are AVERAGED per value. "
                             "Playlist rows record local_algorithm_bays.&nbsp;</span>")
            if (g_applied or local_on) and bool((gas.get("params") or {}).get("row_bend", True)):
                _rb0 = self._algo_row_bend(0)
                lines.append("<span style='background:#3a1f3a; color:#ffd6ff'>&nbsp;Algorithm bends (never writes): playlist rows as groups — "
                             f"row 1 now: offset {(_rb0['offset'] * 100):+.2f}% of the row for every synth, pitch ×{_rb0['pitch']:.4f}, "
                             f"level ×{_rb0['amp']:.3f}. The Heuristic composes the start values.&nbsp;</span>")
            if engines and cmix > 0.0:
                lines.append("<span style='background:#0f3a45; color:#bff4ff'>&nbsp;Canonicals READ your global + local bays, scope, "
                             "mix and heuristic modes — they never edit them.&nbsp;</span>")
                lines.append(f"<span style='background:#0f3a45; color:#bff4ff'>&nbsp;Canonicals append a parallel fix (mix {cmix:.2f}) "
                             f"on all {len(names)} synths as one more contender: on each value the result is the AVERAGE of "
                             f"global · local · canonical — they fight evenly; none overwrites another.&nbsp;</span>")
            else:
                lines.append("<span style='color:#7a8690'>No canonical engine active: nothing is appended.</span>")
            if getattr(self, "lbl_gp_explain", None) is not None:
                self.lbl_gp_explain.setText("<br>".join(lines))
        except Exception as exc:
            print(f"[UI] canonical explain: {exc}")

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_LOCAL_ALGORITHM_20261103 — Global Play Patcher scope
    # ------------------------------------------------------------------
    def _gp_local_targets(self):
        """Synths whose own Local Algorithm bay is applied."""
        out = []
        for name, bay in (getattr(self, "local_algo_bays", {}) or {}).items():
            if isinstance(bay, dict) and bay.get("apply_enabled"):
                out.append({"instrument": str(name), "sequence": bay.get("sequence", "all")})
        return out

    def _global_algo_applies_to(self, instrument_name, sequence_id=None):
        """The GLOBAL algo (when applied) drives every synth; a synth's applied
        Local bay is averaged with it (see _algo_contenders_for), not a replacement."""
        return True

    def _algo_contenders_for(self, instrument_name, sequence_id=None):
        """[(source, script, mix)] of every algorithm active on this synth:
        the applied GLOBAL algo, the synth's applied LOCAL bay and the canonical
        parallel fix. Consumers AVERAGE their bounded outputs per value."""
        out = []
        g = getattr(self, "global_algo_state", {}) or {}
        if bool(g.get("apply_enabled", False)) and str(g.get("script") or "").strip():
            out.append(("global", str(g["script"]), float(np.clip((g.get("params") or {}).get("mix", 0.35), 0.0, 1.0))))
        ls, lm = self._local_algo_for(instrument_name, sequence_id)
        if ls:
            out.append(("local", ls, lm))
        cs, cm = self._canonical_parallel_algo_for(instrument_name, sequence_id)
        if cs and cm > 0.0:
            out.append(("canonical", cs, cm))
        return out

    def _refresh_gp_local_label(self):
        lbl = getattr(self, "lbl_gp_local_target", None)
        if lbl is None:
            return
        if getattr(self, "combo_gp_scope", None) is None or self.combo_gp_scope.currentText() != "LOCAL":
            lbl.setText("all synths")
            return
        try:
            name = self._current_instrument_name()
        except Exception:
            name = "?"
        bay = self._local_algo_bay(name) or {}
        sq = bay.get("sequence", "all")
        lbl.setText(f"{name} · seq {sq} · " + ("applied" if bay.get("apply_enabled") else "proposal"))

    def _wrap_wide_main_rows(self):
        """Preserve the wide editor layout; both outer canvases scroll biaxially."""
        try:
            lay = getattr(self, "global_geometry_layout", None)
            if lay is not None and lay.count() >= 2:
                lay.setStretch(0, 3)
                lay.setStretch(1, 1)
            self._compact_top_sequencer()
            # no layout-wrap message
        except Exception as exc:
            print(f"[Layout] row wrapping skipped: {exc}")

    def _on_gp_scope_changed(self, retarget=False):
        """GLOBAL ↔ LOCAL switches which bay the patcher edits; ◎ Target
        binds the local bay to the selected sequence (or back to all)."""
        gas = self.global_algo_state if isinstance(getattr(self, "global_algo_state", None), dict) else {}
        self.global_algo_state = gas
        _scope_txt = self.combo_gp_scope.currentText() if getattr(self, "combo_gp_scope", None) else "GLOBAL"
        local = (_scope_txt == "LOCAL")
        _grp  = (_scope_txt == "GROUP")
        _rhythm = (_scope_txt == "RHYTHM")
        _melody = (_scope_txt == "MELODY")
        # RHYTHM_MELODY_SCOPE_VISIBILITY: show dedicated algo fields for rhythm/melody scopes
        if getattr(self, "_gp_rhythm_widget", None) is not None:
            self._gp_rhythm_widget.setVisible(_rhythm)
        if getattr(self, "_gp_melody_widget", None) is not None:
            self._gp_melody_widget.setVisible(_melody)
        # Update button label to match scope
        if getattr(self, "btn_apply_algo_master", None) is not None:
            if _rhythm:
                self.btn_apply_algo_master.setText("▶ Apply RHYTHM Algo to Playlist")
            elif _melody:
                self.btn_apply_algo_master.setText("▶ Apply MELODY Algo to Playlist")
        gas["scope"] = ("local" if local else ("group" if _grp else
                        ("rhythm" if _rhythm else ("melody" if _melody else "global"))))
        if getattr(self, "combo_gp_group", None) is not None:
            self.combo_gp_group.setVisible(_grp)
            if _grp:
                _names = sorted(set(list((getattr(self, "algo_group_bays", {}) or {}).keys()) + [
                    str(e.get("algo_group")) for e in (getattr(self, "master_playlist_data", []) or [])
                    if isinstance(e, dict) and e.get("algo_group")]))
                _cur = self.combo_gp_group.currentText()
                self.combo_gp_group.blockSignals(True)
                self.combo_gp_group.clear(); self.combo_gp_group.addItems(_names or ["group 1"])
                if _cur:
                    self.combo_gp_group.setCurrentText(_cur)
                self.combo_gp_group.blockSignals(False)
        if local and retarget:
            if not getattr(self, "_undo_in_flight", False):
                self._push_undo("Local Algorithm target")
            name = self._current_instrument_name()
            bay = self._local_algo_bay(name, create=True)
            sid = int(self._current_sequence_index(name))
            bay["sequence"] = "all" if bay.get("sequence") == sid else sid
            if bay.get("apply_enabled"):
                self._apply_local_bays()
        self._gp_load_bay_to_ui()
        try:
            self._on_live_source_changed()
        except Exception:
            pass
        QTimer.singleShot(0, self._refresh_canonical_explain)

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_HEURISTIC_SERIES_LOCK_20261103
    # ------------------------------------------------------------------
    def _heuristic_instrument_mode(self, name):
        modes = getattr(self, "heuristic_instrument_modes", None)
        if isinstance(modes, dict) and str(name) in modes:
            return "series" if str(modes[str(name)]).lower().startswith("ser") else "ensemble"
        return "series" if bool(getattr(self, "heuristic_series_lock", False)) else "ensemble"

    def _heuristic_series_plan(self, targets, family, bias, n, scope):
        """Series mode: one continuous heuristic run split across the ensemble.

        Target k (among those in Series mode, in ensemble order) takes the
        segment [k·n, (k+1)·n) of the run, so patterns are written in series
        rather than replicated. Periodic families (modular / lattice) can
        repeat a segment; any repeat is replaced deterministically (further
        along the run, then rotated, then mirrored, then seed-phase blended)
        until every written pattern - values AND resulting step mask - is unique.
        """
        if str(scope).upper() != "GLOBAL":
            return {}
        series_targets = [(nm, int(sd)) for nm, sd in targets if self._heuristic_instrument_mode(nm) == "series"]
        if not series_targets:
            return {}
        n = max(1, int(n))
        out, seen = {}, set()

        def key(vv):
            return tuple(round(float(x), 6) for x in vv)

        thr = 0.58
        if bias == "Sparse": thr = 0.70
        elif bias == "Dense": thr = 0.42
        elif bias in ("Self-Similar", "T-Independent"): thr = 0.52

        def mask(vv):
            m = [bool(x >= thr) for x in vv]
            if vv and not any(m):            # the writer then enables the strongest step
                m[max(range(len(vv)), key=lambda i: vv[i])] = True
            return tuple(m)

        seen_mask = set()
        for k, tgt in enumerate(series_targets):
            vv = self._heuristic_values(family, bias, n, start=k * n)
            attempt = 0
            while (key(vv) in seen or (mask(vv) in seen_mask and len(seen_mask) < 2 ** min(n, 20))) and attempt < 48:
                attempt += 1
                if attempt <= 12:
                    vv = self._heuristic_values(family, bias, n, start=(len(series_targets) + k + attempt * 7) * n + attempt)
                elif attempt <= 24:
                    r = (attempt * 5 + k) % n
                    vv = vv[r:] + vv[:r]
                elif attempt <= 30:
                    vv = list(reversed(vv))
                else:
                    ph = (k + 1) * MEUM + attempt * PHI
                    vv = [float(np.clip(0.80 * x + 0.20 * (0.5 + 0.5 * series_sin(ph + j * MEUM_INV)), 0.0, 1.0))
                          for j, x in enumerate(vv)]
            if mask(vv) in seen_mask and len(seen_mask) < 2 ** min(n, 20):
                # Last resort: flip single steps (deterministic positions) across
                # the writer threshold until the written step mask is unique.
                vv = list(vv)
                for j in [((k * 7 + q * 3) % n) for q in range(n)]:
                    old = vv[j]
                    vv[j] = (thr + 0.01) if old < thr else (thr - 0.01)
                    if mask(vv) not in seen_mask:
                        break
                    vv[j] = old
            seen.add(key(vv)); seen_mask.add(mask(vv))
            out[tgt] = vv
        return out

    def _on_heuristic_series_lock_toggled(self, checked):
        self.heuristic_series_lock = bool(checked)
        # Re-run active writers with the new mode (their own revert memory first).
        try:
            self._on_heuristic_scope_changed()
        except Exception:
            pass
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("Heuristic GLOBAL writes · " + ("SERIES (unique per instrument)" if checked else "ENSEMBLE (replicated)"))

    def _open_heuristic_modes_dialog(self):
        dlg = QDialog(self)
        dlg.setWindowTitle("Heuristic modes per instrument")
        lay = QVBoxLayout(dlg)
        lay.addWidget(QLabel("GLOBAL heuristic writes: Series = this instrument takes its own unique segment;\n"
                             "Ensemble = it receives the shared (rotated) pattern. Default follows the Lock checkbox."))
        from PyQt6.QtWidgets import QScrollArea as _QSA, QFormLayout as _QFL
        area = _QSA(); area.setWidgetResizable(True); inner = QWidget(); form = _QFL(inner); area.setWidget(inner)
        modes = self.__dict__.setdefault("heuristic_instrument_modes", {})
        combos = {}
        for name in list(getattr(self, "instrument_names_48", []) or []):
            cb = QComboBox(); cb.addItems(["Default", "Series", "Ensemble"])
            cur = modes.get(str(name))
            cb.setCurrentText("Series" if cur == "series" else ("Ensemble" if cur == "ensemble" else "Default"))
            form.addRow(str(name), cb); combos[str(name)] = cb
        lay.addWidget(area, 1)
        row = QHBoxLayout()
        b_all_s = QPushButton("All Series"); b_all_e = QPushButton("All Ensemble"); b_def = QPushButton("All Default")
        b_ok = QPushButton("Apply")
        for b in (b_all_s, b_all_e, b_def, b_ok):
            row.addWidget(b)
        lay.addLayout(row)
        b_all_s.clicked.connect(lambda: [c.setCurrentText("Series") for c in combos.values()])
        b_all_e.clicked.connect(lambda: [c.setCurrentText("Ensemble") for c in combos.values()])
        b_def.clicked.connect(lambda: [c.setCurrentText("Default") for c in combos.values()])

        def apply():
            if not getattr(self, "_undo_in_flight", False):
                self._push_undo("Heuristic instrument modes")
            new = {}
            for nm, c in combos.items():
                if c.currentText() != "Default":
                    new[nm] = c.currentText().lower()
            self.heuristic_instrument_modes = new
            try:
                self._on_heuristic_scope_changed()
            except Exception:
                pass
            dlg.accept()
        b_ok.clicked.connect(apply)
        dlg.resize(460, 560)
        dlg.show()
        self._heuristic_modes_dialog = dlg

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_CONTOUR_SHAPE_20261103 — contour for every sequence
    # ------------------------------------------------------------------
    @staticmethod
    def _shape_contour(c, shape):
        """shape −1 … 0 … +1: −1 dulls to nothing (flat), 0 linear (as written),
        +1 sharpens toward square steps (|c|^(1/(1+4s)) keeps sign/zeros)."""
        # Scalar clipping: preserve NaN semantics without allocating a NumPy
        # scalar/array twice for every step in every instrument/engine/lane.
        s = float(shape)
        s = -1.0 if s < -1.0 else 1.0 if s > 1.0 else s
        c = float(c)
        c = -1.0 if c < -1.0 else 1.0 if c > 1.0 else c
        if s < 0.0:
            return c * (1.0 + s)
        if s > 0.0:
            return math.copysign(abs(c) ** (1.0 / (1.0 + 4.0 * s)), c) if c != 0.0 else 0.0
        return c

    def _raw_contour(self, n, seed_i):
        return [float(series_sin((jj + 1) * MEUM_NORM + seed_i * 2.31e-4)
                      * series_cos((jj + 1) * MEUM_INV * 0.5 + seed_i * 7.7e-6)) for jj in range(int(n))]

    def _write_contour_lanes(self, mem, raw, owner, name="", sid=1):
        """Write every contour lane from one raw contour, shaped by the Contour control."""
        shape = float(getattr(self, "contour_shape", 0.0) or 0.0)
        n = len(raw)
        # GROOVEBOX_R23R_CONTOUR_PER_LANE_20261103: each lane group may have its own shape.
        def _lane(group):
            sh = self._contour_lane_shape(group)
            return [self._shape_contour(x, sh) for x in raw], (float(1.0 + sh) if sh < 0.0 else 1.0)
        c, d = _lane("automation")
        cp, _dp = _lane("phase")
        cq, dq = _lane("probability")
        ce, _de = _lane("eq")
        cs, ds = _lane("sidechain")
        cv_env, d_env = _lane("envelope")
        sc = mem.setdefault("step_controls", {})
        sc["phase_shift"] = [float(0.5 * math.pi * x) for x in cp]
        sc["phase_mod_depth"] = [float(0.35 * abs(x)) for x in cp]
        sc["trigger_probability"] = [float(1.0 - 0.15 * dq * (0.5 - 0.5 * x)) for x in cq]
        sc["eq_gain_db"] = [float(3.0 * x) for x in ce]
        sc["eq_frequency"] = [float(1000.0 * 2.0 ** (1.5 * x)) for x in ce]
        sc["eq_q"] = [float(0.707 + 1.3 * abs(x)) for x in ce]
        _sd, _fx = [], []
        for x in cs:
            if ds > 0.0 and x > 0.8:
                _sd.append(float(-ds * (0.4 + 0.6 * (x - 0.8) / 0.2)))
                _fx.append(float(0.35 + 0.4 * (1.0 - x)))
            else:
                _sd.append(float(0.20 * ds * (0.5 + 0.5 * x)) if ds > 0.0 else 0.0)
                _fx.append(1.0)
        sc["sidechain_depth"] = _sd
        sc["fx_probability"] = _fx
        mem["probabilities"] = [int(round(100.0 * pv)) for pv in sc["trigger_probability"]]
        _mean = float(sum(cv_env) / max(1, n))
        _att = 0.5 + d_env * ((0.30 + 0.20 * _mean) - 0.5)
        _rel = 0.5 + d_env * ((0.60 + 0.25 * abs(_mean)) - 0.5)
        mem["sequence_envelope_attack"] = float(np.clip(_att, 0.05, 0.95))
        mem["sequence_envelope_release"] = float(np.clip(max(_rel, mem["sequence_envelope_attack"]) if d_env > 0 else _rel, 0.05, 0.98))
        mem["automation_lane"] = [{"step": jj + 1, "value": float(0.5 + 0.5 * cv), "enabled": True,
                                   "instrument": name, "from_instrument": name, "from_sequence": int(sid),
                                   "canonical_owner": owner} for jj, cv in enumerate(c)]
        mem["automation_lane_length"] = n
        mem["contour_raw"] = [float(x) for x in raw]
        mem["canonical_contour"] = {"version": 2, "shape": shape, "owner": owner,
                                    "lanes": ["pitch", "amp", "offset", "phase_shift", "phase_mod_depth",
                                              "trigger_probability", "eq_gain_db", "eq_frequency", "eq_q", "sidechain_depth",
                                              "fx_probability", "envelope", "automation"]}

    def _on_contour_shape_changed(self, value=None):
        v = int(self.slider_contour_shape.value()) if value is None else int(value)
        self.contour_shape = float(v) / 100.0
        if hasattr(self, "lbl_contour_shape"):
            self.lbl_contour_shape.setText("linear" if v == 0 else (f"dull {abs(v)}%" if v < 0 else f"sharp {v}%"))
        self._contour_reshape_timer.start()

    def _reshape_all_contours(self):
        """Re-shape every contoured sequence in place (canonical + user-contoured)."""
        n_done = 0
        for name, bank in (getattr(self, "instrument_sequence_banks", {}) or {}).items():
            if not isinstance(bank, dict):
                continue
            for sid, mem in bank.items():
                if isinstance(mem, dict) and isinstance(mem.get("contour_raw"), list) and mem["contour_raw"]:
                    owner = str((mem.get("canonical_contour") or {}).get("owner") or mem.get("canonical_owner") or "contour")
                    self._write_contour_lanes(mem, mem["contour_raw"], owner, name, sid)
                    n_done += 1
        try:
            self.reload_active_instrument_sequencer_ui()
        except Exception:
            pass
        try:
            self._on_live_source_changed()
        except Exception:
            pass
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText(f"∿ Contour {self.lbl_contour_shape.text()} · {n_done} sequence(s) reshaped")

    def _contour_current_sequence(self):
        """Apply the contour to the sequence being edited (user sequences too). Undoable."""
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("Contour sequence")
        name = self._current_instrument_name()
        sid = int(self._current_sequence_index(name))
        mem = self._current_sequence_mem(name)
        n = int(mem.get("pattern_length", len(mem.get("steps", []) or [])) or 16)
        self._ensure_seq_mem_length(mem, n)
        try:
            names = list(getattr(self, "instrument_names_48", []) or [])
            seed_i = self._instrument_seed_int(names.index(name) if name in names else 0, name=name, sequence_id=sid)
        except Exception:
            seed_i = _safe_int_seed(f"{self.get_numeric_seed()}|{name}|{sid}")
        self._write_contour_lanes(mem, self._raw_contour(n, seed_i), "user:contour", name, sid)
        mem["contour_user_applied"] = True
        try:
            self._canonical_write_sequence_runtime(name, sid)
        except Exception:
            pass
        try:
            self.reload_active_instrument_sequencer_ui()
            self._on_live_source_changed()
        except Exception:
            pass
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText(f"∿ Contour → {name} / seq {sid} · {n} steps · {self.lbl_contour_shape.text()}")

    def _heuristic_values(self, family, bias, n, seed_value=None, start=0):
        """Return deterministic [0,1] structural values for the Heuristic Composer.

        The generator intentionally uses phase/modulus/index relations rather than
        wall-clock time. That makes every family reproducible and gives the
        T-Independent bias a literal implementation rather than a UI label.
        """
        n = max(1, min(STRUCT_MAX_STEPS, int(n)))
        mod = int(self.spin_nt_modulus.value()) if hasattr(self, "spin_nt_modulus") else 12
        depth = int(self.spin_nt_depth.value()) if hasattr(self, "spin_nt_depth") else 5
        fam = str(family or "ℤ-Lattice")
        bias = str(bias or "Balanced")
        seed = _safe_int_seed(seed_value if seed_value is not None else (self.get_numeric_seed() if hasattr(self, "get_numeric_seed") else 0))
        phase0 = ((seed & 0xFFFFFFFF) / float(0x100000000)) * math.tau
        vals = []
        mode_ui = str(self.combo_nt_mode.currentText()) if hasattr(self, "combo_nt_mode") else "Prime steps"
        qr = set(_nt_quadratic_residues(max(2, mod)))
        phi_n = max(1, _nt_euler_totient(max(2, mod)))
        start = max(0, int(start or 0))
        for i in range(n):
            k = start + i + 1
            residue = k % max(2, mod)
            prime = 1.0 if _nt_is_prime(k) else 0.0
            cop = 1.0 if math.gcd(k, max(2, mod)) == 1 else 0.0
            square = 1.0 if int(math.isqrt(k)) ** 2 == k else 0.0
            sqfree = 1.0 if _nt_mobius(k) != 0 else 0.0
            lattice = prime
            if "Square-free" in mode_ui: lattice = sqfree
            elif "Square" in mode_ui: lattice = square
            elif "Coprime" in mode_ui: lattice = cop
            elif "Fraction" in mode_ui: lattice = ((k * phi_n) % max(2, mod)) / float(max(1, mod - 1))
            elif "Tree-ratio" in mode_ui: lattice = ((k * (depth + 1)) % (mod + depth)) / float(max(1, mod + depth - 1))
            if fam == "ℤ-Lattice":
                v = lattice
            elif fam == "Prime / Modular":
                v = 0.55 * prime + 0.25 * cop + 0.20 * (1.0 if residue in qr else 0.0)
            elif fam == "Farey / Fraction":
                v = ((k * phi_n + depth) % (mod * max(1, depth))) / float(max(1, mod * max(1, depth) - 1))
            elif fam == "Tree / Ratio":
                a = 1 + ((k + depth) % max(2, mod))
                b = 1 + ((k * max(1, depth)) % max(2, mod))
                v = (a / float(a + b))
            elif fam == "Geometric":
                v = 0.5 + 0.5 * series_sin(phase0 + k * MEUM * PHI_INV)
            elif fam == "Harmonic":
                v = 0.5 + 0.25 * series_sin(phase0 + k * PHI) + 0.25 * series_cos(k * MEUM_NORM * math.pi)
            elif fam == "Seed Function":
                try:
                    v = float(evaluate_seed_expression_at_time(self._seed_text(), (k - start) / float(max(1, n)) + start / float(max(1, n)), canonical_context={"step": k, "span": n}))
                    v = 0.5 + 0.5 * series_tanh(v)
                except Exception:
                    v = 0.5 + 0.5 * series_sin(phase0 + k * MEUM)
            else:  # Hybrid
                g = 0.5 + 0.5 * series_sin(phase0 + k * MEUM * PHI_INV)
                v = 0.40 * lattice + 0.25 * cop + 0.20 * g + 0.15 * (1.0 if residue in qr else 0.0)
            v = float(np.clip(v, 0.0, 1.0))
            if bias == "Sparse":
                v = v * v
            elif bias == "Dense":
                v = math.sqrt(v)
            elif bias == "Self-Similar":
                motif = max(2, min(n, 2 ** max(1, int(math.log2(max(2, depth + 1))))))
                mphase = (((start + i) % motif) + 1) / float(motif)
                v = 0.60 * v + 0.40 * (0.5 + 0.5 * series_sin(math.tau * mphase + phase0))
            elif bias == "T-Independent":
                # No absolute t: residue/phase class only.
                v = 0.55 * v + 0.45 * (((residue * phi_n + depth) % max(2, mod)) / float(max(1, mod - 1)))
            vals.append(float(np.clip(v, 0.0, 1.0)))
        return vals

    _HEURISTIC_STEP_FIELDS = (
        "steps", "gates", "amplitudes", "pitches", "probabilities", "offsets",
        "pattern_length", "heuristic_family", "heuristic_bias", "canonical_owner",
        "heuristic_averaged_with_prior", "step_controls",
        "sequence_envelope_attack", "sequence_envelope_release",
    )
    _HEURISTIC_AUTOMATION_FIELDS = ("automation_lane", "automation_lane_length")

    def _heuristic_snapshot_fields(self, mem, fields):
        snap = {}
        if not isinstance(mem, dict):
            mem = {}
        for field in fields:
            snap[field] = (field in mem, copy.deepcopy(mem.get(field)))
        return snap

    def _heuristic_restore_fields(self, mem, snapshot):
        if not isinstance(mem, dict) or not isinstance(snapshot, dict):
            return
        for field, rec in snapshot.items():
            try:
                present, value = rec
            except Exception:
                continue
            if present:
                mem[field] = copy.deepcopy(value)
            else:
                mem.pop(field, None)

    def _heuristic_written_amount(self, name, sid):
        """Heuristic share when it writes over existing material. Canonicals vary it per pattern
        (Meum index) around the playlist overlap amount (Half 50 % / Quarter 25 %): 0.5×–1.5× of it.
        Without active canonicals it is the plain 50 / 50 fight."""
        if not self._md_canonical_on():
            return 0.5
        frac = 0.5
        try:
            frac = float(self.active_paint_table._blend_max_fraction())
        except Exception:
            pass
        names = list(getattr(self, "instrument_names_48", []) or [])
        k = (names.index(name) + 1 if name in names else 1) * 131 + int(sid)
        return float(np.clip(frac * (0.5 + ((k / MEUM) % 1.0)), 0.05, 0.95))

    def _heuristic_synth_factor(self, name):
        """Optional synth shift of heuristic writes: 1.0 for a normal-mix instrument, 0…(1 + M)
        by the instrument's volume relative to the ensemble mean."""
        ps = getattr(self, "instrument_param_state", {}) or {}
        vols = []
        for n in list(getattr(self, "instrument_names_48", []) or []):
            try:
                vols.append(float((ps.get(n) or {}).get("volume", 1.0)))
            except Exception:
                vols.append(1.0)
        mean = (sum(vols) / len(vols)) if vols else 1.0
        try:
            v = float((ps.get(name) or {}).get("volume", mean))
        except Exception:
            v = mean
        return float(np.clip(v / mean if mean > 0 else 1.0, 0.0, 1.0 + MEUM))

    def _heuristic_write_step_into_sequence(self, name, sid, values, family, bias, scope=None):
        """Write the discrete/step-side heuristic layer.

        scope=None or "GLOBAL"/"LOCAL" → full write (all fields).
        scope="RHYTHM" → gate/timing fields only (steps, gates, offsets, envelopes).
        scope="MELODY" → pitch fields only (pitches, chord_intervals, chord_note_count).
        """
        _scope_up = str(scope).upper() if scope else "GLOBAL"
        _rhythm_only = (_scope_up == "RHYTHM")
        _melody_only = (_scope_up == "MELODY")
        bank = (getattr(self, "instrument_sequence_banks", {}) or {}).setdefault(name, {})
        mem = bank.get(int(sid))
        if not isinstance(mem, dict):
            mem = copy.deepcopy((getattr(self, "instrument_sequencer_memory", {}) or {}).get(name, {}))
            bank[int(sid)] = mem
        requested_n = max(1, len(values))
        if bool(mem.get("sequence_length_user_owned", False)):
            n = max(1, min(1024, int(mem.get("pattern_length", requested_n) or requested_n)))
            if len(values) != n:
                values = [values[min(len(values)-1, max(0, int(((i + 0.5) / n) * len(values))))] for i in range(n)] if values else [0.0] * n
        else:
            n = requested_n
        self._ensure_seq_mem_length(mem, n)
        threshold = 0.58
        if bias == "Sparse": threshold = 0.70
        elif bias == "Dense": threshold = 0.42
        elif bias in ("Self-Similar", "T-Independent"): threshold = 0.52
        steps = [bool(v >= threshold) for v in values]
        if not any(steps):
            steps[max(range(n), key=lambda i: values[i])] = True
        # GROOVEBOX_R23R_ALGO_AVERAGING_20261103: when the sequence already holds
        # material (yours or canonical), the heuristic FIGHTS it per data member:
        # continuous values are averaged (pitch ratios geometrically), active
        # steps are the union; the writer's revert snapshot stays exact.
        _prior_on = any(bool(x) for x in (mem.get("steps") or [])[:n])
        _old = {k: list(mem.get(k) or [])[:n] for k in ("steps", "amplitudes", "pitches", "probabilities", "offsets")}
        amps = [float(0.20 + 0.80 * v) for v in values]
        pits = [float(np.clip(2.0 ** ((v - 0.5) * 2.0), 1.0 / 32.0, 32.0)) for v in values]
        probs = [int(np.clip(round(35.0 + 65.0 * v), 1, 100)) for v in values]
        offs = [float((v - 0.5) * 0.5) for v in values]
        if _prior_on and not str(mem.get("canonical_owner", "")).startswith("heuristic"):
            _g = lambda lst, i, d: (float(lst[i]) if i < len(lst) and isinstance(lst[i], (int, float)) else d)
            w = self._heuristic_written_amount(name, sid)
            steps = [bool(steps[i] or (i < len(_old["steps"]) and bool(_old["steps"][i]))) for i in range(n)]
            amps = [w * amps[i] + (1.0 - w) * _g(_old["amplitudes"], i, amps[i]) for i in range(n)]
            pits = [float(np.clip(max(1e-9, pits[i]) ** w * max(1e-9, _g(_old["pitches"], i, pits[i])) ** (1.0 - w), 1.0 / 32.0, 32.0)) for i in range(n)]
            probs = [int(round(w * probs[i] + (1.0 - w) * _g(_old["probabilities"], i, probs[i]))) for i in range(n)]
            offs = [w * offs[i] + (1.0 - w) * _g(_old["offsets"], i, offs[i]) for i in range(n)]
            mem["heuristic_averaged_with_prior"] = True
            mem["heuristic_written_amount"] = float(w)
        if bool(getattr(self, "heuristic_synth_shift", False)):
            f = self._heuristic_synth_factor(name)
            amps = [float(np.clip(a * f, 0.0, 4.0)) for a in amps]
            probs = [int(np.clip(round(p * f), 1, 100)) for p in probs]
            mem["heuristic_synth_factor"] = float(f)
        # RHYTHM_MELODY_WRITE_MASK: scope filter — RHYTHM writes gate/timing,
        # MELODY writes pitch/chord only; full scope writes everything.
        if not _melody_only:
            mem["steps"] = steps
            mem["gates"] = [True] * n
            mem["offsets"] = offs
        if not _rhythm_only:
            mem["amplitudes"] = amps
            mem["pitches"] = pits
            mem["probabilities"] = probs
        # Compatibility: always write both when neither mask is active
        if not _rhythm_only and not _melody_only:
            pass  # already written above
        # GROOVEBOX_R23R_WRITERS_ALL_MEMBERS_20261103: every per-step parameter
        # lane and the sequence envelope are written too (averaged with prior).
        sc = mem.get("step_controls") if isinstance(mem.get("step_controls"), dict) else {}
        mem["step_controls"] = sc
        lane_new = {
            "phase_shift": [float(np.pi * (v - 0.5)) for v in values],
            "phase_mod_depth": [float(0.35 * v) for v in values],
            "trigger_probability": [float(np.clip(0.35 + 0.65 * v, 0.01, 1.0)) for v in values],
            "eq_gain_db": [float(6.0 * (v - 0.5)) for v in values],
            "eq_frequency": [float(1000.0 * 2.0 ** (3.0 * (v - 0.5))) for v in values],
            "eq_q": [float(0.5 + 1.5 * v) for v in values],
            "sidechain_depth": [float(-0.6 * v) if v > 0.9 else float(0.4 * v) for v in values],
            "fx_probability": [float(0.4 if v > 0.9 else 1.0) for v in values],
        }
        if not _melody_only:
            for ln, nv in lane_new.items():
                old = sc.get(ln) if isinstance(sc.get(ln), list) else []
                if _prior_on and old:
                    nv = [0.5 * (nv[i] + float(old[i])) if i < len(old) and isinstance(old[i], (int, float)) else nv[i] for i in range(n)]
                sc[ln] = nv
        _mv = float(sum(values) / max(1, len(values)))
        _a, _r = float(np.clip(0.15 + 0.6 * _mv, 0.0, 1.0)), float(np.clip(0.35 + 0.6 * _mv, 0.0, 1.0))
        if _prior_on:
            _a = 0.5 * (_a + float(mem.get("sequence_envelope_attack", 0.5) or 0.0))
            _r = 0.5 * (_r + float(mem.get("sequence_envelope_release", 0.5) or 0.0))
        if not _melody_only:
            mem["sequence_envelope_attack"] = _a
            mem["sequence_envelope_release"] = max(_a, _r)
        mem["pattern_length"] = n
        mem["heuristic_family"] = str(family)
        mem["heuristic_bias"] = str(bias)
        mem["canonical_owner"] = (
            "heuristic:rhythm" if _rhythm_only else
            "heuristic:melody" if _melody_only else
            "heuristic:step"
        )
        if int((getattr(self, "instrument_selected_sequence", {}) or {}).get(name, 1)) == int(sid):
            self.instrument_sequencer_memory[name] = mem
        return mem

    def _heuristic_write_automation_into_sequence(self, name, sid, values, family, bias):
        """Write only the continuous heuristic automation layer/tiles."""
        self._bake_automation_pattern_to_tiles(
            [100.0 * float(v) for v in values],
            pattern_name=f"Heuristic Automation · {family} · {bias}", activate=True,
            instrument_name=name, sequence_id=int(sid)
        )

    def _heuristic_target_list(self, scope=None):
        scope = str(scope if scope is not None else (self.combo_heuristic_scope.currentText() if hasattr(self, "combo_heuristic_scope") else "LOCAL")).upper()
        targets = []
        if scope == "GLOBAL":
            for name in list(getattr(self, "instrument_names_48", []) or []):
                bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(name, {})
                if isinstance(bank, dict) and bank:
                    for sid in sorted(int(x) for x in bank.keys()): targets.append((name, sid))
                else:
                    targets.append((name, int((getattr(self, "instrument_selected_sequence", {}) or {}).get(name, 1))))
        else:
            name = str(self.instrument_selector_dropdown.currentText()) if hasattr(self, "instrument_selector_dropdown") else (list(getattr(self, "instrument_names_48", []) or ["Operator"])[0])
            sid = int(self.sequence_selector.currentData() or 1) if hasattr(self, "sequence_selector") and self.sequence_selector.currentData() is not None else int((getattr(self, "instrument_selected_sequence", {}) or {}).get(name, 1))
            targets = [(name, sid)]
        return targets

    def _heuristic_restore_writer(self, kind):
        """Restore exactly one heuristic writer's owned state."""
        kind = "automation" if str(kind).lower().startswith("auto") else "step"
        snaps = getattr(self, "_heuristic_writer_snapshots", None)
        if not isinstance(snaps, dict):
            self._heuristic_writer_snapshots = {"step": None, "automation": None}
            snaps = self._heuristic_writer_snapshots
        snap = snaps.get(kind)
        if not isinstance(snap, dict):
            return
        memories = snap.get("memories") or {}
        for key, field_snap in memories.items():
            try:
                name, sid = key
                bank = (getattr(self, "instrument_sequence_banks", {}) or {}).setdefault(name, {})
                mem = bank.get(int(sid))
                if not isinstance(mem, dict):
                    mem = {}
                    bank[int(sid)] = mem
                self._heuristic_restore_fields(mem, field_snap)
                if int((getattr(self, "instrument_selected_sequence", {}) or {}).get(name, 1)) == int(sid):
                    self.instrument_sequencer_memory[name] = mem
            except Exception:
                pass
        if kind == "automation":
            scopes = set(tuple(x) for x in (snap.get("scopes") or []))
            current = []
            for point in list(getattr(self, "sequencer_automation_points", []) or []):
                if not isinstance(point, dict):
                    continue
                sc = (str(point.get("from_instrument") or point.get("instrument") or ""), int(point.get("from_sequence", 1) or 1))
                if sc in scopes:
                    continue
                current.append(point)
            current.extend(copy.deepcopy(snap.get("automation") or []))
            self.sequencer_automation_points = current
        snaps[kind] = None

    def _heuristic_apply_writer(self, kind):
        kind = "automation" if str(kind).lower().startswith("auto") else "step"
        family = str(self.combo_heuristic_family.currentText()) if hasattr(self, "combo_heuristic_family") else "ℤ-Lattice"
        bias = str(self.combo_heuristic_bias.currentText()) if hasattr(self, "combo_heuristic_bias") else "Balanced"
        n = int(self.spin_heuristic_span.value()) if hasattr(self, "spin_heuristic_span") else 16
        scope = str(self.combo_heuristic_scope.currentText()) if hasattr(self, "combo_heuristic_scope") else "LOCAL"
        targets = self._heuristic_target_list(scope)
        values = self._heuristic_values(family, bias, n)
        memories = {}; scopes = []; automation = []
        all_points = list(getattr(self, "sequencer_automation_points", []) or [])
        fields = self._HEURISTIC_AUTOMATION_FIELDS if kind == "automation" else self._HEURISTIC_STEP_FIELDS
        for name, sid in targets:
            bank = (getattr(self, "instrument_sequence_banks", {}) or {}).setdefault(name, {})
            mem = bank.get(int(sid))
            if not isinstance(mem, dict):
                mem = copy.deepcopy((getattr(self, "instrument_sequencer_memory", {}) or {}).get(name, {}))
                bank[int(sid)] = mem
            memories[(name, int(sid))] = self._heuristic_snapshot_fields(mem, fields)
            if kind == "automation":
                scopes.append((name, int(sid)))
                for point in all_points:
                    if not isinstance(point, dict):
                        continue
                    sc = (str(point.get("from_instrument") or point.get("instrument") or ""), int(point.get("from_sequence", 1) or 1))
                    if sc == (name, int(sid)):
                        automation.append(copy.deepcopy(point))
        self._heuristic_writer_snapshots[kind] = {
            "scope": scope, "memories": memories, "scopes": scopes, "automation": automation,
            "family": family, "bias": bias, "span": n,
        }
        _planner = getattr(self, "_heuristic_series_plan", None)
        _series = _planner(targets, family, bias, n, scope) if callable(_planner) else {}
        for idx, (name, sid) in enumerate(targets):
            vv = list(values)
            if (name, int(sid)) in _series:
                vv = list(_series[(name, int(sid))])
            elif idx and vv:
                rot = int(identity_unit(name, "heuristic_rotation") * len(vv)) % len(vv)
                vv = vv[rot:] + vv[:rot]
            if kind == "automation":
                self._heuristic_write_automation_into_sequence(name, sid, vv, family, bias)
            else:
                self._heuristic_write_step_into_sequence(name, sid, vv, family, bias, scope=scope)
        # RHYTHM_MELODY_OWNERSHIP_REGISTER: after a RHYTHM/MELODY scope write,
        # claim engine ownership so canonical passes know to blend/skip.
        _scope_up = str(scope).upper()
        if _scope_up in ("RHYTHM", "MELODY") and kind == "step":
            self._register_heuristic_ownership(
                f"engine_{_scope_up.lower()}", source="user", strength=1.0)
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(
                    f"🎵 {_scope_up} heuristic ({family} · {bias}) written to engines · "
                    f"canonical will blend, not overwrite")
        return len(targets), scope, family, bias, n

    def _heuristic_active_writer_summary(self):
        step_on = bool(getattr(self, "btn_heuristic_write_step", None) and self.btn_heuristic_write_step.isChecked())
        auto_on = bool(getattr(self, "btn_heuristic_write_automation", None) and self.btn_heuristic_write_automation.isChecked())
        active = []
        if step_on: active.append("STEP")
        if auto_on: active.append("AUTOMATION")
        return "+".join(active) if active else "OFF"

    # ------------------------------------------------------------------
    # RHYTHM_MELODY_HEURISTIC_OWNERSHIP_REGISTRY_20261104
    # Tracks which field families have been claimed by user/canonical writes.
    # Canonical paint checks this and blends (strength<1) or skips (strength=1).
    # ------------------------------------------------------------------
    def _register_heuristic_ownership(self, family, source="user", strength=1.0):
        import time as _t
        reg = getattr(self, "_heuristic_ownership", None)
        if not isinstance(reg, dict):
            reg = {}
            self._heuristic_ownership = reg
        reg[str(family)] = {
            "source": str(source),
            "strength": float(max(0.0, min(1.0, strength))),
            "ts": _t.monotonic(),
        }

    def _heuristic_owns(self, family):
        """Return ownership record for family, or None if not owned."""
        reg = getattr(self, "_heuristic_ownership", {})
        return reg.get(str(family)) if isinstance(reg, dict) else None

    def _clear_heuristic_ownership(self, family=None):
        """Clear one family (or all if family is None) from the registry."""
        reg = getattr(self, "_heuristic_ownership", None)
        if not isinstance(reg, dict):
            return
        if family is None:
            reg.clear()
        else:
            reg.pop(str(family), None)

    def _heuristic_ownership_status(self):
        """Return a short human-readable summary of current ownership."""
        reg = getattr(self, "_heuristic_ownership", {}) or {}
        if not reg:
            return ""
        parts = []
        for fam, rec in sorted(reg.items()):
            if isinstance(rec, dict):
                src = rec.get("source", "?")
                st = int(float(rec.get("strength", 1.0)) * 100)
                parts.append(f"{fam}@{src}({st}%)")
        return " · ".join(parts)

    def _heuristic_refresh_after_write(self):
        try: self.reload_active_instrument_sequencer_ui()
        except Exception: pass
        try: self._refresh_sequencer_automation_row()
        except Exception: pass
        try: self._canonical_write_sequence_runtime()
        except Exception: pass
        try: self._on_live_source_changed()
        except Exception: pass

    def _on_heuristic_scope_changed(self, _index=0):
        for _kind, _btn in (("seqsynth", getattr(self, "btn_heuristic_seq_synth", None)),
                            ("geo", getattr(self, "btn_heuristic_write_geo", None))):
            try:
                if _btn is not None and _btn.isCheckable() and _btn.isChecked():
                    self._heuristic_extra_restore(_kind)
                    _btn.blockSignals(True); _btn.setChecked(False); _btn.blockSignals(False)
                    _btn.setChecked(True)
            except Exception as _hx:
                print(f"[Heuristic] {_kind} rescope: {_hx}")
        QTimer.singleShot(0, self._refresh_canonical_explain)
        active = []
        if hasattr(self, "btn_heuristic_write_step") and self.btn_heuristic_write_step.isChecked(): active.append("step")
        if hasattr(self, "btn_heuristic_write_automation") and self.btn_heuristic_write_automation.isChecked(): active.append("automation")
        if not active:
            return
        # Restore both independent zero states before applying the new common
        # GLOBAL/LOCAL scope, so scope switches cannot stack writer residue.
        for kind in active:
            self._heuristic_restore_writer(kind)
        details = None
        for kind in active:
            details = self._heuristic_apply_writer(kind)
        if details and hasattr(self, "scope_status_label"):
            count, scope, family, bias, n = details
            self.scope_status_label.setText(f"Heuristic {self._heuristic_active_writer_summary()} · {scope} · {family} · {bias} · {count} sequence(s) · {n} steps")
        self._heuristic_refresh_after_write()

    def _on_heuristic_writer_toggle(self, kind, checked=False):
        label = "automation" if str(kind).lower().startswith("auto") else "step"
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo(f"Toggle heuristic {label} writer")
        button = self.btn_heuristic_write_automation if label == "automation" else self.btn_heuristic_write_step
        title = "HEURISTIC WRITE AUTOMATION" if label == "automation" else "HEURISTIC WRITE STEP"
        if bool(checked):
            self._heuristic_restore_writer(label)
            count, scope, family, bias, n = self._heuristic_apply_writer(label)
            button.setText(f"{title} · {scope} · ON")
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(f"Heuristic {self._heuristic_active_writer_summary()} · {scope} · {family} · {bias} · {count} sequence(s) · {n} steps")
        else:
            self._heuristic_restore_writer(label)
            button.setText(f"{title} · OFF")
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(f"Heuristic {self._heuristic_active_writer_summary()} · own revert state restored")
        self._heuristic_refresh_after_write()
        self._refresh_canonical_explain()

    def _on_heuristic_write_step(self, checked=False):
        self._on_heuristic_writer_toggle("step", checked)

    def _on_heuristic_write_automation(self, checked=False):
        self._on_heuristic_writer_toggle("automation", checked)

    def _on_heuristic_transcribe(self, checked=False):
        """Compatibility route for older scripts: controls the STEP writer only."""
        if hasattr(self, "btn_heuristic_write_step") and self.btn_heuristic_write_step.isChecked() != bool(checked):
            self.btn_heuristic_write_step.setChecked(bool(checked))
        else:
            self._on_heuristic_write_step(bool(checked))

    def _heuristic_geo_from_values(self, base_geo, vals, idx):
        """Deterministic Vector / Wavetable / Ball / Cellular instance from heuristic values."""
        geo = copy.deepcopy(base_geo) if isinstance(base_geo, dict) else copy.deepcopy(self._geometric_convolution_defaults())
        fac = self._geometric_convolution_defaults()
        for lane in ("vector", "wavetable", "ball", "cellular"):
            if not isinstance(geo.get(lane), dict):
                geo[lane] = copy.deepcopy(fac[lane])
        seq = [float(np.clip(v, 0.0, 1.0)) for v in (vals or [0.5])] or [0.5]
        def g(k):
            return seq[(int(idx) * 7 + int(k)) % len(seq)]
        vec = geo["vector"]
        vec["x"], vec["y"], vec["z"] = (2.0 * g(0) - 1.0), (2.0 * g(1) - 1.0), (2.0 * g(2) - 1.0)
        vec["drive"] = g(3)
        wt = geo["wavetable"]          # a hand-drawn cycle ("drawn") is left untouched
        wt["mode"] = 1 + int(g(4) * 3.0) % 3
        wt["phase"] = g(5) - 0.5
        wt["curvature"] = 0.25 + 0.5 * g(6)
        wt["twist"] = 0.25 + 0.5 * g(7)
        wt["fold"] = 0.05 + 0.4 * g(8)
        if not geo.get("ball_locked"):
            ball = geo["ball"]
            ball["gravity"] = 2.0 * (2.0 * g(9) - 1.0)
            ball["gravity_angle_degrees"] = 360.0 * g(10)
            ball["radius"] = 0.05 + 0.95 * g(11)
            ball["vx"] = 2.0 * (2.0 * g(12) - 1.0)
            ball["vy"] = 2.0 * (2.0 * g(13) - 1.0)
        if not geo.get("ca_locked"):
            ca = geo["cellular"]       # hand-placed cells ("manual_cells") are left untouched
            ca["width"] = 4 + int(g(14) * 60.0)
            ca["height"] = 4 + int(g(15) * 60.0)
            ca["cell_types"] = 2 + int(g(16) * 6.0)
            ca["generations"] = 4 + int(g(17) * 60.0)
            ca["rule"] = int(g(18) * 255.0)
            ca["neighborhood"] = "moore" if g(19) < 0.5 else "von_neumann"
        return geo

    def _heuristic_write_geometrics(self, name, sid, mem, vals, idx):
        """Write the four geometric instances for one (instrument, sequence) target.

        Edit Synth Per Seq ON  -> the sequence's own synth panel owns the instances.
        Edit Synth Per Seq OFF -> the instrument's instance changes, and the canonical macro
        user store records it as the authored program so unison reconciliation keeps it.
        """
        ps = getattr(self, "instrument_param_state", None)
        if ps is None:
            ps = self.instrument_param_state = {}
        inst = ps.setdefault(name, {})
        per_seq = False
        try:
            per_seq = bool(self._panels_per_sequence_enabled())
        except Exception:
            pass
        synth = mem.get("synth") if isinstance(mem.get("synth"), dict) else {}
        base = synth.get("geo") if (per_seq and isinstance(synth.get("geo"), dict)) else inst.get("geo")
        geo = self._heuristic_geo_from_values(base, vals, idx)
        synth["geo"] = copy.deepcopy(geo)
        mem["synth"] = synth
        if not per_seq:
            inst["geo"] = copy.deepcopy(geo)
            store = getattr(self, "_canonical_macro_user_store", None)
            if not isinstance(store, dict):
                store = self._canonical_macro_user_store = {}
            us = store.setdefault(name, {})
            if isinstance(us, dict):
                us["geo"] = copy.deepcopy(geo)
        return geo

    def _heuristic_reload_geo_editor(self):
        try:
            nm = self.instrument_selector_dropdown.currentText() if hasattr(self, "instrument_selector_dropdown") else ""
            if nm:
                self._geo_editor_instrument = None
                self._geo_buffer_load(nm)
        except Exception:
            pass

    def _on_heuristic_geometrics(self):
        """Write only the four geometric synths from the heuristic."""
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("Heuristic → 4 geometrics")
        family = str(self.combo_heuristic_family.currentText()) if hasattr(self, "combo_heuristic_family") else "ℤ-Lattice"
        bias = str(self.combo_heuristic_bias.currentText()) if hasattr(self, "combo_heuristic_bias") else "Balanced"
        span = int(self.spin_heuristic_span.value()) if hasattr(self, "spin_heuristic_span") else 16
        vals = self._heuristic_values(family, bias, max(8, span))
        n = 0
        for idx, (name, sid) in enumerate(self._heuristic_target_list()):
            bank = (getattr(self, "instrument_sequence_banks", {}) or {}).setdefault(name, {})
            mem = bank.setdefault(int(sid), {})
            self._heuristic_write_geometrics(name, sid, mem, vals, idx)
            if int((getattr(self, "instrument_selected_sequence", {}) or {}).get(name, 1)) == int(sid):
                self.instrument_sequencer_memory[name] = mem
            n += 1
        self._heuristic_reload_geo_editor()
        self._heuristic_refresh_after_write()
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText(f"Heuristic → 4 geometrics · {family} · {bias} · {n} target(s)")

    def _on_heuristic_seq_synth(self):
        """Apply heuristic structure to sequence-local synth/script/domain/patch context only.

        This is deliberately not a third STEP/AUTOMATION writer. It authors the
        same sequence-panel stores used by Edit Synth Per Seq and is covered by
        normal project Undo/Redo.
        """
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("Apply heuristic to sequence synth")
        family = str(self.combo_heuristic_family.currentText()) if hasattr(self,"combo_heuristic_family") else "ℤ-Lattice"
        bias = str(self.combo_heuristic_bias.currentText()) if hasattr(self,"combo_heuristic_bias") else "Balanced"
        span = int(self.spin_heuristic_span.value()) if hasattr(self,"spin_heuristic_span") else 16
        targets = self._heuristic_target_list()
        vals = self._heuristic_values(family,bias,max(8,span))
        seed = float(self.get_numeric_seed()) if hasattr(self,"get_numeric_seed") else 1.0
        touched = 0
        _scope_now = str(self.combo_heuristic_scope.currentText()) if hasattr(self, "combo_heuristic_scope") else "LOCAL"
        _series = self._heuristic_series_plan(targets, family, bias, max(8, span), _scope_now)
        _used_v = set()
        for idx,(name,sid) in enumerate(targets):
            bank=(getattr(self,"instrument_sequence_banks",{}) or {}).setdefault(name,{})
            mem=bank.setdefault(int(sid),{})
            v=float(vals[idx % len(vals)]) if vals else 0.5
            if (name, int(sid)) in _series:
                # Series: this target's own segment → its own synth coordinate,
                # made unique across the ensemble.
                _seg = _series[(name, int(sid))]
                v = float(sum(_seg[j] * (j + 1) for j in range(len(_seg))) / float(sum(range(1, len(_seg) + 1)) or 1))
                _k = 0
                while round(v, 9) in _used_v and _k < 64:
                    _k += 1
                    v = float((v + MEUM_NORM * _k / (len(targets) + 1)) % 1.0)
                _used_v.add(round(v, 9))
            synth=copy.deepcopy(mem.get("synth") or {})
            # Bounded sequence-local offsets/preset coordinates. These are context
            # values, not generated notes or automation control points.
            _hp = float(np.clip(0.5 + v * MEUM, 0.125, 2.0)); _ha = float(np.clip(0.25 + 0.75*v, 0.0, 1.0))
            if isinstance(synth.get("pitch"), (int, float)):      # fight the prior value: average
                _hp = float(np.clip(math.sqrt(max(0.0, _hp) * max(0.0, float(synth["pitch"]))), 0.125, 2.0))
            if isinstance(synth.get("amp"), (int, float)):
                _ha = float(np.clip(0.5 * (_ha + float(synth["amp"])), 0.0, 1.0))
            synth.update({
                "pitch": _hp,
                "amp": _ha,
                "detune": float((v-0.5) * MEUM_MINUS_1),
                "heuristic_family": family, "heuristic_bias": bias,
                "heuristic_value": v,
            })
            mem["synth"] = synth
            mem["script"] = (
                f"# heuristic:{family}:{bias} · full graph\n"
                f"def evaluate_wave(x, y, z, t=0.0, t_norm=0.0, graph=None):\n"
                f"    spatial = sin((x + graph_z) * MEUM * {1.0+v:.12g}) * cos((y - graph_x) * PHI)\n"
                f"    temporal = isn(graph_phase + t * {1.0+v:.12g})\n"
                f"    return {{'wave': spatial * (0.5 + 0.5*temporal), 'amp': 0.5 + 0.5*graph_u, 'pitch': 1.0 + {0.125*v:.12g}*graph_curvature, 'pan': 2.0*graph_v-1.0}}"
            )
            mem["domain"] = {"domains": [{
                "name": "heuristic_full_graph", "axis": "both",
                "t0": 0.0, "t1": 1.0, "x0": -1.0, "x1": 1.0, "y0": -1.0, "y1": 1.0,
                "logic": "True",
                "equation": f"sin((x+graph_z)*MEUM*{1.0+v:.12g})*cos((y+t)*PHI)+0.25*graph_energy",
                "limit_lo": -1.0, "limit_hi": 1.0, "weight": v,
                "source": "heuristic_seq_synth", "user_defined": False,
            }], "source": "heuristic_seq_synth"}
            mem["patch"] = {"source":"heuristic_seq_synth","mod_depth":v,"ratio":float(1.0+MEUM_MINUS_1*v)}
            mem["heuristic_seq_synth"] = {"family":family,"bias":bias,"value":v,"span":span}
            if getattr(self, "chk_heuristic_geo", None) is None or self.chk_heuristic_geo.isChecked():
                self._heuristic_write_geometrics(name, sid, mem, vals, idx)
            if int((getattr(self,"instrument_selected_sequence",{}) or {}).get(name,1)) == int(sid):
                self.instrument_sequencer_memory[name]=mem
            touched += 1
        self._heuristic_reload_geo_editor()
        self._heuristic_refresh_after_write()
        if hasattr(self,"scope_status_label"):
            self.scope_status_label.setText(f"Heuristic → Seq Synth · {family} · {bias} · {touched} sequence context(s); steps/automation unchanged")

    def _on_nt_to_seed(self):
        """Emit a seed script that number-theorists will recognize as structured.

        The prior seed is kept on the seed-revert history and on the project
        undo stack, so "Algorithm → Seed" is fully reversible.
        """
        if not getattr(self, "_undo_in_flight", False):
            self._push_undo("Algorithm → Seed")
        mod = int(self.spin_nt_modulus.value()) if hasattr(self, "spin_nt_modulus") else 12
        depth = int(self.spin_nt_depth.value()) if hasattr(self, "spin_nt_depth") else 5
        phi = _nt_euler_totient(mod)
        mu = _nt_mobius(mod)
        qr = _nt_quadratic_residues(mod)
        qr_s = ", ".join(str(x) for x in qr[:12])
        # Time-varying script using φ(n), μ(n), and Meum
        script = (
            f"# NT seed · n={mod} φ={phi} μ={mu}\\n"
            f"# QR mod n: {qr_s}\\n"
            f"return (φ if False else {phi}) * (0.5 + 0.5 * isn(t * MEUM)) "
            f"+ {mod} * MEUM_NORM * cos(t * PHI) + ({mu}) * ics(t)"
        )
        # φ is not in env — use numeric phi only
        script = (
            f"# NT seed · n={mod} · φ(n)={phi} · μ(n)={mu}\\n"
            f"# quadratic residues mod n: {qr_s}\\n"
            f"({phi} * (0.5 + 0.5 * isn(t * MEUM)) + {mod} * MEUM_NORM * cos(t * PHI) "
            f"+ ({mu}) * ics(t))"
        )
        if hasattr(self, "_push_seed_history"):
            self._push_seed_history(script)
        if hasattr(self, "_apply_seed_script_text"):
            self._apply_seed_script_text(script, status_prefix=f"ℤ→Seed n={mod}")
        elif hasattr(self, "input_seed_val"):
            self.input_seed_val.setPlainText(script)
            try:
                self._on_live_source_changed()
            except Exception:
                pass

    def _ensure_hardware_use(self, reason="hardware-use"):
        try:
            from hardware_runtime import ensure_first_hardware_refresh
            ensure_first_hardware_refresh(reason, block=False)
        except Exception:
            pass

    def play_selected_sequence(self):
        """Preview one sequence and visualize that instrument. Same stream."""
        # GROOVEBOX_PLAY_GUARD_20261031: a double-click must not queue two
        # render/open cycles; every failure path leaves the transport idle.
        if getattr(self, "_play_begin_busy", False):
            return
        self._play_begin_busy = True
        try:
            try:
                self.stop_playback()
            except Exception:
                pass
            try:
                self.claim_audio("main")
            except Exception as exc:
                print(f"[Play] claim_audio failed: {exc}")
            name = ""
            try:
                name = str(self.instrument_selector_dropdown.currentText())
            except Exception:
                name = ""
            self._sequence_preview_instrument = name
            self._live_preview_rows_override = 1
            self._begin_playback_async(audio_only=False)
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText("This Sequence · %s" % (name or "operator"))
        except Exception as exc:
            self._live_preview_rows_override = None
            print(f"[Play] This Sequence failed safely: {exc}")
            try:
                self.scope_status_label.setText("This Sequence failed: %s" % exc)
            except Exception:
                pass
        finally:
            self._play_begin_busy = False

    def play_audio_only(self):
        """Play the rendered audio track without driving the audiovisual monitors."""
        self._ensure_hardware_use("track-play")
        self.claim_audio("main")
        # Mutually exclusive with audiovisual playback.
        if self.is_playing or self.is_paused:
            if not getattr(self, "_audio_only_mode", False):
                self.stop_playback()
            else:
                return
        self._begin_playback_async(audio_only=True)

    def claim_audio(self, owner: str):
        """One PortAudio/ALSA owner at a time. Stops the other window first."""
        owner = str(owner or "main")
        current = getattr(self, "_audio_owner", None)
        if current and current != owner:
            self.release_audio(current)
        if owner == "main":
            perf = getattr(self, "_performance_window", None) or getattr(self, "performance_window", None)
            if perf is not None and hasattr(perf, "_stop_player"):
                try:
                    perf._stop_player()
                except Exception:
                    pass
        if owner != "main":
            try:
                self.stop_playback()
            except Exception:
                pass
            try:
                self.stop_audio_playback()
            except Exception:
                pass
            # GROOVEBOX_R23R_WAV_PLAYER_DEVICE_20261101: the Trigger/keyboard audition
            # stream stays open between hits; on a direct ALSA device it kept the card
            # busy, so Performance .wav playback (aplay / file stream) was silent while
            # the main window kept working. Close it; the next hit reopens it lazily.
            self._close_audition_stream()
        self._audio_owner = owner
        if not hasattr(self, "play_lock") or self.play_lock is None:
            self.play_lock = threading.Lock()
        return self.play_lock

    def _close_audition_stream(self):
        lock = getattr(self, "_pkp_poly_lock", None)
        try:
            if lock is not None:
                with lock:
                    st = getattr(self, "_pkp_poly_stream", None); self._pkp_poly_stream = None
                    try:
                        self._pkp_poly_voices.clear()
                    except Exception:
                        pass
            else:
                st = getattr(self, "_pkp_poly_stream", None); self._pkp_poly_stream = None
            if st is not None:
                try:
                    st.stop()
                except Exception:
                    pass
                st.close()
        except Exception:
            pass

    def release_audio(self, owner: str):
        if getattr(self, "_audio_owner", None) not in (None, owner):
            return
        self._audio_owner = None
        try:
            if getattr(self, "audio_stream", None) is not None:
                self.audio_stream.stop()
                self.audio_stream.close()
        except Exception:
            pass
        self.audio_stream = None
        self.is_playing = False
        self.is_paused = False
        self._audio_only_mode = False

    def stop_audio_playback(self):
        """Stop/reset audio-only transport without changing composition state."""
        was_active = self.is_playing and getattr(self, "_audio_only_mode", False)
        if not getattr(self, "_audio_only_mode", False) and not was_active:
            return
        self.is_playing = False
        self.is_paused = False
        self._audio_only_mode = False
        self._transport_finished = False
        self._stop_requested = True
        if hasattr(self, "_scope_update_timer") and self._scope_update_timer.isActive():
            self._scope_update_timer.stop()
        if getattr(self, "audio_stream", None) is not None:
            try:
                self.audio_stream.stop(); self.audio_stream.close()
            except Exception:
                pass
            self.audio_stream = None
        with getattr(self, "play_lock", threading.Lock()):
            self.play_cursor = 0
        if hasattr(self, "btn_audio_only"):
            self.btn_audio_only.setText("▶ PLAY Audio Track")
            self.btn_audio_only.setStyleSheet(
                "QPushButton { background-color:#14301c; color:#9dffb0; border:2px solid #46d158; "
                "border-radius:8px; padding:10px 16px; font-weight:900; font-size:13pt; }"
                "QPushButton:hover { background-color:#1f4228; }"
                "QPushButton:pressed { background-color:#0c1f10; }"
            )
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("📊 GLOBAL monitors · Wave · Scenograph · Spectrum  |  Idle")
        self._stop_requested = False
        if was_active:
            print("[Audio-only] Playback stopped.")

    def stop_playback(self):
        """Hard stop: reset the audiovisual transport to the beginning."""
        # GROOVEBOX_PLAY_GUARD_20261031: invalidate any in-flight async render
        # so Stop during "Rendering track..." cannot start audio afterwards, and
        # drop the one-instrument preview override so the next full Play is full.
        self._play_gen = int(getattr(self, "_play_gen", 0)) + 1
        self._live_preview_rows_override = None
        self._sequence_preview_instrument = ""
        was_active = self.is_playing or self.is_paused
        self.is_playing = False
        self.is_paused = False
        self._audio_only_mode = False
        self._stop_requested = True
        self._transport_finished = False
        # Drop live modulation baselines so the next Play starts clean
        self._live_offset_baselines = {}
        self._live_param_baselines = {}
        if hasattr(self, '_scope_update_timer') and self._scope_update_timer.isActive():
            self._scope_update_timer.stop()
        if getattr(self, 'audio_stream', None) is not None:
            try:
                self.audio_stream.stop(); self.audio_stream.close()
            except Exception:
                pass
            self.audio_stream = None
        with getattr(self, 'play_lock', threading.Lock()):
            self.play_cursor = 0
        if hasattr(self, 'btn_play'):
            self.btn_play.setText("▶ PLAY Audiovisual Track")
            self.btn_play.setStyleSheet(
                "QPushButton { background-color:#14301c; color:#9dffb0; border:2px solid #46d158; "
                "border-radius:8px; padding:10px 16px; font-weight:900; font-size:13pt; }"
                "QPushButton:hover { background-color:#1f4228; }"
                "QPushButton:pressed { background-color:#0c1f10; }"
            )
        if hasattr(self, 'btn_audio_only'):
            self.btn_audio_only.setText("▶ PLAY Audio Track")
            self.btn_audio_only.setStyleSheet(
                "QPushButton { background-color:#14301c; color:#9dffb0; border:2px solid #46d158; "
                "border-radius:8px; padding:10px 16px; font-weight:900; font-size:13pt; }"
                "QPushButton:hover { background-color:#1f4228; }"
                "QPushButton:pressed { background-color:#0c1f10; }"
            )
        if hasattr(self, 'scope_status_label'):
            self.scope_status_label.setText("📊 Audiovisual Track  |  Stopped")
        if isinstance(getattr(self, 'visual_oscilloscope', None), VisualOscilloscope):
            self.visual_oscilloscope.update_waveform(np.zeros(100))
        if hasattr(self, 'video_synth_viewer'):
            self.video_synth_viewer.update_from_audio(np.zeros(100, dtype=np.float32))
        if was_active:
            print("[Audio] Audiovisual playback stopped.")
        self._stop_requested = False

    # GROOVEBOX_R23R_EXPORT_PROJECT_NAMING_20261101 ------------------------
    def _prepare_export_project(self, kind="export"):
        """Every export belongs to a named, saved project.

        Unsaved project: ask to name + save it first (exports then go into that
        project's folders and carry its name), or export into "Untitled", or
        cancel. Saved project: save it now so the export matches a snapshot on disk.
        Returns False only when the user cancels.
        """
        if (os.environ.get("GROOVEBOX_NO_EXPORT_PROMPT") == "1" or getattr(self, "_export_prompt_in_flight", False)
                or getattr(self, "_batch_export_active", False)):
            return True
        cur = getattr(self, "_current_project_path", None)
        try:
            self._export_prompt_in_flight = True
            if self._pending_export_parts():
                # Crash/parts continuation: keep the folder the parts live in, so the
                # part dialog can resume them (no renaming/moving the project now).
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText(f"↻ Unfinished {kind} parts found — continuing in the same project folder")
                return True
            if cur and getattr(self, "_recovered_needs_save", False):
                if not self.isVisible():
                    return True
                box = QMessageBox(self)
                box.setWindowTitle("Recovered project")
                box.setText(f"This project was restored from an autosave. Save it over\n{cur}\nbefore the {kind}?")
                b_save = box.addButton("Save recovered project", QMessageBox.ButtonRole.AcceptRole)
                b_as = box.addButton("Save as…", QMessageBox.ButtonRole.ActionRole)
                b_skip = box.addButton("Export without saving", QMessageBox.ButtonRole.DestructiveRole)
                box.addButton(QMessageBox.StandardButton.Cancel)
                box.setDefaultButton(b_save); box.exec(); c = box.clickedButton()
                if c is b_skip:
                    return True
                if c is b_as:
                    self.save_project_dialog(); return True
                if c is not b_save:
                    return False
                self._save_project_document(cur, show_saved=False); self._recovered_needs_save = False
                return True
            if not cur:
                if not self.isVisible():
                    return True
                box = QMessageBox(self)
                box.setWindowTitle("Name this project before exporting")
                box.setText(f"This {kind} will be saved inside a project folder and named after the project.\n\n"
                            "Name and save the project now?")
                b_save = box.addButton("Save project…", QMessageBox.ButtonRole.AcceptRole)
                b_skip = box.addButton("Export without saving (Untitled)", QMessageBox.ButtonRole.DestructiveRole)
                box.addButton(QMessageBox.StandardButton.Cancel)
                box.setDefaultButton(b_save)
                box.exec()
                clicked = box.clickedButton()
                if clicked is b_skip:
                    return True
                if clicked is not b_save:
                    return False
                self.save_project_dialog()
                return bool(getattr(self, "_current_project_path", None))
            try:
                self._save_project_document(cur, show_saved=False)
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText(f"💾 Project saved before {kind}: {os.path.basename(cur)}")
            except Exception as exc:
                print(f"[Export] project save before {kind} failed: {exc}")
            return True
        finally:
            self._export_prompt_in_flight = False

    _PART_RE = re.compile(r"^(?P<stem>.+?)\.(?:audio\.)?part(?P<n>\d{2})\.(?P<ext>[A-Za-z0-9]+)$")

    def _pending_parts_in(self, folder, exts=None):
        """[(mtime, stem, ext)] of part sets in folder whose final file is missing (newest first)."""
        out = {}
        try:
            names = os.listdir(folder)
        except Exception:
            return []
        finals = {os.path.splitext(n)[0] for n in names if ".part" not in n}
        for n in names:
            m = self._PART_RE.match(n)
            if not m:
                continue
            stem, ext = m.group("stem"), m.group("ext").lower()
            if exts and ext not in exts and ext != "wav":
                continue
            if stem in finals:
                continue
            try:
                mt = os.path.getmtime(os.path.join(folder, n))
            except OSError:
                continue
            key = (stem, ext)
            out[key] = max(out.get(key, 0.0), mt)
        return sorted(((mt, st, ex) for (st, ex), mt in out.items()), reverse=True)

    def _pending_export_parts(self):
        """Unfinished .part sets in this project's audio/video export folders."""
        rows = []
        for fn in ("_audio_exports_dir", "_video_exports_dir"):
            try:
                rows += self._pending_parts_in(getattr(self, fn)())
            except Exception:
                pass
        return sorted(rows, reverse=True)

    def _export_name(self, kind, ext, folder):
        """<folder>/<Project> · <kind> NNN<ext> — the next free number for that project.

        Crash continuation: when the folder holds an unfinished .part set for this
        file type (any naming, incl. pre-R23r "groovebox_video_003"), that stem is
        offered instead so the existing resume dialog picks the parts up.
        """
        _ext = (ext if str(ext).startswith(".") else "." + str(ext)).lower().lstrip(".")
        try:
            pend = self._pending_parts_in(folder, {_ext})
            pend = [r for r in pend if r[2] == _ext] or ([r for r in pend if r[2] == "wav"] if kind == "mixdown" else [])
            if pend:
                return os.path.join(folder, pend[0][1] + "." + (ext.lstrip(".") if str(ext) else _ext))
        except Exception:
            pass
        import groovebox_paths
        try:
            proj = groovebox_paths.project_name(getattr(self, "_current_project_path", None))
        except Exception:
            proj = "Untitled"
        _sess = getattr(self, "_session_name", "")   # SESSION_NAME_R31
        if _sess:
            proj = _sess if proj in ("", "Untitled") else f"{_sess} · {proj}"
        ext = ext if str(ext).startswith(".") else "." + str(ext)
        os.makedirs(folder, exist_ok=True)
        n = 1
        while True:
            cand = os.path.join(folder, f"{proj} · {kind} {n:03d}{ext}")
            if not os.path.exists(cand):
                return cand
            n += 1

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_SAVE_TO_DRIVE_20261103 — "Save to:" export destination
    # ------------------------------------------------------------------
    def _export_target_dir(self, sub=""):
        """<drive>/Groovebox Exports/<project>/<sub> while a USB / SD drive is chosen
        under "Save to:", else None (project exports folder). A drive that was
        unplugged falls back to the project folder (and says so)."""
        root = str(getattr(self, "export_target", "") or "")
        if not root:
            return None
        if not os.path.isdir(root) or not os.access(root, os.W_OK):
            self.export_target = ""
            try:
                self.scope_status_label.setText("💾 Save-to drive is gone — exports go to the project folder again")
            except Exception:
                pass
            self._refresh_export_target_pickers()
            return None
        proj = os.path.splitext(os.path.basename(str(getattr(self, "_current_project_path", "") or "")))[0] or "Untitled"
        d = os.path.join(root, "Groovebox Exports", proj, sub) if sub else os.path.join(root, "Groovebox Exports", proj)
        try:
            os.makedirs(d, exist_ok=True)
        except OSError:
            return None
        return d

    def _exports_dir(self):
        """Project-local export root: <Project>/exports/ (or the "Save to:" drive)."""
        t = self._export_target_dir("")
        if t:
            return t
        import groovebox_paths
        return groovebox_paths.renders_dir(getattr(self, "_current_project_path", None))

    def _audio_exports_dir(self):
        t = self._export_target_dir("audio")
        if t:
            return t
        import groovebox_paths
        return groovebox_paths.audio_exports_dir(getattr(self, "_current_project_path", None))

    def _video_exports_dir(self):
        t = self._export_target_dir("video")
        if t:
            return t
        import groovebox_paths
        return groovebox_paths.video_exports_dir(getattr(self, "_current_project_path", None))

    def _frame_exports_dir(self):
        t = self._export_target_dir("frames")
        if t:
            return t
        import groovebox_paths
        return groovebox_paths.frame_exports_dir(getattr(self, "_current_project_path", None))

    def _refresh_export_target_pickers(self):
        alive = []
        for fn in list(getattr(self, "_export_target_pickers", []) or []):
            try:
                fn(); alive.append(fn)
            except RuntimeError:
                pass
        self._export_target_pickers = alive

    def _make_export_target_picker(self, parent=None):
        """Row: Save to: [Project exports folder | 💾 <drive> (free)] ↻ ⏏ Flush.
        Every picker (Export window, Batch, Live Player) shows and sets the same choice."""
        import drive_targets as dt
        w = QWidget(parent)
        row = QHBoxLayout(w); row.setContentsMargins(0, 0, 0, 0)
        row.addWidget(QLabel("Save to:"))
        cmb = QComboBox(); cmb.setMinimumWidth(260)
        cmb.setToolTip("Where exports, batch exports and live takes are written. Pick a USB stick / SD card to "
                       "export straight onto it (<drive>/Groovebox Exports/<project>/…) — no folder dialogs needed.")
        row.addWidget(cmb, 1)
        b_ref = QPushButton("↻"); b_ref.setToolTip("Detect drives"); b_ref.setFixedWidth(34); row.addWidget(b_ref)
        b_sync = QPushButton("⏏ Flush"); b_sync.setToolTip("Write everything still cached to the drive, so it is safe to unplug")
        row.addWidget(b_sync)
        state = {"busy": False}

        def fill():
            # Detect drives off the UI thread so a slow stick doesn't hitch the window.
            state["busy"] = True
            def _detect():
                try:
                    drives = list(dt.removable_drives())
                except Exception:
                    drives = []
                try:
                    probs = list(dt.drive_problems())
                except Exception:
                    probs = []
                return drives, probs
            def _apply(found):
                drives, probs = found if isinstance(found, tuple) else (found, [])
                state["probs"] = probs
                try:
                    state["busy"] = True
                    cmb.clear()
                    cmb.addItem("📁 Project exports folder", "")
                    cur = str(getattr(self, "export_target", "") or "")
                    for r in drives:
                        pth = str(r.get("path") or "")
                        if not pth:
                            continue
                        free = r.get("free")
                        lab = f"💾 {r.get('label') or os.path.basename(pth) or pth}"
                        if isinstance(free, (int, float)) and free > 0:
                            lab += f" · {free / 1e9:.1f} GB free"
                        cmb.addItem(lab, pth)
                    if cur and cmb.findData(cur) < 0 and os.path.isdir(cur):
                        cmb.addItem(f"📂 {cur}", cur)
                    for pr in probs:    # R32.10: plugged in but unusable — say why, offer the fix
                        cmb.addItem(f"⚠ {pr['device']} — {pr['reason']}" + (" (click to mount)" if pr.get("fix") == "mount" else ""),
                                    "__problem__:" + pr["device"])
                    cmb.addItem("📂 Choose a folder… (any drive)", "__choose__")
                    i = cmb.findData(cur)
                    cmb.setCurrentIndex(i if i >= 0 else 0)
                    b_sync.setEnabled(bool(cur))
                    state["last"] = cmb.currentIndex()
                finally:
                    state["busy"] = False
            try:
                ex = getattr(self, "_usb_worker", None)
                if ex is None:
                    try:
                        import thread_budget as _tb
                        ex = self._usb_worker = _tb.make_lane("usb-storage", max_workers=1, max_pending=8)
                    except Exception:
                        import concurrent.futures
                        ex = self._usb_worker = concurrent.futures.ThreadPoolExecutor(max_workers=1, thread_name_prefix="usb-flush")
                fut = ex.submit(_detect)
                def _publish_detect(done):
                    try:
                        result = done.result()
                    except Exception:
                        result = []
                    try:
                        from ui_runtime import post_to_ui
                        post_to_ui(_apply, result, key=("usb-drive-detect", id(self)))
                    except Exception:
                        pass
                fut.add_done_callback(_publish_detect)
            except Exception:
                _apply([])

        def chosen(_i):
            if state["busy"]:
                return
            data = str(cmb.currentData() or "")
            if data == "__choose__" or data.startswith("__problem__:"):
                back = int(state.get("last", 0) or 0)
                state["busy"] = True; cmb.setCurrentIndex(back); state["busy"] = False
                if data == "__choose__":
                    start = str(getattr(self, "export_target", "") or "") or ("/media" if os.path.isdir("/media") else os.path.expanduser("~"))
                    d = QFileDialog.getExistingDirectory(w, "Save exports and live takes to…", start)
                    if not d:
                        return
                    if not os.access(d, os.W_OK):
                        QMessageBox.warning(w, "Save to", f"Groovebox cannot write to:\n{d}\n\nPick another folder, or fix the drive's permissions.")
                        return
                    self.export_target = d
                else:
                    dev = data.split(":", 1)[1]
                    pr = next((x for x in (state.get("probs") or []) if x.get("device") == dev), {})
                    if pr.get("fix") == "mount":
                        ok, msg = dt.mount_drive(dev)
                        if not ok:
                            QMessageBox.warning(w, "Mount drive", f"Could not mount {dev}:\n{msg}")
                        fill()
                        return
                    QMessageBox.information(w, "Drive not usable", f"{dev}: {pr.get('reason', '')}\n\n{pr.get('fix', '')}")
                    return
            else:
                self.export_target = data
            state["last"] = cmb.currentIndex()
            where = self._exports_dir()
            try:
                self.scope_status_label.setText(f"💾 Exports now save to {where}")
            except Exception:
                pass
            self._refresh_export_target_pickers()

        def flush():
            # USB_OFF_UI_20261106: os.sync() can stall the main window for
            # seconds on a slow stick. Run it on a worker and only touch the
            # UI when it finishes.
            if not hasattr(os, "sync"):
                QMessageBox.information(w, "Save to drive", "Files are written. Use the system's "
                                        "'Safely remove' / 'Eject' before unplugging.")
                return
            try:
                self.scope_status_label.setText("⏏ Flushing drive…")
            except Exception:
                pass
            def _work():
                try:
                    os.sync()
                    return None
                except Exception as exc:
                    return exc
            def _done(err):
                if err is None:
                    QMessageBox.information(w, "Save to drive", "Everything is written to the drive — safe to unplug.")
                else:
                    QMessageBox.warning(w, "Save to drive", f"Flush failed: {err}")
                try:
                    self.scope_status_label.setText("Ready.")
                except Exception:
                    pass
            try:
                ex = getattr(self, "_usb_worker", None)
                if ex is None:
                    try:
                        import thread_budget as _tb
                        ex = self._usb_worker = _tb.make_lane("usb-storage", max_workers=1, max_pending=8)
                    except Exception:
                        import concurrent.futures
                        ex = self._usb_worker = concurrent.futures.ThreadPoolExecutor(max_workers=1, thread_name_prefix="usb-flush")
                fut = ex.submit(_work)
                def _publish_flush(done):
                    try:
                        result = done.result()
                    except Exception as exc:
                        result = exc
                    try:
                        from ui_runtime import post_to_ui
                        post_to_ui(_done, result, key=("usb-drive-flush", id(self)))
                    except Exception:
                        pass
                fut.add_done_callback(_publish_flush)
            except Exception as exc:
                QMessageBox.warning(w, "Save to drive", f"Flush failed: {exc}")
        cmb.currentIndexChanged.connect(chosen)
        b_ref.clicked.connect(fill)
        b_sync.clicked.connect(flush)
        fill()
        self._export_target_pickers = list(getattr(self, "_export_target_pickers", []) or []) + [fill]
        return w

    def _index_project_file(self, path, role):
        try:
            import groovebox_paths
            groovebox_paths.index_file(path, role, getattr(self, "_current_project_path", None))
        except Exception:
            pass

    def _export_frame_size(self):
        """Video resolution = main window size at export time (even dims for yuv420p).
        HW_SIZE_20261107: Compatibility can force 720p, 1080p, or the screen."""
        try:
            import compat_settings as _cs
            size = str(_cs.load().get("scene_size", "auto"))
        except Exception:
            size = "auto"
        if size == "720p":
            return 1280, 720
        if size == "1080p":
            return 1920, 1080
        if size == "native":
            try:
                g = QApplication.primaryScreen().size()
                return int(g.width()) - int(g.width()) % 2, int(g.height()) - int(g.height()) % 2
            except Exception:
                pass
        try:
            w = max(320, int(self.width()))
            h = max(240, int(self.height()))
        except Exception:
            w, h = 1280, 720
        # Even dimensions required by most codecs
        w -= w % 2
        h -= h % 2
        return w, h

    def _export_provenance_payload(self):
        """Self-describing generation manifest embedded in every export (audio
        WAV chunk / ffmpeg comment / game provenance.mgpr).  Small, plain,
        standard metadata so reverse-engineering an export back onto the main
        window is a simple parameter copy — and re-rendering with these values
        reproduces the exact artifact.  Device-independent (no timestamps).
        """
        # Local helper — export must never fail with NameError on _safe_json
        # (was previously only defined inside _project_snapshot).
        def _safe_json(obj):
            try:
                return copy.deepcopy(obj)
            except Exception:
                try:
                    return json.loads(json.dumps(obj, default=str))
                except Exception:
                    return None

        def _num(widget, default=0.0):
            w = getattr(self, widget, None)
            if w is not None and hasattr(w, "value"):
                try:
                    return float(w.value())
                except Exception:
                    return default
            return default

        def _txt(widget, default=""):
            w = getattr(self, widget, None)
            if w is None:
                return default
            try:
                if hasattr(w, "toPlainText"):
                    return w.toPlainText()
                return str(w.text() if hasattr(w, "text") else default)
            except Exception:
                return default

        def _on(button):
            b = getattr(self, button, None)
            if b is None:
                return 0.0
            try:
                return 1.0 if b.isChecked() else 0.0
            except Exception:
                return 0.0

        manifest = {
            "doc": "eqr_export_manifest_v1",
            "fingerprint": None,
            # PI_MEDIA_HUB_2026: absolute project path so batch re-render can
            # reopen the linked .mgpr and re-export at new FPS/bitrate.
            "source_project_path": str(getattr(self, "_current_project_path", "") or "") or None,
            "seed": _txt("input_seed_val", ""),
            "bpm": _num("spin_bpm", 120.0),
            "seq_length": _num("spin_seq_length", 16.0),
            "track_offset": float(getattr(self, "global_track_offset", 0.0)),
            "base_frequency": _num("spin_base_frequency", 432.0),
            "global_convolve": _num("spin_global_convolve", 0.0),
            "clip_ratio_pct": _num("spin_clip_ratio", 50.0),
            "import_speed": _num("spin_import_speed", 1.0),
            "speed_scrub": 1.0 if (getattr(self, "chk_speed_scrub", None) and self.chk_speed_scrub.isChecked()) else 0.0,
            "speed_scrub_depth": _num("spin_speed_scrub", 0.0),
            "sparse_mask": 1.0 if (getattr(self, "chk_sparse_mask", None) and self.chk_sparse_mask.isChecked()) else 0.0,
            "sparse_density": _num("spin_sparse_density", 1.0),
            # Documented composition inputs that the canonical fingerprint reads:
            # re-applying these to a fresh window and recomposing deterministically
            # reproduces the exported artifact's identity.
            "engine_strength": _num("spin_engine_strength", CANONICAL_SEED_WEIGHT_DEFAULT),
            "synth_count": int(round(_num("spin_synth_count", 48.0))),
            "engines": {
                "seeded": _on("btn_seeded_randomize"),
                "randomizer": _on("btn_local_randomize"),
                "phase_lock": _on("btn_local_phase_lock"),
                "euclidean": _on("btn_idealize_rhythm"),
                "goava": _on("btn_goava"),
                "fractal_seed": _on("btn_fractal_seed_mode"),
            },
            "canonical_levels": _safe_json(self._canonical_levels()),
            "phase_lock_characteristics": _safe_json(self._lock_characteristics()),
            "rand_instance_seed": int(getattr(self, "_rand_instance_seed", 0) or 0),
            "rand_generation_counter": int(getattr(self, "_rand_generation_counter", 0) or 0),
            "draw_record_3d": {
                "model_path": str(getattr(self,"imported_3d_model_path","") or ""),
                "model_meta": _safe_json(getattr(self,"imported_3d_model_meta",{}) or {}),
                "grid_size": int(getattr(self,"voxel_grid_size",16) or 16),
                "alias_pct": int(getattr(self,"voxel_alias_pct",0) or 0),
                "paint_color": _safe_json(getattr(self,"voxel_paint_color",[80,220,200]) or [80,220,200]),
                "paint_blend_pct": int(getattr(self,"voxel_paint_blend_pct",86) or 86),
                "voxels": _safe_json(getattr(self,"voxel_cells",[]) or []),
            },
            "master_volume": _num("slider_master_vol", 72.0),
            "dj": {
                "boost": _num("slider_pkp_boost", 0.0),
                "boost_pitch": _num("slider_pkp_boost_pitch", 0.0),
                "boost_steps": _num("slider_pkp_boost_steps", 1.0),
                "boost_offset": _num("slider_pkp_boost_offset", 0.5),
                "boost_mod": _num("slider_pkp_boost_mod", 0.0),
                "boost_prob": _num("slider_pkp_boost_prob", 100.0),
                "boost_env": _num("slider_pkp_boost_env", 0.0),
                "envelope": _num("slider_pkp_envelope", 0.0),
            },
            "fx": {
                "eqr": _num("slider_eqr", 0.0),
                "fractalizer": _num("slider_fractalizer", 0.0),
            },
            "operator_media_samples": {str(k): {"path": str(v.get("path", "")), "source_kind": str(v.get("source_kind", "audio")), "video_path": str(v.get("video_path", "")), "video_input_enabled": bool(v.get("video_input_enabled", False)), "layered_state": _safe_json(v.get("layered_state", {}))} for k, v in (getattr(self, "instrument_media_samples", {}) or {}).items() if isinstance(v, dict) and v.get("path")},
            "media_workbench_state": _safe_json(self._collect_media_workbench_state()),
            "scode_optimizer": _safe_json(self._scode_optimizer.state_for_project() if getattr(self, "_scode_optimizer", None) is not None else {"required": True}),
            "author_numeric_font": _safe_json(AUTHOR_NUMERIC_FONT.project_manifest()),
            "sample_morph": _safe_json(getattr(self, "sample_morph_state", {})),
            "global_mod": _safe_json(getattr(self, "global_mod_state", {})),
            "canonical_blend_contract": {
                "canonical_control_min": 0.50,
                "userdata_share_min": 0.50,
                "carrier_as_modulation_source": True,
                "carrier_phase_lock": 0.50,
                "multi_target_blend": True,
                "arbitrary_time_offsets": True,
            },
            "canonical_user_blend_ledger": _safe_json(getattr(self, "_canonical_user_blend_ledger", {})),
            "canonical_user_carrier_proof": self._verify_canonical_user_carrier_contract(
                getattr(self, "imported_waveform", None) is not None
            ),
            "master_vector": {
                "x": float((getattr(self, "master_vector_state", {}) or {}).get("x", 0.0)),
                "y": float((getattr(self, "master_vector_state", {}) or {}).get("y", 0.0)),
                "z": float((getattr(self, "master_vector_state", {}) or {}).get("z", 0.0)),
                "drive": float((getattr(self, "master_vector_state", {}) or {}).get("drive", 0.5)),
                "enabled": bool((getattr(self, "master_vector_state", {}) or {}).get("enabled", True)),
                "guard": bool((getattr(self, "master_vector_state", {}) or {}).get("guard", True)),
                "canonical_weight": 0.5,
                "user_weight": 0.5,
            },
        }
        # GAME_AUDIO_CONTRACT_2026: the numeric triad (audio/visual/game
        # quantities) is the single cross-verification key between an audio/video
        # export and the exported game package.  It is a closed-form function of
        # the composition seed alone, so both artifacts derive the same value and
        # _triad_digest() can prove they came from one project.
        try:
            _gm = self._composition_meta_for_game()
            _gt = _vge.game_triad(_gm.get("seed"))
            if isinstance(_gt, dict):
                manifest["game_triad"] = _gt
        except Exception:
            pass
        try:
            manifest["fingerprint"] = self._canonical_fingerprint()
        except Exception:
            manifest["fingerprint"] = None
        try:
            manifest["composition_fingerprint"] = self.visual_composition_fingerprint()
        except Exception:
            manifest["composition_fingerprint"] = None
        rules = getattr(self, "_video_assembly_rules", None)
        if isinstance(rules, dict):
            manifest["video_assembly_rules"] = dict(rules)
        try:
            manifest["seed_script_video_overrides"] = self._seed_script_video_overrides()
        except Exception:
            manifest["seed_script_video_overrides"] = {}
        try:
            manifest["lookup"] = self._lookup_proof()
        except Exception:
            manifest["lookup"] = {"mode": "lookup"}
        return json.dumps(manifest, sort_keys=True, separators=(",", ":"))

    def _apply_provenance_payload(self, payload):
        """Restore the main-window inputs documented in an export manifest."""
        if not isinstance(payload, dict) or payload.get("doc") != "eqr_export_manifest_v1":
            return False
        if isinstance(payload.get("canonical_levels"), dict):
            self.canonical_engine_levels.update({k: float(np.clip(float(v),0.0,1.0)) for k,v in payload["canonical_levels"].items() if k in self.canonical_engine_levels})
        if isinstance(payload.get("phase_lock_characteristics"), dict):
            self.phase_lock_characteristics.update({k: float(np.clip(float(v),0.0,1.0)) for k,v in payload["phase_lock_characteristics"].items() if k in self.phase_lock_characteristics})
        _rs = int(payload.get("rand_instance_seed",0) or 0); self._rand_instance_seed = _rs if _rs else None
        self._rand_generation_counter = int(payload.get("rand_generation_counter", getattr(self,"_rand_generation_counter",0)) or 0)
        _dr = payload.get("draw_record_3d") if isinstance(payload.get("draw_record_3d"), dict) else {}
        if _dr:
            self.imported_3d_model_path = str(_dr.get("model_path","") or "")
            self.imported_3d_model_meta = copy.deepcopy(_dr.get("model_meta",{}) or {})
            self.voxel_grid_size = max(4,min(64,int(_dr.get("grid_size",16) or 16)))
            self.voxel_alias_pct = max(0,min(100,int(_dr.get("alias_pct",0) or 0)))
            self.voxel_paint_color = [max(0,min(255,int(x))) for x in list(_dr.get("paint_color", [80,220,200]) or [80,220,200])[:3]]
            self.voxel_paint_blend_pct = max(0,min(100,int(_dr.get("paint_blend_pct",86) or 86)))
            self.voxel_cells = self._normalize_voxel_records(_dr.get("voxels") or [])
        try: self._sync_canonical_widgets_from_state()
        except Exception: pass

        setmap = {
            "bpm": ("spin_bpm", float),
            "seq_length": ("spin_seq_length", float),
            "track_offset": ("spin_global_track_offset", float),
            "base_frequency": ("spin_base_frequency", float),
            "global_convolve": ("spin_global_convolve", float),
            "clip_ratio_pct": ("spin_clip_ratio", float),
            "import_speed": ("spin_import_speed", float),
            "speed_scrub": ("chk_speed_scrub", bool),
            "speed_scrub_depth": ("spin_speed_scrub", float),
            "sparse_mask": ("chk_sparse_mask", bool),
            "sparse_density": ("spin_sparse_density", float),
            "master_volume": ("slider_master_vol", float),
            "engine_strength": ("spin_engine_strength", float),
            "synth_count": ("spin_synth_count", int),
        }
        for manifest_key, (attr, cast) in setmap.items():
            if manifest_key not in payload:
                continue
            w = getattr(self, attr, None)
            if w is None:
                continue
            try:
                w.blockSignals(True)
                if cast is bool and hasattr(w, "setChecked"):
                    w.setChecked(bool(payload[manifest_key]))
                elif hasattr(w, "setValue"):
                    w.setValue(cast(payload[manifest_key]))
            except Exception:
                try:
                    w.setValue(0)
                except Exception:
                    pass
            finally:
                try:
                    w.blockSignals(False)
                except Exception:
                    pass
        dj = payload.get("dj") if isinstance(payload.get("dj"), dict) else {}
        fx = payload.get("fx") if isinstance(payload.get("fx"), dict) else {}
        fills = list(dj.items()) + list(fx.items())
        for key, val in fills:
            w = getattr(self, key, None)
            if w is None or not hasattr(w, "setValue"):
                continue
            try:
                w.blockSignals(True)
                w.setValue(float(val))
                w.blockSignals(False)
            except Exception:
                pass
        if isinstance(payload.get("sample_morph"), dict):
            self.sample_morph_state.update({k: payload["sample_morph"][k] for k in ("enabled", "adaptive_fit", "phase_lock", "guard") if k in payload["sample_morph"]})
            try:
                self.chk_sample_precano.setChecked(bool(self.sample_morph_state.get("enabled", True)))
                self.slider_sample_adaptive_fit.setValue(int(round(float(self.sample_morph_state.get("adaptive_fit", .50))*50)))
                self.slider_sample_phase_lock.setValue(int(round(float(self.sample_morph_state.get("phase_lock", .50))*50)))
                self.chk_sample_guard.setChecked(bool(self.sample_morph_state.get("guard", True)))
            except Exception: pass

        # MASTER_VECTOR_PROVENANCE_2026: exports carry the explicit user-vector
        # settings so an exported artifact can be rehydrated onto the same render path.
        mv = payload.get("master_vector") if isinstance(payload.get("master_vector"), dict) else {}
        if mv:
            try:
                self.master_vector_state.update({
                    k: mv[k] for k in ("x", "y", "z", "drive", "enabled", "guard") if k in mv
                })
                for key in ("x", "y", "z"):
                    if key in getattr(self, "master_vector_sliders", {}):
                        sl, lab = self.master_vector_sliders[key]
                        sl.blockSignals(True); sl.setValue(int(round(float(self.master_vector_state.get(key, 0.0)) * 100.0))); sl.blockSignals(False)
                        lab.setText(f"{float(self.master_vector_state.get(key, 0.0)):+.2f}")
                if hasattr(self, "slider_master_vector_drive"):
                    self.slider_master_vector_drive.blockSignals(True); self.slider_master_vector_drive.setValue(int(round(float(self.master_vector_state.get("drive", 0.5)) * 100.0))); self.slider_master_vector_drive.blockSignals(False)
                if hasattr(self, "btn_master_vector_convert"):
                    self.btn_master_vector_convert.setChecked(bool(self.master_vector_state.get("enabled", True)))
                    self.btn_master_vector_convert.setText("VECTOR CONVERT · ON" if self.btn_master_vector_convert.isChecked() else "VECTOR CONVERT · OFF")
                if hasattr(self, "chk_master_vector_guard"):
                    self.chk_master_vector_guard.setChecked(bool(self.master_vector_state.get("guard", True)))
                self._master_vector_effective()
            except Exception:
                pass
        if isinstance(payload.get("video_assembly_rules"), dict):
            self._video_assembly_rules = dict(payload["video_assembly_rules"])
        if isinstance(payload.get("seed_script_video_overrides"), dict):
            self._restored_seed_script_video_overrides = dict(payload["seed_script_video_overrides"])
        if isinstance(payload.get("media_workbench_state"), dict):
            try:
                self._restore_media_workbench_state(payload.get("media_workbench_state", {}))
            except Exception:
                pass
        if isinstance(payload.get("operator_media_samples"), dict):
            # Rehydrate user-owned operator media and retain the layered
            # Draw/Record reconstruction recipe when the source file remains.
            try:
                restored_media = {}
                for _op, _rec in payload.get("operator_media_samples", {}).items():
                    if not isinstance(_rec, dict) or not _rec.get("path"):
                        continue
                    _path = str(_rec.get("path"))
                    if not os.path.isfile(_path):
                        continue
                    _arr, _sr = self._decode_media_audio(_path)
                    if getattr(_arr, "size", 0):
                        restored_media[str(_op)] = {
                            "path": _path, "sample_rate": int(_sr), "waveform": _arr,
                            "user_owned": True, "source_kind": str(_rec.get("source_kind", "audio")),
                            "video_path": str(_rec.get("video_path", "")),
                            "video_input_enabled": bool(_rec.get("video_input_enabled", False)),
                            "layered_state": copy.deepcopy(_rec.get("layered_state", {})) if isinstance(_rec.get("layered_state"), dict) else {},
                        }
                if restored_media:
                    self.instrument_media_samples = restored_media
                    try: self._refresh_operator_sample_ui()
                    except Exception: pass
            except Exception as _prov_media_exc:
                print(f"[Reconvert] operator media skipped: {_prov_media_exc}")
        # sCode remains mandatory; serialized optimizer data is provenance only.
        if isinstance(payload.get("scode_optimizer"), dict):
            try:
                if getattr(self, "_scode_optimizer", None) is not None:
                    self._scode_optimizer._last_categories = {}
            except Exception:
                pass

        seed = str(payload.get("seed") or "")
        if hasattr(self, "input_seed_val") and self.input_seed_val is not None:
            try:
                self.input_seed_val.blockSignals(True)
                if hasattr(self.input_seed_val, "setPlainText"):
                    self.input_seed_val.setPlainText(seed)
                elif hasattr(self.input_seed_val, "setText"):
                    self.input_seed_val.setText(seed)
                self.input_seed_val.blockSignals(False)
            except Exception:
                pass
        try:
            self._on_live_source_changed()
        except Exception:
            pass
        # Engine toggles are restored UNBLOCKED so activation regenerates the
        # composition from the documented inputs (seed/bpm/base + engine mask).
        engines = payload.get("engines") if isinstance(payload.get("engines"), dict) else {}
        for eng_name, attr in (
            ("seeded", "btn_seeded_randomize"), ("randomizer", "btn_local_randomize"),
            ("phase_lock", "btn_local_phase_lock"), ("euclidean", "btn_idealize_rhythm"), ("goava", "btn_goava"),
            ("fractal_seed", "btn_fractal_seed_mode"),
        ):
            if eng_name not in engines:
                continue
            b = getattr(self, attr, None)
            if b is None:
                continue
            try:
                b.setChecked(bool(engines[eng_name]))
            except Exception:
                pass
        # Let engine-triggered (possibly deferred) scope work complete, then
        # re-assert the documented instrument count/strength LAST so a faithful
        # rebuild reproduces the exported artifact's composition identity.
        # SWEEP_20261107: no processEvents here; it re-enters the UI.
        for mkey, attr in (("synth_count", "spin_synth_count"), ("engine_strength", "spin_engine_strength")):
            if mkey not in payload:
                continue
            w = getattr(self, attr, None)
            if w is None or not hasattr(w, "setValue"):
                continue
            try:
                # spin_synth_count is an int QSpinBox (PyQt6 rejects float).
                _val = int(round(float(payload[mkey]))) if mkey == "synth_count" else float(payload[mkey])
                w.setValue(_val)
            except Exception:
                pass
        return True

    def _recompose_project(self, pump=3):
        """Regenerate the composition deterministically from the documented
        inputs (seed / BPM / base frequency / engine mask), stop the live
        engines' timers, and commit perfect unison so the canonical fingerprint
        reflects the final committed state — not intermediate rebuild frames."""
        from PyQt6.QtWidgets import QApplication as _QA
        # Explicit project/load recompose must execute even when its final numeric
        # identity matches the previously committed project. Invalidate only the
        # canonical work claim; all other sCode caches remain reusable.
        _opt = getattr(self, "_scode_optimizer", None)
        if _opt is not None:
            _opt.invalidate_work("canonical")
            _opt.request_host_plan(self, force=True)
        for t in (getattr(self, "_live_euclid_timer", None), getattr(self, "_live_seeded_timer", None)):
            if t is not None:
                try:
                    t.stop()
                except Exception:
                    pass
        # SWEEP_20261107: no processEvents; unison runs without re-entering the UI.
        try:
            self._ensure_perfect_unison()
        except Exception:
            pass

    def _triad_digest(self, triad_obj):
        """Stable short digest of a numeric game triad (audio/visual/game)."""
        try:
            if not isinstance(triad_obj, dict):
                return ""
            compact = {}
            for p in ("audio", "visual", "game"):
                if isinstance(triad_obj.get(p), dict):
                    compact[p] = {
                        str(k): round(float(v), 6)
                        for k, v in triad_obj[p].items() if isinstance(v, (int, float))
                    }
            return hashlib.sha256(json.dumps(compact, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()[:12]
        except Exception:
            return ""

    def _triad_matches(self, manifest_triad, zip_triad):
        """GAME_AUDIO_CONTRACT_2026: field-wise cross-verification between the
        audio manifest's game_triad and the game package's triad.mgpr.  All
        audio/visual quantities and all game quantities except sigil_count must
        agree to float64 precision; sigil_count is classification-tracked (the
        package legitimately pins its own), so it is reported separately."""
        try:
            if not (isinstance(manifest_triad, dict) and isinstance(zip_triad, dict)):
                return None, ""
            note = []
            for p in ("audio", "visual"):
                a = manifest_triad.get(p) or {}
                b = zip_triad.get(p) or {}
                for k in set(a) | set(b):
                    if abs(float(a.get(k, 0.0)) - float(b.get(k, 0.0))) > 1e-6:
                        return False, f"{p}.{k} differs"
            a = manifest_triad.get("game") or {}
            b = zip_triad.get("game") or {}
            for k in set(a) | set(b):
                if k == "sigil_count":
                    if int(a.get(k, 0) or 0) != int(b.get(k, 0) or 0):
                        note.append(f"sigil_count {a.get(k)} vs {b.get(k)}")
                    continue
                if abs(float(a.get(k, 0.0)) - float(b.get(k, 0.0))) > 1e-6:
                    return False, f"game.{k} differs"
            return True, (" · " + "; ".join(note)) if note else ""
        except Exception:
            return None, ""

    def _extract_provenance_from_file(self, file_path):
        """Read the export manifest back out of a WAV / media file / game zip."""
        low = str(file_path).lower()
        if low.endswith((".wav", ".aiff", ".aif")):
            payload = _extract_wav_provenance(file_path)
            if payload:
                return payload
        low = str(file_path).lower()
        if low.endswith((".zip", ".mcc")):
            try:
                import zipfile as _zf
                with _zf.ZipFile(self._package_zip_source(file_path)) as zf:
                    names = set(zf.namelist())
                    for cand in ("provenance.mgpr", "main_window_settings.mgpr", "multimodal_contract.mgpr"):
                        if cand in names:
                            try:
                                payload = json.loads(zf.read(cand).decode("utf-8"))
                                # Legacy packages double-encode the manifest via
                                # json.dumps when embedding the provenance string;
                                # unwrap a single layer so payload is always a dict.
                                if isinstance(payload, str):
                                    payload = json.loads(payload)
                                # GAME_AUDIO_CONTRACT_2026: when this is a game zip,
                                # also surface the package's own triad.mgpr so the
                                # reconvert step can cross-verify the audio export's
                                # manifest against the game's numeric contract key.
                                for triad_cand in ("assets/triad.mgpr", "triad.mgpr"):
                                    if triad_cand in names:
                                        try:
                                            payload["_zip_triad"] = json.loads(zf.read(triad_cand).decode("utf-8"))
                                        except Exception:
                                            pass
                                        break
                                return payload
                            except Exception:
                                continue
            except Exception:
                pass
        ffprobe = resolve_local_tool("ffprobe", required=False)
        if ffprobe:
            try:
                proc = subprocess.run(
                    [ffprobe, "-v", "error", "-show_entries", "format_tags=comment", "-of", "json", file_path],
                    capture_output=True, text=True, timeout=60,
                )
                tags = json.loads(proc.stdout or "{}").get("format", {}).get("tags", {})
                comment = tags.get("comment") or tags.get("COMMENT") or ""
                if comment:
                    return json.loads(comment)
            except Exception:
                pass
        return None

    def reconvert_export_dialog(self):
        """REVERSE-ENGINEERING: rebuild the main window from an exported
        artifact.  Reads the plain provenance manifest the export carried
        (WAV 'eqrf' chunk / ffmpeg 'comment' tag / game provenance.mgpr) and
        re-applies every documented input so a re-render reproduces the same
        artifact; the restored canonical fingerprint is shown for comparison.
        """
        filter_all = "Exports (*.MCC *.mcc *.wav *.flac *.mp3 *.ogg *.opus *.caf *.aiff *.mp4 *.webm *.avi *.zip);;All files (*)"
        file_path, _ = QFileDialog.getOpenFileName(self, "Reconvert Export → Main Window", self._exports_dir(), filter_all)
        if not file_path:
            return
        payload = self._extract_provenance_from_file(file_path)
        if not payload:
            QMessageBox.warning(
                self, "Reconvert Export",
                "No EQR export manifest found in this file.\n"
                "Only artifacts written by this app carry the document; a plain "
                "file cannot be reverse-engineered back to the original window."
            )
            return
        restored_ok = self._apply_provenance_payload(payload)
        if restored_ok and payload.get("engines"):
            try:
                self._recompose_project()
            except Exception:
                pass
        try:
            self._refresh_canonical_fingerprint()
        except Exception:
            pass
        fp = payload.get("fingerprint")
        cur = ""
        try:
            cur = self._canonical_fingerprint()
        except Exception:
            cur = ""
        # GAME_AUDIO_CONTRACT_2026: if the artifact is a game zip, cross-verify
        # the embedded triad.mgpr against the audio manifest's game_triad key —
        # both must be the same closed-form f(seed), proving the audio and game
        # came from one project.
        triad_note = ""
        try:
            _gt = payload.get("game_triad")
            _zt = payload.get("_zip_triad")
            if isinstance(_gt, dict) and isinstance(_zt, dict):
                _ok, _why = self._triad_matches(_gt, _zt)
                if _ok is True:
                    triad_note = " · 🎮⇄♫ game triad matches" + _why
                elif _ok is False:
                    triad_note = f" · game triad ≠ manifest ({_why})"
        except Exception:
            triad_note = ""
        if restored_ok:
            match = "✓ fingerprint matches" if (fp and cur and fp == cur) else ("≠ fingerprint differs" if fp else "")
            self.scope_status_label.setText(
                f"♻ Reconverted export → main window restored{(' · ' + match) if match else ''}{triad_note}"
            )
            if fp and cur:
                QMessageBox.information(
                    self, "Reconvert Export",
                    f"Main window restored from:\n{os.path.basename(file_path)}\n\n"
                    f"export fingerprint: {fp}\ncurrent fingerprint:  {cur}\n\n{match}{triad_note}"
                )
            else:
                QMessageBox.information(self, "Reconvert Export", "Main window restored from export manifest." + triad_note)
        else:
            QMessageBox.warning(self, "Reconvert Export", "Manifest recognized but could not be restored.")

    @staticmethod
    def _package_zip_source(path):
        """A zip-readable source for a game/software package (.zip, or .MCC package)."""
        try:
            import mcc_media as _mm
            if _mm.media_kind(path) == "package":
                import zipfile as _zf
                import io as _io
                buf = _io.BytesIO()
                with _zf.ZipFile(buf, "w", _zf.ZIP_STORED) as zf:
                    for btype, meta, payload in _mm._blocks(path):
                        if btype == b"F":
                            zf.writestr(meta["path"], payload)
                buf.seek(0)
                return buf
        except Exception as exc:
            print(f"[Import] MCC package: {exc}")
        return path

    def _recover_program_bundle(self, zip_path):
        """REVERSE-ENGINEERING: a .zip export written by this app is fully
        self-describing.  Read the package back into its recoverable parts — the
        emitted program source, its identity, the audio<->game triad contract,
        the software-lattice proof, and the provenance manifest that rebuilds
        the original main window.  Returns a bundle dict for display/saving.
        """
        import zipfile as _zf
        import hashlib as _hl
        bundle = {
            "zip": str(zip_path),
            "files": [], "program": None, "identity": None, "triad": None,
            "payload": None, "lattice": None,
            "restored": False, "fp_match": None, "triad_ok": None, "triad_note": "",
        }
        try:
            with _zf.ZipFile(self._package_zip_source(zip_path)) as zf:
                names = zf.namelist()
                script_name = ""
                script_size = 0
                for n in names:
                    low = n.lower()
                    if not any(low.endswith(e) for e in (".py", ".mgpr", ".md", ".sh", ".bat", ".command", ".txt")):
                        continue
                    try:
                        data = zf.read(n)
                    except Exception:
                        continue
                    bundle["files"].append({
                        "name": n, "size": len(data),
                        "sha256": _hl.sha256(data).hexdigest()[ :16],
                    })
                    if low.endswith(".py"):
                        if len(data) > script_size:
                            script_size = len(data)
                            script_name = n
                            bundle["program"] = {
                                "name": n, "size": len(data),
                                "sha256": _hl.sha256(data).hexdigest(),
                                "head": data[:6000].decode("utf-8", "replace"),
                            }
                for n in names:
                    low = n.lower()
                    if not low.endswith(".mgpr"):
                        continue
                    try:
                        obj = json.loads(zf.read(n).decode("utf-8"))
                    except Exception:
                        continue
                    if isinstance(obj, str):
                        try:
                            obj = json.loads(obj)
                        except Exception:
                            continue
                    if not isinstance(obj, dict):
                        continue
                    base = os.path.basename(n).lower()
                    if "provenance" in base or "manifest" in base or "main_window_settings" in base:
                        if bundle["payload"] is None:
                            bundle["payload"] = obj
                    elif "triad" in base:
                        if bundle["triad"] is None:
                            bundle["triad"] = obj
                    elif base.startswith("game_") or "identity" in base:
                        if bundle["identity"] is None and isinstance(obj, dict) and "title" in obj:
                            bundle["identity"] = obj
                    elif "lattice" in base:
                        bundle["lattice"] = obj
            # The .py script name is discovered above; also accept the classic
            # launcher set as proof of a fully self-contained package.
            if script_name and bundle["program"]:
                bundle["program"]["name"] = script_name
        except Exception:
            return bundle
        payload = bundle["payload"]
        if payload:
            try:
                bundle["restored"] = bool(self._apply_provenance_payload(payload))
            except Exception:
                bundle["restored"] = False
            if bundle["restored"] and payload.get("engines"):
                try:
                    self._recompose_project()
                except Exception:
                    pass
            try:
                self._refresh_canonical_fingerprint()
            except Exception:
                pass
            try:
                cur = self._canonical_fingerprint()
                bundle["fp_match"] = bool(payload.get("fingerprint")) and payload["fingerprint"] == cur
            except Exception:
                bundle["fp_match"] = None
            if bundle["triad"]:
                try:
                    _ok2, _why2 = self._triad_matches(payload.get("game_triad"), bundle["triad"])
                    bundle["triad_ok"], bundle["triad_note"] = _ok2, _why2
                except Exception:
                    pass
        return bundle

    def _apply_video_plan_to_frame(self, frame, fi, n_frames):
        """Color map, temporal phase, and transition from the current plan."""
        plan = getattr(self, "_last_plan", None) or getattr(self, "_video_assembly_rules", None) or {}
        if not isinstance(plan, dict) or frame is None:
            return frame
        out = np.asarray(frame, dtype=np.float32)
        ph = float(fi) / float(max(1, n_frames - 1))
        cmap = str(plan.get("color_map") or "default")
        if cmap == "density":
            g = out.mean(axis=2, keepdims=True)
            out = np.concatenate([g, g * 0.7, g * 0.4], axis=2)
        elif cmap == "phase":
            out[..., 0] = np.clip(out[..., 0] * (0.4 + ph), 0, 255)
            out[..., 2] = np.clip(out[..., 2] * (1.2 - ph), 0, 255)
        elif cmap == "seed_hue":
            hue = (int(plan.get("seed") or 0) % 360) / 360.0
            out[..., 0] = np.clip(out[..., 0] * (0.5 + hue), 0, 255)
            out[..., 1] = np.clip(out[..., 1] * (0.5 + (1.0 - hue)), 0, 255)
        # R/G/B channel routing with a blend amount (colour convolution).
        order = str(plan.get("channel_order") or "RGB").upper()
        if len(order) == 3 and sorted(order) == ["B", "G", "R"] and order != "RGB":
            try:
                mix = float(np.clip(float(plan.get("channel_mix", 1.0)), 0.0, 1.0))
            except Exception:
                mix = 1.0
            swapped = out[..., ["RGB".index(c) for c in order]]
            out = (1.0 - mix) * out + mix * swapped if mix < 1.0 else swapped
        phase = str(plan.get("temporal_phase_source") or "none")
        if phase == "meum":
            out *= 0.85 + 0.15 * abs((ph * 2.0) - 1.0)
        elif phase == "isn":
            out = 255.0 - out if ph > 0.5 else out
        elif phase == "seed":
            out *= 0.75 + 0.25 * ((int(plan.get("seed") or 1) % 7) / 7.0)
        mode = str(plan.get("transition_mode") or "none")
        if mode == "crossfade" and ph < 0.08:
            out *= ph / 0.08
        elif mode == "lattice_morph":
            step = int(ph * 8)
            if step % 2 == 0:
                out[::2] *= 0.85
        elif mode == "cut" and 0.49 < ph < 0.51:
            out *= 0.2
        op = float(plan.get("overlay_opacity") or 1.0)
        if op < 1.0:
            out *= op
        # LIVE_JAM_VIDEO_DRIVE_20261104: brightness, contrast, color rotation,
        # and a negative flash from the active Live Jam controls.
        try:
            jam = getattr(self, "_live_jam_controls", {}) or {}
            jam_active = bool(getattr(getattr(self, "_live_jam_controller", None), "enabled", False))
            if jam_active and jam:
                # brightness (0-1, 0.5 = neutral)
                br = float(jam.get("brightness", 0.5))
                if abs(br - 0.5) > 0.01:
                    out *= (0.6 + 0.8 * br)
                # contrast (0-1, 0.5 = neutral)
                ct = float(jam.get("contrast", 0.5))
                if abs(ct - 0.5) > 0.01:
                    mean = out.mean()
                    out = mean + (out - mean) * (0.5 + ct)
                # color rotation (0-1 maps to hue shift via channel cycle)
                rot = float(jam.get("color_rotation", 0.0))
                if rot > 0.02:
                    shift = int(rot * 3) % 3
                    if shift:
                        out = np.roll(out, shift, axis=2)
                # negative flash (fx toggle)
                if jam.get("fx:Negative", 0.0) > 0.5 or jam.get("negative", 0.0) > 0.5:
                    out = 255.0 - out
        except Exception:
            pass
        return np.clip(out, 0, 255).astype(np.uint8)

    def _lookup_proof(self):
        """Video and game are lookups of the composition, not interpretations.

        Same seed + same fingerprint always yields the same proof token.
        """
        import hashlib
        fp = ""
        try:
            fp = self._canonical_fingerprint()
        except Exception:
            fp = ""
        seed = ""
        try:
            if hasattr(self, "input_seed_val") and self.input_seed_val is not None:
                seed = self.input_seed_val.toPlainText() if hasattr(self.input_seed_val, "toPlainText") else ""
        except Exception:
            seed = ""
        try:
            length = float(self._composition_length_seconds())
        except Exception:
            length = 0.0
        raw = ("%s|%s|%.4f" % (fp, seed.strip(), length)).encode("utf-8")
        token = hashlib.sha256(raw).hexdigest()[:16]
        return {
            "mode": "lookup",
            "fingerprint": fp,
            "composition_length_seconds": length,
            "token": token,
        }

    def _regenerate_and_compare(self, expected_token=None):
        proof = self._lookup_proof()
        match = expected_token is None or str(expected_token) == proof["token"]
        return match, proof

    def _export_integrity_ok(self, video_path=None, audio_rms=None):
        """Reject a black/silent export when the plan asked for an integrity gate."""
        if not getattr(self, "_last_integrity_check", True):
            return True, "integrity off"
        notes = []
        if audio_rms is not None and float(audio_rms) < 1e-4:
            notes.append("audio silent")
        if video_path and os.path.isfile(video_path):
            try:
                if os.path.getsize(video_path) < 1024:
                    notes.append("video too small")
            except Exception:
                pass
        if notes:
            return False, "; ".join(notes)
        return True, "ok"

    def _on_reverse_engineer_zip(self):
        """Import a game/software .zip export and recover the program it holds:
        the emitted source, its identity, the triad contract and the manifest,
        all demonstrated (fingerprint + triad cross-check) and optionally saved
        to a folder.  REVERSE_ENGINEERING: the export is the inverse of export.
        """
        filter_all = "Packages (*.MCC *.mcc *.zip);;All files (*)"
        path, _ = QFileDialog.getOpenFileName(self, "Reverse-Engineer Program from .MCC / .zip", self._games_dir(), filter_all)
        if not path:
            return
        bundle = self._recover_program_bundle(path)
        if not bundle.get("program") and not bundle.get("payload") and not bundle.get("lattice"):
            QMessageBox.warning(
                self, "Reverse-Engineer Program",
                "This package holds no recoverable program source or manifest.\n"
                "Only packages exported by this app are self-describing inverses."
            )
            return
        prog = bundle.get("program")
        payload = bundle.get("payload")
        lines = []
        lines.append(f"$ reverse-engineer {os.path.basename(path)}")
        lines.append(f"  recovered files ............ {len(bundle.get('files', []))}")
        if prog:
            lines.append(f"  program .................... {prog['name']}")
            lines.append(f"  program sha256 ............. {prog['sha256'][:32]}…")
            lines.append(f"  program size ............... {prog['size']} bytes")
        if bundle.get("identity"):
            _id = bundle["identity"]
            lines.append(f"  identity ................... {_id.get('title', '?')} "
                         f"[{_id.get('genre', '?')} / {_id.get('camera', '?')} / {_id.get('objective', '?')}]")
        if payload:
            lines.append(f"  origin seed ................ {payload.get('seed')}")
            lines.append(f"  manifest fingerprint ....... {payload.get('fingerprint')}")
            lines.append(f"  composition fingerprint .... {payload.get('composition_fingerprint')}")
            if payload.get("video_assembly_rules"):
                lines.append("  video assembly rules ....... restored")
            lookup = payload.get("lookup") if isinstance(payload.get("lookup"), dict) else {}
            if lookup.get("token"):
                ok, proof = self._regenerate_and_compare(lookup.get("token"))
                lines.append("  lookup proof ............... %s (%s)" % ("✓ same composition" if ok else "≠ diverged", proof.get("token")))
            lines.append(f"  main window restored ....... {'yes' if bundle.get('restored') else 'no'}")
            if bundle.get("fp_match") is True:
                lines.append("  fingerprint proof .......... ✓ reconstructs the exact original window")
            elif bundle.get("fp_match") is False:
                lines.append("  fingerprint proof .......... ≠ (window differs from manifest)")
        if bundle.get("triad"):
            t_ok = bundle.get("triad_ok")
            if t_ok is True:
                lines.append("  triad proof ................ ✓ audio<->game key matches the package" + (bundle.get("triad_note") or ""))
            elif t_ok is False:
                lines.append("  triad proof ................ ✗ differs from game_triad (%s)" % bundle.get("triad_note"))
        if bundle.get("lattice"):
            _lp = bundle["lattice"]
            if isinstance(_lp, dict):
                _keys = list(_lp.keys())
                lines.append(f"  lattice proof .............. {_keys[:6]}")
            else:
                lines.append(f"  lattice proof .............. {len(_lp)} entries")
        detail = "\n".join(lines)
        dlg = QDialog(self)
        dlg.setWindowTitle("🔓 Reverse-Engineered Program from .zip")
        dlg.resize(760, 560)
        dlg.setStyleSheet(DAW_STYLE if "DAW_STYLE" in dir() else "")
        lay = QVBoxLayout(dlg)
        lay.addWidget(QLabel(
            "<b>Reverse-engineered program</b> — the .MCC (or legacy .zip) package is the inverse of export: "
            "the program source, its identity, the triad contract and the provenance "
            "manifest are all recoverable, and re-applying the manifest reproduces the "
            "original main window."
        ))
        txt = QTextEdit()
        txt.setReadOnly(True)
        txt.setFont(QFont("Menlo", 10))
        body = detail + "\n\n" + ("— recovered program source —\n" + prog["head"] if prog else "")
        if not prog:
            body += "\n\n(no .py source embedded — manifest-only package)"
        txt.setPlainText(body)
        lay.addWidget(txt, 1)
        row = QHBoxLayout()
        save_btn = QPushButton("Save recovered program…")
        close_btn = QPushButton("Close")
        row.addWidget(save_btn)
        row.addStretch(1)
        row.addWidget(close_btn)
        lay.addLayout(row)
        close_btn.clicked.connect(dlg.accept)

        def _save():
            out_dir = QFileDialog.getExistingDirectory(
                self, "Save recovered program bundle to", self._games_dir()
            )
            if not out_dir:
                return
            saved = []
            try:
                if prog:
                    with open(os.path.join(out_dir, prog["name"]), "w", encoding="utf-8") as f:
                        f.write(prog["head"])
                        saved.append(prog["name"])
                for name_key, obj, label in (
                    ("identity", bundle.get("identity"), "identity_recovered.mgpr"),
                    ("triad", bundle.get("triad"), "triad_recovered.mgpr"),
                    ("payload", bundle.get("payload"), "provenance_recovered.mgpr"),
                ):
                    if isinstance(obj, dict):
                        with open(os.path.join(out_dir, label), "w", encoding="utf-8") as f:
                            json.dump(obj, f, indent=2, sort_keys=True)
                        saved.append(label)
                with open(os.path.join(out_dir, "recovered_README.md"), "w", encoding="utf-8") as f:
                    f.write("# Reverse-engineered from .zip\n\nSource: %s\n\n```\n%s\n```\n"
                            % (os.path.basename(path), detail))
                saved.append("recovered_README.md")
            except Exception as _ee:
                QMessageBox.warning(self, "Save recovered program", f"Could not save: {_ee}")
                return
            QMessageBox.information(
                self, "Save recovered program",
                "Recovered bundle written to:\n" + out_dir + "\n\n" + "\n".join("• " + s for s in saved)
            )

        save_btn.clicked.connect(_save)
        dlg.exec()
        self.scope_status_label.setText(
            f"🔓 Reverse-engineered program from {os.path.basename(path)} "
            f"({len(bundle.get('files', []))} files)"
        )

    def _bake_compare_render(self, payload):
        """Render the current window as one full canonical master (int16 pcm +
        sample rate + provenance).  Optionally applies a target manifest first
        (blocked, then restored) so A/B renders isolate the documented inputs."""
        pcm = None
        sr = 48000
        # Offline generation/export must not stop the live transport. Mixdown
        # works from a snapshot and is isolated from the output callback.
        try:
            # BUFFER_OFF_UI_20261107: export prepare must not freeze the window.
            master, sr = self._run_off_gui(lambda: self._get_shared_mixdown_buffer(purpose="Export prepare"))
            master = np.nan_to_num(np.asarray(master, dtype=np.float32), nan=0.0, posinf=1.0, neginf=-1.0)
        except Exception as _rexc:
            print(f"[BakeCompare] render failed: {_rexc}")
            return None, sr
        try:
            master = self._bake_dj_write(master, sr)
        except Exception:
            pass
        try:
            # Export gets the same hardclip path as live: vol × factors → clip.
            master, _ = self._master_hardclip(master, sr, apply_master_vol=True)
            # Bake/Compare's public contract is int16 PCM; do not reference
            # the audio-export dialog's local bit-depth variable here.
            pcm = quantize_float_master(master, 16)
        except Exception:
            pcm = None
        return pcm, sr

    def bake_compare_export_dialog(self):
        """BAKE_AND_COMPARE_2026: bake the current main window and an exported
        artifact side by side and diff the actual sample streams.

        A = current window rendered to canonical pcm (as export would write).
        B = the SAME render after applying the artifact's provenance manifest
            (blocked, then everything restored to A's values).
        Reports duration, peak, RMS and per-sample difference so "reconverting"
        is verified in the sample domain, not just the fingerprint domain.
        """
        filter_all = "Exports (*.MCC *.mcc *.wav *.flac *.mp3 *.ogg *.opus *.caf *.aiff *.mp4 *.webm *.avi *.zip);;All files (*)"
        file_path, _ = QFileDialog.getOpenFileName(self, "Bake & Compare Export", self._exports_dir(), filter_all)
        if not file_path:
            return
        target = self._extract_provenance_from_file(file_path)
        if not target:
            QMessageBox.warning(
                self, "Bake & Compare",
                "No EQR export manifest found in this file — cannot bake a "
                "comparable render from it."
            )
            return
        # EXPORT_SCHEDULER_R31: A/B renders run in a worker process on a frozen copy of this
        # project, so the window is never mutated mid-compare and never waits.
        job = self._export_scheduler().submit_job(
            "bake_compare", str(file_path), {"target": target, "file_label": os.path.basename(file_path)},
            label="BAKE & COMPARE · " + os.path.basename(file_path))
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText(f"⚖ Bake & Compare #{job.id} queued · rendering A and B in a worker process")
        self.show_export_jobs()

    def _bake_compare_compute(self, target, file_label):
        """Worker side of Bake & Compare: returns (report, identical, rms_ratio)."""
        cur_manifest = self._export_provenance_payload()
        try:
            cur_payload = json.loads(cur_manifest)
        except Exception:
            cur_payload = None
        A, sr = self._bake_compare_render(None)
        if A is None or len(A) == 0:
            raise RuntimeError("Current render produced no audio.")
        # Apply the artifact's documented inputs (blocked), render B, restore.
        try:
            self._apply_provenance_payload(target)
        except Exception:
            pass
        try:
            self._refresh_canonical_fingerprint()
        except Exception:
            pass
        if hasattr(self, 'scope_status_label'):
            self.scope_status_label.setText("⚖ Bake & Compare: rendering artifact manifest (B)…")
        B, _sr2 = self._bake_compare_render(None)
        try:
            if cur_payload:
                self._apply_provenance_payload(cur_payload)
        except Exception:
            pass
        try:
            self._refresh_canonical_fingerprint()
        except Exception:
            pass
        if hasattr(self, 'scope_status_label'):
            self.scope_status_label.setText("⚖ Bake & Compare complete — window restored.")
        if B is None or len(B) == 0:
            raise RuntimeError("Artifact render produced no audio.")
        n = min(len(A), len(B))
        if n == 0:
            raise RuntimeError("Renders are empty.")
        len_match = len(A) == len(B)
        segA = A[:n].astype(np.float64) / 32767.0
        segB = B[:n].astype(np.float64) / 32767.0
        diff = segA - segB
        rms_a = float(np.sqrt(np.mean(segA * segA))) if n else 0.0
        rms_b = float(np.sqrt(np.mean(segB * segB))) if n else 0.0
        max_abs = float(np.max(np.abs(diff))) if n else 0.0
        denom = float(np.sqrt(np.mean(segA * segA)) + np.sqrt(np.mean(segB * segB)))
        rms_ratio = float(np.sqrt(np.mean(diff * diff)) / denom) if denom > 0.0 and math.isfinite(denom) else 0.0
        identical = bool(np.array_equal(A[:n], B[:n])) and len_match
        peak_a = float(np.max(np.abs(segA))) if n else 0.0
        peak_b = float(np.max(np.abs(segB))) if n else 0.0
        dur_a = len(A) / max(float(sr), 1.0)
        dur_b = len(B) / max(float(_sr2 or sr), 1.0)
        fp_cur = ""
        fp_tgt = str(target.get("fingerprint") or "")
        try:
            fp_cur = self._canonical_fingerprint()
        except Exception:
            fp_cur = ""
        report = (
            f"Current main window (A)\n"
            f"  duration {dur_a:.2f}s · peak {20.0 * math.log10(peak_a) if peak_a > 0.0 else -math.inf:+.1f} dBFS\n"
            f"  fingerprint {fp_cur or '—'}\n\n"
            f"Artifact manifest (B) from {file_label}\n"
            f"  duration {dur_b:.2f}s · peak {20.0 * math.log10(peak_b) if peak_b > 0.0 else -math.inf:+.1f} dBFS\n"
            f"  fingerprint {fp_tgt or '—'}\n\n"
            f"Diff (first {n} samples)\n"
            f"  identical: {'yes — bit-for-bit' if identical else 'no'}\n"
            f"  rms ratio: {rms_ratio:.6f} (0 = identical, 1 = unrelated)\n"
            f"  max abs diff: {max_abs:.6f}\n"
            f"  length match: {'yes' if len_match else f'no ({len(A)} vs {len(B)})'}\n"
            f"  rms A {rms_a:.4f} · rms B {rms_b:.4f}\n\n"
            f"Fingerprints {'match' if (fp_cur and fp_tgt and fp_cur == fp_tgt) else 'differ'}: "
            f"{fp_cur or '—'} vs {fp_tgt or '—'}"
        )
        return report, identical, rms_ratio

    def _default_export_part_count(self, duration_s=None):
        """Heuristic default part count in 1–128 from duration (and prior choice)."""
        prev = int(getattr(self, "_last_export_part_count", 0) or 0)
        if 1 <= prev <= 128:
            return prev
        try:
            d = float(duration_s) if duration_s is not None else 0.0
        except Exception:
            d = 0.0
        if d <= 30:
            return 4
        if d <= 120:
            return 8
        if d <= 600:
            return 16
        if d <= 1800:
            return 32
        return 64

    def _export_part_count_dialog(self, title="Export Parts", default=16, hint=""):
        """Modal Part Count selector (1–128) for all long export jobs.

        Returns int part count, or None if the user cancels.
        """
        try:
            default = int(default)
        except Exception:
            default = 16
        default = max(1, min(128, default))
        dlg = QDialog(self)
        dlg.setWindowTitle(str(title or "Export Parts"))
        try:
            dlg.setStyleSheet(getattr(self, "styleSheet", lambda: "")() or "")
        except Exception:
            pass
        form = QFormLayout(dlg)
        spin = QSpinBox()
        spin.setRange(1, 128)
        spin.setSingleStep(1)
        spin.setValue(default)
        spin.setToolTip(
            "How many recoverable .part segments to write.\n"
            "1 = single file (no partition). 16 is the classic default.\n"
            "Higher counts lower peak temp disk and improve crash resume."
        )
        form.addRow("Part Count (1–128)", spin)
        note = QLabel(
            (hint or "")
            + ("\n" if hint else "")
            + "Parts are written next to the final file as "
            "<stem>.partNN.<ext> (and <stem>.audio.partNN.wav for A/V). "
            "Completed parts can be resumed after a crash."
        )
        note.setWordWrap(True)
        form.addRow(note)
        btns = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel
        )
        btns.accepted.connect(dlg.accept)
        btns.rejected.connect(dlg.reject)
        form.addRow(btns)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return None
        n = max(1, min(128, int(spin.value())))
        self._last_export_part_count = n
        return n

    def _write_audio_parts_and_final(
        self,
        file_path,
        sample_rate,
        pcm_int16,
        n_parts=1,
        provenance_bytes=None,
        audio_format="wav",
        audio_bitrate_kbps=None,
        stitch_parts=True,
        bit_depth=16,
        expected_float_peak=None,
        worker_safe=False,
        progress_callback=None,
        cancel_event=None,
    ):
        """Write optional audio .partNN files, then the final audio artifact.

        audio_bitrate_kbps: optional target bitrate for lossy formats (mp3/opus/ogg).
        WAV/FLAC/AIFF/CAF ignore it (lossless / PCM).

        Returns (final_path, list_of_part_paths).
        """
        def _check_export_cancelled():
            if cancel_event is not None and cancel_event.is_set():
                raise RuntimeError("CANCELLED: Audio export cancelled; any completed .part files remain recoverable.")
        _check_export_cancelled()
        bit_depth = 24 if int(bit_depth or 16) >= 24 else 16
        pcm_dtype = np.int32 if bit_depth == 24 else np.int16
        pcm = np.asarray(pcm_int16, dtype=pcm_dtype).reshape(-1)
        # HF27: refuse audio stitch/write when peak RAM would starve the session.
        try:
            from memory_guard import guard_or_raise, estimate_pcm_bytes
            guard_or_raise(
                estimate_pcm_bytes(int(pcm.shape[0]), channels=1, sample_width=4 if bit_depth == 24 else 2, copies=3),
                label="audio export write",
                cancel_event=cancel_event,
            )
        except RuntimeError:
            raise
        except Exception:
            pass
        n_parts = max(1, min(128, int(n_parts or 1)))
        dest_dir = os.path.dirname(os.path.abspath(file_path)) or self._exports_dir()
        try:
            os.makedirs(dest_dir, exist_ok=True)
        except Exception:
            pass
        stem = os.path.splitext(os.path.basename(file_path))[0]
        total = int(pcm.shape[0])
        if total < 1:
            raise RuntimeError("No audio samples to export.")

        part_paths = []
        if n_parts > 1:
            # Even split with remainder on the last part.
            base = total // n_parts
            rem = total % n_parts
            offset = 0
            for pi in range(n_parts):
                _check_export_cancelled()
                take = base + (1 if pi < rem else 0)
                take = max(1, take) if offset < total else 0
                chunk = pcm[offset:offset + take] if take else pcm[0:1]
                offset += take
                part_path = os.path.join(dest_dir, f"{stem}.part{pi:02d}.wav")
                _write_wav_with_provenance(
                    part_path,
                    sample_rate,
                    chunk,
                    provenance_bytes if pi == 0 else None,
                    bit_depth=bit_depth,
                )
                part_paths.append(part_path)
                if not worker_safe:
                    self._index_project_file(part_path, "audio_export_part")
                    if hasattr(self, "scope_status_label"):
                        self.scope_status_label.setText(
                            f"📊 Audio part {pi + 1}/{n_parts} → {os.path.basename(part_path)}"
                        )
                        QApplication.processEvents()
                if progress_callback is not None:
                    try: progress_callback(80 + int(8 * (pi + 1) / max(1, n_parts)), f"Audio export · wrote part {pi + 1}/{n_parts}")
                    except Exception: pass

        audio_format = str(audio_format or "wav").lower().lstrip(".")
        try:
            br = int(audio_bitrate_kbps) if audio_bitrate_kbps is not None else None
        except Exception:
            br = None
        if br is not None:
            br = max(32, min(512, br))

        # Default-on STITCH contract: final output is reconstructed from the
        # just-written part WAVs, proving the parts themselves are sufficient.
        _check_export_cancelled()
        stitch_pcm = pcm
        if progress_callback is not None:
            try: progress_callback(89, "Audio export · verifying/stitching parts")
            except Exception: pass
        if n_parts > 1 and bool(stitch_parts):
            chunks = []
            for pp in part_paths:
                _sr, _bits, _chunk_pcm = _read_wav_mono_pcm(pp)
                if _sr != int(sample_rate) or _bits != bit_depth:
                    raise RuntimeError(f"Incompatible audio part for stitch: {pp}")
                chunks.append(_chunk_pcm)
            stitch_pcm = np.concatenate(chunks).astype(pcm_dtype, copy=False) if chunks else pcm
            if stitch_pcm.shape[0] != pcm.shape[0] or not np.array_equal(stitch_pcm, pcm):
                raise RuntimeError("Audio .part stitch verification failed; final output was not written.")
        elif n_parts > 1 and not bool(stitch_parts):
            return file_path, part_paths

        if progress_callback is not None:
            try: progress_callback(92, f"Audio export · finalizing {audio_format.upper()}")
            except Exception: pass
        _check_export_cancelled()
        _candidate_ext = {"aiff": ".aiff"}.get(audio_format, "." + audio_format)
        candidate_path = os.path.join(
            dest_dir,
            f".{stem}.groovebox-tmp-{os.getpid()}-{getattr(self, '_audio_export_job_counter', getattr(self, 'export_counter', 0))}{_candidate_ext}",
        )
        try:
            if os.path.isfile(candidate_path): os.remove(candidate_path)
        except OSError:
            pass
        if audio_format == "mcc":
            # GROOVEBOX_R23R_MCC_MEDIA_CODEC_20261101: lossless MCC audio of the exact
            # final PCM (bit-exact round trip), provenance carried in the header.
            import mcc_media as _mm
            _prov = None
            try:
                _prov = json.loads(provenance_bytes.decode("utf-8")) if provenance_bytes else None
            except Exception:
                _prov = None
            _mm.encode_audio(candidate_path, np.asarray(stitch_pcm), int(sample_rate),
                             extra={"bit_depth": int(bit_depth), "provenance": _prov})
            os.replace(candidate_path, file_path)
        elif audio_format == "wav":
            # OFF_UI_20261106: the WAV write can be large; keep it off the UI thread.
            self._run_off_gui(lambda: _write_wav_with_provenance(
                candidate_path, sample_rate, stitch_pcm, provenance_bytes, bit_depth=bit_depth))
            try:
                _check_export_cancelled()
            except Exception:
                try:
                    if os.path.isfile(candidate_path): os.remove(candidate_path)
                except OSError: pass
                raise
            os.replace(candidate_path, file_path)
        else:
            ffmpeg = self._resolve_ffmpeg_binary()
            if not ffmpeg:
                raise RuntimeError(f"FFmpeg is required for {audio_format.upper()} audio export.")
            tmp = os.path.join(
                dest_dir, f".groovebox_audio_tmp_{os.getpid()}_{getattr(self, 'export_counter', 0)}.wav"
            )
            _write_wav_with_provenance(tmp, sample_rate, stitch_pcm, bit_depth=bit_depth)
            # Bitrate-aware codec args for lossy formats; lossless stay fixed.
            if audio_format == "mp3":
                if br is not None:
                    codec_args = ["-c:a", "libmp3lame", "-b:a", f"{br}k"]
                else:
                    codec_args = ["-c:a", "libmp3lame", "-q:a", "2"]
            elif audio_format == "opus":
                codec_args = ["-c:a", "libopus", "-b:a", f"{br or 192}k"]
            elif audio_format == "ogg":
                # libvorbis prefers quality scale; approximate from bitrate when set.
                if br is not None:
                    # ~64kbps→q2 … ~320kbps→q9
                    q = max(0, min(10, int(round((br - 64) / 28.0))))
                    codec_args = ["-c:a", "libvorbis", "-q:a", str(q)]
                else:
                    codec_args = ["-c:a", "libvorbis", "-q:a", "6"]
            else:
                codec_args = {
                    "flac": ["-c:a", "flac"],
                    "aiff": ["-c:a", "pcm_s24be" if bit_depth == 24 else "pcm_s16be"],
                    "caf": ["-c:a", "pcm_s24le" if bit_depth == 24 else "pcm_s16le"],
                }.get(audio_format, ["-c:a", "flac"])
            meta = []
            if provenance_bytes:
                try:
                    meta = ["-metadata", f"comment={provenance_bytes.decode('utf-8')}"]
                except Exception:
                    meta = []
            proc = subprocess.Popen(
                [ffmpeg, "-y", "-hide_banner", "-loglevel", "error", "-i", tmp, *codec_args, *meta, candidate_path],
                stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
            )
            started = time.monotonic()
            cancelled = False
            while proc.poll() is None:
                if cancel_event is not None and cancel_event.is_set():
                    cancelled = True
                    try: proc.terminate()
                    except Exception: pass
                    try: proc.wait(timeout=2.0)
                    except Exception:
                        try: proc.kill()
                        except Exception: pass
                    break
                if time.monotonic() - started > 180.0:
                    try: proc.terminate()
                    except Exception: pass
                    try: proc.wait(timeout=2.0)
                    except Exception:
                        try: proc.kill()
                        except Exception: pass
                    break
                time.sleep(0.05)
            try:
                stdout_text, stderr_text = proc.communicate(timeout=2.0)
            except Exception:
                stdout_text, stderr_text = "", ""
            try:
                os.remove(tmp)
            except OSError:
                pass
            if cancelled:
                try:
                    if os.path.isfile(candidate_path): os.remove(candidate_path)
                except OSError:
                    pass
                raise RuntimeError("CANCELLED: Audio export cancelled during encoding; completed .part files remain recoverable.")
            if proc.returncode != 0:
                try:
                    if os.path.isfile(candidate_path): os.remove(candidate_path)
                except OSError:
                    pass
                raise RuntimeError(stderr_text or f"FFmpeg failed for {audio_format.upper()}")
            # ENCODED_AUDIO_INTEGRITY_20260913: for a non-silent rendered
            # master, verify the final lossy/lossless encoded artifact did not
            # collapse to silence or suffer gross level loss.  This is a read-
            # only check; it never normalizes or rewrites the result.
            try:
                _expected_peak = (
                    float(expected_float_peak)
                    if expected_float_peak is not None
                    else normalized_pcm_peak(stitch_pcm, bit_depth)
                )
                _ok_level, _level_note = verify_encoded_level(
                    ffmpeg, candidate_path, _expected_peak
                )
                print(f"[Export] {_level_note}")
                if not _ok_level:
                    raise RuntimeError(
                        f"{audio_format.upper()} audio integrity check failed: {_level_note}"
                    )
            except RuntimeError:
                try:
                    if os.path.isfile(candidate_path): os.remove(candidate_path)
                except OSError: pass
                raise
            except Exception as _verify_exc:
                print(f"[Export] encoded-level verification unavailable: {_verify_exc}")
        try:
            _check_export_cancelled()
        except Exception:
            try:
                if os.path.isfile(candidate_path): os.remove(candidate_path)
            except OSError: pass
            raise
        if audio_format != "wav":
            os.replace(candidate_path, file_path)
        if not worker_safe:
            self._index_project_file(file_path, "audio_export")
        if progress_callback is not None:
            try: progress_callback(97, "Audio export · artifact verified")
            except Exception: pass
        return file_path, part_paths

    def _on_audio_export_progress(self, token, value, message):
        if int(token) != int(getattr(self, "_audio_export_active_token", -1)):
            return
        self._set_work_progress("Audio export", value, message)
        dialog = getattr(self, "_audio_export_progress_dialog", None)
        if dialog is not None:
            try:
                dialog.setLabelText(str(message))
                dialog.setValue(max(0, min(100, int(value))))
            except Exception: pass
        label = getattr(self, "scope_status_label", None)
        if label is not None:
            try: label.setText(f"📊 {message}")
            except Exception: pass

    def _on_audio_export_finished(self, token, result):
        try:
            path = (result or {}).get("path") or (result or {}).get("output")
            if path:
                self._play_export_when_done(path, "audio")
        except Exception:
            pass
        if int(token) != int(getattr(self, "_audio_export_active_token", -1)):
            return
        self._audio_export_active = False
        dialog = getattr(self, "_audio_export_progress_dialog", None)
        self._audio_export_progress_dialog = None
        if dialog is not None:
            try: dialog.close()
            except Exception: pass
        self._audio_export_cancel_event = None
        try:
            file_path = str(result.get("file_path") or "")
            part_paths = list(result.get("part_paths") or [])
            for part_path in part_paths:
                self._index_project_file(part_path, "audio_export_part")
            if bool(result.get("final_written", True)) and file_path and os.path.isfile(file_path):
                self._index_project_file(file_path, "audio_export")
            preview = np.asarray(result.get("preview", []), dtype=np.float32)
            if isinstance(getattr(self, "visual_oscilloscope", None), VisualOscilloscope) and preview.size:
                self.visual_oscilloscope.update_waveform(preview)
            self.export_counter += 1
            if float(result.get("peak", 0.0) or 0.0) == 0.0:
                print("[Export] Warning: rendered master is exactly silent (peak=0).")
            clip_report = result.get("clip_report") or {}
            if isinstance(clip_report, dict):
                self._clipgain_report = dict(clip_report)
                self._eqr_z_rel = float(clip_report.get("density_after", 0.0) or 0.0)
                peak = float(clip_report.get("peak", 0.0) or 0.0)
                self._eqr_peak_db = (20.0 * math.log10(peak)) if peak > 0.0 else -math.inf
                try:
                    status_widget = getattr(self, "lbl_clip_gain_status", None)
                    if status_widget is not None:
                        status_widget.setVisible(True)
                        status_widget.setText(
                            f"HARDCLIP drive {float(clip_report.get('drive', 1.0)):.2f} · "
                            f"vol {float(clip_report.get('vol', 0.5))*100:.0f}% · "
                            f"clip dens {float(clip_report.get('density_before', 0.0))*100:.2f}%→"
                            f"{float(clip_report.get('density_after', 0.0))*100:.2f}%"
                        )
                except Exception:
                    pass
            n_parts = len(part_paths)
            stitch_parts = bool(result.get("stitch_parts", True))
            if n_parts > 1 and not stitch_parts:
                msg = f"📊 Export parts complete · {n_parts} files · stitching OFF"
            else:
                msg = f"📊 Export complete → {os.path.basename(file_path)}"
            label = getattr(self, "scope_status_label", None)
            if label is not None:
                label.setText(msg)
            self._set_work_progress("Audio export", 100, msg)
        except Exception as exc:
            self._on_audio_export_failed(token, f"Export finished but UI finalization failed: {exc}")

    def _on_audio_export_failed(self, token, message):
        if int(token) != int(getattr(self, "_audio_export_active_token", -1)):
            return
        self._audio_export_active = False
        dialog = getattr(self, "_audio_export_progress_dialog", None)
        self._audio_export_progress_dialog = None
        if dialog is not None:
            try: dialog.close()
            except Exception: pass
        self._audio_export_cancel_event = None
        cancelled = str(message).startswith("CANCELLED:")
        clean_message = str(message).split(":", 1)[1].strip() if cancelled else str(message)
        print(f"[System] {'Export cancelled' if cancelled else 'Export error'}: {clean_message}")
        label = getattr(self, "scope_status_label", None)
        if label is not None:
            try: label.setText(f"📊 {'Export cancelled' if cancelled else 'Export error'}: {clean_message}")
            except Exception: pass
        if not cancelled:
            QMessageBox.critical(self, "Export Error", clean_message)

    def _cancel_audio_export(self, token):
        if int(token) != int(getattr(self, "_audio_export_active_token", -1)) or not getattr(self, "_audio_export_active", False):
            return
        cancel_event = getattr(self, "_audio_export_cancel_event", None)
        if cancel_event is not None:
            cancel_event.set()
        dialog = getattr(self, "_audio_export_progress_dialog", None)
        if dialog is not None:
            try:
                dialog.setLabelText("Cancelling export safely… completed .part files will be retained")
                dialog.setCancelButton(None)
            except Exception: pass
        label = getattr(self, "scope_status_label", None)
        if label is not None:
            try: label.setText("📊 Cancelling export safely…")
            except Exception: pass

    def _export_render_buffer(self, purpose, sample_rate, max_rows=None, force_worker=None):
        """EXPORT_WORKER_20261102: the shared mixdown buffer for an export.

        With "Render exports in a separate process" on, the canonical project document is packed (the same
        one Save writes) and rendered by export_worker.py in its own process while this window keeps
        running (the wait pumps the Qt event loop, so scrolling, editing and playing stay smooth).
        Any worker failure falls back to the ordinary in-window render, so an export never fails because
        of the worker.
        """
        # EXPORT_OFF_UI_20261107: every export uses the worker. The window
        # never waits on a render. The Compatibility flag is now a hint only.
        use = True if force_worker is None else bool(force_worker)
        if getattr(self, "_render_queue_running", False):
            use = True
        if use:
            try:
                return self._render_mixdown_in_worker(purpose, sample_rate, max_rows)
            except Exception as exc:
                print(f"[Export worker] falling back to the in-window render: {exc}")
                try: self._export_log(f"Worker render failed ({exc}); rendering in this window instead.")
                except Exception: pass
        # EXPORT_SNAPSHOT_20261102: the render reads bpm / rows / lengths / effect amounts from a settings
        # snapshot that only Play used to take, so an export without a prior Play used stale or default values.
        # Take a fresh one here (main thread) so every in-window export renders what the controls show now.
        try:
            self._snapshot_render_inputs()
        except Exception:
            pass
        return self._get_shared_mixdown_buffer(max_rows=max_rows, purpose=purpose)

    def _export_log(self, text):
        log = self.__dict__.setdefault("_export_log_lines", [])
        log.append(f"{time.strftime('%H:%M:%S')}  {text}")
        del log[:-200]
        win = getattr(self, "_export_window", None)
        if win is not None:
            try: win.refresh_log()
            except Exception: pass

    def _render_mixdown_in_worker(self, purpose, sample_rate, max_rows=None):
        # R31: the old "start and return (None, 0)" path deleted the job folder before the
        # worker could read it and handed callers an empty buffer. Audio exports now go through
        # ExportScheduler (whole job in the worker). Synchronous callers get the in-window render.
        raise RuntimeError("synchronous worker render retired; use ExportScheduler")
        import json as _json, tempfile as _tf, shutil as _sh
        from PyQt6.QtCore import QProcess, QEventLoop
        if getattr(self, "_export_worker_busy", False):
            raise RuntimeError("a worker render is already running")
        here = os.path.dirname(os.path.abspath(__file__))
        tmp = _tf.mkdtemp(prefix="groovebox_export_")
        self._export_worker_busy = True
        try:
            proj = os.path.join(tmp, "project.MCC")
            self._atomic_write_document(proj, self._project_snapshot())
            job = {"project": proj, "sample_rate": int(sample_rate or 0), "out_npy": os.path.join(tmp, "master.npy"),
                   "out_meta": os.path.join(tmp, "master.json"), "kind": "audio", "purpose": str(purpose),
                   "max_rows": (int(max_rows) if max_rows else None)}
            jpath = os.path.join(tmp, "job.json")
            with open(jpath, "w", encoding="utf-8") as f:
                _json.dump(job, f)
            proc = QProcess(self)
            proc.setProcessChannelMode(QProcess.ProcessChannelMode.MergedChannels)
            loop = QEventLoop()
            state = {"fail": ""}

            def _on_out():
                for line in bytes(proc.readAllStandardOutput()).decode("utf-8", "replace").splitlines():
                    if line.startswith("PROGRESS "):
                        parts = line.split(" ", 2)
                        try: self._set_work_progress(purpose, int(parts[1]), "worker · " + (parts[2] if len(parts) > 2 else ""))
                        except Exception: pass
                    elif line.startswith("FAIL "):
                        state["fail"] = line[5:]
            proc.readyReadStandardOutput.connect(_on_out)
            # NO_FREEZE_20261107: do not loop.exec(). The window stays live.
            # The result is posted back when the process finishes.
            def _done(*_a):
                try:
                    if proc.exitCode() == 0 and not state["fail"] and os.path.isfile(job["out_npy"]):
                        meta = _json.load(open(job["out_meta"], "r", encoding="utf-8"))
                        buf = np.load(job["out_npy"])
                        self._export_log(f"{purpose}: worker finished ({buf.shape[0]} frames).")
                        if hasattr(self, "scope_status_label"):
                            self.scope_status_label.setText(f"{purpose} done")
                    else:
                        self._export_log(f"{purpose}: worker failed")
                except Exception:
                    pass
                finally:
                    self._export_worker_busy = False
                    self._export_cancel_worker = None
                    _sh.rmtree(tmp, ignore_errors=True)
            proc.finished.connect(_done)
            proc.errorOccurred.connect(_done)
            self._export_cancel_worker = proc.kill
            self._export_log(f"{purpose}: rendering in a separate process…")
            try:
                from groovebox_subprocess import helper_argv as _ha
                _argv = _ha("export_worker", jpath)
                proc.start(_argv[0], _argv[1:])
            except Exception:
                proc.start(sys.executable, [os.path.join(here, "export_worker.py"), jpath])
            return None, 0
        finally:
            self._export_worker_busy = False
            self._export_cancel_worker = None
            _sh.rmtree(tmp, ignore_errors=True)

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_PROCESS_RENDER_20261103 — render without freezing the window
    # ------------------------------------------------------------------
    def _render_in_process_async(self, purpose, on_done, max_rows=None):
        """Render the shared mixdown in the export-worker PROCESS and call
        on_done(buf, sr, error) on the GUI thread. No nested event loop and no Python
        thread competing with the window for the interpreter lock — the window stays
        fully responsive however long the render takes. The result is stored in the
        shared mixdown cache under the state key taken at start (if nothing changed
        meanwhile), so Play / Export reuse it."""
        import json as _json, tempfile as _tf, shutil as _sh
        from PyQt6.QtCore import QProcess
        if getattr(self, "_export_worker_busy", False):
            on_done(None, 0, "a worker render is already running"); return None
        try:
            key = self._shared_mixdown_key(max_rows)
        except Exception:
            key = None
        here = os.path.dirname(os.path.abspath(__file__))
        tmp = _tf.mkdtemp(prefix="groovebox_render_")
        self._export_worker_busy = True
        try:
            proj = os.path.join(tmp, "project.MCC")
            self._atomic_write_document(proj, self._project_snapshot())
            job = {"project": proj, "sample_rate": 0, "out_npy": os.path.join(tmp, "master.npy"),
                   "out_meta": os.path.join(tmp, "master.json"), "kind": "audio", "purpose": str(purpose),
                   "max_rows": (int(max_rows) if max_rows else None)}
            jpath = os.path.join(tmp, "job.json")
            with open(jpath, "w", encoding="utf-8") as f:
                _json.dump(job, f)
        except Exception as exc:
            self._export_worker_busy = False
            _sh.rmtree(tmp, ignore_errors=True)
            on_done(None, 0, f"could not pack the project: {exc}"); return None
        proc = QProcess(self)
        proc.setProcessChannelMode(QProcess.ProcessChannelMode.MergedChannels)
        state = {"fail": "", "done": False}

        def _on_out():
            for line in bytes(proc.readAllStandardOutput()).decode("utf-8", "replace").splitlines():
                if line.startswith("PROGRESS "):
                    parts = line.split(" ", 2)
                    try: self._set_work_progress(purpose, int(parts[1]), "render process · " + (parts[2] if len(parts) > 2 else ""))
                    except Exception: pass
                elif line.startswith("FAIL "):
                    state["fail"] = line[5:]

        def _finish(*_a):
            if state["done"]:
                return
            state["done"] = True
            self._export_worker_busy = False
            if getattr(self, "_render_process", None) is proc:
                self._render_process = None
            buf, sr, err = None, 0, ""
            try:
                if proc.exitCode() != 0 or state["fail"] or not os.path.isfile(job["out_npy"]):
                    err = state["fail"] or f"render process exit {proc.exitCode()}"
                else:
                    meta = _json.load(open(job["out_meta"], "r", encoding="utf-8"))
                    buf = np.load(job["out_npy"]); sr = int(meta["sample_rate"])
                    try:
                        if key is not None and key == self._shared_mixdown_key(max_rows):
                            with self._shared_mixdown_lock:
                                self._shared_mixdown_cache = {key: (buf, int(sr), time.monotonic())}
                    except Exception:
                        pass
            except Exception as exc:
                err = str(exc)
            finally:
                _sh.rmtree(tmp, ignore_errors=True)
                try: proc.deleteLater()
                except Exception: pass
            on_done(buf, sr, err)
        proc.readyReadStandardOutput.connect(_on_out)
        proc.finished.connect(_finish)
        def _on_error(*_a):
            try:
                stopped = proc.state() == QProcess.ProcessState.NotRunning
            except RuntimeError:
                # Quitting mid-render deletes the QProcess before this fires; an exception
                # escaping a slot makes PyQt6 abort the whole process.
                return
            if stopped:
                _finish()
        proc.errorOccurred.connect(_on_error)
        self._render_process = proc
        try:
            from groovebox_subprocess import helper_argv as _ha
            _argv = _ha("export_worker", jpath)
            proc.start(_argv[0], _argv[1:])
        except Exception:
            proc.start(sys.executable, [os.path.join(here, "export_worker.py"), jpath])
        return proc

    def _cancel_render_process(self):
        p = getattr(self, "_render_process", None)
        if p is not None:
            try:
                p.kill()
            except Exception:
                pass

    def _install_background_prerender(self):
        """Idle pre-render: once the project has been unchanged for ~8 s (and nothing is
        playing / exporting), render the mix in the worker process and keep it in RAM, so
        Play and Export start from a ready buffer. Off: Keyboard Assign checkbox or
        GROOVEBOX_BACKGROUND_PRERENDER=0."""
        if os.environ.get("GROOVEBOX_BACKGROUND_PRERENDER", "1") == "0":
            return
        t = getattr(self, "_bg_prerender_timer", None)
        if t is None:
            t = self._bg_prerender_timer = QTimer(self)
            t.setInterval(6000)
            t.timeout.connect(self._bg_prerender_tick)
        t.start()

    def _bg_prerender_tick(self):
        try:
            if not bool(getattr(self, "background_prerender", True)):
                return
            if (getattr(self, "is_playing", False) or getattr(self, "_export_worker_busy", False)
                    or getattr(self, "_render_queue_running", False) or getattr(self, "_bg_prerender_inflight", False)):
                return
            lp = getattr(self, "_live_player_window", None)
            if lp is not None and lp.is_active():
                return
            if not self.isVisible():          # parked project tabs never pre-render
                return
            # GROOVEBOX_R23R_SMOOTH_IDLE_20261103: never hash the project while you are editing / dragging
            _deb = getattr(self, "_canonical_authoring_debounce_timer", None)
            if (_deb is not None and _deb.isActive()) or QApplication.mouseButtons() != Qt.MouseButton.NoButton:
                self._bg_stable = 0
                return
            if time.monotonic() - float(getattr(self, "_last_live_source_change", 0.0) or 0.0) < 5.0:
                return
            rows = self._live_preview_max_rows()
            key = self._shared_mixdown_key(rows)
            with self._shared_mixdown_lock:
                cached = key in (self._shared_mixdown_cache or {})
            if cached:
                self._bg_prev_key = key; return
            if getattr(self, "_bg_prev_key", None) != key:      # still changing: wait for a stable state
                self._bg_prev_key = key; self._bg_stable = 0; return
            self._bg_stable = int(getattr(self, "_bg_stable", 0)) + 1
            if self._bg_stable < 2:
                return
            self._bg_prerender_inflight = True

            def done(buf, sr, err):
                self._bg_prerender_inflight = False
                if err:
                    print(f"[Background render] {err}")
            self._render_in_process_async("Background prepare", done, max_rows=rows)
        except Exception as exc:
            self._bg_prerender_inflight = False
            print(f"[Background render] skipped: {exc}")

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_MEMORY_MANAGER_20261103 — RAM budget, SSD swap, safety autosave
    # ------------------------------------------------------------------
    def _install_memory_manager(self):
        import memory_manager as _mm
        M = _mm.manager()
        me = self

        def _nb(a):
            try:
                return 0 if a is None or _mm.is_swapped(a) else int(getattr(a, "nbytes", 0) or 0)
            except Exception:
                return 0

        def key_size():
            kb = getattr(me, "_key_bank_obj", None)
            return kb.ram_bytes() if kb is not None else 0

        def key_spill(_need):
            kb = getattr(me, "_key_bank_obj", None)
            if kb is None:
                return 0
            n = kb.ram_bytes()
            with kb.lock:
                kb.cache.clear()          # re-rendered on the next press (bindings are kept)
            return n

        def memo_size():
            import multidim_synth as _md
            return int(_md.FI_STATS.get("memo_bytes", 0))

        def memo_spill(_need):
            import multidim_synth as _md
            n = int(_md.FI_STATS.get("memo_bytes", 0)); _md.memo_clear(); return n

        def mix_size():
            with me._shared_mixdown_lock:
                return sum(_nb(v[0]) for v in (me._shared_mixdown_cache or {}).values())

        def mix_spill(_need):
            """The track's rendered mix moves to the SSD swap as a memory-map: it still plays (only
            the part being played is paged into RAM)."""
            freed = 0
            sw = M.swap_store()
            with me._shared_mixdown_lock:
                for k, v in list((me._shared_mixdown_cache or {}).items()):
                    if _nb(v[0]) <= 0:
                        continue
                    mmv = sw.put(f"{id(me)}:mix:{_stable_hash(repr(k))}", v[0])
                    if mmv is not None:
                        freed += int(v[0].nbytes)
                        me._shared_mixdown_cache[k] = (mmv, v[1], v[2])
            return freed

        def play_size():
            return 0 if getattr(me, "is_playing", False) else _nb(getattr(me, "play_buffer", None))

        def play_spill(_need):
            if getattr(me, "is_playing", False):
                return 0
            buf = getattr(me, "play_buffer", None)
            n = _nb(buf)
            if n <= 0:
                return 0
            mmv = M.swap_store().put(f"{id(me)}:play", buf)
            if mmv is None:
                return 0
            with me.play_lock:
                me.play_buffer = mmv
            return n

        def pool_size():
            opt = getattr(me, "_scode_optimizer", None)
            try:
                return int(opt.pool_stats().get("bytes", 0)) if opt is not None and hasattr(opt, "pool_stats") else 0
            except Exception:
                return 0

        def pool_spill(_need):
            opt = getattr(me, "_scode_optimizer", None)
            if opt is None or getattr(me, "_render_busy", False):
                return 0
            n = pool_size()
            try:
                with opt._pool_lock:
                    opt._pool.clear()
            except Exception:
                return 0
            return n

        M.register_spill(self, "key_cache", 10, key_spill, key_size)
        M.register_spill(self, "multidim_memo", 12, memo_spill, memo_size)
        M.register_spill(self, "shared_mixdown", 20, mix_spill, mix_size)
        M.register_spill(self, "play_buffer", 40, play_spill, play_size)
        M.register_spill(self, "scode_pool", 50, pool_spill, pool_size)
        t = getattr(self, "_memory_timer", None)
        if t is None:
            t = self._memory_timer = QTimer(self)
            t.setInterval(3000)
            t.timeout.connect(self._memory_tick)
        t.start()

    def _memory_tick(self):
        import memory_manager as _mm
        try:
            import project_tabs as _pt
            act = _pt.tabs().active
            if act is not None and act is not self:
                return                 # one window (the active project) drives the manager
        except Exception:
            act = self
        M = _mm.manager()
        before = {}
        for _p, _n, o, _sp, size in list(M._spills):
            try:
                before[id(o)] = before.get(id(o), 0) + int(size() or 0)
            except Exception:
                pass
        if M.pressure() <= 0:
            return
        self._memory_safety_autosave()        # the project is safe on disk before any buffer moves
        freed = M.tick(active_owner=self)
        if freed > 0:
            self._memory_note_parked(freed, pressure=True)

    def _memory_safety_autosave(self):
        """A recovery copy (metadata/autosave.MCC) written whatever the Autosave box says — never
        over the project file itself."""
        try:
            import groovebox_paths
            path = os.path.join(groovebox_paths.metadata_dir(getattr(self, "_current_project_path", None)), "autosave.MCC")
            self._atomic_write_document(path, self._project_snapshot())
            self._last_safety_autosave = path
            return path
        except Exception as exc:
            print(f"[Memory] safety autosave failed: {exc}")
            return ""

    def _set_status_message(self, message, persist=True):
        """Push a message into the editable status history and update the scope label."""
        try:
            msg = str(message or "").strip()
            if not msg:
                return
            if hasattr(self, "status_history") and self.status_history is not None:
                # Avoid duplicate consecutive entries
                if self.status_history.count() == 0 or self.status_history.itemText(0) != msg:
                    self.status_history.insertItem(0, msg)
                self.status_history.setCurrentIndex(0)
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(msg[:120])
        except Exception:
            pass

    def _memory_note_parked(self, freed, pressure=False):
        """The prompt: what moved to the SSD swap, and that the project was autosaved first."""
        import memory_manager as _mm
        now = time.monotonic()
        if now - float(getattr(self, "_memory_note_at", 0.0) or 0.0) < 60.0:
            return
        self._memory_note_at = now
        where = getattr(self, "_last_safety_autosave", "") or "the project's metadata folder"
        why = ("Memory was getting low" if pressure else "You switched to another project tab")
        msg = (f"{why}, so {_mm.fmt_bytes(freed)} of this project's buffers moved to the SSD swap.\n\n"
               f"The project was autosaved first ({where}). Nothing was lost: the buffers are read back from "
               "the SSD when they are needed.")
        try:
            self._set_status_message(msg)
        except Exception:
            pass

    # ------------------------------------------------------------------
    # GROOVEBOX_R23R_HARDWARE_FOLLOW_20261103 — the UI follows the hardware, no device prompts
    # ------------------------------------------------------------------
    def _install_hardware_follow(self):
        t = getattr(self, "_hw_follow_timer", None)
        if t is None:
            t = self._hw_follow_timer = QTimer(self)
            t.setInterval(5000)
            t.timeout.connect(self._hw_follow_tick)
        t.start()
        # POWER_PROFILE_20261106: lightweight battery/thermal refresh; never blocks switchover.
        try:
            self._refresh_power_profile()
        except Exception:
            pass
        pt = getattr(self, "_power_timer", None)
        if pt is None:
            pt = self._power_timer = QTimer(self)
            pt.setInterval(15000)
            pt.timeout.connect(self._refresh_power_profile)
        pt.start()

    def _hardware_pass(self):
        """Measure a tiny frame and lock preview FPS / export scale to what this machine holds."""
        import time as _t
        t0 = _t.perf_counter()
        try:
            # Cheap stand-in: a small numpy op timed as a frame proxy
            a = np.random.rand(64, 64, 3).astype(np.float32)
            _ = (a * 0.5 + 0.1).sum()
        except Exception:
            pass
        dt = _t.perf_counter() - t0
        # Map measured time to a safe preview FPS and export scale
        if dt > 0.04:
            fps, scale = 12, 0.6
        elif dt > 0.015:
            fps, scale = 24, 0.85
        else:
            fps, scale = 30, 1.0
        self._hw_preview_fps = fps
        self._hw_export_scale = scale
        try:
            viewer = getattr(self, "video_synth_viewer", None)
            if viewer is not None and hasattr(viewer, "_preview_min_interval"):
                viewer._preview_min_interval = 1.0 / max(8, fps)
        except Exception:
            pass
        return {"fps": fps, "export_scale": scale, "frame_ms": dt * 1000.0}

    def _refresh_power_profile(self):
        """Update the adaptive profile and a short status hint. Never raises."""
        try:
            import power_profile as _pp
            prof = _pp.compute_profile()
            self._power_profile = prof
            try:
                hw = self._hardware_pass()
                prof["visual_fps"] = hw["fps"]
                prof["export_scale"] = hw["export_scale"]
            except Exception:
                pass
            # AUTO_PROFILE_20261106: apply preview FPS from the detected tier.
            try:
                fps = int(prof.get("visual_fps", 24) or 24)
                viewer = getattr(self, "video_synth_viewer", None)
                if viewer is not None and hasattr(viewer, "_preview_min_interval"):
                    viewer._preview_min_interval = 1.0 / max(8, fps)
            except Exception:
                pass
            hint = prof.get("label") or ""
            if hint and hasattr(self, "scope_status_label") and self.scope_status_label is not None:
                # Only annotate when the label is idle-ish, so we don't clobber real status.
                cur = self.scope_status_label.text() or ""
                if not cur or cur.startswith("Ready") or "threads" in cur or cur.startswith("⚡"):
                    self.scope_status_label.setText("⚡ " + hint)
        except Exception:
            pass

    def _hw_follow_tick(self):
        if getattr(self, "_hw_follow_busy", False) or not self.isVisible():
            return
        self._hw_follow_busy = True

        def work():
            names = set()
            try:
                import shutil as _sh, subprocess as _sp
                if _sh.which("pactl"):
                    out = _sp.run(["pactl", "list", "short", "sinks"], capture_output=True, text=True, timeout=2).stdout
                    names |= {("pulse:" + (l.split("\t") if "\t" in l else l.split())[1]) for l in out.splitlines()
                              if len(l.split()) >= 2 and "groovebox_all_outputs" not in l}
            except Exception:
                pass
            try:
                from audio_os_backend import _device_snapshot
                names |= {str(d.get("name")) for d in (_device_snapshot() or []) if int(d.get("max_output_channels", 0) or 0) > 0}
            except Exception:
                pass
            prev = getattr(self, "_hw_follow_names", None)
            added = sorted(names - prev) if prev is not None else []
            removed = sorted(prev - names) if prev is not None else []
            self._hw_follow_names = names
            if added or removed:
                try:
                    import media_output_router as _mor
                    _mor.prewarm_all_outputs()        # rebuild the All-outputs route off the GUI thread
                    status = _mor.all_outputs_status()
                    if hasattr(self, "scope_status_label") and status:
                        self.scope_status_label.setText("🔊 " + status)
                except Exception:
                    pass
            self._hw_follow_result = (added, removed)
        self._hw_follow_result = None
        threading.Thread(target=work, name="hardware-follow", daemon=True).start()
        QTimer.singleShot(300, self._hw_follow_done)

    def _hw_follow_done(self):
        res = getattr(self, "_hw_follow_result", None)
        if res is None:
            if getattr(self, "_hw_follow_busy", False):
                QTimer.singleShot(300, self._hw_follow_done)
            return
        self._hw_follow_busy = False
        added, removed = res
        if not added and not removed:
            return
        try:
            self._close_audition_stream()             # the next note opens on the new route
        except Exception:
            pass
        bits = []
        if added:
            bits.append("added " + ", ".join(n.replace("pulse:", "") for n in added[:3]))
        if removed:
            bits.append("removed " + ", ".join(n.replace("pulse:", "") for n in removed[:3]))
        try:
            self.scope_status_label.setText("🔌 Outputs changed — " + "; ".join(bits) + " · audio follows automatically")
        except Exception:
            pass
        try:
            w = getattr(self, "_hardware_master_dialog", None)
            if w is not None and w.isVisible():
                w._fill_devices()
        except Exception:
            pass

    def verify_worker_parity(self):
        """Render a short slice both ways and compare. Returns (identical, text)."""
        a, sra = self._get_shared_mixdown_buffer(max_rows=1, purpose="Parity check", force=True)
        b, srb = self._render_mixdown_in_worker("Parity check", 0, max_rows=1)
        a = np.asarray(a, dtype=np.float32)
        same = a.shape == b.shape and sra == srb and bool(np.array_equal(a, b))
        diff = float(np.max(np.abs(a - b))) if a.shape == b.shape and a.size else None
        return same, ("Identical: the worker renders exactly what this window renders." if same else
                      f"DIFFERENT (shape {a.shape} vs {b.shape}, max diff {diff}). Keep the worker off.")

    def export_window_dialog(self, tab=None):
        """GROOVEBOX_R23R_EXPORT_MERGE_20261103: ONE 📦 Export window — This project (every format,
        separate-process worker, log) · Queue · Batch (many projects, parallel export workers)."""
        import export_window as _ew
        hub = getattr(self, "_export_hub", None)
        if hub is None:
            from PyQt6.QtWidgets import QTabWidget as _QTW
            hub = QDialog(None, Qt.WindowType.Window)
            hub.setWindowTitle("📦 Export")
            hub.resize(780, 720)
            lay = QVBoxLayout(hub); lay.setContentsMargins(4, 4, 4, 4)
            tabs = _QTW(); lay.addWidget(tabs)
            win = self._export_window = _ew.ExportWindow(self)
            win.setWindowFlags(Qt.WindowType.Widget)
            tabs.addTab(win, "This project")
            q = QWidget(); ql = QVBoxLayout(q)
            ql.addWidget(QLabel("<b>Render queue</b> — several exports of this project, one after another; "
                                "the audio renders once and every format reuses it."))
            bq = QPushButton("🗂 Open render queue…"); bq.setMinimumHeight(40); bq.clicked.connect(self.render_queue_dialog)
            ql.addWidget(bq); ql.addStretch(1)
            tabs.addTab(q, "Queue")
            perf = self._perf_backend() if hasattr(self, "_perf_backend") else None
            if perf is not None and hasattr(perf, "_build_batch_tab"):
                tabs.addTab(perf._scroll_page(perf._build_batch_tab()), "Batch (many projects)")
            hub._tabs = tabs
            self._export_hub = hub
        try:
            self._export_window.refresh_log()
        except Exception:
            pass
        if tab == "batch":
            hub._tabs.setCurrentIndex(hub._tabs.count() - 1)
        elif tab == "project":
            hub._tabs.setCurrentIndex(0)
        hub.show(); hub.raise_(); hub.activateWindow()
        return hub

