    def export_mixdown_dialog(self, audio_format="wav"):
        """Re-entrancy guard around the interactive export setup.

        The non-modal dialog compatibility layer runs a nested Qt event loop.
        That allows a second click to re-enter this method while the first
        Save/Options dialog is still open. Only the setup interaction is
        serialized; once a job is submitted, later deliberate exports are
        allowed and remain independently queued by the export scheduler.
        """
        if bool(getattr(self, "_audio_export_dialog_active", False)):
            try:
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText("Audio export setup is already open — finish or cancel that dialog first.")
            except Exception:
                pass
            return None
        self._audio_export_dialog_active = True
        try:
            return self._export_mixdown_dialog_impl(audio_format)
        finally:
            self._audio_export_dialog_active = False

    def _export_mixdown_dialog_impl(self, audio_format="wav"):
        if not self._prepare_export_project('audio export'):
            return
        # EXPORT_SCHEDULER_R31: no "already running" refusal; every press queues its own frozen state.
        self._ensure_hardware_use("audio-export")

        """Export the same canonical master mix in WAV/FLAC/OGG/AIFF/MP3/OPUS/CAF.

        Pathway (all formats share this — no alternate soft bus):
          1. ``_render_mixdown_buffer`` — composition identity (sum of voices)
          2. optional bake-DJ write (live parametric, not a normalizer)
          3. ``_master_hardclip`` — Master Volume × Clip/Gain factors → hard clip
             (NO peak normalizer, NO limiter, NO EQ/filter on this final bus)
          4. user-selected 16/24-bit PCM quantization for lossless container write

        72% default Master Volume is the initial level on play/preview;
        export uses the same hardclip path so offline files match what you heard.
        Video exports that embed this mixdown inherit the same hardclip stage.
        """
        audio_format = str(audio_format or "wav").lower().lstrip(".")
        if audio_format not in {"wav", "flac", "ogg", "aiff", "mp3", "opus", "caf", "mcc"}:
            audio_format = "wav"
        filters = {
            "mcc": "MCC Lossless Audio (*.MCC)",
            "wav": "WAV Audio (*.wav)", "flac": "FLAC Audio (*.flac)",
            "ogg": "Ogg Vorbis Audio (*.ogg)", "aiff": "AIFF Audio (*.aiff *.aif)",
            "mp3": "MP3 Audio (*.mp3)", "opus": "Opus Audio (*.opus)",
            "caf": "Core Audio Format (*.caf)",
        }
        ext = ".aiff" if audio_format == "aiff" else (".MCC" if audio_format == "mcc" else "." + audio_format)
        try:
            default_filename = self._export_name("mixdown", ext, self._audio_exports_dir())
            # GROOVEBOX_UNIFIED_EXPORT_20261101: the unified Export dialog supplies path + options.
            _pre = self.__dict__.pop("_export_preset", None)
            if _pre and _pre.get("path"):
                file_path = str(_pre["path"])
            else:
                file_path, _ = QFileDialog.getSaveFileName(self, "Save Mixdown Audio", default_filename, filters[audio_format])
            if not file_path:
                return
            if not file_path.lower().endswith(ext.lower()):
                file_path += ext
            # Parts + optional bitrate (lossy formats only).
            opts_dlg = QDialog(self)
            opts_dlg.setWindowTitle(f"Audio Export — {audio_format.upper()}")
            opts_form = QFormLayout(opts_dlg)
            spin_parts = QSpinBox()
            spin_parts.setRange(1, 128)
            spin_parts.setValue(int(self._default_export_part_count()))
            spin_parts.setToolTip("Recoverable .part segments (1–128).")
            opts_form.addRow("Part Count (1–128)", spin_parts)
            chk_stitch = QCheckBox("Stitch .part files into final output")
            chk_stitch.setChecked(bool(getattr(self, "_last_stitch_parts", True)))
            chk_stitch.setToolTip("Default ON: the final artifact is reconstructed from the written .part files. OFF leaves the recoverable part files only.")
            opts_form.addRow(chk_stitch)
            lossy = audio_format in {"mp3", "opus", "ogg"}

            combo_quality = QComboBox()
            combo_quality.addItems([
                "Radio / Broadcast — 48 kHz / 24-bit",
                "Studio HQ — 96 kHz / 24-bit",
                "Ultra HQ — 128 kHz / 24-bit",
                "CD-compatible — 44.1 kHz / 16-bit",
                "Custom",
            ])
            opts_form.addRow("Quality preset", combo_quality)

            combo_sr = QComboBox()
            for _sr in (44100, 48000, 88200, 96000, 128000, 176400, 192000):
                combo_sr.addItem(f"{_sr / 1000.0:g} kHz", _sr)
            _last_sr = int(getattr(self, "_last_export_sample_rate", 48000) or 48000)
            _idx = combo_sr.findData(_last_sr)
            combo_sr.setCurrentIndex(_idx if _idx >= 0 else combo_sr.findData(48000))
            combo_sr.setToolTip("True render sample rate. 96/128 kHz are synthesized natively, not post-export upsampled.")
            opts_form.addRow("Render sample rate", combo_sr)

            combo_output_sr = QComboBox()
            combo_output_sr.addItem("Same as render", 0)
            for _sr in (44100, 48000, 88200, 96000):
                combo_output_sr.addItem(f"Output at {_sr / 1000.0:g} kHz", _sr)
            combo_output_sr.setCurrentIndex(0)
            combo_output_sr.setToolTip("Optional anti-aliased downsampling after rendering. Useful when rendering at 96/128/192 kHz but delivering a 44.1/48 kHz file.")
            opts_form.addRow("Output file sample rate", combo_output_sr)

            combo_bits = QComboBox()
            combo_bits.addItem("16-bit PCM", 16)
            combo_bits.addItem("24-bit PCM", 24)
            combo_bits.addItem("32-bit float (no quantization, WAV/CAF/AIFF/FLAC→WAV)", 32)
            _last_bits = int(getattr(self, "_last_export_bit_depth", 24) or 24)
            combo_bits.setCurrentIndex(2 if _last_bits >= 32 else (1 if _last_bits >= 24 else 0))
            combo_bits.setToolTip("Lossless WAV/AIFF/CAF carry this PCM depth; FLAC preserves the source precision. Lossy codecs encode from this render master.")
            opts_form.addRow("Render bit depth", combo_bits)
            # UNBOUNDED_OUTPUT_R31_6: optional removal of the final hard limit.
            chk_clip_bypass = QCheckBox("Bypass master hardclip (keep peaks above 0 dBFS — use with 32-bit float)")
            chk_clip_bypass.setChecked(bool(getattr(self, "_last_export_clip_bypass", False)))
            chk_clip_bypass.setToolTip("OFF (default): the canonical Master Volume × Clip/Gain → hard clip stage.\n"
                                       "ON: master volume only, no clip. Integer PCM / lossy formats still clip at\n"
                                       "full scale; 32-bit float WAV keeps every overshoot exactly.")
            opts_form.addRow(chk_clip_bypass)

            def _apply_quality_preset(_index=None):
                txt = combo_quality.currentText()
                preset = None
                if txt.startswith("Radio"):
                    preset = (48000, 24)
                elif txt.startswith("Studio"):
                    preset = (96000, 24)
                elif txt.startswith("Ultra"):
                    preset = (128000, 24)
                elif txt.startswith("CD-compatible"):
                    preset = (44100, 16)
                if preset:
                    si = combo_sr.findData(preset[0])
                    if si >= 0:
                        combo_sr.setCurrentIndex(si)
                    combo_bits.setCurrentIndex(1 if preset[1] == 24 else 0)
            combo_quality.currentIndexChanged.connect(_apply_quality_preset)
            _apply_quality_preset()
            spin_br = QSpinBox()
            spin_br.setRange(32, 512)
            spin_br.setSingleStep(16)
            try:
                spin_br.setValue(int(getattr(self, "_last_audio_bitrate_kbps", 192) or 192))
            except Exception:
                spin_br.setValue(192)
            spin_br.setSuffix(" kbps")
            spin_br.setToolTip(
                "Target audio bitrate for lossy formats (mp3 / opus / ogg). "
                "WAV / FLAC / AIFF / CAF ignore this (lossless or PCM)."
            )
            spin_br.setEnabled(lossy)
            opts_form.addRow("Bitrate", spin_br)
            if not lossy:
                opts_form.addRow(QLabel("Bitrate applies to MP3 / Opus / OGG only."))
            opts_form.addRow(QLabel(f"Final file: {os.path.basename(file_path)}"))
            opts_btns = QDialogButtonBox(
                QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel
            )
            opts_btns.accepted.connect(opts_dlg.accept)
            opts_btns.rejected.connect(opts_dlg.reject)
            opts_form.addRow(opts_btns)
            if _pre:
                spin_parts.setValue(int(_pre.get("parts", spin_parts.value())))
                chk_stitch.setChecked(bool(_pre.get("stitch", True)))
                _i = combo_sr.findData(int(_pre.get("render_sr", 48000)))
                if _i >= 0:
                    combo_sr.setCurrentIndex(_i)
                _o = int(_pre.get("output_sr", 0) or 0)
                _oi = combo_output_sr.findData(0 if _o in (0, int(combo_sr.currentData() or 0)) else _o)
                combo_output_sr.setCurrentIndex(_oi if _oi >= 0 else 0)
                _bd = int(_pre.get("bit_depth", 24))
                combo_bits.setCurrentIndex(2 if _bd >= 32 else (1 if _bd >= 24 else 0))
                if lossy:
                    spin_br.setValue(int(_pre.get("bitrate", spin_br.value())))
            elif opts_dlg.exec() != QDialog.DialogCode.Accepted:
                return
            n_parts = max(1, min(128, int(spin_parts.value())))
            export_sample_rate = int(combo_sr.currentData() or 48000)
            output_sample_rate = int(combo_output_sr.currentData() or 0) or export_sample_rate
            if output_sample_rate > export_sample_rate:
                QMessageBox.warning(self, "Output Sample Rate", "Output sample rate cannot exceed the render rate in this downsampling control. Choose a lower output rate or Same as render.")
                return
            export_bit_depth = int(combo_bits.currentData() or 24)
            clip_bypass = bool(chk_clip_bypass.isChecked())
            self._last_export_clip_bypass = clip_bypass
            if _pre and _pre.get("clip_bypass") is not None:
                clip_bypass = bool(_pre.get("clip_bypass"))
            self._last_export_sample_rate = export_sample_rate
            self._last_export_bit_depth = export_bit_depth
            stitch_parts = bool(chk_stitch.isChecked())
            self._last_stitch_parts = stitch_parts
            self._last_export_part_count = n_parts
            audio_bitrate_kbps = int(spin_br.value()) if lossy else None
            if audio_bitrate_kbps is not None:
                self._last_audio_bitrate_kbps = audio_bitrate_kbps
            if hasattr(self, 'scope_status_label'):
                _br_tag = f" @ {audio_bitrate_kbps}k" if audio_bitrate_kbps else ""
                self.scope_status_label.setText(
                    f"📊 Rendering canonical master mix → {audio_format.upper()}{_br_tag} · "
                    f"{export_sample_rate/1000:g} kHz render → {output_sample_rate/1000:g} kHz file / {export_bit_depth}-bit "
                    f"({n_parts} part{'s' if n_parts != 1 else ''})…"
                )
            # EXPORT_SCHEDULER_R31: freeze this project state + options and queue it. The render,
            # DJ bake, single master hardclip, encode and verify all run in a worker process.
            try:
                clip_ratio_snapshot = float(self.spin_clip_ratio.value()) if hasattr(self, "spin_clip_ratio") else 50.0
            except Exception:
                clip_ratio_snapshot = 50.0
            try:
                master_volume_snapshot = float(getattr(self, "master_volume", 0.72))
                if not math.isfinite(master_volume_snapshot):
                    master_volume_snapshot = 0.72
            except Exception:
                master_volume_snapshot = 0.72
            job = self._export_scheduler().submit_audio(str(file_path), {
                "audio_format": str(audio_format), "render_sample_rate": int(export_sample_rate),
                "output_sample_rate": int(output_sample_rate), "bit_depth": int(export_bit_depth),
                "n_parts": int(n_parts), "stitch_parts": bool(stitch_parts),
                "bitrate_kbps": (int(audio_bitrate_kbps) if audio_bitrate_kbps is not None else None),
                "clip_ratio_pct": float(clip_ratio_snapshot),
                "master_volume": max(0.0, min(1.0, master_volume_snapshot)),
                "clip_bypass": bool(clip_bypass),
            }, label="%s · %s" % (audio_format.upper(), os.path.basename(str(file_path))))
            n_pending = self._export_scheduler().pending_count()
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(
                    f"📊 Export #{job.id} queued ({n_pending} pending) · rendering in a separate process — keep working")
            if not getattr(self, "_render_queue_running", False):
                self.show_export_jobs()
        except Exception as e:
            self._audio_export_active = False
            print(f"[System] Export error: {e}")
            if hasattr(self, 'scope_status_label'):
                self.scope_status_label.setText(f"📊 Export error: {e}")
            QMessageBox.critical(self, "Export Error", str(e))

    # =====================================================================
    # VIDEO_EXPORT_FEATURE — 2.5D render + audio mux + optional source-video blend
    # Supports Video+Audio / Video-only in mp4|webm|avi with encoder auto-fallback.
    # =====================================================================
    def _resolve_ffmpeg_binary(self):
        """Return only the provisioned/bundled Groovebox-local FFmpeg."""
        return resolve_local_tool("ffmpeg", required=False)

    def _ffmpeg_encoder_args(self, ffmpeg_bin, container="mp4"):
        """Pick video/audio encoder args this ffmpeg build actually supports."""
        try:
            proc = subprocess.run(
                [ffmpeg_bin, "-hide_banner", "-encoders"],
                capture_output=True, text=True, timeout=12,
            )
            listing = (proc.stdout or "") + "\n" + (proc.stderr or "")
        except Exception:
            listing = ""

        def has(name):
            return (" " + name + " ") in (" " + listing.replace("\n", " ") + " ")

        container = (container or "mp4").lower().lstrip(".")
        vcodec, vargs = None, []

        # Container-aware preference
        if container == "webm":
            order = ["libvpx-vp9", "libvpx", "libx264", "mpeg4", "mjpeg"]
        elif container == "avi":
            order = ["mpeg4", "libxvid", "msmpeg4v2", "libx264", "mjpeg"]
        else:  # mp4 and default
            order = ["libx264", "libopenh264", "h264_mf", "libxvid", "mpeg4",
                     "libvpx-vp9", "libvpx", "mjpeg"]

        presets = {
            "libx264": ["-preset", "medium", "-crf", "18"],
            "libopenh264": ["-b:v", "2M"],
            "h264_mf": ["-b:v", "2M"],
            "libxvid": ["-qscale:v", "5"],
            "mpeg4": ["-qscale:v", "5"],
            "msmpeg4v2": ["-qscale:v", "5"],
            "libvpx-vp9": ["-b:v", "1.5M", "-row-mt", "1"],
            "libvpx": ["-b:v", "1.5M"],
            "mjpeg": ["-q:v", "5"],
        }
        for name in order:
            if has(name):
                vcodec, vargs = name, list(presets.get(name, ["-b:v", "2M"]))
                try:
                    import library_tuning as _lt   # Smooth level caps the encoder threads
                    vargs += _lt.ffmpeg_threads_args()
                except Exception:
                    pass
                break
        if vcodec is None:
            vcodec, vargs = "mpeg4", ["-qscale:v", "5"]

        # Audio
        if container == "webm":
            a_order = ["libopus", "libvorbis", "aac", "libmp3lame"]
        elif container == "avi":
            a_order = ["libmp3lame", "aac", "libvorbis"]
        else:
            a_order = ["aac", "libmp3lame", "libvorbis", "libopus"]
        acodec, aargs = None, []
        a_presets = {
            "aac": ["-b:a", "192k"],
            "libmp3lame": ["-b:a", "192k"],
            "libvorbis": ["-b:a", "160k"],
            "libopus": ["-b:a", "128k"],
        }
        for name in a_order:
            if has(name):
                acodec, aargs = name, list(a_presets.get(name, ["-b:a", "192k"]))
                break
        if acodec is None:
            acodec, aargs = "aac", ["-b:a", "192k"]

        print(f"[Video] ffmpeg={ffmpeg_bin} container={container} vcodec={vcodec} acodec={acodec}")
        return vcodec, vargs, acodec, aargs


    def _multidim_programmes_for_game(self, max_programmes=4):
        """GROOVEBOX_R23R_MULTIDIM_SCENE_20261103: the multidimensional programmes (params, seed, slot)
        a game rebuilds its world from — the game computes the exact state at its own time."""
        out = []
        try:
            names = list(getattr(self, "instrument_names_48", []) or [])
            mem = getattr(self, "instrument_sequencer_memory", {}) or {}
            sel = self.instrument_selector_dropdown.currentText() if hasattr(self, "instrument_selector_dropdown") else ""
            order = [sel] + [n for n in names if n != sel and any((mem.get(n) or {}).get("steps") or [])]
            for n in order[:max_programmes]:
                if not n:
                    continue
                slot = self._instance_slot(n)
                p, seed_int = self._md_params(n, slot)
                out.append({"params": {k: v for k, v in p.items() if not str(k).startswith("_")},
                            "seed": int(seed_int), "slot": int(slot), "instrument": n})
        except Exception:
            pass
        return out

    def _composition_meta_for_game(self):
        """Snapshot for game classification — same lattice as save/export.

        Global Player algo fingerprint is included so the video-game interpreter
        responds to Script/Domain/Wire/Params without ever mutating the seed.
        """
        gas = self._effective_global_algo_state()
        try:
            algo_fp = hashlib.sha256(
                json.dumps(gas, sort_keys=True, default=str).encode("utf-8")
            ).hexdigest()[:16]
        except Exception:
            algo_fp = "0" * 16
        try:
            # GROOVEBOX_R23R_SEED_ENGINE_INVARIANCE_20261031: the graph-scripts
            # digest captures AUTHORED scripting only. Stock per-voice workspace
            # scripts are deterministic (seed, voice) scaffolding whose roster
            # cardinality would otherwise leak the instrument count into the
            # game/video identity, breaking the count-invariance contract.
            _scripts = getattr(self, "instrument_scripts", {}) or {}
            _authored_scripts = []
            for _sname in sorted(_scripts):
                _stext = str(_scripts.get(_sname) or "")
                if instrument_script_is_stock(_stext):
                    continue
                _authored_scripts.append((
                    str(_sname),
                    hashlib.sha256(_stext.encode("utf-8", "replace")).hexdigest()[:16],
                ))
            graph_scripts_fp = hashlib.sha256(json.dumps({
                "authored_scripts": _authored_scripts,
                "rand_param_script": str(getattr(self, "live_dj_random_script", "") or ""),
                "contract": "full_graph_v1",
            }, sort_keys=True, default=str).encode("utf-8")).hexdigest()[:16]
        except Exception:
            graph_scripts_fp = "0" * 16
        live_p = ""
        try:
            pl = getattr(self, "master_playlist_data", None) or []
            if pl and isinstance(pl[0], dict) and pl[0].get("live_parametrics"):
                live_p = str(pl[0].get("live_parametrics"))[:240]
        except Exception:
            pass
        notes = ""
        try:
            if getattr(self, "qe_notes", None) is not None:
                notes = self.qe_notes.toPlainText()[:200]
        except Exception:
            pass
        # Algorithm application is composition state, not merely UI state.
        # Export both the effective per-row step algorithms and their canonical
        # digest so video/audio/game consumers see the same applied composition.
        step_rows = []
        for _r, _e in enumerate(getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or []):
            if not isinstance(_e, dict):
                continue
            step_rows.append({
                "row": int(_r),
                "scope": str(_e.get("step_algorithm_scope", "")),
                "algorithm": str(_e.get("step_algorithm", "")),
                "refs": list(_e.get("step_algorithm_refs") or []),
            })
        try:
            # GROOVEBOX_R23R_SEED_ENGINE_INVARIANCE_20261031: the step-algorithm
            # digest is roster-invariant — per-row refs are instrument names, so
            # hashing them would leak the instrument count into the game/video
            # identity. The refs still drive the music; they just do not enter
            # the identity digest.
            step_algo_fingerprint = hashlib.sha256(
                json.dumps(
                    [{"row": r["row"], "scope": r["scope"], "algorithm": r["algorithm"]} for r in step_rows],
                    sort_keys=True, default=str,
                ).encode("utf-8")
            ).hexdigest()[:16]
        except Exception:
            step_algo_fingerprint = "0" * 16
        # Engine bits from live toggles — these control game + video identity.
        # Instrument count is recorded for UI only; classify ignores it.
        rnd_on = bool(getattr(self, "btn_local_randomize", None) and self.btn_local_randomize.isChecked())
        pl_on = bool(getattr(self, "btn_local_phase_lock", None) and self.btn_local_phase_lock.isChecked())
        # CANONICAL_COMMAND_2026: master vector, xmods, synth features and
        # resonance (always 50–150%) travel with the game under canonical authority.
        master_vector = (0.0, 0.0, 0.0)
        try:
            if hasattr(self, "_master_vector_effective"):
                mv = self._master_vector_effective()
                master_vector = (float(mv[0]), float(mv[1]), float(mv[2]))
        except Exception:
            pass
        st = getattr(self, "master_vector_state", None) or {}
        gms = getattr(self, "global_mod_state", None) or {}
        resonance = float(getattr(self, "canonical_resonance_factor", CANONICAL_RESONANCE_DEFAULT) or CANONICAL_RESONANCE_DEFAULT)
        if not math.isfinite(resonance):
            resonance = 1.50
        _hyper = self._hyperdrive_state(0.0, 0) if hasattr(self, "_hyperdrive_state") else {"enabled": False}
        return {
            "bpm": float(self.spin_bpm.value()) if hasattr(self, "spin_bpm") else 120.0,
            "seq_length": int(self.spin_seq_length.value()) if hasattr(self, "spin_seq_length") else DEFAULT_SEQUENCE_LENGTH,
            "playlist_rows": int(self.spin_playlist_length.value()) if hasattr(self, "spin_playlist_length") else DEFAULT_PLAYLIST_ROWS,
            "n_instruments": len(getattr(self, "instrument_names_48", []) or []),
            "goava_active": bool(getattr(self, "goava_active", False)),
            # Preserve any continuous GOAVA activation control if present; legacy
            # projects without one retain deterministic binary toggle semantics.
            "goava_activation": max(0.0, min(1.0, float(getattr(self, "goava_activation", 1.0 if getattr(self, "goava_active", False) else 0.0) or 0.0))),
            "randomizer_active": rnd_on,
            "phase_lock_active": pl_on,
            "seed": float(self.get_numeric_seed()) if hasattr(self, "get_numeric_seed") else 0.0,
            "seed_script": str(self._seed_text() if hasattr(self, "_seed_text") else ""),
            "instrument_scripts": dict(getattr(self, "instrument_scripts", {}) or {}),
            "graph_script_variables": list(GRAPH_SCRIPT_VARIABLES),
            "graph_context_contract": "full_graph_v1",
            "graph_scripts_fingerprint": graph_scripts_fp,
            "hyperdrive": _hyper,
            "live_parametrics": live_p,
            "goava_group_phase": bool(getattr(self, "goava_active", False)),
            "global_algo": gas,
            "algorithm_xmod_local": float(getattr(self, "local_algorithm_xmod", 1.0)),
            "algorithm_xmod_global": float(getattr(self, "global_algorithm_xmod", 1.0)),
            "global_algo_fingerprint": algo_fp,
            "step_algorithms": step_rows,
            "step_algorithm_fingerprint": step_algo_fingerprint,
            "live_dj_goava": bool(getattr(self, "live_dj_goava", False)),
            "live_dj_random": bool(getattr(self, "live_dj_random", False)),
            "live_dj_random_script": str(getattr(self, "live_dj_random_script", "") or ""),
            "contour_shape": float(getattr(self, "contour_shape", 0.0) or 0.0),
            "goava_off_bleed": float(getattr(self, "goava_off_bleed", 0.0) or 0.0),
            "fractal_seed_mod": dict(self._fractal_mod_state()),
            "key_bindings": (self._key_bank().to_json() if getattr(self, "_key_bank_obj", None) is not None else {}),
            "heuristic_series_lock": bool(getattr(self, "heuristic_series_lock", False)),
            "heuristic_instrument_modes": dict(getattr(self, "heuristic_instrument_modes", {}) or {}),
            "local_algo_bays": copy.deepcopy(getattr(self, "local_algo_bays", {}) or {}),
            "algo_group_bays": copy.deepcopy(getattr(self, "algo_group_bays", {}) or {}),
            "contour_lane_shapes": dict(getattr(self, "contour_lane_shapes", {}) or {}),
            "heuristic_bays": copy.deepcopy(getattr(self, "heuristic_bays", {}) or {}),
            "project_notes": notes,
            "master_vector": master_vector,
            "master_vector_drive": float(st.get("drive", 0.50) or 0.50),
            "master_vector_enabled": bool(st.get("enabled", True)),
            "global_xmod": float(gms.get("xmod", 1.0) or 1.0),
            "global_input_xmod": float(gms.get("input_xmod", 1.0) or 1.0),
            "global_mod_state": {k: float(gms.get(k, 1.0) or 1.0) for k in ("xmod", "input_xmod", "synth", "patch", "script", "domain")},
            "md_net_mod_max": float(getattr(self, "md_net_mod_max", 0.5)),
            "md_stoch_default_mix": float(getattr(self, "md_stoch_default_mix", 1.0)),
            "automation_morph_span": float(getattr(self, "automation_morph_span", 1.0)),
            "canonical_resonance_factor": resonance,
            "resonance_min": 0.50,
            "resonance_max": 1.50,
            "wavetable_projector": dict(getattr(self, "wavetable_projector_state", {}) or {}),
            "automator_timing_mode": str(getattr(self, "automator_timing_mode", "wrap")),
            "sequencer_automation_points": list(getattr(self, "sequencer_automation_points", []) or [])[:256],
            # User-owned TrackOffset (engines respond; not a canonical write handle)
            "global_track_offset": float(getattr(self, "global_track_offset", 0.0) or 0.0),
            "track_offset": float(getattr(self, "global_track_offset", 0.0) or 0.0),
            # GAME_BOUND_MEDIA_2026: authoritative carrier + per-operator media
            # references.  Buffers are never serialized; generated games stage
            # the referenced files into their own package and use a bounded
            # decoder cache so game FPS is not tied to instrument count.
            "game_bound_media": {
                "carrier": {
                    "audio_path": str(getattr(self, "imported_wav_path", "") or ""),
                    "video_path": str(getattr(self, "imported_video_path", "") or ""),
                    "binding_mode": str(getattr(self, "carrier_binding_mode", "") or ""),
                    "binding_source": str(getattr(self, "carrier_binding_source", "") or ""),
                },
                "instruments": [
                    {
                        "name": str(_name),
                        "audio_path": str((_rec or {}).get("path", "") or ""),
                        "video_path": str((_rec or {}).get("video_path", "") or ""),
                        "video_input_enabled": bool((_rec or {}).get("video_input_enabled", False)),
                        "audio_present": bool((_rec or {}).get("audio_present", bool((_rec or {}).get("path")))),
                        "binding_mode": str((_rec or {}).get("binding_mode", "") or ""),
                        "binding_source": str((_rec or {}).get("binding_source", "") or ""),
                    }
                    for _name, _rec in sorted((getattr(self, "instrument_media_samples", {}) or {}).items())
                    if isinstance(_rec, dict) and ((_rec.get("path")) or (_rec.get("video_path")))
                ],
                "visual_policy": {"carrier_full_frame": True, "instrument_tile_max_fraction": 0.18, "max_live_video_decoders": 4},
                "audio_policy": {"carrier_gain": 0.45, "instrument_gain": 0.14, "max_live_audio_players": 8},
            },
            # GROOVEBOX_R23R_MULTIDIM_SCENE_20261103: the multidimensional programmes; the game
            # rebuilds the exact same world (CA, ball, vector, partials, resonators) at its own time
            "multidim": self._multidim_programmes_for_game(),
            "multidim_clock": list(__import__("multidim_scene").host_clock(self)),   # (sample rate, row duration)
            "multidim_opacity": float(getattr(self, "multidim_video_opacity", 0.85)) * float(self._md_mix()),
        }

    def _classify_live_game(self):
        """Deterministic unique non-redundant game identity from the live seed."""
        global _vge
        if _vge is None:
            try:
                import videogame_engine as _vge
            except Exception as e:
                raise RuntimeError(f"videogame_engine not available: {e}")
        meta = self._composition_meta_for_game()
        # Prefer first playlist row live_parametrics if present
        try:
            pl = getattr(self, "master_playlist_data", None) or []
            if pl and isinstance(pl[0], dict) and pl[0].get("live_parametrics"):
                meta["live_parametrics"] = str(pl[0].get("live_parametrics"))[:240]
        except Exception:
            pass
        _game_seed = float(meta["seed"])
        _hd = meta.get("hyperdrive") or {}
        if bool(_hd.get("enabled", False)):
            # Same shared finite coordinate deterministically perturbs the game
            # identity seed; no independent random branch is introduced.
            _game_seed = _game_seed + float(_hd.get("modulation", 0.0)) * float(MEUM_MINUS_1)
        _game_payload = (_game_seed, meta)
        _opt = getattr(self, "_scode_optimizer", None)
        def _produce_game_identity():
            return _vge.classify_from_composition(
            _game_seed,
            bpm=meta["bpm"],
            seq_length=meta["seq_length"],
            playlist_rows=meta["playlist_rows"],
            n_instruments=meta.get("n_instruments", 8),  # ignored by identity
            goava_active=meta["goava_active"],
            randomizer_active=bool(meta.get("randomizer_active", False)),
            phase_lock_active=bool(meta.get("phase_lock_active", False)),
            live_parametrics=meta.get("live_parametrics"),
            global_algo_fingerprint=meta.get("global_algo_fingerprint"),
            global_algo=meta.get("global_algo"),
            step_algorithm_fingerprint=meta.get("step_algorithm_fingerprint"),
            step_algorithms=meta.get("step_algorithms"),
            live_dj_goava=meta.get("live_dj_goava"),
            live_dj_random=meta.get("live_dj_random"),
            graph_scripts_fingerprint=meta.get("graph_scripts_fingerprint"),
        )
        if _opt is not None:
            identity = _opt.memoized_result("game", _game_payload, _produce_game_identity, max_entries=24)
        else:
            identity = _produce_game_identity()
        return identity, meta

    def _on_export_videogame_scripts(self):
        """Export the video game as one .zip package: deterministic script +
        identity JSON + Windows/macOS/Linux launchers, all from the live seed."""
        if not self._prepare_export_project('game export'):
            return
        try:
            identity, meta = self._classify_live_game()
        except Exception as e:
            QMessageBox.warning(self, "Video Game", str(e))
            return
        default_name = (self._export_name(f"game {identity.composition_fingerprint[:8]}", ".MCC", self._games_dir()))
        path, _filter = QFileDialog.getSaveFileName(
            self, "Export Video Game Package", default_name,
            "Video Game Package (*.MCC);;Legacy .zip package (*.zip);;All files (*)",
        )
        if not path:
            return
        legacy_zip = path.lower().endswith(".zip") or "zip" in str(_filter).lower()
        if not legacy_zip and not path.lower().endswith(".mcc"):
            path = path + ".MCC"
        try:
            global _vge
            _prov = json.loads(self._export_provenance_payload())
            if legacy_zip:
                out = _vge.package_game_zip(identity, path, meta, {"provenance.mgpr": _prov})
            else:
                # GROOVEBOX_R23R_MCC_MEDIA_CODEC_20261101: .MCC package + real composition audio.
                out = _vge.package_game_mcc(identity, path, meta, {"provenance.mgpr": _prov},
                                            composition_audio=self._cached_shared_mixdown(max_age=0))
            self._last_videogame_path = out
            self._last_videogame_identity = identity.to_dict()
            QMessageBox.information(
                self, "Video Game Exported",
                f"{identity.title}\n\nPackage ({'.zip' if legacy_zip else '.MCC'}):\n{out}\n\n"
                f"Includes: game script · identity JSON · launch_windows.bat · "
                f"launch_macos.command · launch_linux.sh\n\n"
                f"genre={identity.genre} camera={identity.camera}\n"
                f"objective={identity.objective} difficulty={identity.difficulty}\n"
                f"level_type={identity.level_type} sigil_count={identity.sigil_count}\n"
                f"world_fingerprint={identity.world_fingerprint}"
            )
        except Exception as e:
            QMessageBox.warning(self, "Export failed", str(e))

    def _set_work_progress(self, kind, value, text=""):
        try:
            v=max(0,min(100,int(value)))
            self._render_pipeline_stats["last_kind"]=str(kind); self._render_pipeline_stats["progress"]=v
            self._work_progress_latest=(v,(str(text) if text else str(kind))+f"  {v}%")
            def _apply():
                bar=getattr(self,"work_progress",None)
                lv,lt=getattr(self,"_work_progress_latest",(v,""))
                if bar is not None:
                    bar.setValue(lv); bar.setFormat(lt)
            # Render workers report progress too; widgets are only touched on the GUI thread.
            self._gui_refresh("work_progress",_apply) if hasattr(self,"_gui_refresh") else _apply()
        except Exception:
            pass

    def _shared_mixdown_key(self, max_rows=None):
        try:
            payload={
                "fp":self._canonical_fingerprint(),"rows":max_rows,
                "playlist":getattr(self,"master_playlist_data",[]),
                "seq":getattr(self,"instrument_sequencer_memory",{}),
                "params":getattr(self,"instrument_param_state",{}),
                "global_eq":getattr(self,"global_eq_state",{}),
                "carrier":str(getattr(self,"imported_wav_path","") or ""),
                "algo":getattr(self,"global_algo_state",{}),
                # R23r: every state the render reads must invalidate the shared buffer.
                "ball":getattr(self,"ball_synth_params",{}),
                "cellular":getattr(self,"cellular_synth_params",{}),
                # R32.8: automation lanes + every R32 module state change the render too
                "r32_auto":getattr(self,"r32_automation",None),
                "r32_fx":getattr(self,"r32_fx_state",None),"r32_tfx":getattr(self,"r32_time_fx",None),
                "r32_syn":getattr(self,"r32_synth_engine",None),"r32_mod":getattr(self,"r32_mod_osc",None),
                "r32_eq":getattr(self,"r32_eq",None),"r32_pred":getattr(self,"r32_predictive",None),
                "r32_div":(getattr(self,"seed_divergence",None),getattr(self,"_r32_divergence_user",False)),
                "r32_inst":getattr(self,"r32_active_instruments",None),
                "r32_mix":getattr(self,"r32_inst_mix",None),
                "r32_perseq":getattr(self,"r32_perseq",None),
                "rand_src":(str(getattr(self,"rand_source","fractal")),int(getattr(self,"_rand_instance_seed",0) or 0)),
                "conv_track":bool(getattr(self,"convolve_tracks_workspace",True)),
                "wavetable":getattr(self,"wavetable_projector_state",{}),
                "vector":getattr(self,"master_vector_state",{}),
                "geo_mix":getattr(self,"geometric_synth_mixer_state",{}),
                "master_eq":getattr(self,"master_global_eq_points",[]),
                "sidechain":getattr(self,"sidechain_state",{}),
                "mod":getattr(self,"global_mod_state",{}),
                "md_net":float(getattr(self,"md_net_mod_max",0.5)),   # R31: multidim max net modulation
                "md_stoch":float(getattr(self,"md_stoch_default_mix",1.0)),
                "auto_span":float(getattr(self,"automation_morph_span",1.0)),   # R31.7: automation morph span
                "touched":sorted((getattr(self,"_canonical_field_touched",set()) or []), key=lambda x: (x is None, type(x).__name__, str(x))),
                "energy":(int(self.dial_track_energy.value()) if hasattr(self,"dial_track_energy") else 50,
                          int(self.dial_track_harmonic.value()) if hasattr(self,"dial_track_harmonic") else 50),
                "patch_motion":getattr(self,"patch_motion_state",{}),
                "loudness_match":bool(getattr(self,"loudness_match_enabled",True)),
                "seed_ws_override":bool(SEED_WORKSPACE_OVERRIDE),
                "auto_points":getattr(self,"sequencer_automation_points",[]),
                "engines":sorted(self._get_active_engine_set()) if hasattr(self,"_get_active_engine_set") else [],
                "sample_morph":getattr(self,"sample_morph_state",{}),
                "samples":{str(k):(str(v.get("path","")),int(v.get("sample_rate",0) or 0),bool(v.get("reversed")),bool(v.get("pingpong")),
                                   zlib.crc32(np.ascontiguousarray(np.asarray(v.get("waveform"),dtype=np.float32)).tobytes()) if v.get("waveform") is not None else 0)
                           for k,v in sorted((getattr(self,"instrument_media_samples",{}) or {}).items()) if isinstance(v,dict)},
            }
            return hashlib.sha256(json.dumps(payload,sort_keys=True,default=str,separators=(",",":")).encode()).hexdigest()
        except Exception:
            return f"fallback:{self._canonical_fingerprint()}:{max_rows}:{getattr(self,'_composition_generation_counter',0)}"

    def _snapshot_render_inputs(self):
        """Copy the widget values the mixdown reads, so a worker never touches Qt."""
        def _v(obj, default=0.0):
            try:
                return float(obj.value()) if obj is not None else float(default)
            except Exception:
                return float(default)
        def _b(obj, default=False):
            try:
                return bool(obj.isChecked()) if obj is not None else bool(default)
            except Exception:
                return bool(default)
        self._render_input_snapshot = {
            "bpm": _v(getattr(self, "spin_bpm", None), 120.0),
            "rows": _v(getattr(self, "spin_playlist_length", None), DEFAULT_PLAYLIST_ROWS),
            "seq_length": _v(getattr(self, "spin_seq_length", None), DEFAULT_SEQUENCE_LENGTH),
            "global_playlist": _b(getattr(self, "chk_global_playlist", None), True),
            "row_beats": _v(getattr(self, "spin_row_beats", None), 4.0),
            "playlist_beats": _v(getattr(self, "spin_playlist_beats", None), 4.0),
            "eqr": _v(getattr(self, "slider_eqr", None), EQR_DEFAULT * 100.0) / 100.0,
            "pkp": _v(getattr(self, "slider_pkp_envelope", None), 500.0) / 1000.0,
            "fractalizer": _v(getattr(self, "slider_fractalizer", None), FRACTALLIZER_DEFAULT * 100.0) / 100.0,
            "convolve_fit": _b(getattr(self, "chk_convolve_fit", None), False),
            "global_convolve": _v(getattr(self, "slider_global_convolve", None), 0.0) / 100.0,
            "sparse": _b(getattr(self, "chk_sparse_mask", None), False),
            "sparse_density": _v(getattr(self, "spin_sparse_density", None), 1.0),
            "base_frequency": _v(getattr(self, "spin_base_frequency", None), 432.0),
        }

    def _rin(self, name, default=0.0):
        snap = getattr(self, "_render_input_snapshot", None) or {}
        return snap.get(name, default)

    def _begin_playback_async(self, audio_only=False):
        """Render the shared mixdown off the UI thread, then open the stream."""
        # GROOVEBOX_PLAY_GUARD_20261031: generation token + no nested event loop.
        self._play_gen = int(getattr(self, "_play_gen", 0)) + 1
        _gen = self._play_gen
        # GROOVEBOX_R23R_TRANSPORT_FREES_AUDITION_20261103: the Trigger / key-chart audition
        # stream stays open between hits; on a direct ALSA device (Dell, sOS) it kept the card
        # busy so Play Audio / Audiovisual / This Sequence opened silently after any key press.
        try:
            self._close_audition_stream()
        except Exception:
            pass
        try:
            if getattr(self, "_live_player_window", None) is not None:
                self._live_player_window.stop()   # GROOVEBOX_R23R_LIVE_PLAYER_20261103
        except Exception:
            pass
        try:
            self._snapshot_render_inputs()
        except Exception as exc:
            print(f"[Play] snapshot failed: {exc}")
            self._live_preview_rows_override = None
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText("Play failed: %s" % exc)
            return
        prev = self._live_preview_max_rows()
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("Rendering track…" if not audio_only else "Rendering audio…")
            try:
                self.scope_status_label.repaint()
            except Exception:
                pass
        def _work():
            return self._get_shared_mixdown_buffer(max_rows=prev, purpose="Play prepare")

        def _start_lane():
            """In-window render on the audio lane thread (fallback / cache hit)."""
            try:
                fut = self._live_audio_fx_lane.submit(_work)
            except Exception as exc:
                print(f"[Play] render lane unavailable: {exc}")
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText("Render lane unavailable; try again")
                self._live_preview_rows_override = None
                return

            def _finish():
                if _gen != getattr(self, "_play_gen", _gen):
                    return  # Stop / a newer Play superseded this render
                if not fut.done():
                    QTimer.singleShot(40, _finish)
                    return
                try:
                    buf, sr = fut.result()
                except Exception as exc:
                    if hasattr(self, "scope_status_label"):
                        self.scope_status_label.setText("Render failed: %s" % exc)
                    return
                try:
                    self._open_play_stream(buf, sr, audio_only=audio_only, preview_rows=prev)
                except Exception as exc:
                    print(f"[Play] stream open failed safely: {exc}")
                    self._abort_play_stream_open(exc)
            QTimer.singleShot(0, _finish)

        # GROOVEBOX_R23R_PROCESS_RENDER_20261103: a cache miss renders in the worker PROCESS
        # (the window stays responsive); the in-window thread render remains the fallback.
        try:
            _cached_now = self._cached_shared_mixdown(prev, max_age=0.0) is not None
        except Exception:
            _cached_now = False
        _use_proc = (not _cached_now) and os.environ.get("GROOVEBOX_PLAY_IN_PROCESS", "1") != "0"
        if _use_proc and getattr(self, "_bg_prerender_inflight", False):
            self._cancel_render_process()          # Play wins over the idle pre-render
        if _use_proc and not getattr(self, "_export_worker_busy", False):
            def _proc_done(buf, sr, err):
                if _gen != getattr(self, "_play_gen", _gen):
                    return
                if err or buf is None:
                    print(f"[Play] render process failed ({err}); rendering in the window instead")
                    _start_lane()
                    return
                try:
                    self._open_play_stream(buf, sr, audio_only=audio_only, preview_rows=prev)
                except Exception as exc:
                    print(f"[Play] stream open failed safely: {exc}")
                    self._abort_play_stream_open(exc)
            if self._render_in_process_async("Play prepare", _proc_done, max_rows=prev) is not None:
                return
        _start_lane()

    def _abort_play_stream_open(self, exc=None):
        """Return the transport to a clean idle state after a failed stream open."""
        self.is_playing = False
        self.is_paused = False
        self._audio_only_mode = False
        self._live_preview_rows_override = None
        try:
            st = getattr(self, "audio_stream", None)
            self.audio_stream = None
            if st is not None:
                try: st.stop()
                except Exception: pass
                try: st.close()
                except Exception: pass
        except Exception:
            pass
        try:
            if hasattr(self, "_scope_update_timer") and self._scope_update_timer.isActive():
                self._scope_update_timer.stop()
        except Exception:
            pass
        try:
            self.btn_play.setText("▶ PLAY Audiovisual Track")
            self.btn_audio_only.setText("▶ PLAY Audio Track")
            self.scope_status_label.setText("Audio output unavailable: %s" % (exc or "stream failed"))
        except Exception:
            pass

    def _open_play_stream(self, buf, sr, audio_only=False, preview_rows=None):
        _render_sr = int(sr)
        if HAS_SOUNDDEVICE:
            preferred = str(getattr(self, "_preferred_audio_output_name", "") or "")
            buf, sr, _hw = prepare_output_buffer(buf, sr, preferred_name=preferred)
        with self.play_lock:
            self.play_buffer = buf
            self.play_sample_rate = sr
            self.play_cursor = 0
            self.is_playing = True
            try:
                self._pulse_multidim_viz(0.3)
            except Exception:
                pass
            self.is_paused = False
            self._audio_only_mode = bool(audio_only)
            self._transport_finished = False
            self._stop_requested = False
        try:
            self._live_audio_fx_lane.submit(self._prepare_realtime_dj_cache)
        except Exception:
            pass
        if HAS_SOUNDDEVICE:
            self._close_audition_stream()   # PLAY_KEYS_ON_TRANSPORT_20261102: free the hw for the transport
            try:
                self.concurrent_audio_bus.clear()
            except Exception:
                pass
            old = getattr(self, "audio_stream", None)
            self.audio_stream = None
            if old is not None:
                try:
                    old.stop()
                except Exception:
                    pass
                try:
                    old.close()
                except Exception:
                    pass
            if buf is None or int(np.asarray(buf).size) == 0:
                if hasattr(self, "scope_status_label"):
                    self.scope_status_label.setText("This Sequence · empty buffer")
                self._abort_play_stream_open("empty buffer")
                return
            self.audio_stream = open_output_stream(
                samplerate=sr, channels=1, dtype="float32", callback=self._audio_callback,
                blocksize=_stream_tuning("transport")[0], latency=_stream_tuning("transport")[1],
                preferred_name=str(getattr(self, "_preferred_audio_output_name", "") or ""),
            )
            self.audio_stream.start()
        if audio_only:
            self.btn_audio_only.setText("🔊 AUDIO Track  |  LIVE")
            self.btn_play.setText("▶ PLAY Audiovisual Track")
        else:
            self.btn_play.setText("⏸ PAUSE Audiovisual Track")
        if hasattr(self, "scope_status_label"):
            tag = " preview %sr" % preview_rows if preview_rows else ""
            self.scope_status_label.setText(("🔊 Audio" if audio_only else "📊 Audiovisual") + " Track  |  LIVE" + tag)
        self._scope_tick_counter = 0
        self._scope_update_timer.start()

    def _entropy_knob(self, attr):
        """-1..+1 from a 0..100 knob; 0 at centre (off)."""
        dial = getattr(self, attr, None)
        try:
            v = int(dial.value()) if dial is not None else 50
        except Exception:
            v = 50
        return float(np.clip((v - 50) / 50.0, -1.0, 1.0))

    def _on_entropy_knob_changed(self):
        e = self._entropy_knob("dial_track_energy"); h = self._entropy_knob("dial_track_harmonic")
        self.entropy_energy_mode = "balanced" if e == 0 else ("increase" if e > 0 else "lower")
        self.entropy_harmonic_mode = "balanced" if h == 0 else ("divergence" if h > 0 else "convergence")
        try:
            self._shared_mixdown_cache = {}
        except Exception:
            pass
        try:
            self._on_live_source_changed()
        except Exception:
            pass

    def _apply_entropy(self, buf):
        """Track Energy + Converge/Diverge master-bus knobs. Centre leaves audio untouched.

        GROOVEBOX_R23R_TRACK_ENERGY_HARMONIC_KNOBS_20261031: user-only (no canonical
        scaling). Replaces the old dropdowns, whose amount depended on the mean
        canonical engine level and whose "increase" mode hard-clipped at full scale.
        """
        arr = np.asarray(buf, dtype=np.float32)
        e = self._entropy_knob("dial_track_energy")
        h = self._entropy_knob("dial_track_harmonic")
        if e == 0.0 and h == 0.0:
            return arr
        if h < 0.0:
            a = -h
            smooth = np.convolve(arr, np.ones(5, dtype=np.float32) / 5.0, mode="same")
            arr = (1.0 - a) * arr + a * smooth
        elif h > 0.0:
            arr = arr + (0.15 * h) * np.diff(arr, prepend=arr[:1])
        gain = 1.0 + 0.35 * e
        arr = arr * gain                       # plain gain; no soft saturation (project policy)
        return np.clip(arr, -1.0, 1.0).astype(np.float32)

    def _cached_shared_mixdown(self, max_rows=None, max_age=1.0):
        """The shared mixdown if it is already rendered for the current state, else None (never renders).

        GROOVEBOX_R23R_MIXDOWN_PROBE_MEMO_20261101: the scenograph asks this from
        paintEvent/render_frame on every frame, and the exact key serialises and
        hashes the whole project (incl. CRC32 of every sample waveform). Visual
        callers get a memoised answer for max_age seconds; render/export paths call
        _get_shared_mixdown_buffer(), which always computes the exact key.
        """
        now = time.monotonic()
        memo = getattr(self, "_mixdown_probe_memo", None)
        if memo is not None and memo[0] == max_rows and now - memo[1] < float(max_age):
            return memo[2]
        try:
            key = self._shared_mixdown_key(max_rows)
            with self._shared_mixdown_lock:
                ent = self._shared_mixdown_cache.get(key)
            out = (ent[0], ent[1]) if ent is not None else None
        except Exception:
            out = None
        self._mixdown_probe_memo = (max_rows, now, out)
        return out

    def _get_shared_mixdown_buffer(self, max_rows=None, purpose="Render", force=False):
        """One authoritative PCM memory buffer reused by Play and every export.
        render/export unchanged: the composition rate is not rewritten here.
        """
        key=self._shared_mixdown_key(max_rows)
        # SINGLE_FLIGHT_20261107: only one render of a key at a time.
        # A second caller waits and then reads the cache.
        flight = getattr(self, "_mixdown_flight", None)
        if flight is None:
            self._mixdown_flight = flight = {}
        ev = flight.get(key)
        if ev is not None and not force:
            ev.wait(30)
            with self._shared_mixdown_lock:
                ent = self._shared_mixdown_cache.get(key)
                if ent is not None:
                    return ent[0], ent[1]
        ev = flight.setdefault(key, threading.Event())
        with self._shared_mixdown_lock:
            ent=self._shared_mixdown_cache.get(key)
            if (not force) and ent is not None:
                self._render_pipeline_stats["cache_hits"]+=1
                self._set_work_progress(purpose,100,f"{purpose} · shared buffer ready")
                # One shared PCM source feeds audio analysis as well as playback
                # and export, including when the mixdown came from cache.
                try:
                    import canonical_cross_media as _cm
                    self._last_cross_media_wave_analysis = _cm.analyze_waveform(ent[0], int(ent[1]))
                except Exception:
                    pass
                try:
                    _buffer_linker().link(self)
                except Exception:
                    pass
                try:
                    flight.get(key, threading.Event()).set()
                except Exception:
                    pass
                return ent[0],ent[1]
        self._render_pipeline_stats["cache_misses"]+=1
        self._set_work_progress(purpose,3,f"{purpose} · prepare shared buffer")
        self._seed_values_memo={}
        # POOL_PASS_20261107: the shared buffer is the single source for play
        # and export. Callers should read it, not rebuild, unless force=True.
        # LIVE_BUFFER_20261107: audio is the base. Video renders on top of this
        # buffer. The change point (if set) is the start of the rebuild.
        # BUFFER_OFF_UI_20261107: do not processEvents here. This runs on the
        # audio lane; a nested event loop re-enters the UI and freezes it.
        try:
            buf,sr=self._render_mixdown_buffer(max_rows=max_rows)
        finally:
            self._seed_values_memo=None
        buf=self._apply_entropy(buf)
        # R23r loudness matching (gain only, peak-capped; no limiter).
        # GROOVEBOX_R23R_LOUDNESS_BEFORE_CLIP_20261101: order is fixed —
        #   render (no clip) → entropy → LOUDNESS MATCH (relative gain on the
        #   unclipped sum) → shared buffer → master bus: volume × factors → HARD CLIP.
        # Every consumer (live play, audio/video/MCC/batch exports, bake) reads this
        # buffer, so loudness is always measured and applied before any hard clip.
        try:
            if bool(getattr(self,"loudness_match_enabled",True)):
                _lg,_lufs=loudness_match_gain(buf,sr)
                self._last_loudness_report={"lufs_in":_lufs,"gain_db":20.0*math.log10(_lg) if _lg>0 else None}
                if _lg!=1.0:
                    buf=(np.asarray(buf,dtype=np.float32)*np.float32(_lg)).astype(np.float32)
                print(f"[Loudness] in={_lufs if _lufs is None else round(_lufs,2)} LUFS gain={20.0*math.log10(_lg):+.2f} dB target {LOUDNESS_TARGET_LUFS} LUFS",flush=True)
        except Exception as _ld_exc:
            print(f"[Loudness] skipped: {_ld_exc}")
        # Keep the actual ndarray object authoritative; callers must treat it read-only.
        buf=np.ascontiguousarray(np.asarray(buf,dtype=np.float32))
        try: buf.setflags(write=False)
        except Exception: pass
        with self._shared_mixdown_lock:
            self._shared_mixdown_cache={key:(buf,int(sr),time.monotonic())}
        # SINGLE_FLIGHT_20261107: wake any waiter now that the buffer is stored.
        try:
            flight.get(key).set()
        except Exception:
            pass
        # CANONICAL_CROSS_MEDIA_SOURCE_20261023: analyze the exact PCM buffer
        # used by Play/export; the visual renderer consumes this live trace per
        # frame. Analysis is deterministic and never mutates the audio buffer.
        try:
            import canonical_cross_media as _cm
            self._last_cross_media_wave_analysis = _cm.analyze_waveform(buf, int(sr))
        except Exception:
            pass
        self._set_work_progress(purpose,100,f"{purpose} · shared buffer ready")
        return buf,int(sr)

    def _playlist_snapshot_threaded(self):
        """Freeze playlist data on its dedicated lane before expensive work."""
        try:
            fut=self._playlist_lane.submit(copy.deepcopy,getattr(self,"master_playlist_data",[]) or [])
            return fut.result()
        except Exception:
            return _fast_copy(getattr(self,"master_playlist_data",[]) or [])

    def _sequencer_snapshot_threaded(self):
        """Freeze sequencer/bank data on its own lane, parallel to playlist planning."""
        try:
            payload = (
                getattr(self, "instrument_sequencer_memory", {}) or {},
                getattr(self, "instrument_sequence_banks", {}) or {},
                getattr(self, "instrument_selected_sequence", {}) or {},
            )
            fut = self._sequencer_lane.submit(copy.deepcopy, payload)
            mem, banks, selected = fut.result()
            return mem, banks, selected
        except Exception:
            return (
                copy.deepcopy(getattr(self, "instrument_sequencer_memory", {}) or {}),
                copy.deepcopy(getattr(self, "instrument_sequence_banks", {}) or {}),
                copy.deepcopy(getattr(self, "instrument_selected_sequence", {}) or {}),
            )

    def _live_audio_analysis_job(self, chunk):
        """Calculate meter values away from the real-time audio callback."""
        samples = np.asarray(chunk, dtype=np.float32).reshape(-1)
        if not samples.size:
            peak = rms = 0.0
        else:
            peak = float(np.max(np.abs(samples)))
            rms = float(np.sqrt(np.mean(samples * samples)))
        previous_hold = float(getattr(self, "_live_peak_hold", 0.0) or 0.0)
        sample_rate = max(float(getattr(self, "preferred_sample_rate", 44100) or 44100), 1.0)
        hold_decay = float(np.exp(-float(samples.size) / sample_rate))
        peak_hold = max(peak, previous_hold * hold_decay)
        return {"rms": rms, "peak": peak, "peak_hold": peak_hold}

    def _queue_live_audio_analysis(self, chunk):
        """Schedule at most one meter job; analysis must never back-pressure audio."""
        if getattr(self, "_live_audio_analysis_pending", False):
            return
        self._live_audio_analysis_pending = True
        try:
            # Copy the short output chunk so the worker never observes a buffer
            # that PortAudio or the next callback is about to reuse.
            snapshot = np.asarray(chunk, dtype=np.float32).copy()
            future = self._live_audio_analysis_lane.submit(
                self._live_audio_analysis_job, snapshot
            )
        except Exception:
            self._live_audio_analysis_pending = False
            return

        def _publish_metrics(done_future):
            try:
                metrics = done_future.result()
                self._live_audio_metrics = metrics
                self._live_peak = float(metrics.get("peak", 0.0))
                self._live_peak_hold = float(metrics.get("peak_hold", 0.0))
            except Exception:
                # Meter errors are non-fatal and intentionally do not escape
                # into the PortAudio thread.
                pass
            finally:
                self._live_audio_analysis_pending = False

        future.add_done_callback(_publish_metrics)

    def _health_report_text(self):
        lines=["Groovebox System / Performance Health", "="*38]
        st=getattr(self,"_render_pipeline_stats",{}) or {}
        lines.append(f"Render pipeline: {st.get('last_kind','idle')} {st.get('progress',0)}% · buffer hits {st.get('cache_hits',0)} / misses {st.get('cache_misses',0)}")
        lines.append(f"Python threads: {threading.active_count()} · CPU cores: {os.cpu_count() or '?'}")
        try:
            lines.append(f"Load average: {', '.join(f'{v:.2f}' for v in os.getloadavg())}")
        except Exception: pass
        _pb = getattr(self, "play_buffer", None)
        try:
            _pbn = int(len(_pb)) if _pb is not None else 0
        except Exception:
            _pbn = 0
        lines.append(f"Audio: {'PLAYING' if getattr(self,'is_playing',False) else 'idle'} · {getattr(self,'play_sample_rate',0)} Hz · buffer {_pbn} samples")
        m=getattr(self,"_live_audio_metrics",{}) or {}; lines.append(f"Live meters: RMS {float(m.get('rms',0.0)):.4f} · peak {float(m.get('peak',0.0)):.4f}")
        lines.append(f"Video render calibration: {float(getattr(self,'_video_render_seconds_per_frame',0.0) or 0.0):.4f} s/frame")
        # Linux removable-media summary, including Dell microSD mmcblk devices.
        try:
            devs=[]
            for root in ('/sys/class/block','/sys/block'):
                if os.path.isdir(root):
                    for n in os.listdir(root):
                        if n.startswith('mmcblk') or n.startswith('sd'):
                            devs.append(n)
            lines.append("Removable candidates: "+(", ".join(sorted(set(devs))) if devs else "none visible to kernel"))
        except Exception: pass
        try:
            if HAS_SOUNDDEVICE:
                q=sd.query_devices(); lines.append(f"PortAudio devices: {len(q)}")
        except Exception as e: lines.append(f"PortAudio scan: {e}")
        lines.append("Worker lanes: project-memory · playlist-data · sequencer-plan · canonical-write · live-audio-fx · live-audio-analysis · per-canonical · waveform · spectrum · video-object")
        return "\n".join(lines)

    def _run_health_job(self, title, work, finish):
        """Run blocking OS work (modprobe/udevadm/alsactl) off the GUI thread.

        GROOVEBOX_NO_GUI_STALL_20261030: these used to run inline and could freeze
        the whole UI for 30+ seconds.  ``finish`` runs back on the GUI thread.
        """
        if getattr(self, "_health_job_busy", False):
            self._set_work_progress(title, 10, f"{title}: previous health action still running")
            return
        bridge = getattr(self, "_health_job_bridge", None)
        if bridge is None:
            bridge = _HealthJobBridge(self)
            bridge.done.connect(lambda fn: fn())
            self._health_job_bridge = bridge
        self._health_job_busy = True

        def _end():
            self._health_job_busy = False
            try:
                finish()
            except Exception as exc:
                print(f"[Health] {title} finish failed: {type(exc).__name__}: {exc}")

        def _runner():
            try:
                work()
            except Exception as exc:
                print(f"[Health] {title} failed: {type(exc).__name__}: {exc}")
            try:
                bridge.done.emit(_end)
            except RuntimeError:
                pass  # window closed while the job ran

        threading.Thread(target=_runner, daemon=True, name="GrooveboxHealthJob").start()

    def _live_portaudio_streams(self):
        """True if any known PortAudio stream is still running (terminate/initialize would crash it)."""
        if not HAS_SOUNDDEVICE:
            return False
        base = getattr(sd, "_StreamBase", None)
        owners = [self, getattr(self, "_performance_panel", None), getattr(self, "record_page", None),
                  getattr(self, "video_studio", None), getattr(self, "concurrent_audio_bus", None)]
        for owner in owners:
            if owner is None:
                continue
            try:
                values = list(vars(owner).values())
            except Exception:
                continue
            for v in values:
                try:
                    if base is not None and isinstance(v, base) and v.active:
                        return True
                except Exception:
                    continue
        return False

    def _health_recover_audio(self):
        self._set_work_progress("Recover Audio",10,"Recover Audio")
        try: self.stop_playback()
        except Exception: pass

        def work():
            for cmd in (["udevadm","trigger","--subsystem-match=sound"],["alsactl","init"]):
                try: subprocess.run(cmd,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=8)
                except Exception: pass
            try:
                from media_output_router import _preferred_alsa_output_device, _prepare_physical_alsa_output
                _dev=_preferred_alsa_output_device()
                if _dev: _prepare_physical_alsa_output(_dev)
            except Exception: pass

        def finish():
            # PortAudio terminate/initialize closes every open stream underneath its
            # owner; doing that while any stream is live segfaults on the next callback.
            try:
                if self._live_portaudio_streams():
                    print("[Health] Recover Audio: live audio stream present; skipping PortAudio re-init")
                elif HAS_SOUNDDEVICE and hasattr(sd,"_terminate") and hasattr(sd,"_initialize"):
                    sd._terminate(); sd._initialize()
            except Exception: pass
            try:
                from audio_os_backend import invalidate_device_cache
                invalidate_device_cache()
            except Exception: pass
            try:
                p=getattr(self,"_performance_panel",None)
                if p is not None and hasattr(p,"_refresh_hardware"): p._refresh_hardware()
            except Exception: pass
            self._set_work_progress("Recover Audio",100,"Recover Audio complete")
            self._refresh_health_panel()

        self._run_health_job("Recover Audio", work, finish)

    def _health_rescan_storage(self):
        self._set_work_progress("Rescan SD",10,"Rescan SD / removable")

        def work():
            for mod in ("rtsx_pci_sdmmc","rtsx_pci","sdhci_pci","sdhci","mmc_block","usb_storage","uas"):
                try: subprocess.run(["modprobe",mod],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=5)
                except Exception: pass
            try: subprocess.run(["udevadm","trigger","--subsystem-match=block"],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=8)
            except Exception: pass

        def finish():
            try:
                p=getattr(self,"_performance_panel",None)
                if p is not None and hasattr(p,"_refresh_storage_devices"): p._refresh_storage_devices()
            except Exception: pass
            self._set_work_progress("Rescan SD",100,"Rescan SD complete")
            self._refresh_health_panel()

        self._run_health_job("Rescan SD", work, finish)

    def _rename_file_dialog(self):
        """Safely rename a user-selected file without overwriting an existing file."""
        source, _ = QFileDialog.getOpenFileName(self, "Choose File to Rename", self._project_workspace(), "All files (*)")
        if not source:
            return
        source = os.path.abspath(os.path.expanduser(source))
        if not os.path.isfile(source):
            QMessageBox.warning(self, "Rename File", "Choose an existing regular file.")
            return
        old_name = os.path.basename(source)
        new_name, accepted = QInputDialog.getText(self, "Rename File", "New filename (keep the extension when renaming projects):", text=old_name)
        if not accepted:
            return
        new_name = str(new_name or "").strip()
        if not new_name or new_name in (".", "..") or os.path.basename(new_name) != new_name or any(c in new_name for c in ("/", "\\", "\x00")):
            QMessageBox.warning(self, "Rename File", "Enter a valid filename without directory separators.")
            return
        # Preserve the MCC extension if the user entered a bare project name.
        if source.lower().endswith(".mcc") and not new_name.lower().endswith(".mcc"):
            new_name += ".MCC"
        target = os.path.join(os.path.dirname(source), new_name)
        if os.path.abspath(target) == source:
            return
        if os.path.exists(target):
            QMessageBox.warning(self, "Rename File", f"A file already exists at:\n{target}\n\nNothing was overwritten.")
            return
        try:
            os.rename(source, target)
            if os.path.abspath(str(getattr(self, "_current_project_path", "") or "")) == source:
                self._current_project_path = target
                try:
                    import groovebox_paths
                    groovebox_paths.project_root(target)
                    groovebox_paths.index_file(target, "project", target)
                except Exception as index_exc:
                    print(f"[Rename File] Project renamed; index refresh skipped: {index_exc}")
            QMessageBox.information(self, "Rename File", f"Renamed successfully:\n{old_name}\n→ {new_name}")
        except OSError as exc:
            QMessageBox.critical(self, "Rename File Failed", str(exc))

