    def _open_musical_explorer(self):
        """Open the bundled standalone Musical Explorer without mutating project/audio state."""
        try:
            from pathlib import Path
            candidates = [
                Path(__file__).resolve().parent / "docs" / "fractal-seed-mode" / "musical_explorer.html",
            ]
            frozen_root = getattr(sys, "_MEIPASS", None)
            if frozen_root:
                candidates.append(Path(frozen_root) / "docs" / "fractal-seed-mode" / "musical_explorer.html")
            try:
                candidates.append(Path(sys.executable).resolve().parent / "docs" / "fractal-seed-mode" / "musical_explorer.html")
            except Exception:
                pass
            asset = next((q for q in candidates if q.is_file()), None)
            if asset is None:
                raise FileNotFoundError("Bundled docs/fractal-seed-mode/musical_explorer.html is missing")
            dlg = getattr(self, "_musical_explorer_dialog", None)
            if dlg is not None:
                try:
                    if dlg.isVisible():
                        dlg.show(); dlg.raise_(); dlg.activateWindow(); return
                except Exception:
                    pass
            dlg = QDialog(self)
            dlg.setWindowTitle("Musical Explorer · Fractal Seed")
            dlg.resize(1280, 820)
            layout = QVBoxLayout(dlg)
            split = QHBoxLayout()
            side = QPlainTextEdit()
            side.setReadOnly(True)
            side.setMaximumWidth(360)
            side.setStyleSheet("font-family: Consolas, monospace; font-size: 11px;")
            try:
                side.setPlainText(json.dumps(self._canonical_sync_snapshot(), indent=2, default=str))
            except Exception as exc:
                side.setPlainText(str(exc))
            split.addWidget(side)
            try:
                from PyQt6.QtCore import QUrl
                from PyQt6.QtWebEngineWidgets import QWebEngineView
                view = QWebEngineView(dlg)
                view.setUrl(QUrl.fromLocalFile(str(asset.resolve())))
                split.addWidget(view, 1)
            except Exception as web_exc:
                from PyQt6.QtCore import QUrl
                from PyQt6.QtGui import QDesktopServices
                if not QDesktopServices.openUrl(QUrl.fromLocalFile(str(asset.resolve()))):
                    raise RuntimeError(f"Qt WebEngine is unavailable ({web_exc}); no external browser accepted the local asset")
                return
            layout.addLayout(split, 1)
            refresh = QPushButton("Refresh canonical identity")
            refresh.clicked.connect(lambda: side.setPlainText(json.dumps(self._canonical_sync_snapshot(), indent=2, default=str)))
            layout.addWidget(refresh)
            self._musical_explorer_dialog = dlg
            dlg.show()
        except Exception as exc:
            try:
                QMessageBox.warning(self, "Musical Explorer", f"The bundled Explorer could not be opened:\n{exc}")
            except Exception:
                print(f"[Musical Explorer] {exc}")

