    def _canonical_sidechain_amount_for(self, target_name=None):
        """Return the signed, canonically composed sidechain amount in [-1, +1].

        Global amount is the base contribution. A non-inheriting local target
        contributes a signed offset; canonical engines can query this method
        to use the same composition rule for every target.
        """
        state = getattr(self, "sidechain_state", {}) or {}
        global_state = state.get("global", {}) if isinstance(state, dict) else {}
        try:
            global_state = dict(global_state, **{k: v for k, v in self._effective_sidechain_global().items() if k in ("amount", "attack_ms", "release_ms")})
        except Exception:
            pass
        try:
            base = float(global_state.get("amount", 0.0))
        except (TypeError, ValueError):
            base = 0.0
        if not bool(global_state.get("enabled", True)):
            base = 0.0
        targets = state.get("targets", {}) if isinstance(state, dict) else {}
        rec = targets.get(str(target_name), {}) if target_name is not None and isinstance(targets, dict) else {}
        if isinstance(rec, dict) and not bool(rec.get("inherit_global", True)) and bool(rec.get("enabled", True)):
            try:
                base += float(rec.get("amount", 0.0))
            except (TypeError, ValueError):
                pass
        return max(-1.0, min(1.0, base))

    def _open_canonical_sidechain_dialog(self):
        """Edit signed global sidechain contribution and signed local offsets."""
        dlg = QDialog(self)
        dlg.setWindowTitle("Canonical Sidechain Routing")
        dlg.resize(560, 380)
        layout = QVBoxLayout(dlg)
        state = copy.deepcopy(getattr(self, "sidechain_state", {}) or {})
        global_state = state.get("global") if isinstance(state.get("global"), dict) else {}
        amount = QDoubleSpinBox(); amount.setRange(-1.0, 1.0); amount.setDecimals(10); amount.setSingleStep(0.01)
        amount.setPrefix("+")
        _amt0 = float(global_state.get("amount", 0.0))
        amount.setValue(0.0 if abs(_amt0 - 0.1975807343) < 1e-9 else _amt0)   # old untouched default reads as blank
        enabled = QCheckBox("Enable global sidechain contribution")
        enabled.setChecked(bool(global_state.get("enabled", True)))
        source = QComboBox(); source.addItems(["master", "playlist", "kick", "selected instrument"])
        source.setCurrentText(str(global_state.get("source", "master")))
        target = QComboBox(); target.addItem("Global default / inherit", "__global__")
        names = sorted(set((getattr(self, "instrument_sequencer_memory", {}) or {}).keys()) | set((getattr(self, "instrument_sequence_banks", {}) or {}).keys()))
        for name in names: target.addItem(str(name), str(name))
        local_amount = QDoubleSpinBox(); local_amount.setRange(-1.0, 1.0); local_amount.setDecimals(10); local_amount.setSingleStep(0.01)
        local_amount.setPrefix("+")
        local_amount.setValue(0.0)
        inherit = QCheckBox("Selected target inherits global amount (no local offset)")
        inherit.setChecked(True)
        targets = state.get("targets") if isinstance(state.get("targets"), dict) else {}
        def _target_changed(_index=None):
            key = target.currentData()
            rec = targets.get(key, {}) if isinstance(targets.get(key, {}), dict) else {}
            is_global = key == "__global__"
            inherit.setEnabled(not is_global)
            local_amount.setEnabled(not is_global and not inherit.isChecked())
            inherit.setChecked(bool(rec.get("inherit_global", True)) if not is_global else True)
            local_amount.setValue(float(rec.get("amount", 0.0)))
            local_amount.setEnabled(not is_global and not inherit.isChecked())
        target.currentIndexChanged.connect(_target_changed)
        inherit.toggled.connect(lambda checked: local_amount.setEnabled(target.currentData() != "__global__" and not checked))
        form = QFormLayout()
        form.addRow(enabled); form.addRow("Global signed contribution (−1.0 to +1.0)", amount); form.addRow("Sidechain source", source)
        form.addRow("Local instrument / sequencer", target); form.addRow(inherit); form.addRow("Local signed offset (−1.0 to +1.0)", local_amount)
        layout.addLayout(form)
        preview = QLabel("Effective amount = global contribution + local offset, clamped to −1.0…+1.0. Negative values invert the signed contribution; canonical engines should query _canonical_sidechain_amount_for(target).")
        preview.setWordWrap(True); layout.addWidget(preview)
        note = QLabel("These values are canonical project parameters. Audible processing still depends on the active render engine implementing the selected source/target route.")
        note.setWordWrap(True); layout.addWidget(note)
        buttons = QDialogButtonBox(QDialogButtonBox.StandardButton.Save | QDialogButtonBox.StandardButton.Cancel)
        buttons.accepted.connect(dlg.accept); buttons.rejected.connect(dlg.reject); layout.addWidget(buttons)
        _target_changed()
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        state["schema"] = 1
        state["default_amount"] = 0.0
        state["global"] = {"enabled": enabled.isChecked(), "amount": float(amount.value()), "source": str(source.currentText()),
                            "attack_ms": float(global_state.get("attack_ms", 5.0)), "release_ms": float(global_state.get("release_ms", 120.0))}
        key = target.currentData()
        if key and key != "__global__":
            if inherit.isChecked():
                targets.pop(str(key), None)
            else:
                targets[str(key)] = {"enabled": True, "inherit_global": False, "amount": float(local_amount.value()),
                                     "source": str(source.currentText()), "attack_ms": 5.0, "release_ms": 120.0}
        state["targets"] = targets
        state["inherit_global"] = True
        # Persist canonical effective values as a convenience for engines that
        # consume project snapshots, while keeping base/offset as source of truth.
        state["effective_amounts"] = {str(name): max(-1.0, min(1.0, float(state["global"]["amount"]) + (0.0 if not isinstance(rec, dict) or rec.get("inherit_global", True) or not rec.get("enabled", True) else float(rec.get("amount", 0.0)))))
                                       for name, rec in targets.items()}
        self.sidechain_state = state
        self.userdata_protection = copy.deepcopy(getattr(self, "userdata_protection", {}) or {})
        self.userdata_protection.setdefault("schema", 1)
        self.userdata_protection.setdefault("playlist_math_writer", {"layer": "userdata", "protect_from_canonical_overwrite": True})
        try: self._sync_project_state()
        except Exception: pass
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("Signed global/local sidechain contributions saved; canonical composition is global + local offset.")

