    def _memory_ok(self, needed_bytes, label, parent=None):
        """Warn and return False if this action would risk an OOM crash.
        The warning is non-modal; Escape / Back returns to this window."""
        try:
            from memory_guard import warn_if_unsafe
            return not warn_if_unsafe(int(needed_bytes), label=label, parent=parent or self, host=self)
        except Exception:
            return True

    def _install_memory_watchdog(self):
        """Longitudinal check: warn before a long session runs out of RAM."""
        if getattr(self, "_mem_watch", None) is not None:
            return
        self._mem_watch = QTimer(self)
        self._mem_watch.setInterval(15000)
        def _tick():
            try:
                from memory_guard import runtime_pressure, warn_if_unsafe
                msg = runtime_pressure()
                if msg and not getattr(self, "_mem_warned", False):
                    self._mem_warned = True
                    from memory_guard import show_memory_notice      # MEMORY_NOTICE_R31: one reusable popup
                    show_memory_notice("Low memory", msg, host=self)
                elif not msg:
                    self._mem_warned = False
            except Exception:
                pass
        self._mem_watch.timeout.connect(_tick)
        self._mem_watch.start()

    def open_extra_window(self, kind):
        """＋ New window: another Performance / Player / Live Player with its own window-bar tab.

        The primary instances stay the ones the rest of the app talks to (audio routing,
        key hits); extras are independent stations, e.g. several players scanning media.
        """
        extras = self.__dict__.setdefault("_extra_windows", [])
        alive = []
        for w in extras:
            try:
                w.isVisible()
                alive.append(w)
            except RuntimeError:
                pass
        extras[:] = alive
        n = 2 + sum(1 for w in extras if getattr(w, "_gb_extra_kind", "") == kind)
        try:
            from memory_guard import estimate_window_bytes
            if not self._memory_ok(estimate_window_bytes(kind), f"open {kind} window"):
                return None
            if kind == "performance":
                from performance import Performance
                w = Performance(self, parent=None)
                w.setWindowFlags(Qt.WindowType.Window | Qt.WindowType.WindowTitleHint | Qt.WindowType.WindowSystemMenuHint
                                 | Qt.WindowType.WindowMinMaxButtonsHint | Qt.WindowType.WindowCloseButtonHint)
                w.setModal(False)
            elif kind == "player":
                from performance import MediaPlayerWindow
                perf = getattr(self, "_performance_panel", None)
                try:
                    perf.isVisible()
                except Exception:
                    perf = None
                if perf is None:
                    perf = self._open_performance()
                    perf.hide()
                items = list(getattr(perf, "_playlist", []) or [])
                w = MediaPlayerWindow(perf, items, 0)
                w.setModal(False)
            elif kind == "live_player":
                from live_player import LivePlayerWindow
                w = LivePlayerWindow(self)
            else:
                return None
            w.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, False)
            w._gb_extra_kind = kind
            w.setWindowTitle(f"#{n} {w.windowTitle() or kind.replace('_', ' ').title()}")   # number first: the bar truncates titles
            extras.append(w)
            w.show(); w.raise_(); w.activateWindow()
            return w
        except Exception as exc:
            print(f"[Windows] new {kind} window failed: {exc}")
            return None

    def _open_performance(self):
        """Open or re-open Performance as an independent top-level window.
        MEMORY_SAFE_20261106: refuse if opening it would risk an OOM.

        Performance must never participate in the main-window dock layout.
        Using a top-level window prevents opening/closing Performance from
        changing the central widget width, frame thickness, splitter sizes,
        or any other main-window geometry.
        """
        try:
            from memory_guard import estimate_window_bytes
            if not self._memory_ok(estimate_window_bytes("performance"), "open Performance"):
                return None
            panel = getattr(self, "_performance_panel", None)

            if panel is not None:
                try:
                    # Match the Performance window to the current main-window
                    # size and screen position every time it is opened.
                    try:
                        panel.setGeometry(self.geometry())
                    except Exception:
                        try:
                            panel.resize(self.size())
                            panel.move(self.pos())
                        except Exception:
                            pass

                    if panel.isMinimized():
                        panel.showNormal()
                    else:
                        panel.setWindowState(panel.windowState() & ~Qt.WindowState.WindowMinimized)
                    panel.show()
                    try:
                        if hasattr(panel, "resume_after_show"):
                            panel.resume_after_show()
                    except Exception:
                        pass
                    panel.raise_()
                    try:
                        panel.activateWindow()
                    except Exception:
                        pass
                    return panel
                except RuntimeError:
                    self._performance_panel = None
                    panel = None

            from performance import Performance

            panel = Performance(self, parent=None)

            # Independent application window: do NOT add to QMainWindow docks.
            panel.setWindowFlags(
                Qt.WindowType.Window
                | Qt.WindowType.WindowTitleHint
                | Qt.WindowType.WindowSystemMenuHint
                | Qt.WindowType.WindowMinMaxButtonsHint
                | Qt.WindowType.WindowCloseButtonHint
            )
            panel.setModal(False)
            panel.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, False)

            self._performance_panel = panel
            self._performance_dock = None

            def _performance_destroyed(*_):
                self._performance_panel = None
                self._performance_dock = None

            try:
                panel.destroyed.connect(_performance_destroyed)
            except Exception:
                pass

            # R28.4: fit Performance to usable screen geometry rather than
            # allowing the OS panel/window-manager strip to overlap it.
            try:
                _screen = self.screen() or QApplication.primaryScreen()
                panel.setGeometry(_screen.availableGeometry() if _screen is not None else self.geometry())
            except Exception:
                try:
                    panel.resize(self.size())
                    panel.move(self.pos())
                except Exception:
                    pass

            # Closing Performance hides/reuses it without touching any
            # main-window splitter/dock state.
            try:
                old_close = panel.closeEvent

                def _perf_close(event, _panel=panel, _old=old_close):
                    # Hide/reuse instead of deleting, but suspend hidden timers,
                    # capture handles and Performance-owned background services first.
                    try:
                        if hasattr(_panel, "suspend_for_hide"):
                            _panel.suspend_for_hide()
                        _panel.hide()
                        event.ignore()
                        return
                    except Exception:
                        pass

                    try:
                        _old(event)
                    except Exception:
                        event.accept()

                panel.closeEvent = _perf_close
            except Exception:
                pass

            panel.show()
            try:
                if hasattr(panel, "resume_after_show"):
                    panel.resume_after_show()
            except Exception:
                pass
            panel.raise_()
            try:
                panel.activateWindow()
            except Exception:
                pass

            return panel

        except Exception as e:
            # PERFORMANCE_OPEN_DIAG_20261102: keep the full traceback (an error text like "-3" alone says nothing).
            import traceback as _tb
            _trace = _tb.format_exc()
            print("[Performance] open failed:\n" + _trace, flush=True)
            _logp = ""
            try:
                _logp = os.path.join(str(self._exports_dir()), "performance_open_error.log")
                with open(_logp, "w", encoding="utf-8") as _f:
                    _f.write(_trace)
            except Exception:
                _logp = ""
            QMessageBox.warning(
                self,
                "Performance",
                f"Could not open Performance:\n{type(e).__name__}: {e}\n\n"
                + (f"Full details were saved to:\n{_logp}" if _logp else "Full details were printed to the console.")
                + "\n\nLast lines:\n" + "\n".join(_trace.strip().splitlines()[-6:]),
            )
            return None

    def _restore_windows_after_crash(self):
        """Bring the main window and Performance back after a relaunch."""
        try:
            self.show()
            self.raise_()
            self.activateWindow()
        except Exception:
            pass
        try:
            self._open_performance()
        except Exception:
            pass
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("Relaunched after a crash. Windows restored.")

