    # ----------------------------------------------------------------------
    # PROJECT_UNDO_2026 — full-project snapshot history
    # ----------------------------------------------------------------------
    def _project_history_media_samples(self):
        """Small, JSON-safe operator-media history records (never PCM/frame buffers)."""
        out = {}
        for name, rec in (getattr(self, "instrument_media_samples", {}) or {}).items():
            if not isinstance(rec, dict):
                continue
            out[str(name)] = {
                "path": str(rec.get("path", "") or ""),
                "sample_rate": int(rec.get("sample_rate", 44100) or 44100),
                "user_owned": bool(rec.get("user_owned", True)),
                "source_kind": str(rec.get("source_kind", "audio") or "audio"),
                "video_path": str(rec.get("video_path", "") or ""),
                "video_input_enabled": bool(rec.get("video_input_enabled", False)),
                "layered_state": copy.deepcopy(rec.get("layered_state", {})) if isinstance(rec.get("layered_state"), dict) else {},
                "binding_mode": str(rec.get("binding_mode", "") or ""),
                "binding_source": str(rec.get("binding_source", "") or ""),
                "bound_layers_state": copy.deepcopy(rec.get("bound_layers_state", {})) if isinstance(rec.get("bound_layers_state"), dict) else {},
                "audio_present": bool(rec.get("audio_present", True)),
            }
        return out

    def _restore_project_history_media_samples(self, saved):
        """Restore media metadata cheaply; only decode when the referenced path changed."""
        saved = saved if isinstance(saved, dict) else {}
        current = getattr(self, "instrument_media_samples", {}) or {}
        rebuilt = {}
        for name, rec in saved.items():
            if not isinstance(rec, dict):
                continue
            path = str(rec.get("path", "") or "")
            old = current.get(name) if isinstance(current.get(name), dict) else None
            if old is not None and str(old.get("path", "") or "") == path:
                item = copy.deepcopy(old)
                # Preserve derived waveform bytes while restoring authoritative metadata.
                for k, v in rec.items():
                    item[k] = copy.deepcopy(v)
                rebuilt[str(name)] = item
                continue
            arr = np.zeros(1, dtype=np.float32)
            sr = int(rec.get("sample_rate", 44100) or 44100)
            if path and os.path.isfile(path):
                try:
                    arr, sr = self._decode_media_audio(path)
                except Exception:
                    pass
            item = copy.deepcopy(rec)
            item["waveform"] = arr if getattr(arr, "size", 0) else np.zeros(1, dtype=np.float32)
            item["sample_rate"] = int(sr)
            rebuilt[str(name)] = item
        self.instrument_media_samples = rebuilt
        try:
            self._refresh_operator_sample_ui()
        except Exception:
            pass

    def _project_history_snapshot(self):
        """Authoritative deep snapshot of everything undo/redo must preserve.

        All project data is captured BEFORE mutation.  instrument_sequencer_memory,
        instrument_sequence_banks and instrument_selected_sequence are re-projected
        on restore via _ensure_sequence_banks_after_resize() so their alias
        relationship (live memory == banks[name][selected]) is preserved exactly
        the way the app itself maintains it.
        """
        import copy as _c
        snap = {}
        for key in (
            "master_playlist_data",
            "playlist_automation",
            "_playlist_overflow_rows",
            "instrument_sequence_banks",
            "instrument_selected_sequence",
            "instrument_sequencer_memory",
            "instrument_names_48",
            "instrument_scripts",
            "instrument_param_state",
            "patch_connections",
            "global_algo_state",
            "goava_note_events",
            "goava_steps",
            "goava_pitches",
            "goava_frequencies",
            "goava_raw_values",
            "goava_seed_values",
            "composition_toggle_state",
            "_user_composition_snapshot",
            # SEQ_RANDOMIZER_RESET_V41: sequence randomizer mutates automation
            # references and selection state as well as sequence banks. Capture
            # those so OFF restores the exact pre-randomized state even after
            # the randomized sequence was manually edited.
            "sequencer_automation_points",
            "sequencer_automation_enabled",
            "automator_timing_mode",
            "_selected_automation_step",
            # PROJECT_STATE_INTEGRATION_20260909: state added by recent media,
            # graph, Performance, canonical, modulation and game work. These are
            # lightweight authoritative values/caches, never live device objects.
            "automation_patterns",
            "master_vector_state",
            "wavetable_projector_state",
            "sample_morph_state",
            "global_mod_state",
            "algorithm_xmod_local",
            "algorithm_xmod_global",
            "media_carrier_slot",
            "carrier_binding_mode",
            "carrier_binding_source",
            "carrier_bound_layers_state",
            "live_dj_random_script",
            "_live_dj_random_generation",
            "canonical_continuation_enabled",
            "canonical_continuation_mode",
            "canonical_resonance_factor",
            "canonical_resonance_handoff",
            "meum_spatial_resolution_enabled",
            "meum_spatial_activity_modulus",
            "_canonical_user_blend_ledger",
            "_canonical_activity_ledger",
            "_last_videogame_identity",
            "_last_videogame_path",
            "canonical_engine_levels", "phase_lock_characteristics", "_rand_instance_seed", "_rand_generation_counter",
            "imported_3d_model_path", "imported_3d_model_meta", "voxel_grid_size", "voxel_alias_pct", "voxel_paint_color", "voxel_paint_blend_pct", "voxel_cells",
        ):
            try:
                snap[key] = _c.deepcopy(getattr(self, key, None))
            except Exception:
                snap[key] = None
        try:
            snap["seed_text"] = self._seed_text() if hasattr(self, "_seed_text") else ""
        except Exception:
            snap["seed_text"] = ""
        try:
            snap["domain_eq_domains"] = _c.deepcopy(
                (getattr(self, "domain_eq_engine", None).domains
                 if getattr(self, "domain_eq_engine", None) is not None else []) or []
            )
        except Exception:
            snap["domain_eq_domains"] = []
        # Save/Load parity fields that live behind UI/workbench adapters.
        # They are captured here without raw media buffers, device handles or
        # render caches, keeping history cheap enough for normal interaction.
        try:
            snap["ui_state"] = _c.deepcopy(self._collect_project_ui_state())
        except Exception:
            snap["ui_state"] = {}
        try:
            snap["media_workbench_state"] = _c.deepcopy(self._collect_media_workbench_state())
        except Exception:
            snap["media_workbench_state"] = _c.deepcopy(getattr(self, "media_workbench_state", {}) or {})
        try:
            snap["instrument_media_samples_state"] = self._project_history_media_samples()
        except Exception:
            snap["instrument_media_samples_state"] = {}
        try:
            snap["media_carrier_state"] = {
                "wav_path": str(getattr(self, "imported_wav_path", "") or ""),
                "video_path": str(getattr(self, "imported_video_path", "") or ""),
                "sample_rate": int(getattr(self, "imported_sample_rate", 44100) or 44100),
                "video_meta": _c.deepcopy(getattr(self, "imported_video_meta", {}) or {}),
                "binding_mode": str(getattr(self, "carrier_binding_mode", "") or ""),
                "binding_source": str(getattr(self, "carrier_binding_source", "") or ""),
                "bound_layers_state": _c.deepcopy(getattr(self, "carrier_bound_layers_state", {}) or {}),
            }
        except Exception:
            snap["media_carrier_state"] = {}
        try:
            snap["visual_view_state"] = _c.deepcopy(self.video_synth_engine.get_camera_state()) if getattr(self, "video_synth_engine", None) is not None else {}
        except Exception:
            snap["visual_view_state"] = {}
        try:
            snap["project_notes"] = self.qe_notes.toPlainText() if getattr(self, "qe_notes", None) is not None else ""
        except Exception:
            snap["project_notes"] = ""

        try:
            snap["instrument_name"] = self.qe_instrument.text() if getattr(self, "qe_instrument", None) is not None else ""
        except Exception:
            snap["instrument_name"] = ""
        snap["instrument_display_names"] = self._sanitized_instrument_display_names(
            getattr(self, "instrument_display_names", {})
        )

        btn_state = {}
        for attr in (
            "btn_goava", "btn_local_randomize", "btn_local_phase_lock",
            "btn_idealize_rhythm", "btn_seeded_randomize", "btn_fractal_seed_mode",
            "btn_apply_algo_master", "chk_user_program_only",
            "chk_canonical_protect", "btn_meum_engine_simplify", "btn_trigonometry_engine", "btn_operator_theory", "btn_math_symbols", "btn_hyperdrive", "chk_fullweight_seed", "chk_full_unison",
            "btn_auto_randomize_sequence", "btn_auto_randomize_everywhere", "chk_seed_ws_override_off",
        ):
            try:
                w = getattr(self, attr, None)
                if w is not None:
                    btn_state[attr] = bool(w.isChecked())
            except Exception:
                pass
        snap["btn_state"] = btn_state
        return snap

    def _project_history_restore(self, snap):
        """Restore a captured snapshot; never re-enters undo itself."""
        import copy as _c
        # Restore every authoritative project key (identical list as the
        # snapshot).  The old "restore_like_sets" placeholder loop never had a
        # producer and silently dropped ALL data — undo/redo now actually works.
        for key in (
            "master_playlist_data",
            "playlist_automation",
            "_playlist_overflow_rows",
            "instrument_sequence_banks",
            "instrument_selected_sequence",
            "instrument_sequencer_memory",
            "instrument_names_48",
            "instrument_scripts",
            "instrument_param_state",
            "patch_connections",
            "global_algo_state",
            "goava_note_events",
            "goava_steps",
            "goava_pitches",
            "goava_frequencies",
            "goava_raw_values",
            "goava_seed_values",
            "composition_toggle_state",
            "_user_composition_snapshot",
            # SEQ_RANDOMIZER_RESET_V41: sequence randomizer mutates automation
            # references and selection state as well as sequence banks. Capture
            # those so OFF restores the exact pre-randomized state even after
            # the randomized sequence was manually edited.
            "sequencer_automation_points",
            "sequencer_automation_enabled",
            "automator_timing_mode",
            "_selected_automation_step",
            "canonical_engine_levels", "phase_lock_characteristics", "_rand_instance_seed", "_rand_generation_counter",
            "imported_3d_model_path", "imported_3d_model_meta", "voxel_grid_size", "voxel_alias_pct", "voxel_paint_color", "voxel_paint_blend_pct", "voxel_cells",
        ):
            if key in snap:
                try:
                    setattr(self, key, _c.deepcopy(snap[key]))
                except Exception:
                    pass
        try: self._sync_canonical_widgets_from_state()
        except Exception: pass
        try:
            if "instrument_display_names" in snap:
                self._apply_loaded_instrument_display_names(snap.get("instrument_display_names"))
        except Exception:
            pass
        # Domain engine list is stored separately (engine is a singleton object).
        try:
            dom = _c.deepcopy(snap.get("domain_eq_domains") or [])
            if getattr(self, "domain_eq_engine", None) is not None:
                self.domain_eq_engine.domains = dom
        except Exception:
            pass
        # Restore adapters shared with normal project Save/Load.  These calls
        # intentionally happen before repaint/rebuild so consumers see one state.
        try:
            if isinstance(snap.get("ui_state"), dict):
                self._restore_project_ui_state(_c.deepcopy(snap["ui_state"]))
        except Exception:
            pass
        try:
            self._restore_media_workbench_state(_c.deepcopy(snap.get("media_workbench_state", {})))
        except Exception:
            pass
        try:
            self._restore_project_history_media_samples(_c.deepcopy(snap.get("instrument_media_samples_state", {})))
        except Exception:
            pass
        try:
            mc = _c.deepcopy(snap.get("media_carrier_state", {}))
            if isinstance(mc, dict):
                self._clear_global_carrier_state(refresh=False, update_ui=True)
                self.carrier_binding_mode = str(mc.get("binding_mode") or "")
                self.carrier_binding_source = str(mc.get("binding_source") or "")
                self.carrier_bound_layers_state = _c.deepcopy(mc.get("bound_layers_state", {})) if isinstance(mc.get("bound_layers_state"), dict) else {}
                vid_p = str(mc.get("video_path") or "")
                wav_p = str(mc.get("wav_path") or "")
                if vid_p and os.path.isfile(vid_p):
                    self._load_video_path(vid_p)
                elif wav_p and os.path.isfile(wav_p):
                    self._load_wav_path(wav_p)
                else:
                    self._refresh_after_file_input(reason="undo_carrier_restore")
        except Exception:
            pass
        try:
            if getattr(self, "qe_notes", None) is not None and "project_notes" in snap:
                self.qe_notes.blockSignals(True)
                self.qe_notes.setPlainText(str(snap.get("project_notes") or ""))
                self.qe_notes.blockSignals(False)
        except Exception:
            pass
        try:
            if hasattr(self, "_apply_visual_view_state"):
                self._apply_visual_view_state(_c.deepcopy(snap.get("visual_view_state", {})))
        except Exception:
            pass

        # Seed field (user-controlled; block so no spurious recomposition).
        try:
            if hasattr(self, "input_seed_val") and self.input_seed_val is not None:
                self.input_seed_val.blockSignals(True)
                self.input_seed_val.setPlainText(str(snap.get("seed_text") or ""))
                self.input_seed_val.blockSignals(False)
        except Exception:
            pass
        # Engine toggle buttons (block so no side-effect churn).
        for attr, checked in (snap.get("btn_state") or {}).items():
            try:
                w = getattr(self, attr, None)
                if w is not None:
                    w.blockSignals(True)
                    w.setChecked(bool(checked))
                    w.blockSignals(False)
            except Exception:
                pass
        if "chk_seed_ws_override_off" in (snap.get("btn_state") or {}):
            globals()["SEED_WORKSPACE_OVERRIDE"] = not bool(snap["btn_state"]["chk_seed_ws_override_off"])
        # Re-project live memory from banks (+ selected) for alias fidelity.
        if hasattr(self, "_ensure_sequence_banks_after_resize"):
            try:
                self._ensure_sequence_banks_after_resize()
            except Exception:
                pass
        # SEQ_RANDOMIZER_RESET_V41: restore the automation model and selected
        # sequence before repainting, so the sequence-toggle OFF path cannot
        # leave randomized references behind.
        try:
            if hasattr(self, "_refresh_sequencer_automation_row"):
                self._refresh_sequencer_automation_row()
            if hasattr(self, "_refresh_sequence_selector"):
                self._refresh_sequence_selector()
        except Exception:
            pass
        # Refresh every dependent surface without mutating data.
        try:
            if hasattr(self, "_resize_playlist_memory"):
                self._resize_playlist_memory(len(getattr(self, "_render_playlist_snapshot", None) or getattr(self, "master_playlist_data", []) or []))
        except Exception:
            pass
        try:
            if hasattr(self, "_refresh_sequence_dependent_panels"):
                self._refresh_sequence_dependent_panels()
        except Exception:
            pass
        try:
            if hasattr(self, "_refresh_step_ui"):
                self._refresh_step_ui()
        except Exception:
            pass
        try:
            if hasattr(self, "_rebuild_active_canonical_playlist"):
                self._rebuild_active_canonical_playlist("undo_restore")
        except Exception:
            pass
        try:
            self._on_live_source_changed()
        except Exception:
            pass
        try:
            self._refresh_canonical_fingerprint()
        except Exception:
            pass
        try:
            panel = getattr(self, "_main_voxel_panel", None)
            if panel is not None:
                panel.grid_spin.blockSignals(True); panel.grid_spin.setValue(int(getattr(self,"voxel_grid_size",16) or 16)); panel.grid_spin.blockSignals(False)
                panel.z_spin.setRange(0, max(0, panel.grid_spin.value()-1))
                panel.alias_slider.blockSignals(True); panel.alias_slider.setValue(int(getattr(self,"voxel_alias_pct",0) or 0)); panel.alias_slider.blockSignals(False)
                panel.alias_label.setText(f"{int(getattr(self,'voxel_alias_pct',0) or 0)}%")
                panel.blend_slider.blockSignals(True); panel.blend_slider.setValue(int(getattr(self,"voxel_paint_blend_pct",86) or 86)); panel.blend_slider.blockSignals(False)
                panel.blend_label.setText(f"{int(getattr(self,'voxel_paint_blend_pct',86) or 86)}%")
                panel._sync_color_button(); panel.refresh_views()
        except Exception:
            pass

    def _clear_written_playlist(self):
        """Clear every written playlist row + automation; active canonicals rewrite it.

        GROOVEBOX_R23R_CLEAR_PLAYLIST_20261031. Undo-able. User ownership marks on
        the rows are cleared too, so canonical engines (when active) may write the
        whole playlist again on the next canonical transaction.
        """
        try:
            ans = QMessageBox.question(self, "Clear Playlist",
                                       "Clear every written playlist row and its automation?\n\n"
                                       "Undo restores it. If canonical engines are active they will write a fresh playlist.")
            if ans != QMessageBox.StandardButton.Yes:
                return
        except Exception:
            return
        try:
            self._push_undo("clear playlist")
        except Exception:
            pass
        rows = max(1, len(getattr(self, "master_playlist_data", []) or []) or
                   (int(self.spin_playlist_length.value()) if hasattr(self, "spin_playlist_length") else DEFAULT_PLAYLIST_ROWS))
        self.master_playlist_data = [{} for _ in range(rows)]
        self.playlist_automation = [{} for _ in range(rows)]
        self._playlist_cleared_hold = True
        table = getattr(self, "active_paint_table", None)
        if table is not None:
            try:
                table.clearContents()
                table.playlist_user_touched = set()
            except Exception:
                pass
        for attr in ("update_playlist_display", "_refresh_playlist_ui"):
            fn = getattr(self, attr, None)
            if callable(fn):
                try:
                    fn()
                except Exception:
                    pass
                break
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("🧹 Playlist cleared" + (" · canonical engines rewriting" if self._get_active_engine_set() else ""))
        self._on_live_source_changed()

    def _push_undo(self, label="edit"):
        """Snapshot current project state onto the undo stack (clears redo).

        Never captures snapshots while an undo/redo restore is in flight, which
        would otherwise dirty the opposite stack with the restored state.
        """
        if getattr(self, "_undo_in_flight", False):
            return
        self._redo_stack.clear()
        self._undo_stack.append((str(label), self._project_history_snapshot()))
        if len(self._undo_stack) > self._undo_max:
            self._undo_stack.pop(0)
        self._sync_undo_buttons()

    def _do_undo(self):
        if not self._undo_stack:
            return False
        self._undo_in_flight = True
        try:
            prior = self._project_history_snapshot()
            label, snap = self._undo_stack.pop()
            self._project_history_restore(snap)
            self._redo_stack.append((str(label) + " (redo)", prior))
            if len(self._redo_stack) > self._undo_max:
                self._redo_stack.pop(0)
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(f"↩ Undo: {label}")
            return True
        finally:
            self._undo_in_flight = False
            self._sync_undo_buttons()

    def _do_redo(self):
        if not self._redo_stack:
            return False
        self._undo_in_flight = True
        try:
            # Redo mirrors Undo: capture the state we are leaving, restore the
            # redo target, then put the pre-redo state on Undo.  Storing `snap`
            # itself here made a subsequent Undo restore the already-redone state.
            prior = self._project_history_snapshot()
            label, snap = self._redo_stack.pop()
            self._project_history_restore(snap)
            clean_label = str(label).replace(" (redo)", "")
            self._undo_stack.append((clean_label, prior))
            if len(self._undo_stack) > self._undo_max:
                self._undo_stack.pop(0)
            if hasattr(self, "scope_status_label"):
                self.scope_status_label.setText(f"↪ Redo: {clean_label}")
            return True
        finally:
            self._undo_in_flight = False
            self._sync_undo_buttons()

    def _sync_undo_buttons(self):
        try:
            for attr, enabled in (
                ("btn_undo", bool(self._undo_stack)),
                ("btn_redo", bool(self._redo_stack)),
            ):
                w = getattr(self, attr, None)
                if w is not None:
                    w.setEnabled(enabled)
        except Exception:
            pass

    def _push_seed_history(self, text):
        """Record a prior seed-field value so Algorithm→Seed (and friends) revert."""
        try:
            prior = self._seed_text() if hasattr(self, "_seed_text") else ""
        except Exception:
            prior = ""
        if prior != str(text or ""):
            self._seed_history.append(str(prior))
            if len(self._seed_history) > 32:
                self._seed_history.pop(0)

    def _revert_seed_to_history(self):
        """Revert the seed field to the last pre-Algorithm→Seed value."""
        if not self._seed_history:
            return False
        prior = self._seed_history.pop()
        self._push_undo("Revert seed")
        try:
            if hasattr(self, "input_seed_val") and self.input_seed_val is not None:
                self.input_seed_val.blockSignals(True)
                self.input_seed_val.setPlainText(prior)
                self.input_seed_val.blockSignals(False)
        except Exception:
            pass
        try:
            self._on_live_source_changed()
        except Exception:
            pass
        try:
            self._refresh_canonical_fingerprint()
        except Exception:
            pass
        if hasattr(self, "scope_status_label"):
            self.scope_status_label.setText("↩ Seed reverted")
        return True

    def _is_local_context(self):
        """Authoritative GLOBAL/LOCAL selector: index 1 is selected-instrument context."""
        try:
            return bool(self.mode_combo.currentIndex() == 1)
        except Exception:
            return False

    def _on_context_scope_changed(self, _idx=None):
        """Make every local editor follow the visible GLOBAL/LOCAL dropdown.

        In LOCAL CONTEXT the active instrument dropdown is authoritative, including
        the Automator destination selector. This prevents the first roster entry
        (Z-Pinch Resonator) from leaking into unrelated automation lanes.
        """
        if self._is_local_context():
            try:
                selected = str(self.instrument_selector_dropdown.currentText())
                if selected and hasattr(self, "auto_to_instrument"):
                    idx = self.auto_to_instrument.findText(selected)
                    if idx >= 0:
                        self.auto_to_instrument.blockSignals(True)
                        self.auto_to_instrument.setCurrentIndex(idx)
                        self.auto_to_instrument.blockSignals(False)
            except Exception:
                pass
        try:
            self._refresh_operator_sample_ui()
        except Exception:
            pass

    def _apply_canonical_sample_mimic(self, instrument_name, waveform, sample_rate):
        """Derive morph / harmonic_freq / chaos / fold_depth / harmonic_lattice from a sample.

        Deterministic: same waveform + rate always yields the same macros.  The
        values are written into instrument_param_state and the canonical macro
        user store so Panel Synth Clones, randomizers, and playlist cells stay
        interlinked.  This is the 'instrument → file → contextual mimic' path.
        """
        a = np.asarray(waveform, dtype=np.float32).ravel()
        if a.size < 32:
            return
        sr = max(1, int(sample_rate))
        # Peak-normalized analysis window (up to ~1 s)
        n = min(a.size, sr)
        seg = a[:n].astype(np.float64)
        peak = float(np.max(np.abs(seg)) or 1.0)
        seg = seg / peak
        # Spectral centroid via rFFT magnitude
        spec = np.abs(np.fft.rfft(seg * np.hanning(seg.size)))
        freqs = np.fft.rfftfreq(seg.size, d=1.0 / sr)
        power = spec * spec
        psum = float(np.sum(power) or 1.0)
        centroid = float(np.sum(freqs * power) / psum)
        # Spectral flatness (geometric / arithmetic mean) → chaos proxy
        log_spec = np.log(np.maximum(spec, 1e-12))
        flatness = float(np.exp(np.mean(log_spec)) / (np.mean(spec) + 1e-12))
        flatness = max(0.0, min(1.0, flatness))
        # Zero-crossing rate → fold / lattice
        zc = float(np.mean(np.abs(np.diff(np.signbit(seg)).astype(np.float64))))
        # RMS energy → morph depth
        rms = float(np.sqrt(np.mean(seg * seg)))
        # Map into the five canonical generator ranges
        morph = float(np.clip(0.5 + 4.5 * rms, 0.01, 10.0))
        harmonic_freq = float(np.clip(centroid if centroid > 20.0 else 432.0, 20.0, 20000.0))
        chaos = float(np.clip(flatness, 0.0, 1.0))
        fold_depth = float(np.clip(1.0 + 15.0 * zc, 1.0, 16.0))
        harmonic_lattice = float(np.clip(0.15 + 0.7 * (1.0 - flatness) + 0.15 * rms, 0.0, 1.0))
        macros = {
            "morph": morph,
            "harmonic_freq": harmonic_freq,
            "chaos": chaos,
            "fold_depth": fold_depth,
            "harmonic_lattice": harmonic_lattice,
            "sample_mimic": True,
            "sample_centroid_hz": centroid,
            "sample_flatness": flatness,
            "sample_zcr": zc,
            "sample_rms": rms,
        }
        st = self.instrument_param_state.setdefault(instrument_name, {})
        st.update(macros)
        try:
            store = getattr(self, "_canonical_macro_user_store", None)
            if isinstance(store, dict):
                store.setdefault(instrument_name, {}).update(macros)
        except Exception:
            pass
        # Drive visible main-panel controls when they exist for this instrument
        try:
            for attr, key, scale in (
                ("spin_morph", "morph", 1.0),
                ("spin_harmonic_freq", "harmonic_freq", 1.0),
            ):
                w = getattr(self, attr, None)
                if w is not None and hasattr(w, "setValue"):
                    w.blockSignals(True)
                    w.setValue(float(macros[key]) * scale)
                    w.blockSignals(False)
        except Exception:
            pass
        print(
            f"[Sample Mimic] {instrument_name}: morph={morph:.3f} hf={harmonic_freq:.1f}Hz "
            f"chaos={chaos:.3f} fold={fold_depth:.2f} lattice={harmonic_lattice:.3f}"
        )


    def _mimic_selected_operator_sample(self):
        """Re-run contextual mimic from the sample already attached to the selection."""
        try:
            name = self._current_instrument_name()
            rec = (getattr(self, "instrument_media_samples", {}) or {}).get(name)
            if not rec or rec.get("waveform") is None:
                QMessageBox.information(
                    self, "Morph Synth → Mimic Sample",
                    "Load a sample onto the selected instrument first "
                    "(Load Sample → Selected Operator)."
                )
                return
            arr = np.asarray(rec["waveform"], dtype=np.float32)
            sr = int(rec.get("sample_rate") or 48000)
            self._apply_canonical_sample_mimic(name, arr, sr)
            self._on_live_source_changed()
            QMessageBox.information(
                self, "Sample Mimic",
                f"Canonical macros for «{name}» now track the loaded sample "
                f"(centroid / flatness / ZCR / RMS → five generators)."
            )
        except Exception as exc:
            QMessageBox.warning(self, "Sample Mimic", str(exc))


    def _open_lan_chat(self):
        """Open the existing Nearby Grooveboxes chat from the status bar."""
        try:
            p = self._open_performance_tab("⇄ Drive / Clone")
        except Exception as exc:
            self._set_status_message(f"LAN Chat unavailable: {exc}")
            return None
        if p is None:
            self._set_status_message("LAN Chat is unavailable: Performance did not open")
            return None

        def _focus_chat():
            try:
                if hasattr(p, "_nearby_msg_count"):
                    p._nearby_msg_count = -1
                if hasattr(p, "_refresh_nearby_messages"):
                    p._refresh_nearby_messages()
                target = getattr(p, "txt_nearby_messages", None)
                area = target.parentWidget() if target is not None else None
                while area is not None and not isinstance(area, QScrollArea):
                    area = area.parentWidget()
                if area is not None and target is not None:
                    area.ensureWidgetVisible(target, 20, 20)
                edit = getattr(p, "edit_nearby_message", None)
                if edit is not None:
                    edit.setFocus(Qt.FocusReason.ShortcutFocusReason)
            except Exception as exc:
                self._set_status_message(f"LAN Chat focus failed: {exc}")

        QTimer.singleShot(0, _focus_chat)
        QTimer.singleShot(180, _focus_chat)
        self._set_status_message("LAN Chat · Nearby Grooveboxes · choose a conversation or device")
        return p


    def _record_live_step_event(self, degree, key, pitch_bend=0.0, sample_binding=None):
        """Write one live note into an immutable-copy sequence snapshot.

        Audio/retrigger readers holding the previous dictionary keep using it;
        assigning the completed copy publishes the edit atomically for the next
        scheduler boundary without blocking the callback or stopping playback.
        """
        if not getattr(self, "_live_step_record_enabled", False):
            return False
        target = getattr(self, "_live_step_record_target", None)
        if not target:
            return False
        try:
            name, sid = str(target[0]), int(target[1])
            bank = (getattr(self, "instrument_sequence_banks", {}) or {}).get(name, {})
            base_mem = bank.get(sid)
            if not isinstance(base_mem, dict):
                return False
            length = max(1, int(base_mem.get("pattern_length", len(base_mem.get("steps", [])) or 16)))
            if getattr(self, "is_playing", False):
                playhead = int(getattr(self, "_playhead_step", -1))
                step = (playhead if playhead >= 0 else int(getattr(self, "_live_step_record_cursor", 0))) % length
                # A second key on the same tick is placed in the next cell so
                # rapid live input remains a sequential take, not lost overwrites.
                if step == getattr(self, "_live_step_record_last_step", None):
                    step = (step + 1) % length
            else:
                step = int(getattr(self, "_live_step_record_cursor", 0)) % length
            updated = copy.deepcopy(base_mem)
            self._ensure_seq_mem_length(updated, length)
            updated.setdefault("steps", [False] * length)
            updated.setdefault("gates", [True] * length)
            updated.setdefault("amplitudes", [1.0] * length)
            updated.setdefault("pitches", [1.0] * length)
            self._adopt_canonical_for_edit(updated, name)
            updated["steps"][step] = True
            updated["gates"][step] = True
            updated["amplitudes"][step] = max(float(updated["amplitudes"][step]), 1.0)
            semitones = float(degree) + float(pitch_bend)
            updated["pitches"][step] = float(np.clip(2.0 ** (semitones / 12.0), 1.0 / 32.0, 32.0))
            updated.setdefault("live_step_events", {})
            if not isinstance(updated["live_step_events"], dict): updated["live_step_events"] = {}
            events = list(updated["live_step_events"].get(str(step), []))
            events.append({"key": str(key), "degree": int(degree), "pitch_bend": float(pitch_bend),
                           "sample_binding": copy.deepcopy(sample_binding) if isinstance(sample_binding, dict) else None})
            updated["live_step_events"][str(step)] = events[-8:]
            self._mark_step_touched(updated, step)
            updated["user_owned"] = True
            updated["canonical_owner"] = None
            # Commit both bank and active mirror with one reference swap each.
            bank[sid] = updated
            if getattr(self, "instrument_selected_sequence", {}).get(name, 1) == sid:
                self.instrument_sequencer_memory[name] = updated
                if name == self.instrument_selector_dropdown.currentText():
                    self.active_instrument_memory = updated
            self._live_step_record_last_step = step
            self._live_step_record_cursor = (step + 1) % length
            self._live_step_record_events = int(getattr(self, "_live_step_record_events", 0)) + 1
            try:
                self._gui_refresh("live_step_record", lambda: (self.rebuild_sequencer_steps(length), self._refresh_sequencer_automation_row()))
            except Exception:
                pass
            try: self.arc_seq_view.update_from_host()
            except Exception: pass
            if hasattr(self, "lbl_live_step_record"):
                self.lbl_live_step_record.setText(f"REC {self._live_step_record_events} · STEP {step+1}/{length}")
            return True
        except Exception as exc:
            _gb_log_error("live step record", exc)
            return False


    def _record_parallel_keybind(self, degree, ch, bend=0.0):
        """Record a keybind into its own instrument sequence.

        If the key is bound to an instrument, that instrument's sequence is
        written. Otherwise the selected instrument is used. With single_loop
        every key shares one sequence index; otherwise each instrument opens
        the next free sequence. auto_travel advances the step after the hit.
        """
        bus = self._live_keyboard_link()
        if not bus.get("parallel_record"):
            return False
        try:
            bank = self._key_bank()
            b = bank.binding(ch) if ch else {}
            inst = bank.inst_for(b) if b else ""
            if not inst:
                inst = str(self.instrument_selector_dropdown.currentText())
            if not inst:
                return False
            seq_bank = (getattr(self, "instrument_sequence_banks", {}) or {}).setdefault(inst, {})
            if bus.get("single_loop", True):
                sid = int(bus.get("loop_index", 1))
            else:
                # Next free sequence number for this instrument
                used = [int(k) for k in seq_bank.keys() if str(k).isdigit()]
                sid = (max(used) + 1) if used else 1
                bus["loop_index"] = sid
            mem = seq_bank.get(sid)
            if not isinstance(mem, dict):
                mem = {"pattern_length": 16, "steps": [False]*16, "gates": [True]*16,
                       "amplitudes": [1.0]*16, "pitches": [1.0]*16, "user_owned": True}
                seq_bank[sid] = mem
            length = max(1, int(mem.get("pattern_length", 16)))
            cursor_key = f"_par_cursor_{inst}_{sid}"
            step = int(getattr(self, cursor_key, 0)) % length
            updated = copy.deepcopy(mem)
            self._ensure_seq_mem_length(updated, length)
            updated.setdefault("steps", [False]*length)
            updated.setdefault("gates", [True]*length)
            updated.setdefault("amplitudes", [1.0]*length)
            updated.setdefault("pitches", [1.0]*length)
            updated["steps"][step] = True
            updated["gates"][step] = True
            updated["amplitudes"][step] = float(bus.get("velocity", 1.0))
            semitones = float(degree) + float(bend)
            updated["pitches"][step] = float(np.clip(2.0 ** (semitones / 12.0), 1.0/32.0, 32.0))
            updated.setdefault("live_step_events", {})
            events = list(updated["live_step_events"].get(str(step), []))
            events.append({"key": str(ch), "degree": int(degree), "pitch_bend": float(bend),
                           "inst": inst, "seq": sid})
            updated["live_step_events"][str(step)] = events[-8:]
            updated["user_owned"] = True
            seq_bank[sid] = updated
            if getattr(self, "instrument_selected_sequence", {}).get(inst, 1) == sid:
                self.instrument_sequencer_memory[inst] = updated
            if bus.get("auto_travel", True):
                setattr(self, cursor_key, (step + 1) % length)
            if bus.get("write_playlist", True):
                self._write_live_playlist_row(inst, degree, ch, bend, sid)
            try:
                self.scope_status_label.setText(f"⏺ {inst[:16]} · seq {sid} · step {step+1}/{length}")
            except Exception:
                pass
            return True
        except Exception as exc:
            try:
                _gb_log_error("parallel keybind record", exc)
            except Exception:
                pass
            return False

    def _write_live_playlist_row(self, inst, degree, ch, bend=0.0, sid=1):
        """Append one playlist row as if the key was played live.

        Deferred so the UI thread is not blocked by a refresh that can wait.
        """
        def _do():
            try:
                rows = getattr(self, "master_playlist_data", None)
                if not isinstance(rows, list):
                    self.master_playlist_data = rows = []
                row = {
                    "instrument": str(inst),
                    "from_instrument": str(inst),
                    "degree": int(degree),
                    "key": str(ch),
                    "pitch_bend": float(bend),
                    "sequence": int(sid),
                    "live": True,
                    "user_owned": True,
                    "write_mode": "step",
                    "active": True,
                }
                rows.append(row)
                # Light refresh only; full rebuild is deferred and coalesced.
                if hasattr(self, "update_playlist_display"):
                    self.update_playlist_display()
            except Exception:
                pass
        try:
            QTimer.singleShot(0, _do)
        except Exception:
            _do()

    def _toggle_live_step_record(self, checked):
        """Arm a sequence-local live note recorder without stopping the transport."""
        self._live_step_record_enabled = bool(checked)
        if checked:
            try:
                name = str(self.instrument_selector_dropdown.currentText())
                sid = int(self._current_sequence_index(name))
                mem = self._current_sequence_mem(name)
                length = max(1, int(mem.get("pattern_length", len(mem.get("steps", [])) or 16)))
                playhead = int(getattr(self, "_playhead_step", -1))
                start = playhead if getattr(self, "is_playing", False) and playhead >= 0 else (int(getattr(self, "selected_step_idx", -1)) if getattr(self, "selected_step_idx", None) is not None else 0)
                self._live_step_record_target = (name, sid)
                self._live_step_record_cursor = start % length
                self._live_step_record_last_step = None
                self._live_step_record_events = 0
                self.lbl_live_step_record.setText(f"ARMED · {name[:14]} · SEQ {sid}")
            except Exception:
                self._live_step_record_enabled = False
                self.btn_live_step_record.blockSignals(True); self.btn_live_step_record.setChecked(False); self.btn_live_step_record.blockSignals(False)
                return
            self.btn_live_step_record.setText("⏺ STEP REC ON")
            self.lbl_live_step_record.setStyleSheet("color:#ff8ba8;font-size:8pt;font-weight:900;")
        else:
            self._live_step_record_target = None
            self.btn_live_step_record.setText("⏺ STEP REC OFF")
            self.lbl_live_step_record.setText("RECORD OFF")
            self.lbl_live_step_record.setStyleSheet("color:#9aa6b4;font-size:8pt;font-weight:900;")



