# STARTUP_DIAGNOSTIC — protects against the exact QSizePolicy crash reported
# by the user. Keep this import at module scope; do not move it into the UI.
# Revert: remove only this 3-line diagnostic block if a host app supplies its
# own PyQt6 import audit.
# ============================================================================
_REQUIRED_QT_SYMBOLS = (QSizePolicy, QCheckBox, QFileDialog, QProgressBar)
assert all(sym is not None for sym in _REQUIRED_QT_SYMBOLS), "Required PyQt6 UI symbols are unavailable."

# ============================================================================
# COMPONENT_CLASS_REGISTRY — restores the usable-class registry that
# test_component_usage.py / tests.py check against. Built once at import
# time (not per-frame or per-timer), so it carries no idle-lag cost. Covers
# this module plus the other modules test_component_usage.py expects, and
# any class already defined here.
# ============================================================================
def _build_component_class_registry():
    import inspect as _inspect
    import importlib as _importlib

    registry = {}
    modules = [sys.modules[__name__]]
    for _mod_name in ("composition_state", "dj_effects", "fractal_spatial_engine",
                       "videogame_engine", "fast_widgets"):
        try:
            modules.append(_importlib.import_module(_mod_name))
        except Exception:
            pass
    for _mod in modules:
        for _name, _obj in vars(_mod).items():
            if not _name.startswith("_") and _inspect.isclass(_obj):
                registry.setdefault(_name, _obj)
    return registry


COMPONENT_CLASS_REGISTRY = _build_component_class_registry()

# GROOVEBOX_R28_4_4_EXPLICIT_AUTOSAVE_RECOVERY_MENU_20261017
# GROOVEBOX_R28_4_3_STARTUP_SELECTOR_SHARED_LAUNCH_PATH_20261017
# The appliance, desktop launcher, and direct `python groovebox.py` path must
# all use the same startup UI. In particular, run_groovebox.py is the appliance
# entry point; keeping the dialog only in this module's __main__ block silently
# bypasses it in the ISO.
def _gb_log_error(label, exc=None):
    """Append a full traceback to <data root>/logs/errors.log and return that path.

    GROOVEBOX_R23R_ERROR_LOG_20261101: startup/randomizer failures used to show only
    str(exc) (e.g. "Error -3 while decompressing data"), which hides the source.
    """
    import traceback as _tb
    try:
        import groovebox_paths as _gp
        root = Path(_gp.base_dir())
    except Exception:
        root = Path.home() / ".groovebox"
    try:
        logs = root / "logs"; logs.mkdir(parents=True, exist_ok=True)
        path = logs / "errors.log"
        with open(path, "a", encoding="utf-8") as f:
            f.write(f"\n===== {time.strftime('%Y-%m-%d %H:%M:%S')} · {label} =====\n")
            f.write(_tb.format_exc() if exc is not None else "".join(_tb.format_stack()))
        return str(path)
    except Exception:
        return ""


def _fit_main_window(player, screen):
    """DISPLAY_SCALE_20261102: main window = the usable screen area scaled by the saved Window size % (centred)."""
    try:
        g = screen.availableGeometry()
        try:
            import compat_settings as _cs_win
            pct = int(_cs_win.load().get("window_scale", 100))
        except Exception:
            pct = 100
        if pct >= 100:
            player.setGeometry(g)
        else:
            x, y, w, h = _cs_win.scaled_rect(g.x(), g.y(), g.width(), g.height(), pct)
            player.setGeometry(x, y, w, h)
    except Exception:
        pass


def _build_entertainer_dj_script(files):
    """Generate a random parametric DJ script for the given file list."""
    import random as _r
    script = {"title": "Groovebox Entertainer Mix", "tracks": []}
    for i, f in enumerate(files):
        entry = {
            "file": f,
            "bpm_hint": _r.choice([80, 90, 100, 110, 120, 128, 140, 160]),
            "crossfade_s": round(_r.uniform(1.0, 6.0), 1),
            "fx": _r.choice(["none", "reverb", "echo", "filter_sweep", "bitcrush"]),
            "convolve_seed": _r.randint(0, 999999),
            "gain_db": round(_r.uniform(-3.0, 3.0), 1),
        }
        script["tracks"].append(entry)
    return script


def _apply_entertainer_playlist(pwin, files, script):
    """Load a shuffled playlist into the performance window and start playback."""
    try:
        playlist = getattr(pwin, "playlist_widget", None) or getattr(pwin, "_playlist", None)
        if playlist is not None:
            try:
                playlist.clear()
                for f in files:
                    playlist.add_file(f)
            except Exception:
                for f in files:
                    try:
                        playlist.addItem(f)
                    except Exception:
                        pass
        # start playback
        play_fn = getattr(pwin, "play", None) or getattr(pwin, "_play", None)
        if callable(play_fn):
            play_fn()
    except Exception as exc:
        print(f"[Entertainer] apply playlist: {exc}")


def _gb_startup_sweep(player, app):
    """First-launch audible trigger: all instruments in default state,
    quick 3-note arpeggio at 1x, 1.1975807343x, 2.19758x.

    Runs once before the launcher. Debug mode skips it.
    """
    if os.environ.get("GROOVEBOX_DEBUG_LAUNCH", "0") in ("1", "true", "yes"):
        return
    if getattr(player, "_startup_sweep_done", False):
        return
    player._startup_sweep_done = True
    try:
        import numpy as _np
        from audio_os_backend import play_buffer as _play_buf
        sr = 48000
        ratios = (1.0, 1.1975807343, 2.19758)
        names = list(getattr(player, "instrument_names_48", []) or [])
        if not names:
            names = [f"Instrument {i+1}" for i in range(8)]
        base = 220.0
        try:
            base = float(player.spin_base_frequency.value()) if hasattr(player, "spin_base_frequency") else 220.0
        except Exception:
            base = 220.0
        if not (base > 0):
            base = 220.0
        notes = []
        for ratio in ratios:
            hz = base * ratio
            dur = 0.12
            t = _np.linspace(0, dur, int(sr * dur), endpoint=False)
            # Sum a short voice for each instrument at this ratio (default state).
            acc = _np.zeros_like(t)
            for i, name in enumerate(names[:16]):  # cap so startup stays quick
                try:
                    if hasattr(player, "_audition_voice"):
                        v = player._audition_voice(name, hz, t, sr)
                        acc += _np.asarray(v, dtype=_np.float32)[:len(t)]
                    else:
                        acc += _np.sin(2 * _np.pi * hz * t * (1.0 + 0.01 * i)).astype(_np.float32) * 0.1
                except Exception:
                    acc += _np.sin(2 * _np.pi * hz * t).astype(_np.float32) * 0.08
            # Soft envelope
            env = _np.minimum(1.0, t / 0.01) * _np.minimum(1.0, (dur - t) / 0.02)
            notes.append((acc * env * 0.15).astype(_np.float32))
        sweep = _np.concatenate(notes)
        try:
            _play_buf(sweep, sr, blocking=False)
        except Exception:
            pass
    except Exception as exc:
        print(f"[Startup sweep] {exc}")


def launch_startup_mode_selector(player, app, *, project_path=None, skip=False, force_chooser=False):
    # R41.2_STARTUP_ORDER_20261106: do NOT show the main window until the
    # launcher dialog has finished and applied any changes. The previous
    # early showNormal/show/lower caused the main workspace to appear
    # before the chooser concluded.
    try:
        player.hide()
    except Exception:
        pass
    """Show the first-run workspace chooser before revealing the main window.

    Safe defaults: dismissing the dialog opens the main workspace; project-file
    launches and the explicit skip flag bypass it; destructive/reset actions run
    only after their matching button is clicked. The dialog is an unparented,
    application-modal top-level window so it cannot be obscured by a hidden or
    maximized main window on Linux window managers.
    """
    def _run_startup_action_safely(label, callback):
        """Keep a deferred startup action failure from aborting the GUI event loop."""
        try:
            callback()
        except Exception as exc:
            import traceback as _startup_traceback
            print(f"[Startup launcher] {label} failed: {exc}")
            _startup_traceback.print_exc()
            log = _gb_log_error(f"startup · {label}", exc)
            # GROOVEBOX_R23R_ERROR_LOG_20261101: one quiet retry once background
            # startup work (hardware probe, autosave, caches) has settled.
            if not getattr(callback, "_gb_retried", False):
                def _retry():
                    try:
                        callback()
                        print(f"[Startup launcher] {label} succeeded on retry")
                        return
                    except Exception as exc2:
                        log2 = _gb_log_error(f"startup · {label} (retry)", exc2)
                        try:
                            QMessageBox.warning(player, f"{label} failed",
                                                f"{exc2}\n\nFull details were written to:\n{log2 or log}")
                        except Exception:
                            pass
                try:
                    callback._gb_retried = True
                except Exception:
                    pass
                QTimer.singleShot(1500, _retry)
                return
            try:
                QMessageBox.warning(player, f"{label} failed",
                                    f"{exc}\n\nFull details were written to:\n{log}" if log else str(exc))
            except Exception:
                pass

    try:
        _main_screen = app.primaryScreen()
        if _main_screen is not None:
            _fit_main_window(player, _main_screen)
    except Exception:
        pass
    if project_path:
        player.show()
        QTimer.singleShot(0, lambda p=str(project_path): _run_startup_action_safely(
            "Open Project", lambda: player.open_project_path(p)))
        QTimer.singleShot(0, lambda: _run_startup_action_safely(
            "Autosave startup", player._install_project_autosave))
        return "project"
    from pathlib import Path as _StartupPath
    last_path = _StartupPath.home() / ".config" / "groovebox" / "startup_last.json"
    last = {}
    try:
        if last_path.is_file():
            last = json.loads(last_path.read_text(encoding="utf-8"))
    except Exception:
        last = {}
    choice = {"value": "main"}
    # The startup screen is never skipped from the UI. --skip-startup-launcher is honoured only for
    # automated runs that also set GROOVEBOX_ALLOW_STARTUP_SKIP=1.
    if skip and os.environ.get("GROOVEBOX_ALLOW_STARTUP_SKIP") == "1":
        player.show()
        QTimer.singleShot(0, lambda: _run_startup_action_safely(
            "Autosave startup", player._install_project_autosave))
        return "main"

    global _GROOVEBOX_STARTUP_ACTIVE
    _GROOVEBOX_STARTUP_ACTIVE = True

    dlg = QDialog(None, Qt.WindowType.Dialog | Qt.WindowType.WindowStaysOnTopHint)
    dlg.setWindowTitle("Mathematician's Groovebox · Startup Mode")
